async def scheduled_sla_breach_check():
    """
    Scheduled job: Check for SLA breaches every 30 minutes.
    Runs automatically via APScheduler.
    """
    try:
        escalated_count = await check_and_escalate_sla_breaches()
        if escalated_count > 0:
            logger.info(f"[SCHEDULED] SLA Breach Check: Escalated {escalated_count} tickets")
        else:
            logger.debug("[SCHEDULED] SLA Breach Check: No new breaches found")
    except Exception as e:
        logger.error(f"[SCHEDULED] SLA Breach Check failed: {str(e)}")


async def scheduled_warranty_claim_sla_check():
    """Hourly scan for warranty claims that have breached the 7-working-day SLA."""
    try:
        await check_warranty_claim_sla_breaches()
    except Exception as e:
        logger.error(f"[SCHEDULED] Warranty Claim SLA check failed: {e}")


async def scheduled_maintenance_reminders():
    """Daily: notify customers of due/overdue product maintenance + warranty
    expiry. De-duped per cycle (reminded_for) so a parked task isn't re-sent
    every day. Reminders flow through create_notification → push."""
    try:
        reminded = 0
        now = datetime.now(timezone.utc)
        warranties = await db.warranties.find(
            {"status": {"$in": ["approved", "active", "extended"]},
             "customer_id": {"$nin": [None, ""]}},
            {"_id": 0},
        ).to_list(5000)
        for w in warranties:
            cust = w.get("customer_id")
            if not cust:
                continue
            label = w.get("product_name") or w.get("device_type") or "your product"
            for t in await _ensure_maintenance_tasks(w):
                status = _maintenance_status(t["due_date"])
                if status not in ("due_soon", "overdue"):
                    continue
                if t.get("reminded_for") == t["due_date"]:
                    continue
                verb = "is overdue" if status == "overdue" else "is due soon"
                await create_notification(
                    title=f"Maintenance due: {t['title']}",
                    message=f"{t['title']} for {label} {verb}. Tap to book it.",
                    notification_type="maintenance",
                    link=f"/products/{w['id']}",
                    target_user_ids=[cust],
                    priority="normal",
                    data={"warranty_id": w["id"], "task_key": t["task_key"]},
                )
                await db.maintenance_tasks.update_one(
                    {"warranty_id": w["id"], "task_key": t["task_key"]},
                    {"$set": {"reminded_for": t["due_date"]}},
                )
                reminded += 1
            end = _parse_dt(w.get("warranty_end_date"))
            if end:
                days = (end - now).days
                if 0 <= days <= 30 and w.get("expiry_reminded_for") != w.get("warranty_end_date"):
                    await create_notification(
                        title="Warranty expiring soon",
                        message=f"The warranty for {label} expires in {days} day(s).",
                        notification_type="warranty",
                        link=f"/products/{w['id']}",
                        target_user_ids=[cust],
                        priority="normal",
                        data={"warranty_id": w["id"]},
                    )
                    await db.warranties.update_one(
                        {"id": w["id"]},
                        {"$set": {"expiry_reminded_for": w.get("warranty_end_date")}},
                    )
                    reminded += 1
        logger.info(f"[SCHEDULED] Maintenance reminders: sent {reminded}")
    except Exception as e:
        logger.error(f"[SCHEDULED] Maintenance reminders failed: {e}")


async def scheduled_amazon_tracking_push():
    """Push tracking back to Amazon via SP-API for any locally-dispatched
    orders that haven't been confirmed to Amazon yet.

    Without this job, the manual /api/amazon/push-tracking endpoint is the
    only way orders get marked shipped on Amazon — so an order dispatched
    today shows as 'pending' to the buyer until the accountant remembers to
    click the button. Result: buyers escalate, A-Z claims, negative reviews.

    Runs hourly. Per-firm budget of 50 orders/run keeps SP-API rate-limit
    headroom intact. Individual order failures are logged but don't abort
    the run.
    """
    try:
        pushed = failed = skipped = 0
        async for creds in db.marketplace_credentials.find(
            {"platform": "amazon", "is_active": True}, {"_id": 0, "firm_id": 1}
        ):
            firm_id = creds.get("firm_id")
            if not firm_id:
                continue
            cur = db.amazon_orders.find(
                {
                    "firm_id": firm_id,
                    "tracking_number": {"$exists": True, "$nin": [None, ""]},
                    "crm_status": {"$in": ["dispatched", "delivered"]},
                    "$or": [
                        {"amazon_tracking_pushed": {"$ne": True}},
                        {"amazon_tracking_pushed": {"$exists": False}},
                    ],
                },
                {"_id": 0, "amazon_order_id": 1},
            ).limit(50)
            async for order in cur:
                aid = order.get("amazon_order_id")
                if not aid:
                    skipped += 1
                    continue
                result = await _push_tracking_to_amazon_internal(aid, firm_id)
                if result.get("success"):
                    pushed += 1
                else:
                    failed += 1
                    logger.warning(
                        f"[amazon-track-push] firm={firm_id[:8]} {aid}: "
                        f"{result.get('error', 'unknown error')[:200]}"
                    )
        logger.info(
            f"[amazon-track-push] scheduled run done: pushed={pushed} failed={failed} skipped={skipped}"
        )
    except Exception as e:
        logger.error(f"[SCHEDULED] Amazon tracking push failed: {e}", exc_info=True)


# ---------------------------------------------------------------------------
# Daily Amazon-finance reconciliation agent
# ---------------------------------------------------------------------------
# ===================================================================
# Finance Agent — audit-grade reconciliation helpers
# ===================================================================
# Each helper returns either an action count (it changed the books) or a
# list/dict of FINDINGS (read-only checks the accountant must triage).
# Findings carry a `severity` so the agent can decide notification priority:
#   high — broken GL or material drift; admin must look TODAY
#   warn — visible gap (unmatched rows, aged clearing) — review this week
#   info — informational snapshot (aging buckets, baseline)
# Helpers must be idempotent and side-effect-free unless explicitly named
# `_book_*` or `_post_*`.

_AGENT_STUCK_REIMB_DAYS = 30          # refund out but no return after N days
_AGENT_SETTLEMENT_DRIFT_RUPEES = 100  # three-way match drift threshold
_AGENT_CLEARING_DRIFT_RUPEES = 50000  # marketplace-clearing balance threshold
_AGENT_CLEARING_DRIFT_DAYS = 14       # ...if older than N days
_AGENT_TRIAL_BALANCE_TOLERANCE = 1.0  # debits-vs-credits tolerance
_AGENT_GST_DRIFT_RUPEES = 100         # invoice-vs-register GST tolerance
_AGENT_AGING_90PLUS_RUPEES = 100000   # 90+ receivables write-off flag
_AGENT_ANOMALY_MULTIPLIER = 3.0       # today's metric > N x 30-day mean


async def _book_a_to_z_outcomes(firm_id: str, system_user: dict) -> dict:
    """Walk A-Z claim refunds and ensure granted ones are booked, pending
    ones are counted. `record_amazon_refund` already runs at ingestion, so
    this is a catch-up pass for records that came in without a credit note
    (e.g. uploaded via CSV, or where ingestion errored)."""
    out = {"granted_booked": 0, "pending": 0, "denied": 0, "errors": []}
    cur = db.amazon_refunds.find(
        {"firm_id": firm_id, "refund_type": "a_to_z_claim"},
        {"_id": 0, "id": 1, "amazon_order_id": 1, "refund_amount": 1,
         "refund_date": 1, "a_to_z_outcome": 1, "credit_note_id": 1},
    )
    async for r in cur:
        outcome = (r.get("a_to_z_outcome") or "pending").lower()
        if outcome == "pending":
            out["pending"] += 1
            continue
        if outcome == "denied":
            out["denied"] += 1
            continue
        if outcome != "granted":
            continue
        # Granted but no credit note yet → book it
        if r.get("credit_note_id"):
            continue
        try:
            await record_amazon_refund(
                {
                    "amazon_order_id": r.get("amazon_order_id"),
                    "firm_id": firm_id,
                    "refund_event_id": f"a-z-catchup-{r['id']}",
                    "refund_amount": abs(float(r.get("refund_amount") or 0)),
                    "refund_date": r.get("refund_date"),
                    "refund_type": "a_to_z_claim",
                    "refund_reason": "A-Z claim granted (agent catch-up)",
                    "source": "finance_agent",
                    "source_doc_id": r["id"],
                },
                user=system_user, auto_credit_note=True, reverse_cogs=False,
            )
            out["granted_booked"] += 1
        except Exception as e:
            out["errors"].append(f"a-z {r.get('id')}: {str(e)[:80]}")
    return out


async def _find_stuck_reimbursements(firm_id: str) -> List[dict]:
    """Refunds where money went out but the product never came back after
    N days. These are FBA-reimbursement candidates — Amazon owes us either
    the inventory or its value. Returned as a list, not booked: filing the
    claim is a manual step that needs evidence."""
    cutoff = (datetime.now(timezone.utc) - timedelta(days=_AGENT_STUCK_REIMB_DAYS)).isoformat()
    rows = await db.amazon_refunds.find(
        {
            "firm_id": firm_id,
            "product_returned": {"$ne": True},
            "refund_date": {"$lt": cutoff[:10]},
            "refund_type": {"$in": ["return_refund", None]},
        },
        {"_id": 0, "id": 1, "amazon_order_id": 1, "refund_amount": 1, "refund_date": 1},
    ).sort("refund_date", 1).limit(200).to_list(200)
    out = []
    for r in rows:
        try:
            d = datetime.fromisoformat(str(r.get("refund_date") or "")[:10])
            age = (datetime.now(timezone.utc).replace(tzinfo=None) - d).days
        except Exception:
            age = None
        out.append({
            "refund_id": r["id"],
            "amazon_order_id": r.get("amazon_order_id"),
            "amount": float(r.get("refund_amount") or 0),
            "refund_date": r.get("refund_date"),
            "days_open": age,
        })
    return out


async def _three_way_settlement_match(firm_id: str) -> List[dict]:
    """For each of the last 5 payout statements: compare the sum of
    transaction `total_amount` rows to the statement's declared
    `net_payout`. Drift > _AGENT_SETTLEMENT_DRIFT_RUPEES = data quality
    problem (missing rows, double-counted lines, or a parser bug)."""
    out = []
    statements = await db.payout_statements.find(
        {"firm_id": firm_id},
        {"_id": 0, "id": 1, "summary": 1, "statement_period_end": 1, "filename": 1},
    ).sort("statement_period_end", -1).limit(5).to_list(5)
    for s in statements:
        declared = float((s.get("summary") or {}).get("net_payout") or 0)
        if declared == 0:
            continue
        pipeline = [
            {"$match": {"statement_id": s["id"]}},
            {"$group": {"_id": None, "sum": {"$sum": "$total_amount"}}},
        ]
        agg = await db.payout_transactions.aggregate(pipeline).to_list(1)
        computed = float(agg[0]["sum"]) if agg else 0.0
        drift = round(computed - declared, 2)
        if abs(drift) > _AGENT_SETTLEMENT_DRIFT_RUPEES:
            out.append({
                "statement_id": s["id"],
                "period_end": s.get("statement_period_end"),
                "filename": s.get("filename"),
                "declared_payout": round(declared, 2),
                "computed_payout": round(computed, 2),
                "drift": drift,
                "severity": "high" if abs(drift) > 10000 else "warn",
            })
    return out


async def _marketplace_clearing_balance(firm_id: str) -> dict:
    """Net balance of the Amazon Marketplace Clearing account from
    journal_entries. Fees post Dr Expense / Cr Clearing; bank deposits
    should post Dr Bank / Cr Clearing → the account should trend to zero.
    A persistent non-zero balance means deposits aren't matching fees."""
    pipeline = [
        {"$match": {"firm_id": firm_id}},
        {"$unwind": "$lines"},
        {"$match": {"lines.account": _FEE_CLEARING_ACCOUNT}},
        {"$group": {
            "_id": None,
            "debit": {"$sum": "$lines.debit"},
            "credit": {"$sum": "$lines.credit"},
            "earliest": {"$min": "$accounting_date"},
            "latest": {"$max": "$accounting_date"},
        }},
    ]
    agg = await db.journal_entries.aggregate(pipeline).to_list(1)
    if not agg:
        return {"balance": 0.0, "age_days": 0, "severity": "ok"}
    row = agg[0]
    balance = round(float(row["debit"]) - float(row["credit"]), 2)
    age_days = 0
    try:
        if row.get("earliest"):
            d = datetime.fromisoformat(str(row["earliest"])[:10])
            age_days = (datetime.now(timezone.utc).replace(tzinfo=None) - d).days
    except Exception:
        pass
    if abs(balance) > _AGENT_CLEARING_DRIFT_RUPEES and age_days > _AGENT_CLEARING_DRIFT_DAYS:
        sev = "high"
    elif abs(balance) > _AGENT_CLEARING_DRIFT_RUPEES:
        sev = "warn"
    else:
        sev = "ok"
    return {
        "balance": balance,
        "age_days": age_days,
        "earliest": row.get("earliest"),
        "latest": row.get("latest"),
        "severity": sev,
    }


async def _trial_balance_check(firm_id: str) -> dict:
    """Sum debits and credits across journal_entries for the last 30 days
    per firm. They MUST match within tolerance; otherwise the GL is broken
    and downstream reports (P&L, balance sheet) are lies."""
    since = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
    pipeline = [
        {"$match": {"firm_id": firm_id, "created_at": {"$gte": since}}},
        {"$unwind": "$lines"},
        {"$group": {
            "_id": None,
            "debit": {"$sum": "$lines.debit"},
            "credit": {"$sum": "$lines.credit"},
        }},
    ]
    agg = await db.journal_entries.aggregate(pipeline).to_list(1)
    if not agg:
        return {"debit": 0.0, "credit": 0.0, "diff": 0.0, "ok": True, "severity": "ok"}
    debit  = round(float(agg[0]["debit"]),  2)
    credit = round(float(agg[0]["credit"]), 2)
    diff   = round(debit - credit, 2)
    ok = abs(diff) <= _AGENT_TRIAL_BALANCE_TOLERANCE
    return {
        "debit": debit, "credit": credit, "diff": diff, "ok": ok,
        "severity": "ok" if ok else "high",
    }


async def _gst_output_reconciliation(firm_id: str) -> dict:
    """Current-month output GST: sum from sales_invoices vs the value
    recorded in the gst_itc_balances register. Drift means the register
    is stale or the books are."""
    period = datetime.now(timezone.utc).strftime("%Y-%m")
    cur = db.sales_invoices.find(
        {
            "firm_id": firm_id,
            "$or": [
                {"invoice_date": {"$regex": f"^{period}"}},
                {"date": {"$regex": f"^{period}"}},
            ],
        },
        {"_id": 0, "cgst": 1, "sgst": 1, "igst": 1, "total_gst": 1},
    )
    invoice_total = 0.0
    n_invoices = 0
    async for inv in cur:
        gst = (inv.get("total_gst")
               or ((inv.get("cgst") or 0) + (inv.get("sgst") or 0) + (inv.get("igst") or 0)))
        invoice_total += float(gst or 0)
        n_invoices += 1
    register = await db.gst_itc_balances.find_one(
        {"firm_id": firm_id, "period": period}, {"_id": 0, "output_gst": 1},
    )
    register_val = float((register or {}).get("output_gst") or 0)
    drift = round(invoice_total - register_val, 2)
    if register is None and invoice_total > 0:
        sev = "warn"  # register not snapshot yet — accountant should generate it
    elif abs(drift) > _AGENT_GST_DRIFT_RUPEES:
        sev = "high"
    else:
        sev = "ok"
    return {
        "period": period,
        "invoices_sum": round(invoice_total, 2),
        "register_value": round(register_val, 2),
        "drift": drift,
        "invoice_count": n_invoices,
        "register_snapshot": register is not None,
        "severity": sev,
    }


async def _scan_duplicates(firm_id: str) -> dict:
    """Last 30 days: invoice_numbers and payment references that appear
    more than once for the firm. Duplicates here mean either the same
    transaction was booked twice (overstates revenue) or two different
    transactions accidentally got the same id (audit nightmare)."""
    since = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
    dup_invoices = await db.sales_invoices.aggregate([
        {"$match": {
            "firm_id": firm_id,
            "created_at": {"$gte": since},
            "invoice_number": {"$ne": None, "$exists": True},
        }},
        {"$group": {"_id": "$invoice_number", "count": {"$sum": 1},
                    "ids": {"$push": "$id"}}},
        {"$match": {"count": {"$gt": 1}}},
        {"$limit": 50},
    ]).to_list(50)
    dup_payments = await db.payments.aggregate([
        {"$match": {
            "firm_id": firm_id,
            "created_at": {"$gte": since},
            "reference_number": {"$ne": None, "$exists": True, "$nin": ["", "N/A", "n/a"]},
        }},
        {"$group": {"_id": "$reference_number", "count": {"$sum": 1},
                    "ids": {"$push": "$id"},
                    "amount": {"$sum": "$amount"}}},
        {"$match": {"count": {"$gt": 1}}},
        {"$limit": 50},
    ]).to_list(50)
    return {
        "duplicate_invoices": [
            {"invoice_number": d["_id"], "count": d["count"], "ids": d["ids"][:5]}
            for d in dup_invoices
        ],
        "duplicate_payments": [
            {"reference": d["_id"], "count": d["count"], "ids": d["ids"][:5],
             "amount": round(float(d.get("amount") or 0), 2)}
            for d in dup_payments
        ],
        "severity": "high" if (dup_invoices or dup_payments) else "ok",
    }


async def _detect_anomalies(firm_id: str, today_stats: dict) -> List[dict]:
    """Compare today's fee + refund counts to the trailing 30-day mean.
    > _AGENT_ANOMALY_MULTIPLIER ⇒ surface for human eyes (probably a
    settlement-format change, a fraud spike, or a fee schedule update)."""
    out = []
    since = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
    pipeline = [
        {"$match": {"firm_id": firm_id, "created_at": {"$gte": since},
                    "reference_type": "payout_transaction"}},
        {"$group": {"_id": None, "sum": {"$sum": "$amount"}, "count": {"$sum": 1}}},
    ]
    agg = await db.journal_entries.aggregate(pipeline).to_list(1)
    if agg and agg[0]["count"] > 0:
        # Mean per day over 30-day window
        daily_mean_fees = float(agg[0]["sum"]) / 30.0
        today_fees = float(today_stats.get("fees_total_amount") or 0)
        if daily_mean_fees > 0 and today_fees > daily_mean_fees * _AGENT_ANOMALY_MULTIPLIER:
            out.append({
                "metric": "fees_total_amount",
                "today": round(today_fees, 2),
                "baseline": round(daily_mean_fees, 2),
                "multiple": round(today_fees / daily_mean_fees, 1),
                "severity": "warn",
            })
    # Refunds anomaly — count of refund rows in window vs today
    refund_count_30d = await db.amazon_refunds.count_documents({
        "firm_id": firm_id, "created_at": {"$gte": since},
    })
    if refund_count_30d > 0:
        daily_mean_refunds = refund_count_30d / 30.0
        today_refunds = int(today_stats.get("refunds_posted") or 0)
        if daily_mean_refunds > 0 and today_refunds > daily_mean_refunds * _AGENT_ANOMALY_MULTIPLIER:
            out.append({
                "metric": "refunds_posted",
                "today": today_refunds,
                "baseline": round(daily_mean_refunds, 1),
                "multiple": round(today_refunds / daily_mean_refunds, 1),
                "severity": "warn",
            })
    return out


async def _receivables_aging_snapshot(firm_id: str) -> dict:
    """Bucketed unpaid invoices. The 90+ bucket is the write-off candidate
    pile — if it crosses _AGENT_AGING_90PLUS_RUPEES we surface it so an
    accountant can chase or provision."""
    invoices = await db.sales_invoices.find(
        {"firm_id": firm_id, "payment_status": {"$in": ["unpaid", "partial", "pending"]}},
        {"_id": 0, "invoice_date": 1, "date": 1, "balance_due": 1, "grand_total": 1,
         "party_name": 1, "invoice_number": 1, "created_at": 1},
    ).to_list(5000)
    buckets = {"0-30": 0.0, "31-60": 0.0, "61-90": 0.0, "90+": 0.0}
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    over_90 = []
    for inv in invoices:
        balance = float(inv.get("balance_due") or inv.get("grand_total") or 0)
        if balance <= 0:
            continue
        date_str = (inv.get("invoice_date") or inv.get("date") or inv.get("created_at") or "")[:10]
        try:
            d = datetime.strptime(date_str, "%Y-%m-%d")
        except Exception:
            continue
        age = (now - d).days
        if age <= 30:
            buckets["0-30"] += balance
        elif age <= 60:
            buckets["31-60"] += balance
        elif age <= 90:
            buckets["61-90"] += balance
        else:
            buckets["90+"] += balance
            if len(over_90) < 20:
                over_90.append({
                    "invoice_number": inv.get("invoice_number"),
                    "party_name": inv.get("party_name"),
                    "amount": round(balance, 2),
                    "age_days": age,
                })
    total = round(sum(buckets.values()), 2)
    rounded = {k: round(v, 2) for k, v in buckets.items()}
    sev = "warn" if rounded["90+"] > _AGENT_AGING_90PLUS_RUPEES else "info"
    return {
        "total_outstanding": total,
        "buckets": rounded,
        "over_90_items": over_90,
        "over_90_count": len([i for i in invoices if 0 < (now - datetime.strptime(
            (i.get("invoice_date") or i.get("date") or i.get("created_at") or "1970-01-01")[:10],
            "%Y-%m-%d"
        )).days > 90]) if invoices else 0,
        "severity": sev,
    }


_REIMB_RECEIVABLE_ACCOUNT = "Amazon Reimbursements Receivable"
_REIMB_INCOME_ACCOUNT = "FBA Reimbursement Income"


async def _scrape_and_book_reimbursements(firm_id: str, firm_name: str, system_user: dict) -> dict:
    """Pull the FBA Reimbursements report from Seller Central via the browser
    agent, persist new rows to `amazon_fba_reimbursements`, and book each new
    row as a journal entry (Dr Receivable / Cr Reimbursement Income).

    Amazon owes us money for every reimbursement on this page — booking it
    creates the receivable, and the next bank deposit clears it.

    Operates on whichever firm is currently logged into Seller Central in
    the browser agent (single account constraint until we add per-firm).
    Idempotent: existing reimbursement_ids are skipped.

    Returns:
      {
        "status": "ok" | "session_expired" | "page_changed" | "skipped" | "error",
        "scraped": int,        # rows scraped from the page
        "new_rows": int,       # rows we hadn't seen before
        "booked": int,         # journal entries written
        "total_amount": float, # sum of new reimbursement amounts (INR)
        "raw_text_sample": str (only if status != ok, for debugging),
        "error": str | None,
      }
    """
    try:
        agent = await get_browser_agent()
    except Exception as e:
        return {"status": "error", "scraped": 0, "new_rows": 0, "booked": 0,
                "total_amount": 0.0, "error": f"browser agent init failed: {e}"}

    # If the browser isn't running, don't auto-start it from inside the
    # scheduled job — that would pop a headless Chromium without a human
    # ready to log in. Just degrade gracefully.
    if not agent.page:
        return {"status": "session_expired", "scraped": 0, "new_rows": 0, "booked": 0,
                "total_amount": 0.0,
                "error": "Browser agent not started — log in at /admin/browser-agent"}

    try:
        result = await agent.scrape_fba_reimbursements()
    except Exception as e:
        logger.error(f"[finance-agent] reimbursement scrape crashed: {e}", exc_info=True)
        return {"status": "error", "scraped": 0, "new_rows": 0, "booked": 0,
                "total_amount": 0.0, "error": str(e)[:200]}

    if result.get("status") != "ok":
        return {
            "status": result.get("status") or "error",
            "scraped": 0, "new_rows": 0, "booked": 0, "total_amount": 0.0,
            "raw_text_sample": (result.get("raw_text_sample") or "")[:600],
            "error": result.get("error") or "scrape returned no rows",
        }

    rows = result.get("rows") or []
    scraped = len(rows)
    new_count = 0
    booked = 0
    total_amount = 0.0
    now = datetime.now(timezone.utc).isoformat()

    for row in rows:
        rid = row.get("reimbursement_id")
        if not rid:
            continue
        # Upsert: skip if we already have this reimbursement_id for this firm
        existing = await db.amazon_fba_reimbursements.find_one(
            {"firm_id": firm_id, "reimbursement_id": rid}, {"_id": 0, "id": 1}
        )
        if existing:
            continue
        doc = {
            "id": str(uuid.uuid4()),
            "firm_id": firm_id,
            "reimbursement_id": rid,
            "approval_date": row.get("approval_date"),
            "case_id": row.get("case_id"),
            "amazon_order_id": row.get("amazon_order_id"),
            "reason": row.get("reason"),
            "sku": row.get("sku"),
            "fnsku": row.get("fnsku"),
            "asin": row.get("asin"),
            "quantity": int(row.get("quantity") or 0),
            "amount": float(row.get("amount") or 0),
            "currency": row.get("currency") or "INR",
            "source": "browser_agent",
            "scraped_at": now,
            "scraped_by": system_user.get("email"),
            "journal_entry_id": None,
        }
        amount = doc["amount"]
        if amount <= 0:
            # Don't book zero/negative reimbursements — flag the row but skip
            # creating an entry to keep the GL clean.
            await db.amazon_fba_reimbursements.insert_one(doc)
            new_count += 1
            continue
        # Book Dr Reimbursements Receivable / Cr Reimbursement Income
        je_id = str(uuid.uuid4())
        je = {
            "id": je_id,
            "firm_id": firm_id,
            "firm_name": firm_name,
            "reference_type": "fba_reimbursement",
            "reference_id": doc["id"],
            "reference_number": rid,
            "marketplace": "amazon",
            "marketplace_order_id": doc.get("amazon_order_id"),
            "amount": round(amount, 2),
            "lines": [
                {"account": _REIMB_RECEIVABLE_ACCOUNT, "debit": round(amount, 2), "credit": 0},
                {"account": _REIMB_INCOME_ACCOUNT,     "debit": 0, "credit": round(amount, 2)},
            ],
            "narration": (
                f"FBA reimbursement {rid} — {doc.get('reason') or 'no reason given'}"
                + (f" on order {doc['amazon_order_id']}" if doc.get("amazon_order_id") else "")
            ),
            "created_by": system_user["id"],
            "created_by_name": f"{system_user.get('first_name','')} {system_user.get('last_name','')}".strip() or system_user.get("email"),
            "created_at": now,
            "accounting_date": doc.get("approval_date") or now[:10],
            "accounting_date_source": "reimbursement_approval_date",
        }
        try:
            await db.journal_entries.insert_one(je)
            doc["journal_entry_id"] = je_id
            booked += 1
            total_amount += amount
        except Exception as e:
            logger.warning(f"[finance-agent] failed to book reimbursement {rid}: {e}")
        await db.amazon_fba_reimbursements.insert_one(doc)
        new_count += 1

    return {
        "status": "ok",
        "scraped": scraped,
        "new_rows": new_count,
        "booked": booked,
        "total_amount": round(total_amount, 2),
        "error": None,
    }


def _agent_priority(per_firm_stats: List[dict]) -> str:
    """Roll a notification priority off the worst severity seen across firms."""
    for s in per_firm_stats:
        for finding in (
            s.get("trial_balance") or {}, s.get("clearing") or {}, s.get("gst") or {},
            s.get("duplicates") or {}):
            if finding.get("severity") == "high":
                return "high"
        if s.get("settlement_drift") and any(
            x.get("severity") == "high" for x in s["settlement_drift"]):
            return "high"
        if s.get("errors"):
            return "high"
    for s in per_firm_stats:
        if (s.get("unmatched_transactions") or 0) > 0:
            return "high"
        if s.get("stuck_reimbursements") or s.get("anomalies"):
            return "high"
        for finding in (
            s.get("trial_balance") or {}, s.get("clearing") or {}, s.get("gst") or {},
            s.get("aging") or {}):
            if finding.get("severity") == "warn":
                return "high"
    return "normal"


async def _run_finance_agent_for_firm(firm: dict, system_user: dict) -> dict:
    """One firm's slice of the daily finance agent — KPMG-grade pass.

    Actions taken (idempotent):
      - book unposted settlement fees as journal entries
      - book refund-type settlement rows as credit notes
      - catch up any granted A-Z claims that didn't get a credit note at ingest

    Read-only checks (surfaced as findings, never auto-resolved):
      - unmatched payout-transaction count
      - stuck reimbursements (refund out, product never came back)
      - three-way settlement match per recent payout
      - marketplace-clearing account balance + age
      - 30-day trial balance: debits == credits
      - current-month GST output: invoices vs register
      - duplicate invoice numbers + payment references (30-day window)
      - anomaly detection vs 30-day baseline
      - receivables aging snapshot

    Refusing to auto-fix findings is intentional: in a financial workflow
    a false positive is worse than a visible gap. Surface, don't silently
    correct.
    """
    firm_id = firm.get("id")
    firm_name = firm.get("name")
    stats = {
        "firm_id": firm_id,
        "firm_name": firm_name,
        # Actions
        "fees_posted_rows": 0,
        "fees_journal_entries": 0,
        "fees_total_amount": 0.0,
        "refunds_posted": 0,
        "refunds_skipped": 0,
        "a_to_z": {"granted_booked": 0, "pending": 0, "denied": 0},
        # Findings
        "unmatched_transactions": 0,
        "stuck_reimbursements": [],
        "settlement_drift": [],
        "clearing": {},
        "trial_balance": {},
        "gst": {},
        "duplicates": {},
        "anomalies": [],
        "aging": {},
        "errors": [],
    }

    # ----- ACTIONS: settlement fees -----
    statement_ids = [
        s["id"] async for s in db.payout_statements.find(
            {"firm_id": firm_id}, {"_id": 0, "id": 1}
        )
    ]
    if statement_ids:
        cur = db.payout_transactions.find(
            {
                "statement_id": {"$in": statement_ids},
                "$or": [
                    {"fees_posted": {"$ne": True}},
                    {"fees_posted": {"$exists": False}},
                ],
            },
            {"_id": 0},
        )
        async for t in cur:
            try:
                entries = await _post_fees_for_transaction(t, firm_id, firm_name, system_user)
            except Exception as e:
                stats["errors"].append(f"fees:{t.get('id')}: {str(e)[:120]}")
                continue
            if entries:
                stats["fees_posted_rows"] += 1
                stats["fees_journal_entries"] += len(entries)
                stats["fees_total_amount"] += sum(je["amount"] for je in entries)

    # ----- ACTIONS: refund-type transactions → credit notes -----
    if statement_ids:
        refund_cur = db.payout_transactions.find(
            {
                "statement_id": {"$in": statement_ids},
                "$or": [
                    {"transaction_type": "Refund"},
                    {"transaction_category": "refund"},
                ],
            },
            {"_id": 0},
        )
        async for t in refund_cur:
            aid = t.get("marketplace_order_id") or t.get("amazon_order_id")
            if not aid:
                stats["refunds_skipped"] += 1
                continue
            try:
                r = await record_amazon_refund(
                    {
                        "amazon_order_id": aid,
                        "firm_id": firm_id,
                        "refund_event_id": f"payout-{t.get('id')}",
                        "refund_amount": abs(float(t.get("total_amount") or 0)),
                        "refund_date": t.get("date"),
                        "refund_type": "return_refund",
                        "refund_reason": t.get("product_details") or "From Amazon settlement",
                        "source": "amazon_settlement",
                        "source_doc_id": t.get("id"),
                        "linked_payout_transaction_id": t.get("id"),
                    },
                    user=system_user,
                    auto_credit_note=True,
                    reverse_cogs=False,
                )
                if r.get("already_existed"):
                    stats["refunds_skipped"] += 1
                else:
                    stats["refunds_posted"] += 1
            except Exception as e:
                stats["refunds_skipped"] += 1
                stats["errors"].append(f"refund:{aid}: {str(e)[:120]}")

    # ----- ACTIONS: A-Z claim catch-up -----
    try:
        a_to_z = await _book_a_to_z_outcomes(firm_id, system_user)
        stats["a_to_z"] = {
            "granted_booked": a_to_z["granted_booked"],
            "pending": a_to_z["pending"],
            "denied": a_to_z["denied"],
        }
        stats["errors"].extend(a_to_z["errors"])
    except Exception as e:
        stats["errors"].append(f"a-z: {str(e)[:120]}")

    # ----- FINDINGS -----
    if statement_ids:
        stats["unmatched_transactions"] = await db.payout_transactions.count_documents(
            {"statement_id": {"$in": statement_ids}, "crm_match_status": "unmatched"}
        )
    for label, coro in (
        ("stuck_reimbursements", _find_stuck_reimbursements(firm_id)),
        ("settlement_drift",     _three_way_settlement_match(firm_id)),
        ("clearing",             _marketplace_clearing_balance(firm_id)),
        ("trial_balance",        _trial_balance_check(firm_id)),
        ("gst",                  _gst_output_reconciliation(firm_id)),
        ("duplicates",           _scan_duplicates(firm_id)),
        ("aging",                _receivables_aging_snapshot(firm_id)),
    ):
        try:
            stats[label] = await coro
        except Exception as e:
            stats["errors"].append(f"{label}: {str(e)[:120]}")
    # Anomalies are computed last because they read today's posted-totals
    try:
        stats["anomalies"] = await _detect_anomalies(firm_id, stats)
    except Exception as e:
        stats["errors"].append(f"anomalies: {str(e)[:120]}")

    stats["fees_total_amount"] = round(stats["fees_total_amount"], 2)
    return stats


def _agent_aggregate_totals(per_firm: List[dict], reimb_scrape: Optional[dict] = None) -> dict:
    """Compute org-wide totals + finding counts from per-firm stats. Used by
    both the scheduled and manual runs so the UI sees a consistent shape."""
    reimb = reimb_scrape or {}
    return {
        # Actions
        "fees_posted_rows":     sum(s.get("fees_posted_rows", 0)     for s in per_firm),
        "fees_journal_entries": sum(s.get("fees_journal_entries", 0) for s in per_firm),
        "fees_total_amount":    round(sum(s.get("fees_total_amount", 0) for s in per_firm), 2),
        "refunds_posted":       sum(s.get("refunds_posted", 0)       for s in per_firm),
        "refunds_skipped":      sum(s.get("refunds_skipped", 0)      for s in per_firm),
        "a_to_z_booked":  sum((s.get("a_to_z") or {}).get("granted_booked", 0) for s in per_firm),
        "a_to_z_pending": sum((s.get("a_to_z") or {}).get("pending", 0)        for s in per_firm),
        # Run-level: FBA reimbursements scraped via browser agent
        "reimbursements_scraped":      reimb.get("scraped", 0),
        "reimbursements_new":          reimb.get("new_rows", 0),
        "reimbursements_booked":       reimb.get("booked", 0),
        "reimbursements_total_amount": reimb.get("total_amount", 0.0),
        "reimbursement_status":        reimb.get("status", "skipped"),
        # Findings — counts only, full payload is per_firm[*]
        "unmatched_transactions": sum(s.get("unmatched_transactions", 0) for s in per_firm),
        "stuck_reimbursements":   sum(len(s.get("stuck_reimbursements") or []) for s in per_firm),
        "settlement_drifts":      sum(len(s.get("settlement_drift") or [])     for s in per_firm),
        "trial_balance_failures": sum(
            1 for s in per_firm if (s.get("trial_balance") or {}).get("severity") == "high"),
        "clearing_drifts": sum(
            1 for s in per_firm if (s.get("clearing") or {}).get("severity") in ("high", "warn")),
        "gst_drifts": sum(
            1 for s in per_firm if (s.get("gst") or {}).get("severity") in ("high", "warn")),
        "duplicates_found": sum(
            (len((s.get("duplicates") or {}).get("duplicate_invoices") or [])
             + len((s.get("duplicates") or {}).get("duplicate_payments") or []))
            for s in per_firm),
        "anomalies": sum(len(s.get("anomalies") or []) for s in per_firm),
        "aging_90plus_total": round(
            sum((s.get("aging") or {}).get("buckets", {}).get("90+", 0) for s in per_firm), 2),
        "errors": sum(len(s.get("errors") or []) for s in per_firm),
    }


async def _pick_browser_agent_firm() -> Optional[dict]:
    """Decide which firm the browser-agent scrape attributes its results to.
    Single-account browser today — pick env var override or first Amazon firm."""
    override = os.environ.get("BROWSER_AGENT_FIRM_ID")
    if override:
        f = await db.firms.find_one({"id": override}, {"_id": 0, "id": 1, "name": 1})
        if f:
            return f
    creds = await db.marketplace_credentials.find_one(
        {"platform": "amazon", "is_active": True}, {"_id": 0, "firm_id": 1}
    )
    if not creds:
        return None
    return await db.firms.find_one({"id": creds["firm_id"]}, {"_id": 0, "id": 1, "name": 1})


async def scheduled_amazon_finance_agent():
    """Daily KPMG-grade Amazon finance reconciliation. Runs 02:30 UTC
    (08:00 IST), right after the nightly Amazon sync at 20:30 UTC.

    Per firm with active Amazon credentials, runs the full
    `_run_finance_agent_for_firm()` pass — books fees + refunds + A-Z
    claim catch-ups, then walks 7 read-only integrity checks and surfaces
    findings without auto-resolving them. Persists the whole run to
    `scheduled_job_runs` (audit trail) and posts a notification summarizing
    actions taken + findings count to accountants + admins.
    """
    started = datetime.now(timezone.utc)
    run = {
        "id": str(uuid.uuid4()),
        "job": "amazon_finance_agent",
        "trigger": "scheduled",
        "started_at": started.isoformat(),
        "status": "running",
        "per_firm": {},
    }
    await db.scheduled_job_runs.insert_one(dict(run))

    try:
        # System-user payload for record_amazon_refund / journal-entry
        # `created_by_name` fields. NOT a real user row — just metadata.
        system_user = {
            "id": "system-finance-agent",
            "first_name": "Finance",
            "last_name": "Agent",
            "email": "system@musclegrid.in",
        }

        all_firm_stats: List[Dict] = []
        async for creds in db.marketplace_credentials.find(
            {"platform": "amazon", "is_active": True},
            {"_id": 0, "firm_id": 1},
        ):
            firm_id = creds.get("firm_id")
            if not firm_id:
                continue
            firm = await db.firms.find_one({"id": firm_id}, {"_id": 0, "id": 1, "name": 1})
            if not firm:
                continue
            try:
                stats = await _run_finance_agent_for_firm(firm, system_user)
                all_firm_stats.append(stats)
                run["per_firm"][firm_id] = stats
                logger.info(
                    f"[finance-agent] firm={firm.get('name','')[:20]} "
                    f"fees_posted={stats['fees_posted_rows']} "
                    f"fees_amount=₹{stats['fees_total_amount']} "
                    f"refunds={stats['refunds_posted']} "
                    f"a_to_z_booked={stats['a_to_z']['granted_booked']} "
                    f"unmatched={stats['unmatched_transactions']} "
                    f"stuck={len(stats['stuck_reimbursements'])} "
                    f"tb_ok={stats['trial_balance'].get('ok', True)} "
                    f"clearing=₹{stats['clearing'].get('balance', 0)} "
                    f"errors={len(stats['errors'])}"
                )
            except Exception as e:
                logger.error(f"[finance-agent] firm={firm.get('name')} crashed: {e}", exc_info=True)

        if not all_firm_stats:
            logger.info("[finance-agent] no firms with active Amazon credentials")
            run["status"] = "completed"
            run["completed_at"] = datetime.now(timezone.utc).isoformat()
            run["totals"] = _agent_aggregate_totals([])
            await db.scheduled_job_runs.update_one({"id": run["id"]}, {"$set": run})
            return

        # Browser-agent scrape: pull FBA reimbursements that SP-API won't ship.
        # Runs ONCE per agent invocation (single Seller Central account); the
        # result is attributed to BROWSER_AGENT_FIRM_ID env or the first
        # Amazon firm. If the browser isn't logged in, we degrade gracefully
        # and surface a notification rather than block the whole run.
        reimb_scrape = None
        reimb_firm = await _pick_browser_agent_firm()
        if reimb_firm:
            reimb_scrape = await _scrape_and_book_reimbursements(
                reimb_firm["id"], reimb_firm.get("name", ""), system_user
            )
            reimb_scrape["firm_id"]   = reimb_firm["id"]
            reimb_scrape["firm_name"] = reimb_firm.get("name")
            run["reimbursement_scrape"] = reimb_scrape
            logger.info(
                f"[finance-agent] reimbursement scrape: status={reimb_scrape.get('status')} "
                f"scraped={reimb_scrape.get('scraped')} new={reimb_scrape.get('new_rows')} "
                f"booked={reimb_scrape.get('booked')} amt=₹{reimb_scrape.get('total_amount')}"
            )

        totals = _agent_aggregate_totals(all_firm_stats, reimb_scrape)
        priority = _agent_priority(all_firm_stats)
        # Browser session expired or page-changed bumps priority — accountant
        # has to take an action (re-login) for the next run to be clean.
        if reimb_scrape and reimb_scrape.get("status") in ("session_expired", "page_changed"):
            priority = "high"

        logger.info(
            f"[finance-agent] daily run done: firms={len(all_firm_stats)} "
            f"fees=₹{totals['fees_total_amount']} refunds={totals['refunds_posted']} "
            f"a_to_z={totals['a_to_z_booked']} reimb_booked={totals['reimbursements_booked']} "
            f"unmatched={totals['unmatched_transactions']} "
            f"stuck={totals['stuck_reimbursements']} drifts={totals['settlement_drifts']} "
            f"tb_fail={totals['trial_balance_failures']} duplicates={totals['duplicates_found']} "
            f"anomalies={totals['anomalies']} errors={totals['errors']} priority={priority}"
        )

        # Persist the full run for audit trail.
        run["status"] = "completed"
        run["completed_at"] = datetime.now(timezone.utc).isoformat()
        run["totals"] = totals
        run["priority"] = priority
        await db.scheduled_job_runs.update_one({"id": run["id"]}, {"$set": run})

        # Build a digest notification. Title leads with actions, then the
        # most material finding. Detail message lists every finding count.
        title_bits = []
        if totals["fees_total_amount"] > 0: title_bits.append(f"₹{totals['fees_total_amount']:,.0f} fees")
        if totals["refunds_posted"] > 0:    title_bits.append(f"{totals['refunds_posted']} refunds")
        if totals["a_to_z_booked"] > 0:     title_bits.append(f"{totals['a_to_z_booked']} A-Z")
        if totals["reimbursements_booked"] > 0:
            title_bits.append(f"₹{totals['reimbursements_total_amount']:,.0f} reimb")
        finding_bits = []
        if totals["reimbursement_status"] == "session_expired":
            finding_bits.append("⛔ browser session expired")
        elif totals["reimbursement_status"] == "page_changed":
            finding_bits.append("⛔ reimb page changed")
        if totals["trial_balance_failures"] > 0: finding_bits.append(f"⛔ {totals['trial_balance_failures']} TB break")
        if totals["unmatched_transactions"] > 0: finding_bits.append(f"⚠ {totals['unmatched_transactions']} unmatched")
        if totals["stuck_reimbursements"] > 0:   finding_bits.append(f"⚠ {totals['stuck_reimbursements']} stuck reimb")
        if totals["settlement_drifts"] > 0:      finding_bits.append(f"⚠ {totals['settlement_drifts']} drift")
        if totals["duplicates_found"] > 0:       finding_bits.append(f"⛔ {totals['duplicates_found']} dups")
        if totals["anomalies"] > 0:              finding_bits.append(f"⚠ {totals['anomalies']} anom")
        if totals["clearing_drifts"] > 0:        finding_bits.append(f"⚠ {totals['clearing_drifts']} clearing")
        if totals["gst_drifts"] > 0:             finding_bits.append(f"⚠ {totals['gst_drifts']} GST")

        title = "Finance agent: " + (
            ", ".join(title_bits + finding_bits) if (title_bits or finding_bits) else "all clean")

        reimb_line = ""
        rs = reimb_scrape or {}
        if rs.get("status") == "ok":
            reimb_line = (
                f"FBA reimbursements: {rs.get('new_rows', 0)} new "
                f"({rs.get('booked', 0)} booked, ₹{rs.get('total_amount', 0):,.0f}). "
            )
        elif rs.get("status") == "session_expired":
            reimb_line = (
                "FBA reimbursements: browser session expired — please re-login at "
                "/admin/browser-agent so the next run can scrape. "
            )
        elif rs.get("status") == "page_changed":
            reimb_line = (
                "FBA reimbursements: Amazon's report page layout changed — "
                "scraper selectors need updating. "
            )

        try:
            await create_notification(
                title=title,
                message=(
                    f"Daily reconciliation across {len(all_firm_stats)} firm(s). "
                    f"Actions: ₹{totals['fees_total_amount']:,.0f} fees in {totals['fees_journal_entries']} "
                    f"journal entries, {totals['refunds_posted']} refunds, "
                    f"{totals['a_to_z_booked']} A-Z claims booked ({totals['a_to_z_pending']} pending). "
                    + reimb_line +
                    f"Findings: {totals['unmatched_transactions']} unmatched, "
                    f"{totals['stuck_reimbursements']} stuck reimbursements, "
                    f"{totals['settlement_drifts']} settlement drifts, "
                    f"{totals['trial_balance_failures']} trial-balance failures, "
                    f"{totals['clearing_drifts']} clearing-account drifts, "
                    f"{totals['gst_drifts']} GST drifts, "
                    f"{totals['duplicates_found']} duplicates, "
                    f"{totals['anomalies']} anomalies. "
                    f"90+ receivables: ₹{totals['aging_90plus_total']:,.0f}. "
                    f"Errors: {totals['errors']}."
                ),
                notification_type="info",
                target_roles=["accountant", "admin"],
                priority=priority,
                data={
                    "type": "finance_agent_summary",
                    "run_id": run["id"],
                    "per_firm": all_firm_stats,
                    "totals": totals,
                    "reimbursement_scrape": reimb_scrape,
                },
            )
        except Exception as e:
            logger.warning(f"[finance-agent] notification post failed: {e}")
    except Exception as e:
        logger.error(f"[SCHEDULED] Amazon finance agent failed: {e}", exc_info=True)
        run["status"] = "failed"
        run["error"] = str(e)[:500]
        run["completed_at"] = datetime.now(timezone.utc).isoformat()
        await db.scheduled_job_runs.update_one({"id": run["id"]}, {"$set": run})


# ===================================================================
# Finance Agent — continuous scrape pulse
# ===================================================================
# Runs every 30 minutes. Picks the next-due scrape task from
# `finance_scraper_state` and executes it through the existing browser
# agent. This makes the Finance Agent feel "always on" — between the
# daily full reconciliation pass and the pulse, the books are fresh
# without anyone clicking anything.
#
# Adding a new scrape: append to FINANCE_SCRAPE_TASKS with a cadence
# and a handler coroutine `(system_user, broadcast) -> dict`. State
# rows are auto-seeded on the next pulse.
#
# Cookies live in MongoDB (browser_sessions), so the session survives
# pm2 restarts; the pulse keeps it warm for the ~14 days Amazon honors
# a session. When it expires, the pulse posts ONE high-priority
# notification telling the user to re-login at /admin/browser-agent.

async def _pulse_handler_fba_reimbursements(system_user: dict, broadcast) -> dict:
    """One pulse of the FBA reimbursement scrape. Idempotent on its own."""
    firm = await _pick_browser_agent_firm()
    if not firm:
        return {"status": "skipped", "reason": "no_amazon_firm",
                "summary": "No firm with active Amazon credentials"}
    await broadcast({"task": "fba_reimbursements", "phase": "starting",
                     "firm": firm.get("name"), "ts": datetime.now(timezone.utc).isoformat()})
    result = await _scrape_and_book_reimbursements(
        firm["id"], firm.get("name", ""), system_user
    )
    result["firm_id"]   = firm["id"]
    result["firm_name"] = firm.get("name")
    result["summary"] = (
        f"{result.get('new_rows', 0)} new / {result.get('booked', 0)} booked / "
        f"₹{result.get('total_amount', 0):,.0f}"
        if result.get("status") == "ok" else
        f"{result.get('status')} — {result.get('error') or 'see logs'}"
    )
    await broadcast({"task": "fba_reimbursements", "phase": "completed",
                     "status": result.get("status"),
                     "summary": result["summary"],
                     "ts": datetime.now(timezone.utc).isoformat()})
    return result


async def _pulse_handler_amazon_order_lookup(system_user: dict, broadcast) -> dict:
    """Walk every Amazon order in the CRM that has no `amazon_order_scrapes`
    row and scrape its full financial breakdown from Seller Central.

    One pulse processes up to AMAZON_ORDER_LOOKUP_BATCH orders and stops
    early on wall-clock budget or session-expired. Remaining orders are
    picked up by the next pulse — so a backlog of N orders drains over
    ceil(N / batch) pulses.

    Each scrape result is upserted into amazon_order_scrapes keyed on
    order_id, including failures — that way an order Amazon doesn't
    recognize isn't retried forever. To re-scrape, hit the per-order
    endpoint with force=true."""
    batch_size = int(os.environ.get("AMAZON_ORDER_LOOKUP_BATCH", "25"))
    wall_budget_s = int(os.environ.get("AMAZON_ORDER_LOOKUP_WALL_S", "900"))  # 15 min

    agent = await get_browser_agent()
    if not agent or not agent.page:
        return {"status": "skipped", "reason": "agent_not_started",
                "summary": "Browser agent not started — sign in at /admin/browser-agent"}

    # Orders we already tried (success OR failure) — skip them. The user can
    # re-trigger any single one with force=true on the per-order endpoint.
    already_scraped = set(
        await db.amazon_order_scrapes.distinct("order_id")
    )

    # Pick the next chunk — newest orders first so freshly-imported orders
    # get their detail filled in before historical ones.
    pipeline = [
        {"$match": {"amazon_order_id": {"$nin": list(already_scraped) or [None]}}},
        {"$sort": {"purchase_date": -1}},
        {"$limit": batch_size},
        {"$project": {"_id": 0, "amazon_order_id": 1, "purchase_date": 1}},
    ]
    candidates = await db.amazon_orders.aggregate(pipeline).to_list(batch_size)
    logger.info(
        f"[order-lookup] already_scraped={len(already_scraped)} sample={list(already_scraped)[:3]} "
        f"picked={[c.get('amazon_order_id') for c in candidates]}"
    )

    if not candidates:
        # Total remaining was zero — report idle.
        total_orders = await db.amazon_orders.count_documents({})
        return {
            "status": "ok",
            "summary": f"No orders pending — {total_orders} orders / {len(already_scraped)} scraped",
            "scraped": 0, "errors": 0, "session_expired": False,
            "remaining": 0,
        }

    await broadcast({
        "task": "amazon_order_lookup", "phase": "starting",
        "batch": len(candidates), "already": len(already_scraped),
        "ts": datetime.now(timezone.utc).isoformat(),
    })

    scraped_ok = 0
    scraped_err = 0
    scraped_not_found = 0
    session_expired = False
    start_ts = datetime.now(timezone.utc)

    for idx, order in enumerate(candidates):
        order_id = order.get("amazon_order_id")
        if not order_id:
            continue

        # Wall-clock guard so a slow pulse doesn't overrun the cadence.
        elapsed = (datetime.now(timezone.utc) - start_ts).total_seconds()
        if elapsed > wall_budget_s:
            logger.info(f"[order-lookup] wall budget exhausted at {idx}/{len(candidates)}")
            break

        try:
            result = await agent.scrape_order_transactions(order_id)
        except Exception as e:
            logger.exception(f"[order-lookup] order={order_id} crashed")
            result = {
                "status": "error", "order_id": order_id, "url": "",
                "transactions": [], "totals": {}, "raw_text_sample": "",
                "error": f"Crash: {str(e)[:200]}",
            }

        status = result.get("status") or "error"
        doc = {
            "order_id": order_id,
            "scraped_at": datetime.now(timezone.utc).isoformat(),
            "scraped_by": "system-finance-scraper",
            **result,
        }
        await db.amazon_order_scrapes.update_one(
            {"order_id": order_id},
            {"$set": doc},
            upsert=True,
        )

        if status == "ok":
            scraped_ok += 1
        elif status == "not_found":
            scraped_not_found += 1
        else:
            scraped_err += 1

        # If the session died mid-batch, bail — every remaining call will fail
        # the same way and we want the operator to re-login.
        if status == "not_logged_in":
            session_expired = True
            logger.warning(f"[order-lookup] session expired at order {order_id}, aborting batch")
            break

        # Per-iteration progress so the Watch page shows movement.
        await broadcast({
            "task": "amazon_order_lookup", "phase": "progress",
            "order_id": order_id, "status": status,
            "done": idx + 1, "of": len(candidates),
            "ts": datetime.now(timezone.utc).isoformat(),
        })

        # Polite pacing — Amazon throttles fast hits on the order page.
        await asyncio.sleep(2)

    # Remaining backlog after this pulse (for the Watch page).
    after_scraped = await db.amazon_order_scrapes.count_documents({})
    total_orders = await db.amazon_orders.count_documents({})
    remaining = max(0, total_orders - after_scraped)

    summary = (
        f"{scraped_ok} ok / {scraped_not_found} not_found / {scraped_err} err / "
        f"{remaining} still pending"
        if not session_expired else
        f"session expired after {scraped_ok + scraped_not_found + scraped_err} orders — "
        f"re-login at /admin/browser-agent"
    )

    overall_status = (
        "session_expired" if session_expired else
        ("ok" if scraped_err == 0 else "partial")
    )

    await broadcast({
        "task": "amazon_order_lookup", "phase": "completed",
        "status": overall_status, "summary": summary,
        "ts": datetime.now(timezone.utc).isoformat(),
    })

    return {
        "status": overall_status,
        "summary": summary,
        "scraped": scraped_ok,
        "not_found": scraped_not_found,
        "errors": scraped_err,
        "session_expired": session_expired,
        "remaining": remaining,
        "total_orders": total_orders,
        "already_scraped": after_scraped,
    }


FINANCE_SCRAPE_TASKS = {
    "fba_reimbursements": {
        "label": "FBA reimbursements",
        "description": "Walk the Seller Central Reimbursements report and book new rows.",
        "cadence_minutes": int(os.environ.get("FIN_SCRAPE_FBA_REIMB_MINUTES", "720")),  # 12h
        "handler": _pulse_handler_fba_reimbursements,
    },
    "amazon_order_lookup": {
        "label": "Amazon order lookup",
        "description": "Open each Amazon order in Seller Central and pull its financial breakdown into amazon_order_scrapes.",
        "cadence_minutes": int(os.environ.get("FIN_SCRAPE_ORDER_LOOKUP_MINUTES", "30")),
        "handler": _pulse_handler_amazon_order_lookup,
    },
    # Future tasks (selectors + handlers pending):
    # "settlements":          {"label": "Settlement statements", "cadence_minutes": 360, ...},
    # "a_to_z_claims":        {"label": "A-Z claims dashboard",  "cadence_minutes": 360, ...},
    # "returns":              {"label": "Returns dashboard",     "cadence_minutes": 240, ...},
    # "inventory_adjustments":{"label": "Inventory adjustments", "cadence_minutes": 1440, ...},
    # "long_term_storage":    {"label": "Long-term storage fees",  "cadence_minutes": 10080, ...},
}


async def _seed_scraper_state():
    """Ensure each task in FINANCE_SCRAPE_TASKS has a state row. Idempotent —
    only inserts missing rows; never resets a row that's already running."""
    now = datetime.now(timezone.utc).isoformat()
    for kind, meta in FINANCE_SCRAPE_TASKS.items():
        existing = await db.finance_scraper_state.find_one({"task_kind": kind}, {"_id": 0, "task_kind": 1})
        if existing:
            continue
        await db.finance_scraper_state.insert_one({
            "id": str(uuid.uuid4()),
            "task_kind": kind,
            "label": meta["label"],
            "cadence_minutes": meta["cadence_minutes"],
            "enabled": True,
            "running": False,
            "next_due_at": now,  # due immediately on first pulse
            "last_run_at": None,
            "last_status": None,
            "last_result": None,
            "last_error": None,
            "created_at": now,
        })


async def _broadcast_scrape_progress(payload: dict):
    """Push a small JSON blob to the existing browser-agent WebSocket so the
    Watch Live page can show what the agent is doing right now. The
    browser-agent's own screen-pop already pushes screenshots; this is the
    higher-level task narration on top."""
    try:
        await broadcast_status({"source": "finance_scraper", **payload})
    except Exception as e:
        logger.debug(f"[scrape-pulse] broadcast failed: {e}")


async def scheduled_finance_scraper_pulse():
    """One tick of the continuous scrape loop. Picks the most-overdue task
    from finance_scraper_state and runs it. Concurrency-safe via the atomic
    `running` flag in find_and_modify."""
    try:
        await _seed_scraper_state()
    except Exception as e:
        logger.error(f"[scrape-pulse] seed failed: {e}")
        return

    now = datetime.now(timezone.utc)
    # Atomic claim: only one pulse can grab this task at a time.
    task_state = await db.finance_scraper_state.find_one_and_update(
        {
            "enabled": True,
            "running": {"$ne": True},
            "next_due_at": {"$lte": now.isoformat()},
        },
        {"$set": {
            "running": True,
            "started_at": now.isoformat(),
        }},
        sort=[("next_due_at", 1)],
        return_document=True,
    )
    if not task_state:
        return  # nothing due — quiet pulse

    kind = task_state["task_kind"]
    meta = FINANCE_SCRAPE_TASKS.get(kind)
    cadence = (meta or {}).get("cadence_minutes", task_state.get("cadence_minutes", 720))
    next_due = (now + timedelta(minutes=cadence)).isoformat()

    if not meta:
        # Disable rows whose task definition got removed so we don't busy-loop.
        await db.finance_scraper_state.update_one(
            {"task_kind": kind},
            {"$set": {"running": False, "enabled": False,
                      "last_error": "task kind no longer defined",
                      "next_due_at": next_due}},
        )
        logger.warning(f"[scrape-pulse] unknown task kind {kind}, disabling")
        return

    system_user = {
        "id": "system-finance-scraper",
        "first_name": "Finance",
        "last_name": "Scraper",
        "email": "system@musclegrid.in",
    }

    logger.info(f"[scrape-pulse] running task={kind}")
    try:
        result = await meta["handler"](system_user, _broadcast_scrape_progress)
        status = result.get("status") or "ok"
        await db.finance_scraper_state.update_one(
            {"task_kind": kind},
            {"$set": {
                "running": False,
                "last_run_at": now.isoformat(),
                "last_status": status,
                "last_result": result,
                "last_error": result.get("error"),
                "next_due_at": next_due,
            }},
        )
        # Surface a session-expired event ONCE — don't spam the
        # accountant on every pulse for the same problem.
        if status == "session_expired":
            recent = await db.notifications.find_one(
                {"data.type": "finance_scraper_session_expired",
                 "created_at": {"$gte": (now - timedelta(hours=6)).isoformat()}},
                {"_id": 0, "id": 1},
            )
            if not recent:
                try:
                    await create_notification(
                        title="Finance scraper: Seller Central session expired",
                        message=("The autonomous scrape pulse can't run — browser session has expired. "
                                 "Open /admin/browser-agent, sign in once, and the agent will resume "
                                 "scraping every 30 minutes for the next ~14 days."),
                        notification_type="warning",
                        target_roles=["accountant", "admin"],
                        priority="high",
                        data={"type": "finance_scraper_session_expired", "task": kind},
                    )
                except Exception as e:
                    logger.warning(f"[scrape-pulse] session-expired notif failed: {e}")
        logger.info(f"[scrape-pulse] done task={kind} status={status}")
    except Exception as e:
        logger.error(f"[scrape-pulse] task={kind} crashed: {e}", exc_info=True)
        await db.finance_scraper_state.update_one(
            {"task_kind": kind},
            {"$set": {
                "running": False,
                "last_run_at": now.isoformat(),
                "last_status": "error",
                "last_error": str(e)[:500],
                "next_due_at": next_due,
            }},
        )


async def scheduled_payment_verification_reminder():
    """
    Scheduled job: Send reminders for overdue dealer payment verifications.
    Runs every hour via APScheduler.
    """
    try:
        now = datetime.now(timezone.utc).isoformat()
        
        # Find orders with payment proof uploaded but not verified within 24hrs
        overdue_orders = await db.dealer_orders.find({
            "payment_status": "verification_pending",
            "payment_verification_due": {"$lt": now}
        }, {"_id": 0, "id": 1, "order_number": 1, "dealer_id": 1}).to_list(100)
        
        if overdue_orders:
            # Create a single notification for all overdue verifications
            await create_notification(
                title=f"⚠️ {len(overdue_orders)} Dealer Payments Overdue",
                message=f"{len(overdue_orders)} dealer payment(s) need verification. Some are past the 24hr deadline.",
                notification_type="warning",
                link="/admin/dealer-payments",
                target_roles=["admin", "accountant"],
                priority="high"
            )
            logger.info(f"[SCHEDULED] Payment Verification: {len(overdue_orders)} overdue reminders sent")
        else:
            logger.debug("[SCHEDULED] Payment Verification: No overdue payments")
    except Exception as e:
        logger.error(f"[SCHEDULED] Payment Verification Reminder failed: {str(e)}")


def hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

def verify_password(plain_password: str, hashed_password: str) -> bool:
    # PHP bcrypt uses $2y$ prefix, Python bcrypt uses $2b$
    # Convert $2y$ to $2b$ for compatibility
    if hashed_password.startswith('$2y$'):
        hashed_password = '$2b$' + hashed_password[4:]
    return bcrypt.checkpw(plain_password.encode('utf-8'), hashed_password.encode('utf-8'))

def create_token(user_id: str, role: str) -> str:
    # Consumer-app roles get a long-lived session so customers aren't logged out
    # every day; staff/admin keep the short 24h session for security.
    hours = 24 * 30 if role in ("customer", "dealer") else JWT_EXPIRATION_HOURS
    payload = {
        "user_id": user_id,
        "role": role,
        "exp": datetime.now(timezone.utc) + timedelta(hours=hours)
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGORITHM)

async def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)):
    try:
        payload = jwt.decode(credentials.credentials, JWT_SECRET, algorithms=[JWT_ALGORITHM])
        user = await db.users.find_one({"id": payload["user_id"]}, {"_id": 0})
        if not user or user.get("is_deleted"):
            raise HTTPException(status_code=401, detail="User not found")
        return user
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")

# Optional version that returns None instead of raising exception (for endpoints with fallback auth)
security_optional = HTTPBearer(auto_error=False)

async def get_current_user_optional(credentials: HTTPAuthorizationCredentials = Depends(security_optional)):
    """Get current user if token provided, otherwise return None.

    Returns None for truly anonymous (no Authorization header). Raises 401 for
    expired/tampered tokens so callers fail closed instead of treating an invalid
    token as anonymous.
    """
    if not credentials:
        return None
    try:
        payload = jwt.decode(credentials.credentials, JWT_SECRET, algorithms=[JWT_ALGORITHM])
        user = await db.users.find_one({"id": payload["user_id"]}, {"_id": 0})
        return user
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")


FILE_URL_TTL_SECONDS = int(os.environ.get("FILE_URL_TTL_SECONDS", str(6 * 3600)))  # default 6h


def make_signed_file_url(relative_path: str, ttl_seconds: int = FILE_URL_TTL_SECONDS, user_id: str | None = None) -> str:
    """Return a signed path for serving a file without a Bearer token.

    The signature binds the relative path + expiry to FILE_DOWNLOAD_SECRET; an
    optional user_id is also bound so the URL is single-user. TTL defaults to 6h
    (was 10 min) so links embedded in a dashboard stay clickable for a full work
    session — a 10-min TTL meant invoices opened later 401'd.
    """
    import hmac as _hmac, hashlib as _hashlib, base64 as _b64
    exp = int((datetime.now(timezone.utc) + timedelta(seconds=ttl_seconds)).timestamp())
    msg = f"{relative_path}|{exp}|{user_id or ''}".encode()
    sig = _hmac.new(FILE_DOWNLOAD_SECRET.encode(), msg, _hashlib.sha256).digest()
    sig_b64 = _b64.urlsafe_b64encode(sig).decode().rstrip("=")
    base = f"/api/files/{relative_path}?exp={exp}&sig={sig_b64}"
    if user_id:
        base += f"&u={user_id}"
    return base


def verify_signed_file_url(relative_path: str, exp: str, sig: str, user_id: str | None = None) -> bool:
    import hmac as _hmac, hashlib as _hashlib, base64 as _b64
    try:
        exp_int = int(exp)
    except (TypeError, ValueError):
        return False
    if exp_int < int(datetime.now(timezone.utc).timestamp()):
        return False
    msg = f"{relative_path}|{exp_int}|{user_id or ''}".encode()
    expected = _hmac.new(FILE_DOWNLOAD_SECRET.encode(), msg, _hashlib.sha256).digest()
    expected_b64 = _b64.urlsafe_b64encode(expected).decode().rstrip("=")
    return _const_eq(sig or "", expected_b64)

def require_roles(allowed_roles: List[str]):
    async def role_checker(user: dict = Depends(get_current_user)):
        if user["role"] not in allowed_roles:
            raise HTTPException(status_code=403, detail="Insufficient permissions")
        return user
    return role_checker

async def add_ticket_history(ticket_id: str, action: str, by_user: dict, details: dict = None):
    """Add entry to ticket history with a hard cap on slice size.

    The previous implementation $push-ed without a $slice cap. A long-lived
    ticket cycled through many state changes accumulates kilobytes per entry
    and eventually trips Mongo's 16MB document limit, after which every
    further write to the ticket fails. Keep the most recent 500 entries — more
    than enough for any real audit trail — and let older entries roll off.
    """
    history_entry = {
        "action": action,
        "by": f"{by_user['first_name']} {by_user['last_name']}",
        "by_id": by_user["id"],
        "by_role": by_user["role"],
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "details": details or {}
    }
    await db.tickets.update_one(
        {"id": ticket_id},
        {"$push": {"history": {"$each": [history_entry], "$slice": -500}}},
    )

async def log_activity(action: str, entity_type: str, entity_id: str, user: dict, details: dict = None):
    """Log activity to audit_logs collection"""
    now = datetime.now(timezone.utc)
    log_entry = {
        "id": str(uuid.uuid4()),
        "action": action,
        "entity_type": entity_type,
        "entity_id": entity_id,
        "user_id": user["id"],
        "user_name": f"{user['first_name']} {user['last_name']}",
        "user_role": user["role"],
        "details": details or {},
        "created_at": now.isoformat()
    }
    await db.audit_logs.insert_one(log_entry)


# ==================== DUPLICATE VALIDATION UTILITIES ====================

async def check_tracking_id_duplicate(tracking_id: str, exclude_id: str = None) -> dict:
    """
    Check if tracking ID already exists across all relevant collections.
    Returns: {"exists": bool, "source": str, "details": dict} 
    """
    if not tracking_id or tracking_id.strip() == "":
        return {"exists": False}
    
    tracking_id = tracking_id.strip()
    
    # Check pending_fulfillment
    query = {"tracking_id": tracking_id}
    if exclude_id:
        query["id"] = {"$ne": exclude_id}
    
    pf = await db.pending_fulfillment.find_one(query, {"_id": 0, "id": 1, "order_id": 1, "status": 1})
    if pf:
        return {
            "exists": True, 
            "source": "pending_fulfillment",
            "details": {"order_id": pf.get("order_id"), "status": pf.get("status")},
            "message": f"Tracking ID already used in Pending Fulfillment (Order: {pf.get('order_id')})"
        }
    
    # Check dispatches
    dispatch = await db.dispatches.find_one(
        {"tracking_id": tracking_id, "status": {"$ne": "cancelled"}},
        {"_id": 0, "dispatch_number": 1, "order_id": 1, "status": 1}
    )
    if dispatch:
        return {
            "exists": True,
            "source": "dispatches", 
            "details": {"dispatch_number": dispatch.get("dispatch_number"), "status": dispatch.get("status")},
            "message": f"Tracking ID already used in Dispatch #{dispatch.get('dispatch_number')}"
        }
    
    # Check tickets (return tracking)
    ticket = await db.tickets.find_one(
        {"$or": [{"pickup_tracking": tracking_id}, {"return_tracking": tracking_id}]},
        {"_id": 0, "ticket_number": 1, "status": 1}
    )
    if ticket:
        return {
            "exists": True,
            "source": "tickets",
            "details": {"ticket_number": ticket.get("ticket_number")},
            "message": f"Tracking ID already used in Ticket #{ticket.get('ticket_number')}"
        }
    
    return {"exists": False}


async def check_order_id_duplicate(order_id: str, exclude_id: str = None, source_type: str = None) -> dict:
    """
    Check if Order ID already exists across all relevant collections.
    source_type: 'pending_fulfillment', 'dispatch', 'amazon', 'sales' - to exclude self
    Returns: {"exists": bool, "source": str, "details": dict}
    """
    if not order_id or order_id.strip() == "":
        return {"exists": False}
    
    order_id = order_id.strip()
    
    # Check pending_fulfillment
    if source_type != "pending_fulfillment":
        pf = await db.pending_fulfillment.find_one(
            {"$or": [{"order_id": order_id}, {"amazon_order_id": order_id}]},
            {"_id": 0, "id": 1, "status": 1}
        )
        if pf and pf.get("id") != exclude_id:
            return {
                "exists": True,
                "source": "pending_fulfillment",
                "details": {"status": pf.get("status")},
                "message": "Order ID already exists in Pending Fulfillment"
            }
    
    # Check dispatches
    if source_type != "dispatch":
        dispatch = await db.dispatches.find_one(
            {"$or": [{"order_id": order_id}, {"marketplace_order_id": order_id}], "status": {"$ne": "cancelled"}},
            {"_id": 0, "dispatch_number": 1, "status": 1}
        )
        if dispatch:
            return {
                "exists": True,
                "source": "dispatches",
                "details": {"dispatch_number": dispatch.get("dispatch_number")},
                "message": f"Order ID already exists in Dispatch #{dispatch.get('dispatch_number')}"
            }
    
    # Check amazon_orders (if not already tracked)
    if source_type not in ["amazon", "pending_fulfillment"]:
        amazon = await db.amazon_orders.find_one(
            {"amazon_order_id": order_id, "crm_status": {"$in": ["dispatched", "in_pending_fulfillment"]}},
            {"_id": 0, "crm_status": 1}
        )
        if amazon:
            return {
                "exists": True,
                "source": "amazon_orders",
                "details": {"crm_status": amazon.get("crm_status")},
                "message": f"Amazon Order already processed (Status: {amazon.get('crm_status')})"
            }
    
    # Check sales_orders
    if source_type != "sales":
        sales = await db.sales_orders.find_one(
            {"$or": [{"order_number": order_id}, {"external_invoice_number": order_id}]},
            {"_id": 0, "order_number": 1, "status": 1}
        )
        if sales and sales.get("id") != exclude_id:
            return {
                "exists": True,
                "source": "sales_orders",
                "details": {"order_number": sales.get("order_number")},
                "message": f"Order ID already exists in Sales Order #{sales.get('order_number')}"
            }
    
    return {"exists": False}


async def check_invoice_number_duplicate(invoice_number: str, exclude_id: str = None, firm_id: str = None) -> dict:
    """
    Check if Invoice Number already exists across all relevant collections.
    CRITICAL FIX (H1): Now scoped to firm_id to allow same invoice numbers across different firms.
    Returns: {"exists": bool, "source": str, "details": dict}
    """
    if not invoice_number or invoice_number.strip() == "":
        return {"exists": False}
    
    invoice_number = invoice_number.strip()
    
    # Build base query - scope to firm if provided
    def build_query(base_query: dict) -> dict:
        if firm_id:
            return {**base_query, "firm_id": firm_id}
        return base_query
    
    # Check dispatches (scoped to firm)
    dispatch_query = build_query({"invoice_number": invoice_number, "status": {"$ne": "cancelled"}})
    dispatch = await db.dispatches.find_one(
        dispatch_query,
        {"_id": 0, "id": 1, "dispatch_number": 1, "status": 1}
    )
    if dispatch and dispatch.get("id") != exclude_id:
        return {
            "exists": True,
            "source": "dispatches",
            "details": {"dispatch_number": dispatch.get("dispatch_number")},
            "message": f"Invoice Number already used in Dispatch #{dispatch.get('dispatch_number')}"
        }
    
    # Check sales_invoices (scoped to firm)
    sales_query = build_query({"invoice_number": invoice_number})
    sales_inv = await db.sales_invoices.find_one(
        sales_query,
        {"_id": 0, "id": 1, "invoice_number": 1}
    )
    if sales_inv and sales_inv.get("id") != exclude_id:
        return {
            "exists": True,
            "source": "sales_invoices",
            "details": {},
            "message": "Invoice Number already exists in Sales Invoices"
        }
    
    # Check service_invoices (scoped to firm)
    service_query = build_query({"invoice_number": invoice_number})
    service_inv = await db.service_invoices.find_one(
        service_query,
        {"_id": 0, "id": 1}
    )
    if service_inv and service_inv.get("id") != exclude_id:
        return {
            "exists": True,
            "source": "service_invoices", 
            "details": {},
            "message": "Invoice Number already exists in Service Invoices"
        }
    
    # Check pending_fulfillment (scoped to firm)
    pf_base = {"$or": [{"invoice_number": invoice_number}, {"external_invoice_number": invoice_number}]}
    if firm_id:
        pf_query = {"$and": [pf_base, {"firm_id": firm_id}]}
    else:
        pf_query = pf_base
    pf = await db.pending_fulfillment.find_one(
        pf_query,
        {"_id": 0, "id": 1, "order_id": 1}
    )
    if pf and pf.get("id") != exclude_id:
        return {
            "exists": True,
            "source": "pending_fulfillment",
            "details": {"order_id": pf.get("order_id")},
            "message": f"Invoice Number already used in Pending Fulfillment (Order: {pf.get('order_id')})"
        }
    
    return {"exists": False}


async def validate_no_duplicates(
    tracking_id: str = None, 
    order_id: str = None, 
    invoice_number: str = None,
    exclude_id: str = None,
    source_type: str = None
) -> list:
    """
    Validate multiple fields at once. Returns list of error messages.
    """
    errors = []
    
    if tracking_id:
        result = await check_tracking_id_duplicate(tracking_id, exclude_id)
        if result["exists"]:
            errors.append(result["message"])
    
    if order_id:
        result = await check_order_id_duplicate(order_id, exclude_id, source_type)
        if result["exists"]:
            errors.append(result["message"])
    
    if invoice_number:
        result = await check_invoice_number_duplicate(invoice_number, exclude_id)
        if result["exists"]:
            errors.append(result["message"])
    
    return errors


async def get_stock_info_for_pending_fulfillment(master_sku_id: str, pf_entry: dict) -> dict:
    """Get stock info for a pending fulfillment entry"""
    if not master_sku_id:
        return {
            "product_name": pf_entry.get("master_sku_name"),
            "sku_code": pf_entry.get("sku_code"),
            "current_stock": 0,
            "in_stock": False,
            "is_manufactured": False
        }
    
    master_sku = await db.master_skus.find_one({"id": master_sku_id}, {"_id": 0})
    if not master_sku:
        return {
            "product_name": pf_entry.get("master_sku_name"),
            "sku_code": pf_entry.get("sku_code"),
            "current_stock": 0,
            "in_stock": False,
            "is_manufactured": False
        }
    
    is_manufactured = master_sku.get("is_manufactured", False) or master_sku.get("product_type") == "manufactured"
    firm_id = pf_entry.get("firm_id")
    
    if is_manufactured:
        # Check finished_good_serials for manufactured items
        # Bug 4 Fix: Don't filter by firm_id if not set - check all stock
        query = {"master_sku_id": master_sku_id, "status": "in_stock"}
        if firm_id:
            query["firm_id"] = firm_id
        stock_count = await db.finished_good_serials.count_documents(query)
        current_stock = stock_count
    else:
        # Check inventory_ledger for traded items
        # Bug 4 Fix: Use master_sku as item_type and handle missing firm_id
        if firm_id:
            current_stock = await get_current_stock("master_sku", master_sku_id, firm_id)
        else:
            # No firm_id - sum across all firms
            pipeline = [
                {"$match": {"item_id": master_sku_id, "item_type": "master_sku"}},
                {"$sort": {"created_at": -1}},
                {"$group": {"_id": "$firm_id", "latest_balance": {"$first": "$running_balance"}}},
                {"$group": {"_id": None, "total": {"$sum": "$latest_balance"}}}
            ]
            result = await db.inventory_ledger.aggregate(pipeline).to_list(1)
            current_stock = result[0]["total"] if result else 0
    
    return {
        "product_name": master_sku.get("name"),
        "sku_code": master_sku.get("sku_code"),
        "current_stock": current_stock,
        "in_stock": current_stock > 0,
        "is_manufactured": is_manufactured
    }


# ==================== AUTH ENDPOINTS ====================

@api_router.post("/auth/register", response_model=TokenResponse)
async def register(user_data: UserCreate):
    existing = await db.users.find_one({"email": user_data.email.lower()})
    if existing:
        raise HTTPException(status_code=400, detail="Email already registered")
    
    # Only allow customer registration via public endpoint
    if user_data.role != "customer":
        raise HTTPException(status_code=400, detail="Invalid registration")
    
    user_id = str(uuid.uuid4())
    now = datetime.now(timezone.utc).isoformat()
    
    user_doc = {
        "id": user_id,
        "email": user_data.email.lower(),
        "first_name": user_data.first_name,
        "last_name": user_data.last_name,
        "phone": user_data.phone,
        "role": "customer",
        "password_hash": hash_password(user_data.password),
        "address": user_data.address,
        "city": user_data.city,
        "state": user_data.state,
        "pincode": user_data.pincode,
        "created_at": now,
        "updated_at": now
    }
    
    await db.users.insert_one(user_doc)
    token = create_token(user_id, "customer")
    
    return TokenResponse(
        access_token=token,
        user=UserResponse(**{k: v for k, v in user_doc.items() if k != "password_hash" and k != "_id"})
    )

@api_router.post("/auth/login", response_model=TokenResponse)
async def login(credentials: UserLogin):
    # Support login by email OR phone number
    email_or_phone = credentials.email.lower().strip()
    
    # Check if it looks like a phone number (all digits, 10+ chars)
    is_phone = email_or_phone.replace('+', '').replace(' ', '').isdigit() and len(email_or_phone.replace('+', '').replace(' ', '')) >= 10
    
    user = None
    
    if is_phone:
        # Clean phone number
        phone = email_or_phone.replace('+', '').replace(' ', '').replace('-', '')
        if phone.startswith('91') and len(phone) > 10:
            phone = phone[2:]  # Remove country code
        
        # Find user by phone - first check users table
        user = await db.users.find_one({"phone": phone})
        
        # If not found in users, check dealers table and get linked user
        if not user:
            dealer = await db.dealers.find_one({"phone": phone})
            if dealer:
                user_id = dealer.get("user_id")
                if user_id:
                    # Try as ObjectId first
                    if ObjectId.is_valid(user_id):
                        user = await db.users.find_one({"_id": ObjectId(user_id)})
                    if not user:
                        user = await db.users.find_one({"id": user_id})
    else:
        # Email login
        user = await db.users.find_one({"email": email_or_phone})
    
    if not user:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    # OTP-only dealers (imported / auto-created) have no password set. Direct
    # key access used to KeyError into a 500 here — give a clear message instead.
    if not user.get("password_hash"):
        raise HTTPException(
            status_code=400,
            detail="This account has no password set. Please sign in with OTP using your registered mobile number.",
        )
    if not verify_password(credentials.password, user["password_hash"]):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    
    # Ensure user has an id field
    if "_id" in user and "id" not in user:
        user["id"] = str(user["_id"])
    
    # Convert datetime to string if needed
    if "created_at" in user and not isinstance(user["created_at"], str):
        user["created_at"] = user["created_at"].isoformat() if user["created_at"] else None
    
    # Remove _id for response
    user_response = {k: v for k, v in user.items() if k not in ["_id", "password_hash"]}
    
    token = create_token(user["id"], user["role"])
    
    return TokenResponse(
        access_token=token,
        user=UserResponse(**user_response)
    )

@api_router.get("/auth/me", response_model=UserResponse)
async def get_me(user: dict = Depends(get_current_user)):
    # Convert datetime fields to string if needed
    user_data = {k: v for k, v in user.items() if k != "password_hash"}
    if "created_at" in user_data and isinstance(user_data["created_at"], datetime):
        user_data["created_at"] = user_data["created_at"].isoformat()
    return UserResponse(**user_data)

@api_router.patch("/auth/me", response_model=UserResponse)
async def update_me(update_data: UserUpdate, user: dict = Depends(get_current_user)):
    update_dict = {k: v for k, v in update_data.dict().items() if v is not None}
    if update_dict:
        update_dict["updated_at"] = datetime.now(timezone.utc).isoformat()
        await db.users.update_one({"id": user["id"]}, {"$set": update_dict})
    
    updated_user = await db.users.find_one({"id": user["id"]}, {"_id": 0})
    # Convert datetime fields to string if needed
    user_data = {k: v for k, v in updated_user.items() if k != "password_hash"}
    if "created_at" in user_data and isinstance(user_data["created_at"], datetime):
        user_data["created_at"] = user_data["created_at"].isoformat()
    return UserResponse(**user_data)

@api_router.post("/auth/delete-account")
async def delete_my_account(user: dict = Depends(get_current_user)):
    """Customer-initiated account deletion (Apple Guideline 5.1.1(v)).

    Soft-deletes by anonymizing PII and flagging is_deleted, rather than a hard
    delete that would orphan referential history (tickets/warranties/orders).
    The freed phone/email allow a clean re-registration; get_current_user treats
    is_deleted as 401 so the existing token dies immediately.
    """
    now = datetime.now(timezone.utc).isoformat()
    anon_email = f"deleted_{uuid.uuid4().hex}@deleted.invalid"
    await db.users.update_one(
        {"id": user["id"]},
        {"$set": {
            "is_deleted": True,
            "deleted_at": now,
            "email": anon_email,
            "phone": None,
            "first_name": "Deleted",
            "last_name": "User",
            "address": None,
            "city": None,
            "state": None,
            "pincode": None,
            "password_hash": None,
            "updated_at": now,
        }},
    )
    try:
        await db.audit_logs.insert_one({
            "id": str(uuid.uuid4()),
            "action": "account_self_deleted",
            "entity_type": "user",
            "entity_id": user["id"],
            "performed_by": user["id"],
            "performed_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
            "details": {"deleted_user_role": user.get("role")},
            "timestamp": now,
        })
    except Exception as e:
        logger.warning(f"delete-account audit log failed: {e}")
    return {"success": True, "message": "Your account has been deleted."}


class PushTokenInput(BaseModel):
    token: str
    platform: Optional[str] = None
    prefs: Optional[Dict[str, bool]] = None


class PushTokenRemove(BaseModel):
    token: str


class NotificationPrefsInput(BaseModel):
    orders: Optional[bool] = None
    tickets: Optional[bool] = None
    promotions: Optional[bool] = None


@api_router.post("/auth/push-token")
async def register_push_token(
    body: PushTokenInput, user: dict = Depends(get_current_user)
):
    """Register this device's Expo push token for the signed-in customer."""
    token = (body.token or "").strip()
    if not token:
        raise HTTPException(status_code=400, detail="token is required")
    update: dict = {"$addToSet": {"push_tokens": token}}
    sets = {"updated_at": datetime.now(timezone.utc).isoformat()}
    if body.prefs:
        for k in ("orders", "tickets", "promotions"):
            if k in body.prefs:
                sets[f"push_prefs.{k}"] = bool(body.prefs[k])
    update["$set"] = sets
    await db.users.update_one({"id": user["id"]}, update)
    return {"success": True}


@api_router.delete("/auth/push-token")
async def remove_push_token(
    body: PushTokenRemove, user: dict = Depends(get_current_user)
):
    """Drop a device token (called on sign-out)."""
    token = (body.token or "").strip()
    if token:
        await db.users.update_one(
            {"id": user["id"]}, {"$pull": {"push_tokens": token}}
        )
    return {"success": True}


@api_router.post("/auth/notification-prefs")
async def update_notification_prefs(
    body: NotificationPrefsInput, user: dict = Depends(get_current_user)
):
    """Update the customer's per-category push preferences (Settings toggles)."""
    sets = {}
    for k in ("orders", "tickets", "promotions"):
        v = getattr(body, k)
        if v is not None:
            sets[f"push_prefs.{k}"] = bool(v)
    if sets:
        sets["updated_at"] = datetime.now(timezone.utc).isoformat()
        await db.users.update_one({"id": user["id"]}, {"$set": sets})
    return {"success": True}

# ==================== OTP AUTHENTICATION ====================

# Fast2SMS Configuration
FAST2SMS_API_KEY = os.environ.get("FAST2SMS_API_KEY", "")
FAST2SMS_SENDER_ID = os.environ.get("FAST2SMS_SENDER_ID", "MUSGRD")
FAST2SMS_TEMPLATE_ID = os.environ.get("FAST2SMS_TEMPLATE_ID", "203700")
OTP_EXPIRY_MINUTES = 5

# In-memory OTP storage (use Redis in production)
otp_store = {}

# App Store review demo account: a fixed phone + OTP so Apple's reviewer can log
# in (phone-OTP login otherwise needs a real Indian SMS). Set in .env.
REVIEW_DEMO_PHONE = os.environ.get("REVIEW_DEMO_PHONE", "").strip()
REVIEW_DEMO_OTP = os.environ.get("REVIEW_DEMO_OTP", "").strip()

def generate_otp() -> str:
    """Generate a 6-digit OTP"""
    return str(random.randint(100000, 999999))

async def send_otp_via_fast2sms(phone: str, otp: str) -> bool:
    """Send OTP via Fast2SMS DLT route"""
    if not FAST2SMS_API_KEY:
        logger.error("Fast2SMS API key not configured")
        return False
    
    try:
        # Clean phone number (remove +91, spaces, etc.)
        clean_phone = phone.replace('+', '').replace(' ', '').replace('-', '')
        if clean_phone.startswith('91') and len(clean_phone) > 10:
            clean_phone = clean_phone[2:]
        
        # Fast2SMS DLT API
        url = "https://www.fast2sms.com/dev/bulkV2"
        params = {
            "authorization": FAST2SMS_API_KEY,
            "route": "dlt",
            "sender_id": FAST2SMS_SENDER_ID,
            "message": FAST2SMS_TEMPLATE_ID,
            "variables_values": otp,
            "flash": "0",
            "numbers": clean_phone
        }
        
        response = requests.get(url, params=params, timeout=30)
        result = response.json()
        
        if result.get("return") == True:
            logger.info(f"OTP sent successfully to {clean_phone[-4:].rjust(10, '*')}")
            return True
        else:
            logger.error(f"Fast2SMS error: {result}")
            return False
            
    except Exception as e:
        logger.error(f"Failed to send OTP: {str(e)}")
        return False

class OTPRequest(BaseModel):
    phone: str

class OTPVerify(BaseModel):
    phone: str
    otp: str

class ProfileUpdate(BaseModel):
    first_name: Optional[str] = None
    last_name: Optional[str] = None
    email: Optional[str] = None
    address: Optional[str] = None
    city: Optional[str] = None
    state: Optional[str] = None
    pincode: Optional[str] = None

@api_router.post("/auth/otp/send")
async def send_otp(request: OTPRequest):
    """Send OTP to phone number for login"""
    # Clean phone number
    phone = request.phone.replace('+', '').replace(' ', '').replace('-', '')
    if phone.startswith('91') and len(phone) > 10:
        phone = phone[2:]
    
    if len(phone) != 10 or not phone.isdigit():
        raise HTTPException(status_code=400, detail="Invalid phone number. Please enter 10-digit mobile number.")

    # App Store reviewer demo account — accept without SMS; the OTP is fixed.
    if REVIEW_DEMO_PHONE and phone == REVIEW_DEMO_PHONE and REVIEW_DEMO_OTP:
        return {"message": "OTP sent successfully", "phone": f"******{phone[-4:]}", "expires_in": OTP_EXPIRY_MINUTES * 60}

    # Check if user exists (in users table or has a ticket)
    user = await db.users.find_one({"phone": phone})
    
    # If not found in users, check if they have any tickets
    if not user:
        ticket = await db.tickets.find_one({"customer_phone": phone})
        if ticket:
            # Create a user account for this customer
            user_id = str(uuid.uuid4())
            now = datetime.now(timezone.utc).isoformat()
            user = {
                "id": user_id,
                "email": f"{phone}@temp.musclegrid.in",  # Temporary email
                "first_name": ticket.get("customer_name", "").split()[0] if ticket.get("customer_name") else "Customer",
                "last_name": " ".join(ticket.get("customer_name", "").split()[1:]) if ticket.get("customer_name") and len(ticket.get("customer_name", "").split()) > 1 else "",
                "phone": phone,
                "role": "customer",
                "password_hash": "",  # No password for OTP users
                "address": ticket.get("customer_address"),
                "city": ticket.get("customer_city"),
                "state": ticket.get("state"),
                "pincode": ticket.get("pincode"),
                "created_at": now,
                "updated_at": now,
                "otp_user": True,  # Flag for OTP-created users
                "profile_incomplete": True  # Flag to prompt profile completion
            }
            await db.users.insert_one(user)
            logger.info(f"Created user account for existing ticket customer: {phone}")
        else:
            raise HTTPException(
                status_code=404, 
                detail="No account found with this phone number. Please register first or contact support."
            )
    
    # Generate and store OTP
    otp = generate_otp()
    expiry = datetime.now(timezone.utc) + timedelta(minutes=OTP_EXPIRY_MINUTES)
    
    otp_store[phone] = {
        "otp": otp,
        "expiry": expiry,
        "attempts": 0
    }
    
    logger.info(f"OTP stored for phone ******{phone[-4:]}: {otp}")
    
    # Send OTP via Fast2SMS
    sent = await send_otp_via_fast2sms(phone, otp)
    
    if not sent:
        raise HTTPException(status_code=500, detail="Failed to send OTP. Please try again.")
    
    return {
        "message": "OTP sent successfully",
        "phone": f"******{phone[-4:]}",
        "expires_in": OTP_EXPIRY_MINUTES * 60
    }

@api_router.post("/auth/otp/verify", response_model=TokenResponse)
async def verify_otp(request: OTPVerify):
    """Verify OTP and login user"""
    # Clean phone number
    phone = request.phone.replace('+', '').replace(' ', '').replace('-', '')
    if phone.startswith('91') and len(phone) > 10:
        phone = phone[2:]
    
    # Clean OTP input
    otp_input = request.otp.strip()

    logger.info(f"OTP verification attempt for phone: ******{phone[-4:]}")

    # App Store reviewer demo account — fixed OTP, bypass the store entirely.
    if (REVIEW_DEMO_PHONE and REVIEW_DEMO_OTP and phone == REVIEW_DEMO_PHONE
            and otp_input == REVIEW_DEMO_OTP):
        demo = await db.users.find_one({"phone": phone, "role": "customer"})
        if not demo:
            raise HTTPException(status_code=404, detail="Demo account not provisioned")
        token = create_token(demo["id"], demo["role"])
        demo_data = {k: v for k, v in demo.items() if k not in ["password_hash", "_id"]}
        demo_data["profile_incomplete"] = False
        demo_data["missing_fields"] = []
        return TokenResponse(
            access_token=token,
            user=UserResponse(**{k: v for k, v in demo_data.items() if k in UserResponse.__fields__}),
        )

    # Check OTP store
    stored = otp_store.get(phone)
    
    if not stored:
        logger.warning(f"No OTP found in store for phone: ******{phone[-4:]}")
        raise HTTPException(status_code=400, detail="OTP expired or not requested. Please request a new OTP.")
    
    # Check expiry
    if datetime.now(timezone.utc) > stored["expiry"]:
        del otp_store[phone]
        logger.warning(f"OTP expired for phone: ******{phone[-4:]}")
        raise HTTPException(status_code=400, detail="OTP has expired. Please request a new OTP.")
    
    # Check attempts
    if stored["attempts"] >= 3:
        del otp_store[phone]
        logger.warning(f"Too many attempts for phone: ******{phone[-4:]}")
        raise HTTPException(status_code=400, detail="Too many incorrect attempts. Please request a new OTP.")
    
    # Verify OTP
    logger.info(f"Comparing OTP: stored={stored['otp']}, received={otp_input}")
    if str(stored["otp"]).strip() != str(otp_input).strip():
        stored["attempts"] += 1
        remaining = 3 - stored["attempts"]
        logger.warning(f"Invalid OTP for phone: ******{phone[-4:]}, attempts: {stored['attempts']}")
        raise HTTPException(status_code=400, detail=f"Invalid OTP. {remaining} attempts remaining.")
    
    # OTP verified - clean up and login
    logger.info(f"OTP verified successfully for phone: ******{phone[-4:]}")
    del otp_store[phone]
    
    # Get user
    user = await db.users.find_one({"phone": phone})
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Check if profile is incomplete
    profile_incomplete = False
    missing_fields = []
    
    # Check mandatory fields
    if not user.get("email") or user.get("email", "").endswith("@temp.musclegrid.in"):
        missing_fields.append("email")
        profile_incomplete = True
    if not user.get("first_name") or user.get("first_name") == "Customer":
        missing_fields.append("first_name")
        profile_incomplete = True
    if not user.get("address"):
        missing_fields.append("address")
        profile_incomplete = True
    if not user.get("city"):
        missing_fields.append("city")
        profile_incomplete = True
    if not user.get("pincode"):
        missing_fields.append("pincode")
        profile_incomplete = True
    
    # Update profile_incomplete flag in database
    if profile_incomplete != user.get("profile_incomplete", False):
        await db.users.update_one(
            {"id": user["id"]},
            {"$set": {"profile_incomplete": profile_incomplete}}
        )
    
    # Create token
    token = create_token(user["id"], user["role"])
    
    # Prepare user response (exclude sensitive fields)
    user_data = {k: v for k, v in user.items() if k not in ["password_hash", "_id"]}
    user_data["profile_incomplete"] = profile_incomplete
    user_data["missing_fields"] = missing_fields
    
    return TokenResponse(
        access_token=token,
        user=UserResponse(**{k: v for k, v in user_data.items() if k in UserResponse.__fields__})
    )

@api_router.post("/auth/otp/resend")
async def resend_otp(request: OTPRequest):
    """Resend OTP to phone number"""
    # Clean phone number
    phone = request.phone.replace('+', '').replace(' ', '').replace('-', '')
    if phone.startswith('91') and len(phone) > 10:
        phone = phone[2:]
    
    # Check if user exists
    user = await db.users.find_one({"phone": phone})
    if not user:
        raise HTTPException(status_code=404, detail="No account found with this phone number.")
    
    # Check rate limiting (only allow resend after 30 seconds)
    existing = otp_store.get(phone)
    if existing:
        time_since_sent = datetime.now(timezone.utc) - (existing["expiry"] - timedelta(minutes=OTP_EXPIRY_MINUTES))
        if time_since_sent.total_seconds() < 30:
            wait_time = int(30 - time_since_sent.total_seconds())
            raise HTTPException(status_code=429, detail=f"Please wait {wait_time} seconds before requesting a new OTP.")
    
    # Generate and store new OTP
    otp = generate_otp()
    expiry = datetime.now(timezone.utc) + timedelta(minutes=OTP_EXPIRY_MINUTES)
    
    otp_store[phone] = {
        "otp": otp,
        "expiry": expiry,
        "attempts": 0
    }
    
    # Send OTP
    sent = await send_otp_via_fast2sms(phone, otp)
    
    if not sent:
        raise HTTPException(status_code=500, detail="Failed to send OTP. Please try again.")
    
    return {
        "message": "OTP resent successfully",
        "phone": f"******{phone[-4:]}",
        "expires_in": OTP_EXPIRY_MINUTES * 60
    }

@api_router.post("/auth/complete-profile")
async def complete_profile(
    profile: ProfileUpdate,
    user: dict = Depends(get_current_user)
):
    """Complete user profile after OTP login"""
    update_data = {}
    
    if profile.first_name:
        update_data["first_name"] = profile.first_name
    if profile.last_name:
        update_data["last_name"] = profile.last_name
    if profile.email and not profile.email.endswith("@temp.musclegrid.in"):
        # Check if email already exists
        existing = await db.users.find_one({"email": profile.email.lower(), "id": {"$ne": user["id"]}})
        if existing:
            raise HTTPException(status_code=400, detail="This email is already registered to another account.")
        update_data["email"] = profile.email.lower()
    if profile.address:
        update_data["address"] = profile.address
    if profile.city:
        update_data["city"] = profile.city
    if profile.state:
        update_data["state"] = profile.state
    if profile.pincode:
        update_data["pincode"] = profile.pincode
    
    if update_data:
        update_data["updated_at"] = datetime.now(timezone.utc).isoformat()
        update_data["profile_incomplete"] = False
        
        await db.users.update_one(
            {"id": user["id"]},
            {"$set": update_data}
        )
    
    # Return updated user
    updated_user = await db.users.find_one({"id": user["id"]}, {"_id": 0, "password_hash": 0})
    
    return {
        "message": "Profile updated successfully",
        "user": updated_user
    }


