@api_router.post("/admin/dealers/create")
async def admin_create_dealer(
    data: AdminCreateDealer,
    user: dict = Depends(require_roles(["admin"]))
):
    """Admin manually creates a dealer account"""
    now = datetime.now(timezone.utc).isoformat()
    
    # Clean phone
    phone = data.phone.replace('+', '').replace(' ', '').replace('-', '')
    if phone.startswith('91') and len(phone) > 10:
        phone = phone[2:]
    
    # Check if dealer already exists (only block if already a dealer, not if they're a customer)
    existing_dealer = await db.dealers.find_one({
        "$or": [{"email": data.email.lower()}, {"phone": phone}]
    })
    if existing_dealer:
        raise HTTPException(status_code=400, detail="Dealer with this email or phone already exists")
    
    # Check if user already exists AS A DEALER (not just any user)
    # Customers can convert to dealers, so we only block if they have dealer role
    existing_user = await db.users.find_one({
        "$or": [{"email": data.email.lower()}, {"phone": phone}]
    })
    if existing_user and existing_user.get("role") == "dealer":
        raise HTTPException(status_code=400, detail="A dealer account with this email or phone already exists")
    
    # If user exists but is NOT a dealer (e.g., customer), we'll upgrade them
    # Otherwise create new user
    user_id = existing_user.get("id") if existing_user else str(uuid.uuid4())
    dealer_id = str(uuid.uuid4())
    
    # Generate password hash if password provided
    password_hash = ""
    if data.password:
        password_hash = hash_password(data.password)
    
    # Split contact person name
    name_parts = data.contact_person.split(maxsplit=1)
    first_name = name_parts[0]
    last_name = name_parts[1] if len(name_parts) > 1 else ""
    
    # Create or upgrade user
    if existing_user:
        # Upgrade existing customer/user to dealer role
        await db.users.update_one(
            {"id": user_id},
            {"$set": {
                "role": "dealer",
                "password_hash": password_hash if password_hash else existing_user.get("password_hash", ""),
                "updated_at": now,
                "converted_from_customer": True,
                "converted_at": now
            }}
        )
    else:
        # Create new user
        user_doc = {
            "id": user_id,
            "email": data.email.lower(),
            "first_name": first_name,
            "last_name": last_name,
            "phone": phone,
            "role": "dealer",
            "password_hash": password_hash,
            "address": data.address,
            "city": data.city,
            "state": data.state,
            "pincode": data.pincode,
            "created_at": now,
            "updated_at": now,
            "otp_user": not bool(data.password)  # OTP user if no password
        }
        await db.users.insert_one(user_doc)
    
    dealer_id = str(uuid.uuid4())

    # Generate dealer code
    dealer_count = await db.dealers.count_documents({})
    dealer_code = f"MG-D-{str(dealer_count + 1).zfill(4)}"

    # Firm scope — dealers carry a firm_id so their sales/inventory records are
    # visible to firm-scoped accounting. Admin may pass one; else default firm.
    dealer_firm_id = getattr(data, 'firm_id', None) or await get_default_firm_id()

    # Create dealer profile
    dealer_doc = {
        "id": dealer_id,
        "user_id": user_id,
        "dealer_code": dealer_code,
        "firm_id": dealer_firm_id,
        "firm_name": data.firm_name,
        "contact_person": data.contact_person,
        "email": data.email.lower(),
        "phone": phone,
        "gst_number": data.gst_number,
        "address": data.address,
        "city": data.city,
        "state": data.state,
        "pincode": data.pincode,
        "tier": data.tier,
        "status": "approved",  # Admin-created dealers are approved immediately
        "security_deposit_status": "approved",
        "security_deposit_exempt": True,  # Admin-created dealers are deposit-exempt by admin decision
        "security_deposit_exempt_reason": "Directly onboarded by admin",
        "security_deposit_amount": 100000,  # Default 1 lakh
        "credit_limit": getattr(data, 'credit_limit', 0) or 0,  # 0 = unlimited
        "lifetime_purchases": 0,
        "created_at": now,
        "updated_at": now,
        "created_by": user["id"],
        "created_by_admin": True,
        "discount_percent": data.discount_percent if hasattr(data, 'discount_percent') and data.discount_percent else 15
    }
    await db.dealers.insert_one(dealer_doc)
    
    # Create party record so ledger entries work immediately
    party_doc = {
        "id": str(uuid.uuid4()),
        "name": data.firm_name,
        "party_type": "dealer",
        "dealer_id": dealer_id,
        "phone": phone,
        "email": data.email.lower(),
        "gst_number": data.gst_number or None,
        "address": data.address or None,
        "current_balance": 0,
        "opening_balance": 0,
        "is_active": True,
        "created_at": now,
        "updated_at": now
    }
    await db.parties.insert_one(party_doc)
    
    logger.info(f"Admin {user['email']} created dealer: {data.firm_name} ({dealer_code})")
    
    return {
        "message": "Dealer created successfully",
        "dealer_id": dealer_id,
        "dealer_code": dealer_code,
        "user_id": user_id,
        "login_method": "otp" if not data.password else "password"
    }

# ==================== TICKET ENDPOINTS ====================

@api_router.get("/tickets/check-duplicate")
async def check_duplicate_ticket(
    serial_number: Optional[str] = None,
    order_id: Optional[str] = None,
    user: dict = Depends(get_current_user)
):
    """Check if customer has an existing open ticket for the same product"""
    if not serial_number and not order_id:
        return {"has_duplicate": False}
    
    cust_id = user["id"] if user["role"] == "customer" else None
    if not cust_id:
        return {"has_duplicate": False}
    
    open_statuses = ["new_request", "call_support_followup", "escalated_to_supervisor", 
                    "supervisor_followup", "hardware_service", "awaiting_label", 
                    "label_uploaded", "pickup_scheduled", "received_at_factory", 
                    "in_repair", "repair_completed", "service_invoice_added", "ready_for_dispatch"]
    
    query = {"customer_id": cust_id, "status": {"$in": open_statuses}}
    
    if serial_number:
        query["serial_number"] = serial_number
        existing = await db.tickets.find_one(query, {"_id": 0, "ticket_number": 1, "status": 1})
        if existing:
            return {
                "has_duplicate": True,
                "ticket_number": existing["ticket_number"],
                "status": existing["status"],
                "message": f"You already have an open ticket ({existing['ticket_number']}) for this serial number."
            }
    
    if order_id:
        query.pop("serial_number", None)
        query["order_id"] = order_id
        existing = await db.tickets.find_one(query, {"_id": 0, "ticket_number": 1, "status": 1})
        if existing:
            return {
                "has_duplicate": True,
                "ticket_number": existing["ticket_number"],
                "status": existing["status"],
                "message": f"You already have an open ticket ({existing['ticket_number']}) for this order."
            }
    
    return {"has_duplicate": False}

# File-path fields on a ticket that hold a stored "/api/files/..." path.
TICKET_FILE_FIELDS = (
    "invoice_file", "issue_photo", "jobcard_path",
    "pickup_label", "return_label", "service_invoice",
)


def sign_ticket_file_urls(ticket: dict, user_id: str | None = None) -> dict:
    """Replace stored "/api/files/..." paths on a ticket with short-lived
    signed URLs so the CRM can open them via a plain browser link (no Bearer
    token). Stored DB values are left untouched — signing happens on read."""
    if not ticket:
        return ticket
    for field in TICKET_FILE_FIELDS:
        val = ticket.get(field)
        if isinstance(val, str) and val.startswith("/api/files/"):
            rel = val.split("?", 1)[0][len("/api/files/"):].strip("/")
            if rel:
                ticket[field] = make_signed_file_url(rel, user_id=user_id)
    return ticket


def sign_file_urls_deep(obj, user_id: str | None = None):
    """Recursively replace every "/api/files/..." string anywhere in a dict/list
    with a signed URL, so non-ticket documents (dispatches, purchases, sales
    invoices) open via plain browser links too. Only strings under /api/files/
    are touched; already-signed values are re-signed cleanly. Mutates in place."""
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, str) and v.startswith("/api/files/"):
                rel = v.split("?", 1)[0][len("/api/files/"):].strip("/")
                if rel:
                    obj[k] = make_signed_file_url(rel, user_id=user_id)
            elif isinstance(v, (dict, list)):
                sign_file_urls_deep(v, user_id)
    elif isinstance(obj, list):
        for item in obj:
            if isinstance(item, (dict, list)):
                sign_file_urls_deep(item, user_id)
    return obj


async def _auto_assign_agent(role: str, firm_id: str = None):
    """Pick the least-loaded ACTIVE user of a role (fewest open tickets) so new tickets always get an
    owner and load is balanced. Prefers an agent of the ticket's firm when firm-scoped agents exist.
    Returns (user_id, display_name) or (None, None) if no agent of that role exists."""
    open_st = ["new_request", "call_support_followup", "escalated_to_supervisor", "supervisor_followup",
               "hardware_service", "awaiting_label", "label_uploaded", "pickup_scheduled",
               "received_at_factory", "in_repair", "repair_completed", "service_invoice_added",
               "ready_for_dispatch", "assigned_to_technician", "in_progress", "pending_parts"]
    q = {"role": role, "is_active": {"$ne": False}}
    agents = [u async for u in db.users.find(q, {"_id": 0, "id": 1, "first_name": 1, "last_name": 1, "firm_id": 1})]
    if firm_id:
        same = [a for a in agents if a.get("firm_id") == firm_id]
        if same:
            agents = same
    if not agents:
        return None, None
    best, best_load = None, None
    for a in agents:
        load = await db.tickets.count_documents({"assigned_to": a["id"], "status": {"$in": open_st}})
        if best_load is None or load < best_load:
            best, best_load = a, load
    name = f"{best.get('first_name', '')} {best.get('last_name', '')}".strip()
    return best["id"], (name or "Agent")


@api_router.post("/tickets")
async def create_ticket(
    background_tasks: BackgroundTasks,
    device_type: str = Form(...),
    issue_description: str = Form(...),
    product_name: Optional[str] = Form(None),
    serial_number: Optional[str] = Form(None),
    invoice_number: Optional[str] = Form(None),
    order_id: Optional[str] = Form(None),
    customer_id: Optional[str] = Form(None),
    category: Optional[str] = Form(None),
    invoice_file: Optional[UploadFile] = File(None),
    issue_photo: Optional[UploadFile] = File(None),
    user: dict = Depends(get_current_user)
):
    """Create support ticket - Customer or Agent.

    `category` is an optional intake tag (e.g. "warranty_claim") used to mark
    tickets raised as warranty claims from the app. It does not change the
    support_type channel or routing.
    """
    now = datetime.now(timezone.utc)
    ticket_id = str(uuid.uuid4())
    ticket_number = await generate_ticket_number()
    
    # Determine customer info
    if user["role"] == "customer":
        customer = user
        cust_id = user["id"]
    elif customer_id and user["role"] in ["call_support", "admin"]:
        customer = await db.users.find_one({"id": customer_id}, {"_id": 0})
        if not customer:
            raise HTTPException(status_code=404, detail="Customer not found")
        cust_id = customer_id
    else:
        customer = user
        cust_id = user["id"]
    
    # DUPLICATE TICKET PREVENTION
    # Check if customer already has an open ticket for the same serial number or order_id
    if serial_number or order_id:
        open_statuses = ["new_request", "call_support_followup", "escalated_to_supervisor", 
                        "supervisor_followup", "hardware_service", "awaiting_label", 
                        "label_uploaded", "pickup_scheduled", "received_at_factory", 
                        "in_repair", "repair_completed", "service_invoice_added", "ready_for_dispatch"]
        
        duplicate_query = {
            "customer_id": cust_id,
            "status": {"$in": open_statuses}
        }
        
        # Check by serial number or order_id
        if serial_number:
            duplicate_query["serial_number"] = serial_number
            existing = await db.tickets.find_one(duplicate_query, {"_id": 0})
            if existing:
                raise HTTPException(
                    status_code=400, 
                    detail=f"You already have an open ticket ({existing['ticket_number']}) for this serial number. Please wait for it to be resolved."
                )
        
        if order_id:
            duplicate_query.pop("serial_number", None)
            duplicate_query["order_id"] = order_id
            existing = await db.tickets.find_one(duplicate_query, {"_id": 0})
            if existing:
                raise HTTPException(
                    status_code=400, 
                    detail=f"You already have an open ticket ({existing['ticket_number']}) for this order. Please wait for it to be resolved."
                )
    
    # Handle invoice file upload
    invoice_path = None
    if invoice_file:
        try:
            content = await invoice_file.read()
            relative_path, storage_type = await storage_upload(
                file_data=content,
                folder="invoices",
                original_filename=invoice_file.filename,
                filename_prefix=ticket_id
            )
            invoice_path = f"/api/files/{relative_path}"
        except StorageError as e:
            logger.error(f"Failed to upload ticket invoice: {str(e)}")
            raise HTTPException(status_code=500, detail=f"File upload failed: {str(e)}")

    # Handle issue photo upload — a photo of the problem, kept separate from
    # the invoice document and stored in the tickets folder.
    issue_photo_path = None
    if issue_photo:
        try:
            photo_content = await issue_photo.read()
            relative_path, storage_type = await storage_upload(
                file_data=photo_content,
                folder="tickets",
                original_filename=issue_photo.filename,
                filename_prefix=f"{ticket_id}_photo"
            )
            issue_photo_path = f"/api/files/{relative_path}"
        except StorageError as e:
            logger.error(f"Failed to upload ticket issue photo: {str(e)}")
            raise HTTPException(status_code=500, detail=f"Photo upload failed: {str(e)}")
    
    # Calculate SLA
    sla_due = calculate_sla_due("phone", now)

    # Attribute the ticket to the firm that sold the unit, where derivable.
    # None = unattributed (treated as global by the firm-scoped queue).
    firm_id = await derive_ticket_firm_id(order_id, invoice_number, serial_number)

    # Auto-assign at intake so the ticket has an OWNER from minute one (root-cause fix for the
    # 'unassigned breached' pile). New tickets go to the least-loaded first-line agent.
    intake_role = os.environ.get("TICKET_INTAKE_ROLE", "call_support")
    auto_assignee_id, auto_assignee_name = await _auto_assign_agent(intake_role, firm_id)

    ticket_doc = {
        "id": ticket_id,
        "ticket_number": ticket_number,
        "firm_id": firm_id,
        "customer_id": cust_id,
        "customer_name": f"{customer['first_name']} {customer['last_name']}",
        "customer_phone": customer["phone"],
        "customer_email": customer["email"],
        "customer_address": customer.get("address"),
        "customer_city": customer.get("city"),
        "device_type": device_type,
        "product_name": product_name,
        "serial_number": serial_number,
        "invoice_number": invoice_number,
        "order_id": order_id,
        "invoice_file": invoice_path,
        "issue_photo": issue_photo_path,
        "issue_description": issue_description,
        "support_type": "phone",  # Default to phone support
        "category": category,  # optional intake tag e.g. "warranty_claim"
        "status": "new_request",
        "diagnosis": None,
        "agent_notes": None,
        "repair_notes": None,
        "assigned_to": auto_assignee_id,
        "assigned_to_name": auto_assignee_name,
        "auto_assigned": bool(auto_assignee_id),
        "pickup_label": None,
        "pickup_courier": None,
        "pickup_tracking": None,
        "return_label": None,
        "return_courier": None,
        "return_tracking": None,
        "service_charges": None,
        "service_invoice": None,
        "sla_due": sla_due.isoformat(),
        "sla_breached": False,
        "created_by": user["id"],
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
        "closed_at": None,
        "received_at": None,
        "repaired_at": None,
        "dispatched_at": None,
        "history": [{
            "action": "Ticket created",
            "by": f"{user['first_name']} {user['last_name']}",
            "by_id": user["id"],
            "by_role": user["role"],
            "timestamp": now.isoformat(),
            "details": {"status": "new_request"}
        }] + ([{
            "action": f"Auto-assigned to {auto_assignee_name}",
            "by": "System", "by_id": "system", "by_role": "system",
            "timestamp": now.isoformat(),
            "details": {"assigned_to": auto_assignee_id, "rule": f"least-loaded {intake_role}"}
        }] if auto_assignee_id else [])
    }

    await db.tickets.insert_one(ticket_doc)

    # Notify the auto-assigned agent so they pick it up immediately.
    if auto_assignee_id:
        asyncio.create_task(create_notification(
            title="🎫 New ticket assigned to you",
            message=f"{ticket_number} — {device_type} — {ticket_doc['customer_name']}",
            notification_type="info", link=f"/tickets?search={ticket_number}", priority="normal",
            target_user_ids=[auto_assignee_id], created_by_name="Auto-assign", data={"ticket_id": ticket_id}))

    # ========== AUTO-LINK to recent inbound call ==========
    # If this agent answered a call from this customer in the last 10 minutes
    # and that call isn't yet linked to a ticket, link it now. This makes
    # first-call-resolution measurable.
    try:
        cust_phone = (customer.get("phone") or "").strip()
        if cust_phone:
            p10 = "".join(ch for ch in cust_phone if ch.isdigit())[-10:]
            if len(p10) == 10:
                ten_min_ago = (now - timedelta(minutes=10)).isoformat()
                recent_call = await db.smartflo_calls.find_one(
                    {
                        "$or": [
                            {"caller_id_number": {"$regex": p10 + "$"}},
                            {"caller_phone": {"$regex": p10 + "$"}},
                        ],
                        "received_at": {"$gte": ten_min_ago},
                        "linked_ticket_id": {"$in": [None, "", False]},
                    },
                    sort=[("received_at", -1)]
                )
                if recent_call:
                    await db.smartflo_calls.update_one(
                        {"_id": recent_call["_id"]},
                        {"$set": {
                            "linked_ticket_id": ticket_id,
                            "linked_ticket_number": ticket_number,
                            "linked_at": now.isoformat(),
                            "linked_by": user.get("email") or user.get("id"),
                        }}
                    )
                    logger.info(f"Auto-linked call {recent_call.get('id')} → ticket {ticket_number}")
    except Exception as e:
        logger.warning(f"Auto-link call→ticket failed: {e}")

    # Generate and upload jobcard PDF to NAS
    try:
        invoice_data = None
        if invoice_file:
            await invoice_file.seek(0)
            invoice_data = await invoice_file.read()

        jobcard_path = await create_and_upload_jobcard(ticket_doc, invoice_data)
        
        # Update ticket with jobcard path
        await db.tickets.update_one(
            {"id": ticket_id},
            {"$set": {"jobcard_path": f"/api/files/{jobcard_path}"}}
        )
        ticket_doc["jobcard_path"] = f"/api/files/{jobcard_path}"
        logger.info(f"Jobcard generated for ticket {ticket_number}: {jobcard_path}")
    except Exception as e:
        logger.error(f"Failed to generate jobcard for ticket {ticket_number}: {str(e)}")
        # Don't fail ticket creation if jobcard generation fails
    
    # Create notification for new ticket
    await create_notification(
        title="New Ticket Created",
        message=f"Ticket {ticket_number} created for {ticket_doc['customer_name']} ({ticket_doc['support_type']})",
        notification_type="info",
        link=f"/support/ticket/{ticket_id}",
        target_roles=["call_support", "admin", "supervisor"],
        priority="normal"
    )
    
    # Send email to customer
    if ticket_doc.get("customer_email"):
        asyncio.create_task(send_ticket_email(ticket_doc, "created"))
    
    # Remove _id before returning
    ticket_doc.pop("_id", None)
    return ticket_doc


@api_router.post("/admin/sla/check-breaches")
async def trigger_sla_breach_check(
    user: dict = Depends(require_roles(["admin", "supervisor"]))
):
    """
    H4 FIX: Manually trigger SLA breach check and auto-escalation.
    Can also be called by a scheduled job.
    """
    escalated_count = await check_and_escalate_sla_breaches()
    return {
        "message": f"SLA breach check completed. {escalated_count} tickets escalated.",
        "escalated_count": escalated_count
    }


@api_router.get("/admin/sla/breached-tickets")
async def get_sla_breached_tickets(
    user: dict = Depends(require_roles(["admin", "supervisor"]))
):
    """
    H4 FIX: Get all currently SLA-breached tickets for dashboard display.
    """
    now_iso = datetime.now(timezone.utc).isoformat()
    # Real statuses from TICKET_STATUSES — the previous list was largely
    # phantom names that never appear in DB, so SLA breach detection silently
    # never fired for tickets in call_support_followup/in_repair/etc.
    open_statuses = [
        "new_request", "call_support_followup", "escalated_to_supervisor",
        "supervisor_followup", "hardware_service", "awaiting_label",
        "label_uploaded", "pickup_scheduled", "received_at_factory",
        "in_repair", "repair_completed", "service_invoice_added",
        "ready_for_dispatch", "in_progress", "assigned_to_technician",
        "pending_parts", "pending_customer", "customer_escalated",
    ]
    
    breached = await db.tickets.find({
        "status": {"$in": open_statuses},
        "sla_due": {"$lt": now_iso}
    }, {"_id": 0}).sort("sla_due", 1).to_list(100)
    
    # Calculate hours overdue for each
    for ticket in breached:
        if ticket.get("sla_due"):
            try:
                sla_due = datetime.fromisoformat(ticket["sla_due"].replace("Z", "+00:00"))
                hours_overdue = (datetime.now(timezone.utc) - sla_due).total_seconds() / 3600
                ticket["hours_overdue"] = round(hours_overdue, 1)
            except:
                ticket["hours_overdue"] = 0
    
    return {
        "count": len(breached),
        "tickets": breached
    }


@api_router.get("/tickets")
async def list_tickets(
    search: Optional[str] = None,
    status: Optional[str] = None,
    support_type: Optional[str] = None,
    device_type: Optional[str] = None,
    assigned_to: Optional[str] = None,
    sla_breached: Optional[bool] = None,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    view_as: Optional[str] = None,  # Allow admin to view as specific role
    limit: int = 100,
    skip: int = 0,
    user: dict = Depends(get_current_user)
):
    """List tickets with filters"""
    query = {}
    
    # Determine effective role (admin can view as other roles)
    effective_role = user["role"]
    if user["role"] == "admin" and view_as:
        effective_role = view_as
    
    # Role-based filtering. Default is "deny" — we explicitly enumerate every
    # role that may read tickets, so adding a new role won't accidentally leak
    # the full collection like the previous fall-through did (dealer / gate /
    # dispatcher / supervisor / technician saw everything).
    if effective_role == "customer":
        query["customer_id"] = user["id"]
    elif effective_role in ("service_agent", "technician"):
        if user["role"] != "admin":
            query["assigned_to"] = user["id"]
    elif effective_role == "call_support":
        # Call support sees all tickets — visibility is the job.
        pass
    elif effective_role == "supervisor":
        # Supervisor reviews escalations and team performance.
        pass
    elif effective_role == "accountant":
        query["status"] = {"$in": [
            "hardware_service", "awaiting_label", "label_uploaded",
            "repair_completed", "service_invoice_added",
        ]}
        # Firm scope (soft): an accountant tied to a firm sees that firm's tickets
        # PLUS any ticket we couldn't attribute to a firm (firm_id null/missing —
        # {"firm_id": None} matches both in Mongo). We deliberately do NOT hard-
        # filter: most legacy tickets carry no firm_id and a strict filter would
        # empty the queue. Uses the real caller's scope, so admin (view_as) and
        # accountants with no firm_id remain unscoped (see all). Wrapped in $and so
        # it composes with the search $or below instead of clobbering it.
        acct_firm = get_user_firm_scope(user)
        if acct_firm:
            query.setdefault("$and", []).append(
                {"$or": [{"firm_id": acct_firm}, {"firm_id": None}]}
            )
    elif effective_role == "dispatcher":
        # Dispatchers only need to see tickets reaching dispatch.
        query["status"] = {"$in": [
            "awaiting_label", "label_uploaded", "ready_for_dispatch",
            "dispatched", "delivered",
        ]}
    elif effective_role == "gate":
        # Gate operators need to see in-transit / arriving tickets only.
        query["status"] = {"$in": [
            "dispatched", "label_uploaded", "received_at_factory",
        ]}
    elif effective_role == "dealer":
        # Dealers can only see tickets they raised.
        query["dealer_id"] = user["id"]
    elif effective_role == "admin":
        pass  # full visibility
    else:
        raise HTTPException(status_code=403, detail="Role not permitted to read tickets")
    
    # Apply filters
    if search:
        query["$or"] = [
            {"ticket_number": {"$regex": search, "$options": "i"}},
            {"customer_name": {"$regex": search, "$options": "i"}},
            {"customer_phone": {"$regex": search, "$options": "i"}},
            {"customer_email": {"$regex": search, "$options": "i"}},
            {"serial_number": {"$regex": search, "$options": "i"}},
            {"invoice_number": {"$regex": search, "$options": "i"}},
            {"order_id": {"$regex": search, "$options": "i"}}
        ]
    
    if status:
        query["status"] = status
    if support_type:
        query["support_type"] = support_type
    if device_type:
        query["device_type"] = device_type
    if assigned_to:
        query["assigned_to"] = assigned_to
    if sla_breached is not None:
        query["sla_breached"] = sla_breached
    
    if from_date:
        query["created_at"] = {"$gte": from_date}
    if to_date:
        if "created_at" in query:
            query["created_at"]["$lte"] = to_date
        else:
            query["created_at"] = {"$lte": to_date}
    
    tickets = await db.tickets.find(query, {"_id": 0}).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    
    # Update SLA breach status and convert datetime objects to strings
    for ticket in tickets:
        # Convert datetime objects to ISO strings for JSON serialization
        for key in ["created_at", "updated_at", "closed_at", "received_at", "repaired_at", "dispatched_at", "sla_due"]:
            if key in ticket and ticket[key] is not None:
                if hasattr(ticket[key], 'isoformat'):
                    ticket[key] = ticket[key].isoformat()

        if ticket.get("sla_due"):
            try:
                sla_due = datetime.fromisoformat(str(ticket["sla_due"]).replace('Z', '+00:00'))
                ticket["sla_breached"] = is_sla_breached(sla_due, ticket.get("status", ""))
            except:
                pass

        # Sign file URLs so they open from the CRM via a plain link (no Bearer token).
        sign_ticket_file_urls(ticket, user_id=user["id"])
    
    return tickets

@api_router.get("/tickets/{ticket_id}")
async def get_ticket(ticket_id: str, user: dict = Depends(get_current_user)):
    """Get ticket details"""
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")

    # Permission check — same allow-list applied on the list endpoint.
    role = user["role"]
    if role == "customer" and ticket.get("customer_id") != user["id"]:
        raise HTTPException(status_code=403, detail="Access denied")
    if role == "dealer" and ticket.get("dealer_id") != user["id"]:
        raise HTTPException(status_code=403, detail="Access denied")
    if role in ("service_agent", "technician") and ticket.get("assigned_to") != user["id"]:
        # Technicians can only read their own assignments.
        raise HTTPException(status_code=403, detail="Access denied")
    if role not in (
        "admin", "supervisor", "call_support", "accountant", "dispatcher",
        "gate", "customer", "dealer", "service_agent", "technician",
    ):
        raise HTTPException(status_code=403, detail="Role not permitted")
    
    # Convert datetime objects to ISO strings for JSON serialization
    for key in ["created_at", "updated_at", "closed_at", "received_at", "repaired_at", "dispatched_at", "sla_due"]:
        if key in ticket and ticket[key] is not None:
            if hasattr(ticket[key], 'isoformat'):
                ticket[key] = ticket[key].isoformat()
    
    # Convert datetime in history entries
    if "history" in ticket:
        for entry in ticket["history"]:
            if "timestamp" in entry and hasattr(entry["timestamp"], 'isoformat'):
                entry["timestamp"] = entry["timestamp"].isoformat()
    
    # Update SLA breach status
    if ticket.get("sla_due"):
        try:
            sla_due = datetime.fromisoformat(str(ticket["sla_due"]).replace('Z', '+00:00'))
            ticket["sla_breached"] = is_sla_breached(sla_due, ticket.get("status", ""))
        except:
            pass

    # Sign file URLs so they open from the CRM via a plain link (no Bearer token).
    sign_ticket_file_urls(ticket, user_id=user["id"])

    return ticket

@api_router.patch("/tickets/{ticket_id}")
async def update_ticket(
    ticket_id: str,
    update_data: TicketUpdate,
    user: dict = Depends(require_roles(["call_support", "supervisor", "service_agent", "accountant", "admin"]))
):
    """Update ticket - Support agents, Supervisor, Technicians, Accountants"""
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    now = datetime.now(timezone.utc)
    update_dict = {k: v for k, v in update_data.dict().items() if v is not None}
    update_dict["updated_at"] = now.isoformat()
    
    # Track status changes
    old_status = ticket["status"]
    new_status = update_dict.get("status", old_status)
    
    # ====== STATE-MACHINE VALIDATION: Use centralized StateMachine ======
    if new_status != old_status:
        is_admin = user.get("role") == "admin"
        is_valid, error_msg = StateMachine.validate_transition("ticket", old_status, new_status, is_admin)
        if not is_valid:
            raise HTTPException(status_code=400, detail=error_msg)
    
    # Handle assigned_to name
    if "assigned_to" in update_dict:
        assignee = await db.users.find_one({"id": update_dict["assigned_to"]}, {"_id": 0})
        if assignee:
            update_dict["assigned_to_name"] = f"{assignee['first_name']} {assignee['last_name']}"
    
    # Handle status-specific timestamps
    if new_status == "closed" or new_status == "closed_by_agent" or new_status == "resolved_on_call":
        update_dict["closed_at"] = now.isoformat()
    
    await db.tickets.update_one({"id": ticket_id}, {"$set": update_dict})
    
    # Add to history
    if old_status != new_status:
        await add_ticket_history(ticket_id, f"Status changed from {old_status} to {new_status}", user, {"old_status": old_status, "new_status": new_status})
        
        # Send email on status change
        updated_ticket_for_email = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
        if updated_ticket_for_email and updated_ticket_for_email.get("customer_email"):
            if new_status in ["closed", "closed_by_agent", "resolved_on_call"]:
                asyncio.create_task(send_ticket_email(updated_ticket_for_email, "closed"))
                # Send feedback request after 2 hours
                asyncio.create_task(send_ticket_email(updated_ticket_for_email, "feedback"))
            else:
                asyncio.create_task(send_ticket_email(updated_ticket_for_email, "status_update", old_status))
    
    if update_data.agent_notes:
        await add_ticket_history(ticket_id, "Agent notes updated", user)
    
    updated_ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    return updated_ticket

@api_router.post("/tickets/{ticket_id}/escalate-to-supervisor")
async def escalate_to_supervisor(
    ticket_id: str,
    notes: str = Form(...),
    user: dict = Depends(require_roles(["call_support", "admin"]))
):
    """Support agent escalates ticket to supervisor - notes must be 100+ chars"""
    if len(notes) < MIN_NOTES_LENGTH:
        raise HTTPException(status_code=400, detail=f"Notes must be at least {MIN_NOTES_LENGTH} characters")
    
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    now = datetime.now(timezone.utc)
    sla_due = now + timedelta(hours=SLA_CONFIG["supervisor"])
    
    await db.tickets.update_one(
        {"id": ticket_id},
        {"$set": {
            "status": "escalated_to_supervisor",
            "escalation_notes": notes,
            "escalated_by": user["id"],
            "escalated_by_name": f"{user['first_name']} {user['last_name']}",
            "escalated_at": now.isoformat(),
            "sla_due": sla_due.isoformat(),
            "updated_at": now.isoformat()
        }}
    )
    
    await add_ticket_history(ticket_id, "Escalated to supervisor", user, {"notes": notes})

    asyncio.create_task(post_system_message(
        "support",
        f"🚩 {ticket.get('ticket_number')} escalated to supervisor by {user['first_name']} {user['last_name']} — {notes[:140]}",
        {"ref": ticket.get("ticket_number")}))

    return {"message": "Ticket escalated to supervisor", "new_status": "escalated_to_supervisor"}

@api_router.post("/tickets/{ticket_id}/supervisor-action")
async def supervisor_action(
    ticket_id: str,
    action: str = Form(...),  # resolve, spare_dispatch, reverse_pickup, in_process, close_ticket
    notes: str = Form(...),
    sku: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["supervisor", "admin"]))
):
    """Supervisor takes action on escalated ticket - notes must be 100+ chars"""
    if len(notes) < MIN_NOTES_LENGTH:
        raise HTTPException(status_code=400, detail=f"Notes must be at least {MIN_NOTES_LENGTH} characters")
    
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    now = datetime.now(timezone.utc)
    
    if action == "in_process":
        # Mark ticket as in process - needs followup
        sla_due = now + timedelta(hours=SLA_CONFIG["supervisor"])
        await db.tickets.update_one(
            {"id": ticket_id},
            {"$set": {
                "status": "supervisor_followup",
                "supervisor_notes": notes,
                "sla_due": sla_due.isoformat(),
                "updated_at": now.isoformat()
            }}
        )
        await add_ticket_history(ticket_id, "Marked in-process by supervisor (followup required)", user, {"notes": notes})
        return {"message": "Ticket marked in-process - followup required"}
    
    elif action == "close_ticket":
        # Supervisor closes ticket
        await db.tickets.update_one(
            {"id": ticket_id},
            {"$set": {
                "status": "closed",
                "supervisor_notes": notes,
                "closed_by": user["id"],
                "closed_by_name": f"{user['first_name']} {user['last_name']}",
                "closed_at": now.isoformat(),
                "updated_at": now.isoformat()
            }}
        )
        await add_ticket_history(ticket_id, "Ticket closed by supervisor", user, {"notes": notes})
        return {"message": "Ticket closed by supervisor"}
    
    elif action == "resolve":
        await db.tickets.update_one(
            {"id": ticket_id},
            {"$set": {
                "status": "resolved_on_call",
                "supervisor_notes": notes,
                "resolved_by": user["id"],
                "resolved_by_name": f"{user['first_name']} {user['last_name']}",
                "closed_at": now.isoformat(),
                "updated_at": now.isoformat()
            }}
        )
        await add_ticket_history(ticket_id, "Resolved by supervisor", user, {"notes": notes})
        return {"message": "Ticket resolved by supervisor"}
    
    elif action in ["spare_dispatch", "reverse_pickup"]:
        sla_due = now + timedelta(hours=SLA_CONFIG["accountant"])
        
        await db.tickets.update_one(
            {"id": ticket_id},
            {"$set": {
                # reverse_pickup → awaiting_label: the accountant must produce/upload a
                # pickup label next, which is exactly what "awaiting_label" means.
                # spare_dispatch → hardware_service: no pickup label is involved (a new
                # unit ships out), so it waits in the generic hardware queue for the
                # accountant to raise the outbound dispatch. (These were previously
                # swapped, which mislabelled spare dispatches and leaked them into the
                # dispatcher's awaiting_label queue.)
                "status": "awaiting_label" if action == "reverse_pickup" else "hardware_service",
                "support_type": "hardware",
                "supervisor_notes": notes,
                "supervisor_action": action,
                "supervisor_sku": sku,
                "sla_due": sla_due.isoformat(),
                "updated_at": now.isoformat()
            }}
        )
        
        action_name = "Reverse pickup requested" if action == "reverse_pickup" else "Spare dispatch requested"
        await add_ticket_history(ticket_id, f"Supervisor: {action_name}", user, {"notes": notes, "sku": sku})

        emoji = "🔄" if action == "reverse_pickup" else "📦"
        asyncio.create_task(post_system_message(
            "service",
            f"{emoji} {action_name}: {ticket.get('ticket_number')} ({ticket.get('customer_name','')}) — sent to accountant by {user['first_name']} {user['last_name']}",
            {"ref": ticket.get("ticket_number")}))

        return {"message": f"{action_name} - sent to accountant"}
    
    else:
        raise HTTPException(status_code=400, detail="Invalid action")

@api_router.post("/tickets/{ticket_id}/customer-escalate")
async def customer_escalate_ticket(
    ticket_id: str,
    user: dict = Depends(get_current_user)
):
    """Customer escalates ticket if no update for 48 hours"""
    if user["role"] != "customer":
        raise HTTPException(status_code=403, detail="Only customers can escalate")
    
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    if ticket.get("customer_id") != user["id"]:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Check if ticket is already resolved
    if ticket["status"] in ["closed", "closed_by_agent", "resolved_on_call", "delivered"]:
        raise HTTPException(status_code=400, detail="Ticket is already resolved")
    
    # Check if 48 hours have passed since last update
    last_update = datetime.fromisoformat(ticket["updated_at"].replace('Z', '+00:00'))
    hours_since_update = (datetime.now(timezone.utc) - last_update).total_seconds() / 3600
    
    if hours_since_update < 48:
        remaining = int(48 - hours_since_update)
        raise HTTPException(status_code=400, detail=f"You can escalate after {remaining} hours of no update")
    
    now = datetime.now(timezone.utc)
    
    await db.tickets.update_one(
        {"id": ticket_id},
        {"$set": {
            "status": "customer_escalated",
            "customer_escalated": True,
            "customer_escalated_at": now.isoformat(),
            "sla_breached": True,
            "updated_at": now.isoformat()
        }}
    )
    
    await add_ticket_history(ticket_id, "CUSTOMER ESCALATED - Missed SLA, needs immediate action", user)
    
    return {"message": "Ticket escalated to supervisor for immediate attention"}


@api_router.post("/tickets/{ticket_id}/regenerate-jobcard")
async def regenerate_ticket_jobcard(
    ticket_id: str,
    user: dict = Depends(require_roles(["admin", "supervisor", "accountant"]))
):
    """Regenerate jobcard PDF for an existing ticket"""
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    # Get invoice data if exists
    invoice_data = None
    invoice_path = ticket.get("invoice_file")
    if invoice_path:
        try:
            # Extract relative path from /api/files/...
            relative_path = invoice_path.replace("/api/files/", "")
            invoice_data = await storage_download(relative_path)
        except Exception as e:
            logger.warning(f"Could not load invoice for jobcard: {e}")
    
    try:
        jobcard_path = await create_and_upload_jobcard(ticket, invoice_data)
        
        # Update ticket with new jobcard path
        await db.tickets.update_one(
            {"id": ticket_id},
            {"$set": {"jobcard_path": f"/api/files/{jobcard_path}"}}
        )
        
        return {
            "message": "Jobcard regenerated successfully",
            "jobcard_path": f"/api/files/{jobcard_path}"
        }
    except Exception as e:
        logger.error(f"Failed to regenerate jobcard: {str(e)}")
        raise HTTPException(status_code=500, detail=f"Failed to generate jobcard: {str(e)}")

