@api_router.post("/tickets/{ticket_id}/ai-suggest")
async def ticket_ai_suggest(
    ticket_id: str,
    force: bool = Query(False),
    user: dict = Depends(require_roles(["call_support", "supervisor", "admin"]))
):
    """
    Return an AI-generated next-best-action for this ticket. Cached on the
    ticket for an hour unless `force=true`.
    """
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")

    cached = ticket.get("ai_suggestion") or {}
    cached_at = cached.get("generated_at")
    if not force and cached_at:
        try:
            then = datetime.fromisoformat(cached_at.replace("Z", "+00:00"))
            if (datetime.now(timezone.utc) - then).total_seconds() < AI_SUGGEST_CACHE_HOURS * 3600:
                return {"cached": True, "suggestion": cached.get("suggestion")}
        except Exception:
            pass

    result = await _generate_ticket_ai_suggestion(ticket)
    if not result.get("ok"):
        raise HTTPException(status_code=502, detail=result.get("error") or "AI suggest failed")

    suggestion = result["suggestion"]
    now_iso = datetime.now(timezone.utc).isoformat()
    await db.tickets.update_one(
        {"id": ticket_id},
        {"$set": {"ai_suggestion": {
            "suggestion": suggestion,
            "generated_at": now_iso,
            "generated_by": user.get("email") or user.get("id"),
        }}}
    )
    return {"cached": False, "suggestion": suggestion, "generated_at": now_iso}


@api_router.get("/customers/search")
async def search_customer_history(
    phone: Optional[str] = None,
    email: Optional[str] = None,
    serial_number: Optional[str] = None,
    order_id: Optional[str] = None,
    user: dict = Depends(require_roles(["call_support", "admin", "supervisor", "accountant"]))
):
    """Global search for customer history by phone/email/serial/order_id"""
    if not any([phone, email, serial_number, order_id]):
        raise HTTPException(status_code=400, detail="Please provide at least one search parameter")
    
    or_conditions = []
    if phone:
        or_conditions.append({"customer_phone": {"$regex": phone, "$options": "i"}})
    if email:
        or_conditions.append({"customer_email": {"$regex": email, "$options": "i"}})
    if serial_number:
        or_conditions.append({"serial_number": {"$regex": serial_number, "$options": "i"}})
    if order_id:
        or_conditions.append({"order_id": {"$regex": order_id, "$options": "i"}})
    
    # Get tickets
    tickets = await db.tickets.find(
        {"$or": or_conditions},
        {"_id": 0}
    ).sort("created_at", -1).to_list(100)
    
    # Get warranties
    warranty_conditions = []
    if phone:
        warranty_conditions.append({"phone": {"$regex": phone, "$options": "i"}})
    if email:
        warranty_conditions.append({"email": {"$regex": email, "$options": "i"}})
    if order_id:
        warranty_conditions.append({"order_id": {"$regex": order_id, "$options": "i"}})
    
    warranties = []
    if warranty_conditions:
        warranties = await db.warranties.find(
            {"$or": warranty_conditions},
            {"_id": 0}
        ).to_list(50)
    
    # Get dispatches
    dispatches = await db.dispatches.find(
        {"$or": or_conditions},
        {"_id": 0}
    ).sort("created_at", -1).to_list(50)
    
    return {
        "tickets": tickets,
        "warranties": warranties,
        "dispatches": dispatches,
        "total_tickets": len(tickets),
        "total_warranties": len(warranties),
        "total_dispatches": len(dispatches)
    }



# ==================== VOLTDOCTOR TICKET REPLY ====================

class TicketReply(BaseModel):
    message: str
    change_status: Optional[str] = None

@api_router.post("/tickets/{ticket_id}/reply")
async def reply_to_ticket(
    ticket_id: str,
    reply: TicketReply,
    user: dict = Depends(require_roles(["call_support", "admin", "supervisor", "customer"]))
):
    """
    Post a reply on a ticket. Support agents may reply to any ticket and change
    its status; a customer may reply only to their OWN ticket and cannot change
    the status. (Previously this was staff-only, so the customer app's reply box
    always failed with 403.)
    """
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")

    is_customer = user.get("role") == "customer"
    if is_customer and ticket.get("customer_id") != user["id"]:
        raise HTTPException(status_code=403, detail="Access denied")

    now = datetime.now(timezone.utc).isoformat()
    responder_name = (
        f"{user.get('first_name', '')} {user.get('last_name', '')}".strip()
        or user.get("email") or "User"
    )

    # Record in ticket history — this is what the customer timeline reads.
    label = "Customer reply" if is_customer else "Support reply"
    await add_ticket_history(ticket_id, f"{label}: {reply.message[:100]}", user, {
        "full_message": reply.message,
        "from": "customer" if is_customer else "support",
    })

    # Append to the conversation thread on the ticket.
    current_notes = ticket.get("agent_notes", "") or ""
    tag = f"{responder_name} (Customer)" if is_customer else responder_name
    new_notes = f"{current_notes}\n\n[{now[:10]} - {tag}]: {reply.message}".strip()

    update_data = {"agent_notes": new_notes, "updated_at": now}

    # Only staff may move the ticket's status via a reply.
    if reply.change_status and not is_customer:
        update_data["status"] = reply.change_status

    await db.tickets.update_one({"id": ticket_id}, {"$set": update_data})

    # Notify the other side so the reply isn't missed.
    try:
        if is_customer:
            await create_notification(
                title=f"Customer replied — {ticket.get('ticket_number')}",
                message=f"{responder_name}: {reply.message[:120]}",
                notification_type="ticket",
                link=f"/admin/tickets/{ticket_id}",
                target_roles=["call_support", "supervisor", "admin"],
                priority="high" if ticket.get("sla_breached") else "normal",
            )
        elif ticket.get("customer_id"):
            await create_notification(
                title=f"Support replied to ticket {ticket.get('ticket_number')}",
                message=reply.message[:120],
                notification_type="ticket",
                link="/support",
                target_user_ids=[ticket["customer_id"]],
                priority="normal",
            )
    except Exception as e:
        logger.warning(f"ticket reply notification failed for {ticket_id}: {e}")

    return {"message": "Reply sent successfully"}

# ==================== WARRANTY ENDPOINTS ====================

# Registration reward: customers who REGISTER their product get extra months of
# warranty as a thank-you. This is a value-add for registering — deliberately NOT
# tied to leaving a review (incentivising reviews violates Amazon/marketplace
# policy). Set to 0 to disable. Applied on approval, once per warranty.
WARRANTY_REGISTRATION_BONUS_MONTHS = int(os.environ.get("WARRANTY_REGISTRATION_BONUS_MONTHS", "3") or 0)


def _add_months_iso(date_str: str, months: int) -> str:
    """Add `months` to an ISO date ('YYYY-MM-DD' or full ISO); return same shape.
    Returns the input unchanged if it can't be parsed (never break approval)."""
    from dateutil.relativedelta import relativedelta
    s = str(date_str or "")
    try:
        if "T" in s:
            dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
            return (dt + relativedelta(months=months)).isoformat()
        d = datetime.strptime(s[:10], "%Y-%m-%d").date()
        return (d + relativedelta(months=months)).isoformat()
    except (ValueError, TypeError):
        return date_str


@api_router.post("/warranties")
async def create_warranty(
    first_name: str = Form(...),
    last_name: str = Form(...),
    phone: str = Form(...),
    email: str = Form(...),
    device_type: str = Form(...),
    product_name: Optional[str] = Form(None),
    serial_number: Optional[str] = Form(None),
    invoice_date: str = Form(...),
    invoice_amount: float = Form(...),
    order_id: str = Form(...),
    invoice_file: Optional[UploadFile] = File(None),
    user: dict = Depends(get_current_user)
):
    """Register warranty"""
    warranty_id = str(uuid.uuid4())
    warranty_number = await generate_warranty_number()
    now = datetime.now(timezone.utc).isoformat()
    
    # ====== UNIQUENESS: Prevent duplicate active warranties for same serial number ======
    if serial_number and serial_number.strip():
        existing_warranty = await db.warranties.find_one({
            "serial_number": serial_number.strip(),
            "status": {"$in": ["pending", "approved", "active"]}
        })
        if existing_warranty:
            raise HTTPException(
                status_code=409,
                detail=f"Active warranty already exists for serial number {serial_number} (Warranty: {existing_warranty.get('warranty_number')})"
            )
    
    # Handle file upload using storage utility
    invoice_path = None
    if invoice_file:
        try:
            content = await invoice_file.read()
            relative_path, storage_type = await storage_upload(
                file_data=content,
                folder="invoices",
                original_filename=invoice_file.filename,
                filename_prefix=warranty_id
            )
            invoice_path = f"/api/files/{relative_path}"
        except StorageError as e:
            logger.error(f"Failed to upload warranty invoice: {str(e)}")
            raise HTTPException(status_code=500, detail=f"File upload failed: {str(e)}")
    
    warranty_doc = {
        "id": warranty_id,
        "warranty_number": warranty_number,
        "customer_id": user["id"],
        "first_name": first_name,
        "last_name": last_name,
        "phone": phone,
        "email": email.lower(),
        "device_type": device_type,
        "product_name": product_name,
        "serial_number": serial_number,
        "invoice_date": invoice_date,
        "invoice_amount": invoice_amount,
        "order_id": order_id,
        "invoice_file": invoice_path,
        "status": "pending",
        "warranty_end_date": None,
        "admin_notes": None,
        "extension_requested": False,
        "extension_status": None,
        "extension_review_file": None,
        # Registration reward (applied on approval): a thank-you for registering.
        "registered_via": "self_registration",
        "registered_at": now,
        "registration_bonus_months": WARRANTY_REGISTRATION_BONUS_MONTHS,
        "registration_bonus_applied": False,
        "created_at": now,
        "updated_at": now
    }

    await db.warranties.insert_one(warranty_doc)
    del warranty_doc["_id"]
    return warranty_doc


@api_router.get("/warranties/registration-offer")
async def warranty_registration_offer(user: dict = Depends(get_current_user)):
    """The current 'register & get extra warranty' promo — drives the app's
    registration nudge. Reflects WARRANTY_REGISTRATION_BONUS_MONTHS; hides at 0.
    (Registered before /warranties/{id} so the static path isn't shadowed.)"""
    m = WARRANTY_REGISTRATION_BONUS_MONTHS
    return {"enabled": m > 0, "months": m}

@api_router.get("/warranties")
async def list_warranties(
    search: Optional[str] = None,
    status: Optional[str] = None,
    user: dict = Depends(get_current_user)
):
    """List warranties. Allow-listed roles only — the old endpoint fell through
    to "no filter" for dealer/gate/dispatcher/etc., leaking the full PII table."""
    role = user["role"]
    permitted = {"admin", "supervisor", "call_support", "accountant",
                 "service_agent", "technician", "customer", "dealer"}
    if role not in permitted:
        raise HTTPException(status_code=403, detail="Role not permitted to read warranties")

    query = {}

    if role == "customer":
        # Match by customer_id OR by email/phone (for imported warranties)
        query["$or"] = [
            {"customer_id": user["id"]},
            {"email": {"$regex": f"^{user.get('email', '')}$", "$options": "i"}},
            {"phone": user.get("phone", "")}
        ]
    elif role == "dealer":
        # Dealers see only the warranties they registered or sold against.
        dealer_link = user.get("dealer_id") or user["id"]
        query["$or"] = [
            {"registered_by_dealer_id": dealer_link},
            {"dealer_id": dealer_link},
        ]
    
    if search:
        search_query = [
            {"warranty_number": {"$regex": search, "$options": "i"}},
            {"first_name": {"$regex": search, "$options": "i"}},
            {"last_name": {"$regex": search, "$options": "i"}},
            {"phone": {"$regex": search, "$options": "i"}},
            {"email": {"$regex": search, "$options": "i"}},
            {"order_id": {"$regex": search, "$options": "i"}}
        ]
        if "$or" in query:
            query = {"$and": [query, {"$or": search_query}]}
        else:
            query["$or"] = search_query
    
    if status:
        if "$and" in query:
            query["$and"].append({"status": status})
        elif "$or" in query and user["role"] == "customer":
            query = {"$and": [query, {"status": status}]}
        else:
            query["status"] = status
    
    warranties = await db.warranties.find(query, {"_id": 0}).sort("created_at", -1).to_list(10000)
    for w in warranties:
        # Alias the cover-end date under `end_date` too, so older app builds
        # (which read end_date, not warranty_end_date) show warranty health.
        if w.get("warranty_end_date") and not w.get("end_date"):
            w["end_date"] = w["warranty_end_date"]
    return warranties

@api_router.get("/warranties/{warranty_id}")
async def get_warranty(warranty_id: str, user: dict = Depends(get_current_user)):
    """Get warranty details"""
    warranty = await db.warranties.find_one({"id": warranty_id}, {"_id": 0})
    if not warranty:
        raise HTTPException(status_code=404, detail="Warranty not found")
    
    # ====== SECURITY: Role-based access control ======
    if user["role"] == "customer":
        # Customers can only see their own warranties
        customer_id = warranty.get("customer_id") or warranty.get("user_id")
        customer_email = warranty.get("email", "").lower()
        customer_phone = warranty.get("phone", "")
        
        is_owner = (
            customer_id == user["id"] or
            customer_email == user.get("email", "").lower() or
            customer_phone == user.get("phone", "")
        )
        if not is_owner:
            raise HTTPException(status_code=403, detail="Access denied")
    elif user["role"] == "dealer":
        # Dealers can only see warranties they registered
        if warranty.get("registered_by_dealer_id") != user.get("dealer_id"):
            # Also allow if warranty is for a product they sold
            if warranty.get("dealer_id") != user.get("dealer_id"):
                raise HTTPException(status_code=403, detail="Access denied")
    # Admin, supervisor, call_support, service_agent can see all

    if warranty.get("warranty_end_date") and not warranty.get("end_date"):
        warranty["end_date"] = warranty["warranty_end_date"]
    return warranty


# ==================== PRODUCT MAINTENANCE SCHEDULE ====================

def _maintenance_template_for(device_type: Optional[str]):
    """Founder-confirmed maintenance tasks per device type, with a fallback.

    Order matters: a 'Solar Inverter' is an inverter (battery schedule), not a
    solar panel — so match inverter/battery/UPS before the solar-panel branch.
    """
    t = (device_type or "").lower()
    if "batter" in t or "inverter" in t or "ups" in t:
        return [
            {"key": "battery_check", "title": "Battery water & health check", "interval_months": 3},
            {"key": "full_service", "title": "Full service", "interval_months": 12},
        ]
    if "panel" in t or "solar" in t:
        return [
            {"key": "panel_clean", "title": "Solar panel cleaning", "interval_months": 1},
            {"key": "full_service", "title": "Full service", "interval_months": 12},
        ]
    if "stabil" in t:
        return [{"key": "annual_check", "title": "Annual stabilizer check", "interval_months": 12}]
    return [{"key": "full_service", "title": "Full service", "interval_months": 12}]


def _parse_dt(s):
    if not s:
        return None
    try:
        dt = datetime.fromisoformat(str(s).replace("Z", "+00:00"))
    except Exception:
        try:
            dt = datetime.strptime(str(s)[:10], "%Y-%m-%d")
        except Exception:
            return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def _maintenance_status(due_iso: Optional[str]) -> str:
    due = _parse_dt(due_iso)
    if not due:
        return "upcoming"
    days = (due - datetime.now(timezone.utc)).days
    if days < 0:
        return "overdue"
    if days <= 14:
        return "due_soon"
    return "upcoming"


def _customer_owns_warranty(warranty: dict, user: dict) -> bool:
    if user["role"] != "customer":
        return user["role"] in ("admin", "supervisor", "call_support", "service_agent")
    return (
        (warranty.get("customer_id") or warranty.get("user_id")) == user["id"]
        or warranty.get("email", "").lower() == user.get("email", "").lower()
        or warranty.get("phone", "") == user.get("phone", "")
    )


async def _ensure_maintenance_tasks(warranty: dict):
    """Lazily generate maintenance task docs for a warranty from its template."""
    from dateutil.relativedelta import relativedelta
    wid = warranty["id"]
    existing = {
        t["task_key"]: t
        for t in await db.maintenance_tasks.find(
            {"warranty_id": wid}, {"_id": 0}
        ).to_list(50)
    }
    base = (
        _parse_dt(warranty.get("invoice_date"))
        or _parse_dt(warranty.get("created_at"))
        or datetime.now(timezone.utc)
    )
    out = []
    for tpl in _maintenance_template_for(warranty.get("device_type")):
        if tpl["key"] in existing:
            out.append(existing[tpl["key"]])
            continue
        due = base + relativedelta(months=tpl["interval_months"])
        doc = {
            "id": str(uuid.uuid4()),
            "warranty_id": wid,
            "customer_id": warranty.get("customer_id"),
            "serial_number": warranty.get("serial_number"),
            "device_type": warranty.get("device_type"),
            "task_key": tpl["key"],
            "title": tpl["title"],
            "interval_months": tpl["interval_months"],
            "due_date": due.isoformat(),
            "last_done_at": None,
            "reminded_for": None,
            "created_at": datetime.now(timezone.utc).isoformat(),
        }
        await db.maintenance_tasks.insert_one(dict(doc))
        out.append(doc)
    return out


@api_router.get("/warranties/{warranty_id}/maintenance")
async def get_warranty_maintenance(
    warranty_id: str, user: dict = Depends(get_current_user)
):
    """Upcoming/overdue maintenance for a registered product (My Products)."""
    warranty = await db.warranties.find_one({"id": warranty_id}, {"_id": 0})
    if not warranty:
        raise HTTPException(status_code=404, detail="Warranty not found")
    if not _customer_owns_warranty(warranty, user):
        raise HTTPException(status_code=403, detail="Access denied")
    tasks = await _ensure_maintenance_tasks(warranty)
    items = [{
        "task_key": t["task_key"],
        "title": t["title"],
        "due_date": t["due_date"],
        "interval_months": t.get("interval_months"),
        "last_done_at": t.get("last_done_at"),
        "status": _maintenance_status(t["due_date"]),
    } for t in tasks]
    # Surface a warranty-expiry nudge within 30 days as a (non-stored) item.
    end = _parse_dt(warranty.get("warranty_end_date"))
    if end:
        days = (end - datetime.now(timezone.utc)).days
        if days <= 30:
            items.append({
                "task_key": "warranty_expiry",
                "title": "Warranty expiring",
                "due_date": warranty.get("warranty_end_date"),
                "interval_months": None,
                "last_done_at": None,
                "status": "overdue" if days < 0 else "due_soon",
            })
    rank = {"overdue": 0, "due_soon": 1, "upcoming": 2}
    items.sort(key=lambda x: (rank.get(x["status"], 3), x["due_date"] or ""))
    return {"tasks": items}


@api_router.post("/warranties/{warranty_id}/maintenance/{task_key}/complete")
async def complete_warranty_maintenance(
    warranty_id: str, task_key: str, user: dict = Depends(get_current_user)
):
    """Mark a maintenance task done; advance its next due date by the interval."""
    from dateutil.relativedelta import relativedelta
    warranty = await db.warranties.find_one({"id": warranty_id}, {"_id": 0})
    if not warranty:
        raise HTTPException(status_code=404, detail="Warranty not found")
    if not _customer_owns_warranty(warranty, user):
        raise HTTPException(status_code=403, detail="Access denied")
    task = await db.maintenance_tasks.find_one(
        {"warranty_id": warranty_id, "task_key": task_key}, {"_id": 0}
    )
    if not task:
        await _ensure_maintenance_tasks(warranty)
        task = await db.maintenance_tasks.find_one(
            {"warranty_id": warranty_id, "task_key": task_key}, {"_id": 0}
        )
    if not task:
        raise HTTPException(status_code=404, detail="Maintenance task not found")
    now = datetime.now(timezone.utc)
    next_due = now + relativedelta(months=task.get("interval_months") or 12)
    await db.maintenance_tasks.update_one(
        {"warranty_id": warranty_id, "task_key": task_key},
        {"$set": {
            "last_done_at": now.isoformat(),
            "due_date": next_due.isoformat(),
            "reminded_for": None,
        }},
    )
    return {"success": True, "next_due": next_due.isoformat()}


@api_router.patch("/warranties/{warranty_id}/approve")
async def approve_warranty(
    warranty_id: str,
    approval: WarrantyApproval,
    user: dict = Depends(require_roles(["admin", "supervisor"]))
):
    """Admin/Supervisor approves warranty"""
    warranty = await db.warranties.find_one({"id": warranty_id}, {"_id": 0})
    if not warranty:
        raise HTTPException(status_code=404, detail="Warranty not found")
    
    now = datetime.now(timezone.utc).isoformat()
    base_end = approval.warranty_end_date
    bonus = int(warranty.get("registration_bonus_months") or 0)
    set_fields = {
        "status": "approved",
        "warranty_end_date": base_end,
        "admin_notes": approval.notes,
        "updated_at": now,
    }
    bonus_applied = False
    # Add the registration-reward months on top of the admin's end date — once,
    # and only for warranties the customer actually registered (imported ones
    # don't carry registration_bonus_months).
    if base_end and bonus > 0 and not warranty.get("registration_bonus_applied"):
        set_fields["base_warranty_end_date"] = base_end
        set_fields["warranty_end_date"] = _add_months_iso(base_end, bonus)
        set_fields["registration_bonus_applied"] = True
        set_fields["registration_bonus_applied_at"] = now
        bonus_applied = True

    await db.warranties.update_one({"id": warranty_id}, {"$set": set_fields})

    if bonus_applied and warranty.get("customer_id"):
        prod = warranty.get("product_name") or warranty.get("device_type") or "your product"
        await create_notification(
            title=f"+{bonus} months warranty added 🎉",
            message=(f"Thanks for registering {prod}! We've added {bonus} extra months of warranty — "
                     f"your cover now runs to {set_fields['warranty_end_date'][:10]}."),
            notification_type="warranty", link="/warranty",
            target_user_ids=[warranty["customer_id"]], priority="normal",
        )

    return {"message": "Warranty approved", "warranty_end_date": set_fields["warranty_end_date"],
            "registration_bonus_months": bonus if bonus_applied else 0}

class WarrantyRejectRequest(BaseModel):
    reason: Optional[str] = None
    notes: Optional[str] = None  # Frontend sends 'notes' in FormData

@api_router.patch("/warranties/{warranty_id}/reject")
async def reject_warranty(
    warranty_id: str,
    reason: Optional[str] = None,
    notes: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "supervisor"]))
):
    """Admin/Supervisor rejects warranty - accepts reason as query param or notes from FormData"""
    rejection_reason = reason or notes
    if not rejection_reason:
        raise HTTPException(status_code=400, detail="Rejection reason is required")
    
    now = datetime.now(timezone.utc).isoformat()
    result = await db.warranties.update_one(
        {"id": warranty_id},
        {"$set": {
            "status": "rejected",
            "admin_notes": rejection_reason,
            "rejected_by": user["id"],
            "rejected_at": now,
            "updated_at": now
        }}
    )
    
    if result.modified_count == 0:
        raise HTTPException(status_code=404, detail="Warranty not found or already processed")
    
    return {"message": "Warranty rejected"}

@api_router.post("/warranties/{warranty_id}/request-extension")
async def request_warranty_extension(
    warranty_id: str,
    review_file: UploadFile = File(...),
    user: dict = Depends(get_current_user)
):
    """Customer requests warranty extension with Amazon review screenshot"""
    warranty = await db.warranties.find_one({"id": warranty_id}, {"_id": 0})
    if not warranty:
        raise HTTPException(status_code=404, detail="Warranty not found")
    
    if warranty["customer_id"] != user["id"]:
        raise HTTPException(status_code=403, detail="Access denied")
    
    # Upload review file using storage utility
    try:
        content = await review_file.read()
        relative_path, storage_type = await storage_upload(
            file_data=content,
            folder="reviews",
            original_filename=review_file.filename,
            filename_prefix=f"review_{warranty_id}"
        )
        review_url = f"/api/files/{relative_path}"
    except StorageError as e:
        logger.error(f"Failed to upload warranty review: {str(e)}")
        raise HTTPException(status_code=500, detail=f"File upload failed: {str(e)}")
    
    now = datetime.now(timezone.utc).isoformat()
    
    await db.warranties.update_one(
        {"id": warranty_id},
        {"$set": {
            "extension_requested": True,
            "extension_status": "pending",
            "extension_review_file": review_url,
            "updated_at": now
        }}
    )
    
    return {"message": "Extension request submitted"}

@api_router.get("/admin/warranty-extensions")
async def get_warranty_extensions(
    user: dict = Depends(require_roles(["admin", "supervisor"]))
):
    """Get all warranties with pending extension requests"""
    warranties = await db.warranties.find(
        {"extension_requested": True},
        {"_id": 0}
    ).sort("updated_at", -1).to_list(10000)
    
    return warranties

class ExtensionReview(BaseModel):
    action: str  # approve or reject
    extension_months: Optional[int] = 3  # Default 3 months extension
    notes: Optional[str] = None

@api_router.patch("/admin/warranties/{warranty_id}/review-extension")
async def review_warranty_extension(
    warranty_id: str,
    review: ExtensionReview,
    user: dict = Depends(require_roles(["admin", "supervisor"]))
):
    """Admin/Supervisor approves or rejects warranty extension request"""
    warranty = await db.warranties.find_one({"id": warranty_id}, {"_id": 0})
    if not warranty:
        raise HTTPException(status_code=404, detail="Warranty not found")
    
    if not warranty.get("extension_requested"):
        raise HTTPException(status_code=400, detail="No extension request pending")
    
    now = datetime.now(timezone.utc).isoformat()
    
    if review.action == "approve":
        # Calculate new warranty end date
        current_end = warranty.get("warranty_end_date")
        if current_end:
            end_date = datetime.fromisoformat(current_end.replace('Z', '+00:00'))
        else:
            end_date = datetime.now(timezone.utc)
        
        # Add extension months
        new_end_date = end_date + timedelta(days=review.extension_months * 30)
        
        await db.warranties.update_one(
            {"id": warranty_id},
            {"$set": {
                "extension_status": "approved",
                "warranty_end_date": new_end_date.isoformat()[:10],  # Just the date part
                "extension_notes": review.notes,
                "extension_months_granted": review.extension_months,
                "extension_reviewed_at": now,
                "extension_reviewed_by": user["id"],
                "updated_at": now
            }}
        )
        
        return {
            "message": f"Extension approved - {review.extension_months} months added",
            "new_warranty_end_date": new_end_date.isoformat()[:10]
        }
    
    elif review.action == "reject":
        await db.warranties.update_one(
            {"id": warranty_id},
            {"$set": {
                "extension_status": "rejected",
                "extension_notes": review.notes,
                "extension_reviewed_at": now,
                "extension_reviewed_by": user["id"],
                "updated_at": now
            }}
        )
        
        return {"message": "Extension request rejected"}
    
    else:
        raise HTTPException(status_code=400, detail="Invalid action. Use 'approve' or 'reject'")

# ==================== WARRANTY INVOICE MANAGEMENT ====================

@api_router.post("/warranties/{warranty_id}/upload-invoice")
async def upload_warranty_invoice(
    warranty_id: str,
    invoice_file: UploadFile = File(...),
    user: dict = Depends(get_current_user)
):
    """Upload an invoice PDF/image for a warranty. Staff can upload to any;
    a customer can upload only to their own registered warranty."""
    warranty = await db.warranties.find_one({"id": warranty_id}, {"_id": 0})
    if not warranty:
        raise HTTPException(status_code=404, detail="Warranty not found")
    if user["role"] not in ("admin", "supervisor", "call_support") and warranty.get("customer_id") != user["id"]:
        raise HTTPException(status_code=403, detail="You can only upload an invoice for your own warranty")
    
    # Upload file using storage utility
    try:
        content = await invoice_file.read()
        relative_path, storage_type = await storage_upload(
            file_data=content,
            folder="warranty_invoices",
            original_filename=invoice_file.filename,
            filename_prefix=f"warranty_invoice_{warranty_id}"
        )
        invoice_url = f"/api/files/{relative_path}"
    except StorageError as e:
        logger.error(f"Failed to upload warranty invoice: {str(e)}")
        raise HTTPException(status_code=500, detail=f"File upload failed: {str(e)}")
    
    now = datetime.now(timezone.utc).isoformat()
    
    await db.warranties.update_one(
        {"id": warranty_id},
        {"$set": {
            "admin_invoice_file": invoice_url,
            "admin_invoice_uploaded_at": now,
            "admin_invoice_uploaded_by": user["id"],
            "updated_at": now
        }}
    )
    
    return {"message": "Invoice uploaded successfully", "invoice_url": invoice_url}

# ==================== CUSTOMER EDIT (For Admin/Support) ====================

class CustomerUpdate(BaseModel):
    first_name: Optional[str] = None
    last_name: Optional[str] = None
    email: Optional[str] = None
    address: Optional[str] = None
    city: Optional[str] = None
    state: Optional[str] = None
    pincode: Optional[str] = None

@api_router.patch("/admin/customers/{user_id}")
async def update_customer_info(
    user_id: str,
    update_data: CustomerUpdate,
    user: dict = Depends(require_roles(["admin", "call_support"]))
):
    """Admin or Support updates customer information. Phone cannot be changed (unique ID)."""
    customer = await db.users.find_one({"id": user_id}, {"_id": 0})
    if not customer:
        raise HTTPException(status_code=404, detail="Customer not found")
    
    if customer.get("role") != "customer":
        raise HTTPException(status_code=400, detail="Can only edit customer accounts")
    
    update_dict = {"updated_at": datetime.now(timezone.utc).isoformat()}
    
    if update_data.first_name is not None:
        update_dict["first_name"] = update_data.first_name
    if update_data.last_name is not None:
        update_dict["last_name"] = update_data.last_name
    if update_data.email is not None:
        # Check if email is taken by another user
        existing = await db.users.find_one({"email": update_data.email.lower(), "id": {"$ne": user_id}})
        if existing:
            raise HTTPException(status_code=400, detail="Email already in use by another user")
        update_dict["email"] = update_data.email.lower()
    if update_data.address is not None:
        update_dict["address"] = update_data.address
    if update_data.city is not None:
        update_dict["city"] = update_data.city
    if update_data.state is not None:
        update_dict["state"] = update_data.state
    if update_data.pincode is not None:
        update_dict["pincode"] = update_data.pincode
    
    await db.users.update_one({"id": user_id}, {"$set": update_dict})
    
    # Also update customer info in related tickets
    ticket_update = {}
    new_name = None
    if update_data.first_name is not None or update_data.last_name is not None:
        # Get updated user to construct new name
        updated_user = await db.users.find_one({"id": user_id}, {"_id": 0})
        new_name = f"{updated_user.get('first_name', '')} {updated_user.get('last_name', '')}".strip()
        ticket_update["customer_name"] = new_name
    if update_data.email is not None:
        ticket_update["customer_email"] = update_data.email.lower()
    if update_data.address is not None:
        ticket_update["customer_address"] = update_data.address
    if update_data.city is not None:
        ticket_update["customer_city"] = update_data.city
    
    if ticket_update:
        await db.tickets.update_many(
            {"customer_id": user_id},
            {"$set": ticket_update}
        )
    
    updated_customer = await db.users.find_one({"id": user_id}, {"_id": 0, "password_hash": 0})
    return updated_customer

@api_router.get("/admin/customers/{user_id}")
async def get_customer_detail(
    user_id: str,
    user: dict = Depends(require_roles(["admin", "call_support"]))
):
    """Get detailed customer information"""
    customer = await db.users.find_one({"id": user_id}, {"_id": 0, "password_hash": 0})
    if not customer:
        raise HTTPException(status_code=404, detail="Customer not found")
    
    return customer

# ==================== ADMIN TICKET CLOSE ====================

class AdminCloseTicket(BaseModel):
    notes: str

@api_router.post("/admin/tickets/{ticket_id}/close")
async def admin_close_ticket(
    ticket_id: str,
    close_data: AdminCloseTicket,
    user: dict = Depends(require_roles(["admin"]))
):
    """Admin closes any ticket with notes - regardless of current status"""
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    if not close_data.notes or len(close_data.notes.strip()) < 5:
        raise HTTPException(status_code=400, detail="Closing notes must be at least 5 characters")
    
    now = datetime.now(timezone.utc).isoformat()
    
    # Update ticket status to closed
    await db.tickets.update_one(
        {"id": ticket_id},
        {"$set": {
            "status": "closed",
            "admin_close_notes": close_data.notes,
            "closed_at": now,
            "closed_by": user["id"],
            "closed_by_name": f"{user['first_name']} {user['last_name']}",
            "updated_at": now
        }}
    )
    
    # Add to ticket history
    await add_ticket_history(ticket_id, f"Ticket closed by Admin: {close_data.notes[:100]}...", user, {
        "full_notes": close_data.notes,
        "previous_status": ticket.get("status")
    })
    
    return {"message": "Ticket closed successfully"}

class AdminChangeTicketStatus(BaseModel):
    new_status: str
    notes: str

# Define which statuses can be rolled back to (supervisor-related and pre-repair stages)
ROLLBACK_STATUSES = {
    "new_request": "New Request",
    "call_support_followup": "Call Support Followup",
    "escalated_to_supervisor": "Escalated to Supervisor",
    "supervisor_followup": "Supervisor Followup",
    "hardware_service": "Hardware Service",
    "awaiting_label": "Awaiting Pickup Label",
    "label_uploaded": "Label Uploaded",
    "received_at_factory": "Received at Factory",
    "in_repair": "In Repair",
    "repair_completed": "Repair Completed",
    "ready_for_dispatch": "Ready for Dispatch"
}

@api_router.post("/admin/tickets/{ticket_id}/change-status")
async def admin_change_ticket_status(
    ticket_id: str,
    status_data: AdminChangeTicketStatus,
    user: dict = Depends(require_roles(["admin"]))
):
    """Admin changes ticket status - allows rolling back to any stage"""
    ticket = await db.tickets.find_one({"id": ticket_id}, {"_id": 0})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    new_status = status_data.new_status
    if new_status not in TICKET_STATUSES:
        raise HTTPException(status_code=400, detail=f"Invalid status: {new_status}")
    
    if not status_data.notes or len(status_data.notes.strip()) < 10:
        raise HTTPException(status_code=400, detail="Notes must be at least 10 characters explaining the status change")
    
    old_status = ticket.get("status")
    if old_status == new_status:
        raise HTTPException(status_code=400, detail="New status is the same as current status")
    
    now = datetime.now(timezone.utc).isoformat()
    
    # Build update data
    update_data = {
        "status": new_status,
        "updated_at": now,
        "status_changed_by_admin": user["id"],
        "status_changed_at": now
    }
    
    # Clear certain fields when rolling back
    if new_status in ["new_request", "call_support_followup"]:
        # Rolling back to support stage - clear escalation
        update_data["escalated_to_supervisor"] = False
        update_data["supervisor_action"] = None
        update_data["supervisor_notes"] = None
        update_data["supervisor_sku"] = None
    
    if new_status == "escalated_to_supervisor":
        # Ensure escalation flag is set
        update_data["escalated_to_supervisor"] = True
    
    if new_status in ["awaiting_label", "hardware_service"]:
        # Clear accountant decision if rolling back to pre-accountant stage
        update_data["accountant_decision"] = None
        update_data["accountant_decision_at"] = None
    
    # Clear closed fields if reopening
    if old_status in ["closed", "closed_by_agent", "resolved_on_call", "delivered"]:
        update_data["closed_at"] = None
        update_data["closed_by"] = None
        update_data["closed_by_name"] = None
    
    await db.tickets.update_one({"id": ticket_id}, {"$set": update_data})
    
    # Add to ticket history with full details
    await add_ticket_history(
        ticket_id, 
        f"Status changed by Admin from '{old_status}' to '{new_status}'", 
        user, 
        {
            "old_status": old_status,
            "new_status": new_status,
            "reason": status_data.notes,
            "action_type": "admin_status_override"
        }
    )
    
    return {
        "message": f"Ticket status changed from '{old_status}' to '{new_status}'",
        "old_status": old_status,
        "new_status": new_status
    }

@api_router.get("/admin/tickets/status-options")
async def get_ticket_status_options(user: dict = Depends(require_roles(["admin"]))):
    """Get available status options for admin to change tickets to"""
    return {
        "statuses": ROLLBACK_STATUSES,
        "all_statuses": {s: s.replace("_", " ").title() for s in TICKET_STATUSES}
    }

