@api_router.post("/incoming-queue/{queue_id}/classify", response_model=IncomingQueueResponse)
async def classify_incoming_queue_entry(
    queue_id: str,
    classify_data: IncomingQueueClassify,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Classify an incoming queue entry.
    This is where stock impact happens based on classification type.
    """
    now = datetime.now(timezone.utc)
    
    # Get the queue entry
    queue_entry = await db.incoming_queue.find_one({"id": queue_id})
    if not queue_entry:
        raise HTTPException(status_code=404, detail="Queue entry not found")
    
    if queue_entry.get("status") == "processed":
        raise HTTPException(status_code=400, detail="This entry has already been processed")
    
    # Validate classification type
    if classify_data.classification_type not in INCOMING_CLASSIFICATION_TYPES:
        raise HTTPException(status_code=400, detail=f"Invalid classification type. Must be one of: {INCOMING_CLASSIFICATION_TYPES}")
    
    update_data = {
        "status": "classified",
        "classification_type": classify_data.classification_type,
        "classified_by": user["id"],
        "classified_by_name": f"{user['first_name']} {user['last_name']}",
        "classified_at": now.isoformat(),
        "updated_at": now.isoformat(),
        "remarks": classify_data.remarks
    }
    
    ledger_entry_id = None
    ledger_entry_number = None
    
    # ============ CLASSIFICATION LOGIC ============
    
    if classify_data.classification_type == "repair_item":
        # Link to ticket, send to technician queue, NO stock impact
        if not classify_data.ticket_id:
            raise HTTPException(status_code=400, detail="ticket_id is required for repair_item classification")
        
        ticket = await db.tickets.find_one({"id": classify_data.ticket_id})
        if not ticket:
            raise HTTPException(status_code=400, detail="Ticket not found")
        
        update_data["classified_ticket_id"] = classify_data.ticket_id
        update_data["status"] = "processed"
        
        # Update ticket status to indicate item received for repair
        await db.tickets.update_one(
            {"id": classify_data.ticket_id},
            {"$set": {"status": "in_repair_queue", "updated_at": now.isoformat()}}
        )
        await add_ticket_history(classify_data.ticket_id, "Item received - Sent to repair queue", user, {
            "queue_id": queue_id,
            "queue_number": queue_entry.get("queue_number")
        })
        
    elif classify_data.classification_type == "return_inventory":
        # Return to inventory - create return_in ledger entry
        if not classify_data.firm_id:
            raise HTTPException(status_code=400, detail="firm_id is required for return_inventory classification")
        if not classify_data.item_id and not classify_data.sku_code:
            raise HTTPException(status_code=400, detail="item_id or sku_code is required for return_inventory classification")
        
        # Validate firm
        firm = await db.firms.find_one({"id": classify_data.firm_id, "is_active": True})
        if not firm:
            raise HTTPException(status_code=400, detail="Invalid or inactive firm")
        
        # Get item details
        item_type = classify_data.item_type or "finished_good"
        if item_type == "raw_material":
            if classify_data.item_id:
                item = await db.raw_materials.find_one({"id": classify_data.item_id})
            else:
                item = await db.raw_materials.find_one({"sku_code": classify_data.sku_code.upper()})
            if not item:
                raise HTTPException(status_code=400, detail="Raw material not found")
            item_id = item["id"]
            item_name = item.get("name")
            item_sku = item.get("sku_code")
            # Get stock from ledger for this firm
            last_entry = await db.inventory_ledger.find_one(
                {"item_id": item_id, "firm_id": classify_data.firm_id, "item_type": "raw_material"},
                sort=[("created_at", -1)]
            )
            current_stock = last_entry.get("running_balance", 0) if last_entry else 0
        else:  # finished_good
            if classify_data.item_id:
                item = await db.skus.find_one({"id": classify_data.item_id, "firm_id": classify_data.firm_id})
            else:
                item = await db.skus.find_one({"sku_code": classify_data.sku_code, "firm_id": classify_data.firm_id})
            if not item:
                raise HTTPException(status_code=400, detail="SKU not found for this firm")
            item_id = item["id"]
            item_name = item.get("model_name")
            item_sku = item.get("sku_code")
            current_stock = item.get("stock_quantity", 0)
        
        quantity = classify_data.quantity or 1
        
        # Validate against original dispatch if linked
        original_dispatch = None
        original_dispatch_number = None
        if classify_data.original_dispatch_id:
            original_dispatch = await db.dispatches.find_one({"id": classify_data.original_dispatch_id})
            if original_dispatch:
                original_dispatch_number = original_dispatch.get("dispatch_number")
                # Check if already received
                existing_return = await db.inventory_ledger.find_one({
                    "entry_type": "return_in",
                    "reference_id": classify_data.original_dispatch_id
                })
                if existing_return:
                    raise HTTPException(status_code=400, detail="This dispatch has already been received back. Duplicate receipt not allowed.")
                
                # Validate quantity doesn't exceed original dispatch
                # Original dispatch quantity is 1 per dispatch
                if quantity > 1:
                    raise HTTPException(status_code=400, detail="Cannot receive more quantity than originally dispatched (1 per dispatch)")
        
        # Create return_in ledger entry
        ledger_entry_id = str(uuid.uuid4())
        ledger_entry_number = await generate_ledger_entry_number()
        running_balance = current_stock + quantity
        
        ledger_entry = {
            "id": ledger_entry_id,
            "entry_number": ledger_entry_number,
            "entry_type": "return_in",
            "item_type": item_type,
            "item_id": item_id,
            "item_name": item_name,
            "item_sku": item_sku,
            "firm_id": classify_data.firm_id,
            "firm_name": firm.get("name"),
            "quantity": quantity,
            "running_balance": running_balance,
            "unit_price": None,
            "total_value": None,
            "invoice_number": None,
            "reason": f"Return from {queue_entry.get('customer_name') or 'customer'}",
            "reference_id": classify_data.original_dispatch_id or queue_id,
            "notes": f"Queue: {queue_entry.get('queue_number')}, Tracking: {queue_entry.get('tracking_id')}",
            "created_by": user["id"],
            "created_by_name": f"{user['first_name']} {user['last_name']}",
            "created_at": now.isoformat(),
            "dispatch_id": classify_data.original_dispatch_id,
            "dispatch_number": original_dispatch_number,
            "queue_id": queue_id,
            "queue_number": queue_entry.get("queue_number")
        }
        await db.inventory_ledger.insert_one(ledger_entry)

        # Keep the atomic stock counter in sync with the ledger.
        try:
            await credit_stock_atomic(item_type, item_id, classify_data.firm_id, int(quantity))
        except Exception:
            pass

        # Post reverse-COGS journal entry: Dr Inventory, Cr COGS at WAC.
        try:
            wac = await calculate_wac(item_type, item_id, classify_data.firm_id)
        except Exception:
            wac = 0.0
        cogs_reverse_value = round(float(wac or 0) * float(quantity or 0), 2)
        if cogs_reverse_value > 0:
            await db.journal_entries.insert_one({
                "id": str(uuid.uuid4()),
                "journal_type": "cogs_reversal_return",
                "firm_id": classify_data.firm_id,
                "reference_type": "return_in",
                "reference_id": classify_data.original_dispatch_id or queue_id,
                "item_id": item_id,
                "item_type": item_type,
                "item_name": item_name,
                "quantity": quantity,
                "wac_per_unit": round(float(wac or 0), 4),
                "lines": [
                    {"account": "Inventory",          "debit": cogs_reverse_value, "credit": 0},
                    {"account": "Cost of Goods Sold", "debit": 0, "credit": cogs_reverse_value},
                ],
                "amount": cogs_reverse_value,
                "narration": f"Reverse COGS on return of dispatch "
                             f"{original_dispatch_number or 'N/A'}",
                "created_by": user["id"],
                "created_by_name": f"{user['first_name']} {user['last_name']}",
                "created_at": now.isoformat(),
            })

        # Update stock
        if item_type == "raw_material":
            await db.raw_materials.update_one(
                {"id": item_id},
                {"$set": {"current_stock": running_balance, "updated_at": now.isoformat()}}
            )
        else:
            await db.skus.update_one(
                {"id": item_id},
                {"$set": {"stock_quantity": running_balance, "updated_at": now.isoformat()}}
            )
        
        # Create audit log
        await db.audit_logs.insert_one({
            "id": str(uuid.uuid4()),
            "action": "return_stock_added",
            "entity_type": "incoming_queue",
            "entity_id": queue_id,
            "entity_name": queue_entry.get("queue_number"),
            "performed_by": user["id"],
            "performed_by_name": f"{user['first_name']} {user['last_name']}",
            "details": {
                "classification": "return_inventory",
                "item_sku": item_sku,
                "firm_id": classify_data.firm_id,
                "quantity": quantity,
                "previous_stock": current_stock,
                "new_stock": running_balance,
                "ledger_entry_id": ledger_entry_id,
                "original_dispatch_id": classify_data.original_dispatch_id
            },
            "timestamp": now.isoformat()
        })
        
        update_data.update({
            "classified_firm_id": classify_data.firm_id,
            "classified_firm_name": firm.get("name"),
            "classified_item_type": item_type,
            "classified_item_id": item_id,
            "classified_item_name": item_name,
            "classified_item_sku": item_sku,
            "classified_quantity": quantity,
            "original_dispatch_id": classify_data.original_dispatch_id,
            "original_dispatch_number": original_dispatch_number,
            "ledger_entry_id": ledger_entry_id,
            "ledger_entry_number": ledger_entry_number,
            "status": "processed"
        })
        
    elif classify_data.classification_type == "repair_yard":
        # Repair yard / recovered stock - create repair_yard_in ledger entry
        if not classify_data.firm_id:
            raise HTTPException(status_code=400, detail="firm_id is required for repair_yard classification")
        if not classify_data.item_id and not classify_data.sku_code:
            raise HTTPException(status_code=400, detail="item_id or sku_code is required for repair_yard classification")
        if not classify_data.reason:
            raise HTTPException(status_code=400, detail="reason is MANDATORY for repair_yard stock addition")
        
        # Validate firm
        firm = await db.firms.find_one({"id": classify_data.firm_id, "is_active": True})
        if not firm:
            raise HTTPException(status_code=400, detail="Invalid or inactive firm")
        
        # Get item details
        item_type = classify_data.item_type or "finished_good"
        if item_type == "raw_material":
            if classify_data.item_id:
                item = await db.raw_materials.find_one({"id": classify_data.item_id})
            else:
                item = await db.raw_materials.find_one({"sku_code": classify_data.sku_code.upper()})
            if not item:
                raise HTTPException(status_code=400, detail="Raw material not found")
            item_id = item["id"]
            item_name = item.get("name")
            item_sku = item.get("sku_code")
            # Get stock from ledger for this firm
            last_entry = await db.inventory_ledger.find_one(
                {"item_id": item_id, "firm_id": classify_data.firm_id, "item_type": "raw_material"},
                sort=[("created_at", -1)]
            )
            current_stock = last_entry.get("running_balance", 0) if last_entry else 0
        else:  # finished_good
            if classify_data.item_id:
                item = await db.skus.find_one({"id": classify_data.item_id, "firm_id": classify_data.firm_id})
            else:
                item = await db.skus.find_one({"sku_code": classify_data.sku_code, "firm_id": classify_data.firm_id})
            if not item:
                raise HTTPException(status_code=400, detail="SKU not found for this firm")
            item_id = item["id"]
            item_name = item.get("model_name")
            item_sku = item.get("sku_code")
            current_stock = item.get("stock_quantity", 0)
        
        quantity = classify_data.quantity or 1
        
        # Create repair_yard_in ledger entry
        ledger_entry_id = str(uuid.uuid4())
        ledger_entry_number = await generate_ledger_entry_number()
        running_balance = current_stock + quantity
        
        ledger_entry = {
            "id": ledger_entry_id,
            "entry_number": ledger_entry_number,
            "entry_type": "repair_yard_in",
            "item_type": item_type,
            "item_id": item_id,
            "item_name": item_name,
            "item_sku": item_sku,
            "firm_id": classify_data.firm_id,
            "firm_name": firm.get("name"),
            "quantity": quantity,
            "running_balance": running_balance,
            "unit_price": None,
            "total_value": None,
            "invoice_number": classify_data.reference_number,
            "reason": classify_data.reason,
            "reference_id": queue_id,
            "notes": f"Source: Repair Yard. Queue: {queue_entry.get('queue_number')}. {classify_data.remarks or ''}",
            "created_by": user["id"],
            "created_by_name": f"{user['first_name']} {user['last_name']}",
            "created_at": now.isoformat(),
            "source": "repair_yard",
            "reference_number": classify_data.reference_number,
            "queue_id": queue_id,
            "queue_number": queue_entry.get("queue_number")
        }
        await db.inventory_ledger.insert_one(ledger_entry)
        
        # Update stock
        if item_type == "raw_material":
            await db.raw_materials.update_one(
                {"id": item_id},
                {"$set": {"current_stock": running_balance, "updated_at": now.isoformat()}}
            )
        else:
            await db.skus.update_one(
                {"id": item_id},
                {"$set": {"stock_quantity": running_balance, "updated_at": now.isoformat()}}
            )
        
        # Create audit log
        await db.audit_logs.insert_one({
            "id": str(uuid.uuid4()),
            "action": "repair_yard_stock_added",
            "entity_type": "incoming_queue",
            "entity_id": queue_id,
            "entity_name": queue_entry.get("queue_number"),
            "performed_by": user["id"],
            "performed_by_name": f"{user['first_name']} {user['last_name']}",
            "details": {
                "classification": "repair_yard",
                "item_sku": item_sku,
                "firm_id": classify_data.firm_id,
                "quantity": quantity,
                "previous_stock": current_stock,
                "new_stock": running_balance,
                "reason": classify_data.reason,
                "reference_number": classify_data.reference_number,
                "ledger_entry_id": ledger_entry_id
            },
            "timestamp": now.isoformat()
        })
        
        update_data.update({
            "classified_firm_id": classify_data.firm_id,
            "classified_firm_name": firm.get("name"),
            "classified_item_type": item_type,
            "classified_item_id": item_id,
            "classified_item_name": item_name,
            "classified_item_sku": item_sku,
            "classified_quantity": quantity,
            "reason": classify_data.reason,
            "reference_number": classify_data.reference_number,
            "ledger_entry_id": ledger_entry_id,
            "ledger_entry_number": ledger_entry_number,
            "status": "processed"
        })
        
    elif classify_data.classification_type == "scrap":
        # Mark as scrap - NO stock impact
        if not classify_data.scrap_reason:
            raise HTTPException(status_code=400, detail="scrap_reason is required for scrap classification")
        
        update_data.update({
            "scrap_reason": classify_data.scrap_reason,
            "status": "processed"
        })
        
        # Create audit log
        await db.audit_logs.insert_one({
            "id": str(uuid.uuid4()),
            "action": "incoming_marked_scrap",
            "entity_type": "incoming_queue",
            "entity_id": queue_id,
            "entity_name": queue_entry.get("queue_number"),
            "performed_by": user["id"],
            "performed_by_name": f"{user['first_name']} {user['last_name']}",
            "details": {
                "classification": "scrap",
                "scrap_reason": classify_data.scrap_reason,
                "tracking_id": queue_entry.get("tracking_id")
            },
            "timestamp": now.isoformat()
        })
    
    # ============ END CLASSIFICATION LOGIC ============
    
    # Update the queue entry
    await db.incoming_queue.update_one({"id": queue_id}, {"$set": update_data})
    
    # Fetch and return updated entry
    updated_entry = await db.incoming_queue.find_one({"id": queue_id}, {"_id": 0})
    return IncomingQueueResponse(**updated_entry)

# ==================== ADMIN ENDPOINTS ====================

@api_router.get("/admin/stats")
async def get_admin_stats(user: dict = Depends(require_roles(["admin"]))):
    """Get comprehensive admin dashboard stats"""
    now = datetime.now(timezone.utc)
    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
    
    # Ticket stats
    total_tickets = await db.tickets.count_documents({})
    open_tickets = await db.tickets.count_documents({"status": {"$nin": ["closed", "closed_by_agent", "resolved_on_call", "delivered"]}})
    today_tickets = await db.tickets.count_documents({"created_at": {"$gte": today_start}})
    hardware_tickets = await db.tickets.count_documents({"support_type": "hardware"})
    phone_tickets = await db.tickets.count_documents({"support_type": "phone"})
    
    # SLA breached tickets
    sla_breached = await db.tickets.count_documents({
        "status": {"$nin": ["closed", "closed_by_agent", "resolved_on_call", "delivered"]},
        "sla_due": {"$lt": now.isoformat()}
    })
    
    # Other stats
    total_customers = await db.users.count_documents({"role": "customer"})
    pending_warranties = await db.warranties.count_documents({"status": "pending"})
    pending_extensions = await db.warranties.count_documents({"extension_status": "pending"})
    pending_dispatches = await db.dispatches.count_documents({"status": {"$in": ["pending_label", "ready_for_dispatch"]}})
    
    # Tickets by status for charts
    status_pipeline = [
        {"$group": {"_id": "$status", "count": {"$sum": 1}}}
    ]
    status_counts = await db.tickets.aggregate(status_pipeline).to_list(20)
    
    return {
        "total_tickets": total_tickets,
        "open_tickets": open_tickets,
        "today_tickets": today_tickets,
        "hardware_tickets": hardware_tickets,
        "phone_tickets": phone_tickets,
        "sla_breaches": sla_breached,
        "total_customers": total_customers,
        "pending_warranties": pending_warranties,
        "pending_extensions": pending_extensions,
        "pending_dispatches": pending_dispatches,
        "tickets_by_status": {s["_id"]: s["count"] for s in status_counts}
    }

@api_router.get("/admin/dashboard/executive")
async def admin_dashboard_executive(user: dict = Depends(require_roles(["admin"]))):
    """
    Consolidated data for the Executive Overview admin homepage:
    revenue (this/last month + 30-day trend), support health, sales, stock.
    All figures are computed from live collections.
    """
    now = datetime.now(timezone.utc)
    today = now.strftime("%Y-%m-%d")
    month_start = now.replace(day=1).strftime("%Y-%m-%d")
    last_month_end = now.replace(day=1) - timedelta(days=1)
    last_month_start = last_month_end.replace(day=1)
    d30_start = (now - timedelta(days=29)).strftime("%Y-%m-%d")
    d14_start = (now - timedelta(days=13)).strftime("%Y-%m-%d")

    def _daykey(offset):
        return (now - timedelta(days=offset)).strftime("%Y-%m-%d")

    # ---------- Revenue (sales_invoices, by invoice_date|created_at) ----------
    rev_rows = await db.sales_invoices.aggregate([
        {"$addFields": {"_d": {"$substr": [{"$ifNull": ["$invoice_date", "$created_at"]}, 0, 10]}}},
        {"$match": {"_d": {"$gte": d30_start}}},
        {"$group": {"_id": "$_d",
                    "rev": {"$sum": {"$ifNull": ["$grand_total", 0]}},
                    "cnt": {"$sum": 1}}},
    ]).to_list(2000)
    rev_by_day = {r["_id"]: round(r["rev"] or 0, 2) for r in rev_rows}
    cnt_by_day = {r["_id"]: r["cnt"] for r in rev_rows}

    revenue_trend = [{"date": _daykey(i), "value": rev_by_day.get(_daykey(i), 0)}
                     for i in range(29, -1, -1)]
    # This-month totals: sum the FULL calendar month, not the rolling 30-day window
    # (the window starts at now-29d, so near month-start it would silently drop the 1st/2nd).
    mtd = await db.sales_invoices.aggregate([
        {"$addFields": {"_d": {"$substr": [{"$ifNull": ["$invoice_date", "$created_at"]}, 0, 10]}}},
        {"$match": {"_d": {"$gte": month_start, "$lte": today}}},
        {"$group": {"_id": None,
                    "rev": {"$sum": {"$ifNull": ["$grand_total", 0]}},
                    "cnt": {"$sum": 1}}},
    ]).to_list(1)
    this_month_rev = round(mtd[0]["rev"], 2) if mtd else 0
    orders_month = mtd[0]["cnt"] if mtd else 0
    today_rev = rev_by_day.get(today, 0)

    lm = await db.sales_invoices.aggregate([
        {"$addFields": {"_d": {"$substr": [{"$ifNull": ["$invoice_date", "$created_at"]}, 0, 10]}}},
        {"$match": {"_d": {"$gte": last_month_start.strftime("%Y-%m-%d"),
                           "$lte": last_month_end.strftime("%Y-%m-%d")}}},
        {"$group": {"_id": None, "rev": {"$sum": {"$ifNull": ["$grand_total", 0]}}}},
    ]).to_list(1)
    last_month_rev = round(lm[0]["rev"], 2) if lm else 0
    delta_pct = round((this_month_rev - last_month_rev) / last_month_rev * 100, 1) if last_month_rev else None

    sales_trend_14d = [rev_by_day.get(_daykey(i), 0) for i in range(13, -1, -1)]

    # ---------- Support ----------
    closed_set = ["closed", "closed_by_agent", "resolved_on_call", "resolved", "delivered"]
    open_tickets = await db.tickets.count_documents({"status": {"$nin": closed_set}})
    breached = await db.tickets.count_documents({
        "status": {"$nin": closed_set}, "sla_due": {"$lt": now.isoformat()}
    })
    sla_pct = round((open_tickets - breached) / open_tickets * 100, 1) if open_tickets else 100.0

    res_rows = await db.tickets.aggregate([
        {"$addFields": {"_d": {"$substr": [{"$ifNull": ["$closed_at", ""]}, 0, 10]}}},
        {"$match": {"_d": {"$gte": d14_start}}},
        {"$group": {"_id": "$_d", "n": {"$sum": 1}}},
    ]).to_list(100)
    res_by_day = {r["_id"]: r["n"] for r in res_rows}
    resolved_14d = [res_by_day.get(_daykey(i), 0) for i in range(13, -1, -1)]

    # ---------- Stock (current balance per item from inventory_ledger) ----------
    active_skus = await db.master_skus.count_documents({"is_active": True})
    low_count, total_units = 0, 0
    try:
        stock_rows = await db.inventory_ledger.aggregate([
            {"$sort": {"created_at": 1}},
            {"$group": {"_id": {"item": "$item_id", "firm": "$firm_id"},
                        "bal": {"$last": "$running_balance"}}},
        ]).to_list(50000)
        per_item = {}
        for s in stock_rows:
            per_item[s["_id"]["item"]] = per_item.get(s["_id"]["item"], 0) + (s["bal"] or 0)
        total_units = int(sum(v for v in per_item.values() if v and v > 0))
        low_count = sum(1 for v in per_item.values() if v is not None and 0 < v <= 5)
    except Exception as e:
        logger.warning(f"executive dashboard stock calc failed: {e}")

    # ---------- Action items (for the alert row) ----------
    pending_warranties = await db.warranties.count_documents({"status": "pending"})
    pending_dispatches = await db.dispatches.count_documents(
        {"status": {"$in": ["pending_label", "ready_for_dispatch"]}})

    return {
        "month_label": now.strftime("%B %Y"),
        "generated_at": now.isoformat(),
        "revenue": {
            "this_month": this_month_rev,
            "last_month": last_month_rev,
            "delta_pct": delta_pct,
            "today": today_rev,
            "trend_30d": revenue_trend,
        },
        "support": {
            "open": open_tickets,
            "breached": breached,
            "sla_pct": sla_pct,
            "resolved_14d": resolved_14d,
        },
        "sales": {
            "orders_month": orders_month,
            "today_revenue": today_rev,
            "trend_14d": sales_trend_14d,
        },
        "stock": {
            "active_skus": active_skus,
            "low_count": low_count,
            "total_units": total_units,
        },
        "action_items": {
            "sla_breaches": breached,
            "pending_warranties": pending_warranties,
            "pending_dispatches": pending_dispatches,
        },
    }


@api_router.get("/admin/customers")
async def get_admin_customers(
    search: Optional[str] = None,
    page: int = 1,
    limit: int = 50,
    user: dict = Depends(require_roles(["admin"]))
):
    """Get all customers with their tickets and warranties - paginated"""
    query = {"role": "customer"}
    
    if search:
        query["$or"] = [
            {"first_name": {"$regex": search, "$options": "i"}},
            {"last_name": {"$regex": search, "$options": "i"}},
            {"email": {"$regex": search, "$options": "i"}},
            {"phone": {"$regex": search, "$options": "i"}}
        ]
    
    # Get total count
    total_count = await db.users.count_documents(query)
    total_pages = (total_count + limit - 1) // limit
    
    skip = (page - 1) * limit
    customers = await db.users.find(query, {"_id": 0, "password_hash": 0}).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)

    # Enrich with tickets and warranties in 2 round-trips total (not 2×N) by
    # batching the lookups across all customer_ids on this page.
    customer_ids = [c["id"] for c in customers]
    if customer_ids:
        ticket_rows = await db.tickets.find(
            {"customer_id": {"$in": customer_ids}},
            {"_id": 0, "id": 1, "customer_id": 1, "ticket_number": 1,
             "status": 1, "device_type": 1, "created_at": 1},
        ).sort("created_at", -1).to_list(50 * max(len(customer_ids), 1))
        warranty_rows = await db.warranties.find(
            {"customer_id": {"$in": customer_ids}},
            {"_id": 0, "id": 1, "customer_id": 1, "warranty_number": 1,
             "status": 1, "device_type": 1, "warranty_end_date": 1},
        ).sort("created_at", -1).to_list(50 * max(len(customer_ids), 1))
        tickets_by_cid: dict[str, list] = {}
        for t in ticket_rows:
            tickets_by_cid.setdefault(t["customer_id"], []).append(t)
        warranties_by_cid: dict[str, list] = {}
        for w in warranty_rows:
            warranties_by_cid.setdefault(w["customer_id"], []).append(w)
        for customer in customers:
            customer["tickets"] = tickets_by_cid.get(customer["id"], [])[:50]
            customer["warranties"] = warranties_by_cid.get(customer["id"], [])[:50]
    else:
        for customer in customers:
            customer["tickets"] = []
            customer["warranties"] = []

    return {
        "customers": customers,
        "total": total_count,
        "page": page,
        "limit": limit,
        "total_pages": total_pages
    }

class CustomerCreate(BaseModel):
    first_name: str
    last_name: str
    email: str
    phone: str
    address: Optional[str] = None
    city: Optional[str] = None
    state: Optional[str] = None
    pincode: Optional[str] = None

class CustomerUpdate(BaseModel):
    first_name: Optional[str] = None
    last_name: Optional[str] = None
    email: Optional[str] = None
    phone: Optional[str] = None
    address: Optional[str] = None
    city: Optional[str] = None
    state: Optional[str] = None
    pincode: Optional[str] = None

@api_router.post("/admin/customers")
async def create_customer(
    customer_data: CustomerCreate,
    user: dict = Depends(require_roles(["admin"]))
):
    """Admin creates a new customer"""
    # Check for duplicate email
    existing_email = await db.users.find_one({"email": customer_data.email.lower()})
    if existing_email:
        raise HTTPException(status_code=400, detail="Email already exists")
    
    # Check for duplicate phone
    existing_phone = await db.users.find_one({"phone": customer_data.phone})
    if existing_phone:
        raise HTTPException(status_code=400, detail="Phone number already exists")
    
    customer_id = str(uuid.uuid4())
    now = datetime.now(timezone.utc).isoformat()
    
    customer_doc = {
        "id": customer_id,
        "email": customer_data.email.lower(),
        "first_name": customer_data.first_name,
        "last_name": customer_data.last_name,
        "phone": customer_data.phone,
        "role": "customer",
        "password_hash": hash_password(str(uuid.uuid4())[:8]),  # Random temp password
        "address": customer_data.address,
        "city": customer_data.city,
        "state": customer_data.state,
        "pincode": customer_data.pincode,
        "created_at": now,
        "updated_at": now,
        "created_by_admin": user["id"]
    }
    
    await db.users.insert_one(customer_doc)
    del customer_doc["password_hash"]
    if "_id" in customer_doc:
        del customer_doc["_id"]
    return customer_doc

@api_router.patch("/admin/customers/{customer_id}")
async def update_customer(
    customer_id: str,
    customer_data: CustomerUpdate,
    user: dict = Depends(require_roles(["admin"]))
):
    """Admin updates a customer's details"""
    customer = await db.users.find_one({"id": customer_id, "role": "customer"}, {"_id": 0})
    if not customer:
        raise HTTPException(status_code=404, detail="Customer not found")
    
    update_data = {"updated_at": datetime.now(timezone.utc).isoformat()}
    
    if customer_data.first_name:
        update_data["first_name"] = customer_data.first_name
    if customer_data.last_name:
        update_data["last_name"] = customer_data.last_name
    if customer_data.email:
        # Check if email is taken by another user
        existing = await db.users.find_one({"email": customer_data.email.lower(), "id": {"$ne": customer_id}})
        if existing:
            raise HTTPException(status_code=400, detail="Email already in use")
        update_data["email"] = customer_data.email.lower()
    if customer_data.phone:
        # Check if phone is taken by another user
        existing = await db.users.find_one({"phone": customer_data.phone, "id": {"$ne": customer_id}})
        if existing:
            raise HTTPException(status_code=400, detail="Phone number already in use")
        update_data["phone"] = customer_data.phone
    if customer_data.address is not None:
        update_data["address"] = customer_data.address
    if customer_data.city is not None:
        update_data["city"] = customer_data.city
    if customer_data.state is not None:
        update_data["state"] = customer_data.state
    if customer_data.pincode is not None:
        update_data["pincode"] = customer_data.pincode
    
    await db.users.update_one({"id": customer_id}, {"$set": update_data})
    
    updated_customer = await db.users.find_one({"id": customer_id}, {"_id": 0, "password_hash": 0})
    return updated_customer

@api_router.delete("/admin/customers/{customer_id}")
async def delete_customer(
    customer_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Admin deletes a customer - blocked if customer has tickets, warranties, or orders"""
    customer = await db.users.find_one({"id": customer_id, "role": "customer"}, {"_id": 0})
    if not customer:
        raise HTTPException(status_code=404, detail="Customer not found")
    
    # Check for existing tickets
    ticket_count = await db.tickets.count_documents({"customer_id": customer_id})
    if ticket_count > 0:
        raise HTTPException(
            status_code=400, 
            detail=f"Cannot delete customer with {ticket_count} existing ticket(s). Consider deactivating instead."
        )
    
    # Check for existing warranties
    warranty_count = await db.warranties.count_documents({"customer_id": customer_id})
    if warranty_count > 0:
        raise HTTPException(
            status_code=400, 
            detail=f"Cannot delete customer with {warranty_count} existing warranty registration(s). Consider deactivating instead."
        )
    
    # Check for existing orders
    order_count = await db.orders.count_documents({"customer_id": customer_id})
    if order_count > 0:
        raise HTTPException(
            status_code=400, 
            detail=f"Cannot delete customer with {order_count} existing order(s). Consider deactivating instead."
        )
    
    # Safe to delete
    await db.users.delete_one({"id": customer_id})
    
    return {"message": "Customer deleted successfully"}

@api_router.get("/admin/users")
async def get_admin_users(
    include_customers: bool = False,
    user: dict = Depends(require_roles(["admin"]))
):
    """Get all users (staff only by default, or all if include_customers=true)"""
    query = {} if include_customers else {"role": {"$ne": "customer"}}
    users = await db.users.find(
        query,
        {"_id": 0, "password_hash": 0}
    ).sort("created_at", -1).to_list(10000)
    return users

@api_router.post("/admin/users")
async def create_admin_user(user_data: UserCreate, user: dict = Depends(require_roles(["admin"]))):
    """Create internal user"""
    if user_data.role not in ROLES or user_data.role == "customer":
        raise HTTPException(status_code=400, detail="Invalid role")
    
    existing = await db.users.find_one({"email": user_data.email.lower()})
    if existing:
        raise HTTPException(status_code=400, detail="Email already exists")
    
    user_id = str(uuid.uuid4())
    now = datetime.now(timezone.utc).isoformat()
    
    user_doc = {
        "id": user_id,
        "email": user_data.email.lower(),
        "first_name": user_data.first_name,
        "last_name": user_data.last_name,
        "phone": user_data.phone,
        "role": user_data.role,
        "password_hash": hash_password(user_data.password),
        "address": user_data.address,
        "city": user_data.city,
        "state": user_data.state,
        "pincode": user_data.pincode,
        "created_at": now,
        "updated_at": now
    }
    
    await db.users.insert_one(user_doc)
    del user_doc["password_hash"]
    del user_doc["_id"]
    return user_doc

@api_router.patch("/admin/users/{user_id}")
async def update_user(
    user_id: str,
    first_name: Optional[str] = None,
    last_name: Optional[str] = None,
    email: Optional[str] = None,
    phone: Optional[str] = None,
    role: Optional[str] = None,
    password: Optional[str] = None,
    user: dict = Depends(require_roles(["admin"]))
):
    """Update user details"""
    target_user = await db.users.find_one({"id": user_id}, {"_id": 0})
    if not target_user:
        raise HTTPException(status_code=404, detail="User not found")
    
    update_data = {"updated_at": datetime.now(timezone.utc).isoformat()}
    
    if first_name:
        update_data["first_name"] = first_name
    if last_name:
        update_data["last_name"] = last_name
    if email:
        # Check if email is already taken by another user
        existing = await db.users.find_one({"email": email.lower(), "id": {"$ne": user_id}})
        if existing:
            raise HTTPException(status_code=400, detail="Email already in use")
        update_data["email"] = email.lower()
    if phone:
        update_data["phone"] = phone
    if role:
        if role not in ROLES:
            raise HTTPException(status_code=400, detail="Invalid role")
        update_data["role"] = role
    if password:
        if len(password) < 6:
            raise HTTPException(status_code=400, detail="Password must be at least 6 characters")
        update_data["password_hash"] = hash_password(password)
    
    await db.users.update_one({"id": user_id}, {"$set": update_data})
    
    updated_user = await db.users.find_one({"id": user_id}, {"_id": 0, "password_hash": 0})
    return updated_user


@api_router.delete("/admin/users/{user_id}")
async def delete_user(
    user_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Delete a user (admin only)"""
    # Check if user exists
    existing_user = await db.users.find_one({"id": user_id})
    if not existing_user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Prevent deleting yourself
    if user_id == user["id"]:
        raise HTTPException(status_code=400, detail="Cannot delete your own account")
    
    # Prevent deleting the last admin
    if existing_user.get("role") == "admin":
        admin_count = await db.users.count_documents({"role": "admin"})
        if admin_count <= 1:
            raise HTTPException(status_code=400, detail="Cannot delete the last admin user")
    
    # Delete the user
    await db.users.delete_one({"id": user_id})
    
    # Log the deletion
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "user_deleted",
        "entity_type": "user",
        "entity_id": user_id,
        "entity_name": f"{existing_user.get('first_name')} {existing_user.get('last_name')}",
        "performed_by": user["id"],
        "performed_by_name": f"{user['first_name']} {user['last_name']}",
        "details": {
            "deleted_user_email": existing_user.get("email"),
            "deleted_user_role": existing_user.get("role")
        },
        "timestamp": datetime.now(timezone.utc).isoformat()
    })
    
    return {"message": "User deleted successfully", "user_id": user_id}


@api_router.get("/admin/agent-performance")
async def get_agent_performance(
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    user: dict = Depends(require_roles(["admin"]))
):
    """Get detailed agent performance analytics for team meetings"""
    # Get all agents (support, supervisor, technicians, accountants)
    agents = await db.users.find(
        {"role": {"$in": ["call_support", "supervisor", "service_agent", "accountant"]}},
        {"_id": 0, "id": 1, "first_name": 1, "last_name": 1, "role": 1, "email": 1}
    ).to_list(50)
    
    performance = []
    now = datetime.now(timezone.utc)
    
    for agent in agents:
        # Build query
        query = {"assigned_to": agent["id"]}
        if from_date:
            query["created_at"] = {"$gte": from_date}
        if to_date:
            if "created_at" in query:
                query["created_at"]["$lte"] = to_date
            else:
                query["created_at"] = {"$lte": to_date}
        
        # Get ticket stats
        total = await db.tickets.count_documents(query)
        closed = await db.tickets.count_documents({**query, "status": {"$in": ["closed", "closed_by_agent", "resolved_on_call"]}})
        hardware = await db.tickets.count_documents({**query, "support_type": "hardware"})
        phone = await db.tickets.count_documents({**query, "support_type": "phone"})
        sla_breached = await db.tickets.count_documents({**query, "sla_due": {"$lt": now.isoformat()}, "status": {"$nin": ["closed", "closed_by_agent", "resolved_on_call"]}})
        
        # Calculate average resolution time
        closed_tickets = await db.tickets.find(
            {**query, "closed_at": {"$ne": None}},
            {"_id": 0, "created_at": 1, "closed_at": 1}
        ).to_list(1000)
        
        avg_hours = 0
        if closed_tickets:
            total_hours = 0
            for t in closed_tickets:
                try:
                    created = datetime.fromisoformat(t["created_at"].replace('Z', '+00:00'))
                    closed_time = datetime.fromisoformat(t["closed_at"].replace('Z', '+00:00'))
                    total_hours += (closed_time - created).total_seconds() / 3600
                except:
                    pass
            avg_hours = total_hours / len(closed_tickets) if closed_tickets else 0
        
        sla_compliance = ((total - sla_breached) / total * 100) if total > 0 else 100
        
        performance.append(AgentPerformance(
            agent_id=agent["id"],
            agent_name=f"{agent['first_name']} {agent['last_name']}",
            total_tickets=total,
            closed_tickets=closed,
            hardware_tickets=hardware,
            phone_tickets=phone,
            sla_breaches=sla_breached,
            avg_resolution_hours=round(avg_hours, 2),
            sla_compliance_rate=round(sla_compliance, 2)
        ))
    
    return performance

@api_router.get("/admin/tickets")
async def get_all_tickets_admin(
    search: Optional[str] = None,
    status: Optional[str] = None,
    support_type: Optional[str] = None,
    sla_breached: Optional[bool] = None,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    page: int = 1,
    limit: int = 50,
    user: dict = Depends(require_roles(["admin"]))
):
    """Get all tickets for admin view with pagination"""
    query = {}
    
    if search:
        query["$or"] = [
            {"ticket_number": {"$regex": search, "$options": "i"}},
            {"customer_name": {"$regex": search, "$options": "i"}},
            {"customer_phone": {"$regex": search, "$options": "i"}},
            {"serial_number": {"$regex": search, "$options": "i"}}
        ]
    if status and status != "all":
        query["status"] = status
    if support_type and support_type != "all":
        query["support_type"] = support_type
    if from_date:
        query["created_at"] = {"$gte": from_date}
    if to_date:
        if "created_at" in query:
            query["created_at"]["$lte"] = to_date
        else:
            query["created_at"] = {"$lte": to_date}
    
    # Get total count first
    total_count = await db.tickets.count_documents(query)
    total_pages = (total_count + limit - 1) // limit
    
    skip = (page - 1) * limit
    tickets = await db.tickets.find(query, {"_id": 0}).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    
    # Update SLA status
    now = datetime.now(timezone.utc)
    filtered_tickets = []
    for ticket in tickets:
        if ticket.get("sla_due"):
            try:
                sla_due = datetime.fromisoformat(ticket["sla_due"].replace('Z', '+00:00'))
                ticket["sla_breached"] = is_sla_breached(sla_due, ticket["status"])
            except:
                ticket["sla_breached"] = False
        else:
            ticket["sla_breached"] = False
        
        # Filter by SLA breach if requested
        if sla_breached is not None:
            if sla_breached == ticket.get("sla_breached", False):
                filtered_tickets.append(ticket)
        else:
            filtered_tickets.append(ticket)
    
    # If filtering by SLA breach, adjust total count
    if sla_breached is not None:
        # Need to recount with SLA filter (not efficient but accurate)
        all_for_sla = await db.tickets.find(query, {"_id": 0, "sla_due": 1, "status": 1}).to_list(10000)
        sla_count = 0
        for t in all_for_sla:
            if t.get("sla_due"):
                try:
                    sla_due = datetime.fromisoformat(t["sla_due"].replace('Z', '+00:00'))
                    is_breach = is_sla_breached(sla_due, t["status"])
                    if sla_breached == is_breach:
                        sla_count += 1
                except:
                    if not sla_breached:
                        sla_count += 1
            elif not sla_breached:
                sla_count += 1
        total_count = sla_count
        total_pages = (total_count + limit - 1) // limit
    
    return {
        "tickets": filtered_tickets if sla_breached is not None else tickets,
        "total": total_count,
        "page": page,
        "limit": limit,
        "total_pages": total_pages
    }

