# ==================== FILE SERVING ====================

ALLOWED_FILE_FOLDERS = {
    "invoices", "labels", "reviews", "service_invoices", "pickup_labels",
    "dispatches", "dealer_documents", "dealer_payments", "ewaybills",
    "claude_files", "purchases", "expenses", "gate", "gate_media", "bot",
    "datasheets", "amazon", "bigship", "warranty_invoices", "feedback",
    "tickets", "uploads", "payroll", "kyc", "product_images",
    "amazon_orders", "chat",
}


def _safe_uploads_path(folder: str, filename: str) -> Path:
    """Resolve {folder}/{filename} under UPLOAD_DIR, rejecting traversal."""
    # Allowlist check is case-insensitive (some legacy uploads used "Dispatches"
    # with a capital D); the original casing is kept for the on-disk path so it
    # still matches the real directory.
    if folder.lower() not in ALLOWED_FILE_FOLDERS:
        raise HTTPException(status_code=404, detail="Unknown folder")
    if "/" in filename or "\\" in filename or filename.startswith("."):
        raise HTTPException(status_code=400, detail="Invalid filename")
    base = UPLOAD_DIR.resolve()
    target = (base / folder / filename).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise HTTPException(status_code=400, detail="Path traversal denied")
    return target


def _safe_nested_uploads_path(relative_path: str) -> Path:
    """Validate a nested file path like
    'amazon_orders/2026/05-May/25/{order_id}/label_xxx.pdf' — first segment
    must be an allowed folder, no traversal segments anywhere, and the
    resolved path must stay inside UPLOAD_DIR.
    """
    rel = relative_path.strip("/")
    if not rel:
        raise HTTPException(status_code=400, detail="Empty path")
    parts = rel.split("/")
    if parts[0] not in ALLOWED_FILE_FOLDERS:
        raise HTTPException(status_code=404, detail="Unknown folder")
    if any(p in ("", ".", "..") or p.startswith(".") for p in parts):
        raise HTTPException(status_code=400, detail="Invalid path segment")
    if any("\\" in p for p in parts):
        raise HTTPException(status_code=400, detail="Invalid path segment")
    base = UPLOAD_DIR.resolve()
    target = (base.joinpath(*parts)).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise HTTPException(status_code=400, detail="Path traversal denied")
    return target


@api_router.get("/files/{folder}/{filename}")
async def serve_file(
    folder: str,
    filename: str,
    exp: Optional[str] = Query(None),
    sig: Optional[str] = Query(None),
    u: Optional[str] = Query(None),
    user: Optional[dict] = Depends(get_current_user_optional),
):
    """Serve uploaded files. Requires either a Bearer JWT or a signed URL."""
    relative_path = f"{folder}/{filename}"
    # Path traversal + folder allowlist (also rejects ../).
    _safe_uploads_path(folder, filename)
    if not user:
        if not (sig and exp and verify_signed_file_url(relative_path, exp, sig, u)):
            raise HTTPException(status_code=401, detail="Authentication required")
    elif user.get("role") == "dealer":
        # A dealer's bare Bearer token is NOT sufficient to fetch arbitrary files —
        # that let any dealer read another dealer's invoices / payment proofs /
        # deposit receipts just by knowing the path. Dealers must present a signed,
        # user-bound URL (which /dealer/documents now always issues), and the URL's
        # user binding must match the caller — so one dealer can't replay another's
        # signed link either.
        if not (sig and exp and verify_signed_file_url(relative_path, exp, sig, u) and u == user["id"]):
            raise HTTPException(status_code=403, detail="Access denied")

    # Try to download from storage (WebDAV or local)
    try:
        file_data = await storage_download(relative_path)
        
        if file_data is None:
            # Fallback: Check local uploads directory for legacy files
            file_path = UPLOAD_DIR / folder / filename
            if file_path.exists():
                # Serve from local fallback
                ext = Path(filename).suffix.lower()
                media_types = {
                    '.pdf': 'application/pdf',
                    '.png': 'image/png',
                    '.jpg': 'image/jpeg',
                    '.jpeg': 'image/jpeg',
                    '.gif': 'image/gif',
                    '.heic': 'image/heic',
                    '.heif': 'image/heif',
                    '.webp': 'image/webp'
                }
                media_type = media_types.get(ext, 'application/octet-stream')
                safe_name = filename.replace('"', '').replace('\r', '').replace('\n', '')
                return FileResponse(
                    file_path,
                    media_type=media_type,
                    filename=safe_name,
                    headers={
                        "Content-Disposition": f'inline; filename="{safe_name}"',
                        "X-Content-Type-Options": "nosniff",
                    }
                )
            raise HTTPException(status_code=404, detail="File not found")
        
        # Determine media type
        ext = Path(filename).suffix.lower()
        media_types = {
            '.pdf': 'application/pdf',
            '.png': 'image/png',
            '.jpg': 'image/jpeg',
            '.jpeg': 'image/jpeg',
            '.gif': 'image/gif',
            '.heic': 'image/heic',
            '.heif': 'image/heif',
            '.webp': 'image/webp',
            '.doc': 'application/msword',
            '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            '.xls': 'application/vnd.ms-excel',
            '.xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        }
        media_type = media_types.get(ext, 'application/octet-stream')
        
        safe_name = filename.replace('"', '').replace('\r', '').replace('\n', '')
        return StreamingResponse(
            BytesIO(file_data),
            media_type=media_type,
            headers={
                "Content-Disposition": f'inline; filename="{safe_name}"',
                "X-Content-Type-Options": "nosniff",
                "Content-Length": str(len(file_data))
            }
        )

    except StorageError as e:
        logger.error(f"Storage error serving file {relative_path}: {str(e)}")
        # Do not echo backend storage error text to caller.
        raise HTTPException(status_code=502, detail="Storage backend error")


@api_router.get("/files/check/{folder}/{filename}")
async def check_file_exists(
    folder: str,
    filename: str,
    user: dict = Depends(get_current_user),
):
    """Check if a file exists without downloading it. Requires auth."""
    _safe_uploads_path(folder, filename)
    relative_path = f"{folder}/{filename}"
    exists = await storage_file_exists(relative_path)

    # Fallback check local for legacy files
    if not exists:
        file_path = UPLOAD_DIR / folder / filename
        exists = file_path.exists()

    return {"exists": exists, "path": f"/api/files/{folder}/{filename}"}


@api_router.get("/files-deep/{relative_path:path}")
async def serve_file_deep(
    relative_path: str,
    exp: Optional[str] = Query(None),
    sig: Optional[str] = Query(None),
    u: Optional[str] = Query(None),
    user: Optional[dict] = Depends(get_current_user_optional),
):
    """Same as /files/{folder}/{filename} but supports arbitrary nesting —
    e.g. 'amazon_orders/2026/05-May/25/{order_id}/label_xxx.pdf'. The
    original 2-segment route stays in place for legacy callers."""
    _safe_nested_uploads_path(relative_path)
    if not user:
        if not (sig and exp and verify_signed_file_url(relative_path, exp, sig, u)):
            raise HTTPException(status_code=401, detail="Authentication required")
    try:
        file_data = await storage_download(relative_path)
        if file_data is None:
            local = UPLOAD_DIR / relative_path
            if local.exists():
                file_data = local.read_bytes()
            else:
                raise HTTPException(status_code=404, detail="File not found")
        filename = relative_path.rsplit("/", 1)[-1]
        ext = Path(filename).suffix.lower()
        media_types = {
            ".pdf": "application/pdf",
            ".png": "image/png",
            ".jpg": "image/jpeg",
            ".jpeg": "image/jpeg",
            ".gif": "image/gif",
            ".webp": "image/webp",
        }
        media_type = media_types.get(ext, "application/octet-stream")
        safe_name = filename.replace('"', "").replace("\r", "").replace("\n", "")
        return StreamingResponse(
            BytesIO(file_data),
            media_type=media_type,
            headers={
                "Content-Disposition": f'inline; filename="{safe_name}"',
                "X-Content-Type-Options": "nosniff",
                "Content-Length": str(len(file_data)),
            },
        )
    except StorageError as e:
        logger.error(f"Storage error serving {relative_path}: {e}")
        raise HTTPException(status_code=502, detail="Storage backend error")

