@api_router.put("/supervisor-payables/{payable_id}/payment")
async def record_payable_payment(
    payable_id: str,
    payment_data: SupervisorPayableUpdate,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Record a payment against a supervisor payable"""
    payable = await db.supervisor_payables.find_one({"id": payable_id})
    if not payable:
        raise HTTPException(status_code=404, detail="Payable not found")
    
    if payable.get("status") == "paid":
        raise HTTPException(status_code=400, detail="Payable is already fully paid")
    
    amount_paid = payment_data.amount_paid or 0
    if amount_paid <= 0:
        raise HTTPException(status_code=400, detail="Payment amount must be greater than 0")
    
    current_paid = payable.get("amount_paid", 0)
    total_payable = payable.get("total_payable", 0)
    new_total_paid = current_paid + amount_paid
    
    if new_total_paid > total_payable:
        raise HTTPException(status_code=400, detail=f"Payment exceeds pending amount. Pending: {total_payable - current_paid}")
    
    # Determine new status
    if new_total_paid >= total_payable:
        new_status = "paid"
    elif new_total_paid > 0:
        new_status = "part_paid"
    else:
        new_status = "unpaid"
    
    now = datetime.now(timezone.utc).isoformat()
    
    # Record payment
    payment_record = {
        "id": str(uuid.uuid4()),
        "amount": amount_paid,
        "reference": payment_data.payment_reference,
        "remarks": payment_data.remarks,
        "paid_by": user["id"],
        "paid_by_name": user.get("name", user.get("email")),
        "paid_at": now
    }
    
    await db.supervisor_payables.update_one(
        {"id": payable_id},
        {
            "$set": {
                "amount_paid": new_total_paid,
                "status": new_status,
                "updated_at": now
            },
            "$push": {"payments": payment_record}
        }
    )

    # Post the DEBIT to the contractor's party ledger. Payable creation posts a
    # credit ("we owe them"); this is the matching debit ("we paid"). Without it
    # the contractor's ledger balance never came down after payment.
    contractor_party_id = payable.get("contractor_party_id")
    if contractor_party_id:
        last_ledger = await db.party_ledger.find_one(
            {"party_id": contractor_party_id}, sort=[("created_at", -1)]
        )
        prev_balance = last_ledger.get("running_balance", 0) if last_ledger else 0
        await db.party_ledger.insert_one({
            "id": str(uuid.uuid4()),
            "party_id": contractor_party_id,
            "party_name": payable.get("contractor_name"),
            "entry_type": "payment",
            "reference_type": "production_payment",
            "reference_id": payable_id,
            "reference_number": payable.get("payable_number"),
            "description": f"Payment for production payable {payable.get('payable_number')}",
            "debit": amount_paid,
            "credit": 0,
            "running_balance": prev_balance + amount_paid,  # debit raises balance toward 0
            "firm_id": payable.get("firm_id"),
            "firm_name": payable.get("firm_name"),
            "created_by": user["id"],
            "created_at": now,
        })
    else:
        logger.warning(f"supervisor payable {payable_id} has no contractor_party_id — ledger debit skipped")

    # Audit log
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "supervisor_payment_recorded",
        "entity_type": "supervisor_payable",
        "entity_id": payable_id,
        "user_id": user["id"],
        "user_name": user.get("name", user.get("email")),
        "details": {
            "payable_number": payable.get("payable_number"),
            "amount": amount_paid,
            "new_status": new_status,
            "reference": payment_data.payment_reference
        },
        "created_at": now
    })
    
    return {
        "message": "Payment recorded",
        "status": new_status,
        "total_paid": new_total_paid,
        "pending": total_payable - new_total_paid
    }


