# ==================== FINANCE & GST PLANNING MODULE ====================

# Finance Models
class GSTITCEntry(BaseModel):
    firm_id: str
    month: str  # YYYY-MM format
    igst_balance: float = 0.0
    cgst_balance: float = 0.0
    sgst_balance: float = 0.0
    notes: Optional[str] = None

class DispatchInvoiceValue(BaseModel):
    taxable_value: float
    gst_rate: Optional[float] = None  # Override SKU rate if needed

class FinancialAuditLog(BaseModel):
    action: str
    entity_type: str
    entity_id: str
    details: dict

# Purchase Register Models
class PurchaseItem(BaseModel):
    item_type: str  # "raw_material" or "master_sku"
    item_id: str
    quantity: float
    rate: float  # Unit price before GST
    gst_rate: Optional[float] = None  # Override item's GST rate if needed

class PurchaseCreate(BaseModel):
    firm_id: str
    supplier_name: str
    supplier_gstin: Optional[str] = None
    supplier_state: str
    invoice_number: str
    invoice_date: str  # YYYY-MM-DD
    items: List[PurchaseItem]
    notes: Optional[str] = None
    gst_override: Optional[bool] = False  # Allow manual GST override
    save_as_draft: Optional[bool] = False  # If True, saves as draft even with validation errors
    supplier_invoice_file_url: Optional[str] = None  # URL of uploaded supplier invoice

# GSTIN validation helper
def validate_gstin(gstin: str) -> bool:
    """Validate GSTIN format: 2 digits state code + 10 char PAN + 1 digit + Z + 1 check digit"""
    if not gstin or len(gstin) != 15:
        return False
    import re
    pattern = r'^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$'
    return bool(re.match(pattern, gstin.upper()))

# State code mapping from GSTIN
INDIAN_STATES = {
    "01": "Jammu & Kashmir", "02": "Himachal Pradesh", "03": "Punjab", "04": "Chandigarh",
    "05": "Uttarakhand", "06": "Haryana", "07": "Delhi", "08": "Rajasthan", "09": "Uttar Pradesh",
    "10": "Bihar", "11": "Sikkim", "12": "Arunachal Pradesh", "13": "Nagaland", "14": "Manipur",
    "15": "Mizoram", "16": "Tripura", "17": "Meghalaya", "18": "Assam", "19": "West Bengal",
    "20": "Jharkhand", "21": "Odisha", "22": "Chhattisgarh", "23": "Madhya Pradesh",
    "24": "Gujarat", "26": "Daman & Diu", "27": "Maharashtra", "29": "Karnataka", "30": "Goa",
    "31": "Lakshadweep", "32": "Kerala", "33": "Tamil Nadu", "34": "Puducherry",
    "35": "Andaman & Nicobar", "36": "Telangana", "37": "Andhra Pradesh"
}

def get_state_from_gstin(gstin: str) -> Optional[str]:
    """Extract state name from GSTIN"""
    if gstin and len(gstin) >= 2:
        state_code = gstin[:2]
        return INDIAN_STATES.get(state_code)
    return None

# Helper function to calculate Weighted Average Cost
async def calculate_wac(item_id: str, item_type: str, firm_id: str) -> float:
    """Calculate Weighted Average Cost for an item at a firm"""
    # Get all purchase and production entries for this item
    ledger_entries = await db.inventory_ledger.find({
        "item_id": item_id,
        "item_type": item_type,
        "firm_id": firm_id,
        "entry_type": {"$in": ["purchase", "production_output", "transfer_in"]}
    }).sort("created_at", 1).to_list(10000)
    
    total_qty = 0
    total_value = 0
    
    for entry in ledger_entries:
        qty = entry.get("quantity", 0)
        unit_cost = entry.get("unit_cost", 0)
        if qty > 0 and unit_cost > 0:
            total_qty += qty
            total_value += qty * unit_cost
    
    if total_qty > 0:
        return round(total_value / total_qty, 2)
    
    # Fallback to cost_price from master_sku
    if item_type == "master_sku":
        sku = await db.master_skus.find_one({"id": item_id})
        if sku and sku.get("cost_price"):
            return sku.get("cost_price")
    
    return 0.0

# Helper to log financial actions
async def log_financial_action(action: str, entity_type: str, entity_id: str, details: dict, user: dict):
    """Log financial audit entry"""
    log_entry = {
        "id": str(uuid.uuid4()),
        "action": action,
        "entity_type": entity_type,
        "entity_id": entity_id,
        "details": details,
        "user_id": user["id"],
        "user_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "user_role": user["role"],
        "timestamp": datetime.now(timezone.utc).isoformat()
    }
    await db.financial_audit_logs.insert_one(log_entry)
    return log_entry

@api_router.get("/finance/dashboard")
async def get_finance_dashboard(
    month: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get finance dashboard overview with firm-wise summary (scoped).

    `month` (YYYY-MM) selects the GST period; defaults to the PREVIOUS calendar
    month (the one being filed). Output GST is summed by INVOICE PERIOD
    (invoice_date / invoice_month) — NOT by created_at, which previously lumped
    all recently-imported history into the current month. ITC is wired from the
    reconciled sources in priority: portal (GSTR-3B claimed + Bill-of-Entry
    imports, else GSTR-2B available) -> purchases register -> manual ITC balance.
    """
    # Accountants should only see their own firm in the dashboard.
    firm_query = {"is_active": True}
    scope = get_user_firm_scope(user)
    if scope:
        firm_query["id"] = scope
    firms = await db.firms.find(firm_query, {"_id": 0}).to_list(100)

    firm_summaries = []
    total_inventory_value = 0
    total_receivables = 0
    total_gst_liability = 0

    # GST period to view. Default = previous completed month (typical filing view).
    if month:
        current_month = month
    else:
        _now = datetime.now(timezone.utc)
        current_month = f"{_now.year - 1}-12" if _now.month == 1 else f"{_now.year}-{str(_now.month - 1).zfill(2)}"
    
    for firm in firms:
        firm_id = firm["id"]
        
        # Calculate inventory value (WAC method)
        inventory_value = 0
        
        # Get current stock for this firm
        stock_pipeline = [
            {"$match": {"firm_id": firm_id}},
            {"$group": {
                "_id": {"item_id": "$item_id", "item_type": "$item_type"},
                "total_qty": {"$sum": "$quantity"}
            }},
            {"$match": {"total_qty": {"$gt": 0}}}
        ]
        stock_items = await db.inventory_ledger.aggregate(stock_pipeline).to_list(1000)
        
        for item in stock_items:
            item_id = item["_id"]["item_id"]
            item_type = item["_id"]["item_type"]
            qty = item["total_qty"]
            
            # Get WAC for this item
            wac = await calculate_wac(item_id, item_type, firm_id)
            inventory_value += qty * wac
        
        # Monthly sales BY INVOICE PERIOD (FIX: previously matched created_at, which
        # lumped every recently-imported invoice — years of history — into one month).
        sales_invoices = await db.sales_invoices.find({
            "firm_id": firm_id,
            "$or": [
                {"invoice_month": current_month},                 # YYYY-MM tag (our imports)
                {"invoice_date": {"$regex": f"^{current_month}"}},# YYYY-MM-DD
                {"date": {"$regex": f"^{current_month}"}},        # legacy date field
            ]
        }, {"_id": 0}).to_list(20000)

        monthly_sales = sum(
            (inv.get("grand_total") or inv.get("total_amount") or inv.get("total") or 0)
            for inv in sales_invoices
        )
        monthly_taxable = sum(
            (inv.get("taxable_value") or inv.get("subtotal") or 0)
            for inv in sales_invoices
        )
        output_gst = sum(
            (inv.get("total_gst") or ((inv.get("igst") or 0) + (inv.get("cgst") or 0) + (inv.get("sgst") or 0)) or 0)
            for inv in sales_invoices
        )
        
        # ITC for the period — wired from reconciled sources (FIX: previously only
        # read manual gst_itc_balances, ignoring portal / Bill-of-Entry / purchase ITC).
        # Priority: 1) portal GSTR-3B(claimed) + Bill-of-Entry imports, else GSTR-2B(available)
        #           2) purchases register input GST for the period
        #           3) manual gst_itc_balances entry
        period_mmyyyy = current_month[5:7] + current_month[0:4]  # YYYY-MM -> MMYYYY
        itc_balance = 0
        itc_source = None
        itc_month_used = current_month
        portal = await db.gst_portal_itc.find(
            {"firm_id": firm_id, "period": period_mmyyyy}, {"_id": 0}).to_list(50)
        if portal:
            dom = sum((r.get("itc_total") or 0) for r in portal if r.get("doc") == "GSTR-3B")
            boe = sum((r.get("itc_total") or 0) for r in portal if r.get("doc") == "BOE-import")
            if dom or boe:
                itc_balance = dom + boe
                itc_source = "portal: GSTR-3B" + (" + Bill-of-Entry" if boe else "")
            else:
                itc_balance = max((r.get("itc_total") or 0) for r in portal)
                itc_source = "portal: GSTR-2B"
        if not itc_balance:
            purchases_p = await db.purchases.find(
                {"firm_id": firm_id, "$or": [
                    {"invoice_month": current_month},
                    {"invoice_date": {"$regex": f"^{current_month}"}}]}, {"_id": 0}).to_list(20000)
            if purchases_p:
                itc_balance = sum(
                    (p.get("total_gst") or ((p.get("igst") or 0) + (p.get("cgst") or 0) + (p.get("sgst") or 0)) or 0)
                    for p in purchases_p)
                if itc_balance:
                    itc_source = "purchases register"
        if not itc_balance:
            itc_entry = await db.gst_itc_balances.find_one(
                {"firm_id": firm_id, "month": current_month}, {"_id": 0})
            if itc_entry:
                itc_balance = (itc_entry.get("igst_balance", 0) + itc_entry.get("cgst_balance", 0) + itc_entry.get("sgst_balance", 0))
                if itc_balance:
                    itc_source = "manual ITC balance"

        net_gst_payable = max(0, output_gst - itc_balance)
        
        firm_summary = {
            "firm_id": firm_id,
            "firm_name": firm["name"],
            "gstin": firm.get("gstin", firm.get("gst_number", "")),
            "inventory_value": round(inventory_value, 2),
            "monthly_sales": round(monthly_sales, 2),
            "monthly_taxable": round(monthly_taxable, 2),
            "itc_balance": round(itc_balance, 2),
            "itc_source": itc_source,
            "period": current_month,
            "output_gst": round(output_gst, 2),
            "net_gst_payable": round(net_gst_payable, 2)
        }
        firm_summaries.append(firm_summary)
        
        total_inventory_value += inventory_value
        total_gst_liability += net_gst_payable
    
    # Get pending dispatches (not yet invoiced)
    pending_dispatches = await db.dispatches.count_documents({
        "status": {"$in": ["pending_label", "ready_for_dispatch"]},
        "invoice_value": {"$exists": False}
    })
    
    # Get month-end alerts
    alerts = []
    if pending_dispatches > 0:
        alerts.append({
            "type": "warning",
            "message": f"{pending_dispatches} dispatches pending invoice value entry"
        })
    
    for summary in firm_summaries:
        if summary["net_gst_payable"] > 50000:
            alerts.append({
                "type": "info",
                "message": f"{summary['firm_name']}: High GST liability of Rs.{summary['net_gst_payable']:,.2f}"
            })
        if summary["itc_balance"] == 0:
            alerts.append({
                "type": "warning",
                "message": f"{summary['firm_name']}: No ITC found for {current_month} (no portal GSTR-3B/2B, Bill-of-Entry or purchases) - upload its GSTR-2B / purchase register"
            })
        
        # Stock vs ITC Mismatch Alerts
        stock_gst_value = summary["inventory_value"] * 0.18  # Estimated GST at 18%
        itc_balance = summary["itc_balance"]
        
        # Alert if stock GST value is significantly higher than ITC (possible under-claimed ITC)
        if stock_gst_value > 0 and itc_balance > 0:
            if stock_gst_value > itc_balance * 1.5:  # Stock GST > 1.5x ITC
                alerts.append({
                    "type": "warning",
                    "message": f"{summary['firm_name']}: Stock value (GST: ₹{stock_gst_value:,.0f}) exceeds ITC balance (₹{itc_balance:,.0f}) - verify ITC claims"
                })
            elif itc_balance > stock_gst_value * 2:  # ITC > 2x Stock GST
                alerts.append({
                    "type": "info",
                    "message": f"{summary['firm_name']}: ITC balance (₹{itc_balance:,.0f}) is high relative to stock (GST: ₹{stock_gst_value:,.0f}) - consider stock transfers"
                })
    
    return {
        "current_month": current_month,
        "total_firms": len(firms),
        "total_inventory_value": round(total_inventory_value, 2),
        "total_gst_liability": round(total_gst_liability, 2),
        "firm_summaries": firm_summaries,
        "alerts": alerts,
        "pending_invoice_entries": pending_dispatches
    }

@api_router.get("/finance/firm/{firm_id}/summary")
async def get_firm_financial_summary(
    firm_id: str,
    month: Optional[str] = None,  # YYYY-MM format
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get detailed financial summary for a specific firm"""
    assert_firm_access(user, firm_id)
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    target_month = month or datetime.now(timezone.utc).strftime("%Y-%m")
    year, month_num = map(int, target_month.split("-"))
    month_start = datetime(year, month_num, 1, tzinfo=timezone.utc)
    if month_num == 12:
        month_end = datetime(year + 1, 1, 1, tzinfo=timezone.utc)
    else:
        month_end = datetime(year, month_num + 1, 1, tzinfo=timezone.utc)
    
    # Sales from sales_invoices (more accurate GST data)
    sales_invoices = await db.sales_invoices.find({
        "firm_id": firm_id,
        "invoice_date": {"$gte": month_start.isoformat()[:10], "$lt": month_end.isoformat()[:10]}
    }, {"_id": 0}).to_list(10000)
    
    sales_value = sum(inv.get("grand_total", 0) or 0 for inv in sales_invoices)
    sales_taxable = sum(inv.get("taxable_value", 0) or 0 for inv in sales_invoices)
    sales_count = len(sales_invoices)
    
    # Output GST from sales invoices (accurate CGST/SGST/IGST split)
    output_cgst = sum(inv.get("cgst", 0) or 0 for inv in sales_invoices)
    output_sgst = sum(inv.get("sgst", 0) or 0 for inv in sales_invoices)
    output_igst = sum(inv.get("igst", 0) or 0 for inv in sales_invoices)
    output_gst_total = output_cgst + output_sgst + output_igst
    
    # Calculate GST breakup by rate from sales invoices
    gst_by_rate = {}
    for inv in sales_invoices:
        for item in inv.get("items", []):
            rate = item.get("gst_rate", 18) or 18
            taxable = item.get("taxable_value", 0) or item.get("total", 0) or 0
            gst_amount = item.get("gst_amount", 0) or 0
            if rate not in gst_by_rate:
                gst_by_rate[rate] = {"taxable": 0, "gst": 0, "count": 0}
            gst_by_rate[rate]["taxable"] += taxable
            gst_by_rate[rate]["gst"] += gst_amount
            gst_by_rate[rate]["count"] += 1
    
    # Fallback to dispatches if no sales invoices found
    if not sales_invoices:
        dispatches = await db.dispatches.find({
            "firm_id": firm_id,
            "status": "dispatched",
            "dispatched_at": {"$gte": month_start.isoformat(), "$lt": month_end.isoformat()}
        }, {"_id": 0}).to_list(10000)
        
        sales_value = sum(d.get("invoice_value", 0) or 0 for d in dispatches)
        sales_taxable = sum(d.get("taxable_value", 0) or 0 for d in dispatches)
        sales_count = len(dispatches)
        
        for d in dispatches:
            rate = d.get("gst_rate", 18) or 18
            taxable = d.get("taxable_value", 0) or 0
            if rate not in gst_by_rate:
                gst_by_rate[rate] = {"taxable": 0, "gst": 0, "count": 0}
            gst_by_rate[rate]["taxable"] += taxable
            gst_by_rate[rate]["gst"] += taxable * (rate / 100)
            gst_by_rate[rate]["count"] += 1
        
        output_gst_total = sum(gst_by_rate[r]["gst"] for r in gst_by_rate)
        output_cgst = 0
        output_sgst = 0
        output_igst = output_gst_total
    
    # Purchases from purchases collection (for Input GST / ITC)
    purchase_entries = await db.purchases.find({
        "firm_id": firm_id,
        "invoice_date": {"$gte": month_start.isoformat()[:10], "$lt": month_end.isoformat()[:10]}
    }, {"_id": 0}).to_list(10000)
    
    purchases_value = sum(p.get("grand_total", p.get("total_amount", 0)) or 0 for p in purchase_entries)
    purchases_taxable = sum(p.get("taxable_value", p.get("subtotal", 0)) or 0 for p in purchase_entries)
    purchases_count = len(purchase_entries)
    
    # Input GST from purchases (ITC eligible)
    input_cgst = sum(p.get("cgst", 0) or 0 for p in purchase_entries)
    input_sgst = sum(p.get("sgst", 0) or 0 for p in purchase_entries)
    input_igst = sum(p.get("igst", 0) or 0 for p in purchase_entries)
    input_gst_total = sum(p.get("total_gst", 0) or 0 for p in purchase_entries)
    if input_gst_total == 0:
        input_gst_total = input_cgst + input_sgst + input_igst
    
    # Returns (incoming classified as return_inventory)
    returns = await db.inventory_ledger.find({
        "firm_id": firm_id,
        "entry_type": "return_in",
        "created_at": {"$gte": month_start.isoformat(), "$lt": month_end.isoformat()}
    }, {"_id": 0}).to_list(10000)
    
    returns_value = sum(r.get("quantity", 0) * r.get("unit_cost", 0) for r in returns)
    returns_count = len(returns)
    
    # Transfers In
    transfers_in = await db.inventory_ledger.find({
        "firm_id": firm_id,
        "entry_type": "transfer_in",
        "created_at": {"$gte": month_start.isoformat(), "$lt": month_end.isoformat()}
    }, {"_id": 0}).to_list(10000)
    
    transfers_in_value = sum(t.get("quantity", 0) * t.get("unit_cost", 0) for t in transfers_in)
    transfers_in_count = len(transfers_in)
    
    # Transfers Out
    transfers_out = await db.inventory_ledger.find({
        "firm_id": firm_id,
        "entry_type": "transfer_out",
        "created_at": {"$gte": month_start.isoformat(), "$lt": month_end.isoformat()}
    }, {"_id": 0}).to_list(10000)
    
    transfers_out_value = sum(abs(t.get("quantity", 0)) * t.get("unit_cost", 0) for t in transfers_out)
    transfers_out_count = len(transfers_out)
    
    # Production Output
    production = await db.inventory_ledger.find({
        "firm_id": firm_id,
        "entry_type": "production_output",
        "created_at": {"$gte": month_start.isoformat(), "$lt": month_end.isoformat()}
    }, {"_id": 0}).to_list(10000)
    
    production_value = sum(p.get("quantity", 0) * p.get("unit_cost", 0) for p in production)
    production_count = len(production)
    
    # Current Inventory Value
    inventory_value = 0
    stock_pipeline = [
        {"$match": {"firm_id": firm_id}},
        {"$group": {
            "_id": {"item_id": "$item_id", "item_type": "$item_type"},
            "total_qty": {"$sum": "$quantity"}
        }},
        {"$match": {"total_qty": {"$gt": 0}}}
    ]
    stock_items = await db.inventory_ledger.aggregate(stock_pipeline).to_list(1000)
    
    inventory_details = []
    for item in stock_items:
        item_id = item["_id"]["item_id"]
        item_type = item["_id"]["item_type"]
        qty = item["total_qty"]
        
        wac = await calculate_wac(item_id, item_type, firm_id)
        value = qty * wac
        inventory_value += value
        
        # Get item name
        if item_type == "master_sku":
            sku = await db.master_skus.find_one({"id": item_id}, {"_id": 0, "name": 1, "sku_code": 1})
            item_name = sku.get("name", "Unknown") if sku else "Unknown"
            sku_code = sku.get("sku_code", "") if sku else ""
        else:
            rm = await db.raw_materials.find_one({"id": item_id}, {"_id": 0, "name": 1, "sku_code": 1})
            item_name = rm.get("name", "Unknown") if rm else "Unknown"
            sku_code = rm.get("sku_code", "") if rm else ""
        
        inventory_details.append({
            "item_id": item_id,
            "item_type": item_type,
            "item_name": item_name,
            "sku_code": sku_code,
            "quantity": qty,
            "wac": wac,
            "value": round(value, 2)
        })
    
    # GST ITC Balance
    itc_entry = await db.gst_itc_balances.find_one({
        "firm_id": firm_id,
        "month": target_month
    }, {"_id": 0})
    
    itc_balance = {
        "igst": itc_entry.get("igst_balance", 0) if itc_entry else 0,
        "cgst": itc_entry.get("cgst_balance", 0) if itc_entry else 0,
        "sgst": itc_entry.get("sgst_balance", 0) if itc_entry else 0,
        "total": 0
    }
    itc_balance["total"] = itc_balance["igst"] + itc_balance["cgst"] + itc_balance["sgst"]
    
    # Output GST
    output_gst = sum(gst_by_rate[r]["gst"] for r in gst_by_rate)
    
    # Net GST Payable
    net_gst = max(0, output_gst - itc_balance["total"])
    
    return {
        "firm": {
            "id": firm_id,
            "name": firm["name"],
            "gstin": firm.get("gstin", firm.get("gst_number", ""))
        },
        "month": target_month,
        "sales": {
            "count": sales_count,
            "total_value": round(sales_value, 2),
            "taxable_value": round(sales_taxable, 2),
            "gst_by_rate": {str(k): {"taxable": round(v["taxable"], 2), "gst": round(v["gst"], 2), "count": v["count"]} for k, v in gst_by_rate.items()}
        },
        "returns": {
            "count": returns_count,
            "value": round(returns_value, 2)
        },
        "transfers": {
            "in": {"count": transfers_in_count, "value": round(transfers_in_value, 2)},
            "out": {"count": transfers_out_count, "value": round(transfers_out_value, 2)}
        },
        "production": {
            "count": production_count,
            "value": round(production_value, 2)
        },
        "purchases": {
            "count": purchases_count,
            "value": round(purchases_value, 2),
            "taxable_value": round(purchases_taxable, 2),
            "input_gst": round(input_gst_total, 2)
        },
        "inventory": {
            "total_value": round(inventory_value, 2),
            "item_count": len(inventory_details),
            "details": sorted(inventory_details, key=lambda x: x["value"], reverse=True)[:50]
        },
        "gst": {
            "output_gst": round(output_gst_total, 2),
            "output_cgst": round(output_cgst, 2),
            "output_sgst": round(output_sgst, 2),
            "output_igst": round(output_igst, 2),
            "input_gst": round(input_gst_total, 2),
            "input_cgst": round(input_cgst, 2),
            "input_sgst": round(input_sgst, 2),
            "input_igst": round(input_igst, 2),
            "itc_balance": itc_balance,
            "net_payable": round(max(0, output_gst_total - input_gst_total - itc_balance["total"]), 2)
        }
    }

@api_router.post("/finance/gst-itc")
async def create_gst_itc_entry(
    entry: GSTITCEntry,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Create or update GST ITC balance entry for a firm/month"""
    
    # Validate that ITC can only be entered after 15th of the following month
    # E.g., April 2026 ITC can only be entered after May 15, 2026
    try:
        entry_month = datetime.strptime(entry.month, "%Y-%m")
        current_date = datetime.now(timezone.utc)
        
        # Calculate when this month's ITC becomes available (15th of next month)
        if entry_month.month == 12:
            available_from = datetime(entry_month.year + 1, 1, 15, tzinfo=timezone.utc)
        else:
            available_from = datetime(entry_month.year, entry_month.month + 1, 15, tzinfo=timezone.utc)
        
        if current_date < available_from:
            raise HTTPException(
                status_code=400, 
                detail=f"ITC for {entry_month.strftime('%B %Y')} can only be entered after {available_from.strftime('%d %B %Y')} (GST returns filing deadline)"
            )
    except ValueError:
        raise HTTPException(status_code=400, detail="Invalid month format. Use YYYY-MM")
    
    # Validate firm
    firm = await db.firms.find_one({"id": entry.firm_id}, {"_id": 0})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    # Check if entry exists for this firm/month
    existing = await db.gst_itc_balances.find_one({
        "firm_id": entry.firm_id,
        "month": entry.month
    })
    
    now = datetime.now(timezone.utc).isoformat()
    
    if existing:
        # Update existing entry
        old_values = {
            "igst": existing.get("igst_balance", 0),
            "cgst": existing.get("cgst_balance", 0),
            "sgst": existing.get("sgst_balance", 0)
        }
        
        await db.gst_itc_balances.update_one(
            {"_id": existing["_id"]},
            {"$set": {
                "igst_balance": entry.igst_balance,
                "cgst_balance": entry.cgst_balance,
                "sgst_balance": entry.sgst_balance,
                "notes": entry.notes,
                "updated_by": user["id"],
                "updated_at": now
            }}
        )
        
        # Log the update
        await log_financial_action(
            "gst_itc_updated",
            "gst_itc_balance",
            existing["id"],
            {
                "firm_id": entry.firm_id,
                "firm_name": firm["name"],
                "month": entry.month,
                "old_values": old_values,
                "new_values": {
                    "igst": entry.igst_balance,
                    "cgst": entry.cgst_balance,
                    "sgst": entry.sgst_balance
                },
                "notes": entry.notes
            },
            user
        )
        
        return {"success": True, "message": "ITC balance updated", "id": existing["id"]}
    else:
        # Create new entry
        entry_id = str(uuid.uuid4())
        entry_doc = {
            "id": entry_id,
            "firm_id": entry.firm_id,
            "firm_name": firm["name"],
            "month": entry.month,
            "igst_balance": entry.igst_balance,
            "cgst_balance": entry.cgst_balance,
            "sgst_balance": entry.sgst_balance,
            "notes": entry.notes,
            "created_by": user["id"],
            "created_at": now
        }
        
        await db.gst_itc_balances.insert_one(entry_doc)
        
        # Log the creation
        await log_financial_action(
            "gst_itc_created",
            "gst_itc_balance",
            entry_id,
            {
                "firm_id": entry.firm_id,
                "firm_name": firm["name"],
                "month": entry.month,
                "values": {
                    "igst": entry.igst_balance,
                    "cgst": entry.cgst_balance,
                    "sgst": entry.sgst_balance
                },
                "notes": entry.notes
            },
            user
        )
        
        return {"success": True, "message": "ITC balance created", "id": entry_id}

@api_router.get("/finance/gst-itc/{firm_id}")
async def get_gst_itc_history(
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get GST ITC balance history for a firm"""
    assert_firm_access(user, firm_id)
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    entries = await db.gst_itc_balances.find(
        {"firm_id": firm_id},
        {"_id": 0}
    ).sort("month", -1).to_list(24)  # Last 2 years
    
    return {
        "firm": {"id": firm_id, "name": firm["name"]},
        "entries": entries
    }

@api_router.patch("/finance/dispatch/{dispatch_id}/invoice-value")
async def update_dispatch_invoice_value(
    dispatch_id: str,
    data: DispatchInvoiceValue,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update invoice value for a dispatch (for GST calculation)"""
    dispatch = await db.dispatches.find_one({"id": dispatch_id}, {"_id": 0})
    if not dispatch:
        raise HTTPException(status_code=404, detail="Dispatch not found")
    
    # Get GST rate from SKU if not provided
    gst_rate = data.gst_rate
    if gst_rate is None and dispatch.get("master_sku_id"):
        sku = await db.master_skus.find_one({"id": dispatch["master_sku_id"]}, {"_id": 0})
        gst_rate = sku.get("gst_rate", 18) if sku else 18
    elif gst_rate is None:
        gst_rate = 18
    
    gst_amount = data.taxable_value * (gst_rate / 100)
    invoice_value = data.taxable_value + gst_amount
    
    old_values = {
        "taxable_value": dispatch.get("taxable_value"),
        "gst_rate": dispatch.get("gst_rate"),
        "invoice_value": dispatch.get("invoice_value")
    }
    
    await db.dispatches.update_one(
        {"id": dispatch_id},
        {"$set": {
            "taxable_value": data.taxable_value,
            "gst_rate": gst_rate,
            "gst_amount": round(gst_amount, 2),
            "invoice_value": round(invoice_value, 2),
            "invoice_updated_by": user["id"],
            "invoice_updated_at": datetime.now(timezone.utc).isoformat()
        }}
    )
    
    # Log the update
    await log_financial_action(
        "dispatch_invoice_updated",
        "dispatch",
        dispatch_id,
        {
            "dispatch_number": dispatch.get("dispatch_number"),
            "old_values": old_values,
            "new_values": {
                "taxable_value": data.taxable_value,
                "gst_rate": gst_rate,
                "gst_amount": round(gst_amount, 2),
                "invoice_value": round(invoice_value, 2)
            }
        },
        user
    )
    
    return {
        "success": True,
        "dispatch_id": dispatch_id,
        "taxable_value": data.taxable_value,
        "gst_rate": gst_rate,
        "gst_amount": round(gst_amount, 2),
        "invoice_value": round(invoice_value, 2)
    }

@api_router.get("/finance/transfer-recommendations")
async def get_transfer_recommendations(
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get smart transfer recommendations based on stock, sales velocity, and ITC"""
    firms = await db.firms.find({"is_active": True}, {"_id": 0}).to_list(100)
    if len(firms) < 2:
        return {"recommendations": [], "message": "Need at least 2 firms for transfer recommendations"}
    
    recommendations = []
    current_month = datetime.now(timezone.utc).strftime("%Y-%m")
    
    # Get all SKUs
    skus = await db.master_skus.find({"is_active": True}, {"_id": 0}).to_list(1000)
    
    for sku in skus:
        sku_id = sku["id"]
        sku_code = sku["sku_code"]
        sku_name = sku["name"]
        reorder_level = sku.get("reorder_level", 10)
        
        firm_stock_data = []
        
        for firm in firms:
            firm_id = firm["id"]
            
            # Get current stock
            stock_result = await db.inventory_ledger.aggregate([
                {"$match": {"item_id": sku_id, "firm_id": firm_id}},
                {"$group": {"_id": None, "total": {"$sum": "$quantity"}}}
            ]).to_list(1)
            
            current_stock = stock_result[0]["total"] if stock_result else 0
            
            # Get sales velocity (dispatches in last 30 days)
            thirty_days_ago = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
            dispatches = await db.dispatches.count_documents({
                "firm_id": firm_id,
                "master_sku_id": sku_id,
                "status": "dispatched",
                "dispatched_at": {"$gte": thirty_days_ago}
            })
            
            sales_velocity = dispatches  # Units sold in 30 days
            days_of_stock = (current_stock / sales_velocity * 30) if sales_velocity > 0 else 999
            
            # Get ITC balance
            itc_entry = await db.gst_itc_balances.find_one({
                "firm_id": firm_id,
                "month": current_month
            }, {"_id": 0})
            itc_balance = 0
            if itc_entry:
                itc_balance = (itc_entry.get("igst_balance", 0) + 
                             itc_entry.get("cgst_balance", 0) + 
                             itc_entry.get("sgst_balance", 0))
            
            firm_stock_data.append({
                "firm_id": firm_id,
                "firm_name": firm["name"],
                "current_stock": current_stock,
                "sales_velocity": sales_velocity,
                "days_of_stock": round(days_of_stock, 1),
                "itc_balance": itc_balance,
                "is_low_stock": current_stock < reorder_level,
                "is_surplus": current_stock > reorder_level * 3 and sales_velocity < current_stock / 90
            })
        
        # Find transfer opportunities
        low_stock_firms = [f for f in firm_stock_data if f["is_low_stock"] and f["sales_velocity"] > 0]
        surplus_firms = [f for f in firm_stock_data if f["is_surplus"]]
        
        for low_firm in low_stock_firms:
            for surplus_firm in surplus_firms:
                if low_firm["firm_id"] != surplus_firm["firm_id"]:
                    # Calculate recommended quantity
                    needed = max(reorder_level - low_firm["current_stock"], 0)
                    available = surplus_firm["current_stock"] - reorder_level
                    transfer_qty = min(needed, available)
                    
                    if transfer_qty > 0:
                        # ITC advisory (informational only)
                        itc_note = ""
                        if surplus_firm["itc_balance"] > low_firm["itc_balance"]:
                            itc_note = f"Note: {surplus_firm['firm_name']} has higher ITC (Rs.{surplus_firm['itc_balance']:,.0f}) - transfer may help balance"
                        
                        recommendations.append({
                            "sku_id": sku_id,
                            "sku_code": sku_code,
                            "sku_name": sku_name,
                            "from_firm": {
                                "id": surplus_firm["firm_id"],
                                "name": surplus_firm["firm_name"],
                                "current_stock": surplus_firm["current_stock"],
                                "days_of_stock": surplus_firm["days_of_stock"]
                            },
                            "to_firm": {
                                "id": low_firm["firm_id"],
                                "name": low_firm["firm_name"],
                                "current_stock": low_firm["current_stock"],
                                "days_of_stock": low_firm["days_of_stock"],
                                "sales_velocity": low_firm["sales_velocity"]
                            },
                            "recommended_qty": transfer_qty,
                            "reason": f"Low stock at {low_firm['firm_name']} ({low_firm['current_stock']} units, {low_firm['days_of_stock']} days), surplus at {surplus_firm['firm_name']} ({surplus_firm['current_stock']} units)",
                            "priority": "high" if low_firm["current_stock"] == 0 else "medium",
                            "itc_advisory": itc_note
                        })
    
    # Sort by priority
    recommendations.sort(key=lambda x: (0 if x["priority"] == "high" else 1, -x["recommended_qty"]))
    
    return {
        "recommendations": recommendations[:20],  # Top 20 recommendations
        "total_recommendations": len(recommendations),
        "generated_at": datetime.now(timezone.utc).isoformat()
    }

@api_router.get("/finance/inventory-valuation")
async def get_inventory_valuation(
    firm_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get detailed inventory valuation using WAC method (firm-scoped)."""
    query = {"is_active": True}
    scope = get_user_firm_scope(user)
    if scope:
        if firm_id and firm_id != scope:
            raise HTTPException(status_code=403, detail="Cross-firm access denied")
        query["id"] = scope
    elif firm_id:
        query["id"] = firm_id

    firms = await db.firms.find(query, {"_id": 0}).to_list(100)
    
    result = []
    grand_total = 0
    
    for firm in firms:
        f_id = firm["id"]
        
        # Get stock by item
        stock_pipeline = [
            {"$match": {"firm_id": f_id}},
            {"$group": {
                "_id": {"item_id": "$item_id", "item_type": "$item_type"},
                "total_qty": {"$sum": "$quantity"}
            }},
            {"$match": {"total_qty": {"$gt": 0}}}
        ]
        stock_items = await db.inventory_ledger.aggregate(stock_pipeline).to_list(1000)
        
        firm_total = 0
        items = []
        
        for item in stock_items:
            item_id = item["_id"]["item_id"]
            item_type = item["_id"]["item_type"]
            qty = item["total_qty"]
            
            wac = await calculate_wac(item_id, item_type, f_id)
            value = qty * wac
            firm_total += value
            
            # Get item details
            if item_type == "master_sku":
                sku = await db.master_skus.find_one({"id": item_id}, {"_id": 0})
                item_name = sku.get("name", "Unknown") if sku else "Unknown"
                sku_code = sku.get("sku_code", "") if sku else ""
                hsn = sku.get("hsn_code", "") if sku else ""
                gst_rate = sku.get("gst_rate", 18) if sku else 18
            else:
                rm = await db.raw_materials.find_one({"id": item_id}, {"_id": 0})
                item_name = rm.get("name", "Unknown") if rm else "Unknown"
                sku_code = rm.get("sku_code", "") if rm else ""
                hsn = rm.get("hsn_code", "") if rm else ""
                gst_rate = 18
            
            items.append({
                "item_id": item_id,
                "item_type": item_type,
                "item_name": item_name,
                "sku_code": sku_code,
                "hsn_code": hsn,
                "gst_rate": gst_rate,
                "quantity": qty,
                "wac": round(wac, 2),
                "value": round(value, 2)
            })
        
        items.sort(key=lambda x: x["value"], reverse=True)
        grand_total += firm_total
        
        result.append({
            "firm_id": f_id,
            "firm_name": firm["name"],
            "gstin": firm.get("gstin", firm.get("gst_number", "")),
            "total_value": round(firm_total, 2),
            "item_count": len(items),
            "items": items
        })
    
    return {
        "valuation_method": "Weighted Average Cost (WAC)",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "grand_total": round(grand_total, 2),
        "firms": result
    }

@api_router.get("/finance/month-end-report")
async def get_month_end_report(
    month: str,  # YYYY-MM format
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get comprehensive month-end financial report (firm-scoped)."""
    year, month_num = map(int, month.split("-"))
    month_start = datetime(year, month_num, 1, tzinfo=timezone.utc)
    if month_num == 12:
        month_end = datetime(year + 1, 1, 1, tzinfo=timezone.utc)
    else:
        month_end = datetime(year, month_num + 1, 1, tzinfo=timezone.utc)

    firm_query = {"is_active": True}
    scope = get_user_firm_scope(user)
    if scope:
        firm_query["id"] = scope
    firms = await db.firms.find(firm_query, {"_id": 0}).to_list(100)
    
    report = {
        "month": month,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "firms": [],
        "totals": {
            "sales": 0,
            "purchases": 0,
            "production": 0,
            "transfers": 0,
            "output_gst": 0,
            "itc_available": 0,
            "net_gst_payable": 0
        }
    }
    
    for firm in firms:
        firm_id = firm["id"]
        
        # Get detailed summary
        summary = await get_firm_financial_summary(firm_id, month, user)
        
        firm_report = {
            "firm_id": firm_id,
            "firm_name": firm["name"],
            "gstin": firm.get("gstin", firm.get("gst_number", "")),
            "sales": summary["sales"],
            "purchases": summary["purchases"],
            "production": summary["production"],
            "transfers": summary["transfers"],
            "returns": summary["returns"],
            "gst": summary["gst"],
            "inventory_value": summary["inventory"]["total_value"]
        }
        
        report["firms"].append(firm_report)
        
        # Update totals
        report["totals"]["sales"] += summary["sales"]["total_value"]
        report["totals"]["purchases"] += summary["purchases"]["value"]
        report["totals"]["production"] += summary["production"]["value"]
        report["totals"]["transfers"] += summary["transfers"]["in"]["value"]
        report["totals"]["output_gst"] += summary["gst"]["output_gst"]
        report["totals"]["itc_available"] += summary["gst"]["itc_balance"]["total"]
        report["totals"]["net_gst_payable"] += summary["gst"]["net_payable"]
    
    # Round totals
    for key in report["totals"]:
        report["totals"][key] = round(report["totals"][key], 2)
    
    return report

@api_router.get("/finance/export/{report_type}")
async def export_financial_report(
    report_type: str,  # inventory, gst, sales, month-end
    firm_id: Optional[str] = None,
    month: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Export financial reports as CSV (firm-scoped for accountants)."""
    scope = get_user_firm_scope(user)
    if scope and firm_id and firm_id != scope:
        raise HTTPException(status_code=403, detail="Cross-firm access denied")
    if scope and not firm_id:
        firm_id = scope

    import csv
    import io

    output = io.StringIO()
    
    if report_type == "inventory":
        valuation = await get_inventory_valuation(firm_id, user)
        
        writer = csv.writer(output)
        writer.writerow(["Firm", "GSTIN", "SKU Code", "Item Name", "HSN", "GST Rate", "Quantity", "WAC", "Value"])
        
        for firm in valuation["firms"]:
            for item in firm["items"]:
                writer.writerow([
                    firm["firm_name"],
                    firm["gstin"],
                    item["sku_code"],
                    item["item_name"],
                    item["hsn_code"],
                    item["gst_rate"],
                    item["quantity"],
                    item["wac"],
                    item["value"]
                ])
        
        writer.writerow([])
        writer.writerow(["Grand Total", "", "", "", "", "", "", "", valuation["grand_total"]])
        
    elif report_type == "gst":
        if not firm_id:
            raise HTTPException(status_code=400, detail="firm_id required for GST report")
        
        itc_history = await get_gst_itc_history(firm_id, user)
        
        writer = csv.writer(output)
        writer.writerow(["Month", "IGST Balance", "CGST Balance", "SGST Balance", "Total", "Notes"])
        
        for entry in itc_history["entries"]:
            total = entry.get("igst_balance", 0) + entry.get("cgst_balance", 0) + entry.get("sgst_balance", 0)
            writer.writerow([
                entry["month"],
                entry.get("igst_balance", 0),
                entry.get("cgst_balance", 0),
                entry.get("sgst_balance", 0),
                total,
                entry.get("notes", "")
            ])
    
    elif report_type == "month-end":
        if not month:
            month = datetime.now(timezone.utc).strftime("%Y-%m")
        
        report = await get_month_end_report(month, user)
        
        writer = csv.writer(output)
        writer.writerow(["Month-End Report:", month])
        writer.writerow([])
        writer.writerow(["Firm", "GSTIN", "Sales", "Purchases", "Production", "Transfers In", "Output GST", "ITC Available", "Net GST Payable"])
        
        for firm in report["firms"]:
            writer.writerow([
                firm["firm_name"],
                firm["gstin"],
                firm["sales"]["total_value"],
                firm["purchases"]["value"],
                firm["production"]["value"],
                firm["transfers"]["in"]["value"],
                firm["gst"]["output_gst"],
                firm["gst"]["itc_balance"]["total"],
                firm["gst"]["net_payable"]
            ])
        
        writer.writerow([])
        writer.writerow(["TOTALS", "", 
                        report["totals"]["sales"],
                        report["totals"]["purchases"],
                        report["totals"]["production"],
                        report["totals"]["transfers"],
                        report["totals"]["output_gst"],
                        report["totals"]["itc_available"],
                        report["totals"]["net_gst_payable"]])
    
    else:
        raise HTTPException(status_code=400, detail="Invalid report type. Use: inventory, gst, month-end")
    
    # Log export
    await log_financial_action(
        "report_exported",
        "financial_report",
        report_type,
        {"report_type": report_type, "firm_id": firm_id, "month": month},
        user
    )
    
    output.seek(0)
    
    from fastapi.responses import StreamingResponse
    
    filename = f"{report_type}_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv"
    
    return StreamingResponse(
        iter([output.getvalue()]),
        media_type="text/csv",
        headers={"Content-Disposition": f"attachment; filename={filename}"}
    )

@api_router.get("/finance/audit-logs")
async def get_financial_audit_logs(
    entity_type: Optional[str] = None,
    firm_id: Optional[str] = None,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    limit: int = 100,
    skip: int = 0,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get financial audit logs (firm-scoped for accountants)."""
    query = {}
    scope = get_user_firm_scope(user)
    if scope:
        if firm_id and firm_id != scope:
            raise HTTPException(status_code=403, detail="Cross-firm access denied")
        query["details.firm_id"] = scope
    elif firm_id:
        query["details.firm_id"] = firm_id

    if entity_type:
        query["entity_type"] = entity_type
    if from_date:
        query["timestamp"] = {"$gte": from_date}
    if to_date:
        if "timestamp" in query:
            query["timestamp"]["$lte"] = to_date
        else:
            query["timestamp"] = {"$lte": to_date}
    
    logs = await db.financial_audit_logs.find(query, {"_id": 0}).sort("timestamp", -1).skip(skip).limit(limit).to_list(limit)
    total = await db.financial_audit_logs.count_documents(query)
    
    return {
        "logs": logs,
        "total": total,
        "limit": limit,
        "skip": skip
    }


# ==================== PURCHASE REGISTER MODULE ====================

@api_router.post("/purchases")
async def create_purchase(
    purchase: PurchaseCreate,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Create a purchase entry with GST calculation and inventory update"""

    # Accountants must not be able to create purchases under another firm's id.
    assert_firm_access(user, purchase.firm_id)

    # Validate firm
    firm = await db.firms.find_one({"id": purchase.firm_id}, {"_id": 0})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    firm_state = firm.get("state", "")
    firm_gstin = firm.get("gstin", firm.get("gst_number", ""))
    
    # Validate GSTIN if provided
    if purchase.supplier_gstin and not validate_gstin(purchase.supplier_gstin):
        raise HTTPException(status_code=400, detail="Invalid GSTIN format")
    
    # Validate invoice number uniqueness for this firm
    existing = await db.purchases.find_one({
        "firm_id": purchase.firm_id,
        "invoice_number": purchase.invoice_number
    })
    if existing:
        raise HTTPException(status_code=400, detail="Invoice number already exists for this firm")
    
    # Validate items
    if not purchase.items or len(purchase.items) == 0:
        raise HTTPException(status_code=400, detail="At least one item is required")
    
    # Determine GST type (IGST vs CGST+SGST)
    supplier_state = purchase.supplier_state.lower().strip()
    firm_state_lower = firm_state.lower().strip()
    is_inter_state = supplier_state != firm_state_lower
    
    now = datetime.now(timezone.utc).isoformat()
    purchase_id = str(uuid.uuid4())
    purchase_number = f"PUR-{datetime.now().strftime('%Y%m%d')}-{str(uuid.uuid4())[:5].upper()}"
    
    # Process items and calculate GST
    processed_items = []
    total_taxable = 0
    total_igst = 0
    total_cgst = 0
    total_sgst = 0
    total_amount = 0
    
    ledger_entries = []
    
    for item in purchase.items:
        # Validate quantity
        if item.quantity <= 0:
            raise HTTPException(status_code=400, detail="Quantity must be positive")
        if item.rate <= 0:
            raise HTTPException(status_code=400, detail="Rate must be positive")
        
        # Get item details
        if item.item_type == "raw_material":
            item_doc = await db.raw_materials.find_one({"id": item.item_id}, {"_id": 0})
            if not item_doc:
                raise HTTPException(status_code=404, detail=f"Raw material not found: {item.item_id}")
        elif item.item_type == "master_sku":
            item_doc = await db.master_skus.find_one({"id": item.item_id}, {"_id": 0})
            if not item_doc:
                raise HTTPException(status_code=404, detail=f"Master SKU not found: {item.item_id}")
        else:
            raise HTTPException(status_code=400, detail="Invalid item type. Use 'raw_material' or 'master_sku'")
        
        # Get GST rate (from item or override)
        gst_rate = item.gst_rate if item.gst_rate is not None else item_doc.get("gst_rate", 18)
        
        # Calculate values
        taxable_value = item.quantity * item.rate
        gst_amount = taxable_value * (gst_rate / 100)
        
        if is_inter_state:
            igst = gst_amount
            cgst = 0
            sgst = 0
        else:
            igst = 0
            cgst = gst_amount / 2
            sgst = gst_amount / 2
        
        line_total = taxable_value + gst_amount
        
        processed_item = {
            "item_type": item.item_type,
            "item_id": item.item_id,
            "item_name": item_doc.get("name"),
            "sku_code": item_doc.get("sku_code"),
            "hsn_code": item_doc.get("hsn_code", ""),
            "quantity": item.quantity,
            "rate": item.rate,
            "gst_rate": gst_rate,
            "taxable_value": round(taxable_value, 2),
            "igst": round(igst, 2),
            "cgst": round(cgst, 2),
            "sgst": round(sgst, 2),
            "total": round(line_total, 2)
        }
        processed_items.append(processed_item)
        
        total_taxable += taxable_value
        total_igst += igst
        total_cgst += cgst
        total_sgst += sgst
        total_amount += line_total
        
        # Prepare ledger entry
        ledger_entry = {
            "id": str(uuid.uuid4()),
            "entry_number": f"LED-{datetime.now().strftime('%Y%m%d')}-{str(uuid.uuid4())[:5].upper()}",
            "entry_type": "purchase",
            "item_type": item.item_type,
            "item_id": item.item_id,
            "item_name": item_doc.get("name"),
            "firm_id": purchase.firm_id,
            "firm_name": firm["name"],
            "quantity": item.quantity,
            "unit_cost": item.rate,
            "running_balance": 0,  # Will be calculated
            "invoice_number": purchase.invoice_number,
            "reference_id": purchase_id,
            "reason": f"Purchase from {purchase.supplier_name}",
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
            "created_at": now
        }
        ledger_entries.append(ledger_entry)
    
    # ====== COMPLIANCE VALIDATION ======
    compliance_data = {
        "supplier_name": purchase.supplier_name,
        "invoice_number": purchase.invoice_number,
        "invoice_date": purchase.invoice_date,
        "firm_id": purchase.firm_id,
        "items": processed_items,
        "totals": {
            "taxable_value": round(total_taxable, 2),
            "total_gst": round(total_igst + total_cgst + total_sgst, 2)
        }
    }
    
    # Check for files
    files_present = {"supplier_invoice_file": purchase.supplier_invoice_file_url}
    
    compliance_result = validate_document_compliance(
        "purchase_entry", 
        compliance_data, 
        files_present, 
        round(total_amount, 2)
    )
    
    # Determine status and doc_status
    if not compliance_result["can_proceed"] and not purchase.save_as_draft:
        # Hard block - cannot proceed
        raise HTTPException(
            status_code=400, 
            detail={
                "message": "Compliance validation failed - cannot post final entry",
                "hard_blocks": compliance_result["hard_blocks"],
                "missing_critical": compliance_result["missing_critical"],
                "suggestion": "Fix issues or save as draft"
            }
        )
    
    # Set status based on draft flag and compliance
    if purchase.save_as_draft:
        entry_status = "draft"
        doc_status = "pending" if compliance_result["soft_blocks"] or compliance_result["hard_blocks"] else "complete"
    else:
        entry_status = "final"
        doc_status = compliance_result["status"]
    
    # Create purchase record
    purchase_doc = {
        "id": purchase_id,
        "purchase_number": purchase_number,
        "firm_id": purchase.firm_id,
        "firm_name": firm["name"],
        "firm_gstin": firm_gstin,
        "supplier_name": purchase.supplier_name,
        "supplier_gstin": purchase.supplier_gstin,
        "supplier_state": purchase.supplier_state,
        "invoice_number": purchase.invoice_number,
        "invoice_date": purchase.invoice_date,
        "is_inter_state": is_inter_state,
        "items": processed_items,
        "total_taxable": round(total_taxable, 2),
        "total_igst": round(total_igst, 2),
        "total_cgst": round(total_cgst, 2),
        "total_sgst": round(total_sgst, 2),
        "total_gst": round(total_igst + total_cgst + total_sgst, 2),
        "total_amount": round(total_amount, 2),
        "totals": {
            "grand_total": round(total_amount, 2),
            "taxable_value": round(total_taxable, 2),
            "total_gst": round(total_igst + total_cgst + total_sgst, 2)
        },
        "notes": purchase.notes,
        "invoice_file": purchase.supplier_invoice_file_url,
        "status": entry_status,
        "doc_status": doc_status,
        "compliance_score": compliance_result["compliance_score"],
        "compliance_issues": compliance_result.get("soft_blocks", []) + compliance_result.get("warnings", []),
        "created_by": user["id"],
        "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "created_at": now
    }
    
    # Insert purchase
    await db.purchases.insert_one(purchase_doc)
    
    # Create compliance exception if there are issues (for non-draft entries)
    if entry_status == "final" and doc_status == "pending" and (compliance_result["soft_blocks"] or compliance_result["missing_important"]):
        severity = "critical" if compliance_result["missing_critical"] else "important"
        await create_compliance_exception(
            transaction_type="purchase_entry",
            transaction_id=purchase_id,
            transaction_ref=purchase_number,
            firm_id=purchase.firm_id,
            issues=compliance_result["soft_blocks"] + [f"Missing: {m['label']}" for m in compliance_result.get("missing_important", [])],
            severity=severity,
            user=user
        )
    
    # Insert ledger entries and update stock - ONLY for final entries
    ledger_entries_created = 0
    if entry_status == "final":
        for entry in ledger_entries:
            # Calculate running balance
            current_stock = await db.inventory_ledger.aggregate([
                {"$match": {
                    "item_id": entry["item_id"],
                    "item_type": entry["item_type"],
                    "firm_id": purchase.firm_id
                }},
                {"$group": {"_id": None, "total": {"$sum": "$quantity"}}}
            ]).to_list(1)
            
            current_balance = current_stock[0]["total"] if current_stock else 0
            entry["running_balance"] = current_balance + entry["quantity"]
            
            await db.inventory_ledger.insert_one(entry)
            ledger_entries_created += 1
    
    # Log financial action
    await log_financial_action(
        "purchase_created",
        "purchase",
        purchase_id,
        {
            "purchase_number": purchase_number,
            "firm_id": purchase.firm_id,
            "firm_name": firm["name"],
            "supplier_name": purchase.supplier_name,
            "invoice_number": purchase.invoice_number,
            "total_amount": round(total_amount, 2),
            "total_gst": round(total_igst + total_cgst + total_sgst, 2),
            "items_count": len(processed_items),
            "status": entry_status,
            "doc_status": doc_status
        },
        user
    )
    
    # ====== CREATE SUPPLIER PARTY LEDGER ENTRY (PAYABLES) ======
    # This tracks what we owe to suppliers - critical for double-entry accounting
    if entry_status == "final":
        # Find or create supplier party
        supplier_party = await db.parties.find_one({
            "name": purchase.supplier_name,
            "party_type": {"$in": ["supplier", "vendor"]}
        })
        
        if not supplier_party:
            # Auto-create supplier party
            supplier_party = {
                "id": str(uuid.uuid4()),
                "name": purchase.supplier_name,
                "party_type": "supplier",
                "gstin": purchase.supplier_gstin,
                "state": purchase.supplier_state,
                "phone": None,
                "email": None,
                "current_balance": 0,
                "opening_balance": 0,
                "is_active": True,
                "auto_created": True,
                "created_at": now,
                "updated_at": now
            }
            await db.parties.insert_one(supplier_party)
        
        # ATOMIC party ledger entry for supplier (credit increases payable)
        supplier_ledger_entry = await create_party_ledger_entry_atomic(
            party_id=supplier_party["id"],
            party_name=supplier_party["name"],
            entry_type="purchase",
            debit=0,
            credit=round(total_amount, 2),  # Credit increases payable
            narration=f"Purchase {purchase_number} - {purchase.invoice_number}",
            reference_type="purchase_invoice",
            reference_id=purchase_id,
            firm_id=purchase.firm_id,
            user_id=user["id"],
            user_name=f"{user['first_name']} {user['last_name']}",
            entry_number=f"PUR-{purchase_number}",
            opening_balance=supplier_party.get("opening_balance", 0)
        )
        new_balance = supplier_ledger_entry.get("running_balance", 0)
        
        # Update supplier party balance
        await db.parties.update_one(
            {"id": supplier_party["id"]},
            {"$set": {"current_balance": new_balance, "updated_at": now}}
        )
        
        # Update purchase with payment tracking fields
        await db.purchases.update_one(
            {"id": purchase_id},
            {"$set": {
                "supplier_party_id": supplier_party["id"],
                "balance_due": round(total_amount, 2),
                "amount_paid": 0,
                "payment_status": "unpaid"
            }}
        )
    
    return {
        "success": True,
        "purchase_id": purchase_id,
        "purchase_number": purchase_number,
        "total_taxable": round(total_taxable, 2),
        "total_gst": round(total_igst + total_cgst + total_sgst, 2),
        "total_amount": round(total_amount, 2),
        "ledger_entries_created": ledger_entries_created,
        "status": entry_status,
        "doc_status": doc_status,
        "compliance_score": compliance_result["compliance_score"],
        "compliance_warnings": compliance_result.get("warnings", []),
        "compliance_soft_blocks": compliance_result.get("soft_blocks", [])
    }

@api_router.get("/purchases")
async def list_purchases(
    firm_id: Optional[str] = None,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    supplier_name: Optional[str] = None,
    limit: int = 100,
    skip: int = 0,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """List purchases with filters - FIRM SCOPE ENFORCED for accountants"""
    query = {}
    
    # CRITICAL FIX: Enforce firm scope for accountants
    firm_scope = get_user_firm_scope(user)
    if firm_scope:
        query["firm_id"] = firm_scope
    elif firm_id:
        query["firm_id"] = firm_id
    
    if from_date:
        query["invoice_date"] = {"$gte": from_date}
    if to_date:
        if "invoice_date" in query:
            query["invoice_date"]["$lte"] = to_date
        else:
            query["invoice_date"] = {"$lte": to_date}
    if supplier_name:
        query["supplier_name"] = {"$regex": supplier_name, "$options": "i"}
    
    purchases = await db.purchases.find(query, {"_id": 0}).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    # Defensive: any ObjectId leftover in fields like supplier_id will break
    # FastAPI's JSON serialization. Stringify them on the way out.
    from bson import ObjectId as _OID
    for p in purchases:
        for k, v in list(p.items()):
            if isinstance(v, _OID):
                p[k] = str(v)
        sign_file_urls_deep(p, user["id"])  # supplier invoice opens via plain link
    total = await db.purchases.count_documents(query)
    
    # Calculate summary
    summary_pipeline = [
        {"$match": query},
        {"$group": {
            "_id": None,
            "total_taxable": {"$sum": "$total_taxable"},
            "total_igst": {"$sum": "$total_igst"},
            "total_cgst": {"$sum": "$total_cgst"},
            "total_sgst": {"$sum": "$total_sgst"},
            "total_amount": {"$sum": "$total_amount"},
            "count": {"$sum": 1}
        }}
    ]
    summary_result = await db.purchases.aggregate(summary_pipeline).to_list(1)
    summary = summary_result[0] if summary_result else {
        "total_taxable": 0, "total_igst": 0, "total_cgst": 0, 
        "total_sgst": 0, "total_amount": 0, "count": 0
    }
    if "_id" in summary:
        del summary["_id"]
    
    return {
        "purchases": purchases,
        "total": total,
        "summary": summary,
        "limit": limit,
        "skip": skip
    }

@api_router.get("/purchases/{purchase_id}")
async def get_purchase(
    purchase_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get purchase details"""
    purchase = await db.purchases.find_one({"id": purchase_id}, {"_id": 0})
    if not purchase:
        raise HTTPException(status_code=404, detail="Purchase not found")
    assert_firm_access(user, purchase.get("firm_id"))
    sign_file_urls_deep(purchase, user["id"])  # supplier invoice opens via plain link
    return purchase


@api_router.post("/purchases/{purchase_id}/finalize")
async def finalize_purchase(
    purchase_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Mark an agent-created (or any other) draft purchase as final/reviewed.

    Validates the minimum fields needed for GSTR-3B compliance: firm, supplier,
    inter-state flag, GST split. If anything's missing the call 4xx's with a
    list of missing fields so the UI can show them to the accountant.
    """
    purchase = await db.purchases.find_one({"id": purchase_id})
    if not purchase:
        raise HTTPException(status_code=404, detail="Purchase not found")
    assert_firm_access(user, purchase.get("firm_id"))

    missing = []
    if not purchase.get("firm_id"):           missing.append("firm_id")
    if not purchase.get("supplier_party_id"): missing.append("supplier_party_id")
    if not purchase.get("supplier_gstin"):    missing.append("supplier_gstin")
    if not purchase.get("supplier_state"):    missing.append("supplier_state")
    if purchase.get("is_inter_state") is None: missing.append("is_inter_state")
    if not purchase.get("items"):             missing.append("items")
    if not purchase.get("total_taxable"):     missing.append("total_taxable")
    if missing:
        raise HTTPException(
            status_code=400,
            detail=f"Cannot finalize — missing/blank fields: {', '.join(missing)}",
        )

    now = datetime.now(timezone.utc).isoformat()
    await db.purchases.update_one(
        {"id": purchase_id},
        {"$set": {
            "doc_status": "complete",
            "status": "final",
            "pending_review": False,
            "finalized_at": now,
            "finalized_by": user["id"],
            "finalized_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip() or user.get("email"),
            "compliance_score": 100,
            "compliance_issues": [],
            "updated_at": now,
        }},
    )
    return {"success": True, "purchase_id": purchase_id, "doc_status": "complete"}


@api_router.delete("/purchases/{purchase_id}")
async def delete_purchase(
    purchase_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Delete a purchase. Only drafts / pending purchases may be deleted.

    Final / complete / posted purchases are part of GSTR-3B filings and inventory
    ledger; reversing them needs an explicit credit-note / void flow, not a
    silent delete. Defensive checks refuse the delete if anything downstream
    (party_ledger / payments / inventory_ledger) already references the
    purchase — drafts shouldn't have those, but check anyway so a half-posted
    state can't be silently orphaned.
    """
    purchase = await db.purchases.find_one({"id": purchase_id})
    if not purchase:
        raise HTTPException(status_code=404, detail="Purchase not found")
    assert_firm_access(user, purchase.get("firm_id"))

    doc_status = (purchase.get("doc_status") or "").lower()
    status = (purchase.get("status") or "").lower()
    if doc_status not in ("draft", "pending") or status in ("final", "posted", "complete"):
        raise HTTPException(
            status_code=409,
            detail=(
                f"Refusing to delete purchase {purchase.get('purchase_number')} — "
                f"doc_status={doc_status!r}, status={status!r}. Only draft/pending "
                f"purchases may be deleted. Use a credit note to reverse a posted purchase."
            ),
        )

    ledger_refs   = await db.party_ledger.count_documents({"reference_id": purchase_id})
    payment_refs  = await db.payments.count_documents({"reference_id": purchase_id})
    inv_refs      = await db.inventory_ledger.count_documents({"reference_id": purchase_id})
    if ledger_refs or payment_refs or inv_refs:
        raise HTTPException(
            status_code=409,
            detail=(
                f"Refusing to delete — found downstream references: "
                f"party_ledger={ledger_refs}, payments={payment_refs}, "
                f"inventory_ledger={inv_refs}. Reverse those first."
            ),
        )

    await db.purchases.delete_one({"id": purchase_id})

    try:
        await log_financial_action(
            "purchase_deleted",
            "purchase",
            purchase_id,
            {
                "purchase_number": purchase.get("purchase_number"),
                "supplier_name":   purchase.get("supplier_name"),
                "invoice_number":  purchase.get("invoice_number"),
                "firm_id":         purchase.get("firm_id"),
                "firm_name":       purchase.get("firm_name"),
                "total_amount":    purchase.get("total_amount"),
                "previous_doc_status": doc_status,
                "source":          purchase.get("source"),
            },
            user,
        )
    except Exception as e:
        # Don't fail the delete on an audit-log hiccup, but make it visible.
        logger.warning(f"log_financial_action failed for purchase_deleted {purchase_id}: {e}")

    return {
        "success": True,
        "purchase_id": purchase_id,
        "purchase_number": purchase.get("purchase_number"),
        "deleted_at": datetime.now(timezone.utc).isoformat(),
    }


@api_router.patch("/purchases/{purchase_id}")
async def update_purchase(
    purchase_id: str,
    data: dict,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update purchase details"""
    purchase = await db.purchases.find_one({"id": purchase_id})
    if not purchase:
        raise HTTPException(status_code=404, detail="Purchase not found")
    assert_firm_access(user, purchase.get("firm_id"))

    now = datetime.now(timezone.utc)
    update_data = {"updated_at": now.isoformat()}
    
    # Basic fields anyone can update
    basic_fields = [
        "supplier_invoice_file_url", "invoice_file", "notes", 
        "status", "doc_status", "payment_status"
    ]
    
    for field in basic_fields:
        if field in data:
            update_data[field] = data[field]
    
    # Admin-only editable fields for correcting invoice values
    admin_fields = [
        "items", "party_id", "party_name", "party_gstin", "party_state",
        "subtotal", "total_discount", "taxable_value", "cgst", "sgst", "igst",
        "total_gst", "grand_total", "tds_rate", "tds_amount", "tcs_rate", "tcs_amount"
    ]
    
    for field in admin_fields:
        if field in data:
            update_data[field] = data[field]
    
    # If items are being updated, recalculate totals
    if "items" in data:
        items = data["items"]
        for item in items:
            item["total"] = item.get("quantity", 0) * item.get("rate", 0)
            item["taxable_value"] = item["total"] - item.get("discount", 0)
            item["gst_amount"] = item["taxable_value"] * (item.get("gst_rate", 18) / 100)
            item["total_amount"] = item["taxable_value"] + item["gst_amount"]
        update_data["items"] = items
        
        # Recalculate totals
        subtotal = sum(item.get("total", 0) for item in items)
        total_discount = sum(item.get("discount", 0) for item in items)
        taxable_value = subtotal - total_discount
        total_gst = sum(item.get("gst_amount", 0) for item in items)
        grand_total = taxable_value + total_gst
        
        update_data["subtotal"] = subtotal
        update_data["total_discount"] = total_discount
        update_data["taxable_value"] = taxable_value
        update_data["total_taxable"] = taxable_value  # Display field
        update_data["total_gst"] = total_gst
        update_data["grand_total"] = grand_total
        update_data["total_amount"] = grand_total  # Display field
        
        # Calculate CGST/SGST vs IGST based on state
        firm = await db.firms.find_one({"id": purchase.get("firm_id")})
        firm_state = firm.get("state", "") if firm else ""
        party_state = update_data.get("party_state") or purchase.get("party_state", "")
        
        if firm_state and party_state and firm_state.lower() == party_state.lower():
            update_data["cgst"] = total_gst / 2
            update_data["sgst"] = total_gst / 2
            update_data["igst"] = 0
            update_data["total_cgst"] = total_gst / 2
            update_data["total_sgst"] = total_gst / 2
            update_data["total_igst"] = 0
            update_data["is_inter_state"] = False
        else:
            update_data["cgst"] = 0
            update_data["sgst"] = 0
            update_data["igst"] = total_gst
            update_data["total_cgst"] = 0
            update_data["total_sgst"] = 0
            update_data["total_igst"] = total_gst
            update_data["is_inter_state"] = True
    
    # Track who made the edit
    update_data["edited_by"] = user.get("id")
    update_data["edited_by_name"] = user.get("name")
    update_data["edited_at"] = now.isoformat()
    
    # If status is being updated from draft, also update doc_status
    if update_data.get("status") == "finalized" and purchase.get("status") == "draft":
        update_data["doc_status"] = "pending"
    
    await db.purchases.update_one(
        {"id": purchase_id},
        {"$set": update_data}
    )
    
    # Get updated purchase
    updated_purchase = await db.purchases.find_one({"id": purchase_id}, {"_id": 0})
    return updated_purchase



@api_router.post("/purchases/{purchase_id}/upload-invoice")
async def upload_purchase_invoice(
    purchase_id: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Upload invoice file for a purchase"""
    purchase = await db.purchases.find_one({"id": purchase_id})
    if not purchase:
        raise HTTPException(status_code=404, detail="Purchase not found")
    assert_firm_access(user, purchase.get("firm_id"))

    # Upload file using storage utility
    try:
        content = await file.read()
        relative_path, storage_type = await storage_upload(
            file_data=content,
            folder="purchase_invoices",
            original_filename=file.filename,
            filename_prefix=f"purchase_{purchase_id}"
        )
        file_url = f"/api/files/{relative_path}"
    except StorageError as e:
        logger.error(f"Failed to upload purchase invoice: {str(e)}")
        raise HTTPException(status_code=500, detail=f"File upload failed: {str(e)}")
    
    # Update purchase with file path (store relative path for consistency)
    await db.purchases.update_one(
        {"id": purchase_id},
        {"$set": {"invoice_file": file_url}}
    )
    
    return {"success": True, "file_path": file_url}

@api_router.get("/purchases/report/summary")
async def get_purchase_summary_report(
    firm_id: Optional[str] = None,
    month: Optional[str] = None,  # YYYY-MM
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get purchase summary for GST planning (firm-scoped)."""
    query = firm_scope_filter(user, firm_id)
    
    if month:
        # Filter by month
        year, mon = month.split("-")
        start_date = f"{year}-{mon}-01"
        if int(mon) == 12:
            end_date = f"{int(year)+1}-01-01"
        else:
            end_date = f"{year}-{int(mon)+1:02d}-01"
        query["invoice_date"] = {"$gte": start_date, "$lt": end_date}
    
    # Get summary by firm
    pipeline = [
        {"$match": query},
        {"$group": {
            "_id": "$firm_id",
            "firm_name": {"$first": "$firm_name"},
            "purchase_count": {"$sum": 1},
            "total_taxable": {"$sum": "$total_taxable"},
            "total_igst": {"$sum": "$total_igst"},
            "total_cgst": {"$sum": "$total_cgst"},
            "total_sgst": {"$sum": "$total_sgst"},
            "total_gst": {"$sum": "$total_gst"},
            "total_amount": {"$sum": "$total_amount"}
        }},
        {"$sort": {"total_amount": -1}}
    ]
    
    summaries = await db.purchases.aggregate(pipeline).to_list(100)
    
    # Format response
    result = []
    grand_total = {
        "purchase_count": 0, "total_taxable": 0, "total_igst": 0,
        "total_cgst": 0, "total_sgst": 0, "total_gst": 0, "total_amount": 0
    }
    
    for s in summaries:
        firm_summary = {
            "firm_id": s["_id"],
            "firm_name": s["firm_name"],
            "purchase_count": s["purchase_count"],
            "total_taxable": round(s["total_taxable"], 2),
            "total_igst": round(s["total_igst"], 2),
            "total_cgst": round(s["total_cgst"], 2),
            "total_sgst": round(s["total_sgst"], 2),
            "total_gst": round(s["total_gst"], 2),
            "total_amount": round(s["total_amount"], 2),
            # ITC available from this purchase
            "itc_igst": round(s["total_igst"], 2),
            "itc_cgst": round(s["total_cgst"], 2),
            "itc_sgst": round(s["total_sgst"], 2)
        }
        result.append(firm_summary)
        
        for key in grand_total:
            grand_total[key] += s.get(key, 0)
    
    return {
        "month": month,
        "firms": result,
        "grand_total": {k: round(v, 2) for k, v in grand_total.items()},
        "generated_at": datetime.now(timezone.utc).isoformat()
    }

