    # Header
    writer.writerow([
        "Purchase #", "Invoice Date", "Invoice #", "Firm", "Supplier", "Supplier GSTIN",
        "Supplier State", "Inter-State", "Taxable Value", "IGST", "CGST", "SGST", "Total GST", "Total Amount"
    ])
    
    for p in purchases:
        writer.writerow([
            p.get("purchase_number"),
            p.get("invoice_date"),
            p.get("invoice_number"),
            p.get("firm_name"),
            p.get("supplier_name"),
            p.get("supplier_gstin", ""),
            p.get("supplier_state"),
            "Yes" if p.get("is_inter_state") else "No",
            p.get("total_taxable"),
            p.get("total_igst"),
            p.get("total_cgst"),
            p.get("total_sgst"),
            p.get("total_gst"),
            p.get("total_amount")
        ])
    
    # Item details section
    writer.writerow([])
    writer.writerow(["ITEM DETAILS"])
    writer.writerow([
        "Purchase #", "Invoice #", "Item Type", "SKU Code", "Item Name", "HSN",
        "Qty", "Rate", "GST %", "Taxable", "IGST", "CGST", "SGST", "Total"
    ])
    
    for p in purchases:
        for item in p.get("items", []):
            writer.writerow([
                p.get("purchase_number"),
                p.get("invoice_number"),
                item.get("item_type"),
                item.get("sku_code"),
                item.get("item_name"),
                item.get("hsn_code"),
                item.get("quantity"),
                item.get("rate"),
                item.get("gst_rate"),
                item.get("taxable_value"),
                item.get("igst"),
                item.get("cgst"),
                item.get("sgst"),
                item.get("total")
            ])
    
    output.seek(0)
    filename = f"purchase_register_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv"
    
    return StreamingResponse(
        iter([output.getvalue()]),
        media_type="text/csv",
        headers={"Content-Disposition": f"attachment; filename={filename}"}
    )

