def get_state_code(state_name: str) -> str:
    """Get 2-digit state code from state name"""
    return STATE_CODES.get(state_name, "")


def get_financial_year() -> str:
    """Get current financial year in format 2526 (for 2025-26)"""
    now = datetime.now()
    if now.month >= 4:  # April onwards
        return f"{str(now.year)[2:]}{str(now.year + 1)[2:]}"
    else:  # Jan-March belongs to previous FY
        return f"{str(now.year - 1)[2:]}{str(now.year)[2:]}"


async def get_next_invoice_number(firm_id: str) -> str:
    """Generate next invoice number: INV/{FIRM_CODE}/{FY}/{RUNNING_NUMBER}.

    Uses an atomic per-(firm, FY) counter so concurrent issuance can never
    produce duplicate or out-of-order numbers.
    """
    firm = await db.firms.find_one({"id": firm_id})
    if not firm:
        raise HTTPException(status_code=400, detail="Invalid firm")

    name_parts = firm["name"].split()[:3]
    firm_code = "".join([p[0].upper() for p in name_parts if p])
    if len(firm_code) < 2:
        firm_code = firm["name"][:3].upper()

    fy = get_financial_year()
    prefix = f"INV/{firm_code}/{fy}/"
    counter_key = f"invoice:{firm_id}:{fy}"
    res = await db.counters.find_one_and_update(
        {"_id": counter_key},
        {"$inc": {"seq": 1}},
        upsert=True,
        return_document=True,
    )
    next_num = int((res or {}).get("seq", 1))
    return f"{prefix}{str(next_num).zfill(5)}"


@api_router.get("/parties")
async def list_parties(
    party_type: Optional[str] = None,
    search: Optional[str] = None,
    is_active: Optional[bool] = True,
    include_marketplace: bool = False,
    limit: int = 1000,
    skip: int = 0,
    user: dict = Depends(require_roles(["admin", "accountant", "call_support"]))
):
    """List parties (firm-scoped for accountants).

    Parties are global master data (a vendor can sell to many firms), so
    accountants are restricted to parties their own firm has transacted with —
    discovered via ledger/invoice/purchase/payment references. The displayed
    balance is also recomputed from the in-firm subset of the ledger, not the
    global running_balance, so a firm-A accountant does not see firm-B's
    balance against the same party.

    The type filter matches BOTH the singular `party_type` (WA-agent and
    newer code) and the plural `party_types` (legacy imports) fields, so a
    `?party_type=supplier` request returns suppliers regardless of which
    schema variant they were saved under.
    """
    # Clamp pagination
    limit = max(1, min(limit, 5000))
    skip = max(0, skip)

    filters: List[dict] = []

    # is_active=True (default) should INCLUDE rows that simply never had the
    # field written (older imports + WhatsApp-agent-created parties). Only
    # exclude rows that are EXPLICITLY is_active=False.
    if is_active is True:
        filters.append({"is_active": {"$ne": False}})
    elif is_active is False:
        filters.append({"is_active": False})
    # is_active=None → no filter (caller wants everything)

    if party_type:
        # Match either schema variant. Mongo equality on `party_types` also
        # matches arrays containing the value, so this covers both `"supplier"`
        # and `["supplier", ...]` storage shapes.
        filters.append({"$or": [
            {"party_type": party_type},
            {"party_types": party_type},
        ]})

    # Marketplace buyers (one-time dispatch consignees) are excluded from the
    # customer/dealer master by default so they don't pollute pickers/lists.
    # Pass include_marketplace=true (or explicitly ask for party_type=marketplace_buyer)
    # to see them.
    if not include_marketplace and party_type != "marketplace_buyer":
        filters.append({"party_type": {"$ne": "marketplace_buyer"}})
        filters.append({"party_types": {"$ne": "marketplace_buyer"}})

    if search:
        # GST number is stored as `gstin` on newer rows and `gst_number` on
        # legacy ones — search both so a GST-number lookup finds either.
        filters.append({"$or": [
            {"name":       {"$regex": search, "$options": "i"}},
            {"phone":      {"$regex": search, "$options": "i"}},
            {"gstin":      {"$regex": search, "$options": "i"}},
            {"gst_number": {"$regex": search, "$options": "i"}},
            {"email":      {"$regex": search, "$options": "i"}},
        ]})

    scope = get_user_firm_scope(user)
    if scope:
        # Build the set of party_ids transacted on by this firm.
        scoped_party_ids = set()
        async for doc in db.party_ledger.find({"firm_id": scope}, {"party_id": 1, "_id": 0}):
            if doc.get("party_id"):
                scoped_party_ids.add(doc["party_id"])
        for coll in (db.sales_invoices, db.purchases, db.payments, db.expenses):
            async for doc in coll.find({"firm_id": scope}, {"party_id": 1, "_id": 0}):
                if doc.get("party_id"):
                    scoped_party_ids.add(doc["party_id"])
        if not scoped_party_ids:
            return []
        filters.append({"id": {"$in": list(scoped_party_ids)}})

    query = {"$and": filters} if filters else {}

    parties = await db.parties.find(query, {"_id": 0}).sort("name", 1).skip(skip).limit(limit).to_list(limit)

    # Compute balances. For accountants the balance is firm-scoped (sum of
    # debits − credits on the in-firm ledger); for admin the legacy global
    # running_balance is used.
    for party in parties:
        if scope:
            agg = await db.party_ledger.aggregate([
                {"$match": {"party_id": party["id"], "firm_id": scope}},
                {"$group": {
                    "_id": None,
                    "debit": {"$sum": "$debit"},
                    "credit": {"$sum": "$credit"},
                    "last": {"$max": "$created_at"},
                }},
            ]).to_list(1)
            row = agg[0] if agg else {}
            balance = float(row.get("debit", 0) or 0) - float(row.get("credit", 0) or 0)
            party["current_balance"] = balance
            party["last_transaction_date"] = row.get("last")
        else:
            last_entry = await db.party_ledger.find_one(
                {"party_id": party["id"]},
                sort=[("created_at", -1)]
            )
            party["current_balance"] = (
                last_entry.get("running_balance", party.get("opening_balance", 0))
                if last_entry
                else party.get("opening_balance", 0)
            )
            party["last_transaction_date"] = last_entry.get("created_at") if last_entry else None

        if party["current_balance"] > 0:
            party["total_receivable"] = party["current_balance"]
            party["total_payable"] = 0
        else:
            party["total_receivable"] = 0
            party["total_payable"] = abs(party["current_balance"])

    return parties


@api_router.get("/parties/{party_id}")
async def get_party(
    party_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get single party with full details"""
    party = await db.parties.find_one({"id": party_id}, {"_id": 0})
    if not party:
        raise HTTPException(status_code=404, detail="Party not found")
    
    # Get balance info
    last_entry = await db.party_ledger.find_one(
        {"party_id": party_id},
        sort=[("created_at", -1)]
    )
    party["current_balance"] = last_entry.get("running_balance", party.get("opening_balance", 0)) if last_entry else party.get("opening_balance", 0)
    
    if party["current_balance"] > 0:
        party["total_receivable"] = party["current_balance"]
        party["total_payable"] = 0
    else:
        party["total_receivable"] = 0
        party["total_payable"] = abs(party["current_balance"])
    
    party["last_transaction_date"] = last_entry.get("created_at") if last_entry else None
    
    return party


@api_router.post("/parties", response_model=PartyResponse)
async def create_party(
    party_data: PartyCreate,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Create a new party (Admin and Accountant)"""
    now = datetime.now(timezone.utc)
    
    # Validate party types
    for pt in party_data.party_types:
        if pt not in PARTY_TYPES:
            raise HTTPException(status_code=400, detail=f"Invalid party type: {pt}")
    
    # Check for duplicate GSTIN (if provided)
    if party_data.gstin:
        existing = await db.parties.find_one({"gstin": party_data.gstin.upper()})
        if existing:
            raise HTTPException(status_code=400, detail=f"Party with GSTIN {party_data.gstin} already exists: {existing['name']}")
    
    # Check for duplicate phone
    if party_data.phone:
        existing = await db.parties.find_one({"phone": party_data.phone})
        if existing:
            raise HTTPException(status_code=400, detail=f"Party with phone {party_data.phone} already exists: {existing['name']}")
    
    # Get state code
    state_code = party_data.state_code or get_state_code(party_data.state)
    
    party = {
        "id": str(uuid.uuid4()),
        "name": party_data.name,
        "party_types": party_data.party_types,
        "gstin": party_data.gstin.upper() if party_data.gstin else None,
        "pan": party_data.pan.upper() if party_data.pan else None,
        "state": party_data.state,
        "state_code": state_code,
        "address": party_data.address,
        "city": party_data.city,
        "pincode": party_data.pincode,
        "phone": party_data.phone,
        "email": party_data.email.lower() if party_data.email else None,
        "contact_person": party_data.contact_person,
        "credit_limit": party_data.credit_limit or 0,
        "opening_balance": party_data.opening_balance or 0,
        "notes": party_data.notes,
        "source": "manual",
        "is_active": True,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat()
    }
    
    await db.parties.insert_one(party)
    
    # Create opening balance ledger entry if non-zero
    if party_data.opening_balance and party_data.opening_balance != 0:
        ledger_entry = {
            "id": str(uuid.uuid4()),
            "entry_number": f"OB-{party['id'][:8]}",
            "party_id": party["id"],
            "party_name": party["name"],
            "entry_type": "opening_balance",
            "debit": party_data.opening_balance if party_data.opening_balance > 0 else 0,
            "credit": abs(party_data.opening_balance) if party_data.opening_balance < 0 else 0,
            "running_balance": party_data.opening_balance,
            "narration": "Opening Balance",
            "reference_type": None,
            "reference_id": None,
            "created_by": user["id"],
            "created_by_name": f"{user['first_name']} {user['last_name']}",
            "created_at": now.isoformat()
        }
        await db.party_ledger.insert_one(ledger_entry)
    
    # Log activity
    await log_activity(
        action="party_created",
        entity_type="party",
        entity_id=party["id"],
        user=user,
        details={"name": party["name"], "party_types": party["party_types"]}
    )
    
    party["current_balance"] = party_data.opening_balance or 0
    party["total_receivable"] = party["current_balance"] if party["current_balance"] > 0 else 0
    party["total_payable"] = abs(party["current_balance"]) if party["current_balance"] < 0 else 0
    party["last_transaction_date"] = None
    
    return party


@api_router.patch("/parties/{party_id}", response_model=PartyResponse)
async def update_party(
    party_id: str,
    party_data: PartyUpdate,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update a party"""
    now = datetime.now(timezone.utc)
    
    party = await db.parties.find_one({"id": party_id})
    if not party:
        raise HTTPException(status_code=404, detail="Party not found")
    
    update_data = {"updated_at": now.isoformat()}
    
    if party_data.party_types is not None:
        for pt in party_data.party_types:
            if pt not in PARTY_TYPES:
                raise HTTPException(status_code=400, detail=f"Invalid party type: {pt}")
        update_data["party_types"] = party_data.party_types
    
    if party_data.gstin is not None:
        if party_data.gstin:
            existing = await db.parties.find_one({"gstin": party_data.gstin.upper(), "id": {"$ne": party_id}})
            if existing:
                raise HTTPException(status_code=400, detail=f"GSTIN already exists for: {existing['name']}")
        canonical_gst = party_data.gstin.upper() if party_data.gstin else None
        # Mirror into the legacy `gst_number` field. Older imports + the WA
        # agent's _create_party write `gst_number`; newer code reads `gstin`.
        # Keeping the two fields in sync prevents the drift we hit on
        # Shaktishri (UI edited gstin, gst_number stayed stale, and the
        # purchase register kept showing the old denormed snapshot).
        update_data["gstin"] = canonical_gst
        update_data["gst_number"] = canonical_gst

        # Refresh denormalised supplier_gstin on this party's DRAFT purchases
        # so the Purchase Register reflects the corrected GSTIN. Final / posted
        # purchases stay snapshotted for audit — only drafts get refreshed.
        await db.purchases.update_many(
            {
                "$or": [{"supplier_party_id": party_id}, {"supplier_id": party_id}],
                "doc_status": {"$in": ["draft", "pending"]},
            },
            {"$set": {"supplier_gstin": canonical_gst, "updated_at": now.isoformat()}},
        )
    
    for field in ["name", "pan", "state", "state_code", "address", "city", "pincode", 
                  "phone", "email", "contact_person", "credit_limit", "notes", "is_active"]:
        value = getattr(party_data, field, None)
        if value is not None:
            if field == "email" and value:
                value = value.lower()
            if field == "pan" and value:
                value = value.upper()
            update_data[field] = value
    
    # Handle TDS fields
    if party_data.tds_applicable is not None:
        update_data["tds_applicable"] = party_data.tds_applicable
    if party_data.tds_section is not None:
        update_data["tds_section"] = party_data.tds_section.upper() if party_data.tds_section else None
    if party_data.tds_party_type is not None:
        update_data["tds_party_type"] = party_data.tds_party_type
    if party_data.pan_number is not None:
        update_data["pan_number"] = party_data.pan_number.upper() if party_data.pan_number else None
    if party_data.tds_exemption is not None:
        update_data["tds_exemption"] = party_data.tds_exemption
    if party_data.tds_exemption_certificate is not None:
        update_data["tds_exemption_certificate"] = party_data.tds_exemption_certificate
    if party_data.tds_exemption_valid_till is not None:
        update_data["tds_exemption_valid_till"] = party_data.tds_exemption_valid_till
    
    # Update state code if state changed
    if party_data.state and not party_data.state_code:
        update_data["state_code"] = get_state_code(party_data.state)
    
    await db.parties.update_one({"id": party_id}, {"$set": update_data})
    
    updated = await db.parties.find_one({"id": party_id}, {"_id": 0})
    
    # Get balance
    last_entry = await db.party_ledger.find_one({"party_id": party_id}, sort=[("created_at", -1)])
    updated["current_balance"] = last_entry.get("running_balance", updated.get("opening_balance", 0)) if last_entry else updated.get("opening_balance", 0)
    updated["total_receivable"] = updated["current_balance"] if updated["current_balance"] > 0 else 0
    updated["total_payable"] = abs(updated["current_balance"]) if updated["current_balance"] < 0 else 0
    updated["last_transaction_date"] = last_entry.get("created_at") if last_entry else None
    
    return updated


@api_router.post("/parties/migrate-customers")
async def migrate_customers_to_parties(
    user: dict = Depends(require_roles(["admin"]))
):
    """
    Migrate existing customers from tickets to party master.
    Deduplicates by phone (primary) and GSTIN.
    """
    now = datetime.now(timezone.utc)
    
    # Get all unique customers from tickets
    pipeline = [
        {"$match": {"customer_phone": {"$exists": True, "$ne": None}}},
        {"$group": {
            "_id": "$customer_phone",
            "name": {"$first": "$customer_name"},
            "email": {"$first": "$customer_email"},
            "phone": {"$first": "$customer_phone"},
            "address": {"$first": "$customer_address"},
            "city": {"$first": "$customer_city"},
            "state": {"$first": "$customer_state"},
            "pincode": {"$first": "$customer_pincode"},
            "ticket_count": {"$sum": 1},
            "first_ticket_date": {"$min": "$created_at"}
        }}
    ]
    
    ticket_customers = await db.tickets.aggregate(pipeline).to_list(10000)
    
    # Also get from dispatches
    dispatch_pipeline = [
        {"$match": {"phone": {"$exists": True, "$ne": None}}},
        {"$group": {
            "_id": "$phone",
            "name": {"$first": "$customer_name"},
            "email": {"$first": {"$ifNull": ["$email", None]}},
            "phone": {"$first": "$phone"},
            "address": {"$first": "$address"},
            "city": {"$first": "$city"},
            "state": {"$first": "$state"},
            "pincode": {"$first": "$pincode"},
            "dispatch_count": {"$sum": 1}
        }}
    ]
    
    dispatch_customers = await db.dispatches.aggregate(dispatch_pipeline).to_list(10000)
    
    # Merge by phone
    customers_by_phone = {}
    
    for c in ticket_customers:
        phone = c["phone"]
        if phone not in customers_by_phone:
            customers_by_phone[phone] = {
                "name": c["name"],
                "phone": phone,
                "email": c.get("email"),
                "address": c.get("address"),
                "city": c.get("city"),
                "state": c.get("state") or "Delhi",  # Default
                "pincode": c.get("pincode"),
                "ticket_count": c.get("ticket_count", 0),
                "dispatch_count": 0
            }
        else:
            customers_by_phone[phone]["ticket_count"] = c.get("ticket_count", 0)
    
    for c in dispatch_customers:
        phone = c["phone"]
        if phone not in customers_by_phone:
            customers_by_phone[phone] = {
                "name": c["name"],
                "phone": phone,
                "email": c.get("email"),
                "address": c.get("address"),
                "city": c.get("city"),
                "state": c.get("state") or "Delhi",
                "pincode": c.get("pincode"),
                "ticket_count": 0,
                "dispatch_count": c.get("dispatch_count", 0)
            }
        else:
            customers_by_phone[phone]["dispatch_count"] = c.get("dispatch_count", 0)
            # Update fields if missing
            if not customers_by_phone[phone].get("name"):
                customers_by_phone[phone]["name"] = c["name"]
            if not customers_by_phone[phone].get("address"):
                customers_by_phone[phone]["address"] = c.get("address")
    
    migrated = 0
    skipped = 0
    merged = 0
    
    for phone, cust in customers_by_phone.items():
        # Check if already exists
        existing = await db.parties.find_one({"phone": phone})
        if existing:
            skipped += 1
            continue
        
        # Create party
        state = cust.get("state") or "Delhi"
        party = {
            "id": str(uuid.uuid4()),
            "name": cust["name"] or f"Customer {phone}",
            "party_types": ["customer"],
            "gstin": None,
            "pan": None,
            "state": state,
            "state_code": get_state_code(state),
            "address": cust.get("address"),
            "city": cust.get("city"),
            "pincode": cust.get("pincode"),
            "phone": phone,
            "email": cust.get("email"),
            "contact_person": None,
            "credit_limit": 0,
            "opening_balance": 0,
            "notes": f"Tickets: {cust.get('ticket_count', 0)}, Dispatches: {cust.get('dispatch_count', 0)}",
            "source": "migrated_from_tickets",
            "is_active": True,
            "created_at": now.isoformat(),
            "updated_at": now.isoformat()
        }
        
        await db.parties.insert_one(party)
        migrated += 1
    
    await log_activity(
        action="customers_migrated",
        entity_type="party",
        entity_id="migration",
        user=user,
        details={"migrated": migrated, "skipped": skipped, "merged": merged}
    )
    
    return {
        "success": True,
        "migrated": migrated,
        "skipped": skipped,
        "merged": merged,
        "message": f"Migration complete. Created {migrated} parties, skipped {skipped} duplicates."
    }


# ==================== SALES REGISTER MODULE ====================

PAYMENT_STATUSES = ["unpaid", "partial", "paid"]

class SalesInvoiceItem(BaseModel):
    master_sku_id: str
    sku_code: str
    name: str
    hsn_code: Optional[str] = None
    quantity: int
    rate: float  # Unit rate
    gst_rate: float = 18  # 0, 5, 12, 18, 28
    discount: float = 0
    taxable_value: Optional[float] = None  # Computed
    gst_amount: Optional[float] = None  # Computed

class SalesInvoiceCreate(BaseModel):
    firm_id: str
    party_id: str
    dispatch_id: str  # Must link to dispatch
    invoice_date: str
    items: List[SalesInvoiceItem]
    shipping_charges: float = 0
    other_charges: float = 0
    discount: float = 0
    notes: Optional[str] = None
    gst_override: Optional[bool] = False  # Manual GST override
    override_igst: Optional[float] = None
    override_cgst: Optional[float] = None
    override_sgst: Optional[float] = None
    save_as_draft: Optional[bool] = False  # If True, saves as draft even with validation errors

class SalesInvoiceResponse(BaseModel):
    id: str
    invoice_number: str
    firm_id: str
    firm_name: str
    party_id: str
    party_name: str
    party_gstin: Optional[str] = None
    dispatch_id: str
    dispatch_number: str
    invoice_date: str
    items: List[dict]
    subtotal: float
    shipping_charges: float
    other_charges: float
    discount: float
    taxable_value: float
    is_igst: bool  # True = IGST, False = CGST+SGST
    igst: float
    cgst: float
    sgst: float
    total_gst: float
    grand_total: float
    payment_status: str
    amount_paid: float
    balance_due: float
    gst_override: bool
    notes: Optional[str] = None
    created_by: str
    created_by_name: str
    created_at: str
    updated_at: str


@api_router.get("/sales-invoices")
async def list_sales_invoices(
    firm_id: Optional[str] = None,
    party_id: Optional[str] = None,
    payment_status: Optional[str] = None,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    search: Optional[str] = None,
    limit: int = 100,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """List all sales invoices with filters - FIRM SCOPE ENFORCED for accountants"""
    query = {}
    
    # CRITICAL FIX: Enforce firm scope for accountants
    firm_scope = get_user_firm_scope(user)
    if firm_scope:
        query["firm_id"] = firm_scope
    elif firm_id:
        # Admin can still filter by firm_id if they want
        query["firm_id"] = firm_id
    
    if party_id:
        query["party_id"] = party_id
    if payment_status:
        query["payment_status"] = payment_status
    if from_date:
        query["invoice_date"] = {"$gte": from_date}
    if to_date:
        query.setdefault("invoice_date", {})["$lte"] = to_date
    if search:
        query["$or"] = [
            {"invoice_number": {"$regex": search, "$options": "i"}},
            {"party_name": {"$regex": search, "$options": "i"}},
            {"dispatch_number": {"$regex": search, "$options": "i"}}
        ]
    
    invoices = await db.sales_invoices.find(query, {"_id": 0}).sort("created_at", -1).to_list(limit)
    for inv in invoices:
        sign_file_urls_deep(inv, user["id"])  # invoice PDF / attachments open via plain link
    return invoices


@api_router.get("/sales-invoices/{invoice_id}")
async def get_sales_invoice(
    invoice_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get single sales invoice"""
    invoice = await db.sales_invoices.find_one({"id": invoice_id}, {"_id": 0})
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")
    assert_firm_access(user, invoice.get("firm_id"))
    sign_file_urls_deep(invoice, user["id"])
    return invoice


@api_router.get("/sales-invoices/dispatch-details/{dispatch_id}")
async def get_dispatch_for_invoice(
    dispatch_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get dispatch details and ensure customer party exists for invoice creation"""
    dispatch = await db.dispatches.find_one({"id": dispatch_id}, {"_id": 0})
    if not dispatch:
        raise HTTPException(status_code=404, detail="Dispatch not found")
    
    # Ensure customer party exists
    customer_phone = dispatch.get("phone") or dispatch.get("customer_phone")
    customer_name = dispatch.get("customer_name")
    
    if customer_phone:
        phone_normalized = customer_phone[-10:]
        
        # Find or create party
        party = await db.parties.find_one({
            "$or": [
                {"phone": customer_phone},
                {"phone": phone_normalized},
                {"phone": {"$regex": phone_normalized + "$"}}
            ]
        }, {"_id": 0})
        
        if not party:
            # Create customer party
            party_id = await ensure_customer_party(
                customer_name=customer_name,
                phone=customer_phone,
                address=dispatch.get("address"),
                city=dispatch.get("city"),
                state=dispatch.get("state") or "Unknown",
                pincode=dispatch.get("pincode")
            )
            party = await db.parties.find_one({"id": party_id}, {"_id": 0})
        
        dispatch["party"] = party
        dispatch["party_id"] = party.get("id") if party else None
    
    # Get items from dispatch (typically the SKU)
    dispatch_items = []
    sku_code = dispatch.get("sku")
    if sku_code:
        # Find master SKU for this
        master_sku = await db.master_skus.find_one({
            "$or": [
                {"sku_code": sku_code},
                {"aliases.alias_code": sku_code}
            ]
        }, {"_id": 0})
        
        if master_sku:
            dispatch_items.append({
                "master_sku_id": master_sku.get("id"),
                "sku_code": master_sku.get("sku_code"),
                "name": master_sku.get("name"),
                "hsn_code": str(master_sku.get("hsn_code", "")) if master_sku.get("hsn_code") else "",
                "quantity": 1,
                "rate": master_sku.get("mrp", 0) or master_sku.get("selling_price", 0) or 0,
                "gst_rate": 18,  # Default GST
                "discount": 0
            })
    
    dispatch["suggested_items"] = dispatch_items
    dispatch["invoice_value"] = dispatch.get("invoice_value", 0)
    
    return dispatch


@api_router.post("/sales-invoices", response_model=SalesInvoiceResponse)
async def create_sales_invoice(
    invoice_data: SalesInvoiceCreate,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Create a sales invoice linked to dispatch"""
    now = datetime.now(timezone.utc)

    # Enforce firm scope (accountants must not invoice another firm's dispatch).
    assert_firm_access(user, invoice_data.firm_id)

    # Validate firm
    firm = await db.firms.find_one({"id": invoice_data.firm_id, "is_active": True})
    if not firm:
        raise HTTPException(status_code=400, detail="Invalid or inactive firm")

    # Validate party
    party = await db.parties.find_one({"id": invoice_data.party_id, "is_active": True})
    if not party:
        raise HTTPException(status_code=400, detail="Invalid or inactive party")

    if "customer" not in party.get("party_types", []):
        raise HTTPException(status_code=400, detail="Party must be a customer for sales invoice")

    # Validate dispatch
    dispatch = await db.dispatches.find_one({"id": invoice_data.dispatch_id})
    if not dispatch:
        raise HTTPException(status_code=400, detail="Dispatch not found")

    # Check if invoice already exists for this dispatch
    existing_invoice = await db.sales_invoices.find_one({"dispatch_id": invoice_data.dispatch_id})
    if existing_invoice:
        raise HTTPException(status_code=400, detail=f"Invoice {existing_invoice['invoice_number']} already exists for this dispatch")

    # Determine IGST vs CGST/SGST. Fail closed if state cannot be determined —
    # the previous default treated missing-state customers as IGST regardless
    # of physical location.
    firm_state_code = firm.get("gstin", "")[:2] if firm.get("gstin") else get_state_code(firm.get("state", ""))
    party_state_code = party.get("state_code") or get_state_code(party.get("state", ""))
    if not firm_state_code or not party_state_code:
        raise HTTPException(
            status_code=400,
            detail="Cannot compute GST: missing firm or party state code (set GSTIN or state on both).",
        )
    is_igst = firm_state_code != party_state_code
    
    # Calculate item totals
    items = []
    # Use Decimal for all per-invoice money math. Float carries paise-level
    # drift that breaks the invariant cgst + sgst == total_gst over long
    # invoices; Decimal + quantize(0.01, ROUND_HALF_UP) preserves it exactly.
    from decimal import Decimal, ROUND_HALF_UP

    def _D(value) -> Decimal:
        if value is None:
            return Decimal("0")
        return Decimal(str(value))

    def _q2(value: Decimal) -> Decimal:
        return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    subtotal = Decimal("0")
    total_igst = Decimal("0")
    total_cgst = Decimal("0")
    total_sgst = Decimal("0")

    for item in invoice_data.items:
        taxable = _q2(_D(item.quantity) * _D(item.rate) - _D(item.discount))
        gst_rate = _D(item.gst_rate)
        gst_amount = _q2(taxable * gst_rate / Decimal("100"))
        # Split CGST/SGST so the two halves SUM exactly to gst_amount (avoids
        # the classic 1-paise off where round(x/2)+round(x/2) != round(x)).
        half = _q2(gst_amount / Decimal("2"))
        other_half = _q2(gst_amount - half)

        item_dict = {
            "master_sku_id": item.master_sku_id,
            "sku_code": item.sku_code,
            "name": item.name,
            "hsn_code": item.hsn_code,
            "quantity": item.quantity,
            "rate": item.rate,
            "gst_rate": item.gst_rate,
            "discount": item.discount,
            "taxable_value": float(taxable),
            "gst_amount": float(gst_amount),
        }
        items.append(item_dict)
        subtotal += taxable

        if is_igst:
            total_igst += gst_amount
        else:
            total_cgst += half
            total_sgst += other_half

    shipping = _D(invoice_data.shipping_charges)
    other_charges = _D(invoice_data.other_charges)
    discount = _D(invoice_data.discount)
    taxable_value = _q2(subtotal + shipping + other_charges - discount)

    if discount > 0 and subtotal > 0:
        # Scale per-item GST proportionally so total_gst is computed on the
        # post-discount taxable base (otherwise the global discount escapes
        # GST and GSTR-1 won't reconcile against the stated taxable value).
        ratio = (subtotal - discount) / subtotal
        if ratio < 0:
            ratio = Decimal("0")
        total_igst = _q2(total_igst * ratio)
        total_cgst = _q2(total_cgst * ratio)
        total_sgst = _q2(total_sgst * ratio)

    total_gst = _q2(total_igst + total_cgst + total_sgst)

    # Handle GST override
    if invoice_data.gst_override:
        total_igst = _D(invoice_data.override_igst)
        total_cgst = _D(invoice_data.override_cgst)
        total_sgst = _D(invoice_data.override_sgst)
        total_gst = _q2(total_igst + total_cgst + total_sgst)
        is_igst = total_igst > 0

    grand_total = _q2(taxable_value + total_gst)
    # Cast back to float for storage (Mongo + JSON), values already quantized.
    subtotal = float(subtotal)
    taxable_value = float(taxable_value)
    total_igst = float(total_igst)
    total_cgst = float(total_cgst)
    total_sgst = float(total_sgst)
    total_gst = float(total_gst)
    grand_total = float(grand_total)
    
    # Generate invoice number
    invoice_number = await get_next_invoice_number(invoice_data.firm_id)
    
    # ====== COMPLIANCE VALIDATION ======
    compliance_data = {
        "dispatch_id": invoice_data.dispatch_id,
        "invoice_number": invoice_number,
        "invoice_date": invoice_data.invoice_date,
        "party_id": invoice_data.party_id,
        "taxable_value": round(taxable_value, 2),
        "total_gst": round(total_gst, 2)
    }
    
    compliance_result = validate_document_compliance(
        "sales_invoice",
        compliance_data,
        {},
        grand_total
    )
    
    # Determine status and doc_status
    if not compliance_result["can_proceed"] and not invoice_data.save_as_draft:
        raise HTTPException(
            status_code=400,
            detail={
                "message": "Compliance validation failed - cannot post final entry",
                "hard_blocks": compliance_result["hard_blocks"],
                "missing_critical": compliance_result["missing_critical"],
                "suggestion": "Fix issues or save as draft"
            }
        )
    
    # Set status based on draft flag and compliance
    if invoice_data.save_as_draft:
        entry_status = "draft"
        doc_status = "pending" if compliance_result["soft_blocks"] or compliance_result["hard_blocks"] else "complete"
    else:
        entry_status = "final"
        doc_status = compliance_result["status"]
    
    invoice_id = str(uuid.uuid4())
    
    invoice = {
        "id": invoice_id,
        "invoice_number": invoice_number,
        "firm_id": invoice_data.firm_id,
        "firm_name": firm["name"],
        "party_id": invoice_data.party_id,
        "party_name": party["name"],
        "party_gstin": party.get("gstin"),
        "dispatch_id": invoice_data.dispatch_id,
        "dispatch_number": dispatch.get("dispatch_number"),
        "invoice_date": invoice_data.invoice_date,
        "items": items,
        "subtotal": round(subtotal, 2),
        "shipping_charges": invoice_data.shipping_charges,
        "other_charges": invoice_data.other_charges,
        "discount": invoice_data.discount,
        "taxable_value": round(taxable_value, 2),
        "is_igst": is_igst,
        "igst": round(total_igst, 2),
        "cgst": round(total_cgst, 2),
        "sgst": round(total_sgst, 2),
        "total_gst": round(total_gst, 2),
        "grand_total": grand_total,
        "payment_status": "unpaid",
        "amount_paid": 0,
        "balance_due": grand_total,
        "gst_override": invoice_data.gst_override or False,
        "notes": invoice_data.notes,
        "status": entry_status,
        "doc_status": doc_status,
        "compliance_score": compliance_result["compliance_score"],
        "compliance_issues": compliance_result.get("soft_blocks", []) + compliance_result.get("warnings", []),
        "created_by": user["id"],
        "created_by_name": f"{user['first_name']} {user['last_name']}",
        "created_at": now.isoformat(),
        "updated_at": now.isoformat()
    }
    
    await db.sales_invoices.insert_one(invoice)
    
    # Create compliance exception if there are issues (for non-draft entries)
    if entry_status == "final" and doc_status == "pending" and (compliance_result["soft_blocks"] or compliance_result["missing_important"]):
        severity = "critical" if compliance_result["missing_critical"] else "important"
        await create_compliance_exception(
            transaction_type="sales_invoice",
            transaction_id=invoice_id,
            transaction_ref=invoice_number,
            firm_id=invoice_data.firm_id,
            issues=compliance_result["soft_blocks"] + [f"Missing: {m['label']}" for m in compliance_result.get("missing_important", [])],
            severity=severity,
            user=user
        )
    
    # ATOMIC party ledger entry - ONLY for final entries
    if entry_status == "final":
        await create_party_ledger_entry_atomic(
            party_id=invoice_data.party_id,
            party_name=party["name"],
            entry_type="sales_invoice",
            debit=grand_total,  # Customer owes this
            credit=0,
            narration=f"Sales Invoice {invoice_number}",
            reference_type="sales_invoice",
            reference_id=invoice["id"],
            firm_id=invoice_data.firm_id,
            user_id=user["id"],
            user_name=f"{user['first_name']} {user['last_name']}",
            entry_number=f"SI-{invoice_number}",
            opening_balance=party.get("opening_balance", 0)
        )
        
        # Update dispatch with invoice reference
        await db.dispatches.update_one(
            {"id": invoice_data.dispatch_id},
            {"$set": {"sales_invoice_id": invoice["id"], "sales_invoice_number": invoice_number}}
        )
    
    # Log activity
    await log_activity(
        action="sales_invoice_created",
        entity_type="sales_invoice",
        entity_id=invoice["id"],
        user=user,
        details={
            "invoice_number": invoice_number,
            "party_name": party["name"],
            "grand_total": grand_total,
            "status": entry_status,
            "doc_status": doc_status
        }
    )
    
    return invoice


@api_router.get("/sales-invoices/by-dispatch/{dispatch_id}")
async def get_invoice_by_dispatch(
    dispatch_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get sales invoice for a dispatch if exists"""
    invoice = await db.sales_invoices.find_one({"dispatch_id": dispatch_id}, {"_id": 0})
    return invoice


@api_router.put("/sales-invoices/{invoice_id}")
async def update_sales_invoice(
    invoice_id: str,
    invoice_data: dict = Body(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update an existing sales invoice.

    Three correctness fixes vs the previous implementation:
    1. Firm scope is enforced (accountants couldn't be locked out before).
    2. Global invoice discount no longer slips past GST (it was applied AFTER
       totals, effectively granting a tax-free discount). Per-item discount
       remains the canonical source.
    3. IGST vs CGST/SGST is decided by GSTIN state-code prefix, matching the
       creation path. The previous state-NAME compare flipped tax treatment
       silently when "Karnataka" disagreed with GSTIN "29...".
    4. Party ledger receivable is rebalanced on grand_total change — the
       receivable used to stay pinned at the original amount forever.
    """
    now = datetime.now(timezone.utc)

    # Find existing invoice
    existing = await db.sales_invoices.find_one({"id": invoice_id})
    if not existing:
        raise HTTPException(status_code=404, detail="Invoice not found")
    assert_firm_access(user, existing.get("firm_id"))

    original_grand_total = float(existing.get("grand_total") or 0)
    original_party_id = existing.get("party_id")

    # Build update dict - only update allowed fields
    update_dict = {"updated_at": now.isoformat()}

    # Allow updating items with recalculation
    if "items" in invoice_data:
        items = invoice_data["items"]
        for item in items:
            item["total"] = item.get("quantity", 0) * item.get("rate", 0)
            item["taxable_value"] = item["total"] - item.get("discount", 0)
            item["gst_amount"] = item["taxable_value"] * (item.get("gst_rate", 18) / 100)
            item["total_amount"] = item["taxable_value"] + item["gst_amount"]
        update_dict["items"] = items

        # Per-item discount is already applied to each item's taxable_value
        # above. Do NOT subtract `invoice_data["discount"]` from the totals
        # below — that would untax the global discount portion.
        subtotal = sum(item.get("total", 0) for item in items)
        item_level_discount = sum(item.get("discount", 0) for item in items)
        taxable_value = subtotal - item_level_discount
        total_gst = sum(item.get("gst_amount", 0) for item in items)
        grand_total = taxable_value + total_gst

        update_dict["subtotal"] = subtotal
        update_dict["total_discount"] = item_level_discount
        update_dict["taxable_value"] = taxable_value
        update_dict["total_gst"] = total_gst
        update_dict["grand_total"] = grand_total

    # Allow updating payment status
    if "payment_status" in invoice_data:
        update_dict["payment_status"] = invoice_data["payment_status"]

    # Allow updating notes
    if "notes" in invoice_data:
        update_dict["notes"] = invoice_data["notes"]

    # Allow updating party info
    if "party_id" in invoice_data:
        party = await db.parties.find_one({"id": invoice_data["party_id"], "is_active": True})
        if party:
            update_dict["party_id"] = invoice_data["party_id"]
            update_dict["party_name"] = party.get("name")
            update_dict["party_gstin"] = party.get("gstin")
            update_dict["party_state_code"] = party.get("state_code") or (party.get("gstin") or "")[:2]
            update_dict["party_state"] = invoice_data.get("party_state") or party.get("state")

    if "party_state" in invoice_data and "party_id" not in invoice_data:
        update_dict["party_state"] = invoice_data["party_state"]

    # Calculate CGST/SGST vs IGST from GSTIN state codes (creation also uses
    # this — state-name strings disagree with GSTINs and flip tax wrong).
    firm = await db.firms.find_one({"id": existing.get("firm_id")})
    firm_state_code = (firm.get("gstin") or "")[:2] if firm else ""
    party_state_code = (
        update_dict.get("party_state_code")
        or existing.get("party_state_code")
        or (existing.get("party_gstin") or "")[:2]
    )

    if "items" in update_dict:
        total_gst = update_dict.get("total_gst", 0)
        if not firm_state_code or not party_state_code:
            # Fail closed — do not silently default to IGST when state data is
            # missing (the previous default mis-taxed missing-state customers).
            raise HTTPException(
                status_code=400,
                detail="Cannot compute GST: missing firm/party state code",
            )
        if firm_state_code == party_state_code:
            update_dict["cgst"] = round(total_gst / 2, 2)
            update_dict["sgst"] = round(total_gst / 2, 2)
            update_dict["igst"] = 0
        else:
            update_dict["cgst"] = 0
            update_dict["sgst"] = 0
            update_dict["igst"] = round(total_gst, 2)

    # Track who made the edit
    update_dict["edited_by"] = user.get("id")
    update_dict["edited_by_name"] = user.get("name")
    update_dict["edited_at"] = now.isoformat()

    await db.sales_invoices.update_one({"id": invoice_id}, {"$set": update_dict})

    # Rebalance the party ledger if grand_total changed. Post the DELTA as a
    # reversal-and-repost via the atomic helper so concurrent writes can't
    # corrupt the running balance.
    new_grand_total = float(update_dict.get("grand_total", original_grand_total) or 0)
    delta = new_grand_total - original_grand_total
    if delta and original_party_id:
        party_doc = await db.parties.find_one({"id": original_party_id}, {"_id": 0})
        if party_doc:
            await create_party_ledger_entry_atomic(
                party_id=original_party_id,
                party_name=party_doc.get("name"),
                entry_type="sales_invoice_edit",
                debit=max(0.0, delta),
                credit=max(0.0, -delta),
                narration=f"Invoice {existing.get('invoice_number')} edited "
                          f"(Δ {delta:+.2f})",
                reference_type="sales_invoice_edit",
                reference_id=invoice_id,
                firm_id=existing.get("firm_id"),
                user_id=user["id"],
                user_name=f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
                entry_number=f"INV-EDIT-{existing.get('invoice_number')}",
                opening_balance=party_doc.get("opening_balance", 0),
            )

    updated = await db.sales_invoices.find_one({"id": invoice_id}, {"_id": 0})
    return {"message": "Invoice updated", "invoice": updated}


@api_router.post("/sales-invoices/from-dispatch/{dispatch_id}")
async def create_invoice_for_dispatch(
    dispatch_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Create a sales invoice for a specific dispatch.
    Used after fixing a dispatch with missing data.
    """
    # Find the dispatch
    dispatch = await db.dispatches.find_one({"id": dispatch_id}, {"_id": 0})
    if not dispatch:
        raise HTTPException(status_code=404, detail="Dispatch not found")
    
    # Check if invoice already exists
    existing_invoice = await db.sales_invoices.find_one({"dispatch_id": dispatch_id})
    if existing_invoice:
        raise HTTPException(status_code=400, detail="Dispatch already has invoice")
    
    # Validate required fields
    missing_fields = []
    if not dispatch.get("state"):
        missing_fields.append("state")
    if not dispatch.get("firm_id"):
        missing_fields.append("firm_id")
    
    # Check SKU and pricing
    dispatch_has_pricing = (
        dispatch.get("invoice_value") or 
        dispatch.get("taxable_value") or 
        dispatch.get("selling_price")
    )
    
    master_sku = None
    if dispatch.get("master_sku_id"):
        master_sku = await db.master_skus.find_one({"id": dispatch.get("master_sku_id")}, {"_id": 0})
    elif dispatch.get("sku"):
        master_sku = await db.master_skus.find_one({"sku_code": dispatch.get("sku")}, {"_id": 0})
    
    if not master_sku:
        missing_fields.append("valid_sku")
    elif not dispatch_has_pricing:
        if not master_sku.get("selling_price") and not master_sku.get("mrp") and not master_sku.get("cost_price"):
            missing_fields.append("sku_price")
    
    if missing_fields:
        raise HTTPException(
            status_code=400, 
            detail=f"Dispatch still has missing data: {', '.join(missing_fields)}"
        )
    
    # Create the invoice
    invoice = await create_sales_invoice_from_dispatch(dispatch, db)
    
    if not invoice:
        raise HTTPException(status_code=500, detail="Failed to create invoice - check dispatch data")
    
    return {
        "message": "Invoice created successfully",
        "invoice": invoice
    }


@api_router.post("/sales-invoices/{invoice_id}/recalculate")
async def recalculate_sales_invoice(
    invoice_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Recalculate a sales invoice that has zero values.
    Pulls fresh data from the dispatch and SKU.
    """
    invoice = await db.sales_invoices.find_one({"id": invoice_id})
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")
    
    dispatch_id = invoice.get("dispatch_id")
    if not dispatch_id:
        raise HTTPException(status_code=400, detail="Invoice not linked to a dispatch - cannot recalculate")
    
    # Get fresh dispatch data
    dispatch = await db.dispatches.find_one({"id": dispatch_id}, {"_id": 0})
    if not dispatch:
        raise HTTPException(status_code=404, detail="Linked dispatch not found")
    
    # Get SKU details
    master_sku = None
    if dispatch.get("master_sku_id"):
        master_sku = await db.master_skus.find_one({"id": dispatch.get("master_sku_id")}, {"_id": 0})
    elif dispatch.get("sku"):
        master_sku = await db.master_skus.find_one({"sku_code": dispatch.get("sku")}, {"_id": 0})
    
    if not master_sku:
        raise HTTPException(status_code=400, detail="SKU not found - cannot recalculate")
    
    # Determine pricing - PRIORITIZE dispatch's invoice_value/taxable_value
    quantity = dispatch.get("quantity", 1) or 1
    gst_rate = dispatch.get("gst_rate") or master_sku.get("gst_rate", 18) or 18
    hsn_code = master_sku.get("hsn_code", "")
    
    dispatch_invoice_value = dispatch.get("invoice_value") or 0
    dispatch_taxable_value = dispatch.get("taxable_value") or 0
    dispatch_selling_price = dispatch.get("selling_price") or 0
    
    if dispatch_taxable_value > 0:
        taxable_value = dispatch_taxable_value
    elif dispatch_invoice_value > 0:
        taxable_value = dispatch_invoice_value / (1 + gst_rate / 100)
    elif dispatch_selling_price > 0:
        taxable_value = dispatch_selling_price * quantity
    else:
        unit_price = master_sku.get("selling_price") or master_sku.get("mrp") or master_sku.get("cost_price", 0) or 0
        taxable_value = unit_price * quantity
    
    if taxable_value == 0:
        raise HTTPException(
            status_code=400, 
            detail="No pricing found. Set invoice_value on dispatch or selling_price/mrp/cost_price on SKU."
        )
    
    # Calculate GST
    gst_amount = taxable_value * (gst_rate / 100)
    grand_total = taxable_value + gst_amount
    
    # Determine CGST/SGST vs IGST based on state
    firm = await db.firms.find_one({"id": dispatch.get("firm_id")}, {"_id": 0})
    firm_state = firm.get("state", "") if firm else ""
    party_state = dispatch.get("state", "")
    
    is_intra_state = firm_state and party_state and firm_state.lower() == party_state.lower()
    
    # Update the invoice
    update_data = {
        "items": [{
            "master_sku_id": master_sku["id"],
            "sku_name": master_sku.get("name"),
            "sku_code": master_sku.get("sku_code"),
            "hsn_code": hsn_code,
            "quantity": quantity,
            "rate": round(taxable_value / quantity, 2),
            "gst_rate": gst_rate,
            "discount": 0,
            "total": taxable_value,
            "taxable_value": taxable_value,
            "gst_amount": gst_amount,
            "total_amount": grand_total
        }],
        "subtotal": taxable_value,
        "total_discount": 0,
        "taxable_value": taxable_value,
        "total_gst": gst_amount,
        "cgst": gst_amount / 2 if is_intra_state else 0,
        "sgst": gst_amount / 2 if is_intra_state else 0,
        "igst": 0 if is_intra_state else gst_amount,
        "grand_total": grand_total,
        "party_state": party_state,
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "recalculated_by": user.get("id"),
        "recalculated_at": datetime.now(timezone.utc).isoformat()
    }
    
    await db.sales_invoices.update_one({"id": invoice_id}, {"$set": update_data})
    
    updated_invoice = await db.sales_invoices.find_one({"id": invoice_id}, {"_id": 0})
    
    return {
        "message": f"Invoice recalculated. New total: ₹{grand_total:,.2f}",
        "invoice": updated_invoice
    }


@api_router.post("/sales-invoices/backfill")
async def backfill_sales_invoices(
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Backfill sales invoices for all dispatches that don't have one.
    This generates invoices for historical dispatches.
    Returns details of any dispatches with missing data.
    """
    # Find all dispatches without sales invoices
    all_dispatches = await db.dispatches.find({}, {"_id": 0}).to_list(50000)
    
    created = 0
    skipped = 0
    errors = []
    missing_data = []  # Dispatches with incomplete data
    
    for dispatch in all_dispatches:
        try:
            # Check if invoice already exists
            existing = await db.sales_invoices.find_one({"dispatch_id": dispatch.get("id")})
            if existing:
                skipped += 1
                continue
            
            # Check for missing required data
            missing_fields = []
            if not dispatch.get("firm_id"):
                missing_fields.append("firm_id")
            if not dispatch.get("master_sku_id") and not dispatch.get("sku"):
                missing_fields.append("sku/master_sku_id")
            if not dispatch.get("customer_name"):
                missing_fields.append("customer_name")
            if not dispatch.get("state"):
                missing_fields.append("state")
            
            # Check if SKU has valid pricing - ONLY if dispatch doesn't already have pricing
            dispatch_has_pricing = (
                dispatch.get("invoice_value") or 
                dispatch.get("taxable_value") or 
                dispatch.get("selling_price")
            )
            
            master_sku = None
            if dispatch.get("master_sku_id"):
                master_sku = await db.master_skus.find_one({"id": dispatch.get("master_sku_id")}, {"_id": 0})
            if not master_sku and dispatch.get("sku"):
                master_sku = await db.master_skus.find_one({"sku_code": dispatch.get("sku")}, {"_id": 0})
            
            if not master_sku:
                missing_fields.append("valid_sku")
            elif not dispatch_has_pricing:
                # Only check SKU price if dispatch doesn't have its own pricing
                if not master_sku.get("selling_price") and not master_sku.get("mrp") and not master_sku.get("cost_price"):
                    missing_fields.append("sku_price")
            
            if missing_fields:
                missing_data.append({
                    "dispatch_id": dispatch.get("id"),
                    "dispatch_number": dispatch.get("dispatch_number"),
                    "customer_name": dispatch.get("customer_name", "Unknown"),
                    "sku": dispatch.get("sku", "Unknown"),
                    "missing_fields": missing_fields
                })
                skipped += 1
                continue
            
            # Try to create invoice
            invoice = await create_sales_invoice_from_dispatch(dispatch, db)
            if invoice:
                created += 1
            else:
                skipped += 1
        except Exception as e:
            errors.append({"dispatch_id": dispatch.get("id"), "dispatch_number": dispatch.get("dispatch_number"), "error": str(e)})
    
    return {
        "message": "Backfill complete",
        "created": created,
        "skipped": skipped,
        "errors_count": len(errors),
        "missing_data_count": len(missing_data),
        "missing_data": missing_data[:50],  # Return first 50 with missing data
        "errors": errors[:20]  # Return first 20 errors
    }


@api_router.get("/dispatches-without-invoice")
async def get_dispatches_without_invoice(
    firm_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get dispatches that don't have a sales invoice yet, with SKU details and missing field info"""
    query = {
        "status": "dispatched",
        "$or": [
            {"sales_invoice_id": {"$exists": False}},
            {"sales_invoice_id": None}
        ]
    }
    if firm_id:
        query["firm_id"] = firm_id
    
    dispatches = await db.dispatches.find(query, {"_id": 0}).sort("created_at", -1).to_list(200)
    
    # Also get dispatches without sales invoice in sales_invoices collection
    all_dispatch_ids = [d.get("id") for d in dispatches]
    existing_invoices = await db.sales_invoices.find(
        {"dispatch_id": {"$in": all_dispatch_ids}},
        {"dispatch_id": 1}
    ).to_list(10000)
    existing_dispatch_ids = {inv["dispatch_id"] for inv in existing_invoices}
    
    # Filter out dispatches that already have invoices
    dispatches = [d for d in dispatches if d.get("id") not in existing_dispatch_ids]
    
    # Batch-fetch master SKUs once (id-based AND sku_code/name-based) instead
    # of issuing 1-2 find_one calls per dispatch row. 200 dispatches used to
    # mean up to 400 round-trips here.
    needed_sku_ids = {d["master_sku_id"] for d in dispatches if d.get("master_sku_id")}
    needed_sku_codes = {
        d["sku"] for d in dispatches if d.get("sku") and not d.get("master_sku_id")
    }
    sku_by_id: dict[str, dict] = {}
    sku_by_code: dict[str, dict] = {}
    if needed_sku_ids:
        async for sku in db.master_skus.find({"id": {"$in": list(needed_sku_ids)}}, {"_id": 0}):
            sku_by_id[sku["id"]] = sku
    if needed_sku_codes:
        async for sku in db.master_skus.find(
            {"sku_code": {"$in": list(needed_sku_codes)}}, {"_id": 0}
        ):
            sku_by_code[sku.get("sku_code")] = sku

    # Enrich dispatches with master SKU info and identify missing fields
    for dispatch in dispatches:
        missing_fields = []

        # Check state
        if not dispatch.get("state"):
            missing_fields.append("state")

        # Check customer name
        if not dispatch.get("customer_name"):
            missing_fields.append("customer_name")

        # Check firm
        if not dispatch.get("firm_id"):
            missing_fields.append("firm_id")

        sku = None
        if dispatch.get("master_sku_id"):
            sku = sku_by_id.get(dispatch["master_sku_id"])
        elif dispatch.get("sku"):
            sku = sku_by_code.get(dispatch["sku"])
            if sku:
                dispatch["master_sku_id"] = sku.get("id")
        
        # Check if dispatch already has pricing (from invoice_value, taxable_value, or selling_price)
        dispatch_has_pricing = (
            dispatch.get("invoice_value") or 
            dispatch.get("taxable_value") or 
            dispatch.get("selling_price")
        )
        
        if sku:
            dispatch["hsn_code"] = sku.get("hsn_code")
            dispatch["gst_rate"] = sku.get("gst_rate", 18)
            dispatch["sku_name"] = sku.get("name")
            # Use dispatch's existing price if available, otherwise fall back to SKU
            if not dispatch_has_pricing:
                dispatch["selling_price"] = sku.get("selling_price") or sku.get("mrp") or sku.get("cost_price") or 0
            
            # Check if SKU has valid pricing - ONLY if dispatch doesn't have its own pricing
            if not dispatch_has_pricing:
                if not sku.get("selling_price") and not sku.get("mrp") and not sku.get("cost_price"):
                    missing_fields.append("sku_price")
        else:
            missing_fields.append("valid_sku")
        
        # Default quantity to 1 if not set
        if not dispatch.get("quantity"):
            dispatch["quantity"] = 1
        
        # Add missing fields info
        dispatch["missing_fields"] = missing_fields
        dispatch["can_generate_invoice"] = len(missing_fields) == 0
    
    return dispatches


