PAYMENT_MODES = ["cash", "bank_transfer", "upi", "cheque", "card", "other"]
PAYMENT_TYPES = ["received", "made"]  # received = from customer, made = to supplier/contractor

class PaymentCreate(BaseModel):
    party_id: str
    payment_type: str  # "received" or "made"
    amount: float
    payment_date: str
    payment_mode: str  # cash, bank_transfer, upi, cheque, card, other
    reference_number: Optional[str] = None  # Cheque no, UTR, etc.
    invoice_id: Optional[str] = None  # Optional link to specific invoice
    firm_id: Optional[str] = None
    bank_name: Optional[str] = None
    notes: Optional[str] = None

class PaymentResponse(BaseModel):
    id: str
    payment_number: str
    party_id: str
    party_name: str
    payment_type: str
    amount: float
    payment_date: str
    payment_mode: str
    reference_number: Optional[str] = None
    invoice_id: Optional[str] = None
    invoice_number: Optional[str] = None
    firm_id: Optional[str] = None
    firm_name: Optional[str] = None
    bank_name: Optional[str] = None
    notes: Optional[str] = None
    created_by: str
    created_by_name: str
    created_at: str


async def get_next_payment_number(payment_type: str, firm_id: Optional[str] = None) -> str:
    """Generate payment number: REC/2526/00001 or PAY/2526/00001.

    Atomic per (firm_id, FY, type) so REC/PAY numbers cannot collide across
    concurrent receipts. firm_id is optional for legacy callers but should be
    passed by all firm-scoped writes.
    """
    prefix = "REC" if payment_type == "received" else "PAY"
    fy = get_financial_year()
    full_prefix = f"{prefix}/{fy}/"
    counter_key = f"payment:{prefix}:{firm_id or 'global'}:{fy}"
    res = await db.counters.find_one_and_update(
        {"_id": counter_key},
        {"$inc": {"seq": 1}},
        upsert=True,
        return_document=True,
    )
    next_num = int((res or {}).get("seq", 1))
    return f"{full_prefix}{str(next_num).zfill(5)}"


