class ExpensePaymentRequest(BaseModel):
    amount: Optional[float] = None              # Defaults to net_payable (full pay)
    payment_date: Optional[str] = None          # YYYY-MM-DD; defaults to today
    payment_mode: str = "bank_transfer"         # cash / bank_transfer / upi / cheque / card / other
    reference_number: Optional[str] = None      # UTR, cheque no, etc.
    bank_name: Optional[str] = None
    notes: Optional[str] = None


@api_router.post("/expenses/{expense_id}/pay")
async def pay_expense(
    expense_id: str,
    payload: ExpensePaymentRequest,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Record a payment against an expense and flip its payment_status.

    Closes the gap where /payments wouldn't accept invoice_id pointing at an
    expense — the linkage happens here. Idempotent across partial payments:
    each call adds an `amount` to `paid_amount`; status becomes `partial` if
    short of net_payable, `paid` when met or exceeded.
    """
    expense = await db.expenses.find_one({"id": expense_id})
    if not expense:
        raise HTTPException(status_code=404, detail="Expense not found")
    assert_firm_access(user, expense.get("firm_id"))

    net_payable = float(expense.get("net_payable") or expense.get("gross_amount") or 0)
    already_paid = float(expense.get("paid_amount") or 0)
    outstanding = net_payable - already_paid
    if outstanding <= 0:
        raise HTTPException(status_code=400, detail=f"Expense already paid (paid={already_paid}, net_payable={net_payable})")

    amount = float(payload.amount) if payload.amount is not None else outstanding
    if amount <= 0:
        raise HTTPException(status_code=400, detail="Payment amount must be positive")
    if amount > outstanding + 0.01:
        raise HTTPException(
            status_code=400,
            detail=f"Payment {amount} exceeds outstanding {outstanding}. Use a partial value or split into multiple payments.",
        )

    party_id = expense.get("party_id")
    if not party_id:
        raise HTTPException(status_code=400, detail="Expense has no party_id — cannot create payment")

    pay_date = payload.payment_date or datetime.now(timezone.utc).date().isoformat()
    payment_number = await get_next_payment_number("made", firm_id=expense.get("firm_id"))
    now = datetime.now(timezone.utc).isoformat()
    payment_id = str(uuid.uuid4())

    payment_doc = {
        "id": payment_id,
        "payment_number": payment_number,
        "party_id": party_id,
        "party_name": expense.get("party_name"),
        "payment_type": "made",
        "amount": round(amount, 2),
        "payment_date": pay_date,
        "payment_mode": payload.payment_mode,
        "reference_number": payload.reference_number,
        "bank_name": payload.bank_name,
        "firm_id": expense.get("firm_id"),
        "firm_name": expense.get("firm_name"),
        "expense_id": expense_id,                 # back-link so /expenses/{id} can list its payments
        "expense_number": expense.get("expense_number"),
        "notes": payload.notes or f"Payment against {expense.get('expense_number')}",
        "created_by": user["id"],
        "created_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip() or user.get("email"),
        "created_at": now,
    }
    await db.payments.insert_one(payment_doc)

    # Mirror the payment in the party ledger (debit reduces the party's payable).
    try:
        await create_party_ledger_entry_atomic(
            party_id=party_id,
            party_name=expense.get("party_name"),
            entry_type="payment_made",
            debit=round(amount, 2),
            credit=0,
            narration=f"Payment for {expense.get('expense_number')} ({payload.payment_mode})",
            reference_type="expense_payment",
            reference_id=payment_id,
            firm_id=expense.get("firm_id"),
            user_id=user["id"],
            user_name=f"{user.get('first_name','')} {user.get('last_name','')}".strip() or user.get("email"),
            entry_number=payment_number,
            opening_balance=0,
        )
    except Exception as e:
        # Don't fail the payment write on a ledger hiccup — but make it visible.
        logger.warning(f"party_ledger entry failed for expense payment {payment_id}: {e}")

    # Flip expense status atomically based on the new paid_amount total.
    new_paid_total = round(already_paid + amount, 2)
    new_status = "paid" if new_paid_total + 0.01 >= net_payable else "partial"
    await db.expenses.update_one(
        {"id": expense_id},
        {"$set": {
            "paid_amount": new_paid_total,
            "paid_date": pay_date if new_status == "paid" else expense.get("paid_date"),
            "payment_status": new_status,
            "payment_reference": payment_number,
            "updated_at": now,
        }},
    )

    return {
        "success": True,
        "payment_number": payment_number,
        "payment_id": payment_id,
        "expense_id": expense_id,
        "expense_number": expense.get("expense_number"),
        "amount": round(amount, 2),
        "paid_amount_total": new_paid_total,
        "net_payable": net_payable,
        "payment_status": new_status,
    }


# TDS Export
@api_router.get("/tds/export")
async def export_tds_entries(
    financial_year: Optional[str] = None,
    quarter: Optional[str] = None,
    status: Optional[str] = None,
    firm_id: Optional[str] = None,
    format: str = "csv",
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Export TDS entries as CSV or Excel"""
    import pandas as pd
    
    fy = financial_year or get_financial_year()
    query = {"financial_year": fy, **firm_scope_filter(user, firm_id)}

    if quarter:
        query["quarter"] = quarter
    if status:
        query["status"] = status

    entries = await db.tds_entries.find(query, {"_id": 0}).sort("date", 1).to_list(5000)
    
    if not entries:
        raise HTTPException(status_code=404, detail="No TDS entries found for the selected criteria")
    
    # Create DataFrame
    df = pd.DataFrame(entries)
    
    # Select and rename columns for export
    export_cols = {
        "entry_number": "TDS Entry No",
        "date": "Date",
        "party_name": "Party Name",
        "party_pan": "PAN",
        "party_type": "Party Type",
        "reference_number": "Reference No",
        "gross_amount": "Gross Amount",
        "tds_section": "Section",
        "tds_rate": "TDS Rate %",
        "tds_amount": "TDS Amount",
        "net_payable": "Net Payable",
        "quarter": "Quarter",
        "status": "Status",
        "challan_number": "Challan No",
        "challan_date": "Challan Date",
        "firm_name": "Firm"
    }
    
    # Filter to only existing columns
    existing_cols = {k: v for k, v in export_cols.items() if k in df.columns}
    df = df[list(existing_cols.keys())].rename(columns=existing_cols)
    
    if format == "excel":
        output = BytesIO()
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name='TDS Entries', index=False)
        output.seek(0)
        
        filename = f"TDS_Entries_{fy}_{quarter or 'All'}_{datetime.now().strftime('%Y%m%d')}.xlsx"
        return StreamingResponse(
            output,
            media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            headers={"Content-Disposition": f"attachment; filename={filename}"}
        )
    else:
        output = BytesIO()
        df.to_csv(output, index=False)
        output.seek(0)
        
        filename = f"TDS_Entries_{fy}_{quarter or 'All'}_{datetime.now().strftime('%Y%m%d')}.csv"
        return StreamingResponse(
            output,
            media_type="text/csv",
            headers={"Content-Disposition": f"attachment; filename={filename}"}
        )


# Update Party model to include TDS fields
@api_router.patch("/parties/{party_id}/tds-config")
async def update_party_tds_config(
    party_id: str,
    tds_applicable: bool,
    tds_section: Optional[str] = None,
    tds_party_type: Optional[str] = None,
    pan_number: Optional[str] = None,
    tds_exemption: Optional[bool] = None,
    tds_exemption_certificate: Optional[str] = None,
    tds_exemption_valid_till: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update TDS configuration for a party"""
    party = await db.parties.find_one({"id": party_id})
    if not party:
        raise HTTPException(status_code=404, detail="Party not found")
    
    # Validate TDS party type
    if tds_party_type and tds_party_type not in TDS_PARTY_TYPES:
        raise HTTPException(status_code=400, detail=f"Invalid TDS party type. Must be one of: {TDS_PARTY_TYPES}")
    
    # Validate TDS section exists
    if tds_section:
        section = await db.tds_sections.find_one({"section": tds_section.upper(), "is_active": True})
        if not section:
            raise HTTPException(status_code=400, detail=f"TDS section {tds_section} not found or inactive")
    
    update_data = {
        "tds_applicable": tds_applicable,
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    if tds_section is not None:
        update_data["tds_section"] = tds_section.upper() if tds_section else None
    if tds_party_type is not None:
        update_data["tds_party_type"] = tds_party_type
    if pan_number is not None:
        update_data["pan_number"] = pan_number.upper() if pan_number else None
    if tds_exemption is not None:
        update_data["tds_exemption"] = tds_exemption
    if tds_exemption_certificate is not None:
        update_data["tds_exemption_certificate"] = tds_exemption_certificate
    if tds_exemption_valid_till is not None:
        update_data["tds_exemption_valid_till"] = tds_exemption_valid_till
    
    await db.parties.update_one({"id": party_id}, {"$set": update_data})
    
    updated = await db.parties.find_one({"id": party_id}, {"_id": 0})
    return updated


# ==================== GST / HSN DASHBOARD MODULE ====================

# Company state for GST split (configurable via firm settings)
DEFAULT_COMPANY_STATE = "Delhi"

def get_company_state(firm: dict = None) -> str:
    """Get company state from firm settings or use default"""
    if firm and firm.get("state"):
        return firm.get("state")
    return DEFAULT_COMPANY_STATE

def calculate_gst_split(taxable_amount: float, gst_rate: float, customer_state: str, company_state: str) -> dict:
    """Calculate GST split based on inter-state or intra-state"""
    total_gst = round(taxable_amount * gst_rate / 100, 2)
    
    if customer_state and company_state and customer_state.lower() == company_state.lower():
        # Intra-state: CGST + SGST
        half_gst = round(total_gst / 2, 2)
        return {
            "cgst": half_gst,
            "sgst": half_gst,
            "igst": 0,
            "total_gst": total_gst
        }
    else:
        # Inter-state: IGST
        return {
            "cgst": 0,
            "sgst": 0,
            "igst": total_gst,
            "total_gst": total_gst
        }


@api_router.get("/gst/hsn-summary")
async def get_hsn_summary(
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    firm_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get HSN-wise summary of sales and purchases with GST breakdown"""
    
    # Default to current month if no dates provided
    if not from_date:
        from_date = datetime.now(timezone.utc).replace(day=1).strftime("%Y-%m-%d")
    if not to_date:
        to_date = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    
    # Get company state for GST split
    firm = await db.firms.find_one({}, {"_id": 0}) if not firm_id else await db.firms.find_one({"id": firm_id}, {"_id": 0})
    company_state = get_company_state(firm)
    
    # Aggregate sales data from SALES INVOICES (primary source for GST)
    invoice_pipeline = [
        {
            "$match": {
                "invoice_date": {"$gte": from_date, "$lte": to_date},
                "status": "final"
            }
        },
        {"$unwind": {"path": "$items", "preserveNullAndEmptyArrays": False}},
        {
            "$lookup": {
                "from": "master_skus",
                "localField": "items.master_sku_id",
                "foreignField": "id",
                "as": "sku_info"
            }
        },
        {"$unwind": {"path": "$sku_info", "preserveNullAndEmptyArrays": True}},
        {
            "$group": {
                "_id": {
                    "hsn_code": {"$ifNull": ["$items.hsn_code", "$sku_info.hsn_code"]},
                    "product_name": {"$ifNull": ["$items.description", "$sku_info.name"]}
                },
                "quantity_sold": {"$sum": {"$ifNull": ["$items.quantity", 1]}},
                "sales_taxable": {"$sum": {"$ifNull": ["$items.taxable_value", "$items.amount"]}},
                "documents": {"$push": {
                    "customer_state": "$customer_state",
                    "gst_rate": {"$ifNull": ["$items.gst_rate", "$sku_info.gst_rate", 18]},
                    "taxable": {"$ifNull": ["$items.taxable_value", "$items.amount"]}
                }}
            }
        }
    ]
    
    if firm_id:
        invoice_pipeline[0]["$match"]["firm_id"] = firm_id
    
    sales_data = await db.sales_invoices.aggregate(invoice_pipeline).to_list(1000)
    
    # Also aggregate from dispatches for orders without invoices
    dispatch_pipeline = [
        {
            "$match": {
                "created_at": {"$gte": from_date, "$lte": to_date + "T23:59:59"},
                "status": {"$in": ["dispatched", "delivered"]},
                "sales_invoice_id": {"$exists": False}  # Only dispatches without invoices
            }
        },
        {
            "$lookup": {
                "from": "master_skus",
                "localField": "master_sku_id",
                "foreignField": "id",
                "as": "sku_info"
            }
        },
        {"$unwind": {"path": "$sku_info", "preserveNullAndEmptyArrays": True}},
        {
            "$group": {
                "_id": {
                    "hsn_code": {"$ifNull": ["$sku_info.hsn_code", ""]},
                    "product_name": {"$ifNull": ["$sku_info.name", "$master_sku_name"]}
                },
                "quantity_sold": {"$sum": {"$ifNull": ["$quantity", 1]}},
                "sales_taxable": {"$sum": {"$ifNull": ["$invoice_value", "$order_total", 0]}},
                "documents": {"$push": {
                    "customer_state": "$state",
                    "gst_rate": {"$ifNull": ["$sku_info.gst_rate", 18]},
                    "taxable": {"$ifNull": ["$invoice_value", "$order_total", 0]}
                }}
            }
        }
    ]
    
    if firm_id:
        dispatch_pipeline[0]["$match"]["firm_id"] = firm_id
    
    dispatch_data = await db.dispatches.aggregate(dispatch_pipeline).to_list(1000)
    
    # Merge dispatch data into sales_data
    for d in dispatch_data:
        sales_data.append(d)
    
    # Helper to normalize HSN code (remove .0 from float conversions)
    def normalize_hsn(hsn):
        if hsn is None:
            return ""
        hsn_str = str(hsn)
        # Remove .0 suffix from float conversion
        if hsn_str.endswith('.0'):
            hsn_str = hsn_str[:-2]
        return hsn_str.strip()
    
    # Process sales data with GST split
    hsn_summary = []
    for sale in sales_data:
        hsn_code = normalize_hsn(sale["_id"].get("hsn_code"))
        product_name = sale["_id"].get("product_name") or ""
        
        total_cgst = 0
        total_sgst = 0
        total_igst = 0
        
        for doc in sale.get("documents", []):
            customer_state = doc.get("customer_state") or ""
            gst_rate = doc.get("gst_rate") or 18  # Default 18%
            taxable = doc.get("taxable") or 0
            
            gst_split = calculate_gst_split(taxable, gst_rate, customer_state, company_state)
            total_cgst += gst_split["cgst"]
            total_sgst += gst_split["sgst"]
            total_igst += gst_split["igst"]
        
        hsn_summary.append({
            "hsn_code": hsn_code,
            "product_name": product_name,
            "quantity_sold": sale.get("quantity_sold", 0),
            "sales_taxable": round(sale.get("sales_taxable", 0), 2),
            "sales_cgst": round(total_cgst, 2),
            "sales_sgst": round(total_sgst, 2),
            "sales_igst": round(total_igst, 2),
            "purchase_taxable": 0,
            "purchase_qty": 0
        })
    
    # Add purchase data from inventory_ledger (purchase entries)
    purchase_pipeline = [
        {
            "$match": {
                "entry_type": "purchase",
                "created_at": {"$gte": from_date, "$lte": to_date + "T23:59:59"}
            }
        },
        {
            "$lookup": {
                "from": "master_skus",
                "localField": "item_id",
                "foreignField": "id",
                "as": "sku_info"
            }
        },
        {"$unwind": {"path": "$sku_info", "preserveNullAndEmptyArrays": True}},
        {
            "$group": {
                "_id": {
                    "hsn_code": "$sku_info.hsn_code",
                    "product_name": {"$ifNull": ["$item_name", "$sku_info.name"]}
                },
                "purchase_qty": {"$sum": "$quantity"},
                "purchase_taxable": {"$sum": {"$multiply": ["$quantity", {"$ifNull": ["$unit_price", 0]}]}}
            }
        }
    ]
    
    purchase_data = await db.inventory_ledger.aggregate(purchase_pipeline).to_list(1000)
    
    # Merge purchase data into hsn_summary (normalize HSN codes)
    purchase_map = {}
    for p in purchase_data:
        hsn = normalize_hsn(p["_id"].get("hsn_code"))
        if hsn:
            purchase_map[hsn] = p
    
    for hsn in hsn_summary:
        if hsn["hsn_code"] in purchase_map:
            p = purchase_map[hsn["hsn_code"]]
            hsn["purchase_taxable"] = round(p.get("purchase_taxable", 0), 2)
            hsn["purchase_qty"] = p.get("purchase_qty", 0)
    
    # Add purchase-only HSNs
    for hsn_code, p in purchase_map.items():
        if not any(h["hsn_code"] == hsn_code for h in hsn_summary):
            hsn_summary.append({
                "hsn_code": hsn_code,
                "product_name": p["_id"].get("product_name") or "",
                "quantity_sold": 0,
                "sales_taxable": 0,
                "sales_cgst": 0,
                "sales_sgst": 0,
                "sales_igst": 0,
                "purchase_taxable": round(p.get("purchase_taxable", 0), 2),
                "purchase_qty": p.get("purchase_qty", 0)
            })
    
    # Sort by sales value
    hsn_summary.sort(key=lambda x: x["sales_taxable"], reverse=True)
    
    # State-wise summary
    state_pipeline = [
        {
            "$match": {
                "created_at": {"$gte": from_date, "$lte": to_date + "T23:59:59"},
                "status": {"$in": ["dispatched", "delivered", "invoiced"]}
            }
        },
        {"$unwind": "$items"},
        {
            "$group": {
                "_id": "$customer_state",
                "taxable_value": {"$sum": {"$multiply": ["$items.quantity", "$items.unit_price"]}},
                "invoice_count": {"$addToSet": "$id"}
            }
        },
        {"$project": {
            "state": "$_id",
            "taxable_value": 1,
            "invoice_count": {"$size": "$invoice_count"}
        }},
        {"$sort": {"taxable_value": -1}}
    ]
    
    state_data = await db.dispatches.aggregate(state_pipeline).to_list(100)
    
    # Calculate GST for state-wise data
    state_wise = []
    for state in state_data:
        state_name = state.get("state") or "Not Specified"
        taxable = state.get("taxable_value", 0)
        
        # Assume average 18% GST
        gst_split = calculate_gst_split(taxable, 18, state_name, company_state)
        
        state_wise.append({
            "state": state_name,
            "taxable_value": round(taxable, 2),
            "cgst": gst_split["cgst"],
            "sgst": gst_split["sgst"],
            "igst": gst_split["igst"],
            "invoice_count": state.get("invoice_count", 0)
        })
    
    # Purchase vs Sales comparison
    purchase_vs_sales = []
    for hsn in hsn_summary:
        if hsn["hsn_code"]:
            purchase_vs_sales.append({
                "hsn_code": hsn["hsn_code"],
                "product_name": hsn["product_name"],
                "purchase_value": hsn["purchase_taxable"],
                "purchase_qty": hsn["purchase_qty"],
                "sales_value": hsn["sales_taxable"],
                "sales_qty": hsn["quantity_sold"]
            })
    
    return {
        "hsn_summary": hsn_summary,
        "state_wise": state_wise,
        "purchase_vs_sales": purchase_vs_sales,
        "date_range": {"from": from_date, "to": to_date},
        "company_state": company_state
    }


@api_router.get("/gst/hsn-drilldown/{hsn_code}")
async def get_hsn_drilldown(
    hsn_code: str,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get state-wise breakdown for a specific HSN code"""
    
    if not from_date:
        from_date = datetime.now(timezone.utc).replace(day=1).strftime("%Y-%m-%d")
    if not to_date:
        to_date = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    
    firm = await db.firms.find_one({}, {"_id": 0})
    company_state = get_company_state(firm)
    
    pipeline = [
        {
            "$match": {
                "created_at": {"$gte": from_date, "$lte": to_date + "T23:59:59"},
                "status": {"$in": ["dispatched", "delivered", "invoiced"]}
            }
        },
        {"$unwind": "$items"},
        {
            "$lookup": {
                "from": "master_skus",
                "localField": "items.master_sku_id",
                "foreignField": "id",
                "as": "sku_info"
            }
        },
        {"$unwind": {"path": "$sku_info", "preserveNullAndEmptyArrays": True}},
        {
            "$match": {
                "$or": [
                    {"items.hsn_code": hsn_code},
                    {"sku_info.hsn_code": hsn_code}
                ]
            }
        },
        {
            "$group": {
                "_id": "$customer_state",
                "quantity": {"$sum": "$items.quantity"},
                "taxable_value": {"$sum": {"$multiply": ["$items.quantity", "$items.unit_price"]}},
                "invoice_count": {"$addToSet": "$id"},
                "gst_rate": {"$first": {"$ifNull": ["$items.gst_rate", "$sku_info.gst_rate"]}}
            }
        },
        {"$sort": {"taxable_value": -1}}
    ]
    
    results = await db.dispatches.aggregate(pipeline).to_list(100)
    
    states = []
    for r in results:
        state_name = r["_id"] or "Not Specified"
        taxable = r.get("taxable_value", 0)
        gst_rate = r.get("gst_rate") or 18
        
        gst_split = calculate_gst_split(taxable, gst_rate, state_name, company_state)
        
        states.append({
            "state": state_name,
            "quantity": r.get("quantity", 0),
            "taxable_value": round(taxable, 2),
            "cgst": gst_split["cgst"],
            "sgst": gst_split["sgst"],
            "igst": gst_split["igst"],
            "invoice_count": len(r.get("invoice_count", []))
        })
    
    return {
        "hsn_code": hsn_code,
        "states": states
    }


@api_router.get("/gst/hsn-codes")
async def get_hsn_codes(
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get distinct HSN codes from Master SKUs for dropdown selection"""
    
    # Helper to normalize HSN code
    def normalize_hsn(hsn):
        if hsn is None:
            return None
        hsn_str = str(hsn)
        # Remove .0 suffix from float conversion
        if hsn_str.endswith('.0'):
            hsn_str = hsn_str[:-2]
        return hsn_str.strip()
    
    # Get all Master SKUs with HSN codes
    skus = await db.master_skus.find(
        {"hsn_code": {"$exists": True, "$ne": None, "$ne": ""}},
        {"_id": 0, "hsn_code": 1, "name": 1, "gst_rate": 1}
    ).to_list(500)
    
    # Build unique HSN code list with product names
    hsn_map = {}
    for sku in skus:
        hsn = normalize_hsn(sku.get("hsn_code"))
        if hsn and len(hsn) >= 4:  # Valid HSN codes are at least 4 digits
            if hsn not in hsn_map:
                hsn_map[hsn] = {
                    "code": hsn,
                    "products": [],
                    "gst_rate": sku.get("gst_rate")
                }
            hsn_map[hsn]["products"].append(sku.get("name", ""))
    
    # Convert to list and sort
    result = sorted(hsn_map.values(), key=lambda x: x["code"])
    
    return result


@api_router.get("/gst/missing-data-alerts")
async def get_missing_data_alerts(
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get alerts for records with missing HSN, GST rate, or state"""
    
    alerts = []
    
    # Check dispatches for missing HSN/state
    dispatch_alerts = await db.dispatches.find(
        {
            "$or": [
                {"customer_state": {"$in": [None, ""]}},
                {"items.hsn_code": {"$in": [None, ""]}}
            ],
            "status": {"$in": ["dispatched", "delivered", "invoiced"]}
        },
        {"_id": 0, "id": 1, "dispatch_number": 1, "customer_name": 1, "customer_state": 1, "created_at": 1, "items": 1}
    ).sort("created_at", -1).limit(50).to_list(50)
    
    for d in dispatch_alerts:
        has_missing_hsn = any(not item.get("hsn_code") for item in d.get("items", []))
        missing_state = not d.get("customer_state")
        
        if has_missing_hsn:
            alerts.append({
                "record_type": "Dispatch",
                "record_id": d["id"],
                "record_number": d.get("dispatch_number"),
                "message": "Missing HSN code for one or more items",
                "severity": "high",
                "party_name": d.get("customer_name"),
                "date": d.get("created_at")
            })
        
        if missing_state:
            alerts.append({
                "record_type": "Dispatch",
                "record_id": d["id"],
                "record_number": d.get("dispatch_number"),
                "message": "Missing customer state (affects CGST/SGST vs IGST)",
                "severity": "high",
                "party_name": d.get("customer_name"),
                "date": d.get("created_at")
            })
    
    # Check master_skus for missing HSN/GST rate
    sku_alerts = await db.master_skus.find(
        {
            "$or": [
                {"hsn_code": {"$in": [None, ""]}},
                {"gst_rate": {"$in": [None, 0]}}
            ],
            "is_active": True
        },
        {"_id": 0, "id": 1, "sku_code": 1, "name": 1, "hsn_code": 1, "gst_rate": 1}
    ).limit(50).to_list(50)
    
    for sku in sku_alerts:
        if not sku.get("hsn_code"):
            alerts.append({
                "record_type": "Master SKU",
                "record_id": sku["id"],
                "record_number": sku.get("sku_code"),
                "message": f"Missing HSN code for {sku.get('name')}",
                "severity": "medium",
                "party_name": None,
                "date": None
            })
        
        if not sku.get("gst_rate"):
            alerts.append({
                "record_type": "Master SKU",
                "record_id": sku["id"],
                "record_number": sku.get("sku_code"),
                "message": f"Missing GST rate for {sku.get('name')}",
                "severity": "medium",
                "party_name": None,
                "date": None
            })
    
    # Check parties for missing state
    party_alerts = await db.parties.find(
        {"state": {"$in": [None, ""]}, "party_types": "customer"},
        {"_id": 0, "id": 1, "name": 1}
    ).limit(30).to_list(30)
    
    for p in party_alerts:
        alerts.append({
            "record_type": "Party",
            "record_id": p["id"],
            "record_number": p.get("name"),
            "message": "Missing state for customer party",
            "severity": "low",
            "party_name": p.get("name"),
            "date": None
        })
    
    return alerts


class GSTCorrectionRequest(BaseModel):
    record_type: str
    record_id: str
    corrections: dict
    reason: str


@api_router.post("/gst/correct-record")
async def correct_gst_record(
    request: GSTCorrectionRequest,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Apply corrections to a record and log the change"""
    
    record_type = request.record_type
    record_id = request.record_id
    corrections = request.corrections
    reason = request.reason
    
    # Validate record type
    collection_map = {
        "Dispatch": "dispatches",
        "Master SKU": "master_skus",
        "Party": "parties",
        "Invoice": "sales_invoices"
    }
    
    if record_type not in collection_map:
        raise HTTPException(status_code=400, detail=f"Invalid record type: {record_type}")
    
    collection = db[collection_map[record_type]]
    
    # Get the record
    record = await collection.find_one({"id": record_id})
    if not record:
        raise HTTPException(status_code=404, detail="Record not found")
    
    # Prepare update
    update_data = {"updated_at": datetime.now(timezone.utc).isoformat()}
    
    # Apply corrections based on record type
    if record_type == "Master SKU":
        if corrections.get("hsn_code"):
            update_data["hsn_code"] = corrections["hsn_code"]
        if corrections.get("gst_rate") is not None:
            update_data["gst_rate"] = corrections["gst_rate"]
    
    elif record_type == "Dispatch":
        if corrections.get("state"):
            update_data["customer_state"] = corrections["state"]
        # For HSN, we'd need to update items array
        if corrections.get("hsn_code"):
            # Update all items without HSN
            items = record.get("items", [])
            for item in items:
                if not item.get("hsn_code"):
                    item["hsn_code"] = corrections["hsn_code"]
            update_data["items"] = items
    
    elif record_type == "Party":
        if corrections.get("state"):
            update_data["state"] = corrections["state"]
    
    # Apply update
    await collection.update_one({"id": record_id}, {"$set": update_data})
    
    # Log the correction
    correction_log = {
        "id": str(uuid.uuid4()),
        "record_type": record_type,
        "record_id": record_id,
        "corrections": corrections,
        "reason": reason,
        "corrected_by": user["id"],
        "corrected_by_name": user.get("name", user.get("email")),
        "corrected_at": datetime.now(timezone.utc).isoformat(),
        "old_values": {
            k: record.get(k) for k in corrections.keys() if k in record
        }
    }
    
    await db.gst_corrections_log.insert_one(correction_log)
    
    return {"success": True, "message": "Correction applied and logged"}


@api_router.get("/gst/export/{export_type}")
async def export_gst_data(
    export_type: str,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Export GST data as Excel"""
    import pandas as pd
    
    if not from_date:
        from_date = datetime.now(timezone.utc).replace(day=1).strftime("%Y-%m-%d")
    if not to_date:
        to_date = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    
    # Get summary data
    summary = await get_hsn_summary(from_date, to_date, None, user)
    
    output = BytesIO()
    
    if export_type == "hsn-summary":
        df = pd.DataFrame(summary["hsn_summary"])
        
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name='HSN Summary', index=False)
            
            # Add state-wise sheet
            state_df = pd.DataFrame(summary["state_wise"])
            state_df.to_excel(writer, sheet_name='State-wise', index=False)
    
    elif export_type == "detailed":
        # Get detailed line-level data
        pipeline = [
            {
                "$match": {
                    "created_at": {"$gte": from_date, "$lte": to_date + "T23:59:59"},
                    "status": {"$in": ["dispatched", "delivered", "invoiced"]}
                }
            },
            {"$unwind": "$items"},
            {
                "$lookup": {
                    "from": "master_skus",
                    "localField": "items.master_sku_id",
                    "foreignField": "id",
                    "as": "sku_info"
                }
            },
            {"$unwind": {"path": "$sku_info", "preserveNullAndEmptyArrays": True}},
            {
                "$project": {
                    "date": "$dispatch_date",
                    "invoice_no": "$dispatch_number",
                    "party": "$customer_name",
                    "state": "$customer_state",
                    "hsn": {"$ifNull": ["$items.hsn_code", "$sku_info.hsn_code"]},
                    "product": "$items.name",
                    "quantity": "$items.quantity",
                    "unit_price": "$items.unit_price",
                    "taxable_value": {"$multiply": ["$items.quantity", "$items.unit_price"]},
                    "gst_rate": {"$ifNull": ["$items.gst_rate", "$sku_info.gst_rate"]}
                }
            }
        ]
        
        data = await db.dispatches.aggregate(pipeline).to_list(10000)
        
        firm = await db.firms.find_one({}, {"_id": 0})
        company_state = get_company_state(firm)
        
        # Calculate GST columns
        for row in data:
            taxable = row.get("taxable_value", 0)
            gst_rate = row.get("gst_rate") or 18
            customer_state = row.get("state") or ""
            
            gst_split = calculate_gst_split(taxable, gst_rate, customer_state, company_state)
            row["cgst"] = gst_split["cgst"]
            row["sgst"] = gst_split["sgst"]
            row["igst"] = gst_split["igst"]
            row["total_gst"] = gst_split["total_gst"]
        
        df = pd.DataFrame(data)
        
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name='Detailed GST', index=False)
    
    else:
        raise HTTPException(status_code=400, detail="Invalid export type")
    
    output.seek(0)
    
    filename = f"GST_{export_type}_{from_date}_to_{to_date}.xlsx"
    return StreamingResponse(
        output,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename={filename}"}
    )


# ==================== E-COMMERCE RECONCILIATION MODULE ====================

# Order sources for dispatch
ORDER_SOURCES = ["amazon", "flipkart", "website", "walkin", "direct", "other"]

# Pydantic models for E-commerce Reconciliation
class PayoutStatementCreate(BaseModel):
    platform: str  # amazon, flipkart
    firm_id: str  # Required - which firm this statement belongs to
    statement_period_start: str
    statement_period_end: str
    filename: str


class PayoutTransactionRow(BaseModel):
    date: str
    transaction_type: str
    order_id: Optional[str] = None
    product_details: Optional[str] = None
    total_product_charges: float = 0
    promotional_rebates: float = 0
    platform_fees: float = 0
    other_adjustments: float = 0
    total_amount: float = 0


class FlipkartSheetSummary(BaseModel):
    """Summary of each Flipkart sheet parsed"""
    sheet_name: str
    total_rows: int
    total_amount: float
    parsed_successfully: bool


# Helper function to parse Flipkart multi-sheet Excel
async def parse_flipkart_excel(content: bytes, statement_id: str, firm_id: str, user: dict, db):
    """Parse Flipkart settlement Excel with multiple sheets"""
    import pandas as pd
    import io
    
    now = datetime.now(timezone.utc).isoformat()
    xls = pd.ExcelFile(io.BytesIO(content))
    
    sheet_summaries = []
    all_transactions = []
    order_summaries = {}
    non_order_charges = []
    tax_entries = []
    
    # Totals
    total_sales = 0
    total_marketplace_fees = 0
    total_ad_spend = 0
    total_service_charges = 0
    total_tcs = 0
    total_tds = 0
    total_gst_on_fees = 0
    total_non_order_adjustments = 0
    total_refunds = 0
    total_bank_settlement = 0  # Sum of Bank Settlement Value from Orders sheet
    matched_orders = 0
    unmatched_orders = 0
    
    def safe_float(val):
        if pd.isna(val) or val == '' or val == 'NA':
            return 0.0
        try:
            return float(str(val).replace(',', ''))
        except:
            return 0.0
    
    def safe_str(val):
        if pd.isna(val) or val is None:
            return None
        return str(val).strip()
    
    def parse_date(date_str):
        if pd.isna(date_str):
            return None
        try:
            for fmt in ['%Y-%m-%d', '%d/%m/%Y', '%d-%m-%Y', '%m/%d/%Y']:
                try:
                    return datetime.strptime(str(date_str), fmt).strftime('%Y-%m-%d')
                except:
                    continue
            return str(date_str)
        except:
            return None
    
    # Parse Orders sheet
    if 'Orders' in xls.sheet_names:
        try:
            # Flipkart Orders sheet has header in row 1 (0-indexed), skip row 0 which is grouped header
            df = pd.read_excel(xls, sheet_name='Orders', header=1)
            # Clean column names - handle special chars and newlines
            df.columns = df.columns.astype(str).str.strip().str.lower().str.replace('\n', ' ').str.replace(' ', '_').str.replace('(', '').str.replace(')', '').str.replace('%', 'pct').str.replace('.', '').str.replace('=_sum', '').str.replace('[', '').str.replace(']', '')
            
            # Drop rows where Order ID is empty (including the header row that might remain)
            df = df.dropna(subset=['order_id'] if 'order_id' in df.columns else df.columns[:1])
            
            sheet_total = 0
            for idx, row in df.iterrows():
                order_id = safe_str(row.get('order_id'))
                if not order_id or order_id.lower() == 'order_id' or order_id == 'None':
                    continue
                
                # Map columns with various naming conventions in Flipkart exports
                sale_amount = safe_float(row.get('sale_amount_rs', row.get('sale_amount')))
                marketplace_fee = safe_float(row.get('marketplace_fee_rs__v:ai', row.get('marketplace_fee_rs', row.get('marketplace_fee'))))
                taxes = safe_float(row.get('taxes_rs', row.get('taxes')))
                shipping_fee = safe_float(row.get('shipping_fee_rs', row.get('shipping_fee')))
                commission = safe_float(row.get('commission_rs', row.get('commission')))
                fixed_fee = safe_float(row.get('fixed_fee__rs', row.get('fixed_fee')))
                collection_fee = safe_float(row.get('collection_fee_rs', row.get('collection_fee')))
                tcs = safe_float(row.get('tcs_rs', row.get('tcs')))
                tds = safe_float(row.get('tds_rs', row.get('tds')))
                gst_on_mp_fees = safe_float(row.get('gst_on_mp_fees_rs', row.get('gst_on_mp_fees')))
                refund = safe_float(row.get('refund_rs', row.get('refund')))
                protection_fund = safe_float(row.get('protection_fund_rs', row.get('protection_fund')))
                offer_adjustments = safe_float(row.get('offer_adjustments_rs', row.get('offer_adjustment_rs__as+ao', row.get('offer_adjustments'))))
                # Bank Settlement Value is the final settlement amount
                total = safe_float(row.get('bank_settlement_value_rs__j:r', row.get('bank_settlement_value_rs', row.get('total_rs', row.get('total')))))
                # Get date
                payment_date = row.get('_payment_date', row.get('payment_date', row.get('order_date')))
                seller_sku = safe_str(row.get('seller_sku'))
                
                # Match with CRM
                crm_match = None
                crm_order_id = None
                if order_id:
                    crm_dispatch = await db.dispatches.find_one({
                        "firm_id": firm_id,
                        "$or": [
                            {"marketplace_order_id": order_id},
                            {"order_id": order_id},
                            {"external_order_id": order_id}
                        ]
                    }, {"_id": 0, "id": 1, "dispatch_number": 1})
                    
                    if crm_dispatch:
                        crm_match = "matched"
                        crm_order_id = crm_dispatch.get("id")
                        matched_orders += 1
                    else:
                        crm_match = "unmatched"
                        unmatched_orders += 1
                
                trans_record = {
                    "id": str(uuid.uuid4()),
                    "statement_id": statement_id,
                    "sheet_name": "Orders",
                    "row_index": idx,
                    "date": parse_date(payment_date),
                    "transaction_type": "order_settlement",
                    "transaction_category": "order_payment" if refund == 0 else "partial_refund",
                    "marketplace_order_id": order_id,
                    "order_item_id": safe_str(row.get('order_item_id')),
                    "product_details": seller_sku,
                    "total_product_charges": sale_amount,
                    "marketplace_fee": marketplace_fee,
                    "commission": commission,
                    "fixed_fee": fixed_fee,
                    "collection_fee": collection_fee,
                    "shipping_fee": shipping_fee,
                    "platform_fees": marketplace_fee,
                    "tcs": tcs,
                    "tds": tds,
                    "gst_on_fees": gst_on_mp_fees,
                    "refund_amount": refund,
                    "protection_fund": protection_fund,
                    "offer_adjustments": offer_adjustments,
                    "total_amount": total,
                    "crm_match_status": crm_match,
                    "crm_order_id": crm_order_id,
                    "created_at": now
                }
                all_transactions.append(trans_record)
                
                # Accumulate totals
                total_sales += sale_amount
                total_marketplace_fees += marketplace_fee
                total_tcs += tcs
                total_tds += tds
                total_gst_on_fees += gst_on_mp_fees
                total_refunds += refund
                total_bank_settlement += total  # Bank Settlement Value from each order
                sheet_total += total
                
                # Build order summary
                if order_id not in order_summaries:
                    order_summaries[order_id] = {
                        "marketplace_order_id": order_id,
                        "product_details": seller_sku,
                        "gross_sale": 0,
                        "platform_fees": 0,
                        "commission": 0,
                        "shipping_fee": 0,
                        "tcs": 0,
                        "tds": 0,
                        "gst_on_fees": 0,
                        "promotional_rebates": 0,
                        "other_adjustments": 0,
                        "refund_amount": 0,
                        "net_realized": 0,
                        "crm_match_status": crm_match,
                        "crm_order_id": crm_order_id,
                        "finance_status": "pending"
                    }
                
                order_summaries[order_id]["gross_sale"] += sale_amount
                order_summaries[order_id]["platform_fees"] += marketplace_fee
                order_summaries[order_id]["commission"] += commission
                order_summaries[order_id]["shipping_fee"] += shipping_fee
                order_summaries[order_id]["tcs"] += tcs
                order_summaries[order_id]["tds"] += tds
                order_summaries[order_id]["gst_on_fees"] += gst_on_mp_fees
                order_summaries[order_id]["refund_amount"] += refund
                order_summaries[order_id]["net_realized"] += total
                order_summaries[order_id]["finance_status"] = "refunded" if refund > 0 else "paid"
            
            sheet_summaries.append({
                "sheet_name": "Orders",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "Orders",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse MP Fee Rebate sheet
    if 'MP Fee Rebate' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='MP Fee Rebate', header=1)
            df.columns = df.columns.astype(str).str.strip().str.lower().str.replace('\n', ' ').str.replace(' ', '_').str.replace('(', '').str.replace(')', '').str.replace('.', '')
            df = df.dropna(how='all')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                order_id = safe_str(row.get('order_id'))
                settlement_value = safe_float(row.get('settlement_value_rs', row.get('settlement_value', row.get('rebate_amount'))))
                
                if settlement_value != 0:
                    non_order_charges.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "charge_type": "mp_fee_rebate",
                        "category": "rebate",
                        "order_id": order_id,
                        "sku": safe_str(row.get('sku_id', row.get('sku'))),
                        "date": parse_date(row.get('rebate_processing_date', row.get('payment_date', row.get('date')))),
                        "amount": settlement_value,
                        "description": "Marketplace Fee Rebate",
                        "created_at": now
                    })
                    sheet_total += settlement_value
                    total_non_order_adjustments += settlement_value
            
            sheet_summaries.append({
                "sheet_name": "MP Fee Rebate",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "MP Fee Rebate",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse Non_Order_SPF sheet (Protection Fund)
    if 'Non_Order_SPF' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='Non_Order_SPF', header=0)
            df.columns = df.columns.str.strip().str.lower().str.replace(' ', '_')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                settlement_value = safe_float(row.get('settlement_value'))
                
                if settlement_value != 0:
                    non_order_charges.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "charge_type": "protection_fund",
                        "category": "claim",
                        "claim_id": safe_str(row.get('claim_id')),
                        "sku": safe_str(row.get('sku')),
                        "date": parse_date(row.get('date')),
                        "amount": settlement_value,
                        "description": safe_str(row.get('protection_reason', 'Seller Protection Fund')),
                        "created_at": now
                    })
                    sheet_total += settlement_value
                    total_non_order_adjustments += settlement_value
            
            sheet_summaries.append({
                "sheet_name": "Non_Order_SPF",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "Non_Order_SPF",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse Storage_Recall sheet
    if 'Storage_Recall' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='Storage_Recall', header=0)
            df.columns = df.columns.str.strip().str.lower().str.replace(' ', '_')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                settlement_value = safe_float(row.get('settlement_value'))
                service_name = safe_str(row.get('service_name', 'Storage/Recall'))
                
                if settlement_value != 0:
                    non_order_charges.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "charge_type": "storage_recall",
                        "category": "service",
                        "service_name": service_name,
                        "sku": safe_str(row.get('sku')),
                        "date": parse_date(row.get('date')),
                        "amount": settlement_value,
                        "description": f"Storage/Recall: {service_name}",
                        "created_at": now
                    })
                    sheet_total += settlement_value
                    total_service_charges += settlement_value  # Keep sign
            
            sheet_summaries.append({
                "sheet_name": "Storage_Recall",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "Storage_Recall",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse Value Added Services sheet
    if 'Value Added Services' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='Value Added Services', header=0)
            df.columns = df.columns.str.strip().str.lower().str.replace(' ', '_')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                settlement_value = safe_float(row.get('settlement_value', row.get('amount')))
                
                if settlement_value != 0:
                    non_order_charges.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "charge_type": "value_added_service",
                        "category": "service",
                        "service_name": safe_str(row.get('service_name')),
                        "date": parse_date(row.get('date_of_purchase', row.get('date'))),
                        "amount": settlement_value,
                        "description": safe_str(row.get('service_details', 'Value Added Service')),
                        "created_at": now
                    })
                    sheet_total += settlement_value
                    total_service_charges += settlement_value  # Keep sign
            
            sheet_summaries.append({
                "sheet_name": "Value Added Services",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "Value Added Services",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse Google Ads Services sheet
    if 'Google Ads Services' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='Google Ads Services', header=0)
            df.columns = df.columns.str.strip().str.lower().str.replace(' ', '_')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                settlement_value = safe_float(row.get('settlement_value', row.get('amount')))
                
                if settlement_value != 0:
                    non_order_charges.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "charge_type": "google_ads",
                        "category": "ads",
                        "date": parse_date(row.get('date_of_purchase', row.get('date'))),
                        "amount": settlement_value,
                        "description": safe_str(row.get('service_details', 'Google Ads Service')),
                        "created_at": now
                    })
                    sheet_total += settlement_value
                    total_ad_spend += settlement_value  # Keep sign, negative values = deductions
            
            sheet_summaries.append({
                "sheet_name": "Google Ads Services",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "Google Ads Services",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse Ads sheet
    if 'Ads' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='Ads', header=1)
            df.columns = df.columns.astype(str).str.strip().str.lower().str.replace('\n', ' ').str.replace(' ', '_').str.replace('(', '').str.replace(')', '').str.replace('.', '').str.replace('=_sum', '').str.replace('/', '_')
            df = df.dropna(how='all')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                settlement_value = safe_float(row.get('settlement_value_rs_g:k', row.get('settlement_value_rs', row.get('settlement_value'))))
                trans_type = safe_str(row.get('type', 'ads'))
                
                if settlement_value != 0:
                    non_order_charges.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "charge_type": "ads",
                        "category": "ads",
                        "transaction_type": trans_type,
                        "campaign_id": safe_str(row.get('campaign___transaction_id', row.get('campaign_id'))),
                        "date": parse_date(row.get('payment_date', row.get('date'))),
                        "wallet_redeem": safe_float(row.get('wallet_redeem_rs')),
                        "wallet_topup": safe_float(row.get('wallet_topup_rs')),
                        "wallet_refund": safe_float(row.get('wallet_refund_rs')),
                        "gst_on_ads": safe_float(row.get('gst_on_ads_fees_rs')),
                        "amount": settlement_value,
                        "description": f"Ads: {trans_type}",
                        "created_at": now
                    })
                    sheet_total += settlement_value
                    total_ad_spend += settlement_value  # Keep sign, negative values = deductions
            
            sheet_summaries.append({
                "sheet_name": "Ads",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "Ads",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse TCS_Recovery sheet
    if 'TCS_Recovery' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='TCS_Recovery', header=1)
            df.columns = df.columns.astype(str).str.strip().str.lower().str.replace('\n', ' ').str.replace(' ', '_').str.replace('(', '').str.replace(')', '').str.replace('.', '')
            df = df.dropna(how='all')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                settlement_value = safe_float(row.get('settlement_value_rs', row.get('settlement_value')))
                
                if settlement_value != 0:
                    tax_entries.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "tax_type": "tcs_recovery",
                        "transaction_id": safe_str(row.get('transaction_id')),
                        "date": parse_date(row.get('transaction_date', row.get('date'))),
                        "recovery_month": safe_str(row.get('recovery_month')),
                        "amount": settlement_value,
                        "created_at": now
                    })
                    sheet_total += settlement_value
                    total_tcs += abs(settlement_value)
            
            sheet_summaries.append({
                "sheet_name": "TCS_Recovery",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "TCS_Recovery",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse TDS sheet
    if 'TDS' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='TDS', header=1)
            df.columns = df.columns.astype(str).str.strip().str.lower().str.replace('\n', ' ').str.replace(' ', '_').str.replace('(', '').str.replace(')', '').str.replace('.', '')
            df = df.dropna(how='all')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                settlement_value = safe_float(row.get('settlement_value_rs', row.get('settlement_value')))
                
                if settlement_value != 0:
                    tax_entries.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "tax_type": "tds",
                        "claim_id": safe_str(row.get('id')),
                        "date": parse_date(row.get('payment_date', row.get('claim_date'))),
                        "amount": settlement_value,
                        "created_at": now
                    })
                    sheet_total += settlement_value
                    total_tds += abs(settlement_value)
            
            sheet_summaries.append({
                "sheet_name": "TDS",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "TDS",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Parse GST_Details sheet
    if 'GST_Details' in xls.sheet_names:
        try:
            df = pd.read_excel(xls, sheet_name='GST_Details', header=1)
            df.columns = df.columns.astype(str).str.strip().str.lower().str.replace('\n', ' ').str.replace(' ', '_').str.replace('(', '').str.replace(')', '').str.replace('.', '').str.replace('/', '_')
            df = df.dropna(how='all')
            
            sheet_total = 0
            for idx, row in df.iterrows():
                cgst = safe_float(row.get('cgst_amount', row.get('cgst_amount_rs')))
                sgst = safe_float(row.get('sgst_utgst_amount', row.get('sgst_amount')))
                igst = safe_float(row.get('igst_amount', row.get('igst_amount_rs')))
                total_gst = cgst + sgst + igst
                
                if total_gst != 0:
                    tax_entries.append({
                        "id": str(uuid.uuid4()),
                        "statement_id": statement_id,
                        "tax_type": "gst_on_fees",
                        "fee_name": safe_str(row.get('fee_name')),
                        "fee_amount": safe_float(row.get('fee_amount_rs')),
                        "order_item_id": safe_str(row.get('order_item_id__listing_id__campaign_id_transaction_id__service_order_id', row.get('order_item_id'))),
                        "cgst_rate": safe_float(row.get('cgst_rate', row.get('cgst_rate_pct'))),
                        "sgst_rate": safe_float(row.get('sgst_utgst_rate', row.get('sgst_rate'))),
                        "igst_rate": safe_float(row.get('igst_rate', row.get('igst_rate_pct'))),
                        "cgst_amount": cgst,
                        "sgst_amount": sgst,
                        "igst_amount": igst,
                        "total_gst": total_gst,
                        "amount": total_gst,
                        "created_at": now
                    })
                    sheet_total += total_gst
                    total_gst_on_fees += total_gst
            
            sheet_summaries.append({
                "sheet_name": "GST_Details",
                "total_rows": len(df),
                "total_amount": sheet_total,
                "parsed_successfully": True
            })
        except Exception as e:
            sheet_summaries.append({
                "sheet_name": "GST_Details",
                "total_rows": 0,
                "total_amount": 0,
                "parsed_successfully": False,
                "error": str(e)
            })
    
    # Get date range from transactions
    all_dates = [t.get('date') for t in all_transactions if t.get('date')]
    statement_start = min(all_dates) if all_dates else datetime.now(timezone.utc).strftime('%Y-%m-%d')
    statement_end = max(all_dates) if all_dates else statement_start
    
    # Calculate net payout (Bank Settlement from Orders + Service fees adjustments)
    # The total_bank_settlement is the sum of Bank Settlement Value from Orders sheet
    # The total_ad_spend is typically negative (deduction), so we add it
    # Same for total_service_charges
    net_payout = total_bank_settlement + total_ad_spend + total_service_charges + total_non_order_adjustments
    
    # Debug logging
    import logging
    logging.info(f"Flipkart payout: orders_settlement={total_bank_settlement}, ads={total_ad_spend}, services={total_service_charges}, net={net_payout}")
    
    return {
        "transactions": all_transactions,
        "order_summaries": order_summaries,
        "non_order_charges": non_order_charges,
        "tax_entries": tax_entries,
        "sheet_summaries": sheet_summaries,
        "statement_period_start": statement_start,
        "statement_period_end": statement_end,
        "summary": {
            "total_transactions": len(all_transactions),
            "total_sales": round(total_sales, 2),
            "total_marketplace_fees": round(abs(total_marketplace_fees), 2),
            "total_ad_spend": round(abs(total_ad_spend), 2),
            "total_service_charges": round(abs(total_service_charges), 2),
            "total_tcs": round(abs(total_tcs), 2),
            "total_tds": round(abs(total_tds), 2),
            "total_gst_on_fees": round(abs(total_gst_on_fees), 2),
            "total_refunds": round(abs(total_refunds), 2),
            "total_non_order_adjustments": round(total_non_order_adjustments, 2),
            "orders_bank_settlement": round(total_bank_settlement, 2),
            "net_payout": round(net_payout, 2),
            "matched_orders": matched_orders,
            "unmatched_orders": unmatched_orders,
            "total_orders": len(order_summaries)
        }
    }


@api_router.post("/ecommerce/upload-payout")
async def upload_payout_statement(
    platform: str,
    firm_id: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Upload and process an e-commerce payout statement.
    - Amazon: CSV file with single sheet
    - Flipkart: Excel file with multiple sheets
    
    firm_id is required to associate the statement with the correct business entity.
    
    CRITICAL FIX: Added deduplication check to prevent double-uploading statements.
    """
    import pandas as pd
    import io
    
    platform = platform.lower()
    if platform not in ["amazon", "flipkart"]:
        raise HTTPException(status_code=400, detail="Platform must be 'amazon' or 'flipkart'")
    
    # Validate firm exists
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0, "id": 1, "name": 1})
    if not firm:
        raise HTTPException(status_code=400, detail="Invalid firm_id. Please select a valid firm.")
    
    # Read the file
    try:
        content = await file.read()
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to read file: {str(e)}")
    
    # ==================== DEDUPLICATION CHECK ====================
    # Check if a statement with the same filename+firm combination already exists
    existing_statement = await db.payout_statements.find_one({
        "filename": file.filename,
        "firm_id": firm_id,
        "platform": platform
    }, {"_id": 0, "id": 1, "statement_number": 1, "created_at": 1})
    
    if existing_statement:
        raise HTTPException(
            status_code=400, 
            detail=f"Duplicate statement detected! File '{file.filename}' was already uploaded on {existing_statement.get('created_at', 'N/A')[:10]} (Statement: {existing_statement.get('statement_number')}). Delete the existing statement first if you want to re-upload."
        )
    
    # Additional dedup: Check by file content hash for same-content different-name scenarios
    import hashlib
    content_hash = hashlib.md5(content).hexdigest()
    existing_by_hash = await db.payout_statements.find_one({
        "content_hash": content_hash,
        "firm_id": firm_id,
        "platform": platform
    }, {"_id": 0, "id": 1, "statement_number": 1, "filename": 1, "created_at": 1})
    
    if existing_by_hash:
        raise HTTPException(
            status_code=400,
            detail=f"Duplicate statement content detected! This file's content matches previously uploaded '{existing_by_hash.get('filename')}' (Statement: {existing_by_hash.get('statement_number')}). The same data cannot be uploaded twice."
        )
    # ==================== END DEDUPLICATION CHECK ====================
    
    now = datetime.now(timezone.utc).isoformat()
    statement_id = str(uuid.uuid4())
    statement_number = f"STMT-{platform.upper()[:3]}-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}"
    
    # Create initial statement record with content hash for future dedup
    statement = {
        "id": statement_id,
        "statement_number": statement_number,
        "platform": platform,
        "firm_id": firm_id,
        "firm_name": firm.get("name"),
        "filename": file.filename,
        "content_hash": content_hash,
        "status": "processing",
        "created_by": user["id"],
        "created_by_name": user.get("name", user.get("email")),
        "created_at": now,
        "updated_at": now
    }
    
    await db.payout_statements.insert_one(statement)
    
    try:
        if platform == "flipkart":
            # Use Flipkart multi-sheet Excel parser
            result = await parse_flipkart_excel(content, statement_id, firm_id, user, db)
            
            # Insert transactions
            if result["transactions"]:
                await db.payout_transactions.insert_many(result["transactions"])
            
            # Insert order summaries
            order_summary_records = []
            for order_id, summary in result["order_summaries"].items():
                summary["id"] = str(uuid.uuid4())
                summary["statement_id"] = statement_id
                summary["created_at"] = now
                order_summary_records.append(summary)
            
            if order_summary_records:
                await db.payout_order_summaries.insert_many(order_summary_records)
            
            # Insert non-order charges
            if result["non_order_charges"]:
                await db.payout_non_order_charges.insert_many(result["non_order_charges"])
            
            # Insert tax entries
            if result["tax_entries"]:
                await db.payout_tax_entries.insert_many(result["tax_entries"])
            
            # Calculate matched/unmatched counts for Flipkart
            matched_count_fk = sum(1 for t in result["transactions"] if t.get("crm_match_status") == "matched" and t.get("transaction_type") in ["order_payment", "refund"])
            unmatched_count_fk = sum(1 for t in result["transactions"] if t.get("crm_match_status") != "matched" and t.get("transaction_type") in ["order_payment", "refund"])
            
            # Update statement
            await db.payout_statements.update_one(
                {"id": statement_id},
                {"$set": {
                    "statement_period_start": result["statement_period_start"],
                    "statement_period_end": result["statement_period_end"],
                    "summary": result["summary"],
                    "sheet_summaries": result["sheet_summaries"],
                    "status": "processed",
                    "matched_count": matched_count_fk,
                    "unmatched_count": unmatched_count_fk,
                    "updated_at": now
                }}
            )
            
            return {
                "statement_id": statement_id,
                "statement_number": statement_number,
                "platform": platform,
                "firm_id": firm_id,
                "firm_name": firm.get("name"),
                "summary": result["summary"],
                "sheet_summaries": result["sheet_summaries"],
                "message": f"Flipkart statement processed: {len(result['transactions'])} transactions, {len(result['order_summaries'])} orders, {len(result['non_order_charges'])} non-order charges"
            }
        
        else:
            # Amazon CSV parser (existing logic)
            try:
                df = pd.read_csv(io.BytesIO(content), encoding='utf-8')
            except:
                df = pd.read_csv(io.BytesIO(content), encoding='latin-1')
            
            # Normalize column names
            df.columns = df.columns.str.strip().str.lower().str.replace(' ', '_')
            
            # Amazon column mapping
            column_map = {
                'date': 'date',
                'transaction_type': 'transaction_type',
                'order_id': 'order_id',
                'product_details': 'product_details',
                'total_product_charges': 'total_product_charges',
                'total_promotional_rebates': 'promotional_rebates',
                'amazon_fees': 'platform_fees',
                'other': 'other_adjustments',
                'total_(inr)': 'total_amount'
            }
            
            # Rename columns
            df = df.rename(columns=column_map)
            
            # Parse dates
            def parse_date(date_str):
                if pd.isna(date_str):
                    return None
                try:
                    for fmt in ['%d/%m/%Y', '%Y-%m-%d', '%d-%m-%Y', '%m/%d/%Y']:
                        try:
                            return datetime.strptime(str(date_str), fmt).strftime('%Y-%m-%d')
                        except:
                            continue
                    return str(date_str)
                except:
                    return None
            
            if 'date' in df.columns:
                df['date'] = df['date'].apply(parse_date)
            
            # Get statement period
            dates = df['date'].dropna().tolist()
            if dates:
                statement_start = min(dates)
                statement_end = max(dates)
            else:
                statement_start = datetime.now(timezone.utc).strftime('%Y-%m-%d')
                statement_end = statement_start
            
            # Update statement with period
            await db.payout_statements.update_one(
                {"id": statement_id},
                {"$set": {
                    "statement_period_start": statement_start,
                    "statement_period_end": statement_end
                }}
            )
            
            # Process transactions
            transactions = []
            order_summaries = {}
            
            # Counters for summary
            total_order_payments = 0
            total_refunds = 0
            total_platform_fees = 0
            total_other = 0
            reserve_held = 0
            reserve_released = 0
            matched_orders = 0
            unmatched_orders = 0
            
            for idx, row in df.iterrows():
                trans_type = str(row.get('transaction_type', '')).strip().lower()
                order_id = str(row.get('order_id', '')).strip()
                
                # Skip header rows or empty rows
                if not trans_type or trans_type == 'transaction_type':
                    continue
                
                # Clean order ID
                if order_id in ['---', '', 'nan', 'None']:
                    order_id = None
                
                # Parse amounts (handle comma-separated numbers)
                def parse_amount(val):
                    if pd.isna(val) or val == '':
                        return 0.0
                    try:
                        return float(str(val).replace(',', ''))
                    except:
                        return 0.0
                
                product_charges = parse_amount(row.get('total_product_charges', 0))
                promo_rebates = parse_amount(row.get('promotional_rebates', 0))
                platform_fees_amt = parse_amount(row.get('platform_fees', 0))
                other_adj = parse_amount(row.get('other_adjustments', 0))
                total_amt = parse_amount(row.get('total_amount', 0))
                
                # Classify transaction
                if 'order' in trans_type and 'payment' in trans_type:
                    trans_category = 'order_payment'
                    total_order_payments += total_amt
                elif 'refund' in trans_type:
                    trans_category = 'refund'
                    total_refunds += abs(total_amt)
                elif 'unavailable' in trans_type and 'previous' not in trans_type:
                    trans_category = 'reserve_held'
                    reserve_held += abs(total_amt)
                elif 'previous' in trans_type and 'unavailable' in trans_type:
                    trans_category = 'reserve_released'
                    reserve_released += abs(total_amt)
                else:
                    trans_category = 'other'
                    total_other += total_amt
                
                # Track platform fees
                if platform_fees_amt != 0:
                    total_platform_fees += abs(platform_fees_amt)
                
                # Match with CRM order (filter by firm)
                crm_match = None
                crm_order_id = None
                if order_id:
                    crm_dispatch = await db.dispatches.find_one({
                        "firm_id": firm_id,
                        "$or": [
                            {"marketplace_order_id": order_id},
                            {"order_id": order_id},
                            {"external_order_id": order_id}
                        ]
                    }, {"_id": 0, "id": 1, "dispatch_number": 1, "order_id": 1})
                    
                    if crm_dispatch:
                        crm_match = "matched"
                        crm_order_id = crm_dispatch.get("id")
                        matched_orders += 1
                    else:
                        crm_match = "unmatched"
                        unmatched_orders += 1
                
                # Create transaction record
                trans_record = {
                    "id": str(uuid.uuid4()),
                    "statement_id": statement_id,
                    "row_index": idx,
                    "date": row.get('date'),
                    "transaction_type": str(row.get('transaction_type', '')).strip(),
                    "transaction_category": trans_category,
                    "marketplace_order_id": order_id,
                    "product_details": str(row.get('product_details', ''))[:500] if row.get('product_details') else None,
                    "total_product_charges": product_charges,
                    "promotional_rebates": promo_rebates,
                    "platform_fees": platform_fees_amt,
                    "other_adjustments": other_adj,
                    "total_amount": total_amt,
                    "crm_match_status": crm_match,
                    "crm_order_id": crm_order_id,
                    "created_at": now
                }
                transactions.append(trans_record)
                
                # Build order-level summary
                if order_id and trans_category in ['order_payment', 'refund']:
                    if order_id not in order_summaries:
                        order_summaries[order_id] = {
                            "marketplace_order_id": order_id,
                            "product_details": str(row.get('product_details', ''))[:200] if row.get('product_details') else None,
                            "gross_sale": 0,
                            "platform_fees": 0,
                            "promotional_rebates": 0,
                            "other_adjustments": 0,
                            "refund_amount": 0,
                            "net_realized": 0,
                            "crm_match_status": crm_match,
                            "crm_order_id": crm_order_id,
                            "finance_status": "pending"
                        }
                    
                    if trans_category == 'order_payment':
                        order_summaries[order_id]["gross_sale"] += product_charges
                        order_summaries[order_id]["platform_fees"] += abs(platform_fees_amt)
                        order_summaries[order_id]["promotional_rebates"] += abs(promo_rebates)
                        order_summaries[order_id]["other_adjustments"] += other_adj
                        order_summaries[order_id]["net_realized"] += total_amt
                        order_summaries[order_id]["finance_status"] = "paid"
                    elif trans_category == 'refund':
                        order_summaries[order_id]["refund_amount"] += abs(total_amt)
                        order_summaries[order_id]["net_realized"] += total_amt  # Negative
                        order_summaries[order_id]["finance_status"] = "refunded"
            
            # Insert transactions
            if transactions:
                await db.payout_transactions.insert_many(transactions)
            
            # Insert order summaries
            order_summary_records = []
            for order_id, summary in order_summaries.items():
                summary["id"] = str(uuid.uuid4())
                summary["statement_id"] = statement_id
                summary["created_at"] = now
                order_summary_records.append(summary)
            
            if order_summary_records:
                await db.payout_order_summaries.insert_many(order_summary_records)
            
            # Calculate net payout
            net_payout = total_order_payments - total_refunds + reserve_released - reserve_held + total_other
            
            # Update statement with summary
            statement_summary = {
                "total_transactions": len(transactions),
                "total_order_payments": round(total_order_payments, 2),
                "total_refunds": round(total_refunds, 2),
                "total_platform_fees": round(total_platform_fees, 2),
                "total_other_adjustments": round(total_other, 2),
                "reserve_held": round(reserve_held, 2),
                "reserve_released": round(reserve_released, 2),
                "net_payout": round(net_payout, 2),
                "matched_orders": matched_orders,
                "unmatched_orders": unmatched_orders,
                "total_orders": len(order_summaries)
            }
            
            await db.payout_statements.update_one(
                {"id": statement_id},
                {"$set": {
                    "summary": statement_summary,
                    "status": "processed",
                    "matched_count": matched_orders,
                    "unmatched_count": unmatched_orders,
                    "updated_at": now
                }}
            )
            
            return {
                "statement_id": statement_id,
                "statement_number": statement_number,
                "platform": platform,
                "firm_id": firm_id,
                "firm_name": firm.get("name"),
                "summary": statement_summary,
                "message": f"Amazon statement processed: {len(transactions)} transactions, {len(order_summaries)} unique orders"
            }
    
    except Exception as e:
        # Mark statement as failed
        await db.payout_statements.update_one(
            {"id": statement_id},
            {"$set": {"status": "failed", "error": str(e), "updated_at": now}}
        )
        raise HTTPException(status_code=500, detail=f"Failed to process statement: {str(e)}")


@api_router.get("/ecommerce/statements")
async def list_payout_statements(
    platform: Optional[str] = None,
    firm_id: Optional[str] = None,
    status: Optional[str] = None,
    limit: int = 50,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """List all payout statements, optionally filtered by firm and platform"""
    query = {}
    if platform:
        query["platform"] = platform.lower()
    if firm_id:
        query["firm_id"] = firm_id
    if status:
        query["status"] = status
    
    statements = await db.payout_statements.find(query, {"_id": 0}).sort("created_at", -1).to_list(limit)
    
    # Calculate matched/unmatched counts for statements that don't have them
    for stmt in statements:
        if "matched_count" not in stmt or "unmatched_count" not in stmt:
            # Support various transaction types: Amazon (Order Payment, Refund) and Flipkart (order_settlement)
            order_types = ["order_payment", "refund", "Order Payment", "Refund", "order_settlement"]
            matched = await db.payout_transactions.count_documents({
                "statement_id": stmt["id"],
                "crm_match_status": "matched",
                "transaction_type": {"$in": order_types}
            })
            unmatched = await db.payout_transactions.count_documents({
                "statement_id": stmt["id"],
                "crm_match_status": {"$ne": "matched"},
                "transaction_type": {"$in": order_types}
            })
            stmt["matched_count"] = matched
            stmt["unmatched_count"] = unmatched
    
    return statements


@api_router.get("/ecommerce/statements/{statement_id}")
async def get_payout_statement(
    statement_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get payout statement details with transactions, order summaries, non-order charges, and tax entries"""
    statement = await db.payout_statements.find_one({"id": statement_id}, {"_id": 0})
    if not statement:
        raise HTTPException(status_code=404, detail="Statement not found")
    
    transactions = await db.payout_transactions.find(
        {"statement_id": statement_id}, {"_id": 0}
    ).sort("row_index", 1).to_list(5000)
    
    order_summaries = await db.payout_order_summaries.find(
        {"statement_id": statement_id}, {"_id": 0}
    ).sort("gross_sale", -1).to_list(5000)
    
    # Get non-order charges (for Flipkart)
    non_order_charges = await db.payout_non_order_charges.find(
        {"statement_id": statement_id}, {"_id": 0}
    ).to_list(1000)
    
    # Get tax entries (for Flipkart)
    tax_entries = await db.payout_tax_entries.find(
        {"statement_id": statement_id}, {"_id": 0}
    ).to_list(1000)
    
    # Calculate matched/unmatched counts if not present in statement
    if "matched_count" not in statement or "unmatched_count" not in statement:
        order_types = ["order_payment", "refund", "Order Payment", "Refund", "order_settlement"]
        matched_count = sum(1 for t in transactions if t.get("crm_match_status") == "matched" and t.get("transaction_type") in order_types)
        unmatched_count = sum(1 for t in transactions if t.get("crm_match_status") != "matched" and t.get("transaction_type") in order_types)
        statement["matched_count"] = matched_count
        statement["unmatched_count"] = unmatched_count
    
    return {
        "statement": statement,
        "transactions": transactions,
        "order_summaries": order_summaries,
        "non_order_charges": non_order_charges,
        "tax_entries": tax_entries
    }


@api_router.delete("/ecommerce/statements/{statement_id}")
async def delete_payout_statement(
    statement_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Delete a payout statement and all related records (admin only)"""
    statement = await db.payout_statements.find_one({"id": statement_id}, {"_id": 0})
    if not statement:
        raise HTTPException(status_code=404, detail="Statement not found")
    
    # Delete all related records
    await db.payout_transactions.delete_many({"statement_id": statement_id})
    await db.payout_order_summaries.delete_many({"statement_id": statement_id})
    await db.payout_non_order_charges.delete_many({"statement_id": statement_id})
    await db.payout_tax_entries.delete_many({"statement_id": statement_id})
    
    # Reset payment status on any linked dispatches
    await db.dispatches.update_many(
        {"ecommerce_statement_id": statement_id},
        {"$unset": {"ecommerce_statement_id": "", "marketplace_payment_status": ""}}
    )
    
    # Delete the statement itself
    await db.payout_statements.delete_one({"id": statement_id})
    
    # Create audit log
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "ecommerce_statement_deleted",
        "entity_type": "payout_statement",
        "entity_id": statement_id,
        "entity_name": statement.get("statement_number"),
        "performed_by": user["id"],
        "performed_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}",
        "details": {"platform": statement.get("platform"), "firm_id": statement.get("firm_id")},
        "timestamp": datetime.now(timezone.utc).isoformat()
    })
    
    return {"message": f"Statement {statement.get('statement_number')} and all related records deleted"}


@api_router.post("/ecommerce/upload-mtr")
async def upload_mtr_report(
    mtr_type: str,  # "b2c" or "b2b"
    firm_id: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Upload Amazon MTR (Monthly Transaction Report) for GST data enrichment.
    - Updates existing dispatches with state and GST information
    - Does NOT create new entries - only enriches existing data
    - Tracks uploaded reports to prevent duplicates
    
    MTR files contain: Order ID, Ship To State, Invoice Number, GST breakdowns (CGST, SGST, IGST), HSN codes
    """
    import pandas as pd
    import io
    
    mtr_type = mtr_type.lower()
    if mtr_type not in ["b2c", "b2b"]:
        raise HTTPException(status_code=400, detail="mtr_type must be 'b2c' or 'b2b'")
    
    # Validate firm exists
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0, "id": 1, "name": 1})
    if not firm:
        raise HTTPException(status_code=400, detail="Invalid firm_id")
    
    # Read the file
    try:
        content = await file.read()
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to read file: {str(e)}")
    
    now = datetime.now(timezone.utc).isoformat()
    report_id = str(uuid.uuid4())
    
    # Parse CSV
    try:
        try:
            df = pd.read_csv(io.BytesIO(content), encoding='utf-8')
        except:
            df = pd.read_csv(io.BytesIO(content), encoding='latin-1')
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to parse CSV: {str(e)}")
    
    # Normalize column names
    df.columns = df.columns.str.strip().str.lower().str.replace(' ', '_').str.replace('/', '_')
    
    # Check for duplicates - prevent re-uploading same file
    # Extract period from filename or data
    filename = file.filename or "mtr_report.csv"
    
    # Check if this exact filename was already uploaded for this firm
    # Re-upload of the same file overwrites the prior report record (so corrections / re-runs work).
    await db.mtr_reports.delete_many({"filename": filename, "firm_id": firm_id, "mtr_type": mtr_type})
    
    # Track statistics
    stats = {
        "total_rows": len(df),
        "shipment_rows": 0,
        "cancel_rows": 0,
        "refund_rows": 0,
        "matched_dispatches": 0,
        "state_updated": 0,
        "gst_updated": 0,
        "no_match": 0,
        "already_has_state": 0,
        "skipped_duplicates": 0
    }
    
    # Track which order_ids we've already processed in this upload (to handle duplicates in MTR itself)
    processed_order_ids = set()
    
    # Required columns check
    required_cols = ['order_id', 'ship_to_state', 'transaction_type']
    missing = [c for c in required_cols if c not in df.columns]
    if missing:
        raise HTTPException(status_code=400, detail=f"Missing required columns: {missing}. Found columns: {list(df.columns)}")
    
    # Process each row - only Shipment transactions have valid GST data
    updates_made = []
    
    for idx, row in df.iterrows():
        order_id = str(row.get('order_id', '')).strip()
        transaction_type = str(row.get('transaction_type', '')).strip().lower()
        ship_to_state = str(row.get('ship_to_state', '')).strip().upper()
        
        if not order_id or order_id == 'nan':
            continue
        
        # Track transaction types
        if transaction_type == 'shipment':
            stats["shipment_rows"] += 1
        elif transaction_type == 'cancel':
            stats["cancel_rows"] += 1
            continue  # Skip cancelled orders
        elif transaction_type == 'refund':
            stats["refund_rows"] += 1
            # Still process refunds to get state info
        else:
            continue
        
        # Check if we already processed this order_id in this upload
        if order_id in processed_order_ids:
            stats["skipped_duplicates"] += 1
            continue
        processed_order_ids.add(order_id)
        
        # Extract GST data
        invoice_number = str(row.get('invoice_number', '')).strip()
        invoice_amount = float(row.get('invoice_amount', 0) or 0)
        cgst_tax = float(row.get('cgst_tax', 0) or 0)
        sgst_tax = float(row.get('sgst_tax', 0) or 0)
        igst_tax = float(row.get('igst_tax', 0) or 0)
        hsn_code = str(row.get('hsn_sac', row.get('hsn', ''))).strip()
        
        # Find matching dispatch by marketplace_order_id or order_id
        dispatch = await db.dispatches.find_one({
            "$or": [
                {"marketplace_order_id": order_id},
                {"order_id": order_id}
            ],
            "firm_id": firm_id
        }, {"_id": 0, "id": 1, "dispatch_number": 1, "customer_state": 1, "state": 1, "gst_data": 1})
        
        if not dispatch:
            # Try amazon_orders
            amazon_order = await db.amazon_orders.find_one({
                "amazon_order_id": order_id,
                "firm_id": firm_id
            }, {"_id": 0, "amazon_order_id": 1})
            
            if not amazon_order:
                stats["no_match"] += 1
                continue
            
            # Update amazon_orders with state info
            update_fields = {}
            if ship_to_state and ship_to_state != 'NAN':
                update_fields["shipping_state"] = ship_to_state
                update_fields["customer_state"] = ship_to_state
                
            if update_fields:
                await db.amazon_orders.update_one(
                    {"amazon_order_id": order_id},
                    {"$set": update_fields}
                )
            continue
        
        stats["matched_dispatches"] += 1
        
        # Check if state already exists
        existing_state = dispatch.get("customer_state") or dispatch.get("state")
        
        # Build update fields
        update_fields = {}
        
        # Update state if missing
        if ship_to_state and ship_to_state != 'NAN' and not existing_state:
            update_fields["customer_state"] = ship_to_state
            update_fields["state"] = ship_to_state
            stats["state_updated"] += 1
        elif existing_state:
            stats["already_has_state"] += 1
        
        # Update GST data if available (always update if we have new GST info)
        if cgst_tax > 0 or sgst_tax > 0 or igst_tax > 0:
            gst_data = dispatch.get("gst_data") or {}
            gst_data.update({
                "cgst": cgst_tax,
                "sgst": sgst_tax,
                "igst": igst_tax,
                "total_gst": cgst_tax + sgst_tax + igst_tax,
                "invoice_amount": invoice_amount,
                "mtr_source": True,
                "mtr_updated_at": now
            })
            if hsn_code and hsn_code != 'nan':
                gst_data["hsn_code"] = hsn_code
            if invoice_number and invoice_number != 'nan':
                gst_data["amazon_invoice_number"] = invoice_number
            
            update_fields["gst_data"] = gst_data
            stats["gst_updated"] += 1
        
        # Apply updates if any
        if update_fields:
            update_fields["mtr_enriched"] = True
            update_fields["mtr_enriched_at"] = now
            
            await db.dispatches.update_one(
                {"id": dispatch["id"]},
                {"$set": update_fields}
            )
            
            updates_made.append({
                "dispatch_id": dispatch["id"],
                "dispatch_number": dispatch.get("dispatch_number"),
                "order_id": order_id,
                "state_updated": "customer_state" in update_fields,
                "gst_updated": "gst_data" in update_fields
            })
    
    # Save report record to prevent duplicates
    report_record = {
        "id": report_id,
        "filename": filename,
        "mtr_type": mtr_type,
        "firm_id": firm_id,
        "firm_name": firm.get("name"),
        "stats": stats,
        "created_by": user["id"],
        "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "created_at": now
    }
    await db.mtr_reports.insert_one(report_record)

    # Also persist line-level invoice rows into `amazon_mtr` so the GST Audit can do invoice-level
    # Amazon↔GSTR-1↔CRM matching (the order_id→invoice_number bridge). Best-effort, never blocks upload.
    mtr_persisted = 0
    try:
        from utils import amazon_mtr as _amtr
        parsed = _amtr.parse_mtr_csv(content)
        pk = parsed.get("period_key")
        if pk and parsed.get("invoices"):
            await db.amazon_mtr.delete_many({"firm_id": firm_id, "period_key": pk, "mtr_type": mtr_type})
            docs = [{"id": str(uuid.uuid4()), "firm_id": firm_id, "period_key": pk,
                     "mtr_type": mtr_type, "created_at": now, **e} for e in parsed["invoices"].values()]
            if docs:
                await db.amazon_mtr.insert_many(docs)
                mtr_persisted = len(docs)
    except Exception as e:
        logger.error(f"amazon_mtr persist from upload-mtr failed: {e}")

    return {
        "report_id": report_id,
        "filename": filename,
        "mtr_type": mtr_type,
        "firm_id": firm_id,
        "stats": stats,
        "message": f"MTR {mtr_type.upper()} processed: {stats['matched_dispatches']} dispatches matched, {stats['state_updated']} states updated, {stats['gst_updated']} GST records updated"
                   + (f"; {mtr_persisted} invoices linked for GST audit" if mtr_persisted else ""),
        "updates": updates_made[:20]  # Return first 20 updates for reference
    }


