@api_router.post("/ecommerce/upload-flipkart-sales")
async def upload_flipkart_sales_report(
    report_type: str,  # "sales" or "gst"
    firm_id: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Upload Flipkart Sales Report for GST data enrichment.
    - Updates existing dispatches with state and GST information
    - Does NOT create new entries - only enriches existing data
    - Tracks uploaded reports to prevent duplicates
    
    Flipkart Sales Report contains: Order ID, Customer's Delivery State, GST breakdowns (CGST, SGST, IGST), HSN codes
    """
    import pandas as pd
    import io
    
    report_type = report_type.lower()
    if report_type not in ["sales", "gst"]:
        raise HTTPException(status_code=400, detail="report_type must be 'sales' or 'gst'")
    
    # Validate firm exists
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0, "id": 1, "name": 1})
    if not firm:
        raise HTTPException(status_code=400, detail="Invalid firm_id")
    
    # Read the file
    try:
        content = await file.read()
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to read file: {str(e)}")
    
    now = datetime.now(timezone.utc).isoformat()
    report_id = str(uuid.uuid4())
    filename = file.filename or "flipkart_report.xlsx"
    
    # Check for duplicates
    existing_report = await db.mtr_reports.find_one({
        "filename": filename,
        "firm_id": firm_id,
        "platform": "flipkart"
    })
    if existing_report:
        raise HTTPException(
            status_code=400, 
            detail=f"This Flipkart report ({filename}) was already uploaded on {existing_report.get('created_at', 'unknown date')}. Duplicate uploads are not allowed."
        )
    
    # Parse Excel file
    try:
        # Try to read as Excel file
        excel_file = pd.ExcelFile(io.BytesIO(content))
        sheet_names = excel_file.sheet_names
        
        # Find the main sales sheet - skip Help sheet
        main_sheet = None
        for sheet in sheet_names:
            sheet_lower = sheet.lower()
            if sheet_lower == 'help':
                continue
            if 'sales' in sheet_lower:
                main_sheet = sheet
                break
        
        # If no sales sheet found, use first non-Help sheet
        if not main_sheet:
            for sheet in sheet_names:
                if sheet.lower() != 'help':
                    main_sheet = sheet
                    break
        
        if not main_sheet:
            main_sheet = sheet_names[0]
        
        df = pd.read_excel(io.BytesIO(content), sheet_name=main_sheet)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to parse Excel file: {str(e)}. Make sure it's a valid .xlsx file.")
    
    # Normalize column names
    df.columns = df.columns.str.strip().str.lower().str.replace(' ', '_').str.replace("'", "").str.replace('/', '_')
    
    # Track statistics
    stats = {
        "total_rows": len(df),
        "sale_rows": 0,
        "return_rows": 0,
        "cancel_rows": 0,
        "matched_dispatches": 0,
        "state_updated": 0,
        "gst_updated": 0,
        "no_match": 0,
        "already_has_state": 0,
        "skipped_duplicates": 0,
        "sheet_used": main_sheet,
        "sheets_found": sheet_names
    }
    
    # Flipkart column mapping - try multiple possible column names
    order_id_col = None
    state_col = None
    event_type_col = None
    
    # Find Order ID column
    for col in ['order_id', 'orderid', 'order_item_id']:
        if col in df.columns:
            order_id_col = col
            break
    
    # Find State column (Customer's Delivery State)
    for col in ['customers_delivery_state', 'customer_delivery_state', 'delivery_state', 
                'delivered_state_(pos)', 'delivered_state', 'ship_to_state']:
        if col in df.columns:
            state_col = col
            break
    
    # Find Event Type column
    for col in ['event_type', 'event_sub_type', 'transaction_type', 'document_type']:
        if col in df.columns:
            event_type_col = col
            break
    
    if not order_id_col:
        raise HTTPException(
            status_code=400, 
            detail=f"Could not find Order ID column. Available columns: {list(df.columns)[:20]}"
        )
    
    if not state_col:
        raise HTTPException(
            status_code=400, 
            detail=f"Could not find State column (Customer's Delivery State). Available columns: {list(df.columns)[:20]}"
        )
    
    # Find GST columns
    igst_amt_col = None
    cgst_amt_col = None
    sgst_amt_col = None
    hsn_col = None
    invoice_col = None
    invoice_amt_col = None
    
    for col in df.columns:
        col_lower = col.lower()
        if 'igst' in col_lower and ('amount' in col_lower or col_lower == 'igst_amount') and 'tcs' not in col_lower:
            igst_amt_col = col
        elif 'cgst' in col_lower and ('amount' in col_lower or col_lower == 'cgst_amount') and 'tcs' not in col_lower:
            cgst_amt_col = col
        elif 'sgst' in col_lower and ('amount' in col_lower or col_lower == 'sgst_amount') and 'tcs' not in col_lower:
            sgst_amt_col = col
        elif col_lower in ['hsn_code', 'hsn', 'hsn_sac']:
            hsn_col = col
        elif col_lower in ['buyer_invoice_id', 'invoice_number', 'invoice_no']:
            invoice_col = col
        elif 'final_invoice_amount' in col_lower or col_lower in ['invoice_amount', 'buyer_invoice_amount']:
            invoice_amt_col = col
    
    # Track processed order IDs
    processed_order_ids = set()
    updates_made = []
    
    for idx, row in df.iterrows():
        order_id = str(row.get(order_id_col, '')).strip()
        state = str(row.get(state_col, '')).strip().upper()
        event_type = str(row.get(event_type_col, '')).strip().lower() if event_type_col else 'sale'
        
        if not order_id or order_id == 'nan' or order_id == 'None':
            continue
        
        # Track event types
        if 'sale' in event_type or event_type == '':
            stats["sale_rows"] += 1
        elif 'return' in event_type:
            stats["return_rows"] += 1
        elif 'cancel' in event_type or 'void' in event_type:
            stats["cancel_rows"] += 1
            continue  # Skip cancelled orders
        
        # Check for duplicates in this upload
        if order_id in processed_order_ids:
            stats["skipped_duplicates"] += 1
            continue
        processed_order_ids.add(order_id)
        
        # Extract GST data
        igst_amt = float(row.get(igst_amt_col, 0) or 0) if igst_amt_col else 0
        cgst_amt = float(row.get(cgst_amt_col, 0) or 0) if cgst_amt_col else 0
        sgst_amt = float(row.get(sgst_amt_col, 0) or 0) if sgst_amt_col else 0
        hsn_code = str(row.get(hsn_col, '')).strip() if hsn_col else ''
        invoice_number = str(row.get(invoice_col, '')).strip() if invoice_col else ''
        invoice_amount = float(row.get(invoice_amt_col, 0) or 0) if invoice_amt_col else 0
        
        # Find matching dispatch
        dispatch = await db.dispatches.find_one({
            "$or": [
                {"marketplace_order_id": order_id},
                {"order_id": order_id}
            ],
            "firm_id": firm_id
        }, {"_id": 0, "id": 1, "dispatch_number": 1, "customer_state": 1, "state": 1, "gst_data": 1})
        
        if not dispatch:
            stats["no_match"] += 1
            continue
        
        stats["matched_dispatches"] += 1
        
        # Check existing state
        existing_state = dispatch.get("customer_state") or dispatch.get("state")
        
        # Build update fields
        update_fields = {}
        
        # Update state if missing
        if state and state not in ['NAN', 'NONE', ''] and not existing_state:
            update_fields["customer_state"] = state
            update_fields["state"] = state
            stats["state_updated"] += 1
        elif existing_state:
            stats["already_has_state"] += 1
        
        # Update GST data if available
        if igst_amt > 0 or cgst_amt > 0 or sgst_amt > 0:
            gst_data = dispatch.get("gst_data") or {}
            gst_data.update({
                "cgst": cgst_amt,
                "sgst": sgst_amt,
                "igst": igst_amt,
                "total_gst": cgst_amt + sgst_amt + igst_amt,
                "invoice_amount": invoice_amount,
                "flipkart_source": True,
                "flipkart_updated_at": now
            })
            if hsn_code and hsn_code not in ['nan', 'None', '']:
                gst_data["hsn_code"] = hsn_code
            if invoice_number and invoice_number not in ['nan', 'None', '']:
                gst_data["flipkart_invoice_number"] = invoice_number
            
            update_fields["gst_data"] = gst_data
            stats["gst_updated"] += 1
        
        # Apply updates
        if update_fields:
            update_fields["flipkart_enriched"] = True
            update_fields["flipkart_enriched_at"] = now
            
            await db.dispatches.update_one(
                {"id": dispatch["id"]},
                {"$set": update_fields}
            )
            
            updates_made.append({
                "dispatch_id": dispatch["id"],
                "dispatch_number": dispatch.get("dispatch_number"),
                "order_id": order_id,
                "state_updated": "customer_state" in update_fields,
                "gst_updated": "gst_data" in update_fields
            })
    
    # Save report record
    report_record = {
        "id": report_id,
        "filename": filename,
        "platform": "flipkart",
        "mtr_type": f"flipkart_{report_type}",
        "firm_id": firm_id,
        "firm_name": firm.get("name"),
        "stats": stats,
        "created_by": user["id"],
        "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "created_at": now
    }
    await db.mtr_reports.insert_one(report_record)
    
    return {
        "report_id": report_id,
        "filename": filename,
        "platform": "flipkart",
        "report_type": report_type,
        "firm_id": firm_id,
        "stats": stats,
        "message": f"Flipkart {report_type.title()} Report processed: {stats['matched_dispatches']} dispatches matched, {stats['state_updated']} states updated, {stats['gst_updated']} GST records updated",
        "updates": updates_made[:20]
    }


@api_router.delete("/ecommerce/mtr-reports/{report_id}")
async def delete_mtr_report(
    report_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Delete an MTR report record (allows re-upload of same file)"""
    report = await db.mtr_reports.find_one({"id": report_id}, {"_id": 0})
    if not report:
        raise HTTPException(status_code=404, detail="MTR report not found")
    
    await db.mtr_reports.delete_one({"id": report_id})
    
    # Also delete associated GST data if it's a Vyapar report
    if report.get("platform") == "vyapar":
        await db.gst_report_data.delete_many({"report_id": report_id})
    
    return {"message": f"Report {report.get('filename')} deleted. You can now re-upload this file."}


@api_router.post("/ecommerce/upload-vyapar-gstr")
async def upload_vyapar_gstr_report(
    report_type: str,  # "gstr1" or "gstr3b"
    firm_id: str,
    period_month: int,  # 1-12
    period_year: int,   # e.g., 2026
    file: UploadFile = File(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Upload Vyapar GSTR1 or GSTR3B report for GST consolidation.
    This stores the actual GST data for later consolidation with Amazon/Flipkart data.
    """
    import pandas as pd
    import io
    
    report_type = report_type.lower()
    if report_type not in ["gstr1", "gstr3b"]:
        raise HTTPException(status_code=400, detail="report_type must be 'gstr1' or 'gstr3b'")
    
    if period_month < 1 or period_month > 12:
        raise HTTPException(status_code=400, detail="period_month must be between 1 and 12")
    
    # Validate firm exists
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0, "id": 1, "name": 1, "gstin": 1})
    if not firm:
        raise HTTPException(status_code=400, detail="Invalid firm_id")
    
    # Read the file
    try:
        content = await file.read()
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to read file: {str(e)}")
    
    now = datetime.now(timezone.utc).isoformat()
    report_id = str(uuid.uuid4())
    filename = file.filename or f"vyapar_{report_type}.xlsx"
    period_key = f"{period_year}-{period_month:02d}"
    
    # Check for duplicates
    existing_report = await db.mtr_reports.find_one({
        "firm_id": firm_id,
        "platform": "vyapar",
        "mtr_type": report_type,
        "period_key": period_key
    })
    if existing_report:
        raise HTTPException(
            status_code=400, 
            detail=f"A Vyapar {report_type.upper()} report for {period_key} already exists for this firm. Delete the existing report first to re-upload."
        )
    
    # Parse Excel file
    try:
        excel_file = pd.ExcelFile(io.BytesIO(content))
        sheet_names = excel_file.sheet_names
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to parse Excel file: {str(e)}")
    
    stats = {
        "total_invoices": 0,
        "b2b_invoices": 0,
        "b2c_invoices": 0,
        "credit_notes": 0,
        "hsn_entries": 0,
        "total_taxable_value": 0,
        "total_igst": 0,
        "total_cgst": 0,
        "total_sgst": 0,
        "sheets_found": sheet_names
    }
    
    gst_data_records = []
    
    # Firm state code (first 2 chars of GSTIN) is needed to split IGST vs CGST/SGST.
    firm_gstin = str(firm.get("gstin") or "").strip()
    firm_state_code = firm_gstin[:2] if len(firm_gstin) >= 2 else ""

    def _pos_state_code(value: str) -> str:
        """Extract leading 2-digit state code from a Vyapar place-of-supply string
        like '27-Maharashtra' or '27 Maharashtra'."""
        v = (value or "").strip()
        if len(v) >= 2 and v[:2].isdigit():
            return v[:2]
        return ""

    if report_type == "gstr1":
        # Parse GSTR1 sheets

        # B2B Sheet
        if 'b2b,sez,de' in sheet_names:
            try:
                df = pd.read_excel(io.BytesIO(content), sheet_name='b2b,sez,de', header=2)
                df.columns = df.columns.str.strip().str.lower().str.replace(' ', '_').str.replace('/', '_')

                for idx, row in df.iterrows():
                    gstin = str(row.get('gstin_uin_of_recipient', '')).strip()
                    if not gstin or gstin == 'nan' or len(gstin) < 15:
                        continue

                    invoice_no = str(row.get('invoice_number', '')).strip()
                    if not invoice_no or invoice_no == 'nan':
                        continue

                    taxable_value = float(row.get('taxable_value', 0) or 0)
                    rate = float(row.get('rate', 0) or 0)
                    place_of_supply = str(row.get('place_of_supply', '')).strip()
                    # Vyapar's B2B sheet does not emit IGST/CGST/SGST columns; we
                    # compute them from rate × taxable value and the inter-state
                    # decision derived from POS vs firm GSTIN.
                    pos_code = _pos_state_code(place_of_supply)
                    is_igst = bool(firm_state_code and pos_code and firm_state_code != pos_code)
                    igst = round(taxable_value * rate / 100, 2) if (is_igst and rate > 0) else 0.0
                    cgst = round(taxable_value * rate / 200, 2) if (not is_igst and rate > 0) else 0.0
                    sgst = cgst
                    cess = float(row.get('cess_amount', 0) or 0)

                    record = {
                        "id": str(uuid.uuid4()),
                        "report_id": report_id,
                        "firm_id": firm_id,
                        "period_key": period_key,
                        "source": "vyapar",
                        "section": "b2b",
                        "gstin": gstin,
                        "receiver_name": str(row.get('receiver_name', '')).strip(),
                        "invoice_number": invoice_no,
                        "invoice_date": str(row.get('invoice_date', '')),
                        "invoice_value": float(row.get('invoice_value', 0) or 0),
                        "place_of_supply": place_of_supply,
                        "rate": rate,
                        "taxable_value": taxable_value,
                        "igst": igst,
                        "cgst": cgst,
                        "sgst": sgst,
                        "cess": cess,
                        "created_at": now
                    }
                    gst_data_records.append(record)
                    stats["b2b_invoices"] += 1
                    stats["total_taxable_value"] += taxable_value
                    stats["total_igst"] += igst
                    stats["total_cgst"] += cgst
                    stats["total_sgst"] += sgst
            except Exception as e:
                logger.warning(f"Error parsing Vyapar b2b sheet: {e}")
        
        # B2CS Sheet (B2C Small) - Vyapar format has summary rows at top
        if 'b2cs' in sheet_names:
            try:
                # Skip first 3 rows (summary + header row), use manual column names
                df = pd.read_excel(io.BytesIO(content), sheet_name='b2cs', skiprows=3, header=None)
                if len(df.columns) >= 5:
                    # Vyapar B2CS format: Type, Place Of Supply, Applicable Rate, Rate, Taxable Value, Cess, E-Commerce GSTIN
                    df.columns = ['type', 'place_of_supply', 'applicable_rate', 'rate', 'taxable_value', 'cess', 'ecommerce_gstin'][:len(df.columns)]
                
                for idx, row in df.iterrows():
                    place_of_supply = str(row.get('place_of_supply', '')).strip()
                    # Skip header row that might be included and invalid rows
                    if not place_of_supply or place_of_supply == 'nan' or place_of_supply == 'Place Of Supply':
                        continue
                    
                    try:
                        taxable_value = float(row.get('taxable_value', 0) or 0)
                    except:
                        continue
                    
                    if taxable_value == 0:
                        continue
                    
                    try:
                        rate = float(row.get('rate', 0) or 0)
                    except:
                        rate = 0
                    
                    record = {
                        "id": str(uuid.uuid4()),
                        "report_id": report_id,
                        "firm_id": firm_id,
                        "period_key": period_key,
                        "source": "vyapar",
                        "section": "b2cs",
                        "place_of_supply": place_of_supply,
                        "rate": rate,
                        "taxable_value": taxable_value,
                        "igst": 0,  # B2CS is intra-state, so CGST/SGST only
                        "cgst": round(taxable_value * rate / 200, 2) if rate > 0 else 0,
                        "sgst": round(taxable_value * rate / 200, 2) if rate > 0 else 0,
                        "created_at": now
                    }
                    gst_data_records.append(record)
                    stats["b2c_invoices"] += 1
                    stats["total_taxable_value"] += taxable_value
                    stats["total_cgst"] += record["cgst"]
                    stats["total_sgst"] += record["sgst"]
            except Exception as e:
                print(f"Error parsing b2cs sheet: {e}")
        
        # HSN Summary Sheet - Vyapar format
        for hsn_sheet in ['hsn(b2b)', 'hsn(b2c)']:
            if hsn_sheet in sheet_names:
                try:
                    df = pd.read_excel(io.BytesIO(content), sheet_name=hsn_sheet, skiprows=3, header=None)
                    # Vyapar HSN format: HSN, Description, UQC, Total Qty, Total Value, Rate, Taxable Value, IGST, CGST, SGST, Cess
                    if len(df.columns) >= 7:
                        df.columns = ['hsn', 'description', 'uqc', 'total_quantity', 'total_value', 'rate', 'taxable_value', 'igst', 'cgst', 'sgst', 'cess'][:len(df.columns)]
                    
                    for idx, row in df.iterrows():
                        hsn = str(row.get('hsn', '')).strip()
                        # Skip header row and invalid HSN codes
                        if not hsn or hsn == 'nan' or hsn == 'HSN' or len(hsn) < 4:
                            continue
                        
                        try:
                            taxable_value = float(row.get('taxable_value', 0) or 0)
                        except:
                            continue
                        
                        record = {
                            "id": str(uuid.uuid4()),
                            "report_id": report_id,
                            "firm_id": firm_id,
                            "period_key": period_key,
                            "source": "vyapar",
                            "section": f"hsn_{hsn_sheet.replace('hsn(', '').replace(')', '')}",
                            "hsn_code": hsn,
                            "description": str(row.get('description', '')).strip() if pd.notna(row.get('description')) else '',
                            "uqc": str(row.get('uqc', '')).strip() if pd.notna(row.get('uqc')) else 'NOS',
                            "quantity": float(row.get('total_quantity', 0) or 0) if pd.notna(row.get('total_quantity')) else 0,
                            "total_value": float(row.get('total_value', 0) or 0) if pd.notna(row.get('total_value')) else 0,
                            "rate": float(row.get('rate', 0) or 0) if pd.notna(row.get('rate')) else 0,
                            "taxable_value": taxable_value,
                            "igst": float(row.get('igst', 0) or 0) if len(df.columns) > 7 and pd.notna(row.get('igst')) else 0,
                            "cgst": float(row.get('cgst', 0) or 0) if len(df.columns) > 8 and pd.notna(row.get('cgst')) else 0,
                            "sgst": float(row.get('sgst', 0) or 0) if len(df.columns) > 9 and pd.notna(row.get('sgst')) else 0,
                            "created_at": now
                        }
                        gst_data_records.append(record)
                        stats["hsn_entries"] += 1
                except Exception as e:
                    print(f"Error parsing {hsn_sheet}: {e}")
    
    elif report_type == "gstr3b":
        # Parse GSTR3B sheets

        def _find_header_row(df_raw, label_hints: list[str]) -> int:
            """Scan the first 10 rows for one whose first cell matches any hint.

            Vyapar emits a variable number of metadata rows above the header on
            different builds; a fixed header=1 silently drops every row when the
            real header is at row 2 or 3.
            """
            hints_lower = [h.lower() for h in label_hints]
            for i in range(min(10, len(df_raw))):
                cell = df_raw.iloc[i, 0]
                if pd.isna(cell):
                    continue
                s = str(cell).strip().lower()
                if any(h in s for h in hints_lower):
                    return i
            return 1  # fall back to historical default

        # 3.1 Report - Outward Supplies
        if '3.1 Report' in sheet_names:
            try:
                raw = pd.read_excel(io.BytesIO(content), sheet_name='3.1 Report', header=None)
                header_idx = _find_header_row(raw, ["nature", "details of"])
                df = pd.read_excel(io.BytesIO(content), sheet_name='3.1 Report', header=header_idx)

                for idx, row in df.iterrows():
                    nature = str(row.iloc[0] if len(row) > 0 else '').strip()
                    # Skip empties and grand-total footers, but keep all line
                    # items including "Outward taxable supplies (other than ...)"
                    if not nature or nature.lower() in ("nan", "none"):
                        continue
                    # Some Vyapar exports add a "Total" row at the bottom; skip
                    # only that aggregate, not legitimate row labels.
                    if nature.lower().startswith("total"):
                        continue

                    record = {
                        "id": str(uuid.uuid4()),
                        "report_id": report_id,
                        "firm_id": firm_id,
                        "period_key": period_key,
                        "source": "vyapar",
                        "section": "3.1",
                        "nature_of_supplies": nature,
                        "taxable_value": float(row.iloc[1] if len(row) > 1 and pd.notna(row.iloc[1]) else 0),
                        "igst": float(row.iloc[2] if len(row) > 2 and pd.notna(row.iloc[2]) else 0),
                        "cgst": float(row.iloc[3] if len(row) > 3 and pd.notna(row.iloc[3]) else 0),
                        "sgst": float(row.iloc[4] if len(row) > 4 and pd.notna(row.iloc[4]) else 0),
                        "cess": float(row.iloc[5] if len(row) > 5 and pd.notna(row.iloc[5]) else 0),
                        "created_at": now
                    }
                    gst_data_records.append(record)
                    stats["total_taxable_value"] += record["taxable_value"]
                    stats["total_igst"] += record["igst"]
                    stats["total_cgst"] += record["cgst"]
                    stats["total_sgst"] += record["sgst"]
            except Exception as e:
                logger.warning(f"Error parsing Vyapar 3.1 Report: {e}")

        # 4 Report - ITC Claims
        if '4 Report' in sheet_names:
            try:
                raw = pd.read_excel(io.BytesIO(content), sheet_name='4 Report', header=None)
                header_idx = _find_header_row(raw, ["details", "itc"])
                df = pd.read_excel(io.BytesIO(content), sheet_name='4 Report', header=header_idx)

                for idx, row in df.iterrows():
                    details = str(row.iloc[0] if len(row) > 0 else '').strip()
                    if not details or details.lower() in ("nan", "details", "none"):
                        continue
                    if details.lower().startswith("total"):
                        continue

                    record = {
                        "id": str(uuid.uuid4()),
                        "report_id": report_id,
                        "firm_id": firm_id,
                        "period_key": period_key,
                        "source": "vyapar",
                        "section": "4_itc",
                        "details": details,
                        "igst": float(row.iloc[1] if len(row) > 1 and pd.notna(row.iloc[1]) else 0),
                        "cgst": float(row.iloc[2] if len(row) > 2 and pd.notna(row.iloc[2]) else 0),
                        "sgst": float(row.iloc[3] if len(row) > 3 and pd.notna(row.iloc[3]) else 0),
                        "cess": float(row.iloc[4] if len(row) > 4 and pd.notna(row.iloc[4]) else 0),
                        "created_at": now
                    }
                    gst_data_records.append(record)
            except Exception as e:
                logger.warning(f"Error parsing Vyapar 4 Report: {e}")
    
    # Store GST data records
    if gst_data_records:
        await db.gst_report_data.insert_many(gst_data_records)
    
    stats["total_invoices"] = stats["b2b_invoices"] + stats["b2c_invoices"]
    
    # Save report record
    report_record = {
        "id": report_id,
        "filename": filename,
        "platform": "vyapar",
        "mtr_type": report_type,
        "period_key": period_key,
        "period_month": period_month,
        "period_year": period_year,
        "firm_id": firm_id,
        "firm_name": firm.get("name"),
        "firm_gstin": firm.get("gstin"),
        "stats": stats,
        "created_by": user["id"],
        "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "created_at": now
    }
    await db.mtr_reports.insert_one(report_record)
    
    return {
        "report_id": report_id,
        "filename": filename,
        "platform": "vyapar",
        "report_type": report_type,
        "period": period_key,
        "firm_id": firm_id,
        "stats": stats,
        "records_stored": len(gst_data_records),
        "message": f"Vyapar {report_type.upper()} processed: {stats['total_invoices']} invoices, {stats['hsn_entries']} HSN entries stored"
    }


@api_router.get("/gst/consolidated-report")
async def get_consolidated_gst_report(
    firm_id: str,
    period_month: int,
    period_year: int,
    report_type: str = "gstr1",  # "gstr1" or "gstr3b"
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Get consolidated GST data from all sources (Amazon, Flipkart, Vyapar) for a given period.
    Returns summary data for preview before download.
    """
    period_key = f"{period_year}-{period_month:02d}"
    
    # Get firm details
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0, "id": 1, "name": 1, "gstin": 1})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    # Get Vyapar data
    vyapar_data = await db.gst_report_data.find({
        "firm_id": firm_id,
        "period_key": period_key,
        "source": "vyapar"
    }, {"_id": 0}).to_list(1000)
    
    # Get Amazon/Flipkart enriched dispatch data for this period
    start_date = datetime(period_year, period_month, 1, tzinfo=timezone.utc)
    if period_month == 12:
        end_date = datetime(period_year + 1, 1, 1, tzinfo=timezone.utc)
    else:
        end_date = datetime(period_year, period_month + 1, 1, tzinfo=timezone.utc)
    
    # Get dispatches with GST data from marketplaces
    marketplace_dispatches = await db.dispatches.find({
        "firm_id": firm_id,
        "$or": [
            {"mtr_enriched": True},
            {"flipkart_enriched": True}
        ],
        "created_at": {"$gte": start_date.isoformat(), "$lt": end_date.isoformat()}
    }, {"_id": 0, "id": 1, "dispatch_number": 1, "customer_state": 1, "gst_data": 1, 
        "grand_total": 1, "mtr_enriched": 1, "flipkart_enriched": 1}).to_list(1000)
    
    # Consolidate summaries
    summary = {
        "firm": firm,
        "period": period_key,
        "report_type": report_type,
        "sources": {
            "vyapar": {
                "invoices": len([d for d in vyapar_data if d.get("section") in ["b2b", "b2cs"]]),
                "hsn_entries": len([d for d in vyapar_data if "hsn" in d.get("section", "")]),
                "total_taxable": sum(d.get("taxable_value", 0) for d in vyapar_data if d.get("section") in ["b2b", "b2cs"]),
                "total_igst": sum(d.get("igst", 0) for d in vyapar_data),
                "total_cgst": sum(d.get("cgst", 0) for d in vyapar_data),
                "total_sgst": sum(d.get("sgst", 0) for d in vyapar_data)
            },
            "amazon": {
                "dispatches": len([d for d in marketplace_dispatches if d.get("mtr_enriched")]),
                "total_taxable": sum(d.get("gst_data", {}).get("invoice_amount", 0) for d in marketplace_dispatches if d.get("mtr_enriched")),
                "total_igst": sum(d.get("gst_data", {}).get("igst", 0) for d in marketplace_dispatches if d.get("mtr_enriched")),
                "total_cgst": sum(d.get("gst_data", {}).get("cgst", 0) for d in marketplace_dispatches if d.get("mtr_enriched")),
                "total_sgst": sum(d.get("gst_data", {}).get("sgst", 0) for d in marketplace_dispatches if d.get("mtr_enriched"))
            },
            "flipkart": {
                "dispatches": len([d for d in marketplace_dispatches if d.get("flipkart_enriched")]),
                "total_taxable": sum(d.get("gst_data", {}).get("invoice_amount", 0) for d in marketplace_dispatches if d.get("flipkart_enriched")),
                "total_igst": sum(d.get("gst_data", {}).get("igst", 0) for d in marketplace_dispatches if d.get("flipkart_enriched")),
                "total_cgst": sum(d.get("gst_data", {}).get("cgst", 0) for d in marketplace_dispatches if d.get("flipkart_enriched")),
                "total_sgst": sum(d.get("gst_data", {}).get("sgst", 0) for d in marketplace_dispatches if d.get("flipkart_enriched"))
            }
        },
        "consolidated": {
            "total_taxable": 0,
            "total_igst": 0,
            "total_cgst": 0,
            "total_sgst": 0,
            "total_gst": 0
        }
    }
    
    # Calculate consolidated totals
    for source in ["vyapar", "amazon", "flipkart"]:
        summary["consolidated"]["total_taxable"] += summary["sources"][source].get("total_taxable", 0)
        summary["consolidated"]["total_igst"] += summary["sources"][source].get("total_igst", 0)
        summary["consolidated"]["total_cgst"] += summary["sources"][source].get("total_cgst", 0)
        summary["consolidated"]["total_sgst"] += summary["sources"][source].get("total_sgst", 0)
    
    summary["consolidated"]["total_gst"] = (
        summary["consolidated"]["total_igst"] + 
        summary["consolidated"]["total_cgst"] + 
        summary["consolidated"]["total_sgst"]
    )
    
    return summary


@api_router.get("/gst/download-consolidated")
async def download_consolidated_gst_report(
    firm_id: str,
    period_month: int,
    period_year: int,
    report_type: str = "gstr1",  # "gstr1" or "gstr3b"
    format_type: str = "both",  # "filing", "breakdown", "both"
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Download consolidated GST report (GSTR1 or GSTR3B) combining Amazon, Flipkart, and Vyapar data.
    Returns Excel file with multiple sheets.
    """
    import pandas as pd
    import io
    from fastapi.responses import StreamingResponse
    
    period_key = f"{period_year}-{period_month:02d}"
    month_names = ["", "January", "February", "March", "April", "May", "June", 
                   "July", "August", "September", "October", "November", "December"]
    period_display = f"{month_names[period_month]} {period_year}"
    
    # Get firm details
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    # Get Vyapar data
    vyapar_data = await db.gst_report_data.find({
        "firm_id": firm_id,
        "period_key": period_key,
        "source": "vyapar"
    }, {"_id": 0}).to_list(2000)
    
    # Get marketplace data
    start_date = datetime(period_year, period_month, 1, tzinfo=timezone.utc)
    if period_month == 12:
        end_date = datetime(period_year + 1, 1, 1, tzinfo=timezone.utc)
    else:
        end_date = datetime(period_year, period_month + 1, 1, tzinfo=timezone.utc)
    
    marketplace_dispatches = await db.dispatches.find({
        "firm_id": firm_id,
        "$or": [
            {"mtr_enriched": True},
            {"flipkart_enriched": True}
        ]
    }, {"_id": 0}).to_list(2000)
    
    # Create Excel file
    output = io.BytesIO()
    
    with pd.ExcelWriter(output, engine='openpyxl') as writer:
        # Summary Sheet
        summary_data = []
        summary_data.append(["Consolidated GST Report", "", "", ""])
        summary_data.append(["Firm Name", firm.get("name", ""), "", ""])
        summary_data.append(["GSTIN", firm.get("gstin", ""), "", ""])
        summary_data.append(["Period", period_display, "", ""])
        summary_data.append(["Report Type", report_type.upper(), "", ""])
        summary_data.append(["", "", "", ""])
        summary_data.append(["Source", "Taxable Value", "IGST", "CGST", "SGST", "Total GST"])
        
        # Calculate source-wise totals
        vyapar_taxable = sum(d.get("taxable_value", 0) for d in vyapar_data if d.get("section") in ["b2b", "b2cs", "3.1"])
        vyapar_igst = sum(d.get("igst", 0) for d in vyapar_data)
        vyapar_cgst = sum(d.get("cgst", 0) for d in vyapar_data)
        vyapar_sgst = sum(d.get("sgst", 0) for d in vyapar_data)
        
        amazon_dispatches = [d for d in marketplace_dispatches if d.get("mtr_enriched")]
        amazon_taxable = sum(d.get("gst_data", {}).get("invoice_amount", 0) for d in amazon_dispatches)
        amazon_igst = sum(d.get("gst_data", {}).get("igst", 0) for d in amazon_dispatches)
        amazon_cgst = sum(d.get("gst_data", {}).get("cgst", 0) for d in amazon_dispatches)
        amazon_sgst = sum(d.get("gst_data", {}).get("sgst", 0) for d in amazon_dispatches)
        
        flipkart_dispatches = [d for d in marketplace_dispatches if d.get("flipkart_enriched")]
        flipkart_taxable = sum(d.get("gst_data", {}).get("invoice_amount", 0) for d in flipkart_dispatches)
        flipkart_igst = sum(d.get("gst_data", {}).get("igst", 0) for d in flipkart_dispatches)
        flipkart_cgst = sum(d.get("gst_data", {}).get("cgst", 0) for d in flipkart_dispatches)
        flipkart_sgst = sum(d.get("gst_data", {}).get("sgst", 0) for d in flipkart_dispatches)
        
        summary_data.append(["Vyapar (Offline)", vyapar_taxable, vyapar_igst, vyapar_cgst, vyapar_sgst, vyapar_igst + vyapar_cgst + vyapar_sgst])
        summary_data.append(["Amazon", amazon_taxable, amazon_igst, amazon_cgst, amazon_sgst, amazon_igst + amazon_cgst + amazon_sgst])
        summary_data.append(["Flipkart", flipkart_taxable, flipkart_igst, flipkart_cgst, flipkart_sgst, flipkart_igst + flipkart_cgst + flipkart_sgst])
        summary_data.append(["", "", "", "", "", ""])
        
        total_taxable = vyapar_taxable + amazon_taxable + flipkart_taxable
        total_igst = vyapar_igst + amazon_igst + flipkart_igst
        total_cgst = vyapar_cgst + amazon_cgst + flipkart_cgst
        total_sgst = vyapar_sgst + amazon_sgst + flipkart_sgst
        summary_data.append(["CONSOLIDATED TOTAL", total_taxable, total_igst, total_cgst, total_sgst, total_igst + total_cgst + total_sgst])
        
        summary_df = pd.DataFrame(summary_data)
        summary_df.to_excel(writer, sheet_name='Summary', index=False, header=False)
        
        if report_type == "gstr1":
            # B2B Sheet - Combine all B2B data
            b2b_records = []
            
            # Vyapar B2B
            for d in vyapar_data:
                if d.get("section") == "b2b":
                    b2b_records.append({
                        "Source": "Vyapar",
                        "GSTIN": d.get("gstin", ""),
                        "Receiver Name": d.get("receiver_name", ""),
                        "Invoice Number": d.get("invoice_number", ""),
                        "Invoice Date": d.get("invoice_date", ""),
                        "Invoice Value": d.get("invoice_value", 0),
                        "Place of Supply": d.get("place_of_supply", ""),
                        "Rate": d.get("rate", 0),
                        "Taxable Value": d.get("taxable_value", 0),
                        "IGST": d.get("igst", 0),
                        "CGST": d.get("cgst", 0),
                        "SGST": d.get("sgst", 0)
                    })
            
            # Amazon B2B (from dispatches)
            for d in amazon_dispatches:
                gst = d.get("gst_data", {})
                b2b_records.append({
                    "Source": "Amazon",
                    "GSTIN": "",
                    "Receiver Name": d.get("customer_name", ""),
                    "Invoice Number": gst.get("amazon_invoice_number", d.get("dispatch_number", "")),
                    "Invoice Date": d.get("created_at", "")[:10] if d.get("created_at") else "",
                    "Invoice Value": gst.get("invoice_amount", d.get("grand_total", 0)),
                    "Place of Supply": d.get("customer_state", ""),
                    "Rate": 18,
                    "Taxable Value": gst.get("invoice_amount", 0) - gst.get("igst", 0) - gst.get("cgst", 0) - gst.get("sgst", 0),
                    "IGST": gst.get("igst", 0),
                    "CGST": gst.get("cgst", 0),
                    "SGST": gst.get("sgst", 0)
                })
            
            # Flipkart B2B
            for d in flipkart_dispatches:
                gst = d.get("gst_data", {})
                b2b_records.append({
                    "Source": "Flipkart",
                    "GSTIN": "",
                    "Receiver Name": d.get("customer_name", ""),
                    "Invoice Number": gst.get("flipkart_invoice_number", d.get("dispatch_number", "")),
                    "Invoice Date": d.get("created_at", "")[:10] if d.get("created_at") else "",
                    "Invoice Value": gst.get("invoice_amount", d.get("grand_total", 0)),
                    "Place of Supply": d.get("customer_state", ""),
                    "Rate": 18,
                    "Taxable Value": gst.get("invoice_amount", 0) - gst.get("igst", 0) - gst.get("cgst", 0) - gst.get("sgst", 0),
                    "IGST": gst.get("igst", 0),
                    "CGST": gst.get("cgst", 0),
                    "SGST": gst.get("sgst", 0)
                })
            
            if b2b_records:
                b2b_df = pd.DataFrame(b2b_records)
                b2b_df.to_excel(writer, sheet_name='B2B-All Sources', index=False)
            
            # State-wise Summary
            state_summary = {}
            for record in b2b_records:
                state = record.get("Place of Supply", "Unknown") or "Unknown"
                if state not in state_summary:
                    state_summary[state] = {"taxable": 0, "igst": 0, "cgst": 0, "sgst": 0, "count": 0}
                state_summary[state]["taxable"] += record.get("Taxable Value", 0)
                state_summary[state]["igst"] += record.get("IGST", 0)
                state_summary[state]["cgst"] += record.get("CGST", 0)
                state_summary[state]["sgst"] += record.get("SGST", 0)
                state_summary[state]["count"] += 1
            
            state_data = []
            for state, values in sorted(state_summary.items()):
                state_data.append({
                    "State": state,
                    "No. of Invoices": values["count"],
                    "Taxable Value": values["taxable"],
                    "IGST": values["igst"],
                    "CGST": values["cgst"],
                    "SGST": values["sgst"],
                    "Total Tax": values["igst"] + values["cgst"] + values["sgst"]
                })
            
            if state_data:
                state_df = pd.DataFrame(state_data)
                state_df.to_excel(writer, sheet_name='State-wise Summary', index=False)
            
            # HSN Summary
            hsn_records = []
            for d in vyapar_data:
                if "hsn" in d.get("section", ""):
                    hsn_records.append({
                        "Source": "Vyapar",
                        "HSN Code": d.get("hsn_code", ""),
                        "Description": d.get("description", ""),
                        "UQC": d.get("uqc", ""),
                        "Quantity": d.get("quantity", 0),
                        "Total Value": d.get("total_value", 0),
                        "Taxable Value": d.get("taxable_value", 0),
                        "IGST": d.get("igst", 0),
                        "CGST": d.get("cgst", 0),
                        "SGST": d.get("sgst", 0)
                    })
            
            # Add marketplace HSN from gst_data
            for d in amazon_dispatches + flipkart_dispatches:
                gst = d.get("gst_data", {})
                if gst.get("hsn_code"):
                    hsn_records.append({
                        "Source": "Amazon" if d.get("mtr_enriched") else "Flipkart",
                        "HSN Code": gst.get("hsn_code", ""),
                        "Description": "",
                        "UQC": "NOS",
                        "Quantity": 1,
                        "Total Value": gst.get("invoice_amount", 0),
                        "Taxable Value": gst.get("invoice_amount", 0) - gst.get("total_gst", 0),
                        "IGST": gst.get("igst", 0),
                        "CGST": gst.get("cgst", 0),
                        "SGST": gst.get("sgst", 0)
                    })
            
            if hsn_records:
                hsn_df = pd.DataFrame(hsn_records)
                hsn_df.to_excel(writer, sheet_name='HSN Summary', index=False)
        
        elif report_type == "gstr3b":
            # GSTR3B - 3.1 Outward Supplies
            supplies_data = []
            
            # Vyapar 3.1 data
            for d in vyapar_data:
                if d.get("section") == "3.1":
                    supplies_data.append({
                        "Source": "Vyapar",
                        "Nature of Supplies": d.get("nature_of_supplies", ""),
                        "Taxable Value": d.get("taxable_value", 0),
                        "IGST": d.get("igst", 0),
                        "CGST": d.get("cgst", 0),
                        "SGST": d.get("sgst", 0),
                        "Cess": d.get("cess", 0)
                    })
            
            # Add marketplace supplies
            if amazon_dispatches:
                supplies_data.append({
                    "Source": "Amazon",
                    "Nature of Supplies": "Outward taxable supplies",
                    "Taxable Value": amazon_taxable - (amazon_igst + amazon_cgst + amazon_sgst),
                    "IGST": amazon_igst,
                    "CGST": amazon_cgst,
                    "SGST": amazon_sgst,
                    "Cess": 0
                })
            
            if flipkart_dispatches:
                supplies_data.append({
                    "Source": "Flipkart",
                    "Nature of Supplies": "Outward taxable supplies",
                    "Taxable Value": flipkart_taxable - (flipkart_igst + flipkart_cgst + flipkart_sgst),
                    "IGST": flipkart_igst,
                    "CGST": flipkart_cgst,
                    "SGST": flipkart_sgst,
                    "Cess": 0
                })
            
            if supplies_data:
                supplies_df = pd.DataFrame(supplies_data)
                supplies_df.to_excel(writer, sheet_name='3.1 Outward Supplies', index=False)
            
            # ITC Data from Vyapar
            itc_data = []
            for d in vyapar_data:
                if d.get("section") == "4_itc":
                    itc_data.append({
                        "Details": d.get("details", ""),
                        "IGST": d.get("igst", 0),
                        "CGST": d.get("cgst", 0),
                        "SGST": d.get("sgst", 0),
                        "Cess": d.get("cess", 0)
                    })
            
            if itc_data:
                itc_df = pd.DataFrame(itc_data)
                itc_df.to_excel(writer, sheet_name='4 ITC Claimed', index=False)
    
    output.seek(0)
    
    filename = f"Consolidated_{report_type.upper()}_{firm.get('name', 'Report')}_{period_key}.xlsx"
    
    return StreamingResponse(
        output,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename={filename}"}
    )


@api_router.get("/ecommerce/alerts")
async def get_reconciliation_alerts(
    statement_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get reconciliation alerts - unmatched orders, refunds without CRM match, etc."""
    alerts = []
    
    # Query filter
    query = {}
    if statement_id:
        query["statement_id"] = statement_id
    
    # 1. Unmatched order IDs
    unmatched = await db.payout_transactions.find(
        {**query, "crm_match_status": "unmatched", "transaction_category": "order_payment"},
        {"_id": 0}
    ).to_list(100)
    
    for trans in unmatched:
        alerts.append({
            "type": "unmatched_order",
            "severity": "high",
            "message": f"Order {trans.get('marketplace_order_id')} not found in CRM",
            "transaction_id": trans.get("id"),
            "statement_id": trans.get("statement_id"),
            "order_id": trans.get("marketplace_order_id"),
            "amount": trans.get("total_amount"),
            "date": trans.get("date")
        })
    
    # 2. Refunds without CRM match
    unmatched_refunds = await db.payout_transactions.find(
        {**query, "crm_match_status": "unmatched", "transaction_category": "refund"},
        {"_id": 0}
    ).to_list(100)
    
    for trans in unmatched_refunds:
        alerts.append({
            "type": "unmatched_refund",
            "severity": "high",
            "message": f"Refund for order {trans.get('marketplace_order_id')} not mapped to CRM",
            "transaction_id": trans.get("id"),
            "statement_id": trans.get("statement_id"),
            "order_id": trans.get("marketplace_order_id"),
            "amount": trans.get("total_amount"),
            "date": trans.get("date")
        })
    
    # 3. Unusually high fees (> 25% of sale)
    high_fee_orders = await db.payout_order_summaries.find(
        {
            **query,
            "gross_sale": {"$gt": 0},
            "$expr": {"$gt": [{"$divide": ["$platform_fees", "$gross_sale"]}, 0.25]}
        },
        {"_id": 0}
    ).limit(50).to_list(50)
    
    for order in high_fee_orders:
        fee_pct = (order.get("platform_fees", 0) / order.get("gross_sale", 1)) * 100
        alerts.append({
            "type": "high_fees",
            "severity": "medium",
            "message": f"High platform fees ({fee_pct:.1f}%) on order {order.get('marketplace_order_id')}",
            "order_id": order.get("marketplace_order_id"),
            "amount": order.get("platform_fees"),
            "gross_sale": order.get("gross_sale"),
            "statement_id": order.get("statement_id")
        })
    
    # 4. Orders shipped but not in payout (check last 30 days dispatches)
    if not statement_id:
        # Get recent dispatches with marketplace order IDs
        recent_dispatches = await db.dispatches.find(
            {
                "order_source": {"$in": ["amazon", "flipkart"]},
                "created_at": {"$gte": (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()},
                "status": {"$in": ["dispatched", "delivered"]}
            },
            {"_id": 0, "id": 1, "dispatch_number": 1, "marketplace_order_id": 1, "order_source": 1}
        ).to_list(200)
        
        for dispatch in recent_dispatches:
            if dispatch.get("marketplace_order_id"):
                # Check if this order appears in any payout
                payout_exists = await db.payout_transactions.find_one({
                    "marketplace_order_id": dispatch.get("marketplace_order_id"),
                    "transaction_category": "order_payment"
                })
                
                if not payout_exists:
                    alerts.append({
                        "type": "missing_payout",
                        "severity": "medium",
                        "message": f"Dispatch {dispatch.get('dispatch_number')} shipped but no payout received",
                        "dispatch_id": dispatch.get("id"),
                        "order_id": dispatch.get("marketplace_order_id"),
                        "platform": dispatch.get("order_source")
                    })
    
    return alerts


@api_router.get("/ecommerce/order-reconciliation")
async def get_order_reconciliation(
    statement_id: Optional[str] = None,
    match_status: Optional[str] = None,
    finance_status: Optional[str] = None,
    limit: int = 200,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get order-level reconciliation data"""
    query = {}
    if statement_id:
        query["statement_id"] = statement_id
    if match_status:
        query["crm_match_status"] = match_status
    if finance_status:
        query["finance_status"] = finance_status
    
    orders = await db.payout_order_summaries.find(query, {"_id": 0}).sort("gross_sale", -1).to_list(limit)
    return orders


@api_router.put("/ecommerce/transactions/{transaction_id}/link-crm")
async def link_transaction_to_crm(
    transaction_id: str,
    crm_dispatch_id: Optional[str] = None,
    manual_order_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Manually link a payout transaction to a CRM dispatch and update payment status.
    Can link by dispatch ID or search by manual order ID."""
    transaction = await db.payout_transactions.find_one({"id": transaction_id})
    if not transaction:
        raise HTTPException(status_code=404, detail="Transaction not found")
    
    # If manual_order_id is provided, find the dispatch by order_id or marketplace_order_id
    dispatch = None
    if manual_order_id:
        dispatch = await db.dispatches.find_one({
            "$or": [
                {"order_id": manual_order_id},
                {"marketplace_order_id": manual_order_id}
            ]
        }, {"_id": 0})
        if not dispatch:
            raise HTTPException(status_code=404, detail=f"No dispatch found with order ID: {manual_order_id}")
    elif crm_dispatch_id:
        dispatch = await db.dispatches.find_one({"id": crm_dispatch_id}, {"_id": 0})
        if not dispatch:
            raise HTTPException(status_code=404, detail="Dispatch not found")
    else:
        raise HTTPException(status_code=400, detail="Either crm_dispatch_id or manual_order_id is required")
    
    statement = await db.payout_statements.find_one({"id": transaction.get("statement_id")}, {"_id": 0})
    
    now = datetime.now(timezone.utc).isoformat()
    dispatch_id = dispatch["id"]
    
    # Update transaction
    await db.payout_transactions.update_one(
        {"id": transaction_id},
        {"$set": {
            "crm_match_status": "matched",
            "crm_order_id": dispatch_id,
            "manually_linked": True,
            "linked_by": user["id"],
            "linked_at": now
        }}
    )
    
    # Update order summary if exists
    await db.payout_order_summaries.update_one(
        {
            "statement_id": transaction.get("statement_id"),
            "marketplace_order_id": transaction.get("marketplace_order_id")
        },
        {"$set": {
            "crm_match_status": "matched",
            "crm_order_id": dispatch_id
        }}
    )
    
    # Update dispatch with marketplace info and payment status
    await db.dispatches.update_one(
        {"id": dispatch_id},
        {"$set": {
            "marketplace_order_id": transaction.get("marketplace_order_id"),
            "marketplace_payment_status": "paid_via_marketplace",
            "ecommerce_statement_id": transaction.get("statement_id"),
            "updated_at": now
        }}
    )
    
    # Update sales order payment status to "Paid via Marketplace"
    await db.sales_orders.update_one(
        {"dispatch_id": dispatch_id},
        {"$set": {
            "payment_status": "paid",
            "marketplace_payment_status": "paid_via_marketplace",
            "ecommerce_statement_id": transaction.get("statement_id"),
            "reconciled_at": now,
            "reconciled_by": user["id"],
            "updated_at": now
        }}
    )
    
    # Recalculate statement matched/unmatched counts
    statement_id = transaction.get("statement_id")
    if statement_id:
        # Count matched and unmatched transactions for this statement
        order_types = ["order_payment", "refund", "Order Payment", "Refund", "order_settlement"]
        matched_count = await db.payout_transactions.count_documents({
            "statement_id": statement_id,
            "crm_match_status": "matched",
            "transaction_type": {"$in": order_types}
        })
        unmatched_count = await db.payout_transactions.count_documents({
            "statement_id": statement_id,
            "crm_match_status": {"$ne": "matched"},
            "transaction_type": {"$in": order_types}
        })
        
        # Update statement with new counts
        await db.payout_statements.update_one(
            {"id": statement_id},
            {"$set": {
                "matched_count": matched_count,
                "unmatched_count": unmatched_count,
                "updated_at": now
            }}
        )
    
    return {"success": True, "message": f"Transaction linked to dispatch {dispatch.get('dispatch_number')} - marked as Paid via Marketplace", "matched_count": matched_count, "unmatched_count": unmatched_count}


@api_router.post("/ecommerce/statements/{statement_id}/finalize")
async def finalize_statement_reconciliation(
    statement_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Finalize a reconciled statement and create finance entries:
    - Payment Entry for net payout received
    - Expense entries for platform fees, ads, services
    - Journal entries for TCS/TDS
    """
    statement = await db.payout_statements.find_one({"id": statement_id}, {"_id": 0})
    if not statement:
        raise HTTPException(status_code=404, detail="Statement not found")
    
    if statement.get("finance_status") == "finalized":
        raise HTTPException(status_code=400, detail="Statement already finalized")
    
    now = datetime.now(timezone.utc).isoformat()
    summary = statement.get("summary", {})
    platform = statement.get("platform", "marketplace").title()
    firm_id = statement.get("firm_id")
    firm_name = statement.get("firm_name", "Unknown Firm")
    
    # Create or get marketplace party
    marketplace_party = await db.parties.find_one({"name": {"$regex": f"^{platform}$", "$options": "i"}})
    if not marketplace_party:
        party_id = str(uuid.uuid4())
        marketplace_party = {
            "id": party_id,
            "name": f"{platform} Marketplace",
            "party_type": "marketplace",
            "is_active": True,
            "created_at": now,
            "updated_at": now
        }
        await db.parties.insert_one(marketplace_party)
        marketplace_party.pop("_id", None)
    
    entries_created = []
    
    # 1. Create Payment Entry for Net Payout Received
    net_payout = summary.get("net_payout", 0)
    if net_payout != 0:
        payment_id = str(uuid.uuid4())
        payment_number = f"PMT-{platform[:3].upper()}-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}"
        
        payment_entry = {
            "id": payment_id,
            "payment_number": payment_number,
            "payment_type": "receipt",  # Receipt from marketplace
            "party_id": marketplace_party.get("id"),
            "party_name": marketplace_party.get("name"),
            "firm_id": firm_id,
            "firm_name": firm_name,
            "amount": abs(net_payout),
            "payment_mode": "bank_transfer",
            "payment_date": statement.get("statement_period_end") or now[:10],
            "reference_number": statement.get("statement_number"),
            "description": f"{platform} Payout - {statement.get('statement_number')}",
            "category": "marketplace_payout",
            "ecommerce_statement_id": statement_id,
            "status": "confirmed",
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}",
            "created_at": now,
            "updated_at": now
        }
        await db.payments.insert_one(payment_entry)
        entries_created.append({"type": "payment", "id": payment_id, "amount": net_payout})
    
    # 2. Create Expense Entries for Platform Fees
    platform_fees = summary.get("total_marketplace_fees", 0) or summary.get("total_platform_fees", 0)
    if platform_fees > 0:
        expense_id = str(uuid.uuid4())
        expense_number = f"EXP-{platform[:3].upper()}-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}-FEE"
        
        expense_entry = {
            "id": expense_id,
            "expense_number": expense_number,
            "expense_type": "marketplace_fee",
            "category": "selling_expenses",
            "party_id": marketplace_party.get("id"),
            "party_name": marketplace_party.get("name"),
            "firm_id": firm_id,
            "firm_name": firm_name,
            "amount": platform_fees,
            "expense_date": statement.get("statement_period_end") or now[:10],
            "reference_number": statement.get("statement_number"),
            "description": f"{platform} Platform/Commission Fees - {statement.get('statement_number')}",
            "ecommerce_statement_id": statement_id,
            "gst_applicable": True,
            "status": "confirmed",
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}",
            "created_at": now,
            "updated_at": now
        }
        await db.expenses.insert_one(expense_entry)
        entries_created.append({"type": "expense", "id": expense_id, "category": "platform_fees", "amount": platform_fees})
    
    # 3. Create Expense Entry for Ads
    ad_spend = summary.get("total_ad_spend", 0)
    if ad_spend > 0:
        expense_id = str(uuid.uuid4())
        expense_number = f"EXP-{platform[:3].upper()}-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}-ADS"
        
        expense_entry = {
            "id": expense_id,
            "expense_number": expense_number,
            "expense_type": "advertising",
            "category": "marketing_expenses",
            "party_id": marketplace_party.get("id"),
            "party_name": marketplace_party.get("name"),
            "firm_id": firm_id,
            "firm_name": firm_name,
            "amount": ad_spend,
            "expense_date": statement.get("statement_period_end") or now[:10],
            "reference_number": statement.get("statement_number"),
            "description": f"{platform} Advertising/Ads - {statement.get('statement_number')}",
            "ecommerce_statement_id": statement_id,
            "gst_applicable": True,
            "status": "confirmed",
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}",
            "created_at": now,
            "updated_at": now
        }
        await db.expenses.insert_one(expense_entry)
        entries_created.append({"type": "expense", "id": expense_id, "category": "ads", "amount": ad_spend})
    
    # 4. Create Journal Entry for TCS
    tcs_amount = summary.get("total_tcs", 0)
    if tcs_amount > 0:
        journal_id = str(uuid.uuid4())
        journal_number = f"JV-{platform[:3].upper()}-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}-TCS"
        
        journal_entry = {
            "id": journal_id,
            "journal_number": journal_number,
            "journal_type": "tax_credit",
            "party_id": marketplace_party.get("id"),
            "party_name": marketplace_party.get("name"),
            "firm_id": firm_id,
            "firm_name": firm_name,
            "amount": tcs_amount,
            "journal_date": statement.get("statement_period_end") or now[:10],
            "reference_number": statement.get("statement_number"),
            "description": f"TCS Credit - {platform} - {statement.get('statement_number')}",
            "debit_account": "TCS Receivable",
            "credit_account": f"{platform} Payable",
            "ecommerce_statement_id": statement_id,
            "status": "posted",
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}",
            "created_at": now,
            "updated_at": now
        }
        await db.journal_entries.insert_one(journal_entry)
        entries_created.append({"type": "journal", "id": journal_id, "category": "tcs", "amount": tcs_amount})
    
    # 5. Create Journal Entry for TDS
    tds_amount = summary.get("total_tds", 0)
    if tds_amount > 0:
        journal_id = str(uuid.uuid4())
        journal_number = f"JV-{platform[:3].upper()}-{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S')}-TDS"
        
        journal_entry = {
            "id": journal_id,
            "journal_number": journal_number,
            "journal_type": "tax_credit",
            "party_id": marketplace_party.get("id"),
            "party_name": marketplace_party.get("name"),
            "firm_id": firm_id,
            "firm_name": firm_name,
            "amount": tds_amount,
            "journal_date": statement.get("statement_period_end") or now[:10],
            "reference_number": statement.get("statement_number"),
            "description": f"TDS Credit - {platform} - {statement.get('statement_number')}",
            "debit_account": "TDS Receivable",
            "credit_account": f"{platform} Payable",
            "ecommerce_statement_id": statement_id,
            "status": "posted",
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}",
            "created_at": now,
            "updated_at": now
        }
        await db.journal_entries.insert_one(journal_entry)
        entries_created.append({"type": "journal", "id": journal_id, "category": "tds", "amount": tds_amount})
    
    # Update statement as finalized
    await db.payout_statements.update_one(
        {"id": statement_id},
        {"$set": {
            "finance_status": "finalized",
            "finalized_by": user["id"],
            "finalized_at": now,
            "finance_entries": entries_created,
            "updated_at": now
        }}
    )
    
    return {
        "success": True,
        "message": f"Statement finalized with {len(entries_created)} finance entries created",
        "entries": entries_created,
        "net_payout": net_payout,
        "platform_fees": platform_fees,
        "ad_spend": ad_spend,
        "tcs": tcs_amount,
        "tds": tds_amount
    }


@api_router.get("/journal-entries")
async def list_journal_entries(
    journal_type: Optional[str] = None,  # tax_credit, adjustment, etc.
    firm_id: Optional[str] = None,
    party_id: Optional[str] = None,
    limit: int = 100,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """List journal entries (TCS/TDS credits, adjustments, etc.). Firm-scoped."""
    query = firm_scope_filter(user, firm_id)
    if journal_type:
        query["journal_type"] = journal_type
    if party_id:
        query["party_id"] = party_id

    entries = await db.journal_entries.find(query, {"_id": 0}).sort("created_at", -1).to_list(limit)
    return entries


