@api_router.post("/amazon/fetch-orders/{firm_id}")
async def fetch_amazon_orders(
    firm_id: str,
    order_status: str = "Unshipped,PartiallyShipped,PendingAvailability,Pending,Shipped,Canceled",  # Amazon enum: "Canceled" (one L)
    days_back: int = 30,
    created_after_date: Optional[str] = None,  # Optional: specific date in YYYY-MM-DD format (e.g., "2026-04-01")
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Fetch orders from Amazon SP-API and sync to local database"""
    # Get credentials
    creds = await db.marketplace_credentials.find_one(
        {"firm_id": firm_id, "platform": "amazon", "is_active": True}
    )
    if not creds:
        raise HTTPException(status_code=400, detail="Amazon credentials not configured for this firm")
    
    # Get firm details
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    # Fetch orders from Amazon
    marketplace_id = creds.get("marketplace_id", "A21TJRUUN4KGV")
    uri = "/orders/v0/orders"
    # Get orders - use specific date if provided, else days_back
    if created_after_date:
        # Parse the date string and set to start of day UTC
        try:
            parsed_date = datetime.strptime(created_after_date, "%Y-%m-%d").replace(tzinfo=timezone.utc)
            created_after = parsed_date.strftime('%Y-%m-%dT%H:%M:%SZ')
        except ValueError:
            raise HTTPException(status_code=400, detail="Invalid date format. Use YYYY-MM-DD")
    else:
        created_after = (datetime.now(timezone.utc) - timedelta(days=days_back)).strftime('%Y-%m-%dT%H:%M:%SZ')
    import urllib.parse as _urlparse
    base_query = f"MarketplaceIds={marketplace_id}&OrderStatuses={order_status}&CreatedAfter={created_after}"

    # Amazon's Orders API returns ~100 orders per page plus a NextToken for the
    # rest. Walk every page — without this the sync silently capped at one page.
    all_orders = []
    next_token = None
    page = 0
    MAX_PAGES = 100
    while True:
        page += 1
        if next_token:
            query_string = f"MarketplaceIds={marketplace_id}&NextToken={_urlparse.quote(next_token, safe='')}"
        else:
            query_string = base_query

        # Fetch the page, backing off on 429 (Amazon rate-limits the Orders API hard).
        response = None
        for attempt in range(6):
            try:
                response = await make_amazon_api_request(creds, "GET", uri, query_string)
            except Exception as e:
                raise HTTPException(status_code=500, detail=f"Amazon API error: {str(e)}")
            if response.get("status") == 429:
                await asyncio.sleep(min(60, 3 * (2 ** attempt)))
                continue
            break

        if response["status"] != 200:
            # Page 1 failure is fatal; a later-page failure keeps what we have.
            if page == 1:
                raise HTTPException(status_code=response["status"], detail=f"Amazon API error: {response['data']}")
            logger.warning(f"Amazon sync stopped early at page {page}: {response.get('data')}")
            break

        _payload = response["data"].get("payload", {})
        all_orders.extend(_payload.get("Orders", []))
        next_token = _payload.get("NextToken")
        if not next_token or page >= MAX_PAGES:
            break

    orders = all_orders
    now = datetime.now(timezone.utc).isoformat()

    synced_orders = []
    sku_mapping_required = []

    for order in orders:
        amazon_order_id = order.get("AmazonOrderId")
        
        # Check if order already exists
        existing = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id})
        
        # Determine fulfillment type
        fulfillment_channel = order.get("FulfillmentChannel", "MFN")
        is_easy_ship = order.get("EasyShipShipmentStatus") is not None or fulfillment_channel == "AFN"
        
        # Get order items. Re-sync optimisation: if the order is already stored
        # with its line items, reuse them and skip the (rate-limited) API call.
        _cached_items = existing.get("items") if (existing and existing.get("items")) else None
        items_uri = f"/orders/v0/orders/{amazon_order_id}/orderItems"
        items_response = {"status": 0} if _cached_items else await make_amazon_api_request(creds, "GET", items_uri)
        order_items = list(_cached_items) if _cached_items else []

        if items_response["status"] == 200:
            items = items_response["data"].get("payload", {}).get("OrderItems", [])
            for item in items:
                amazon_sku = item.get("SellerSKU")
                
                # Try to find master SKU mapping
                mapping = await db.amazon_sku_mappings.find_one(
                    {"firm_id": firm_id, "amazon_sku": amazon_sku}
                )
                master_sku = None
                master_sku_id = None
                
                if mapping:
                    master_sku_id = mapping.get("master_sku_id")
                    master_sku_doc = await db.master_skus.find_one({"id": master_sku_id}, {"_id": 0})
                    if master_sku_doc:
                        master_sku = master_sku_doc.get("sku_code")
                else:
                    # Try to match by SKU code directly or by alias with platform = Amazon
                    master_sku_doc = await db.master_skus.find_one(
                        {"$or": [
                            {"sku_code": amazon_sku},
                            {"aliases": {"$elemMatch": {"alias_code": amazon_sku, "platform": {"$regex": "^amazon$", "$options": "i"}}}}
                        ]},
                        {"_id": 0}
                    )
                    if master_sku_doc:
                        master_sku = master_sku_doc.get("sku_code")
                        master_sku_id = master_sku_doc.get("id")
                        
                        # Auto-create SKU mapping if found via alias
                        existing_mapping = await db.amazon_sku_mappings.find_one({
                            "firm_id": firm_id,
                            "amazon_sku": amazon_sku
                        })
                        if not existing_mapping:
                            await db.amazon_sku_mappings.insert_one({
                                "id": str(uuid.uuid4()),
                                "firm_id": firm_id,
                                "amazon_sku": amazon_sku,
                                "master_sku_id": master_sku_id,
                                "master_sku_name": master_sku_doc.get("name"),
                                "sku_code": master_sku,
                                "auto_mapped": True,
                                "mapped_via": "alias",
                                "created_at": datetime.now(timezone.utc).isoformat()
                            })
                    else:
                        # Add to mapping required list
                        if amazon_sku not in [s["amazon_sku"] for s in sku_mapping_required]:
                            sku_mapping_required.append({
                                "amazon_sku": amazon_sku,
                                "asin": item.get("ASIN"),
                                "title": item.get("Title", "")[:100]
                            })
                
                order_items.append({
                    "amazon_sku": amazon_sku,
                    "asin": item.get("ASIN"),
                    "title": item.get("Title"),
                    "quantity": item.get("QuantityOrdered", 1),
                    "item_price": float(item.get("ItemPrice", {}).get("Amount", 0)),
                    "master_sku_id": master_sku_id,
                    "master_sku_code": master_sku
                })
        
        # Get shipping address
        shipping_address = order.get("ShippingAddress", {})
        
        order_doc = {
            "id": existing["id"] if existing else str(uuid.uuid4()),
            "firm_id": firm_id,
            "firm_name": firm.get("name"),
            "amazon_order_id": amazon_order_id,
            "order_status": order.get("OrderStatus"),  # Amazon status: Unshipped, Shipped, PendingAvailability, etc.
            "fulfillment_channel": fulfillment_channel,
            "is_easy_ship": is_easy_ship,
            "easy_ship_status": order.get("EasyShipShipmentStatus"),
            "purchase_date": order.get("PurchaseDate"),
            "last_update_date": order.get("LastUpdateDate"),
            "order_total": float(order.get("OrderTotal", {}).get("Amount", 0)),
            "currency": order.get("OrderTotal", {}).get("CurrencyCode", "INR"),
            "items": order_items,
            "buyer_name": shipping_address.get("Name"),
            "address_line1": shipping_address.get("AddressLine1"),
            "address_line2": shipping_address.get("AddressLine2"),
            "city": shipping_address.get("City"),
            "state": shipping_address.get("StateOrRegion"),
            "postal_code": shipping_address.get("PostalCode"),
            "country": shipping_address.get("CountryCode", "IN"),
            "phone": shipping_address.get("Phone"),
            # CRM tracking - update status if Amazon cancelled, but preserve user actions
            "crm_status": (
                "cancelled" if order.get("OrderStatus") in ("Canceled", "Cancelled") else  # Amazon enum is "Canceled"
                existing.get("crm_status") if existing and existing.get("crm_status") in ["dispatched", "tracking_added", "in_pending_fulfillment"] else  # Preserve user actions
                "amazon_shipped" if order.get("OrderStatus") == "Shipped" else "pending"
            ),
            "amazon_status": order.get("OrderStatus"),  # Track Amazon's status
            "tracking_number": existing.get("tracking_number") if existing else None,
            "carrier_code": existing.get("carrier_code") if existing else None,
            "dispatch_id": existing.get("dispatch_id") if existing else None,
            "synced_at": now,
            "updated_at": now
        }
        
        if not existing:
            order_doc["created_at"] = now
        
        await db.amazon_orders.update_one(
            {"amazon_order_id": amazon_order_id},
            {"$set": order_doc},
            upsert=True
        )
        
        synced_orders.append({
            "amazon_order_id": amazon_order_id,
            "status": order.get("OrderStatus"),
            "total": order_doc["order_total"],
            "is_easy_ship": is_easy_ship,
            "items_count": len(order_items)
        })
    
    return {
        "success": True,
        "orders_synced": len(synced_orders),
        "orders": synced_orders,
        "sku_mapping_required": sku_mapping_required,
        "message": f"Synced {len(synced_orders)} orders from Amazon"
    }


@api_router.get("/amazon/orders/{firm_id}")
async def list_amazon_orders(
    firm_id: str,
    status: Optional[str] = None,  # pending, tracking_added, dispatched, amazon_shipped
    fulfillment_type: Optional[str] = None,  # mfn, easy_ship
    limit: int = 500,
    user: dict = Depends(require_roles(["admin", "accountant", "dispatcher"]))
):
    """List synced Amazon orders for a firm"""
    query = {"firm_id": firm_id}
    
    if status:
        query["crm_status"] = status
    
    if fulfillment_type == "mfn":
        query["is_easy_ship"] = False
    elif fulfillment_type == "easy_ship":
        query["is_easy_ship"] = True
    
    orders = await db.amazon_orders.find(query, {"_id": 0}).sort("purchase_date", -1).to_list(limit)
    
    # Get stats - include amazon_shipped for historical orders, cancelled for cancelled
    total = await db.amazon_orders.count_documents({"firm_id": firm_id})
    pending = await db.amazon_orders.count_documents({"firm_id": firm_id, "crm_status": "pending"})
    details_captured = await db.amazon_orders.count_documents({"firm_id": firm_id, "crm_status": "details_captured"})
    tracking_added = await db.amazon_orders.count_documents({"firm_id": firm_id, "crm_status": "tracking_added"})
    dispatched = await db.amazon_orders.count_documents({"firm_id": firm_id, "crm_status": "dispatched"})
    amazon_shipped = await db.amazon_orders.count_documents({"firm_id": firm_id, "crm_status": "amazon_shipped"})
    cancelled = await db.amazon_orders.count_documents({"firm_id": firm_id, "crm_status": "cancelled"})
    mfn_pending = await db.amazon_orders.count_documents({"firm_id": firm_id, "crm_status": "pending", "is_easy_ship": False})
    easy_ship_pending = await db.amazon_orders.count_documents({"firm_id": firm_id, "crm_status": "pending", "is_easy_ship": True})

    return {
        "orders": orders,
        "stats": {
            "total": total,
            "pending": pending,
            "details_captured": details_captured,
            "tracking_added": tracking_added,
            "dispatched": dispatched,
            "amazon_shipped": amazon_shipped,
            "cancelled": cancelled,
            "mfn_pending": mfn_pending,
            "easy_ship_pending": easy_ship_pending,
        }
    }


class AmazonOrderUpdate(BaseModel):
    """Request model for updating Amazon order data"""
    buyer_name: Optional[str] = None
    phone: Optional[str] = None
    address_line1: Optional[str] = None
    address_line2: Optional[str] = None
    city: Optional[str] = None
    state: Optional[str] = None
    pincode: Optional[str] = None
    carrier_code: Optional[str] = None
    tracking_number: Optional[str] = None
    crm_status: Optional[str] = None  # pending, tracking_added, dispatched, amazon_shipped, cancelled


@api_router.patch("/amazon/orders/{amazon_order_id}")
async def update_amazon_order(
    amazon_order_id: str,
    update_data: AmazonOrderUpdate,
    user: dict = Depends(require_roles(["admin", "accountant", "dispatcher"]))
):
    """
    Update Amazon order data.
    
    Useful for:
    - Correcting customer details (name, phone, address)
    - Adding tracking information manually
    - Updating CRM status
    
    Fields that can be updated:
    - buyer_name, phone, address_line1, address_line2, city, state, pincode
    - carrier_code, tracking_number
    - crm_status (pending, tracking_added, dispatched, amazon_shipped, cancelled)
    """
    # Find the order
    order = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id})
    if not order:
        raise HTTPException(status_code=404, detail=f"Amazon order '{amazon_order_id}' not found")
    
    # Build update document with only provided fields
    update_doc = {}
    
    if update_data.buyer_name is not None:
        update_doc["buyer_name"] = update_data.buyer_name
    
    if update_data.phone is not None:
        update_doc["phone"] = update_data.phone
    
    if update_data.address_line1 is not None:
        update_doc["address_line1"] = update_data.address_line1
        # Also update combined address field if it exists
        addr2 = update_data.address_line2 or order.get("address_line2", "")
        city = update_data.city or order.get("city", "")
        state = update_data.state or order.get("state", "")
        pincode = update_data.pincode or order.get("pincode", "")
        update_doc["shipping_address"] = f"{update_data.address_line1}, {addr2}, {city}, {state} - {pincode}".strip(", -")
    
    if update_data.address_line2 is not None:
        update_doc["address_line2"] = update_data.address_line2
    
    if update_data.city is not None:
        update_doc["city"] = update_data.city
    
    if update_data.state is not None:
        update_doc["state"] = update_data.state
    
    if update_data.pincode is not None:
        update_doc["pincode"] = update_data.pincode
    
    if update_data.carrier_code is not None:
        update_doc["carrier_code"] = update_data.carrier_code
    
    if update_data.tracking_number is not None:
        update_doc["tracking_number"] = update_data.tracking_number
        update_doc["awb_number"] = update_data.tracking_number  # Also set awb_number for compatibility
        # Auto-update status to tracking_added if currently pending
        if order.get("crm_status") == "pending" and update_data.crm_status is None:
            update_doc["crm_status"] = "tracking_added"
    
    if update_data.crm_status is not None:
        valid_statuses = ["pending", "tracking_added", "dispatched", "amazon_shipped", "cancelled"]
        if update_data.crm_status not in valid_statuses:
            raise HTTPException(
                status_code=400, 
                detail=f"Invalid crm_status. Must be one of: {', '.join(valid_statuses)}"
            )
        update_doc["crm_status"] = update_data.crm_status
    
    if not update_doc:
        raise HTTPException(status_code=400, detail="No fields to update")
    
    # Add metadata
    update_doc["updated_at"] = datetime.now(timezone.utc).isoformat()
    update_doc["updated_by"] = user["id"]
    
    # Perform update
    result = await db.amazon_orders.update_one(
        {"amazon_order_id": amazon_order_id},
        {"$set": update_doc}
    )
    
    if result.modified_count == 0:
        return {
            "success": True,
            "message": "No changes made (values may be the same)",
            "amazon_order_id": amazon_order_id
        }
    
    # Fetch updated order
    updated_order = await db.amazon_orders.find_one(
        {"amazon_order_id": amazon_order_id},
        {"_id": 0}
    )
    
    return {
        "success": True,
        "message": "Order updated successfully",
        "amazon_order_id": amazon_order_id,
        "updated_fields": list(update_doc.keys()),
        "order": updated_order
    }


@api_router.post("/amazon/migrate-cancelled-orders")
async def migrate_cancelled_orders(
    firm_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin"]))
):
    """
    One-time migration: Update existing orders with Amazon status 'Cancelled' 
    to have crm_status 'cancelled' so they appear in the Cancelled tab.
    """
    query = {"amazon_status": "Cancelled", "crm_status": {"$nin": ["cancelled", "dispatched"]}}
    if firm_id:
        query["firm_id"] = firm_id
    
    # Find orders that need migration
    orders_to_migrate = await db.amazon_orders.find(query, {"amazon_order_id": 1, "crm_status": 1}).to_list(1000)
    
    if not orders_to_migrate:
        return {"message": "No orders need migration", "migrated_count": 0}
    
    # Update all matching orders
    result = await db.amazon_orders.update_many(
        query,
        {"$set": {"crm_status": "cancelled", "updated_at": datetime.now(timezone.utc).isoformat()}}
    )
    
    return {
        "message": f"Migrated {result.modified_count} orders to cancelled status",
        "migrated_count": result.modified_count,
        "order_ids": [o["amazon_order_id"] for o in orders_to_migrate[:20]]  # Show first 20
    }


@api_router.post("/amazon/orders/{amazon_order_id}/mark-cancelled")
async def mark_amazon_order_cancelled(
    amazon_order_id: str,
    reason: str = Body(None, embed=True),
    user: dict = Depends(require_roles(["admin", "dispatcher"]))
):
    """
    Manually mark an Amazon order as cancelled.
    This moves the order from MFN/EasyShip queue to the Cancelled tab.
    """
    order = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    if order.get("crm_status") == "dispatched":
        raise HTTPException(status_code=400, detail="Cannot cancel: order already dispatched")
    
    if order.get("crm_status") == "cancelled":
        return {"message": "Order already cancelled", "order_id": amazon_order_id}
    
    now = datetime.now(timezone.utc).isoformat()
    await db.amazon_orders.update_one(
        {"amazon_order_id": amazon_order_id},
        {"$set": {
            "crm_status": "cancelled",
            "cancelled_at": now,
            "cancelled_by": user["id"],
            "cancelled_reason": reason or "Manually cancelled by user",
            "updated_at": now
        }}
    )
    
    return {
        "message": "Order marked as cancelled",
        "order_id": amazon_order_id
    }


@api_router.post("/amazon/orders/{amazon_order_id}/restore")
async def restore_amazon_order(
    amazon_order_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """
    Restore a cancelled order back to pending status.
    """
    order = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    if order.get("crm_status") != "cancelled":
        raise HTTPException(status_code=400, detail="Order is not cancelled")
    
    now = datetime.now(timezone.utc).isoformat()
    await db.amazon_orders.update_one(
        {"amazon_order_id": amazon_order_id},
        {"$set": {
            "crm_status": "pending",
            "restored_at": now,
            "restored_by": user["id"],
            "updated_at": now
        },
        "$unset": {
            "cancelled_at": "",
            "cancelled_by": "",
            "cancelled_reason": ""
        }}
    )
    
    return {
        "message": "Order restored to pending",
        "order_id": amazon_order_id
    }


@api_router.get("/amazon/order-lookup")
async def lookup_amazon_order(
    order_id: str,
    firm_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant", "dispatcher"]))
):
    """Lookup Amazon order by order_id or amazon_order_id to get customer details"""
    query = {
        "$or": [
            {"amazon_order_id": order_id},
            {"amazon_order_id": {"$regex": f".*{order_id}.*", "$options": "i"}}
        ]
    }
    if firm_id:
        query["firm_id"] = firm_id
    
    order = await db.amazon_orders.find_one(query, {"_id": 0})
    
    if not order:
        return {"found": False, "message": "Order not found in Amazon orders"}
    
    return {
        "found": True,
        "order": {
            "amazon_order_id": order.get("amazon_order_id"),
            "buyer_name": order.get("buyer_name"),
            "phone": order.get("phone"),
            "address_line1": order.get("address_line1"),
            "address_line2": order.get("address_line2"),
            "city": order.get("city"),
            "state": order.get("state"),
            "postal_code": order.get("postal_code"),
            "is_easy_ship": order.get("is_easy_ship", False),
            "crm_status": order.get("crm_status"),
            "items": order.get("items", [])
        }
    }


@api_router.post("/amazon/sku-mapping")
async def create_sku_mapping(
    firm_id: str,
    mapping: AmazonSKUMapping,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Map an Amazon SKU to a Master SKU"""
    # Verify master SKU exists
    master_sku = await db.master_skus.find_one({"id": mapping.master_sku_id}, {"_id": 0})
    if not master_sku:
        raise HTTPException(status_code=404, detail="Master SKU not found")
    
    now = datetime.now(timezone.utc).isoformat()
    
    mapping_doc = {
        "id": str(uuid.uuid4()),
        "firm_id": firm_id,
        "amazon_sku": mapping.amazon_sku,
        "master_sku_id": mapping.master_sku_id,
        "master_sku_code": master_sku.get("sku_code"),
        "master_sku_name": master_sku.get("name"),
        "created_at": now,
        "created_by": user["id"]
    }
    
    await db.amazon_sku_mappings.update_one(
        {"firm_id": firm_id, "amazon_sku": mapping.amazon_sku},
        {"$set": mapping_doc},
        upsert=True
    )
    
    # Update any existing orders with this SKU
    await db.amazon_orders.update_many(
        {"firm_id": firm_id, "items.amazon_sku": mapping.amazon_sku},
        {"$set": {
            "items.$[elem].master_sku_id": mapping.master_sku_id,
            "items.$[elem].master_sku_code": master_sku.get("sku_code")
        }},
        array_filters=[{"elem.amazon_sku": mapping.amazon_sku}]
    )
    
    return {"success": True, "message": f"Mapped {mapping.amazon_sku} to {master_sku.get('sku_code')}"}


@api_router.get("/amazon/sku-mappings/{firm_id}")
async def list_sku_mappings(
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """List all SKU mappings for a firm"""
    mappings = await db.amazon_sku_mappings.find({"firm_id": firm_id}, {"_id": 0}).to_list(500)
    return mappings


@api_router.post("/amazon/refresh-order-items/{amazon_order_id}")
async def refresh_amazon_order_items(
    amazon_order_id: str,
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Refresh order items from Amazon API for a single order - uses shared SKU resolver"""
    # Get the order
    order = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id, "firm_id": firm_id})
    if not order:
        raise HTTPException(status_code=404, detail="Amazon order not found")
    
    # Get credentials
    creds = await db.marketplace_credentials.find_one(
        {"firm_id": firm_id, "platform": "amazon", "is_active": True}
    )
    if not creds:
        raise HTTPException(status_code=400, detail="Amazon credentials not configured for this firm")
    
    # Fetch order items from Amazon
    items_uri = f"/orders/v0/orders/{amazon_order_id}/orderItems"
    try:
        items_response = await make_amazon_api_request(creds, "GET", items_uri)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Amazon API error: {str(e)}")
    
    if items_response["status"] != 200:
        raise HTTPException(status_code=items_response["status"], detail=f"Amazon API error: {items_response['data']}")
    
    raw_items = items_response["data"].get("payload", {}).get("OrderItems", [])
    
    # Transform Amazon API items to our format
    amazon_items = []
    for item in raw_items:
        amazon_items.append({
            "amazon_sku": item.get("SellerSKU"),
            "seller_sku": item.get("SellerSKU"),
            "asin": item.get("ASIN"),
            "title": item.get("Title"),
            "quantity": item.get("QuantityOrdered", 1),
            "item_price": float(item.get("ItemPrice", {}).get("Amount", 0)) if item.get("ItemPrice") else 0,
            "order_item_id": item.get("OrderItemId")
        })
    
    # Use shared resolver
    temp_order = {"items": amazon_items}
    resolution = await resolve_amazon_order_items_to_master_skus(temp_order, firm_id, db, auto_persist_mapping=True)
    
    # Update the order with resolved items
    now = datetime.now(timezone.utc).isoformat()
    await db.amazon_orders.update_one(
        {"amazon_order_id": amazon_order_id},
        {"$set": {
            "items": resolution["items"],
            "items_refreshed_at": now,
            "total_quantity": resolution["total_quantity"],
            "all_skus_mapped": resolution["all_mapped"],
            "updated_at": now
        }}
    )
    
    return {
        "success": True,
        "items_count": len(resolution["items"]),
        "items": resolution["items"],
        "sku_mapping_required": resolution["unmapped_skus"],
        "all_mapped": resolution["all_mapped"],
        "total_quantity": resolution["total_quantity"],
        "mapping_audit": resolution["mapping_audit"],
        "message": f"Refreshed {len(resolution['items'])} items for order {amazon_order_id}"
    }




@api_router.post("/amazon/save-customer-details")
async def save_amazon_customer_details(
    details: AmazonCustomerDetails,
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant", "dispatcher"]))
):
    """
    Step 1 of the two-step Amazon dispatch flow: save PII against the Amazon order.
    The order stays on the Amazon Orders page in the new 'Awaiting Tracking' tab
    (crm_status = 'details_captured') until tracking is added by /amazon/update-tracking.
    """
    order = await db.amazon_orders.find_one({"amazon_order_id": details.amazon_order_id, "firm_id": firm_id})
    if not order:
        raise HTTPException(status_code=404, detail="Amazon order not found")

    current_status = order.get("crm_status")
    # Allow capture on a fresh order, on an already-captured one (edit), or on a history order
    if current_status not in ("pending", "details_captured", "amazon_shipped"):
        raise HTTPException(
            status_code=400,
            detail=f"Cannot capture customer details for an order in status '{current_status}'"
        )

    # SKU mapping gate: same rule as Add Tracking — block if anything is unmapped
    unmapped_skus = []
    for item in order.get("items", []):
        amazon_sku = item.get("amazon_sku") or item.get("seller_sku")
        if amazon_sku:
            mapping = await db.amazon_sku_mappings.find_one(
                {"firm_id": firm_id, "amazon_sku": amazon_sku}
            )
            if not mapping:
                unmapped_skus.append(amazon_sku)
    if unmapped_skus:
        raise HTTPException(
            status_code=400,
            detail=f"Cannot save customer details: SKUs not mapped to Master SKUs: {', '.join(unmapped_skus)}. Please map all SKUs first."
        )

    first = (details.customer_first_name or "").strip()
    last = (details.customer_last_name or "").strip()
    if not first:
        raise HTTPException(status_code=400, detail="Customer first name is required")
    if not details.phone or len(details.phone) != 10 or not details.phone.isdigit():
        raise HTTPException(status_code=400, detail="Phone must be a 10-digit number")
    if not details.city.strip() or not details.state.strip() or not details.pincode.strip():
        raise HTTPException(status_code=400, detail="City, state, and pincode are required")

    full_name = f"{first} {last}".strip()
    now = datetime.now(timezone.utc).isoformat()

    update_doc = {
        "customer_first_name_manual": first,
        "customer_last_name_manual": last,
        "customer_name_manual": full_name,
        "phone_manual": details.phone,
        "address_manual": (details.address or "").strip(),
        "city_manual": details.city.strip(),
        "state_manual": details.state.strip(),
        "pincode_manual": details.pincode.strip(),
        "details_captured_at": now,
        "details_captured_by": user["id"],
        "updated_at": now,
    }
    # Don't downgrade a history order's status — it can re-enter the tracking dialog from its own tab
    if current_status == "pending":
        update_doc["crm_status"] = "details_captured"

    await db.amazon_orders.update_one(
        {"amazon_order_id": details.amazon_order_id},
        {"$set": update_doc}
    )

    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "amazon_customer_details_saved",
        "entity_type": "amazon_order",
        "entity_id": details.amazon_order_id,
        "entity_name": details.amazon_order_id,
        "performed_by": user["id"],
        "performed_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "details": {"customer_name": full_name, "city": details.city, "state": details.state},
        "timestamp": now,
    })

    return {
        "success": True,
        "message": "Customer details saved. Order is awaiting tracking.",
        "amazon_order_id": details.amazon_order_id,
        "crm_status": update_doc.get("crm_status", current_status),
    }


@api_router.post("/amazon/update-tracking")
async def update_amazon_tracking(
    tracking: AmazonTrackingUpdate,
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant", "dispatcher"]))
):
    """Update tracking number on Amazon and mark order for dispatch"""
    # Get the order
    order = await db.amazon_orders.find_one({"amazon_order_id": tracking.amazon_order_id, "firm_id": firm_id})
    if not order:
        raise HTTPException(status_code=404, detail="Amazon order not found")
    
    is_easy_ship = order.get("is_easy_ship", False)
    is_history_order = tracking.is_history_order or order.get("crm_status") == "amazon_shipped"
    has_captured_details = bool(order.get("phone_manual") and order.get("city_manual"))

    # Check if all SKUs are mapped before allowing tracking
    unmapped_skus = []
    items = order.get("items", [])
    for item in items:
        amazon_sku = item.get("amazon_sku") or item.get("seller_sku")
        if amazon_sku:
            mapping = await db.amazon_sku_mappings.find_one({
                "firm_id": firm_id,
                "amazon_sku": amazon_sku
            })
            if not mapping:
                unmapped_skus.append(amazon_sku)

    if unmapped_skus:
        raise HTTPException(
            status_code=400,
            detail=f"Cannot add tracking: SKUs not mapped to Master SKUs: {', '.join(unmapped_skus)}. Please map all SKUs first."
        )

    # MFN orders and History orders require customer details.
    # If PII was already captured via /amazon/save-customer-details, fall back to the saved fields.
    requires_customer_details = not is_easy_ship or is_history_order
    if requires_customer_details and not has_captured_details:
        if not tracking.customer_name or not tracking.phone:
            raise HTTPException(status_code=400, detail="Customer name and phone are required")
        if not tracking.city or not tracking.state or not tracking.pincode:
            raise HTTPException(status_code=400, detail="City, state, and pincode are required")
        if len(tracking.phone) != 10 or not tracking.phone.isdigit():
            raise HTTPException(status_code=400, detail="Phone must be a 10-digit number")
    elif requires_customer_details and has_captured_details:
        # Use saved PII unless the caller explicitly re-supplied a field
        tracking.customer_name = tracking.customer_name or order.get("customer_name_manual")
        tracking.phone = tracking.phone or order.get("phone_manual")
        tracking.address = tracking.address or order.get("address_manual")
        tracking.city = tracking.city or order.get("city_manual")
        tracking.state = tracking.state or order.get("state_manual")
        tracking.pincode = tracking.pincode or order.get("pincode_manual")
    
    # Get credentials
    creds = await db.marketplace_credentials.find_one(
        {"firm_id": firm_id, "platform": "amazon", "is_active": True}
    )
    if not creds:
        raise HTTPException(status_code=400, detail="Amazon credentials not configured")
    
    # Map carrier code to Amazon carrier name
    carrier_mapping = {
        "bluedart": "Blue Dart",
        "delhivery": "Delhivery",
        "dtdc": "DTDC",
        "fedex": "FedEx",
        "xpressbees": "XpressBees",
        "ecom_express": "Ecom Express",
        "shadowfax": "Shadowfax",
        "professional_couriers": "Professional Couriers",
        "gati": "Gati",
        "other": "Other"
    }
    
    amazon_carrier = carrier_mapping.get(tracking.carrier_code.lower().replace(" ", "_"), tracking.carrier_code)
    
    # Update tracking on Amazon
    # Note: Amazon requires specific API for shipment confirmation
    # For now, we'll mark the order locally and the actual Amazon update would need
    # to use the Feeds API or MWS Shipment Confirmation
    
    now = datetime.now(timezone.utc).isoformat()
    
    # Update local order with customer details for MFN and history orders
    update_data = {
        "tracking_number": tracking.tracking_number,
        "carrier_code": tracking.carrier_code,
        "crm_status": "tracking_added",
        "tracking_updated_at": now,
        "tracking_updated_by": user["id"],
        "updated_at": now
    }
    
    # Mark as processed from history if it was an amazon_shipped order
    if is_history_order:
        update_data["processed_from_history"] = True
    
    # For MFN and history orders, store the manually entered customer details
    if requires_customer_details:
        update_data["customer_name_manual"] = tracking.customer_name
        update_data["phone_manual"] = tracking.phone
        update_data["address_manual"] = tracking.address
        update_data["city_manual"] = tracking.city
        update_data["state_manual"] = tracking.state
        update_data["pincode_manual"] = tracking.pincode
    
    await db.amazon_orders.update_one(
        {"amazon_order_id": tracking.amazon_order_id},
        {"$set": update_data}
    )
    
    # Determine customer details - use manual entry for MFN/History, Amazon data for Easy Ship
    if requires_customer_details:
        customer_name = tracking.customer_name
        phone = tracking.phone
        address = tracking.address or ""
        city = tracking.city
        state = tracking.state
        pincode = tracking.pincode
    else:
        # For Easy Ship orders, get data from Amazon order (check shipping_address too)
        shipping = order.get("shipping_address") or {}
        customer_name = order.get("buyer_name") or shipping.get("name")
        phone = order.get("buyer_phone") or shipping.get("phone") or order.get("phone")
        address = shipping.get("address_line1") or f"{order.get('address_line1', '')} {order.get('address_line2', '')}".strip()
        city = shipping.get("city") or order.get("city")
        state = shipping.get("state") or order.get("state")
        pincode = shipping.get("postal_code") or order.get("postal_code")
    
    # Get firm details
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0})
    firm_name = firm.get("name") if firm else order.get("firm_name")
    
    # Enrich items with master_sku_id from mappings
    enriched_items = []
    for item in order.get("items", []):
        amazon_sku = item.get("amazon_sku") or item.get("seller_sku")
        mapping = await db.amazon_sku_mappings.find_one({
            "firm_id": firm_id,
            "amazon_sku": amazon_sku
        })
        enriched_item = {**item}
        if mapping:
            enriched_item["master_sku_id"] = mapping.get("master_sku_id")
            enriched_item["master_sku_name"] = mapping.get("master_sku_name")
            enriched_item["sku_code"] = mapping.get("sku_code")
        enriched_items.append(enriched_item)
    
    # Get primary SKU for fulfillment entry (first item or main item)
    primary_item = enriched_items[0] if enriched_items else {}
    
    # Add to pending fulfillment queue
    fulfillment_doc = {
        "id": str(uuid.uuid4()),
        "type": "amazon_order",
        "order_source": "amazon",
        "amazon_order_id": tracking.amazon_order_id,
        "order_id": tracking.amazon_order_id,  # Also store as order_id for dispatch flow
        "is_easy_ship": is_easy_ship,
        "is_history_order": is_history_order,  # Track if this came from Amazon History reconciliation
        "firm_id": firm_id,
        "firm_name": firm_name,
        "customer_name": customer_name,
        "customer_phone": phone,
        "phone": phone,
        "address": address,
        "city": city,
        "state": state,
        "pincode": pincode,
        # Primary SKU for inventory tracking
        "master_sku_id": primary_item.get("master_sku_id"),
        "master_sku_name": primary_item.get("master_sku_name"),
        "sku_code": primary_item.get("sku_code"),
        "quantity": primary_item.get("quantity", 1),
        # All items for multi-item orders
        "items": enriched_items,
        "order_total": order.get("order_total"),
        "invoice_value": order.get("order_total"),  # canonical monetary field
        "tracking_number": tracking.tracking_number,
        "tracking_id": tracking.tracking_number,  # Alias for dispatch flow
        "carrier_code": tracking.carrier_code,
        "carrier_name": amazon_carrier,
        "status": "pending_dispatch",  # Status for pending fulfillment queue
        "created_at": now,
        "created_by": user["id"]
    }
    
    await db.pending_fulfillment.insert_one(fulfillment_doc)
    
    return {
        "success": True,
        "message": f"Tracking {tracking.tracking_number} added. Order moved to Pending Dispatch queue.",
        "fulfillment_id": fulfillment_doc["id"]
    }


# ==================== AMAZON PII AUTOSCRAPE (via Browser Agent) ====================
# Drives the existing singleton AmazonBrowserAgent to scrape buyer PII off the
# Seller Central order detail page and writes it onto amazon_orders.*_manual.
# Bulk jobs run as background asyncio tasks; progress is exposed via REST poll
# and broadcast on the existing /api/ws/browser-agent WebSocket.

_amazon_scrape_jobs: Dict[str, Dict[str, Any]] = {}  # firm_id -> job state


def _normalize_scraped_pii(scraped: dict) -> dict:
    """Coerce a raw scrape into the *_manual update shape, applying the missing-phone fallback."""
    raw_phone = (scraped.get("phone") or "").strip()
    digits_only = "".join(c for c in raw_phone if c.isdigit())
    if len(digits_only) == 10 and digits_only[0] in "6789":
        phone = digits_only
        needs_phone_review = False
    else:
        phone = "0000000000"
        needs_phone_review = True

    first = (scraped.get("first_name") or "").strip() or "Amazon"
    last = (scraped.get("last_name") or "").strip() or "Customer"
    full = f"{first} {last}".strip()

    tracking_id = (scraped.get("tracking_id") or "").strip()
    carrier = (scraped.get("carrier") or "").strip()

    out = {
        "customer_first_name_manual": first,
        "customer_last_name_manual": last,
        "customer_name_manual": full,
        "phone_manual": phone,
        "address_manual": (scraped.get("address") or "").strip(),
        "city_manual": (scraped.get("city") or "").strip() or "Unknown",
        "state_manual": (scraped.get("state") or "").strip() or "Unknown",
        "pincode_manual": (scraped.get("pincode") or "").strip() or "000000",
        "needs_phone_review": needs_phone_review,
        "phone_found_in": scraped.get("phone_found_in") or "none",
        "seller_notes_scraped": (scraped.get("seller_notes") or "")[:1000],
    }
    # Tracking, when Amazon already shows it on the order page (Easy Ship
    # picked up, or seller previously confirmed shipment). Saving these
    # lets _save_scraped_pii skip the "Awaiting tracking" parking lot
    # and treat the order as already dispatched.
    if tracking_id:
        out["tracking_number"] = tracking_id
        out["tracking_source"] = "amazon_order_page_scrape"
    if carrier:
        out["carrier_code"] = carrier
    if scraped.get("shipped_on_amazon"):
        out["shipped_on_amazon_detected"] = True
    return out


async def _save_scraped_pii(amazon_order_id: str, firm_id: str, scraped: dict, user_id: str) -> dict:
    """Write scraped PII to an amazon_orders doc, mirroring save_amazon_customer_details.

    If the scrape detected the cancellation signature on Seller Central, mark the order
    cancelled instead of writing garbage PII.
    """
    order = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id, "firm_id": firm_id})
    if not order:
        raise ValueError(f"Amazon order {amazon_order_id} not found")

    now = datetime.now(timezone.utc).isoformat()

    if scraped.get("cancelled_on_amazon"):
        update_doc = {
            "crm_status": "cancelled",
            "cancelled_reason": "Cancelled on Amazon (auto-detected during PII scrape)",
            "cancelled_at": now,
            "cancelled_by": user_id,
            "details_captured_via": "browser_scrape",
            "cancelled_on_amazon_detected": True,
            "updated_at": now,
        }
        await db.amazon_orders.update_one(
            {"amazon_order_id": amazon_order_id},
            {"$set": update_doc}
        )
        return update_doc

    update_doc = _normalize_scraped_pii(scraped)
    update_doc.update({
        "details_captured_at": now,
        "details_captured_by": user_id,
        "details_captured_via": "browser_scrape",
        "updated_at": now,
    })
    # crm_status transition rules:
    #   - If Amazon's page already shows tracking, treat this as fully shipped
    #     and skip the "Awaiting tracking" parking lot. (Caller for the
    #     'just record in CRM' answer to the design Q on 2026-05-24.)
    #   - Else only flip from 'pending' to 'details_captured' — leave
    #     'amazon_shipped' alone for orders that already advanced.
    current_status = order.get("crm_status")
    if update_doc.get("tracking_number") and current_status in ("pending", "details_captured"):
        update_doc["crm_status"] = "amazon_shipped"
        update_doc["amazon_shipped_at"] = now
    elif current_status == "pending":
        update_doc["crm_status"] = "details_captured"

    await db.amazon_orders.update_one(
        {"amazon_order_id": amazon_order_id},
        {"$set": update_doc}
    )
    return update_doc


# ─────────────────────────────────────────────────────────────────────────────
# AMAZON REFUND / A-Z CLAIM / SAFE-T / CHARGEBACK TRACKING
# Closes the loop between Amazon settlement statements (the existing
# payout_transactions feed) and the books — every refund Amazon executes
# becomes a credit_note + a COGS reversal (when product returns).
# ─────────────────────────────────────────────────────────────────────────────

REFUND_TYPES = (
    "full_refund",       # Full sale price refunded
    "partial_refund",    # Partial refund (e.g. concession)
    "return_refund",     # Buyer returned the product
    "a_to_z_claim",      # Amazon A-Z guarantee claim — Amazon refunded the buyer
    "safe_t_claim",      # FBA SAFE-T claim
    "chargeback",        # Credit-card chargeback
    "manual_goodwill",   # Operator-recorded goodwill gesture
)

A_TO_Z_OUTCOMES = ("granted", "denied", "pending", "NA")


async def record_amazon_refund(refund_doc: dict, user: dict, auto_credit_note: bool = True, reverse_cogs: bool = False) -> dict:
    """Insert an `amazon_refunds` row + post the financial ripples.

    1. Insert refund row (dedup'd by refund_event_id when provided).
    2. Auto-create a credit_note (so receivables/party-ledger reflect the refund).
    3. Reverse COGS journal entry IFF the buyer returned the product.
    4. Mark linked payout_transaction as matched.
    5. Stamp amazon_orders.refund_status so the order shows refunded in CRM.
    """
    now = datetime.now(timezone.utc)
    now_iso = now.isoformat()
    aid = refund_doc.get("amazon_order_id")
    fid = refund_doc.get("firm_id")
    refund_amount = float(refund_doc.get("refund_amount", 0) or 0)
    refund_type = refund_doc.get("refund_type") or "partial_refund"
    if refund_type not in REFUND_TYPES:
        refund_type = "partial_refund"

    # Dedup by refund_event_id (Amazon SP-API guarantees uniqueness)
    rev_id = refund_doc.get("refund_event_id")
    if rev_id:
        existing = await db.amazon_refunds.find_one({"refund_event_id": rev_id}, {"_id": 0, "id": 1})
        if existing:
            return {"already_existed": True, "id": existing["id"]}

    refund_id = str(uuid.uuid4())

    # Look up the original Amazon order + dispatch (for COGS reversal context)
    az_order = await db.amazon_orders.find_one({"amazon_order_id": aid}, {"_id": 0}) if aid else None
    dispatch_id = (az_order or {}).get("dispatch_id")
    dispatch = await db.dispatches.find_one({"id": dispatch_id}, {"_id": 0}) if dispatch_id else None

    record = {
        "id": refund_id,
        "amazon_order_id": aid,
        "firm_id": fid,
        "refund_event_id": rev_id,
        "refund_amount": round(refund_amount, 2),
        "refund_date": refund_doc.get("refund_date") or now_iso[:10],
        "currency": refund_doc.get("currency") or "INR",
        "refund_type": refund_type,
        "refund_reason": refund_doc.get("refund_reason") or "",
        "a_to_z_outcome": refund_doc.get("a_to_z_outcome") or ("pending" if refund_type == "a_to_z_claim" else "NA"),
        "is_fake": bool(refund_doc.get("is_fake", False)),
        "is_disputed": bool(refund_doc.get("is_disputed", False)),
        "dispute_notes": refund_doc.get("dispute_notes") or "",
        "source": refund_doc.get("source") or "manual",
        "source_doc_id": refund_doc.get("source_doc_id"),
        "items": refund_doc.get("items") or [],
        "product_returned": bool(refund_doc.get("product_returned", False)),
        "linked_dispatch_id": dispatch_id,
        "linked_credit_note_id": None,
        "linked_journal_entry_id": None,
        "linked_payout_transaction_id": refund_doc.get("linked_payout_transaction_id"),
        "net_loss": round(refund_amount + float(refund_doc.get("return_shipping_cost", 0) or 0)
                          - float(refund_doc.get("recovered_amount", 0) or 0), 2),
        "created_by": user.get("id") if user else "system",
        "created_by_name": (
            f"{user.get('first_name','')} {user.get('last_name','')}".strip() if user else "System"
        ),
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # ─── Auto credit_note ───
    if auto_credit_note and refund_amount > 0 and dispatch_id:
        # Find the linked invoice
        inv = await db.sales_invoices.find_one({"dispatch_id": dispatch_id}, {"_id": 0})
        if inv:
            try:
                cn_number = await get_next_credit_note_number(fid)
                cn_id = str(uuid.uuid4())
                gst_rate = float(inv.get("items", [{}])[0].get("gst_rate", 18) or 18) if inv.get("items") else 18
                taxable_part = round(refund_amount / (1 + gst_rate / 100), 2)
                gst_part = round(refund_amount - taxable_part, 2)
                is_igst = float(inv.get("igst", 0) or 0) > 0
                cn = {
                    "id": cn_id,
                    "credit_note_number": cn_number,
                    "firm_id": fid, "firm_name": inv.get("firm_name"),
                    "party_id": inv.get("party_id"), "party_name": inv.get("party_name"),
                    "party_gstin": inv.get("party_gstin"),
                    "original_invoice_id": inv.get("id"),
                    "original_invoice_number": inv.get("invoice_number"),
                    "credit_note_date": record["refund_date"],
                    "reason": f"Amazon refund ({refund_type}) — {record['refund_reason']}".strip(" —"),
                    "items": [{
                        "name": (inv.get("items") or [{}])[0].get("name", ""),
                        "sku_code": (inv.get("items") or [{}])[0].get("sku_code", ""),
                        "quantity": 1,
                        "rate": refund_amount,
                        "gst_rate": gst_rate,
                        "taxable_value": taxable_part,
                        "gst_amount": gst_part,
                    }],
                    "subtotal": taxable_part,
                    "taxable_value": taxable_part,
                    "igst": gst_part if is_igst else 0,
                    "cgst": round(gst_part / 2, 2) if not is_igst else 0,
                    "sgst": round(gst_part / 2, 2) if not is_igst else 0,
                    "total_gst": gst_part,
                    "grand_total": round(refund_amount, 2),
                    "status": "issued",
                    "linked_refund_id": refund_id,
                    "created_by": record["created_by"],
                    "created_by_name": record["created_by_name"],
                    "created_at": now_iso,
                }
                await db.credit_notes.insert_one(cn)
                record["linked_credit_note_id"] = cn_id

                # Atomic party-ledger entry (credit reduces receivable)
                if inv.get("party_id"):
                    await create_party_ledger_entry_atomic(
                        party_id=inv["party_id"],
                        party_name=inv.get("party_name", ""),
                        entry_type="credit_note",
                        debit=0, credit=refund_amount,
                        narration=f"Amazon refund {refund_type} — CN {cn_number}",
                        reference_type="credit_note",
                        reference_id=cn_id,
                        firm_id=fid,
                        user_id=record["created_by"],
                        user_name=record["created_by_name"],
                        entry_number=f"CN-{cn_number}",
                        opening_balance=0,
                    )
            except Exception as e:
                logger.warning(f"refund auto-CN failed for {aid}: {e}")

    # ─── Reverse COGS only if product physically returned ───
    if reverse_cogs and dispatch and refund_doc.get("product_returned"):
        try:
            master_sku_id = dispatch.get("master_sku_id")
            qty = int(dispatch.get("quantity") or 1)
            master = await db.master_skus.find_one({"id": master_sku_id}, {"_id": 0}) if master_sku_id else None
            wac = await calculate_wac("master_sku", master_sku_id, fid) if master_sku_id else 0
            if not wac and master:
                wac = float(master.get("cost_price") or 0) or float(master.get("selling_price") or 0) * 0.6
            cogs_value = round(float(wac or 0) * qty, 2)
            if cogs_value > 0:
                je_id = str(uuid.uuid4())
                await db.journal_entries.insert_one({
                    "id": je_id,
                    "journal_type": "cogs_reversal_amazon_refund",
                    "firm_id": fid,
                    "reference_type": "amazon_refund",
                    "reference_id": refund_id,
                    "reference_number": refund_doc.get("refund_event_id") or refund_id,
                    "item_id": master_sku_id, "item_type": "master_sku",
                    "quantity": qty, "wac_per_unit": round(float(wac or 0), 4),
                    "lines": [
                        {"account": "Inventory",          "debit": cogs_value, "credit": 0},
                        {"account": "Cost of Goods Sold", "debit": 0, "credit": cogs_value},
                    ],
                    "amount": cogs_value,
                    "narration": f"COGS reversal — Amazon refund {refund_type} on {aid}",
                    "created_by": record["created_by"],
                    "created_by_name": record["created_by_name"],
                    "created_at": now_iso,
                })
                record["linked_journal_entry_id"] = je_id
                # Credit stock back
                try:
                    await credit_stock_atomic("master_sku", master_sku_id, fid, qty)
                except Exception:
                    pass
        except Exception as e:
            logger.warning(f"refund COGS reversal failed for {aid}: {e}")

    await db.amazon_refunds.insert_one(record)

    # Update amazon_orders.refund_status
    if aid:
        await db.amazon_orders.update_one(
            {"amazon_order_id": aid},
            {"$set": {
                "refund_status": refund_type,
                "refund_amount": refund_amount,
                "refund_id": refund_id,
                "updated_at": now_iso,
            }},
        )

    # Mark linked payout_transaction as matched
    if refund_doc.get("linked_payout_transaction_id"):
        await db.payout_transactions.update_one(
            {"id": refund_doc["linked_payout_transaction_id"]},
            {"$set": {"crm_match_status": "matched", "linked_refund_id": refund_id}},
        )

    return {"already_existed": False, "id": refund_id, "record": record}


async def book_existing_refund(refund_id: str, user: Optional[dict] = None) -> dict:
    """Book a credit note + party-ledger entry for an `amazon_refunds` row
    that was ingested but never got `linked_credit_note_id` set.

    Idempotent: skips if `linked_credit_note_id` already exists. Returns a
    structured outcome so a backfill loop can summarize.

    Skip reasons (returned with `skipped=True`):
      - already_booked: the row already has a credit_note linked
      - no_dispatch:    the original Amazon order has no dispatch_id, so we
                        can't find the original invoice → can't post a
                        proper credit note. Operator needs to ship the
                        order first (or link the dispatch manually).
      - no_invoice:     dispatch found but no sales_invoice exists for it.
                        Means the order was shipped but its invoice was
                        never generated — book those orders first.
      - zero_amount:    refund_amount is 0 (nothing to credit).

    On success: returns `{success: True, credit_note_id, credit_note_number}`.
    """
    now_iso = datetime.now(timezone.utc).isoformat()
    r = await db.amazon_refunds.find_one({"id": refund_id}, {"_id": 0})
    if not r:
        return {"success": False, "skipped": True, "reason": "not_found"}
    if r.get("linked_credit_note_id"):
        return {"success": True, "skipped": True, "reason": "already_booked",
                "credit_note_id": r["linked_credit_note_id"]}
    refund_amount = float(r.get("refund_amount") or 0)
    if refund_amount <= 0:
        return {"success": False, "skipped": True, "reason": "zero_amount"}

    aid = r.get("amazon_order_id")
    fid = r.get("firm_id")
    if not (aid and fid):
        return {"success": False, "skipped": True, "reason": "missing_keys"}

    az_order = await db.amazon_orders.find_one({"amazon_order_id": aid}, {"_id": 0})
    dispatch_id = (az_order or {}).get("dispatch_id")
    if not dispatch_id:
        return {"success": False, "skipped": True, "reason": "no_dispatch"}
    inv = await db.sales_invoices.find_one({"dispatch_id": dispatch_id}, {"_id": 0})
    if not inv:
        return {"success": False, "skipped": True, "reason": "no_invoice"}

    try:
        cn_number = await get_next_credit_note_number(fid)
    except Exception as e:
        return {"success": False, "skipped": False, "reason": f"cn_number_error: {e}"}

    cn_id = str(uuid.uuid4())
    items = inv.get("items") or [{}]
    gst_rate = float(items[0].get("gst_rate", 18) or 18) if items else 18
    taxable_part = round(refund_amount / (1 + gst_rate / 100), 2)
    gst_part = round(refund_amount - taxable_part, 2)
    is_igst = float(inv.get("igst", 0) or 0) > 0
    refund_type = r.get("refund_type") or "partial_refund"

    cn = {
        "id": cn_id,
        "credit_note_number": cn_number,
        "firm_id": fid,
        "firm_name": inv.get("firm_name"),
        "party_id": inv.get("party_id"),
        "party_name": inv.get("party_name"),
        "party_gstin": inv.get("party_gstin"),
        "original_invoice_id": inv.get("id"),
        "original_invoice_number": inv.get("invoice_number"),
        "credit_note_date": r.get("refund_date") or now_iso[:10],
        "reason": f"Amazon refund ({refund_type}) — {r.get('refund_reason') or ''}".strip(" —"),
        "items": [{
            "name": items[0].get("name", ""),
            "sku_code": items[0].get("sku_code", ""),
            "quantity": 1,
            "rate": refund_amount,
            "gst_rate": gst_rate,
            "taxable_value": taxable_part,
            "gst_amount": gst_part,
        }],
        "subtotal": taxable_part,
        "taxable_value": taxable_part,
        "igst": gst_part if is_igst else 0,
        "cgst": round(gst_part / 2, 2) if not is_igst else 0,
        "sgst": round(gst_part / 2, 2) if not is_igst else 0,
        "total_gst": gst_part,
        "grand_total": round(refund_amount, 2),
        "status": "issued",
        "linked_refund_id": refund_id,
        "created_by": (user or {}).get("id", "system"),
        "created_by_name": (
            f"{(user or {}).get('first_name','')} {(user or {}).get('last_name','')}".strip()
            or "System (backfill)"
        ),
        "created_at": now_iso,
        "source": "amazon_refund_backfill",
    }
    await db.credit_notes.insert_one(cn)
    await db.amazon_refunds.update_one(
        {"id": refund_id},
        {"$set": {"linked_credit_note_id": cn_id, "updated_at": now_iso}},
    )
    # Party-ledger entry — credit reduces receivable
    if inv.get("party_id"):
        try:
            await create_party_ledger_entry_atomic(
                party_id=inv["party_id"],
                party_name=inv.get("party_name", ""),
                entry_type="credit_note",
                debit=0, credit=refund_amount,
                narration=f"Amazon refund {refund_type} — CN {cn_number}",
                reference_type="credit_note",
                reference_id=cn_id,
                firm_id=fid,
                user_id=cn["created_by"],
                user_name=cn["created_by_name"],
                entry_number=f"CN-{cn_number}",
                opening_balance=0,
            )
        except Exception as e:
            logger.warning(f"backfill refund {refund_id}: ledger entry failed: {e}")
    # Stamp amazon_orders.refund_status (if not already)
    await db.amazon_orders.update_one(
        {"amazon_order_id": aid},
        {"$set": {
            "refund_status": refund_type,
            "refund_amount": refund_amount,
            "refund_id": refund_id,
            "updated_at": now_iso,
        }},
    )
    return {"success": True, "skipped": False,
            "credit_note_id": cn_id, "credit_note_number": cn_number}


class BookRefundsRequest(BaseModel):
    firm_id: Optional[str] = None
    limit: Optional[int] = None  # None = all
    dry_run: bool = False


@api_router.post("/amazon/refunds/book-unbooked")
async def book_unbooked_refunds(
    data: BookRefundsRequest,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Backfill credit notes + party-ledger entries for all amazon_refunds
    rows that were ingested but never linked to a credit note. Accountants
    are firm-scoped; admin can target any firm or all.
    """
    query: Dict[str, Any] = {"linked_credit_note_id": None}
    scope = firm_scope_filter(user, data.firm_id)
    query.update(scope)
    cursor = db.amazon_refunds.find(query, {"_id": 0, "id": 1}).sort("refund_date", 1)
    if data.limit:
        cursor = cursor.limit(data.limit)
    summary = {"total": 0, "booked": 0, "skipped": {}, "errors": []}
    async for r in cursor:
        summary["total"] += 1
        if data.dry_run:
            continue
        try:
            res = await book_existing_refund(r["id"], user=user)
        except Exception as e:
            summary["errors"].append(f"{r['id']}: {str(e)[:120]}")
            continue
        if res.get("skipped"):
            reason = res.get("reason", "unknown")
            summary["skipped"][reason] = summary["skipped"].get(reason, 0) + 1
        elif res.get("success"):
            summary["booked"] += 1
        else:
            summary["errors"].append(f"{r['id']}: {res.get('reason', 'unknown')}")
    return summary


@api_router.get("/amazon/refunds")
async def list_amazon_refunds(
    firm_id: Optional[str] = None,
    refund_type: Optional[str] = None,
    is_fake: Optional[bool] = None,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    limit: int = 200,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """List Amazon refunds with filters. Accountants are firm-scoped."""
    query = firm_scope_filter(user, firm_id)
    if refund_type:
        query["refund_type"] = refund_type
    if is_fake is not None:
        query["is_fake"] = is_fake
    if from_date:
        query["refund_date"] = {"$gte": from_date}
    if to_date:
        query.setdefault("refund_date", {})["$lte"] = to_date
    rows = await db.amazon_refunds.find(query, {"_id": 0}).sort("refund_date", -1).to_list(limit)
    return rows


@api_router.patch("/amazon/refunds/{refund_id}")
async def update_amazon_refund(
    refund_id: str,
    payload: dict = Body(...),
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Patch the manual flags on a refund row (is_fake, is_disputed, dispute_notes,
    product_returned, a_to_z_outcome)."""
    existing = await db.amazon_refunds.find_one({"id": refund_id}, {"_id": 0, "firm_id": 1})
    if not existing:
        raise HTTPException(status_code=404, detail="Refund not found")
    assert_firm_access(user, existing.get("firm_id"))

    ALLOWED = {"is_fake", "is_disputed", "dispute_notes", "product_returned",
               "a_to_z_outcome", "refund_reason", "refund_type"}
    update = {k: v for k, v in payload.items() if k in ALLOWED}
    if not update:
        raise HTTPException(status_code=400, detail="No editable fields supplied")
    if "a_to_z_outcome" in update and update["a_to_z_outcome"] not in A_TO_Z_OUTCOMES:
        raise HTTPException(status_code=400, detail=f"a_to_z_outcome must be one of {A_TO_Z_OUTCOMES}")
    if "refund_type" in update and update["refund_type"] not in REFUND_TYPES:
        raise HTTPException(status_code=400, detail=f"refund_type must be one of {REFUND_TYPES}")
    update["updated_at"] = datetime.now(timezone.utc).isoformat()
    update["updated_by"] = user["id"]
    await db.amazon_refunds.update_one({"id": refund_id}, {"$set": update})
    return await db.amazon_refunds.find_one({"id": refund_id}, {"_id": 0})


@api_router.post("/amazon/refunds/backfill-from-payouts/{firm_id}")
async def backfill_refunds_from_payouts(
    firm_id: str,
    user: dict = Depends(require_roles(["admin"])),
):
    """One-time backfill: convert existing `payout_transactions` of type 'Refund' /
    category 'refund' into `amazon_refunds` rows + credit notes."""
    assert_firm_access(user, firm_id)
    rows = await db.payout_transactions.find({
        "$or": [
            {"transaction_type": "Refund"},
            {"transaction_category": "refund"},
        ],
        "crm_match_status": {"$ne": "matched"},
    }, {"_id": 0}).to_list(5000)
    created, skipped = 0, 0
    for t in rows:
        # Resolve firm_id from the linked statement
        stmt = await db.payout_statements.find_one({"id": t.get("statement_id")}, {"_id": 0, "firm_id": 1})
        t_firm = (stmt or {}).get("firm_id")
        if t_firm and t_firm != firm_id:
            continue
        aid = t.get("marketplace_order_id") or t.get("amazon_order_id")
        if not aid:
            skipped += 1
            continue
        try:
            r = await record_amazon_refund(
                {
                    "amazon_order_id": aid,
                    "firm_id": firm_id,
                    "refund_event_id": f"payout-{t.get('id')}",
                    "refund_amount": abs(float(t.get("total_amount") or 0)),
                    "refund_date": t.get("date"),
                    "refund_type": "return_refund",  # safe default; user can re-classify
                    "refund_reason": t.get("product_details") or "From Amazon settlement",
                    "source": "amazon_settlement",
                    "source_doc_id": t.get("id"),
                    "linked_payout_transaction_id": t.get("id"),
                },
                user=user,
                auto_credit_note=True,
                reverse_cogs=False,
            )
            if r.get("already_existed"):
                skipped += 1
            else:
                created += 1
        except Exception as e:
            logger.warning(f"backfill refund {aid}: {e}")
            skipped += 1
    return {"created": created, "skipped": skipped, "total_examined": len(rows)}


# ---------------------------------------------------------------------------
# Settlement-fee posting: book Amazon's commission / shipping / fixed / GST
# takeout as journal entries so the P&L reflects what actually hit the bank.
# Without this the CRM sees gross revenue from sales_invoices but never the
# 15-45% Amazon kept on the way to the bank.
# ---------------------------------------------------------------------------

# Each fee bucket on a payout_transactions row → its own GL expense account.
# The CR side is a clearing account that nets out against the bank-settlement
# entry (so balance-sheet stays clean).
#
# Some settlement-file parsers populate the GRANULAR fields (commission,
# marketplace_fee, ...), others roll everything into `platform_fees`. The
# code below uses BOTH lists in order: if any granular field is non-zero we
# trust that breakdown; only when ALL granular fields are zero do we fall
# back to the rolled-up platform_fees number. Prevents double-posting when a
# parser fills both.
_FEE_BUCKETS_GRANULAR = [
    ("commission",         "Amazon Commission Expense"),
    ("marketplace_fee",    "Amazon Marketplace Fee Expense"),
    ("fixed_fee",          "Amazon Fixed Fee Expense"),
    ("collection_fee",     "Amazon Collection Fee Expense"),
    ("shipping_fee",       "Amazon Shipping Fee Expense"),
    ("gst_on_fees",        "GST Input on Amazon Fees"),
    ("tcs",                "TCS Recoverable (Amazon)"),
    ("tds",                "TDS Recoverable (Amazon)"),
    ("protection_fund",    "Amazon Protection Fund Expense"),
]
_FEE_BUCKETS_ROLLUP = [
    ("platform_fees",      "Amazon Platform Fee Expense"),
]
_FEE_CLEARING_ACCOUNT = "Amazon Marketplace Clearing"


def _select_fee_buckets(t: dict) -> list:
    """Pick granular fields if any are non-zero, else fall back to rolled-up."""
    def nonzero(field: str) -> bool:
        v = t.get(field)
        try:
            return v not in (None, "", 0, 0.0) and abs(float(v)) >= 0.01
        except (TypeError, ValueError):
            return False
    if any(nonzero(f) for f, _ in _FEE_BUCKETS_GRANULAR):
        return _FEE_BUCKETS_GRANULAR
    return _FEE_BUCKETS_ROLLUP


async def _post_fees_for_transaction(t: dict, firm_id: str, firm_name: Optional[str], user: dict) -> List[dict]:
    """Emit a journal_entries row for each non-zero fee bucket on a settlement
    transaction. Returns the inserted entries.

    Each entry: Dr <fee expense account> / Cr Amazon Marketplace Clearing.
    The clearing account nets against the eventual bank-settlement deposit
    (gross sale Cr - fees Dr = net bank credit), so the balance sheet stays
    intact while the P&L finally shows the fees as expense.

    Idempotent: stamps `fees_posted=True` + `fees_journal_ids` on the
    transaction so re-runs skip rows already booked.
    """
    if t.get("fees_posted") is True:
        return []
    now = datetime.now(timezone.utc).isoformat()
    accounting_date_str = (str(t.get("date"))[:10] if t.get("date") else now[:10])
    inserts: List[dict] = []
    buckets = _select_fee_buckets(t)
    for field, account in buckets:
        raw = t.get(field)
        if raw in (None, "", 0, 0.0):
            continue
        try:
            amount = abs(float(raw))
        except (TypeError, ValueError):
            continue
        if amount < 0.01:
            continue
        # Sign convention: Amazon's fees are SUBTRACTED from the seller's
        # settlement; field values in payout_transactions are usually
        # negative (an outflow). Either sign means the expense is real;
        # use abs() and rely on Dr Expense / Cr Clearing being correct.
        je = {
            "id": str(uuid.uuid4()),
            "journal_type": "marketplace_fee_posting",
            "firm_id": firm_id,
            "firm_name": firm_name,
            "reference_type": "payout_transaction",
            "reference_id": t.get("id"),
            "reference_number": t.get("statement_id"),
            "marketplace": "amazon",
            "marketplace_order_id": t.get("marketplace_order_id"),
            "fee_bucket": field,
            "amount": round(amount, 2),
            "lines": [
                {"account": account, "debit": round(amount, 2), "credit": 0},
                {"account": _FEE_CLEARING_ACCOUNT, "debit": 0, "credit": round(amount, 2)},
            ],
            "narration": (
                f"Amazon settlement {t.get('statement_id', '')[:8]} — "
                f"{field} on order {t.get('marketplace_order_id', '(no-order)')}"
            ),
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip() or user.get("email"),
            "created_at": now,
            "accounting_date": accounting_date_str,
            "accounting_date_source": "settlement_date",
        }
        inserts.append(je)
    if inserts:
        await db.journal_entries.insert_many(inserts)
        await db.payout_transactions.update_one(
            {"id": t.get("id")},
            {"$set": {
                "fees_posted": True,
                "fees_posted_at": now,
                "fees_journal_ids": [je["id"] for je in inserts],
                "fees_posted_total": round(sum(je["amount"] for je in inserts), 2),
            }},
        )
    return inserts


@api_router.post("/finance/run-daily-agent")
async def trigger_finance_agent(
    firm_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Manually invoke the daily Amazon-finance agent. Same code path as the
    scheduled 08:00 IST run — books unposted fees + refunds + counts
    unmatched transactions across firms.

    Pass `firm_id` to scope to one firm; omit for all firms with active
    Amazon credentials. Returns per-firm + aggregate stats. Accountants are
    scoped to their own firm; admins can run for any/all.
    """
    if firm_id:
        assert_firm_access(user, firm_id)

    system_user = {
        "id": f"manual-trigger-{user['id']}",
        "first_name": user.get("first_name", "Manual"),
        "last_name": user.get("last_name", "Trigger"),
        "email": user.get("email"),
    }

    # Which firms to run for
    if firm_id:
        firms = [await db.firms.find_one({"id": firm_id}, {"_id": 0, "id": 1, "name": 1})]
        firms = [f for f in firms if f]
    else:
        firm_ids = [
            c["firm_id"] async for c in db.marketplace_credentials.find(
                {"platform": "amazon", "is_active": True}, {"_id": 0, "firm_id": 1}
            ) if c.get("firm_id")
        ]
        # Accountants are firm-scoped — restrict if they hit this without a firm_id
        accountant_firm = get_user_firm_scope(user)
        if accountant_firm:
            firm_ids = [f for f in firm_ids if f == accountant_firm]
        firms = []
        for fid in firm_ids:
            f = await db.firms.find_one({"id": fid}, {"_id": 0, "id": 1, "name": 1})
            if f:
                firms.append(f)

    # Persist manual runs to the same audit log as scheduled runs so the
    # observability page (and any auditor) sees every invocation.
    started = datetime.now(timezone.utc)
    run = {
        "id": str(uuid.uuid4()),
        "job": "amazon_finance_agent",
        "trigger": "manual",
        "triggered_by": user.get("email") or user.get("id"),
        "scope_firm_id": firm_id,
        "started_at": started.isoformat(),
        "status": "running",
        "per_firm": {},
    }
    await db.scheduled_job_runs.insert_one(dict(run))

    per_firm = []
    for firm in firms:
        try:
            stats = await _run_finance_agent_for_firm(firm, system_user)
            per_firm.append(stats)
            run["per_firm"][firm.get("id")] = stats
        except Exception as e:
            logger.error(f"[finance-agent] manual run firm={firm.get('name')} failed: {e}", exc_info=True)
            err = {"firm_id": firm.get("id"), "firm_name": firm.get("name"), "errors": [str(e)]}
            per_firm.append(err)
            run["per_firm"][firm.get("id")] = err

    # Run-level browser-agent scrape — pulls FBA reimbursements Amazon doesn't
    # ship via SP-API. Only runs if a target firm is configured (no firms with
    # Amazon creds = nothing to scrape; admin can override with env var).
    reimb_scrape = None
    reimb_firm = await _pick_browser_agent_firm()
    if reimb_firm:
        # Accountants may have triggered a scope-limited run; only scrape if
        # the chosen firm is one they're allowed to see.
        scope = get_user_firm_scope(user)
        if scope and reimb_firm["id"] != scope:
            reimb_scrape = {"status": "skipped", "scraped": 0, "new_rows": 0, "booked": 0,
                            "total_amount": 0.0, "firm_id": reimb_firm["id"],
                            "firm_name": reimb_firm.get("name"),
                            "error": "browser agent firm out of accountant scope"}
        else:
            reimb_scrape = await _scrape_and_book_reimbursements(
                reimb_firm["id"], reimb_firm.get("name", ""), system_user
            )
            reimb_scrape["firm_id"]   = reimb_firm["id"]
            reimb_scrape["firm_name"] = reimb_firm.get("name")
        run["reimbursement_scrape"] = reimb_scrape

    totals = _agent_aggregate_totals(per_firm, reimb_scrape)
    priority = _agent_priority(per_firm)
    if reimb_scrape and reimb_scrape.get("status") in ("session_expired", "page_changed"):
        priority = "high"

    run["status"] = "completed"
    run["completed_at"] = datetime.now(timezone.utc).isoformat()
    run["totals"] = totals
    run["priority"] = priority
    await db.scheduled_job_runs.update_one({"id": run["id"]}, {"$set": run})

    return {
        "run_id": run["id"],
        "firms_run": len(per_firm),
        "per_firm": per_firm,
        "totals": totals,
        "priority": priority,
        "reimbursement_scrape": reimb_scrape,
    }


@api_router.get("/finance/agent-runs")
async def list_finance_agent_runs(
    limit: int = 20,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Recent Finance Agent runs (scheduled + manual) from scheduled_job_runs.
    Mirror of `/admin/cron-runs` but scoped to this one job and accessible
    to accountants. Used by the /agents/finance page to render run history."""
    rows = await db.scheduled_job_runs.find(
        {"job": "amazon_finance_agent"},
        {"_id": 0},
    ).sort("started_at", -1).to_list(limit)
    # Accountants are firm-scoped: strip per_firm entries they shouldn't see.
    scope_firm = get_user_firm_scope(user)
    if scope_firm:
        for r in rows:
            r["per_firm"] = {k: v for k, v in (r.get("per_firm") or {}).items() if k == scope_firm}
    return rows


@api_router.get("/finance/scraper-state")
async def get_finance_scraper_state(
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """State of every continuous-scrape task: next-due time, last status,
    last result. Powers the Watch Live page.

    Also returns the browser-agent state so the page can show whether the
    session is alive (and therefore whether the next pulse will actually do
    anything)."""
    await _seed_scraper_state()
    tasks = await db.finance_scraper_state.find({}, {"_id": 0}).sort("task_kind", 1).to_list(50)
    # Browser state snapshot
    browser_state = {"state": "unknown", "page_url": None}
    try:
        agent = await get_browser_agent()
        browser_state["state"] = getattr(agent, "state", None)
        if hasattr(agent.state, "value"):
            browser_state["state"] = agent.state.value
        browser_state["page_url"] = agent.page.url if (agent and agent.page) else None
        browser_state["started"] = bool(agent.page)
    except Exception as e:
        browser_state["error"] = str(e)[:200]
    return {"tasks": tasks, "browser": browser_state}


@api_router.post("/finance/amazon/order/{order_id}/scrape-transactions")
async def scrape_amazon_order_transactions(
    order_id: str,
    force: bool = False,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """On-demand: scrape one Amazon order's full financial breakdown from
    Seller Central. Powers the 'Verify on Amazon' button next to each
    unmatched payout row on the e-commerce recon page.

    Falls back to the Claude brain if the deterministic selectors miss.
    Result is cached for 6 hours so repeated clicks on the same order
    don't burn API tokens — pass `force=true` to bypass."""
    # Light input sanity — Amazon order IDs are 3-7-7 hex blocks like
    # "171-2345678-1234567". Don't lock to that pattern strictly (sandbox
    # IDs can vary) but reject obvious garbage / path-traversal attempts.
    if not order_id or len(order_id) > 50 or any(c in order_id for c in "/\\?#"):
        raise HTTPException(status_code=400, detail="Invalid order_id")

    # Cache check — return recent result unless caller forces a re-scrape.
    if not force:
        six_hours_ago = (datetime.now(timezone.utc) - timedelta(hours=6)).isoformat()
        cached = await db.amazon_order_scrapes.find_one(
            {"order_id": order_id, "scraped_at": {"$gte": six_hours_ago}},
            {"_id": 0},
        )
        if cached:
            cached["from_cache"] = True
            return cached

    agent = await get_browser_agent()
    if not agent or not agent.page:
        raise HTTPException(
            status_code=503,
            detail="Browser agent not started. Open /admin/browser-agent and start it first.",
        )

    try:
        result = await agent.scrape_order_transactions(order_id)
    except Exception as e:
        logger.exception(f"[order-txn-scrape] order={order_id} crashed")
        raise HTTPException(status_code=500, detail=f"Scrape crashed: {str(e)[:200]}")

    doc = {
        "order_id": order_id,
        "scraped_at": datetime.now(timezone.utc).isoformat(),
        "scraped_by": user.get("email") or user.get("id"),
        **result,
    }
    # Upsert into cache (keep latest result per order_id)
    await db.amazon_order_scrapes.update_one(
        {"order_id": order_id},
        {"$set": doc},
        upsert=True,
    )
    doc["from_cache"] = False
    return doc


@api_router.post("/finance/scraper-state/{task_kind}/run-now")
async def force_run_scraper_task(
    task_kind: str,
    user: dict = Depends(require_roles(["admin"])),
):
    """Force a specific scrape task to run *immediately* — not on the next
    30-min pulse tick. Sets next_due_at to NOW and kicks a one-shot pulse
    on the event loop so the user gets progress within seconds.

    Concurrency-safe: the pulse's find_one_and_update atomically claims a
    task, so the kicked pulse and any in-flight scheduled pulse can't
    both grab the same row."""
    if task_kind not in FINANCE_SCRAPE_TASKS:
        raise HTTPException(status_code=404, detail=f"Unknown task kind: {task_kind}")
    await _seed_scraper_state()
    now = datetime.now(timezone.utc).isoformat()
    r = await db.finance_scraper_state.update_one(
        {"task_kind": task_kind, "running": {"$ne": True}},
        {"$set": {"next_due_at": now, "enabled": True}},
    )
    if r.matched_count == 0:
        return {"queued": False, "reason": "task is already running or not seeded"}
    # Kick an immediate pulse so the user doesn't wait up to 30 min for
    # the next apscheduler tick. The pulse picks whatever is most-overdue
    # — since we just set this task's next_due_at to NOW, it wins.
    asyncio.create_task(scheduled_finance_scraper_pulse())
    return {"queued": True, "task_kind": task_kind, "queued_at": now, "kicked": True}


# ===================================================================
# Data Inbox — items the agent needs from the human
# ===================================================================
# When the scraper finds a gap it can't fill (e.g. a bank statement
# Amazon doesn't have), it creates a finance_data_gaps row. The Inbox
# page lists open rows and lets the user upload the missing file.

@api_router.get("/finance/data-gaps")
async def list_finance_data_gaps(
    status: Optional[str] = None,  # open | resolved | all
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """List data gaps the Finance Agent has opened. Default: only `open`."""
    q: Dict[str, Any] = {}
    scope_firm = get_user_firm_scope(user)
    if scope_firm:
        q["firm_id"] = scope_firm
    if not status or status == "open":
        q["status"] = "open"
    elif status == "resolved":
        q["status"] = "resolved"
    rows = await db.finance_data_gaps.find(q, {"_id": 0}).sort("created_at", -1).limit(200).to_list(200)
    counts = {
        "open":     await db.finance_data_gaps.count_documents({**q, "status": "open"}),
        "resolved": await db.finance_data_gaps.count_documents({**({"firm_id": scope_firm} if scope_firm else {}), "status": "resolved"}),
    }
    return {"items": rows, "counts": counts}


@api_router.post("/finance/data-gaps")
async def create_finance_data_gap(
    payload: dict = Body(...),
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Manually open a data gap. Normally the agent does this; this endpoint
    is for testing + for accountants who want to flag a missing file."""
    kind = payload.get("kind")
    if kind not in ("bank_statement", "credit_card_statement", "supplier_invoice", "other"):
        raise HTTPException(status_code=400, detail="Invalid kind")
    now = datetime.now(timezone.utc).isoformat()
    firm_id = payload.get("firm_id") or get_user_firm_scope(user)
    doc = {
        "id": str(uuid.uuid4()),
        "kind": kind,
        "firm_id": firm_id,
        "period": payload.get("period"),  # e.g. "2026-05"
        "description": payload.get("description") or f"{kind} needed",
        "requested_by": "manual",
        "requested_by_user": user.get("email"),
        "status": "open",
        "created_at": now,
        "satisfied_by_upload_id": None,
        "resolved_at": None,
    }
    await db.finance_data_gaps.insert_one(doc)
    return doc


@api_router.post("/finance/data-gaps/{gap_id}/upload")
async def upload_finance_data_gap(
    gap_id: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """User-uploads an Excel/CSV/PDF satisfying a data gap. Stores via the
    existing storage helper and marks the gap resolved. Actual parsing of
    the file (e.g. bank statement → journal entries) is a phase-2 task —
    we just persist the upload here so it isn't lost."""
    gap = await db.finance_data_gaps.find_one({"id": gap_id}, {"_id": 0})
    if not gap:
        raise HTTPException(status_code=404, detail="Data gap not found")
    if gap.get("status") == "resolved":
        raise HTTPException(status_code=400, detail="Gap already resolved")
    scope = get_user_firm_scope(user)
    if scope and gap.get("firm_id") and gap["firm_id"] != scope:
        raise HTTPException(status_code=403, detail="Out of firm scope")

    from utils.storage import upload_file as storage_upload
    content = await file.read()
    filename = file.filename or "upload"
    path = f"finance_data_gaps/{gap_id}/{filename}"
    storage_url = None
    try:
        from io import BytesIO
        fobj = BytesIO(content)
        fobj.name = filename
        storage_url = await asyncio.to_thread(
            storage_upload, fobj, path, file.content_type or "application/octet-stream"
        )
    except Exception as e:
        logger.error(f"[data-gap] storage upload failed: {e}")
        raise HTTPException(status_code=500, detail=f"Upload failed: {e}")

    upload_id = str(uuid.uuid4())
    await db.finance_data_uploads.insert_one({
        "id": upload_id,
        "gap_id": gap_id,
        "filename": filename,
        "size_bytes": len(content),
        "content_type": file.content_type,
        "storage_path": path,
        "storage_url": storage_url,
        "uploaded_by": user.get("email"),
        "uploaded_at": datetime.now(timezone.utc).isoformat(),
        "parse_status": "pending",  # parser is phase-2 — surfaces in UI
    })
    await db.finance_data_gaps.update_one(
        {"id": gap_id},
        {"$set": {
            "status": "resolved",
            "satisfied_by_upload_id": upload_id,
            "resolved_at": datetime.now(timezone.utc).isoformat(),
        }},
    )
    return {"ok": True, "upload_id": upload_id, "gap_id": gap_id}


@api_router.post("/amazon/fees/post-from-payouts/{firm_id}")
async def post_amazon_fees_from_payouts(
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Walk payout_transactions for this firm and book any unposted fees
    as journal entries. Idempotent — transactions already marked
    `fees_posted=True` are skipped.

    Returns per-bucket totals + journal-entry counts so the accountant can
    sanity-check what landed in the P&L.
    """
    assert_firm_access(user, firm_id)

    # Resolve via the parent statement so we only touch this firm's rows.
    firm_doc = await db.firms.find_one({"id": firm_id}, {"_id": 0, "name": 1})
    firm_name = (firm_doc or {}).get("name")
    statement_ids = [
        s["id"] async for s in db.payout_statements.find(
            {"firm_id": firm_id}, {"_id": 0, "id": 1}
        )
    ]
    if not statement_ids:
        return {"posted_rows": 0, "skipped_rows": 0, "journal_entries_created": 0, "total_amount": 0}

    cur = db.payout_transactions.find(
        {
            "statement_id": {"$in": statement_ids},
            "$or": [
                {"fees_posted": {"$ne": True}},
                {"fees_posted": {"$exists": False}},
            ],
        },
        {"_id": 0},
    )

    posted = skipped = journal_created = 0
    total_amount = 0.0
    per_bucket: Dict[str, float] = {}
    async for t in cur:
        try:
            entries = await _post_fees_for_transaction(t, firm_id, firm_name, user)
        except Exception as e:
            logger.warning(f"post-fees for transaction {t.get('id')}: {e}")
            skipped += 1
            continue
        if not entries:
            # Either no non-zero buckets or already posted (idempotent skip)
            skipped += 1
            continue
        posted += 1
        journal_created += len(entries)
        for je in entries:
            total_amount += je["amount"]
            per_bucket[je["fee_bucket"]] = round(per_bucket.get(je["fee_bucket"], 0) + je["amount"], 2)

    return {
        "posted_rows": posted,
        "skipped_rows": skipped,
        "journal_entries_created": journal_created,
        "total_amount": round(total_amount, 2),
        "per_bucket": per_bucket,
        "clearing_account": _FEE_CLEARING_ACCOUNT,
    }


@api_router.post("/amazon/refunds/sync-financial-events/{firm_id}")
async def sync_amazon_financial_events(
    firm_id: str,
    days_back: int = 30,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Pull RefundEvents + GuaranteeClaimEvents + SAFETClaimEvents from Amazon
    SP-API for the given window and persist them via record_amazon_refund."""
    assert_firm_access(user, firm_id)
    creds = await db.marketplace_credentials.find_one(
        {"firm_id": firm_id, "platform": "amazon", "is_active": True}
    )
    if not creds:
        raise HTTPException(status_code=400, detail="Amazon credentials not configured")

    after = (datetime.now(timezone.utc) - timedelta(days=days_back)).strftime("%Y-%m-%dT%H:%M:%SZ")
    page_token = None
    all_events: dict[str, list] = {
        "RefundEventList": [],
        "GuaranteeClaimEventList": [],
        "SAFETClaimEventList": [],
        "ChargebackEventList": [],
    }
    pages = 0
    while True:
        pages += 1
        if pages > 20:
            break
        qs = f"PostedAfter={after}&MaxResultsPerPage=100"
        if page_token:
            qs = f"NextToken={page_token}"
        try:
            resp = await make_amazon_api_request(creds, "GET", "/finances/v0/financialEvents", qs)
        except Exception as e:
            return {"error": f"SP-API call failed: {e}", "pages": pages}
        if resp["status"] != 200:
            return {"error": f"SP-API {resp['status']}: {str(resp.get('data'))[:200]}", "pages": pages}
        payload = (resp.get("data") or {}).get("payload") or {}
        events = payload.get("FinancialEvents") or {}
        for k in all_events:
            for e in events.get(k, []) or []:
                all_events[k].append(e)
        page_token = payload.get("NextToken")
        if not page_token:
            break

    created, skipped = 0, 0

    async def _persist(aid, event_id, refund_type, amount, refund_date, reason, raw):
        nonlocal created, skipped
        try:
            r = await record_amazon_refund({
                "amazon_order_id": aid, "firm_id": firm_id,
                "refund_event_id": event_id,
                "refund_amount": abs(float(amount or 0)),
                "refund_date": refund_date,
                "refund_type": refund_type,
                "refund_reason": reason or "",
                "source": "financial_events_api",
                "source_doc_id": event_id,
                "raw": raw,
            }, user=user, auto_credit_note=True, reverse_cogs=False)
            if r.get("already_existed"):
                skipped += 1
            else:
                created += 1
        except Exception as e:
            logger.warning(f"persist refund {aid}: {e}")
            skipped += 1

    def _sum_charges(adj_list):
        total = 0.0
        for adj in adj_list or []:
            for chg in (adj.get("ItemChargeAdjustmentList") or []):
                total += float((chg.get("ChargeAmount") or {}).get("CurrencyAmount", 0) or 0)
            for fee in (adj.get("ItemFeeAdjustmentList") or []):
                total += float((fee.get("FeeAmount") or {}).get("CurrencyAmount", 0) or 0)
        return abs(total)

    for e in all_events["RefundEventList"]:
        aid = e.get("AmazonOrderId")
        eid = f"refund-{aid}-{e.get('PostedDate')}"
        amount = _sum_charges(e.get("ShipmentItemAdjustmentList"))
        await _persist(aid, eid, "return_refund", amount, str(e.get("PostedDate", ""))[:10],
                       e.get("AdjustmentType") or "", e)

    for e in all_events["GuaranteeClaimEventList"]:
        aid = e.get("AmazonOrderId")
        eid = f"a-to-z-{aid}-{e.get('PostedDate')}"
        amount = _sum_charges(e.get("ShipmentItemAdjustmentList"))
        outcome = (e.get("ClaimStatus") or "").lower() or "granted"
        await _persist(aid, eid, "a_to_z_claim", amount, str(e.get("PostedDate", ""))[:10],
                       f"A-Z claim {outcome}", e)

    for e in all_events["SAFETClaimEventList"]:
        aid = e.get("AmazonOrderId") or e.get("SAFETClaimId")
        eid = f"safe-t-{aid}-{e.get('PostedDate')}"
        amount = _sum_charges(e.get("ShipmentItemAdjustmentList"))
        await _persist(aid, eid, "safe_t_claim", amount, str(e.get("PostedDate", ""))[:10],
                       e.get("ReasonCode") or "SAFE-T claim", e)

    for e in all_events["ChargebackEventList"]:
        aid = e.get("AmazonOrderId")
        eid = f"chargeback-{aid}-{e.get('PostedDate')}"
        amount = _sum_charges(e.get("ShipmentItemAdjustmentList"))
        await _persist(aid, eid, "chargeback", amount, str(e.get("PostedDate", ""))[:10],
                       "Chargeback", e)

    return {
        "success": True,
        "pages": pages,
        "events_found": {k: len(v) for k, v in all_events.items()},
        "refunds_created": created,
        "refunds_skipped_existing": skipped,
    }


@api_router.get("/amazon/refunds/export")
async def export_amazon_refunds_csv(
    firm_id: Optional[str] = None,
    refund_type: Optional[str] = None,
    is_fake: Optional[bool] = None,
    is_disputed: Optional[bool] = None,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Stream filtered refunds as CSV optimised for Amazon-dispute submissions."""
    import csv
    import io
    from fastapi.responses import StreamingResponse

    query = firm_scope_filter(user, firm_id)
    if refund_type: query["refund_type"] = refund_type
    if is_fake is not None: query["is_fake"] = is_fake
    if is_disputed is not None: query["is_disputed"] = is_disputed
    if from_date: query["refund_date"] = {"$gte": from_date}
    if to_date: query.setdefault("refund_date", {})["$lte"] = to_date

    # Column order chosen for Amazon SAFE-T / A-Z dispute upload templates.
    cols = [
        "amazon_order_id", "refund_date", "refund_type", "a_to_z_outcome",
        "refund_amount", "currency", "refund_reason", "is_fake", "is_disputed",
        "product_returned", "dispute_notes",
        "firm_name", "linked_credit_note_id", "linked_journal_entry_id",
        "source", "refund_event_id", "created_at",
    ]

    async def gen():
        buf = io.StringIO()
        w = csv.writer(buf, quoting=csv.QUOTE_MINIMAL)
        w.writerow(cols)
        yield buf.getvalue(); buf.seek(0); buf.truncate()

        # Build firm_id -> name map (cheap, n=few)
        firm_names = {}
        async for f in db.firms.find({}, {"_id": 0, "id": 1, "name": 1}):
            firm_names[f["id"]] = f.get("name") or ""

        async for r in db.amazon_refunds.find(query, {"_id": 0}).sort("refund_date", -1):
            row = []
            for c in cols:
                v = r.get(c)
                if c == "firm_name":
                    v = firm_names.get(r.get("firm_id")) or ""
                if isinstance(v, bool):
                    v = "yes" if v else "no"
                if v is None:
                    v = ""
                row.append(str(v))
            w.writerow(row)
            yield buf.getvalue(); buf.seek(0); buf.truncate()

    fname = f"amazon-refunds-{(from_date or 'all')}-{(to_date or 'now')}.csv"
    return StreamingResponse(
        gen(), media_type="text/csv",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


@api_router.get("/amazon/refunds/summary")
async def amazon_refunds_summary(
    firm_id: Optional[str] = None,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Headline numbers — by type, fake vs real, total net loss."""
    query = firm_scope_filter(user, firm_id)
    if from_date:
        query["refund_date"] = {"$gte": from_date}
    if to_date:
        query.setdefault("refund_date", {})["$lte"] = to_date
    pipeline = [
        {"$match": query},
        {"$group": {
            "_id": "$refund_type",
            "n": {"$sum": 1},
            "amount": {"$sum": "$refund_amount"},
            "net_loss": {"$sum": "$net_loss"},
            "fake_count": {"$sum": {"$cond": ["$is_fake", 1, 0]}},
        }},
        {"$sort": {"amount": -1}},
    ]
    by_type = await db.amazon_refunds.aggregate(pipeline).to_list(50)
    total = await db.amazon_refunds.aggregate([
        {"$match": query},
        {"$group": {"_id": None, "n": {"$sum": 1}, "amount": {"$sum": "$refund_amount"},
                    "net_loss": {"$sum": "$net_loss"},
                    "fake_count": {"$sum": {"$cond": ["$is_fake", 1, 0]}}}}
    ]).to_list(1)
    return {
        "total": total[0] if total else {"n": 0, "amount": 0, "net_loss": 0, "fake_count": 0},
        "by_type": by_type,
    }


@api_router.get("/amazon/refunds/trend")
async def amazon_refunds_trend(
    firm_id: Optional[str] = None,
    days: int = 90,
    bucket: str = "day",   # 'day' | 'week' | 'month'
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Time-series of refunds for the chart on /admin/refunds."""
    from datetime import datetime, timezone, timedelta
    q = firm_scope_filter(user, firm_id)
    cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).strftime("%Y-%m-%d")
    q["refund_date"] = {"$gte": cutoff}
    group_fmt = {"day": 10, "week": 7, "month": 7}.get(bucket, 10)
    pipeline = [
        {"$match": q},
        {"$group": {
            "_id": {"$substr": ["$refund_date", 0, group_fmt]},
            "count": {"$sum": 1},
            "amount": {"$sum": "$refund_amount"},
            "fake_count": {"$sum": {"$cond": ["$is_fake", 1, 0]}},
            "fake_amount": {"$sum": {"$cond": ["$is_fake", "$refund_amount", 0]}},
        }},
        {"$sort": {"_id": 1}},
    ]
    return await db.amazon_refunds.aggregate(pipeline).to_list(366)


@api_router.get("/amazon/refunds/top-skus")
async def amazon_refunds_top_skus(
    firm_id: Optional[str] = None,
    limit: int = 15,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """SKUs causing most refunds — drives product-quality decisions."""
    q = firm_scope_filter(user, firm_id)
    pipeline = [
        {"$match": q},
        {"$unwind": {"path": "$items", "preserveNullAndEmptyArrays": False}},
        {"$group": {
            "_id": "$items.master_sku_id",
            "sku_code": {"$first": "$items.sku_code"},
            "sku_name": {"$first": "$items.master_sku_name"},
            "count": {"$sum": 1},
            "amount": {"$sum": "$refund_amount"},
        }},
        {"$sort": {"count": -1}},
        {"$limit": limit},
    ]
    return await db.amazon_refunds.aggregate(pipeline).to_list(limit)


@api_router.get("/amazon/refunds/dispute-stats")
async def amazon_refunds_dispute_stats(
    firm_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Dispute success rate: won (a_to_z_outcome=denied) vs lost (granted)."""
    q = firm_scope_filter(user, firm_id)
    pipeline = [
        {"$match": {**q, "is_disputed": True}},
        {"$group": {
            "_id": "$a_to_z_outcome",
            "n": {"$sum": 1},
            "amount": {"$sum": "$refund_amount"},
        }},
    ]
    rows = await db.amazon_refunds.aggregate(pipeline).to_list(10)
    total_disputed = sum(r["n"] for r in rows)
    won = next((r["n"] for r in rows if r["_id"] == "denied"), 0)
    lost = next((r["n"] for r in rows if r["_id"] == "granted"), 0)
    pending = next((r["n"] for r in rows if r["_id"] == "pending"), 0)
    return {
        "total_disputed": total_disputed,
        "won": won, "lost": lost, "pending": pending,
        "success_rate": (won / max(total_disputed - pending, 1)) if total_disputed else 0,
        "breakdown": rows,
    }


@api_router.get("/amazon/refunds/reason-distribution")
async def amazon_refunds_reason_distribution(
    firm_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Top refund reasons (free-text, top 20 frequencies)."""
    q = firm_scope_filter(user, firm_id)
    pipeline = [
        {"$match": {**q, "refund_reason": {"$nin": [None, ""]}}},
        {"$group": {
            "_id": "$refund_reason",
            "count": {"$sum": 1},
            "amount": {"$sum": "$refund_amount"},
        }},
        {"$sort": {"count": -1}},
        {"$limit": 20},
    ]
    return await db.amazon_refunds.aggregate(pipeline).to_list(20)


@api_router.post("/amazon/refunds/{refund_id}/attachments")
async def upload_refund_attachment(
    refund_id: str,
    file: UploadFile = File(...),
    note: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Attach a POD / courier proof / screenshot to a refund for dispute evidence."""
    existing = await db.amazon_refunds.find_one({"id": refund_id}, {"_id": 0, "firm_id": 1})
    if not existing:
        raise HTTPException(status_code=404, detail="Refund not found")
    assert_firm_access(user, existing.get("firm_id"))

    content = await file.read()
    if len(content) > 10 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="File exceeds 10 MB")
    safe_name = (file.filename or "evidence").replace("/", "_").replace("\\", "_")[:200]
    rel_path, _ = await storage_upload(
        file_data=content,
        folder="refund_evidence",
        filename=f"{refund_id}-{uuid.uuid4().hex[:8]}-{safe_name}",
    )
    attachment = {
        "id": str(uuid.uuid4()),
        "filename": safe_name,
        "mime_type": file.content_type or "application/octet-stream",
        "size": len(content),
        "path": rel_path,
        "note": note,
        "uploaded_by": user["id"],
        "uploaded_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
        "uploaded_at": datetime.now(timezone.utc).isoformat(),
    }
    await db.amazon_refunds.update_one(
        {"id": refund_id},
        {"$push": {"attachments": attachment},
         "$set": {"updated_at": datetime.now(timezone.utc).isoformat()}}
    )
    return attachment


@api_router.delete("/amazon/refunds/{refund_id}/attachments/{att_id}")
async def delete_refund_attachment(
    refund_id: str,
    att_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    refund = await db.amazon_refunds.find_one({"id": refund_id}, {"_id":0, "firm_id":1})
    if not refund:
        raise HTTPException(status_code=404, detail="Refund not found")
    assert_firm_access(user, refund.get("firm_id"))
    await db.amazon_refunds.update_one(
        {"id": refund_id},
        {"$pull": {"attachments": {"id": att_id}},
         "$set": {"updated_at": datetime.now(timezone.utc).isoformat()}}
    )
    return {"success": True}


@api_router.post("/amazon/refunds/bulk-update")
async def bulk_update_refunds(
    payload: dict = Body(...),
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Apply the same flag/classification change to many refunds at once.
    Body: { ids: [...], updates: { is_fake, is_disputed, refund_type, a_to_z_outcome, dispute_notes, product_returned } }
    """
    ids = payload.get("ids") or []
    updates = payload.get("updates") or {}
    if not ids or not updates:
        raise HTTPException(status_code=400, detail="ids and updates required")
    ALLOWED = {"is_fake", "is_disputed", "dispute_notes", "product_returned",
               "a_to_z_outcome", "refund_type"}
    upd = {k: v for k, v in updates.items() if k in ALLOWED}
    if not upd:
        raise HTTPException(status_code=400, detail="No editable fields supplied")
    # Firm-scope check
    scope = get_user_firm_scope(user)
    match = {"id": {"$in": ids}}
    if scope:
        match["firm_id"] = scope
    upd["updated_at"] = datetime.now(timezone.utc).isoformat()
    upd["updated_by"] = user["id"]
    r = await db.amazon_refunds.update_many(match, {"$set": upd})
    return {"modified": r.modified_count, "matched": r.matched_count}


