@api_router.post("/amazon/refunds/manual")
async def create_manual_amazon_refund(
    payload: dict = Body(...),
    user: dict = Depends(require_roles(["admin", "accountant"])),
):
    """Manual refund record (operator-entered, e.g. for A-Z claims marked fake)."""
    if not payload.get("amazon_order_id") or not payload.get("firm_id"):
        raise HTTPException(status_code=400, detail="amazon_order_id and firm_id required")
    assert_firm_access(user, payload.get("firm_id"))
    payload.setdefault("source", "manual")
    result = await record_amazon_refund(
        payload, user=user,
        auto_credit_note=payload.get("auto_credit_note", True),
        reverse_cogs=payload.get("reverse_cogs", False),
    )
    return result


@api_router.post("/amazon/scrape-tracking/{amazon_order_id}")
async def amazon_scrape_tracking(
    amazon_order_id: str,
    firm_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """
    Scrape the tracking_number + carrier from Seller Central's order page for
    orders Amazon already reports as 'Shipped' but where the CRM has no
    tracking row. Recovers AWBs that were entered directly on Seller Central
    (outside the CRM browser flow).
    """
    import re as _re
    agent = await get_browser_agent()
    if not agent or not agent.page:
        raise HTTPException(status_code=400, detail="Browser agent not started.")
    if getattr(agent.state, "value", str(agent.state)) != "logged_in":
        ok = await agent.check_login_status()
        if not ok:
            raise HTTPException(status_code=400, detail="Browser agent not logged in.")
    try:
        await agent.page.goto(
            f"https://sellercentral.amazon.in/orders-v3/order/{amazon_order_id}",
            wait_until="domcontentloaded",
            timeout=30000,
        )
        await asyncio.sleep(2)
        txt = await agent.page.evaluate("() => document.body.innerText || ''")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Scrape failed: {e}")

    tm = _re.search(r"Tracking\s*(?:ID|Number|#)\s*:?\s*([A-Za-z0-9-]{6,30})", txt, _re.IGNORECASE)
    cm = _re.search(r"Carrier\s*:?\s*([A-Za-z][A-Za-z &.-]{1,40})", txt, _re.IGNORECASE)
    tracking = tm.group(1).strip() if tm else None
    carrier = cm.group(1).strip() if cm else None
    if not tracking or tracking.lower() in ("none","n/a","-"):
        return {"success": True, "found": False, "amazon_order_id": amazon_order_id}

    now = datetime.now(timezone.utc).isoformat()
    await db.amazon_orders.update_one(
        {"amazon_order_id": amazon_order_id, "firm_id": firm_id},
        {"$set": {
            "tracking_number": tracking,
            "carrier_code": (carrier or "other").lower().replace(" ", "_"),
            "tracking_source": "amazon_scrape",
            "tracking_scraped_at": now,
            "updated_at": now,
        }},
    )
    return {
        "success": True, "found": True, "amazon_order_id": amazon_order_id,
        "tracking_number": tracking, "carrier": carrier,
    }


@api_router.post("/amazon/scrape-and-save-pii/{amazon_order_id}")
async def amazon_scrape_and_save_pii(
    amazon_order_id: str,
    firm_id: str,
    dry_run: bool = False,
    user: dict = Depends(require_roles(["admin"]))
):
    """
    Scrape one Amazon order's PII from Seller Central via the browser agent
    and write it onto the order. Requires the agent to be started and logged in.

    With ?dry_run=true: returns the scraped + normalised payload but does NOT
    write to the DB and does NOT audit-log. Used by the 'Auto-fill from Amazon'
    test button so the user can spot-check the scraper before committing.
    """
    agent = await get_browser_agent()
    if not agent or not agent.page:
        raise HTTPException(
            status_code=400,
            detail="Browser agent not started. Open /admin/browser-agent and start it first."
        )
    if getattr(agent.state, "value", str(agent.state)) != "logged_in":
        ok = await agent.check_login_status()
        if not ok:
            raise HTTPException(
                status_code=400,
                detail="Browser agent not logged in to Seller Central. Sign in via /admin/browser-agent."
            )

    try:
        scraped = await agent.scrape_order_pii(amazon_order_id)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Scrape failed: {e}")

    if dry_run:
        # Return the normalised shape WITHOUT writing or auditing
        return {
            "success": True,
            "dry_run": True,
            "amazon_order_id": amazon_order_id,
            "scraped": scraped,
            "preview": _normalize_scraped_pii(scraped),
        }

    saved = await _save_scraped_pii(amazon_order_id, firm_id, scraped, user["id"])

    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "amazon_pii_scraped",
        "entity_type": "amazon_order",
        "entity_id": amazon_order_id,
        "entity_name": amazon_order_id,
        "performed_by": user["id"],
        "performed_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
        "details": {
            "phone_found_in": saved.get("phone_found_in"),
            "needs_phone_review": saved.get("needs_phone_review"),
            "city": saved.get("city_manual"),
            "state": saved.get("state_manual"),
        },
        "timestamp": datetime.now(timezone.utc).isoformat(),
    })

    return {
        "success": True,
        "amazon_order_id": amazon_order_id,
        "scraped": scraped,
        "saved": saved,
    }


async def _bulk_scrape_worker(firm_id: str, order_ids: List[str], user_id: str):
    """Background task: scrape PII for many Amazon orders sequentially."""
    job = _amazon_scrape_jobs[firm_id]
    agent = await get_browser_agent()

    for amazon_order_id in order_ids:
        if job.get("cancel_requested"):
            job["state"] = "cancelled"
            break
        job["current_order_id"] = amazon_order_id
        try:
            scraped = await agent.scrape_order_pii(amazon_order_id)
            saved = await _save_scraped_pii(amazon_order_id, firm_id, scraped, user_id)
            job["succeeded"] += 1
            if saved.get("needs_phone_review"):
                job["needs_review"] += 1
            if saved.get("crm_status") == "cancelled" and saved.get("cancelled_on_amazon_detected"):
                job["cancelled"] = job.get("cancelled", 0) + 1
            await broadcast_status({
                "type": "bulk_scrape_progress",
                "firm_id": firm_id,
                "done": job["succeeded"] + job["failed"],
                "total": job["total"],
                "current": amazon_order_id,
                "needs_review": job["needs_review"],
                "cancelled": job.get("cancelled", 0),
                "succeeded": job["succeeded"],
                "failed": job["failed"],
            })
        except Exception as e:
            job["failed"] += 1
            job["last_error"] = f"{amazon_order_id}: {e}"
            logger.exception("Bulk scrape failed for %s", amazon_order_id)
            await broadcast_status({
                "type": "bulk_scrape_error",
                "firm_id": firm_id,
                "order_id": amazon_order_id,
                "error": str(e),
            })
        # Tiny breath between orders to avoid hammering Seller Central
        await asyncio.sleep(0.8)

    if job["state"] != "cancelled":
        job["state"] = "done"
    job["current_order_id"] = None
    job["finished_at"] = datetime.now(timezone.utc).isoformat()

    # Some jobs (e.g. the courier-board "Pull last N days") want the Delhivery
    # board repopulated the moment scraping finishes, rather than waiting for the
    # next 30-min poll. Gated by a job flag so other callers are unaffected.
    if job.get("refresh_board_on_done"):
        try:
            summary = await refresh_delhivery_board()
            job["board_refresh"] = {
                "checked": summary.get("checked", 0),
                "orders_in_universe": summary.get("orders_in_universe", 0),
                "ran_at": summary.get("ran_at"),
            }
        except Exception as e:
            logger.error(f"Post-scrape board refresh failed: {e}")
            job["board_refresh"] = {"error": str(e)}


@api_router.post("/amazon/bulk-scrape-mfn-pending")
async def amazon_bulk_scrape_mfn_pending(
    firm_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """
    Kick off a background job that scrapes PII from Seller Central for every
    MFN Pending order under this firm and saves it. Only one job per firm at a time.
    """
    existing = _amazon_scrape_jobs.get(firm_id)
    if existing and existing.get("state") == "running":
        raise HTTPException(
            status_code=409,
            detail=f"A scrape job is already running for this firm ({existing.get('succeeded',0)+existing.get('failed',0)}/{existing.get('total','?')})"
        )

    agent = await get_browser_agent()
    if not agent or not agent.page:
        raise HTTPException(status_code=400, detail="Browser agent not started.")
    if getattr(agent.state, "value", str(agent.state)) != "logged_in":
        ok = await agent.check_login_status()
        if not ok:
            raise HTTPException(status_code=400, detail="Browser agent not logged in to Seller Central.")

    pending = await db.amazon_orders.find(
        {"firm_id": firm_id, "crm_status": "pending", "is_easy_ship": False},
        {"_id": 0, "amazon_order_id": 1}
    ).to_list(2000)
    order_ids = [o["amazon_order_id"] for o in pending if o.get("amazon_order_id")]

    if not order_ids:
        return {"success": True, "message": "No MFN Pending orders to scrape.", "total": 0}

    _amazon_scrape_jobs[firm_id] = {
        "state": "running",
        "total": len(order_ids),
        "succeeded": 0,
        "failed": 0,
        "needs_review": 0,
        "cancelled": 0,
        "current_order_id": None,
        "started_at": datetime.now(timezone.utc).isoformat(),
        "started_by": user["id"],
        "cancel_requested": False,
        "last_error": None,
    }
    asyncio.create_task(_bulk_scrape_worker(firm_id, order_ids, user["id"]))

    return {
        "success": True,
        "message": f"Started scraping {len(order_ids)} MFN Pending orders.",
        "total": len(order_ids),
    }


@api_router.post("/amazon/bulk-rescan-awaiting-tracking")
async def amazon_bulk_rescan_awaiting_tracking(
    firm_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Re-scrape every order stuck in 'awaiting tracking' (crm_status =
    details_captured, no tracking_number yet) and promote it to amazon_shipped
    if Amazon now shows tracking on the order page.

    Built for the case where 'Auto-fill all from Amazon' was run before the
    scraper learned to read the Tracking ID field — orders captured back
    then are sitting in the Awaiting Tracking tab even though Amazon already
    has their tracking. Reuses the existing bulk worker, which calls into
    _save_scraped_pii — the save path picks up tracking_number and flips
    crm_status automatically.

    Idempotent: orders whose Amazon page still doesn't show tracking just
    get a refreshed PII timestamp and stay in details_captured."""
    existing = _amazon_scrape_jobs.get(firm_id)
    if existing and existing.get("state") == "running":
        raise HTTPException(
            status_code=409,
            detail=f"A scrape job is already running for this firm "
                   f"({existing.get('succeeded',0)+existing.get('failed',0)}/"
                   f"{existing.get('total','?')})"
        )

    agent = await get_browser_agent()
    if not agent or not agent.page:
        raise HTTPException(status_code=400, detail="Browser agent not started.")
    if getattr(agent.state, "value", str(agent.state)) != "logged_in":
        ok = await agent.check_login_status()
        if not ok:
            raise HTTPException(status_code=400,
                                detail="Browser agent not logged in to Seller Central.")

    # Orders missing a tracking number that Amazon may now show one for:
    #   - details_captured (the classic "Awaiting Tracking" tab), any age, AND
    #   - amazon_shipped within the last 30 days — Amazon reported these Shipped
    #     (so the sync flipped crm_status) but their tracking was never scraped
    #     back, leaving them invisible to the courier board. Scoped to recent so
    #     we don't re-scrape thousands of long-delivered historical orders.
    recent_cutoff = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
    no_tracking = {"$or": [
        {"tracking_number": {"$exists": False}},
        {"tracking_number": None},
        {"tracking_number": ""},
    ]}
    stuck = await db.amazon_orders.find(
        {
            "firm_id": firm_id,
            "$and": [
                no_tracking,
                {"$or": [
                    {"crm_status": "details_captured"},
                    {"crm_status": "amazon_shipped", "purchase_date": {"$gte": recent_cutoff}},
                ]},
            ],
        },
        {"_id": 0, "amazon_order_id": 1},
    ).to_list(5000)
    order_ids = [o["amazon_order_id"] for o in stuck if o.get("amazon_order_id")]

    if not order_ids:
        return {"success": True,
                "message": "No orders stuck in Awaiting Tracking for this firm.",
                "total": 0}

    _amazon_scrape_jobs[firm_id] = {
        "state": "running",
        "total": len(order_ids),
        "succeeded": 0,
        "failed": 0,
        "needs_review": 0,
        "cancelled": 0,
        "current_order_id": None,
        "started_at": datetime.now(timezone.utc).isoformat(),
        "started_by": user["id"],
        "cancel_requested": False,
        "last_error": None,
        "job_kind": "rescan_awaiting_tracking",
    }
    asyncio.create_task(_bulk_scrape_worker(firm_id, order_ids, user["id"]))

    return {
        "success": True,
        "message": f"Re-scraping {len(order_ids)} orders stuck in Awaiting Tracking.",
        "total": len(order_ids),
    }


@api_router.get("/amazon/bulk-scrape-status")
async def amazon_bulk_scrape_status(
    firm_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Poll endpoint for the bulk scrape job state for a firm."""
    job = _amazon_scrape_jobs.get(firm_id)
    if not job:
        return {"state": "idle"}
    return job


@api_router.post("/amazon/bulk-scrape-cancel")
async def amazon_bulk_scrape_cancel(
    firm_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Ask the in-flight bulk scrape job to stop after the current order."""
    job = _amazon_scrape_jobs.get(firm_id)
    if not job or job.get("state") != "running":
        raise HTTPException(status_code=400, detail="No running scrape job for this firm")
    job["cancel_requested"] = True
    return {"success": True, "message": "Cancellation requested; will stop after current order."}


@api_router.post("/courier/delhivery-board/pull-recent-amazon")
async def pull_recent_amazon_tracking(
    firm_id: str,
    days: int = 15,
    user: dict = Depends(require_roles(["admin"]))
):
    """One-click for the Courier Tracking board: scrape the last `days` of Amazon
    orders that are still missing a tracking number (off Seller Central), write
    their AWBs back, and auto-refresh the Delhivery board the moment the scrape
    finishes — so freshly-shipped parcels appear on the board without waiting for
    the 30-min poll.

    Mirrors /amazon/bulk-rescan-awaiting-tracking but bounded to a recent window
    and with the board-refresh hook. Requires the browser agent to be signed in
    to Seller Central (the operator does that under Admin → Browser Agents)."""
    days = max(1, min(int(days or 15), 60))

    existing = _amazon_scrape_jobs.get(firm_id)
    if existing and existing.get("state") == "running":
        raise HTTPException(
            status_code=409,
            detail=f"A scrape job is already running for this firm "
                   f"({existing.get('succeeded',0)+existing.get('failed',0)}/"
                   f"{existing.get('total','?')})")

    agent = await get_browser_agent()
    if not agent or not agent.page:
        raise HTTPException(
            status_code=400,
            detail="Browser agent not started. Open Admin → Browser Agents and sign in to Amazon first.")
    if getattr(agent.state, "value", str(agent.state)) != "logged_in":
        ok = await agent.check_login_status()
        if not ok:
            raise HTTPException(
                status_code=400,
                detail="Browser agent not logged in to Seller Central. "
                       "Open Admin → Browser Agents and sign in to Amazon first.")

    # Recent orders that may now carry a tracking number on their Amazon page but
    # don't have one stored yet. Scoped to the last `days` so we only touch the
    # window the operator asked for (not the whole historical backlog).
    cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
    no_tracking = {"$or": [
        {"tracking_number": {"$exists": False}},
        {"tracking_number": None},
        {"tracking_number": ""},
    ]}
    stuck = await db.amazon_orders.find(
        {
            "firm_id": firm_id,
            "purchase_date": {"$gte": cutoff},
            "$and": [
                no_tracking,
                {"crm_status": {"$in": ["pending", "details_captured", "amazon_shipped"]}},
            ],
        },
        {"_id": 0, "amazon_order_id": 1},
    ).to_list(5000)
    order_ids = [o["amazon_order_id"] for o in stuck if o.get("amazon_order_id")]

    if not order_ids:
        # Nothing to scrape — still refresh the board so any already-scraped recent
        # AWBs surface immediately.
        summary = await refresh_delhivery_board()
        return {
            "success": True, "total": 0,
            "message": f"No orders missing tracking in the last {days} days. Board refreshed "
                       f"({summary.get('checked', 0)} parcels polled).",
            "board_checked": summary.get("checked", 0),
        }

    _amazon_scrape_jobs[firm_id] = {
        "state": "running",
        "total": len(order_ids),
        "succeeded": 0, "failed": 0, "needs_review": 0, "cancelled": 0,
        "current_order_id": None,
        "started_at": datetime.now(timezone.utc).isoformat(),
        "started_by": user["id"],
        "cancel_requested": False,
        "last_error": None,
        "job_kind": "pull_recent_amazon",
        "refresh_board_on_done": True,
        "window_days": days,
    }
    asyncio.create_task(_bulk_scrape_worker(firm_id, order_ids, user["id"]))

    return {
        "success": True,
        "total": len(order_ids),
        "message": f"Scraping {len(order_ids)} orders from the last {days} days. "
                   f"The tracking board updates automatically when the scrape finishes.",
    }


async def _push_tracking_to_amazon_internal(amazon_order_id: str, firm_id: str) -> dict:
    """Push tracking for a single Amazon order via SP-API. Returns
    {success, status_code, message?, error?, amazon_response?}.

    Does NOT raise HTTPException — both the manual endpoint and the scheduled
    job call this helper, and the scheduler must keep going after one order's
    failure. The endpoint wrapper below translates the result into HTTP for
    the UI.
    """
    import aiohttp

    order = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id, "firm_id": firm_id})
    if not order:
        return {"success": False, "status_code": 404, "error": "Amazon order not found"}
    if not order.get("tracking_number"):
        return {"success": False, "status_code": 400, "error": "No tracking number set for this order"}

    creds = await db.marketplace_credentials.find_one(
        {"firm_id": firm_id, "platform": "amazon", "is_active": True}
    )
    if not creds:
        return {"success": False, "status_code": 400, "error": "Amazon credentials not configured"}

    try:
        access_token = await get_amazon_access_token(creds)
        carrier_mapping = {
            "bluedart": "Blue Dart", "delhivery": "Delhivery", "dtdc": "DTDC",
            "fedex": "FedEx", "xpressbees": "Xpressbees", "ecom_express": "Ecom Express",
            "shadowfax": "Shadowfax", "professional_couriers": "Professional Couriers",
            "gati": "Gati", "other": "Other",
        }
        carrier_code = order.get("carrier_code", "")
        amazon_carrier = carrier_mapping.get(carrier_code.lower().replace(" ", "_"), carrier_code)
        now = datetime.now(timezone.utc)
        order_items = [
            {"orderItemId": it.get("order_item_id"), "quantity": it.get("quantity", 1)}
            for it in order.get("items", [])
        ]
        shipment_data = {
            "marketplaceId": creds.get("marketplace_id", "A21TJRUUN4KGV"),  # India
            "packageDetail": {
                "packageReferenceId": f"PKG-{amazon_order_id[:20]}",
                "carrierCode": amazon_carrier,
                "trackingNumber": order.get("tracking_number"),
                "shipDate": now.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "orderItems": order_items,
            },
        }
        url = f"https://sellingpartnerapi-fe.amazon.com/orders/v0/orders/{amazon_order_id}/shipmentConfirmation"
        headers = {"x-amz-access-token": access_token, "Content-Type": "application/json"}

        async with aiohttp.ClientSession() as session:
            async with session.post(url, headers=headers, json=shipment_data) as response:
                response_text = await response.text()
                if response.status in (200, 204):
                    await db.amazon_orders.update_one(
                        {"amazon_order_id": amazon_order_id},
                        {"$set": {
                            "amazon_tracking_pushed": True,
                            "amazon_tracking_pushed_at": now.isoformat(),
                            "amazon_tracking_push_response": response_text,
                            "updated_at": now.isoformat(),
                        }},
                    )
                    return {
                        "success": True,
                        "status_code": response.status,
                        "message": f"Tracking {order.get('tracking_number')} successfully pushed to Amazon",
                        "amazon_response": response_text,
                    }
                if response.status == 403:
                    error_msg = (
                        "Amazon API access denied. Ensure your SP-API app has "
                        "'Direct-to-Consumer Shipping' role enabled in Seller Central "
                        "and the refresh token has correct scopes."
                    )
                    await db.amazon_orders.update_one(
                        {"amazon_order_id": amazon_order_id},
                        {"$set": {
                            "amazon_tracking_push_error": f"403 Forbidden: {response_text}",
                            "amazon_tracking_push_attempted_at": now.isoformat(),
                        }},
                    )
                    return {"success": False, "status_code": 403, "error": error_msg}
                # Other error
                error_detail = f"Amazon API Error ({response.status}): {response_text}"
                await db.amazon_orders.update_one(
                    {"amazon_order_id": amazon_order_id},
                    {"$set": {
                        "amazon_tracking_push_error": error_detail,
                        "amazon_tracking_push_attempted_at": now.isoformat(),
                    }},
                )
                return {"success": False, "status_code": response.status, "error": error_detail}
    except aiohttp.ClientError as e:
        return {"success": False, "status_code": 500, "error": f"Network error communicating with Amazon: {str(e)}"}
    except Exception as e:
        return {"success": False, "status_code": 500, "error": f"Error pushing tracking to Amazon: {str(e)}"}


@api_router.post("/amazon/push-tracking")
async def push_tracking_to_amazon(
    amazon_order_id: str,
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant", "dispatcher"]))
):
    """Push tracking information to Amazon via SP-API Orders confirmShipment."""
    result = await _push_tracking_to_amazon_internal(amazon_order_id, firm_id)
    if not result.get("success"):
        raise HTTPException(status_code=result.get("status_code", 500), detail=result.get("error", "Push failed"))
    return result


@api_router.get("/amazon/unmapped-skus/{firm_id}")
async def get_unmapped_skus(
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get list of Amazon SKUs that are not mapped to Master SKUs"""
    # Get all unique SKUs from orders
    pipeline = [
        {"$match": {"firm_id": firm_id}},
        {"$unwind": "$items"},
        {"$match": {"items.master_sku_id": None}},
        {"$group": {
            "_id": "$items.amazon_sku",
            "asin": {"$first": "$items.asin"},
            "title": {"$first": "$items.title"},
            "count": {"$sum": 1}
        }},
        {"$sort": {"count": -1}}
    ]
    
    unmapped_raw = await db.amazon_orders.aggregate(pipeline).to_list(100)
    
    # Filter out SKUs that have aliases in Master SKUs
    unmapped = []
    for item in unmapped_raw:
        amazon_sku = item["_id"]
        if not amazon_sku:
            continue
            
        # Check if there's a Master SKU with this alias
        alias_match = await db.master_skus.find_one({
            "aliases": {"$elemMatch": {"alias_code": amazon_sku, "platform": {"$regex": "^amazon$", "$options": "i"}}}
        })
        
        if not alias_match:
            # Also check for exact SKU code match
            sku_match = await db.master_skus.find_one({"sku_code": amazon_sku})
            if not sku_match:
                unmapped.append({
                    "amazon_sku": amazon_sku,
                    "asin": item.get("asin"),
                    "title": item.get("title"),
                    "order_count": item["count"]
                })
    
    return unmapped


@api_router.post("/amazon/sync-alias-mappings")
async def sync_amazon_alias_mappings(
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Sync Amazon orders with Master SKU aliases.
    This will auto-map any Amazon SKUs that match Master SKU aliases.
    """
    # Get all orders for this firm
    orders = await db.amazon_orders.find({"firm_id": firm_id}).to_list(1000)
    
    mapped_count = 0
    skus_mapped = []
    
    for order in orders:
        items_updated = False
        updated_items = []
        
        for item in order.get("items", []):
            amazon_sku = item.get("amazon_sku") or item.get("seller_sku")
            
            # Skip if already mapped
            if item.get("master_sku_id"):
                updated_items.append(item)
                continue
            
            if amazon_sku:
                # Check for alias match
                master_sku_doc = await db.master_skus.find_one({
                    "$or": [
                        {"sku_code": amazon_sku},
                        {"aliases": {"$elemMatch": {"alias_code": amazon_sku, "platform": {"$regex": "^amazon$", "$options": "i"}}}}
                    ]
                }, {"_id": 0})
                
                if master_sku_doc:
                    # Update item with master SKU info
                    item["master_sku_id"] = master_sku_doc.get("id")
                    item["master_sku_code"] = master_sku_doc.get("sku_code")
                    items_updated = True
                    
                    # Create SKU mapping if doesn't exist
                    existing_mapping = await db.amazon_sku_mappings.find_one({
                        "firm_id": firm_id,
                        "amazon_sku": amazon_sku
                    })
                    if not existing_mapping:
                        await db.amazon_sku_mappings.insert_one({
                            "id": str(uuid.uuid4()),
                            "firm_id": firm_id,
                            "amazon_sku": amazon_sku,
                            "master_sku_id": master_sku_doc.get("id"),
                            "master_sku_name": master_sku_doc.get("name"),
                            "sku_code": master_sku_doc.get("sku_code"),
                            "auto_mapped": True,
                            "mapped_via": "alias_sync",
                            "created_at": datetime.now(timezone.utc).isoformat()
                        })
                        mapped_count += 1
                        if amazon_sku not in skus_mapped:
                            skus_mapped.append(amazon_sku)
            
            updated_items.append(item)
        
        # Update order if any items were mapped
        if items_updated:
            await db.amazon_orders.update_one(
                {"_id": order["_id"]},
                {"$set": {"items": updated_items}}
            )
    
    return {
        "success": True,
        "message": f"Synced {mapped_count} SKU mappings from aliases",
        "mapped_count": mapped_count,
        "skus_mapped": skus_mapped
    }


@api_router.get("/sales-orders")
async def list_sales_orders(
    category: Optional[str] = None,  # new_order, repair, walkin
    order_source: Optional[str] = None,  # amazon, flipkart, website, direct
    payment_status: Optional[str] = None,  # unpaid, pending, paid
    firm_id: Optional[str] = None,
    search: Optional[str] = None,
    limit: int = 100,
    skip: int = 0,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """List sales orders with filters"""
    query = {}
    
    if category:
        query["order_category"] = category
    if order_source:
        query["order_source"] = order_source
    if payment_status:
        query["payment_status"] = payment_status
    if firm_id:
        query["firm_id"] = firm_id
    if search:
        query["$or"] = [
            {"order_number": {"$regex": search, "$options": "i"}},
            {"customer_name": {"$regex": search, "$options": "i"}},
            {"marketplace_order_id": {"$regex": search, "$options": "i"}},
            {"order_id": {"$regex": search, "$options": "i"}},
            {"phone": {"$regex": search, "$options": "i"}}
        ]
    
    orders = await db.sales_orders.find(query, {"_id": 0}).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    total = await db.sales_orders.count_documents(query)

    return {"orders": orders, "total": total}


# ──────────────────────────────────────────────────────────────────────────────
# LEGAL / LAWYER PORTAL — staff mark an order for a legal notice; the lawyer
# (role "lawyer") sees the flagged orders read-only with notice-ready details.
# ──────────────────────────────────────────────────────────────────────────────
class LegalMarkBody(BaseModel):
    reason: str
    claim_amount: Optional[float] = None
    note: Optional[str] = None


@api_router.post("/sales-orders/{order_id}/mark-legal")
async def mark_sales_order_legal(order_id: str, body: LegalMarkBody,
                                 user: dict = Depends(require_roles(["admin", "accountant"]))):
    """Flag a sales order for a legal notice — it then appears in the lawyer portal."""
    order = await db.sales_orders.find_one({"id": order_id}, {"_id": 0})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    reason = (body.reason or "").strip()
    if not reason:
        raise HTTPException(status_code=400, detail="A reason is required to mark for legal")
    now = datetime.now(timezone.utc).isoformat()
    claim = body.claim_amount if body.claim_amount is not None else order.get("total_amount", 0)
    await db.sales_orders.update_one({"id": order_id}, {"$set": {
        "legal_flag": True,
        "legal_reason": reason,
        "legal_note": (body.note or "").strip() or None,
        "legal_claim_amount": claim,
        "legal_notice_status": order.get("legal_notice_status") or "pending",
        "legal_marked_at": now,
        "legal_marked_by": user["id"],
        "legal_marked_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
        "updated_at": now,
    }})
    return {"success": True, "message": "Marked for legal notice", "order_id": order_id}


@api_router.post("/sales-orders/{order_id}/unmark-legal")
async def unmark_sales_order_legal(order_id: str,
                                   user: dict = Depends(require_roles(["admin", "accountant"]))):
    """Remove the legal flag from a sales order."""
    res = await db.sales_orders.update_one({"id": order_id}, {"$set": {
        "legal_flag": False, "legal_notice_status": None,
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }})
    if not res.matched_count:
        raise HTTPException(status_code=404, detail="Order not found")
    return {"success": True, "message": "Legal flag removed", "order_id": order_id}


@api_router.get("/lawyer/legal-orders")
async def lawyer_legal_orders(status: Optional[str] = None,
                              user: dict = Depends(require_roles(["lawyer", "admin"]))):
    """Read-only list of orders flagged for a legal notice, enriched with the customer's
    full contact details (from the party master) so the lawyer can draft/send notices."""
    q = {"legal_flag": True}
    if status in ("pending", "sent"):
        q["legal_notice_status"] = status
    orders = await db.sales_orders.find(q, {"_id": 0}).sort("legal_marked_at", -1).to_list(1000)
    out = []
    for o in orders:
        party = None
        ph = (o.get("phone") or "").strip()
        if ph:
            digits = re.sub(r"\D", "", ph)[-10:]
            if digits:
                party = await db.parties.find_one(
                    {"phone": {"$regex": digits + "$"}},
                    {"_id": 0, "name": 1, "email": 1, "address": 1, "city": 1, "state": 1,
                     "pincode": 1, "gstin": 1, "gst_number": 1, "current_balance": 1})
        out.append({
            "id": o.get("id"),
            "order_number": o.get("order_number"),
            "order_date": o.get("created_at"),
            "firm_name": o.get("firm_name"),
            "order_source": o.get("order_source"),
            "product": o.get("master_sku_name") or o.get("sku"),
            "quantity": o.get("quantity"),
            "order_amount": o.get("total_amount"),
            "payment_status": o.get("payment_status"),
            # who to serve
            "customer_name": o.get("customer_name"),
            "phone": o.get("phone"),
            "email": (party or {}).get("email"),
            "address": o.get("address") or (party or {}).get("address"),
            "city": o.get("city") or (party or {}).get("city"),
            "state": o.get("state") or (party or {}).get("state"),
            "pincode": o.get("pincode") or (party or {}).get("pincode"),
            "gstin": (party or {}).get("gstin") or (party or {}).get("gst_number"),
            "party_balance": (party or {}).get("current_balance"),
            # the legal claim
            "claim_amount": o.get("legal_claim_amount", o.get("total_amount")),
            "reason": o.get("legal_reason"),
            "note": o.get("legal_note"),
            "marked_by": o.get("legal_marked_by_name"),
            "marked_at": o.get("legal_marked_at"),
            "notice_status": o.get("legal_notice_status") or "pending",
            "notice_sent_at": o.get("legal_notice_sent_at"),
            "notice_ref": o.get("legal_notice_ref"),
        })
    summary = {
        "total": len(out),
        "pending": sum(1 for x in out if x["notice_status"] == "pending"),
        "sent": sum(1 for x in out if x["notice_status"] == "sent"),
        "total_claim": round(sum(float(x.get("claim_amount") or 0) for x in out), 2),
    }
    return {"success": True, "summary": summary, "orders": out}


class LegalNoticeBody(BaseModel):
    notice_ref: Optional[str] = None
