@api_router.put("/admin/incentive-config/{config_id}")
async def update_incentive_config(
    config_id: str,
    update: IncentiveConfigUpdate,
    user: dict = Depends(require_roles(["admin"]))
):
    """Update incentive configuration"""
    config = await db.incentive_configs.find_one({"id": config_id})
    if not config:
        raise HTTPException(status_code=404, detail="Configuration not found")
    
    update_data = {"updated_at": datetime.now(timezone.utc).isoformat()}
    
    if update.incentive_type is not None:
        update_data["incentive_type"] = update.incentive_type
    if update.fixed_amount is not None:
        update_data["fixed_amount"] = update.fixed_amount
    if update.percentage is not None:
        update_data["percentage"] = update.percentage
    if update.min_sale_value is not None:
        update_data["min_sale_value"] = update.min_sale_value
    if update.max_incentive is not None:
        update_data["max_incentive"] = update.max_incentive
    if update.notes is not None:
        update_data["notes"] = update.notes
    if update.is_active is not None:
        update_data["is_active"] = update.is_active
    
    await db.incentive_configs.update_one({"id": config_id}, {"$set": update_data})
    
    return {"success": True, "message": "Configuration updated"}


# Admin: View and manage all incentives
@api_router.get("/admin/incentives")
async def list_all_incentives(
    month: Optional[str] = None,
    agent_id: Optional[str] = None,
    status: Optional[str] = None,
    user: dict = Depends(require_roles(["admin"]))
):
    """List all incentive records"""
    query = {}
    if month:
        query["month"] = month
    if agent_id:
        query["agent_id"] = agent_id
    if status:
        query["status"] = status
    
    incentives = await db.incentives.find(query, {"_id": 0}).sort("created_at", -1).to_list(500)
    
    # Calculate summary
    total_amount = sum(i.get("incentive_amount", 0) for i in incentives)
    pending_amount = sum(i.get("incentive_amount", 0) for i in incentives if i.get("status") == "pending")
    paid_amount = sum(i.get("incentive_amount", 0) for i in incentives if i.get("status") == "paid")
    
    return {
        "incentives": incentives,
        "summary": {
            "total_count": len(incentives),
            "total_amount": round(total_amount, 2),
            "pending_amount": round(pending_amount, 2),
            "paid_amount": round(paid_amount, 2)
        }
    }


@api_router.get("/admin/incentives/summary")
async def get_incentives_summary(
    month: Optional[str] = None,
    user: dict = Depends(require_roles(["admin"]))
):
    """Get incentives summary by agent"""
    query = {}
    if month:
        query["month"] = month
    else:
        # Default to current month
        query["month"] = datetime.now(timezone.utc).strftime("%Y-%m")
    
    incentives = await db.incentives.find(query, {"_id": 0}).to_list(1000)
    
    # Group by agent
    by_agent = {}
    for inc in incentives:
        agent_id = inc.get("agent_id")
        if agent_id not in by_agent:
            by_agent[agent_id] = {
                "agent_id": agent_id,
                "agent_name": inc.get("agent_name", "Unknown"),
                "total_sales": 0,
                "total_incentive": 0,
                "pending_incentive": 0,
                "paid_incentive": 0,
                "conversions": 0
            }
        
        by_agent[agent_id]["total_sales"] += inc.get("sale_value", 0)
        by_agent[agent_id]["total_incentive"] += inc.get("incentive_amount", 0)
        by_agent[agent_id]["conversions"] += 1
        
        if inc.get("status") == "pending":
            by_agent[agent_id]["pending_incentive"] += inc.get("incentive_amount", 0)
        elif inc.get("status") == "paid":
            by_agent[agent_id]["paid_incentive"] += inc.get("incentive_amount", 0)
    
    # Sort by total incentive
    summary = sorted(by_agent.values(), key=lambda x: x["total_incentive"], reverse=True)
    
    return {
        "month": query["month"],
        "agents": summary,
        "totals": {
            "total_incentive": round(sum(a["total_incentive"] for a in summary), 2),
            "pending_incentive": round(sum(a["pending_incentive"] for a in summary), 2),
            "paid_incentive": round(sum(a["paid_incentive"] for a in summary), 2),
            "total_conversions": sum(a["conversions"] for a in summary)
        }
    }


@api_router.post("/admin/incentives/{incentive_id}/approve")
async def approve_incentive(
    incentive_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Approve an incentive for payment"""
    incentive = await db.incentives.find_one({"id": incentive_id})
    if not incentive:
        raise HTTPException(status_code=404, detail="Incentive not found")
    
    if incentive.get("status") != "pending":
        raise HTTPException(status_code=400, detail="Only pending incentives can be approved")
    
    now = datetime.now(timezone.utc)
    
    await db.incentives.update_one(
        {"id": incentive_id},
        {"$set": {
            "status": "approved",
            "approved_at": now.isoformat(),
            "approved_by": user["id"]
        }}
    )
    
    return {"success": True, "message": "Incentive approved"}


@api_router.post("/admin/incentives/{incentive_id}/mark-paid")
async def mark_incentive_paid(
    incentive_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Mark incentive as paid"""
    incentive = await db.incentives.find_one({"id": incentive_id})
    if not incentive:
        raise HTTPException(status_code=404, detail="Incentive not found")
    
    if incentive.get("status") not in ["pending", "approved"]:
        raise HTTPException(status_code=400, detail="Cannot mark as paid")
    
    now = datetime.now(timezone.utc)
    
    await db.incentives.update_one(
        {"id": incentive_id},
        {"$set": {
            "status": "paid",
            "paid_at": now.isoformat(),
            "paid_by": user["id"]
        }}
    )
    
    return {"success": True, "message": "Incentive marked as paid"}


@api_router.post("/admin/incentives/bulk-approve")
async def bulk_approve_incentives(
    agent_id: Optional[str] = None,
    month: Optional[str] = None,
    user: dict = Depends(require_roles(["admin"]))
):
    """Bulk approve pending incentives"""
    query = {"status": "pending"}
    if agent_id:
        query["agent_id"] = agent_id
    if month:
        query["month"] = month
    
    now = datetime.now(timezone.utc)
    
    result = await db.incentives.update_many(
        query,
        {"$set": {
            "status": "approved",
            "approved_at": now.isoformat(),
            "approved_by": user["id"]
        }}
    )
    
    return {"success": True, "message": f"Approved {result.modified_count} incentives"}


@api_router.post("/admin/incentives/bulk-paid")
async def bulk_mark_paid(
    agent_id: Optional[str] = None,
    month: Optional[str] = None,
    user: dict = Depends(require_roles(["admin"]))
):
    """Bulk mark incentives as paid"""
    query = {"status": {"$in": ["pending", "approved"]}}
    if agent_id:
        query["agent_id"] = agent_id
    if month:
        query["month"] = month
    
    now = datetime.now(timezone.utc)
    
    result = await db.incentives.update_many(
        query,
        {"$set": {
            "status": "paid",
            "paid_at": now.isoformat(),
            "paid_by": user["id"]
        }}
    )
    
    return {"success": True, "message": f"Marked {result.modified_count} incentives as paid"}


@api_router.put("/admin/incentives/{incentive_id}")
async def update_incentive(
    incentive_id: str,
    data: dict,
    user: dict = Depends(require_roles(["admin"]))
):
    """Update an incentive record"""
    incentive = await db.incentives.find_one({"id": incentive_id})
    if not incentive:
        raise HTTPException(status_code=404, detail="Incentive not found")
    
    # Only allow editing if not already paid
    if incentive.get("status") == "paid":
        raise HTTPException(status_code=400, detail="Cannot edit paid incentives")
    
    update_dict = {}
    
    if "amount" in data and data["amount"] is not None:
        update_dict["incentive_amount"] = float(data["amount"])
    if "reason" in data and data["reason"] is not None:
        update_dict["reason"] = data["reason"]
    if "month" in data and data["month"] is not None:
        update_dict["month"] = data["month"]
    if "status" in data and data["status"] in ["pending", "approved"]:
        update_dict["status"] = data["status"]
    
    if update_dict:
        update_dict["updated_at"] = datetime.now(timezone.utc).isoformat()
        update_dict["updated_by"] = user["id"]
        await db.incentives.update_one({"id": incentive_id}, {"$set": update_dict})
    
    return {"success": True, "message": "Incentive updated successfully"}


@api_router.delete("/admin/incentives/{incentive_id}")
async def delete_incentive(
    incentive_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Delete an incentive record (only unpaid ones)"""
    incentive = await db.incentives.find_one({"id": incentive_id})
    if not incentive:
        raise HTTPException(status_code=404, detail="Incentive not found")
    
    # Only allow deleting if not already paid
    if incentive.get("status") == "paid":
        raise HTTPException(status_code=400, detail="Cannot delete paid incentives. Revert to pending first.")
    
    await db.incentives.delete_one({"id": incentive_id})
    
    # Create audit log
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "incentive_deleted",
        "entity_type": "incentive",
        "entity_id": incentive_id,
        "entity_name": f"Incentive for {incentive.get('agent_name')}",
        "performed_by": user["id"],
        "performed_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "details": {"amount": incentive.get("incentive_amount"), "reason": incentive.get("reason")},
        "timestamp": datetime.now(timezone.utc).isoformat()
    })
    
    return {"success": True, "message": "Incentive deleted successfully"}


@api_router.put("/admin/incentives/{incentive_id}/revert")
async def revert_paid_incentive(
    incentive_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Revert a paid incentive back to pending status (admin only - for corrections)"""
    incentive = await db.incentives.find_one({"id": incentive_id})
    if not incentive:
        raise HTTPException(status_code=404, detail="Incentive not found")
    
    if incentive.get("status") != "paid":
        raise HTTPException(status_code=400, detail="This incentive is not marked as paid")
    
    now = datetime.now(timezone.utc).isoformat()
    
    # Revert to pending
    await db.incentives.update_one(
        {"id": incentive_id},
        {"$set": {
            "status": "pending",
            "paid_at": None,
            "reverted_at": now,
            "reverted_by": user["id"],
            "updated_at": now
        }}
    )
    
    # Create audit log
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "incentive_reverted",
        "entity_type": "incentive",
        "entity_id": incentive_id,
        "entity_name": f"Incentive for {incentive.get('agent_name')}",
        "performed_by": user["id"],
        "performed_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "details": {"amount": incentive.get("incentive_amount"), "previous_status": "paid", "new_status": "pending"},
        "timestamp": now
    })
    
    return {"success": True, "message": "Incentive reverted to pending status. You can now edit or delete it."}


@api_router.post("/admin/incentives/manual")
async def add_manual_incentive(
    data: dict,
    user: dict = Depends(require_roles(["admin"]))
):
    """Add manual incentive for an employee"""
    user_id = data.get("user_id")
    amount = data.get("amount")
    reason = data.get("reason")
    month = data.get("month", datetime.now(timezone.utc).strftime("%Y-%m"))
    
    if not user_id or not amount or not reason:
        raise HTTPException(status_code=400, detail="user_id, amount, and reason are required")
    
    # Get user info
    target_user = await db.users.find_one({"id": user_id}, {"_id": 0})
    if not target_user:
        raise HTTPException(status_code=404, detail="User not found")
    
    now = datetime.now(timezone.utc)
    
    incentive_doc = {
        "id": str(uuid.uuid4()),
        "agent_id": user_id,
        "agent_name": f"{target_user.get('first_name', '')} {target_user.get('last_name', '')}".strip(),
        "incentive_amount": float(amount),
        "reason": reason,
        "source": "manual",
        "month": month,
        "status": "pending",
        "created_at": now.isoformat(),
        "created_by": user["id"],
        "created_by_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip()
    }
    
    await db.incentives.insert_one(incentive_doc)
    
    # Create notification for the user
    await create_notification(
        title="Incentive Added",
        message=f"You have been awarded an incentive of ₹{amount:.0f} for: {reason}",
        notification_type="incentive",
        link="/my-incentives",
        target_user_ids=[user_id],
        priority="normal"
    )
    
    return {"success": True, "message": "Manual incentive added successfully", "incentive_id": incentive_doc["id"]}


# Call Support: View own incentives
@api_router.get("/my-incentives")
async def get_my_incentives(
    month: Optional[str] = None,
    user: dict = Depends(require_roles(["call_support", "admin"]))
):
    """Get incentives for the logged-in call support agent"""
    query = {"agent_id": user["id"]}
    if month:
        query["month"] = month
    
    incentives = await db.incentives.find(query, {"_id": 0}).sort("created_at", -1).to_list(200)
    
    # Calculate totals
    total_earned = sum(i.get("incentive_amount", 0) for i in incentives)
    pending = sum(i.get("incentive_amount", 0) for i in incentives if i.get("status") == "pending")
    paid = sum(i.get("incentive_amount", 0) for i in incentives if i.get("status") == "paid")
    
    # Get this month's stats
    current_month = datetime.now(timezone.utc).strftime("%Y-%m")
    this_month_incentives = [i for i in incentives if i.get("month") == current_month]
    this_month_total = sum(i.get("incentive_amount", 0) for i in this_month_incentives)
    this_month_conversions = len(this_month_incentives)
    
    return {
        "incentives": incentives,
        "summary": {
            "total_earned": round(total_earned, 2),
            "pending_amount": round(pending, 2),
            "paid_amount": round(paid, 2),
            "this_month": {
                "total": round(this_month_total, 2),
                "conversions": this_month_conversions
            }
        }
    }


@api_router.get("/my-incentives/stats")
async def get_my_incentive_stats(
    user: dict = Depends(require_roles(["call_support", "admin"]))
):
    """Get detailed incentive statistics for call support agent"""
    now = datetime.now(timezone.utc)
    current_month = now.strftime("%Y-%m")
    
    # Get all quotations created by this user
    total_quotations = await db.quotations.count_documents({"created_by": user["id"]})
    converted_quotations = await db.quotations.count_documents({
        "created_by": user["id"],
        "status": "converted"
    })
    
    # Get monthly breakdown
    months = []
    for i in range(6):  # Last 6 months
        month_date = now - timedelta(days=30*i)
        month_str = month_date.strftime("%Y-%m")
        
        incentives = await db.incentives.find(
            {"agent_id": user["id"], "month": month_str}, 
            {"_id": 0}
        ).to_list(100)
        
        total = sum(inc.get("incentive_amount", 0) for inc in incentives)
        sales = sum(inc.get("sale_value", 0) for inc in incentives)
        
        months.append({
            "month": month_str,
            "conversions": len(incentives),
            "total_sales": round(sales, 2),
            "total_incentive": round(total, 2)
        })
    
    return {
        "total_quotations": total_quotations,
        "converted_quotations": converted_quotations,
        "conversion_rate": round((converted_quotations / total_quotations * 100) if total_quotations > 0 else 0, 1),
        "monthly_breakdown": months
    }


# ==================== ATTENDANCE & PAYROLL ENDPOINTS ====================

@api_router.post("/attendance/login")
async def attendance_login(user: dict = Depends(get_current_user)):
    """Start shift / login for the day"""
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    now = datetime.now(timezone.utc).isoformat()
    
    # Check if already logged in today
    existing = await db.attendance.find_one({
        "user_id": user["id"],
        "date": today
    })
    
    if existing and existing.get("login_time") and not existing.get("logout_time"):
        raise HTTPException(status_code=400, detail="Already logged in for today")
    
    if existing and existing.get("logout_time"):
        raise HTTPException(status_code=400, detail="Already completed shift for today")
    
    # Create new attendance record
    attendance_id = str(uuid.uuid4())
    attendance_doc = {
        "id": attendance_id,
        "user_id": user["id"],
        "user_name": f"{user.get('first_name', '')} {user.get('last_name', '')}".strip(),
        "user_email": user.get("email"),
        "user_role": user.get("role"),
        "firm_id": user.get("firm_id"),  # If user is assigned to a firm
        "date": today,
        "login_time": now,
        "logout_time": None,
        "breaks": [],
        "total_break_minutes": 0,
        "net_working_minutes": 0,
        "status": "present",
        "is_on_break": False,
        "notes": None,
        "created_at": now,
        "updated_at": now
    }
    
    await db.attendance.insert_one(attendance_doc)
    
    return {"message": "Shift started", "attendance_id": attendance_id, "login_time": now}


@api_router.post("/attendance/logout")
async def attendance_logout(user: dict = Depends(get_current_user)):
    """End shift / logout for the day"""
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    now = datetime.now(timezone.utc)
    
    # Find today's attendance
    attendance = await db.attendance.find_one({
        "user_id": user["id"],
        "date": today,
        "login_time": {"$ne": None},
        "logout_time": None
    })
    
    if not attendance:
        raise HTTPException(status_code=400, detail="No active shift found for today")
    
    # End any ongoing break
    if attendance.get("is_on_break"):
        breaks = attendance.get("breaks", [])
        if breaks and not breaks[-1].get("end"):
            breaks[-1]["end"] = now.isoformat()
            break_start = datetime.fromisoformat(breaks[-1]["start"].replace("Z", "+00:00"))
            break_minutes = (now - break_start).total_seconds() / 60
            attendance["total_break_minutes"] = attendance.get("total_break_minutes", 0) + int(break_minutes)
    
    # Calculate net working time
    login_time = datetime.fromisoformat(attendance["login_time"].replace("Z", "+00:00"))
    total_minutes = (now - login_time).total_seconds() / 60
    net_working_minutes = int(total_minutes - attendance.get("total_break_minutes", 0))
    
    await db.attendance.update_one(
        {"id": attendance["id"]},
        {"$set": {
            "logout_time": now.isoformat(),
            "is_on_break": False,
            "breaks": attendance.get("breaks", []),
            "total_break_minutes": attendance.get("total_break_minutes", 0),
            "net_working_minutes": max(0, net_working_minutes),
            "updated_at": now.isoformat()
        }}
    )
    
    hours = net_working_minutes // 60
    mins = net_working_minutes % 60
    
    return {
        "message": "Shift ended",
        "logout_time": now.isoformat(),
        "net_working_time": f"{hours}h {mins}m",
        "net_working_minutes": net_working_minutes
    }


@api_router.post("/attendance/break-start")
async def attendance_break_start(user: dict = Depends(get_current_user)):
    """Start a break"""
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    now = datetime.now(timezone.utc).isoformat()
    
    attendance = await db.attendance.find_one({
        "user_id": user["id"],
        "date": today,
        "login_time": {"$ne": None},
        "logout_time": None
    })
    
    if not attendance:
        raise HTTPException(status_code=400, detail="No active shift found")
    
    if attendance.get("is_on_break"):
        raise HTTPException(status_code=400, detail="Already on break")
    
    breaks = attendance.get("breaks", [])
    breaks.append({"start": now, "end": None})
    
    await db.attendance.update_one(
        {"id": attendance["id"]},
        {"$set": {
            "breaks": breaks,
            "is_on_break": True,
            "updated_at": now
        }}
    )
    
    return {"message": "Break started", "break_start": now}


@api_router.post("/attendance/break-end")
async def attendance_break_end(user: dict = Depends(get_current_user)):
    """End a break"""
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    now = datetime.now(timezone.utc)
    
    attendance = await db.attendance.find_one({
        "user_id": user["id"],
        "date": today,
        "login_time": {"$ne": None},
        "logout_time": None
    })
    
    if not attendance:
        raise HTTPException(status_code=400, detail="No active shift found")
    
    if not attendance.get("is_on_break"):
        raise HTTPException(status_code=400, detail="Not currently on break")
    
    breaks = attendance.get("breaks", [])
    if breaks and not breaks[-1].get("end"):
        breaks[-1]["end"] = now.isoformat()
        break_start = datetime.fromisoformat(breaks[-1]["start"].replace("Z", "+00:00"))
        break_minutes = (now - break_start).total_seconds() / 60
        total_break_minutes = attendance.get("total_break_minutes", 0) + int(break_minutes)
    else:
        total_break_minutes = attendance.get("total_break_minutes", 0)
    
    await db.attendance.update_one(
        {"id": attendance["id"]},
        {"$set": {
            "breaks": breaks,
            "is_on_break": False,
            "total_break_minutes": total_break_minutes,
            "updated_at": now.isoformat()
        }}
    )
    
    return {"message": "Break ended", "break_end": now.isoformat(), "total_break_minutes": total_break_minutes}


