# ----- Dealer Products -----

@api_router.get("/dealer/products")
async def get_dealer_products(user: dict = Depends(require_roles(["dealer", "admin"]))):
    """Get products with dealer pricing - redirects to catalogue endpoint"""
    # Use the same logic as products-catalogue for consistency
    enriched_products = []
    seen_sku_ids = set()
    
    # Get products from product_datasheets linked to master SKUs
    datasheets = await db.product_datasheets.find(
        {"master_sku_id": {"$exists": True, "$ne": "", "$ne": None}},
        {"_id": 0}
    ).to_list(500)
    
    for ds in datasheets:
        master_sku_id = ds.get("master_sku_id")
        if not master_sku_id or master_sku_id in seen_sku_ids:
            continue
        
        master_sku = await db.master_skus.find_one(
            {"id": master_sku_id, "is_active": True},
            {"_id": 0}
        )
        if not master_sku:
            continue
        
        selling_price = master_sku.get("selling_price", 0)
        if not selling_price:
            continue

        # dict.get(key, default) only falls back when the key is missing — not when
        # the value is explicitly None, which several legacy master_skus have. Guard
        # both fields before any arithmetic.
        product_discount = master_sku.get("dealer_discount_percent")
        if product_discount is None:
            product_discount = 15
        gst_rate = master_sku.get("gst_rate")
        if gst_rate is None:
            gst_rate = 18
        dealer_price = selling_price * (1 - product_discount / 100)
        seen_sku_ids.add(master_sku_id)

        enriched_products.append({
            "id": master_sku_id,
            "master_sku_id": master_sku_id,
            "name": ds.get("model_name") or master_sku.get("name"),
            "sku": master_sku.get("sku_code"),
            "category": ds.get("category") or master_sku.get("category"),
            "mrp": master_sku.get("mrp") or selling_price,
            "selling_price": selling_price,
            "dealer_price": round(dealer_price, 2),
            "dealer_discount_percent": product_discount,
            "gst_rate": gst_rate,
            "images": ds.get("images") or ([ds.get("image_url")] if ds.get("image_url") else []),
            "is_active": True
        })
    
    # Also include master SKUs with selling_price that don't have datasheets
    master_skus = await db.master_skus.find(
        {"is_active": True, "selling_price": {"$exists": True, "$gt": 0}},
        {"_id": 0}
    ).to_list(500)
    
    for sku in master_skus:
        if sku["id"] in seen_sku_ids:
            continue
        
        selling_price = sku.get("selling_price", 0)
        product_discount = sku.get("dealer_discount_percent")
        if product_discount is None:
            product_discount = 15
        gst_rate = sku.get("gst_rate")
        if gst_rate is None:
            gst_rate = 18
        dealer_price = selling_price * (1 - product_discount / 100)

        enriched_products.append({
            "id": sku["id"],
            "master_sku_id": sku["id"],
            "name": sku.get("name"),
            "sku": sku.get("sku_code"),
            "category": sku.get("category"),
            "mrp": sku.get("mrp") or selling_price,
            "selling_price": selling_price,
            "dealer_price": round(dealer_price, 2),
            "dealer_discount_percent": product_discount,
            "gst_rate": gst_rate,
            "images": [],
            "is_active": True
        })
    
    # Include legacy dealer_products
    legacy = await db.dealer_products.find({"is_active": True}, {"_id": 0}).to_list(500)
    for p in legacy:
        if p.get("master_sku_id") not in seen_sku_ids:
            enriched_products.append(p)
    
    return enriched_products


@api_router.get("/dealer/products-catalogue")
async def get_dealer_products_with_catalogue(user: dict = Depends(require_roles(["dealer", "admin"]))):
    """
    Get product catalogue with dealer-specific pricing.
    
    Logic:
    1. Fetch all product_datasheets that have master_sku_id linked
    2. For each datasheet, get the master SKU selling_price
    3. Calculate dealer price using PRODUCT-SPECIFIC dealer_discount_percent
    
    Price visibility:
    - selling_price: Base price visible to all customers
    - dealer_price: selling_price - (selling_price * dealer_discount_percent / 100)
    """
    enriched_products = []
    seen_sku_ids = set()
    
    # APPROACH 1: Start from product_datasheets (these have images)
    # Only include datasheets that have a linked master_sku_id
    datasheets = await db.product_datasheets.find(
        {"master_sku_id": {"$exists": True, "$ne": "", "$ne": None}},
        {"_id": 0}
    ).to_list(500)
    
    for ds in datasheets:
        master_sku_id = ds.get("master_sku_id")
        if not master_sku_id or master_sku_id in seen_sku_ids:
            continue
        
        # Get master SKU for pricing
        master_sku = await db.master_skus.find_one(
            {"id": master_sku_id, "is_active": True},
            {"_id": 0}
        )
        if not master_sku:
            continue
        
        selling_price = master_sku.get("selling_price", 0)
        if not selling_price:
            continue  # Skip products without selling price

        # dict.get(key, default) only falls back when the key is missing — not when
        # the value is explicitly None. Legacy master_skus have null discount/gst.
        product_discount = master_sku.get("dealer_discount_percent")
        if product_discount is None:
            product_discount = 15
        gst_rate_val = master_sku.get("gst_rate")
        if gst_rate_val is None:
            gst_rate_val = 18
        dealer_price = selling_price * (1 - product_discount / 100)
        seen_sku_ids.add(master_sku_id)

        product = {
            "id": ds.get("id"),
            "datasheet_id": ds.get("id"),
            "master_sku_id": master_sku_id,
            "name": ds.get("model_name") or master_sku.get("name"),
            "sku": master_sku.get("sku_code"),
            "sku_code": master_sku.get("sku_code"),
            "category": ds.get("category") or master_sku.get("category"),
            "hsn_code": master_sku.get("hsn_code"),
            "product_type": master_sku.get("product_type"),
            "gst_rate": gst_rate_val,
            # Pricing
            "selling_price": selling_price,  # Customer price
            "mrp": master_sku.get("mrp") or selling_price,
            "dealer_discount_percent": product_discount,  # Product-specific discount
            "dealer_price": round(dealer_price, 2),
            "savings": round(selling_price - dealer_price, 2),
            # Images and descriptions from datasheet
            "images": ds.get("images") or ([ds.get("image_url")] if ds.get("image_url") else []),
            "description": ds.get("description") or ds.get("subtitle"),
            "specifications": ds.get("specifications"),
            "features": ds.get("features"),
            "warranty": ds.get("warranty"),
            # Stock info
            "unit": master_sku.get("unit", "Pcs"),
            "min_order_qty": master_sku.get("min_order_qty", 1),
            "is_active": True
        }
        
        # Get current stock
        stock_info = await db.stock_ledger.aggregate([
            {"$match": {"item_type": "master_sku", "item_id": master_sku_id}},
            {"$group": {"_id": None, "total": {"$sum": "$quantity"}}}
        ]).to_list(1)
        product["available_stock"] = stock_info[0]["total"] if stock_info else 0
        
        enriched_products.append(product)
    
    # APPROACH 2: Also include master SKUs with selling_price that DON'T have datasheets
    # (for backward compatibility)
    master_skus = await db.master_skus.find(
        {"is_active": True, "selling_price": {"$exists": True, "$gt": 0}},
        {"_id": 0}
    ).to_list(500)
    
    for sku in master_skus:
        if sku["id"] in seen_sku_ids:
            continue  # Already added from datasheet
        
        selling_price = sku.get("selling_price", 0)
        product_discount = sku.get("dealer_discount_percent")
        if product_discount is None:
            product_discount = 15
        gst_rate_val = sku.get("gst_rate")
        if gst_rate_val is None:
            gst_rate_val = 18
        dealer_price = selling_price * (1 - product_discount / 100) if selling_price else 0

        product = {
            "id": sku["id"],
            "master_sku_id": sku["id"],
            "name": sku.get("name"),
            "sku": sku.get("sku_code"),
            "sku_code": sku.get("sku_code"),
            "category": sku.get("category"),
            "hsn_code": sku.get("hsn_code"),
            "product_type": sku.get("product_type"),
            "gst_rate": gst_rate_val,
            "selling_price": selling_price,
            "mrp": sku.get("mrp") or selling_price,
            "dealer_discount_percent": product_discount,
            "dealer_price": round(dealer_price, 2),
            "savings": round(selling_price - dealer_price, 2),
            "images": [],  # No datasheet images
            "unit": sku.get("unit", "Pcs"),
            "min_order_qty": sku.get("min_order_qty", 1),
            "is_active": True
        }
        
        # Get stock
        stock_info = await db.stock_ledger.aggregate([
            {"$match": {"item_type": "master_sku", "item_id": sku["id"]}},
            {"$group": {"_id": None, "total": {"$sum": "$quantity"}}}
        ]).to_list(1)
        product["available_stock"] = stock_info[0]["total"] if stock_info else 0
        
        enriched_products.append(product)
    
    return enriched_products


@api_router.post("/admin/dealer-products")
async def create_dealer_product(
    data: DealerProductCreate,
    user: dict = Depends(require_roles(["admin"]))
):
    """Create a product for dealer catalog"""
    now = datetime.now(timezone.utc).isoformat()
    product_id = str(uuid.uuid4())
    
    # Check SKU uniqueness
    existing = await db.dealer_products.find_one({"sku": data.sku})
    if existing:
        raise HTTPException(status_code=400, detail="SKU already exists")
    
    product_doc = {
        "id": product_id,
        **data.dict(),
        "created_at": now,
        "updated_at": now
    }
    
    await db.dealer_products.insert_one(product_doc)
    return {"id": product_id, "message": "Product created"}


@api_router.patch("/admin/dealer-products/{product_id}")
async def update_dealer_product(
    product_id: str,
    name: str = Form(None),
    mrp: float = Form(None),
    dealer_price: float = Form(None),
    gst_rate: int = Form(None),
    is_active: bool = Form(None),
    master_sku_id: str = Form(None),
    sku: str = Form(None),
    category: str = Form(None),
    warranty_months: int = Form(None),
    user: dict = Depends(require_roles(["admin"]))
):
    """Update dealer product with SKU mapping"""
    logger.info(f"Updating dealer product {product_id}, master_sku_id={master_sku_id}")
    
    # Try finding by 'id' field first, then by _id (ObjectId)
    product = await db.dealer_products.find_one({"id": product_id})
    query = {"id": product_id}
    
    if not product:
        # Try with ObjectId
        if ObjectId.is_valid(product_id):
            product = await db.dealer_products.find_one({"_id": ObjectId(product_id)})
            query = {"_id": ObjectId(product_id)}
            logger.info(f"Found product by ObjectId: {product.get('name') if product else 'Not found'}")
    
    if not product:
        raise HTTPException(status_code=404, detail="Product not found")
    
    update_dict = {}
    if name is not None: update_dict["name"] = name
    if mrp is not None: update_dict["mrp"] = mrp
    if dealer_price is not None: update_dict["dealer_price"] = dealer_price
    if gst_rate is not None: update_dict["gst_rate"] = gst_rate
    if is_active is not None: update_dict["is_active"] = is_active
    if sku is not None: update_dict["sku"] = sku
    if category is not None: update_dict["category"] = category
    if warranty_months is not None: update_dict["warranty_months"] = warranty_months
    if master_sku_id is not None:
        update_dict["master_sku_id"] = master_sku_id if master_sku_id not in ['none', '', 'undefined'] else None
        logger.info(f"Setting master_sku_id to: {update_dict.get('master_sku_id')}")
    
    if update_dict:
        update_dict["updated_at"] = datetime.now(timezone.utc).isoformat()
        result = await db.dealer_products.update_one(query, {"$set": update_dict})
        logger.info(f"Update result: modified={result.modified_count}, matched={result.matched_count}")
    
    return {"message": "Product updated"}


