@api_router.post("/dealer-applications")
async def submit_dealer_application(data: DealerApplicationCreate):
    """Public endpoint for dealer application submission"""
    now = datetime.now(timezone.utc).isoformat()
    
    # Get phone from either field
    phone = data.phone or data.mobile
    
    # Check if email/mobile already has a PENDING application
    existing_application = await db.dealer_applications.find_one({
        "$or": [{"email": data.email}, {"phone": phone}],
        "status": {"$in": ["new", "under_review", "pending"]}
    })
    if existing_application:
        raise HTTPException(status_code=400, detail="An application with this email or phone is already pending review")
    
    # Check if they're already a dealer
    existing_dealer = await db.dealers.find_one({
        "$or": [{"email": data.email}, {"phone": phone}]
    })
    if existing_dealer:
        raise HTTPException(status_code=400, detail="You are already registered as a dealer")
    
    application_id = str(uuid.uuid4())
    application_number = await generate_dealer_application_number()
    
    # Build address from new or legacy fields
    address = data.address or {
        "line1": data.address_line1,
        "line2": data.address_line2,
        "city": data.city,
        "district": data.district,
        "state": data.state,
        "pincode": data.pincode
    }
    
    application_doc = {
        "id": application_id,
        "application_number": application_number,
        "firm_name": data.firm_name,
        "contact_person": data.contact_person,
        "email": data.email,
        "phone": phone,
        "alternate_phone": data.alternate_phone,
        "designation": data.designation,
        "address": address,
        "gst_number": data.gst_number or data.gstin,
        "pan_number": data.pan_number,
        "business_type": data.business_type,
        "years_in_business": data.years_in_business,
        "current_brands": data.current_brands,
        "monthly_turnover": data.monthly_turnover or data.expected_monthly_volume,
        "shop_area": data.shop_area,
        "godown_available": data.godown_available,
        "delivery_vehicle": data.delivery_vehicle,
        "reference": data.reference,
        "notes": data.notes,
        "status": "new",
        "admin_notes": None,
        "approved_user_id": None,
        "approved_dealer_id": None,
        "legacy_id": None,
        "created_at": now,
        "updated_at": now
    }
    
    await db.dealer_applications.insert_one(application_doc)
    
    # Notify admins
    await create_notification(
        title="New Dealer Application",
        message=f"New dealer application from {data.firm_name}",
        notification_type="dealer",
        link="/admin/dealer-applications",
        target_roles=["admin"],
        priority="high"
    )
    
    # Send confirmation email to applicant
    if data.email:
        asyncio.create_task(send_dealer_email(
            {"email": data.email, "firm_name": data.firm_name, "contact_person": data.contact_person},
            application_doc,
            "application_received"
        ))
    
    return {
        "id": application_id,
        "application_number": application_number,
        "message": "Application submitted successfully. We will review and contact you soon."
    }


