# ----- Dealer Orders -----

@api_router.post("/dealer/orders")
async def create_dealer_order(
    data: DealerOrderCreate,
    user: dict = Depends(require_roles(["dealer"]))
):
    """Create a new dealer order"""
    dealer = await db.dealers.find_one({"user_id": user["id"]})
    if not dealer:
        raise HTTPException(status_code=404, detail="Dealer profile not found")
    
    # Check if dealer can place orders
    if dealer.get("security_deposit_status") != "approved":
        raise HTTPException(status_code=403, detail="Security deposit not approved. Cannot place orders.")
    
    if dealer.get("status") != "approved":
        raise HTTPException(status_code=403, detail="Dealer account not active")

    # Terms & Conditions must be accepted (current version) before ordering.
    # The React TermsAcceptanceGuard is advisory only (fails open if it never
    # mounts / is bypassed) — enforce the same invariant server-side.
    tnc_user = await db.users.find_one({"id": user["id"]}, {"_id": 0, "tnc_accepted_version": 1})
    if (tnc_user or {}).get("tnc_accepted_version") != DEALER_TNC_CURRENT_VERSION:
        raise HTTPException(
            status_code=403,
            detail="You must accept the current Dealer Terms & Conditions before placing an order.",
        )

    from decimal import Decimal, ROUND_HALF_UP

    def _money(v):
        return Decimal(str(v or 0)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    now = datetime.now(timezone.utc).isoformat()
    order_id = str(uuid.uuid4())
    order_number = await generate_dealer_order_number()

    # Calculate order total — Decimal math so multi-item orders reconcile exactly.
    order_items = []
    total_amount = Decimal("0")

    for item in data.items:
        product_id = item["product_id"]
        quantity = int(item["quantity"])
        if quantity <= 0:
            raise HTTPException(status_code=400, detail="Quantity must be positive")

        # First try to find in dealer_products (legacy)
        product = await db.dealer_products.find_one({"id": product_id})

        if product:
            # Legacy dealer_product
            dealer_price = Decimal(str(product.get("dealer_price", 0)))
            gst_rate = Decimal(str(product.get("gst_rate", 18)))
            product_name = product.get("name")
            sku_code = product.get("sku")
            master_sku_id = product.get("master_sku_id")
            product_discount = 0  # Legacy products have fixed dealer_price
        else:
            # Try master_skus (new flow)
            master_sku = await db.master_skus.find_one({"id": product_id, "is_active": True})
            if not master_sku:
                raise HTTPException(status_code=400, detail=f"Product {product_id} not found")

            selling_price = Decimal(str(master_sku.get("selling_price", 0)))
            if not selling_price:
                raise HTTPException(status_code=400, detail=f"Product {master_sku['name']} has no price set")

            # Use PRODUCT-SPECIFIC discount (default 15%)
            product_discount = master_sku.get("dealer_discount_percent", 15)
            dealer_price = (selling_price * (Decimal("1") - Decimal(str(product_discount)) / Decimal("100"))).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            gst_rate = Decimal(str(master_sku.get("gst_rate", 18)))
            product_name = master_sku.get("name")
            sku_code = master_sku.get("sku_code")
            master_sku_id = master_sku.get("id")

        line_total = _money(dealer_price * quantity)
        gst_amount = _money(line_total * gst_rate / Decimal("100"))
        line_grand = _money(line_total + gst_amount)

        order_items.append({
            "id": str(uuid.uuid4()),
            "product_id": product_id,
            "master_sku_id": master_sku_id,
            "product_name": product_name,
            "sku": sku_code,
            "quantity": quantity,
            "unit_price": float(dealer_price),
            "discount_percent": product_discount,
            "gst_rate": float(gst_rate),
            "gst_amount": float(gst_amount),
            "line_total": float(line_grand)
        })

        total_amount += line_grand

    total_amount = _money(total_amount)

    # ---- Credit-limit enforcement ----
    # A dealer with credit_limit > 0 cannot let (unpaid orders + this order)
    # exceed the limit. credit_limit of 0 / unset means unlimited.
    credit_limit = Decimal(str(dealer.get("credit_limit", 0) or 0))
    if credit_limit > 0:
        outstanding_orders = await db.dealer_orders.find({
            "dealer_id": dealer["id"],
            "payment_status": {"$ne": "received"},
            "status": {"$nin": ["cancelled", "rejected"]},
        }, {"_id": 0, "total_amount": 1}).to_list(1000)
        outstanding = sum((Decimal(str(o.get("total_amount", 0) or 0)) for o in outstanding_orders), Decimal("0"))
        if outstanding + total_amount > credit_limit:
            raise HTTPException(
                status_code=403,
                detail=(
                    f"Credit limit exceeded. Limit ₹{credit_limit:,.2f}, "
                    f"unpaid orders ₹{outstanding:,.2f}, this order ₹{total_amount:,.2f}. "
                    f"Clear pending payments before ordering more."
                ),
            )

    order_doc = {
        "id": order_id,
        "order_number": order_number,
        "dealer_id": dealer["id"],
        "dealer_name": dealer["firm_name"],
        "dealer_phone": dealer["phone"],
        "firm_id": dealer.get("firm_id"),
        "items": order_items,
        "total_amount": float(total_amount),
        "status": "pending",
        "payment_status": "pending",
        "payment_proof_path": None,
        "payment_received_at": None,
        "dispatch_due_date": None,
        "dispatch_date": None,
        "dispatch_courier": None,
        "dispatch_awb": None,
        "dispatch_remarks": None,
        "proforma_number": None,
        "proforma_date": None,
        "final_invoice_number": None,
        "final_invoice_date": None,
        "notes": data.notes,
        "legacy_order_id": None,
        "created_at": now,
        "updated_at": now
    }
    
    await db.dealer_orders.insert_one(order_doc)
    
    # Notify admin
    await create_notification(
        title="New Dealer Order",
        message=f"Dealer {dealer['firm_name']} placed order {order_number} for ₹{total_amount:,.2f}",
        notification_type="dealer",
        link="/admin/dealer-orders",
        target_roles=["admin", "accountant"],
        priority="high"
    )
    
    # Send order confirmation email to dealer
    if dealer.get("email"):
        asyncio.create_task(send_dealer_email(dealer, order_doc, "order_confirmation"))

    asyncio.create_task(post_system_message(
        "accounts",
        f"🛒 New dealer order {order_number} from {dealer['firm_name']} — ₹{total_amount:,.0f} ({len(order_items)} item{'s' if len(order_items) != 1 else ''})",
        {"ref": order_number}))

    return {
        "id": order_id,
        "order_number": order_number,
        "total_amount": float(total_amount),
        "message": "Order created successfully"
    }


