@api_router.post("/dealer/orders/{order_id}/upload-payment")
async def upload_dealer_payment_proof(
    order_id: str,
    amount: float = Form(...),
    payment_reference: str = Form(None),
    proof_file: UploadFile = File(...),
    user: dict = Depends(require_roles(["dealer"]))
):
    """Upload payment proof for an order"""
    dealer = await db.dealers.find_one({"user_id": user["id"]})
    if not dealer:
        raise HTTPException(status_code=404, detail="Dealer profile not found")
    
    order = await db.dealer_orders.find_one({"id": order_id, "dealer_id": dealer["id"]})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    if order.get("payment_status") == "received":
        raise HTTPException(status_code=400, detail="Payment already received for this order")

    # Admin must APPROVE the order before the dealer can pay. The approve step
    # was previously skippable — proof could be uploaded on a still-'pending'
    # (never-reviewed) order, which then flowed straight through verify/confirm
    # without anyone approving it. Gate the upload on an admin-approved status.
    if order.get("status") != "approved":
        raise HTTPException(
            status_code=400,
            detail=(
                f"Order is not yet approved for payment (status '{order.get('status')}'). "
                f"Please wait for admin approval before uploading payment proof."
            ),
        )

    now = datetime.now(timezone.utc).isoformat()

    # Upload file using storage utility
    try:
        content = await proof_file.read()
        relative_path, storage_type = await storage_upload(
            file_data=content,
            folder="dealer_payments",
            original_filename=proof_file.filename,
            filename_prefix=f"{order_id}_payment"
        )
        file_url = f"/api/files/{relative_path}"
    except StorageError as e:
        logger.error(f"Failed to upload payment proof: {str(e)}")
        raise HTTPException(status_code=500, detail=f"File upload failed: {str(e)}")
    
    # Update order with payment_status = verification_pending (H2 FIX)
    await db.dealer_orders.update_one(
        {"id": order_id},
        {"$set": {
            "payment_proof_path": file_url,
            "payment_proof_amount": amount,
            "payment_proof_reference": payment_reference,
            "payment_proof_uploaded_at": now,
            "payment_status": "verification_pending",  # H2 FIX: Track verification status
            "payment_verification_due": (datetime.now(timezone.utc) + timedelta(hours=24)).isoformat(),  # H2 FIX: 24hr deadline
            "updated_at": now
        }}
    )
    
    # Notify admin
    await create_notification(
        title="Payment Proof Uploaded - Verify within 24hrs",
        message=f"Dealer {dealer['firm_name']} uploaded payment for order {order['order_number']}. Please verify.",
        notification_type="dealer",
        link="/admin/dealer-payments",
        target_roles=["admin", "accountant"],
        priority="high"
    )
    
    return {"message": "Payment proof uploaded. Admin will verify within 24 hours."}


# ----- Admin Dealer Orders -----

@api_router.get("/admin/dealer-orders")
async def admin_get_dealer_orders(
    status: Optional[str] = None,
    payment_status: Optional[str] = None,
    dealer_id: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Admin view of dealer orders. Accountants are scoped to their own firm."""
    query = {}
    if status:
        query["status"] = status
    if payment_status:
        query["payment_status"] = payment_status
    if dealer_id:
        query["dealer_id"] = dealer_id

    # Firm scope — accountants only see orders for their firm.
    firm_scope = get_user_firm_scope(user)
    if firm_scope:
        query["firm_id"] = firm_scope

    # Projection excludes _id so the document's real UUID `id` is preserved.
    # The old code did `order["id"] = str(order.pop("_id"))`, which clobbered
    # the UUID with the Mongo ObjectId and broke every downstream admin action
    # keyed by the order id.
    orders = await db.dealer_orders.find(query, {"_id": 0}).sort("created_at", -1).to_list(500)

    # Enrich with dealer names
    dealer_cache = {}
    for order in orders:
        d_id = order.get("dealer_id")
        if d_id and d_id not in dealer_cache:
            dealer = await db.dealers.find_one({"id": d_id}, {"_id": 0, "firm_name": 1})
            dealer_cache[d_id] = dealer.get("firm_name") if dealer else d_id
        if not order.get("dealer_name"):
            order["dealer_name"] = dealer_cache.get(d_id, d_id)

    return orders


@api_router.get("/admin/dealer-orders/overdue-verifications")
async def get_overdue_payment_verifications(
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    H2 FIX: Get dealer orders with payment proof uploaded but not verified within 24hrs.
    These need immediate attention.
    """
    now = datetime.now(timezone.utc).isoformat()

    overdue_query = {
        "payment_status": "verification_pending",
        "payment_verification_due": {"$lt": now}
    }
    firm_scope = get_user_firm_scope(user)
    if firm_scope:
        overdue_query["firm_id"] = firm_scope

    overdue_orders = await db.dealer_orders.find(
        overdue_query, {"_id": 0}
    ).sort("payment_verification_due", 1).to_list(100)
    
    # Enrich with dealer names
    for order in overdue_orders:
        dealer = await db.dealers.find_one({"id": order.get("dealer_id")}, {"_id": 0, "firm_name": 1})
        order["dealer_name"] = dealer.get("firm_name") if dealer else "Unknown"
        # Calculate hours overdue
        if order.get("payment_verification_due"):
            due_dt = datetime.fromisoformat(order["payment_verification_due"].replace("Z", "+00:00"))
            now_dt = datetime.now(timezone.utc)
            hours_overdue = (now_dt - due_dt).total_seconds() / 3600
            order["hours_overdue"] = round(hours_overdue, 1)
    
    return {
        "overdue_count": len(overdue_orders),
        "orders": overdue_orders
    }


@api_router.post("/admin/dealer-orders/{order_id}/verify-payment")
async def verify_dealer_payment(
    order_id: str,
    verified: bool = Form(...),
    rejection_reason: str = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    H2 FIX: Verify or reject dealer payment proof. 
    Clears the verification_pending status.
    """
    order = await db.dealer_orders.find_one({"id": order_id})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    if order.get("payment_status") != "verification_pending":
        raise HTTPException(status_code=400, detail=f"Order payment status is '{order.get('payment_status')}', not verification_pending")
    
    now = datetime.now(timezone.utc).isoformat()
    
    if verified:
        update = {
            "payment_status": "verified",
            "payment_verified_by": user["id"],
            "payment_verified_at": now,
            "status": "payment_received",  # Move order forward
            "updated_at": now
        }
        message = f"Payment verified for order {order.get('order_number')}"
    else:
        update = {
            "payment_status": "rejected",
            "payment_rejection_reason": rejection_reason,
            "payment_rejected_by": user["id"],
            "payment_rejected_at": now,
            "updated_at": now
        }
        message = f"Payment rejected for order {order.get('order_number')}: {rejection_reason}"
    
    await db.dealer_orders.update_one({"id": order_id}, {"$set": update})
    
    # Notify dealer
    dealer = await db.dealers.find_one({"id": order.get("dealer_id")})
    if dealer:
        await create_notification(
            title="Payment Verified" if verified else "Payment Rejected",
            message=message,
            notification_type="success" if verified else "warning",
            link="/dealer/orders",
            target_roles=["dealer"],
            priority="high"
        )
    
    return {"message": message, "verified": verified}


@api_router.post("/admin/dealer-orders/{order_id}/approve")
async def approve_dealer_order(
    order_id: str,
    admin_notes: str = Form(None),
    user: dict = Depends(require_roles(["admin"]))
):
    """Admin reviews and approves a pending dealer order before payment collection."""
    order = await db.dealer_orders.find_one({"id": order_id})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    if order.get("status") != "pending":
        raise HTTPException(status_code=400, detail=f"Order cannot be approved in status '{order.get('status')}'")
    
    now = datetime.now(timezone.utc).isoformat()
    update = {
        "status": "approved",
        "approved_by": user["id"],
        "approved_at": now,
        "updated_at": now
    }
    if admin_notes:
        update["admin_notes"] = admin_notes
    
    await db.dealer_orders.update_one({"id": order_id}, {"$set": update})
    
    # Notify dealer
    dealer = await db.dealers.find_one({"id": order.get("dealer_id")})
    if dealer:
        await create_notification(
            title="Order Approved",
            message=f"Your order {order.get('order_number')} has been approved. Please complete payment to proceed.",
            notification_type="success",
            link="/dealer/orders",
            target_roles=["dealer"],
            priority="normal"
        )
    
    return {"message": "Order approved", "order_id": order_id}


@api_router.post("/admin/dealer-orders/{order_id}/confirm-payment")
async def confirm_dealer_payment(
    order_id: str,
    payment_date: str = Form(None),
    remarks: str = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Confirm payment for dealer order"""
    order = await db.dealer_orders.find_one({"id": order_id})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    if order.get("payment_status") == "received":
        raise HTTPException(status_code=400, detail="Payment already confirmed for this order")
    # The proof MUST be verified first. Previously this accepted
    # "verification_pending" (proof uploaded but NOT yet checked) and
    # "approved" (a status nothing ever sets) — both let an admin mark a
    # payment received without anyone actually verifying the proof file.
    if order.get("payment_status") != "verified":
        raise HTTPException(
            status_code=400,
            detail=(
                f"Payment cannot be confirmed: current payment_status is "
                f"'{order.get('payment_status')}'. The payment proof must be "
                f"verified first via the verify-payment action."
            ),
        )
    # A verified payment leaves the order at status "payment_received" (set by
    # verify-payment). The old allow-list had "pending" (never-approved orders
    # could be confirmed → approve gate bypass) and omitted "payment_received"
    # (so a correctly-verified order could NEVER be confirmed → 0 ledger entries
    # ever booked in prod). Accept only post-approval/post-verify statuses.
    if order.get("status") not in ["payment_received", "approved", "confirmed"]:
        raise HTTPException(status_code=400, detail=f"Cannot confirm payment for order in status '{order.get('status')}'")
    
    now = datetime.now(timezone.utc).isoformat()

    # ATOMIC payment-status flip: only ONE request can move verified -> received.
    # The old check-then-act let two concurrent confirms both pass the read-guard
    # above and both post a ledger CREDIT, double-booking the dealer's payment.
    locked = await db.dealer_orders.find_one_and_update(
        {"id": order_id, "payment_status": "verified"},
        {"$set": {
            "payment_status": "received",
            "payment_received_at": payment_date or now[:10],
            "payment_confirmed_by": user["id"],
            "payment_remarks": remarks,
            "status": "confirmed",
            "updated_at": now,
        }},
    )
    if not locked:
        # Lost the race — another request already confirmed it. Idempotent, no double-book.
        raise HTTPException(status_code=400, detail="Payment already confirmed for this order")

    # Idempotency backstop: never post a second CREDIT for the same order, even if
    # a prior run flipped the status but died before booking the ledger.
    if await db.party_ledger.find_one(
        {"reference_type": "dealer_order_payment", "reference_id": order_id}, {"_id": 1}
    ):
        return {"message": "Payment confirmed", "order_id": order_id}

    # Add to party ledger — auto-create party if missing
    dealer = await db.dealers.find_one({"id": order["dealer_id"]})
    party = await db.parties.find_one({"dealer_id": order["dealer_id"]})
    if not party:
        party = {
            "id": str(uuid.uuid4()),
            "name": dealer.get("firm_name") or "Unknown Dealer",
            "party_type": "dealer",
            "dealer_id": order["dealer_id"],
            "phone": dealer.get("phone") or dealer.get("mobile"),
            "email": dealer.get("email"),
            "gst_number": dealer.get("gst_number"),
            "address": dealer.get("address"),
            "current_balance": 0,
            "firm_id": dealer.get("firm_id"),
            "is_active": True,
            "created_at": now,
            "updated_at": now,
        }
        await db.parties.insert_one(party)

    # Payment received from the dealer is a CREDIT — it reduces what the dealer
    # owes us (running_balance = prev + debit - credit). The matching DEBIT for
    # the goods themselves is posted as a sales_invoice entry at dispatch time.
    led = await create_party_ledger_entry_atomic(
        party_id=party["id"],
        party_name=party["name"],
        entry_type="dealer_order_payment",
        debit=0,
        credit=order.get("total_amount", 0) or 0,
        narration=f"Payment received for dealer order {order['order_number']}",
        reference_type="dealer_order_payment",
        reference_id=order_id,
        firm_id=party.get("firm_id") or (dealer.get("firm_id") if dealer else None),
        user_id=user["id"],
        user_name=f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
        opening_balance=party.get("opening_balance", 0),
    )
    await db.parties.update_one(
        {"id": party["id"]},
        {"$set": {"current_balance": led["running_balance"], "updated_at": now}}
    )

    # Create pending_fulfillment entry so dispatcher/admin queue sees this order
    pf_exists = await db.pending_fulfillment.find_one({"dealer_order_id": order_id})
    if not pf_exists:
        pf_id = str(uuid.uuid4())
        pf_items = []
        for item in order.get("items", []):
            dp = await db.dealer_products.find_one({"id": item.get("product_id")}, {"_id": 0})
            pf_items.append({
                "product_name": item.get("product_name"),
                "sku": item.get("sku"),
                "master_sku_id": dp.get("master_sku_id") if dp else None,
                "quantity": item.get("quantity", 1),
                "unit_price": item.get("unit_price"),
                "gst_rate": item.get("gst_rate"),
                "line_total": item.get("line_total")
            })
        pf_doc = {
            "id": pf_id,
            "pf_number": f"PF-DLR-{now[:10].replace('-','')}-{pf_id[:6].upper()}",
            "type": "dealer_order",
            "order_id": order.get("order_number"),
            "dealer_order_id": order_id,
            "dealer_id": order.get("dealer_id"),
            "customer_name": dealer.get("firm_name") if dealer else order.get("dealer_name"),
            "customer_phone": dealer.get("phone") if dealer else order.get("dealer_phone"),
            "address": dealer.get("address") if dealer else None,
            "items": pf_items,
            "total_amount": order.get("total_amount"),
            "invoice_value": order.get("total_amount"),  # canonical monetary field
            "order_source": "dealer",
            "status": "pending_dispatch",
            "payment_status": "received",
            "firm_id": dealer.get("firm_id") if dealer else None,
            "created_by": user["id"],
            "created_at": now,
            "updated_at": now
        }
        await db.pending_fulfillment.insert_one(pf_doc)
    
    return {"message": "Payment confirmed, order status updated"}


@api_router.post("/admin/dealer-orders/{order_id}/dispatch")
async def dispatch_dealer_order(
    order_id: str,
    dispatch_date: str = Form(...),
    courier: str = Form(...),
    tracking_id: str = Form(...),
    invoice_number: str = Form(...),
    invoice_date: str = Form(None),
    invoice_file: UploadFile = File(...),
    shipping_label: UploadFile = File(...),
    remarks: str = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant", "dispatcher"]))
):
    """Dispatch dealer order — uploads invoice + label, deducts stock, creates sales records, notifies dealer."""
    order = await db.dealer_orders.find_one({"id": order_id})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    if order.get("payment_status") != "received":
        raise HTTPException(status_code=400, detail="Cannot dispatch: payment not confirmed yet")
    if order.get("status") in ("dispatched", "delivered", "cancelled"):
        raise HTTPException(status_code=400, detail=f"Order already {order.get('status')}")
    if order.get("stock_deducted"):
        raise HTTPException(status_code=400, detail="Stock already deducted for this order")
    
    now = datetime.now(timezone.utc).isoformat()
    
    # Upload invoice file
    try:
        inv_bytes = await invoice_file.read()
        inv_path, _ = await storage_upload(
            file_data=inv_bytes,
            folder="dealer_invoices",
            original_filename=invoice_file.filename,
            filename_prefix=f"inv_{order_id}"
        )
        invoice_url = f"/api/files/{inv_path}"
    except Exception as e:
        logger.error(f"Dealer invoice upload failed for {order_id}: {e}")
        raise HTTPException(status_code=500, detail=f"Invoice upload failed: {e}")
    
    # Upload shipping label
    try:
        lbl_bytes = await shipping_label.read()
        lbl_path, _ = await storage_upload(
            file_data=lbl_bytes,
            folder="dealer_shipping_labels",
            original_filename=shipping_label.filename,
            filename_prefix=f"label_{order_id}"
        )
        shipping_label_url = f"/api/files/{lbl_path}"
    except Exception as e:
        logger.error(f"Dealer shipping label upload failed for {order_id}: {e}")
        raise HTTPException(status_code=500, detail=f"Shipping label upload failed: {e}")
    
    # Atomic guard to prevent double-dispatch / double stock deduction
    lock = await db.dealer_orders.find_one_and_update(
        {"id": order_id, "status": {"$nin": ["dispatched", "delivered", "cancelled"]}, "stock_deducted": {"$ne": True}},
        {"$set": {"stock_deducted": True, "dispatch_in_progress": True, "updated_at": now}},
        return_document=False
    )
    if not lock:
        raise HTTPException(status_code=409, detail="Dispatch already in progress or completed")
    
    # Stock deduction per item
    dealer = await db.dealers.find_one({"id": order.get("dealer_id")})
    firm_id = dealer.get("firm_id") if dealer else None
    firm = await db.firms.find_one({"id": firm_id}) if firm_id else None
    ledger_entries = []
    for item in order.get("items", []):
        dp = await db.dealer_products.find_one({"id": item.get("product_id")}, {"_id": 0})
        master_sku_id = dp.get("master_sku_id") if dp else None
        if not master_sku_id:
            continue
        master_sku = await db.master_skus.find_one({"id": master_sku_id})
        if not master_sku:
            continue
        qty = item.get("quantity", 1)
        current_stock = await get_current_stock("master_sku", master_sku_id, firm_id) if firm_id else 0
        ledger_entries.append({
            "id": str(uuid.uuid4()),
            "entry_number": f"LED-{datetime.now(timezone.utc).strftime('%Y%m%d')}-{str(uuid.uuid4())[:8].upper()}",
            "entry_type": "dispatch_out",
            "item_type": "master_sku",
            "item_id": master_sku_id,
            "item_name": master_sku.get("name"),
            "item_sku": master_sku.get("sku_code"),
            "firm_id": firm_id,
            "firm_name": firm.get("name") if firm else None,
            "quantity": qty,
            "running_balance": current_stock - qty,
            "reference_id": order_id,
            "reference_type": "dealer_order",
            "notes": f"Dealer dispatch - Order: {order.get('order_number')}",
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
            "created_at": now
        })
    if ledger_entries:
        await db.inventory_ledger.insert_many(ledger_entries)
    
    # Final dealer_orders update
    await db.dealer_orders.update_one(
        {"id": order_id},
        {"$set": {
            "status": "dispatched",
            "dispatch_date": dispatch_date,
            "dispatch_courier": courier,
            "dispatch_awb": tracking_id,
            "tracking_id": tracking_id,
            "dispatch_remarks": remarks,
            "dispatched_by": user["id"],
            "final_invoice_number": invoice_number,
            "final_invoice_date": invoice_date or dispatch_date,
            "invoice_url": invoice_url,
            "shipping_label_url": shipping_label_url,
            "stock_deducted_at": now,
            "ledger_entry_ids": [e["id"] for e in ledger_entries],
            "dispatch_in_progress": False,
            "updated_at": now
        }}
    )
    
    # Update pending_fulfillment entry to dispatched
    await db.pending_fulfillment.update_one(
        {"dealer_order_id": order_id},
        {"$set": {"status": "dispatched", "dispatched_at": now, "updated_at": now}}
    )
    
    # Create sales_orders entry (one per line item so reports stay accurate)
    for item in order.get("items", []):
        dp = await db.dealer_products.find_one({"id": item.get("product_id")}, {"_id": 0})
        _so_date_d = datetime.now(timezone.utc).strftime('%Y%m%d')
        _so_counter_d = await db.counters.find_one_and_update(
            {"_id": f"sales_order:{_so_date_d}"},
            {"$inc": {"seq": 1}},
            upsert=True,
            return_document=True,
        )
        so_count = int((_so_counter_d or {}).get("seq", 1))
        so_doc = {
            "id": str(uuid.uuid4()),
            "order_number": f"SO-{_so_date_d}-{so_count:04d}",
            "dispatch_id": None,
            "firm_id": firm_id,
            "firm_name": firm.get("name") if firm else None,
            "order_category": "dealer_order",
            "order_source": "dealer",
            "dealer_order_id": order_id,
            "dealer_id": order.get("dealer_id"),
            "order_id": order.get("order_number"),
            "customer_name": dealer.get("firm_name") if dealer else order.get("dealer_name"),
            "phone": dealer.get("phone") if dealer else order.get("dealer_phone"),
            "address": dealer.get("address") if dealer else None,
            "state": dealer.get("state") if dealer else None,
            "sku": item.get("sku"),
            "master_sku_id": dp.get("master_sku_id") if dp else None,
            "master_sku_name": item.get("product_name"),
            "quantity": item.get("quantity", 1),
            "unit_price": item.get("unit_price"),
            "total_amount": item.get("line_total"),
            "gst_rate": item.get("gst_rate"),
            "gst_amount": item.get("gst_amount"),
            "payment_status": "paid",
            "payment_mode": "direct",
            "tracking_id": tracking_id,
            "courier": courier,
            "dispatch_status": "dispatched",
            "invoice_url": invoice_url,
            "invoice_number": invoice_number,
            "created_by": user["id"],
            "created_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
            "created_at": now,
            "updated_at": now,
            "dispatched_at": now
        }
        await db.sales_orders.insert_one(so_doc)
    
    # Create sales_invoices entry for GST compliance — atomic counter.
    _si_date = datetime.now(timezone.utc).strftime('%Y%m%d')
    _si_counter = await db.counters.find_one_and_update(
        {"_id": f"sales_invoice_legacy:{_si_date}"},
        {"$inc": {"seq": 1}},
        upsert=True,
        return_document=True,
    )
    si_count = int((_si_counter or {}).get("seq", 1))
    subtotal = sum(i.get("line_total", 0) - i.get("gst_amount", 0) for i in order.get("items", []))
    total_gst = sum(i.get("gst_amount", 0) for i in order.get("items", []))
    grand_total = order.get("total_amount", 0)
    invoice_doc = {
        "id": str(uuid.uuid4()),
        "invoice_number": invoice_number,
        "invoice_date": invoice_date or dispatch_date,
        "firm_id": firm_id,
        "firm_name": firm.get("name") if firm else None,
        "source": "dealer_order",
        "dealer_order_id": order_id,
        "dealer_id": order.get("dealer_id"),
        "customer_name": dealer.get("firm_name") if dealer else order.get("dealer_name"),
        "customer_gst": dealer.get("gst_number") if dealer else None,
        "customer_state": dealer.get("state") if dealer else None,
        "customer_address": dealer.get("address") if dealer else None,
        "items": order.get("items", []),
        "subtotal": subtotal,
        "total_gst": total_gst,
        "grand_total": grand_total,
        "payment_status": "paid",
        "invoice_url": invoice_url,
        "created_by": user["id"],
        "created_at": now
    }
    await db.sales_invoices.insert_one(invoice_doc)

    # Post the sales-invoice DEBIT to the dealer's party ledger. This is the
    # other half of double-entry: the dealer owes us for the goods invoiced.
    # The payment CREDIT was posted earlier at confirm-payment, so once both
    # exist the dealer's running_balance nets back to (minus their deposit).
    dealer_party = await db.parties.find_one({"dealer_id": order.get("dealer_id")})
    if dealer_party:
        inv_led = await create_party_ledger_entry_atomic(
            party_id=dealer_party["id"],
            party_name=dealer_party["name"],
            entry_type="sales_invoice",
            debit=grand_total or 0,
            credit=0,
            narration=f"Invoice {invoice_number} for dealer order {order.get('order_number')}",
            reference_type="dealer_order_invoice",
            reference_id=order_id,
            firm_id=dealer_party.get("firm_id") or firm_id,
            user_id=user["id"],
            user_name=f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
            entry_number=f"INV-{invoice_number}",
            opening_balance=dealer_party.get("opening_balance", 0),
        )
        await db.parties.update_one(
            {"id": dealer_party["id"]},
            {"$set": {"current_balance": inv_led["running_balance"], "updated_at": now}}
        )

    # Notify dealer via in-app notification
    await create_notification(
        title="Order Dispatched",
        message=f"Your order {order.get('order_number')} has shipped via {courier} (Tracking: {tracking_id}).",
        notification_type="success",
        link="/dealer/orders",
        target_roles=["dealer"],
        priority="normal"
    )
    
    # Email dealer if email available
    if dealer and dealer.get("email"):
        try:
            asyncio.create_task(send_dispatch_email({
                "customer_name": dealer.get("firm_name"),
                "customer_email": dealer.get("email"),
                "order_id": order.get("order_number"),
                "tracking_id": tracking_id,
                "courier": courier,
                "invoice_url": invoice_url,
                "shipping_label_url": shipping_label_url
            }))
        except Exception as e:
            logger.error(f"Dealer dispatch email failed for {order_id}: {e}")
    
    # Audit log
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "dealer_order_dispatched",
        "entity_type": "dealer_order",
        "entity_id": order_id,
        "entity_name": order.get("order_number"),
        "performed_by": user["id"],
        "performed_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
        "details": {
            "invoice_number": invoice_number,
            "tracking_id": tracking_id,
            "courier": courier,
            "total_amount": grand_total,
            "ledger_entries": len(ledger_entries)
        },
        "timestamp": now
    })
    
    return {
        "message": "Order dispatched successfully",
        "order_id": order_id,
        "invoice_number": invoice_number,
        "tracking_id": tracking_id,
        "invoice_url": invoice_url,
        "shipping_label_url": shipping_label_url
    }


@api_router.post("/admin/dealer-orders/{order_id}/cancel")
async def cancel_dealer_order(
    order_id: str,
    reason: str = Form(...),
    user: dict = Depends(require_roles(["admin"]))
):
    """Cancel dealer order"""
    order = await db.dealer_orders.find_one({"id": order_id})
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    if order.get("status") in ("dispatched", "delivered", "cancelled"):
        raise HTTPException(status_code=400, detail=f"Cannot cancel: order is {order.get('status')}")
    
    now = datetime.now(timezone.utc).isoformat()
    
    await db.dealer_orders.update_one(
        {"id": order_id},
        {"$set": {
            "status": "cancelled",
            "cancellation_reason": reason,
            "cancelled_by": user["id"],
            "cancelled_at": now,
            "updated_at": now
        }}
    )

    # If payment was received, a CREDIT was posted to the dealer's ledger at
    # confirm-payment. The order never dispatched (cancel is blocked once
    # dispatched/delivered), so there's no offsetting sales-invoice DEBIT —
    # cancelling without reversing leaves a phantom credit. Post a reversing
    # DEBIT (once) for the credited amount.
    if order.get("payment_status") == "received":
        already = await db.party_ledger.find_one(
            {"reference_type": "dealer_order_cancel_reversal", "reference_id": order_id}, {"_id": 1})
        paid_credit = await db.party_ledger.find_one(
            {"reference_type": "dealer_order_payment", "reference_id": order_id}, {"_id": 0, "credit": 1})
        if paid_credit and not already:
            party = await db.parties.find_one({"dealer_id": order["dealer_id"]})
            if party:
                amt = paid_credit.get("credit") or order.get("total_amount", 0) or 0
                led = await create_party_ledger_entry_atomic(
                    party_id=party["id"], party_name=party["name"],
                    entry_type="dealer_order_cancel_reversal", debit=amt, credit=0,
                    narration=f"Reversal of payment credit — dealer order {order.get('order_number')} cancelled",
                    reference_type="dealer_order_cancel_reversal", reference_id=order_id,
                    firm_id=party.get("firm_id") or order.get("firm_id"),
                    user_id=user["id"],
                    user_name=f"{user.get('first_name','')} {user.get('last_name','')}".strip(),
                    opening_balance=party.get("opening_balance", 0),
                )
                await db.parties.update_one(
                    {"id": party["id"]},
                    {"$set": {"current_balance": led["running_balance"], "updated_at": now}})

    return {"message": "Order cancelled"}


