@api_router.post("/dealer/tickets")
async def create_dealer_ticket(
    issue_description: str = Form(...),
    product_id: str = Form(None),
    subject: str = Form(None),
    issue_type: str = Form(None),
    customer_name: str = Form(None),
    customer_phone: str = Form(None),
    attachment: UploadFile = File(None),
    user: dict = Depends(require_roles(["dealer"]))
):
    """Create support ticket from dealer"""
    dealer = await db.dealers.find_one({"user_id": user["id"]})
    if not dealer:
        raise HTTPException(status_code=404, detail="Dealer profile not found")
    
    now = datetime.now(timezone.utc).isoformat()
    ticket_id = str(uuid.uuid4())
    ticket_number = await generate_dealer_ticket_number()
    
    attachment_path = None
    if attachment:
        try:
            content = await attachment.read()
            relative_path, storage_type = await storage_upload(
                file_data=content,
                folder="dealer_tickets",
                original_filename=attachment.filename,
                filename_prefix=ticket_id
            )
            attachment_path = f"/api/files/{relative_path}"
        except StorageError as e:
            logger.error(f"Failed to upload dealer ticket attachment: {str(e)}")
            raise HTTPException(status_code=500, detail=f"File upload failed: {str(e)}")
    
    # Get product info if provided
    product_name = None
    if product_id:
        product = await db.dealer_products.find_one({"id": product_id})
        if product:
            product_name = product["name"]
    
    ticket_doc = {
        "id": ticket_id,
        "ticket_number": ticket_number,
        "dealer_id": dealer["id"],
        "dealer_name": dealer["firm_name"],
        "product_id": product_id,
        "product_name": product_name,
        "subject": subject,
        "issue_type": issue_type,
        "customer_name": customer_name,
        "customer_phone": customer_phone,
        "issue_description": issue_description,
        "attachment_path": attachment_path,
        "status": "open",
        "admin_notes": None,
        "dealer_message": None,
        "legacy_ticket_id": None,
        "created_at": now,
        "updated_at": now
    }
    
    await db.dealer_tickets.insert_one(ticket_doc)

    # Upsert into dealer's customer book if customer info was provided
    if customer_phone:
        cust_id = await _upsert_dealer_customer(
            dealer_id=dealer["id"],
            dealer_name=dealer.get("firm_name"),
            customer={"name": customer_name, "phone": customer_phone},
            source="ticket",
            source_id=ticket_id,
        )
        if cust_id:
            c = await db.dealer_customers.find_one({"id": cust_id}, {"phone_normalized": 1})
            if c:
                await _refresh_dealer_customer_counters(dealer["id"], c["phone_normalized"])

    # Notify admin
    await create_notification(
        title="New Dealer Ticket",
        message=f"Dealer {dealer['firm_name']} raised ticket: {issue_description[:50]}...",
        notification_type="dealer",
        link="/admin/dealer-tickets",
        target_roles=["admin"],
        priority="normal"
    )

    return {"id": ticket_id, "ticket_number": ticket_number, "message": "Ticket created"}


