@api_router.post("/chat/upload")
async def chat_upload(file: UploadFile = File(...), user: dict = Depends(require_internal_chat)):
    content = await file.read()
    if len(content) > 25 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="File too large (max 25MB)")
    try:
        rel, _ = await storage_upload(file_data=content, folder="chat", original_filename=file.filename or "file")
    except StorageError as e:
        raise HTTPException(status_code=500, detail=f"Upload failed: {e}")
    return {"url": f"/api/files/{rel}", "name": file.filename, "type": file.content_type, "size": len(content)}


@api_router.get("/chat/stream")
async def chat_stream(request: Request, token: str = Query(None)):
    """SSE stream of chat events for the authenticated internal user. Also drives
    presence (the user is 'online' while a stream is open)."""
    if not token:
        raise HTTPException(status_code=401, detail="token query param required")
    try:
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGORITHM])
        u = await db.users.find_one({"id": payload.get("user_id")})
        if not u or u.get("role") not in INTERNAL_CHAT_ROLES:
            raise HTTPException(status_code=403, detail="Not allowed")
    except jwt.PyJWTError:
        raise HTTPException(status_code=401, detail="Invalid token")
    uid = u["id"]
    queue: asyncio.Queue = asyncio.Queue(maxsize=200)
    first = uid not in _chat_online_ids()
    CHAT_SUBSCRIBERS.setdefault(uid, set()).add(queue)
    if first:
        await broadcast_chat(_chat_online_ids(), {"type": "presence", "user_id": uid, "online": True})

    async def event_gen():
        try:
            yield ": connected\n\n"
            while True:
                if await request.is_disconnected():
                    break
                try:
                    event = await asyncio.wait_for(queue.get(), timeout=20.0)
                    yield f"event: chat\ndata: {json.dumps(event)}\n\n"
                except asyncio.TimeoutError:
                    yield f": ping {datetime.now(timezone.utc).isoformat()}\n\n"
        finally:
            qs = CHAT_SUBSCRIBERS.get(uid)
            if qs:
                qs.discard(queue)
                if not qs:
                    CHAT_SUBSCRIBERS.pop(uid, None)
                    await broadcast_chat(_chat_online_ids(), {"type": "presence", "user_id": uid, "online": False})

    return StreamingResponse(event_gen(), media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache, no-transform", "X-Accel-Buffering": "no", "Connection": "keep-alive"})


@api_router.post("/smartflo/webhook")
async def smartflo_webhook(request: Request):
    """
    Receive call data from Tata Smartflo IVR system.
    Requires X-Webhook-Secret header matching SMARTFLO_WEBHOOK_SECRET env.
    """
    if not SMARTFLO_WEBHOOK_SECRET:
        raise HTTPException(status_code=503, detail="Smartflo webhook secret not configured")
    if not _const_eq(request.headers.get("x-webhook-secret", ""), SMARTFLO_WEBHOOK_SECRET):
        raise HTTPException(status_code=401, detail="Invalid webhook secret")
    now = datetime.now(timezone.utc)

    try:
        # Get the raw JSON body
        body = await request.json()
        
        # Log the incoming webhook for debugging
        logger.info(f"Smartflo webhook received: {body}")
        
        # ====== DEDUP: Check if this webhook was already processed ======
        # Use uuid or call_id as idempotency key
        webhook_uuid = body.get("uuid") or body.get("call_id")
        if webhook_uuid:
            existing = await db.smartflo_calls.find_one({"uuid": webhook_uuid})
            if existing:
                logger.info(f"Smartflo webhook duplicate - uuid {webhook_uuid} already exists")
                return {"status": "duplicate", "message": "Call already recorded", "call_id": existing.get("id")}
        
        # Extract call data from webhook payload
        call_record = {
            "id": str(uuid.uuid4()),
            "source": "smartflo",
            "raw_data": body,
            
            # Standard fields from Smartflo
            "uuid": body.get("uuid"),
            "call_to_number": body.get("call_to_number"),
            "caller_id_number": body.get("caller_id_number"),
            "caller_phone": body.get("caller_id_number"),  # Alias for easy lookup
            "start_stamp": body.get("start_stamp"),
            "call_id": body.get("call_id"),
            "billing_circle": body.get("billing_circle"),
            "customer_no_with_prefix": body.get("customer_no_with_prefix"),
            
            # Additional fields that may be present
            "call_flow": body.get("call_flow"),
            "dept_id": body.get("dept_id"),
            "dept_name": body.get("dept_name"),
            "ivr_name": body.get("ivr_name"),
            "agent_name": body.get("agent_name") or body.get("answered_agent_name") or body.get("missed_agent"),
            "agent_number": body.get("agent_number") or body.get("answered_agent_number"),
            "answered_agent_name": body.get("answered_agent_name"),
            "answered_agent_number": body.get("answered_agent_number"),
            "missed_agent": body.get("missed_agent"),
            "duration": body.get("duration") or body.get("billsec"),
            "call_status": body.get("call_status"),
            "recording_url": body.get("recording_url"),
            "date": body.get("date"),
            
            # Metadata
            "received_at": now.isoformat(),
            "processed": False
        }
        
        # Store in database
        await db.smartflo_calls.insert_one(call_record)
        
        # Try to match with existing customer/ticket by phone number
        caller_phone = body.get("caller_id_number", "")
        if caller_phone:
            # Clean phone number (remove +91 prefix if present)
            clean_phone = caller_phone.replace("+91", "").replace(" ", "").strip()
            if len(clean_phone) > 10:
                clean_phone = clean_phone[-10:]  # Get last 10 digits
            
            # Look up customer in tickets
            ticket = await db.tickets.find_one(
                {"phone": {"$regex": clean_phone}},
                {"_id": 0, "id": 1, "ticket_number": 1, "customer_name": 1, "phone": 1}
            )
            
            if ticket:
                # Update call record with matched ticket info
                await db.smartflo_calls.update_one(
                    {"id": call_record["id"]},
                    {"$set": {
                        "matched_ticket_id": ticket.get("id"),
                        "matched_ticket_number": ticket.get("ticket_number"),
                        "matched_customer_name": ticket.get("customer_name"),
                        "processed": True
                    }}
                )
                logger.info(f"Smartflo call matched to ticket: {ticket.get('ticket_number')}")
        
        # ========== SEND POST-CALL SMS ==========
        # Send SMS to caller after every call (missed, answered, any type)
        if caller_phone:
            # Determine call type for logging
            call_status = body.get("call_status", "unknown")
            call_type = "missed" if body.get("missed_agent") else "answered" if body.get("answered_agent_name") else call_status

            # Send SMS asynchronously (don't block webhook response)
            import asyncio
            asyncio.create_task(send_post_call_sms(caller_phone, call_type))
            logger.info(f"Triggered post-call SMS for {caller_phone} (call type: {call_type})")

            # On a MISSED call, also WhatsApp the caller (opt-in via MISSED_CALL_WA_ENABLED).
            if call_type == "missed":
                asyncio.create_task(send_missed_call_whatsapp(caller_phone, call_type))

        # ========== SCREEN-POP BROADCAST ==========
        # Notify connected agents about the inbound call so the browser can pop
        # a 360° caller card. Only broadcast on the initial ringing event —
        # Smartflo posts a single webhook per call, so this fires once.
        if caller_phone:
            asyncio.create_task(broadcast_screen_pop({
                "type": "inbound_call",
                "call_id": call_record["id"],
                "uuid": call_record.get("uuid"),
                "phone": _normalize_phone(caller_phone),
                "raw_phone": caller_phone,
                "agent_name": body.get("answered_agent_name") or body.get("missed_agent"),
                "dept_name": body.get("dept_name"),
                "received_at": now.isoformat(),
            }))
        
        return {"status": "success", "message": "Call data received", "call_id": call_record["id"]}
        
    except Exception as e:
        logger.error(f"Smartflo webhook error: {str(e)}")
        # Still return 200 to prevent Smartflo from retrying
        return {"status": "error", "message": str(e)}


@api_router.get("/smartflo/calls")
async def get_smartflo_calls(
    limit: int = 50,
    phone: Optional[str] = None,
    user: dict = Depends(require_roles(["admin", "call_support", "supervisor"]))
):
    """Get recent Smartflo call logs"""
    query = {}
    if phone:
        query["caller_phone"] = {"$regex": phone}
    
    calls = await db.smartflo_calls.find(
        query, 
        {"_id": 0}
    ).sort("received_at", -1).limit(limit).to_list(limit)
    
    return {"calls": calls, "total": len(calls)}


@api_router.get("/smartflo/agents")
async def get_smartflo_agents(
    user: dict = Depends(require_roles(["admin", "supervisor"]))
):
    """Get Smartflo agents — never expose per-agent api_key in the response.

    These keys are reused as click-to-call Bearer tokens; previously any
    supervisor session could exfiltrate them all in one request.
    """
    projection = {
        "_id": 0,
        "api_key": 0,
        "secret": 0,
        "auth_token": 0,
    }
    agents = await db.smartflo_agents.find({}, projection).to_list(100)
    # Add a boolean so the UI can show "Key configured" without leaking the value.
    for a in agents:
        a["has_api_key"] = bool(a.pop("_has_key", True))
    return {"agents": agents}


@api_router.get("/sms/logs")
async def get_sms_logs(
    limit: int = 50,
    phone: Optional[str] = None,
    success_only: bool = False,
    user: dict = Depends(require_roles(["admin"]))
):
    """Get post-call SMS logs"""
    query = {}
    if phone:
        clean_phone = phone.replace("+91", "").replace(" ", "").strip()
        if len(clean_phone) > 10:
            clean_phone = clean_phone[-10:]
        query["phone"] = {"$regex": clean_phone}
    if success_only:
        query["success"] = True
    
    logs = await db.sms_logs.find(query, {"_id": 0}).sort("sent_at", -1).limit(limit).to_list(limit)
    total = await db.sms_logs.count_documents(query)
    
    # Get stats
    today_start = datetime.now(timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
    today_total = await db.sms_logs.count_documents({"sent_at": {"$gte": today_start.isoformat()}})
    today_success = await db.sms_logs.count_documents({"sent_at": {"$gte": today_start.isoformat()}, "success": True})
    
    return {
        "logs": logs,
        "total": total,
        "stats": {
            "today_total": today_total,
            "today_success": today_success,
            "today_failed": today_total - today_success
        }
    }


