@api_router.get("/smartflo/agent-performance")
async def get_smartflo_agent_performance(
    days: int = 30,
    user: dict = Depends(require_roles(["admin", "supervisor"]))
):
    """Get detailed agent performance metrics for admin dashboard"""
    from datetime import timedelta
    
    cutoff_date = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
    
    # Get all calls within the period
    calls = await db.smartflo_calls.find({
        "received_at": {"$gte": cutoff_date}
    }).to_list(10000)
    
    # Get all agents
    agents = await db.smartflo_agents.find({}).to_list(100)
    agent_map = {a.get("name"): a for a in agents}
    
    # Calculate metrics per agent
    agent_metrics = {}
    
    for call in calls:
        # Get agent name from multiple possible fields
        raw = call.get("raw_data") or {}
        agent_name = (
            call.get("agent_name") or 
            call.get("answered_agent_name") or 
            raw.get("answered_agent_name") or
            raw.get("agent_name") or
            raw.get("missed_agent")
        )
        
        # Handle case where agent_name might be a list
        if isinstance(agent_name, list):
            agent_name = agent_name[0] if agent_name else None
        
        if not agent_name or not isinstance(agent_name, str):
            continue
            
        if agent_name not in agent_metrics:
            agent_metrics[agent_name] = {
                "name": agent_name,
                "department": call.get("dept_name", "Unknown"),
                "total_calls": 0,
                "answered": 0,
                "missed": 0,
                "total_duration": 0,
                "outcomes": {},
                "quality_scores": [],
                "customer_satisfaction": {"high": 0, "medium": 0, "low": 0},
                "red_flags_count": 0,
                "unresolved_count": 0
            }
        
        metrics = agent_metrics[agent_name]
        metrics["total_calls"] += 1
        
        # Call status - check multiple fields to determine if answered
        raw_data = call.get("raw_data", {})
        event_type = raw_data.get("event_type", "")
        duration = raw_data.get("duration", 0) or call.get("duration", 0) or 0
        status = call.get("status", "")
        
        is_answered = (
            event_type == "answered" or 
            status == "Answered" or 
            (duration and int(duration) > 0)
        )
        
        if is_answered:
            metrics["answered"] += 1
            metrics["total_duration"] += int(duration) if duration else 0
        else:
            metrics["missed"] += 1
        
        # Outcome tracking
        outcome = call.get("outcome")
        if outcome:
            metrics["outcomes"][outcome] = metrics["outcomes"].get(outcome, 0) + 1
        
        # AI Analysis metrics
        ai_analysis = call.get("ai_analysis", {}).get("analysis", {})
        if ai_analysis:
            if ai_analysis.get("call_quality_score"):
                metrics["quality_scores"].append(ai_analysis["call_quality_score"])
            
            satisfaction = ai_analysis.get("customer_satisfaction_likely")
            if satisfaction in ["high", "medium", "low"]:
                metrics["customer_satisfaction"][satisfaction] += 1
            
            if ai_analysis.get("red_flags"):
                metrics["red_flags_count"] += len(ai_analysis["red_flags"])
            
            if ai_analysis.get("issue_resolved") == False:
                metrics["unresolved_count"] += 1
    
    # Calculate summary metrics
    performance_data = []
    for name, metrics in agent_metrics.items():
        total = metrics["total_calls"]
        answered = metrics["answered"]
        missed = metrics["missed"]
        
        # Calculate averages
        avg_duration = metrics["total_duration"] / answered if answered > 0 else 0
        avg_quality = sum(metrics["quality_scores"]) / len(metrics["quality_scores"]) if metrics["quality_scores"] else None
        
        # Performance indicators
        miss_rate = (missed / total * 100) if total > 0 else 0
        resolution_rate = ((total - metrics["unresolved_count"]) / total * 100) if total > 0 else 0
        
        # Customer satisfaction rate (high / (high + medium + low))
        total_satisfaction = sum(metrics["customer_satisfaction"].values())
        satisfaction_rate = (metrics["customer_satisfaction"]["high"] / total_satisfaction * 100) if total_satisfaction > 0 else None
        
        # Performance issues
        issues = []
        if miss_rate > 30:
            issues.append(f"High miss rate: {miss_rate:.0f}% of calls missed")
        if avg_quality and avg_quality < 5:
            issues.append(f"Low call quality: Average score {avg_quality:.1f}/10")
        if metrics["red_flags_count"] > 3:
            issues.append(f"Multiple red flags: {metrics['red_flags_count']} issues flagged")
        if satisfaction_rate is not None and satisfaction_rate < 50:
            issues.append(f"Low customer satisfaction: Only {satisfaction_rate:.0f}% happy")
        if resolution_rate < 70:
            issues.append(f"Low resolution rate: {resolution_rate:.0f}% resolved")
        
        # Overall status
        if len(issues) >= 3:
            status = "needs_attention"
        elif len(issues) >= 1:
            status = "average"
        else:
            status = "good"
        
        performance_data.append({
            "agent_name": name,
            "department": metrics["department"],
            "total_calls": total,
            "answered": answered,
            "missed": missed,
            "miss_rate": round(miss_rate, 1),
            "avg_duration_seconds": round(avg_duration, 0),
            "avg_quality_score": round(avg_quality, 1) if avg_quality else None,
            "satisfaction_rate": round(satisfaction_rate, 1) if satisfaction_rate is not None else None,
            "resolution_rate": round(resolution_rate, 1),
            "red_flags_count": metrics["red_flags_count"],
            "unresolved_count": metrics["unresolved_count"],
            "outcomes": metrics["outcomes"],
            "issues": issues,
            "status": status
        })
    
    # Sort by status (needs_attention first) then by total calls
    performance_data.sort(key=lambda x: (0 if x["status"] == "needs_attention" else 1 if x["status"] == "average" else 2, -x["total_calls"]))
    
    return {
        "period_days": days,
        "total_agents": len(performance_data),
        "agents_needing_attention": len([a for a in performance_data if a["status"] == "needs_attention"]),
        "agents": performance_data
    }


async def _qa_score_transcript(transcript_text: str) -> dict:
    """Score a call transcript on 5 supervisor-coaching criteria using OpenAI."""
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key or not transcript_text:
        return {"error": "OPENAI_API_KEY missing or empty transcript"}

    system_prompt = (
        "You are a strict QA reviewer for a customer-support call centre. Score the agent on a 1–5 scale "
        "for each of five criteria. 1 = poor, 3 = acceptable, 5 = excellent. Be honest, not generous.\n\n"
        "Criteria:\n"
        "- greeting: opened the call professionally, identified self/company\n"
        "- empathy: acknowledged customer's situation, used courteous language\n"
        "- resolution: addressed the issue substantively or set a clear next step\n"
        "- handoff: if escalation/transfer happened, was it explained and warm? If no handoff occurred, score 5\n"
        "- close: ended with a clear summary, next steps, and polite sign-off\n\n"
        "Return ONLY valid JSON: "
        '{ "greeting":<1-5>, "empathy":<1-5>, "resolution":<1-5>, "handoff":<1-5>, "close":<1-5>, '
        '"overall":<weighted average rounded to 1 decimal>, '
        '"coaching_tip":"<one specific, actionable sentence the agent should fix next call>" }'
    )
    try:
        import httpx
        async with httpx.AsyncClient(timeout=30.0) as client:
            r = await client.post(
                "https://api.openai.com/v1/chat/completions",
                headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                json={
                    "model": "gpt-4o-mini",
                    "temperature": 0.0,
                    "response_format": {"type": "json_object"},
                    "messages": [
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": transcript_text[:12000]},
                    ],
                },
            )
            r.raise_for_status()
            text = r.json()["choices"][0]["message"]["content"]
            return {"ok": True, "scorecard": json.loads(text)}
    except Exception as e:
        return {"error": str(e)}


@api_router.post("/smartflo/calls/{call_id}/qa-score")
async def qa_score_call(
    call_id: str,
    force: bool = Query(False),
    user: dict = Depends(require_roles(["supervisor", "admin"]))
):
    """Score a single call on the 5-criteria QA scorecard. Requires existing transcript."""
    call = await db.smartflo_calls.find_one({"id": call_id}) or await db.smartflo_calls.find_one({"uuid": call_id})
    if not call:
        raise HTTPException(status_code=404, detail="Call not found")
    if not force and call.get("qa_scorecard"):
        return {"cached": True, "scorecard": call["qa_scorecard"]}
    transcript = (call.get("ai_analysis") or {}).get("transcript") or ""
    if not transcript:
        raise HTTPException(status_code=400, detail="No transcript available — run /analyze first")

    result = await _qa_score_transcript(transcript)
    if not result.get("ok"):
        raise HTTPException(status_code=502, detail=result.get("error") or "QA scoring failed")

    sc = result["scorecard"]
    sc["scored_at"] = datetime.now(timezone.utc).isoformat()
    sc["scored_by"] = user.get("email") or user.get("id")
    await db.smartflo_calls.update_one({"_id": call["_id"]}, {"$set": {"qa_scorecard": sc}})
    return {"cached": False, "scorecard": sc}


@api_router.get("/smartflo/qa/agent-scorecards")
async def qa_agent_scorecards(
    days: int = 30,
    user: dict = Depends(require_roles(["supervisor", "admin"]))
):
    """Rolling per-agent averages on the 5-criteria scorecard over the last `days`."""
    cutoff = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
    cursor = db.smartflo_calls.find(
        {"qa_scorecard": {"$exists": True}, "received_at": {"$gte": cutoff}},
        {"_id": 0, "agent_name": 1, "qa_scorecard": 1, "received_at": 1,
         "raw_data.answered_agent_name": 1}
    )
    buckets: dict = {}
    async for call in cursor:
        agent = (
            call.get("agent_name")
            or ((call.get("raw_data") or {}).get("answered_agent_name") if isinstance(call.get("raw_data"), dict) else None)
            or "Unassigned"
        )
        b = buckets.setdefault(agent, {
            "agent_name": agent,
            "calls": 0,
            "totals": {"greeting": 0.0, "empathy": 0.0, "resolution": 0.0, "handoff": 0.0, "close": 0.0, "overall": 0.0},
            "weakest_count": {"greeting": 0, "empathy": 0, "resolution": 0, "handoff": 0, "close": 0},
            "latest_coaching": [],
        })
        sc = call.get("qa_scorecard") or {}
        b["calls"] += 1
        for k in b["totals"].keys():
            try:
                b["totals"][k] += float(sc.get(k) or 0)
            except (TypeError, ValueError):
                pass
        # Track each call's weakest criterion
        sub_scores = {k: sc.get(k) for k in ("greeting", "empathy", "resolution", "handoff", "close") if sc.get(k) is not None}
        if sub_scores:
            weakest = min(sub_scores, key=sub_scores.get)
            b["weakest_count"][weakest] = b["weakest_count"].get(weakest, 0) + 1
        if sc.get("coaching_tip") and len(b["latest_coaching"]) < 3:
            b["latest_coaching"].append({"tip": sc["coaching_tip"], "scored_at": sc.get("scored_at")})

    out = []
    for agent, b in buckets.items():
        n = b["calls"]
        averages = {k: round(v / n, 2) for k, v in b["totals"].items()} if n else b["totals"]
        weakest_overall = max(b["weakest_count"], key=b["weakest_count"].get) if b["weakest_count"] else None
        out.append({
            "agent_name": agent,
            "calls_scored": n,
            "averages": averages,
            "weakest_criterion": weakest_overall,
            "latest_coaching": b["latest_coaching"],
        })
    out.sort(key=lambda x: (-x["calls_scored"], x["agent_name"]))
    return {"period_days": days, "agents": out}


@api_router.put("/smartflo/calls/{call_id}/outcome")
async def update_call_outcome(
    call_id: str,
    outcome: str = Query(...),
    notes: Optional[str] = None,
    user: dict = Depends(get_current_user)
):
    """Update call outcome and notes"""
    from bson import ObjectId
    
    # Try to find call by multiple ID formats
    call = None
    
    # First try by our generated 'id' field
    call = await db.smartflo_calls.find_one({"id": call_id})
    
    # Then try by Smartflo UUID
    if not call:
        call = await db.smartflo_calls.find_one({"uuid": call_id})
    
    # Finally try by MongoDB ObjectId
    if not call:
        try:
            obj_id = ObjectId(call_id)
            call = await db.smartflo_calls.find_one({"_id": obj_id})
        except:
            pass
    
    if not call:
        raise HTTPException(status_code=404, detail="Call not found")
    
    # Validate outcome
    valid_outcomes = [o["value"] for o in CALL_OUTCOMES]
    if outcome not in valid_outcomes:
        raise HTTPException(status_code=400, detail="Invalid outcome")
    
    update_data = {
        "outcome": outcome,
        "outcome_updated_at": datetime.now(timezone.utc).isoformat(),
        "outcome_updated_by": user.get("email")
    }
    
    if notes:
        update_data["outcome_notes"] = notes
    
    await db.smartflo_calls.update_one({"_id": call["_id"]}, {"$set": update_data})
    
    return {"message": "Outcome updated successfully"}


