class FixEndToEndRequest(BaseModel):
    """Request model for fix end-to-end"""
    order_id: str
    customer_name: Optional[str] = None
    customer_phone: Optional[str] = None
    address: Optional[str] = None
    city: Optional[str] = None
    state: Optional[str] = None
    pincode: Optional[str] = None
    master_sku_id: Optional[str] = None
    tracking_id: Optional[str] = None
    invoice_url: Optional[str] = None
    label_url: Optional[str] = None


@api_router.post("/bot/diagnose-order-comprehensive")
async def bot_diagnose_order_comprehensive(
    order_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Comprehensive order diagnosis - checks ALL data requirements for dispatch.
    Returns detailed report of what's present, missing, and actionable fixes.
    """
    # Search for the order across all collections
    order = None
    source = None
    
    # Check dispatches first (dispatch queue)
    dispatch = await db.dispatches.find_one(
        {"$or": [{"id": order_id}, {"order_id": order_id}, {"tracking_id": order_id}]},
        {"_id": 0}
    )
    if dispatch:
        order = dispatch
        source = "dispatches"
    
    # Check pending_fulfillment
    if not order:
        pf = await db.pending_fulfillment.find_one(
            {"$or": [{"id": order_id}, {"order_id": order_id}, {"amazon_order_id": order_id}]},
            {"_id": 0}
        )
        if pf:
            order = pf
            source = "pending_fulfillment"
    
    # Check amazon_orders
    amazon_order = await db.amazon_orders.find_one(
        {"$or": [{"amazon_order_id": order_id}, {"order_id": order_id}]},
        {"_id": 0}
    )
    if not order and amazon_order:
        order = amazon_order
        source = "amazon_orders"
    
    if not order:
        return {"found": False, "message": f"Order {order_id} not found"}
    
    # Build comprehensive diagnosis
    diagnosis = {
        "found": True,
        "order_id": order.get("order_id") or order.get("amazon_order_id") or order.get("id"),
        "source": source,
        "status": order.get("status", "unknown"),
        "firm_id": order.get("firm_id"),
        "firm_name": order.get("firm_name"),
        "checks": {},
        "issues": [],
        "fixes_needed": [],
        "ready_for_dispatch": True
    }
    
    # 1. CUSTOMER DETAILS CHECK
    customer_check = {
        "name": order.get("customer_name") or order.get("buyer_name"),
        "phone": (order.get("customer_phone") or order.get("phone") or order.get("buyer_phone") or 
                  (amazon_order.get("buyer_phone") if amazon_order else None)),
        "address": order.get("address") or order.get("shipping_address"),
        "city": order.get("city"),
        "state": order.get("state"),
        "pincode": order.get("pincode") or order.get("postal_code"),
        "complete": True,
        "missing": []
    }
    
    if not customer_check["name"]:
        customer_check["missing"].append("customer_name")
        customer_check["complete"] = False
    if not customer_check["phone"]:
        customer_check["missing"].append("phone")
        customer_check["complete"] = False
    if not customer_check["address"]:
        customer_check["missing"].append("address")
        customer_check["complete"] = False
    if not customer_check["city"]:
        customer_check["missing"].append("city")
        customer_check["complete"] = False
    if not customer_check["state"]:
        customer_check["missing"].append("state")
        customer_check["complete"] = False
    if not customer_check["pincode"]:
        customer_check["missing"].append("pincode")
        customer_check["complete"] = False
    
    diagnosis["checks"]["customer"] = customer_check
    if not customer_check["complete"]:
        diagnosis["ready_for_dispatch"] = False
        diagnosis["issues"].append(f"Missing customer details: {', '.join(customer_check['missing'])}")
        diagnosis["fixes_needed"].append({"type": "customer_details", "fields": customer_check["missing"]})
    
    # 2. SKU/PRODUCT CHECK
    sku_check = {
        "master_sku_id": order.get("master_sku_id"),
        "master_sku_name": order.get("master_sku_name"),
        "sku_code": order.get("sku_code"),
        "quantity": order.get("quantity", 1),
        "mapped": bool(order.get("master_sku_id")),
        "complete": bool(order.get("master_sku_id"))
    }
    
    if sku_check["master_sku_id"]:
        master_sku = await db.master_skus.find_one({"id": sku_check["master_sku_id"]}, {"_id": 0})
        if master_sku:
            sku_check["master_sku_details"] = {
                "name": master_sku.get("name"),
                "sku_code": master_sku.get("sku_code"),
                "weight": master_sku.get("weight"),
                "dimensions": master_sku.get("dimensions")
            }
    
    diagnosis["checks"]["sku"] = sku_check
    if not sku_check["mapped"]:
        diagnosis["ready_for_dispatch"] = False
        diagnosis["issues"].append("SKU not mapped to master catalog")
        diagnosis["fixes_needed"].append({"type": "sku_mapping"})
    
    # 3. STOCK CHECK
    stock_check = {"available": 0, "required": order.get("quantity", 1), "in_stock": False}
    
    if sku_check["mapped"] and order.get("firm_id"):
        items_for_stock = order.get("items") or ([{
            "master_sku_id": order.get("master_sku_id"),
            "quantity": order.get("quantity", 1)
        }] if order.get("master_sku_id") else [])
        
        if items_for_stock:
            stock_result = await get_stock_for_resolved_items(items_for_stock, order.get("firm_id", ""), db)
            stock_check["in_stock"] = stock_result.get("all_in_stock", False)
            stock_check["per_item"] = stock_result.get("items", [])
            # Summarise across all items — not just item[0]
            stock_check["available"] = min(
                (i.get("available", 0) for i in stock_check["per_item"]),
                default=0
            )
    
    diagnosis["checks"]["stock"] = stock_check
    if not stock_check["in_stock"] and sku_check["mapped"]:
        diagnosis["ready_for_dispatch"] = False
        per_item = stock_check.get("per_item", [])
        if len(per_item) > 1:
            short_lines = [
                f"  • {i.get('master_sku_name', i.get('master_sku_id', 'Item'))}: "
                f"{i.get('available', 0)} available, {i.get('required', i.get('quantity', 1))} needed"
                for i in per_item if not i.get("in_stock", True)
            ]
            stock_msg = "Insufficient stock for:\n" + "\n".join(short_lines)
        else:
            stock_msg = f"Insufficient stock: {stock_check['available']} available, {stock_check['required']} needed"
        diagnosis["issues"].append(stock_msg)
        diagnosis["fixes_needed"].append({
            "type": "stock",
            "description": "Stock not available - check inventory or production",
            "per_item_detail": stock_check.get("per_item", [])
        })
    
    # 3b. SERIAL AVAILABILITY CHECK for manufactured items
    if sku_check.get("master_sku_id") and order.get("firm_id"):
        master_sku = await db.master_skus.find_one({"id": sku_check["master_sku_id"]}, {"_id": 0})
        is_manufactured = master_sku.get("product_type") == "manufactured" if master_sku else False
        if is_manufactured:
            available_serials = await db.finished_good_serials.count_documents({
                "master_sku_id": sku_check["master_sku_id"],
                "firm_id": order.get("firm_id"),
                "status": "in_stock"
            })
            stock_check["available_serials"] = available_serials
            stock_check["is_manufactured"] = True
            stock_check["serial_stock_ok"] = available_serials >= sku_check.get("quantity", 1)
            if not stock_check["serial_stock_ok"]:
                diagnosis["ready_for_dispatch"] = False
                diagnosis["issues"].append(
                    f"Insufficient serialized units: need {sku_check.get('quantity', 1)}, only {available_serials} serial(s) in stock"
                )
                diagnosis["fixes_needed"].append({
                    "type": "serial_stock",
                    "description": f"Add {sku_check.get('quantity', 1) - available_serials} more serialized unit(s) to finished goods inventory",
                    "available": available_serials,
                    "required": sku_check.get("quantity", 1)
                })
    
    # 4. TRACKING CHECK
    tracking_check = {
        "tracking_id": order.get("tracking_id") or order.get("tracking_number"),
        "has_tracking": bool(order.get("tracking_id") or order.get("tracking_number")),
        "is_easy_ship": order.get("is_easy_ship", False) or order.get("fulfillment_channel") == "AMAZON_IN"
    }
    
    diagnosis["checks"]["tracking"] = tracking_check
    if not tracking_check["has_tracking"] and not tracking_check["is_easy_ship"]:
        diagnosis["issues"].append("No tracking ID assigned")
    
    # 5. DOCUMENTS CHECK
    docs_check = {
        "invoice": bool(order.get("invoice_url") or order.get("invoice_file")),
        "invoice_url": order.get("invoice_url") or order.get("invoice_file"),
        "shipping_label": bool(order.get("label_url") or order.get("shipping_label")),
        "label_url": order.get("label_url") or order.get("shipping_label")
    }
    diagnosis["checks"]["documents"] = docs_check
    
    # Summary
    diagnosis["total_issues"] = len(diagnosis["issues"])
    
    # Check if can auto-fix from Amazon
    diagnosis["can_fix_automatically"] = []
    if amazon_order and not customer_check["complete"]:
        shipping = amazon_order.get("shipping_address", {})
        if shipping:
            diagnosis["can_fix_automatically"].append({
                "type": "customer_from_amazon",
                "data": {
                    "customer_name": amazon_order.get("buyer_name") or shipping.get("name"),
                    "phone": amazon_order.get("buyer_phone") or shipping.get("phone"),
                    "address": shipping.get("address_line1"),
                    "city": shipping.get("city"),
                    "state": shipping.get("state"),
                    "pincode": shipping.get("postal_code")
                }
            })
    
    return diagnosis


@api_router.post("/bot/fix-end-to-end")
async def bot_fix_end_to_end(
    data: FixEndToEndRequest,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Fix all issues with an order end-to-end."""
    now = datetime.now(timezone.utc)
    
    # Find the order
    order = None
    collection = None
    
    dispatch = await db.dispatches.find_one({"$or": [{"id": data.order_id}, {"order_id": data.order_id}]}, {"_id": 0})
    if dispatch:
        order = dispatch
        collection = "dispatches"
    
    if not order:
        pf = await db.pending_fulfillment.find_one(
            {"$or": [{"id": data.order_id}, {"order_id": data.order_id}, {"amazon_order_id": data.order_id}]},
            {"_id": 0}
        )
        if pf:
            order = pf
            collection = "pending_fulfillment"
    
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    # Get amazon order for fallbacks
    amazon_order = await db.amazon_orders.find_one(
        {"$or": [
            {"amazon_order_id": data.order_id},
            {"order_id": data.order_id},
            {"amazon_order_id": order.get("amazon_order_id")},
            {"order_id": order.get("order_id")}
        ]},
        {"_id": 0}
    )
    amazon_shipping = (amazon_order.get("shipping_address") or {}) if amazon_order else {}
    
    update_data = {"updated_at": now.isoformat()}
    fixes_applied = []
    
    # Fix customer details
    if data.customer_name or not order.get("customer_name"):
        name = data.customer_name or (amazon_order.get("buyer_name") if amazon_order else None)
        if name:
            update_data["customer_name"] = name
            fixes_applied.append(f"Name: {name}")
    
    if data.customer_phone or not (order.get("customer_phone") or order.get("phone")):
        phone = data.customer_phone or (amazon_order.get("buyer_phone") if amazon_order else None) or amazon_shipping.get("phone")
        if phone:
            update_data["customer_phone"] = phone
            update_data["phone"] = phone
            fixes_applied.append(f"Phone: {phone}")
    
    if data.address or not order.get("address"):
        address = data.address or amazon_shipping.get("address_line1")
        if address:
            update_data["address"] = address
            fixes_applied.append(f"Address: {address[:50]}...")
    
    if data.city or not order.get("city"):
        city = data.city or amazon_shipping.get("city")
        if city:
            update_data["city"] = city
            fixes_applied.append(f"City: {city}")
    
    if data.state or not order.get("state"):
        state = data.state or amazon_shipping.get("state")
        if state:
            update_data["state"] = state
            fixes_applied.append(f"State: {state}")
    
    if data.pincode or not order.get("pincode"):
        pincode = data.pincode or amazon_shipping.get("postal_code")
        if pincode:
            update_data["pincode"] = pincode
            fixes_applied.append(f"Pincode: {pincode}")
    
    if data.master_sku_id:
        master_sku = await db.master_skus.find_one({"id": data.master_sku_id}, {"_id": 0})
        if master_sku:
            update_data["master_sku_id"] = data.master_sku_id
            update_data["master_sku_name"] = master_sku.get("name")
            update_data["sku_code"] = master_sku.get("sku_code")
            fixes_applied.append(f"SKU: {master_sku.get('name')}")
    
    if data.tracking_id:
        update_data["tracking_id"] = data.tracking_id
        fixes_applied.append(f"Tracking: {data.tracking_id}")
    
    # Apply update
    if collection == "dispatches":
        await db.dispatches.update_one({"id": order.get("id")}, {"$set": update_data})
    else:
        await db.pending_fulfillment.update_one({"id": order.get("id")}, {"$set": update_data})
    
    # Re-run diagnosis
    diagnosis = await bot_diagnose_order_comprehensive(data.order_id, user)
    
    return {
        "success": True,
        "message": f"Fixed {len(fixes_applied)} issues",
        "fixes_applied": fixes_applied,
        "remaining_issues": diagnosis.get("issues", []),
        "ready_for_dispatch": diagnosis.get("ready_for_dispatch", False),
        "diagnosis": diagnosis
    }


@api_router.post("/bot/auto-fix-from-amazon")
async def bot_auto_fix_from_amazon(
    order_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Automatically fix order data by pulling from Amazon order."""
    now = datetime.now(timezone.utc)
    
    order = await db.pending_fulfillment.find_one(
        {"$or": [{"id": order_id}, {"order_id": order_id}, {"amazon_order_id": order_id}]},
        {"_id": 0}
    )
    collection = "pending_fulfillment"
    
    if not order:
        order = await db.dispatches.find_one({"$or": [{"id": order_id}, {"order_id": order_id}]}, {"_id": 0})
        collection = "dispatches"
    
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    amazon_order = await db.amazon_orders.find_one(
        {"$or": [
            {"amazon_order_id": order.get("amazon_order_id") or order_id},
            {"order_id": order.get("order_id") or order_id}
        ]},
        {"_id": 0}
    )
    
    if not amazon_order:
        raise HTTPException(status_code=404, detail="Amazon order not found - cannot auto-fix")
    
    shipping = amazon_order.get("shipping_address") or {}
    update_data = {"updated_at": now.isoformat(), "auto_fixed_at": now.isoformat()}
    fixes = []
    
    if not order.get("customer_name"):
        name = amazon_order.get("buyer_name") or shipping.get("name")
        if name:
            update_data["customer_name"] = name
            fixes.append(f"Name: {name}")
    
    if not (order.get("customer_phone") or order.get("phone")):
        phone = amazon_order.get("buyer_phone") or shipping.get("phone")
        if phone:
            update_data["customer_phone"] = phone
            update_data["phone"] = phone
            fixes.append(f"Phone: {phone}")
    
    if not order.get("address"):
        addr = shipping.get("address_line1")
        if shipping.get("address_line2"):
            addr = f"{addr}, {shipping.get('address_line2')}"
        if addr:
            update_data["address"] = addr
            fixes.append(f"Address: {addr[:40]}...")
    
    if not order.get("city"):
        city = shipping.get("city")
        if city:
            update_data["city"] = city
            fixes.append(f"City: {city}")
    
    if not order.get("state"):
        state = shipping.get("state")
        if state:
            update_data["state"] = state
            fixes.append(f"State: {state}")
    
    if not order.get("pincode"):
        pincode = shipping.get("postal_code")
        if pincode:
            update_data["pincode"] = pincode
            fixes.append(f"Pincode: {pincode}")
    
    if not fixes:
        return {"success": True, "message": "No fixes needed", "fixes_applied": []}
    
    if collection == "dispatches":
        await db.dispatches.update_one({"id": order.get("id")}, {"$set": update_data})
    else:
        await db.pending_fulfillment.update_one({"id": order.get("id")}, {"$set": update_data})
    
    diagnosis = await bot_diagnose_order_comprehensive(order_id, user)
    
    return {
        "success": True,
        "message": f"Auto-fixed {len(fixes)} fields",
        "fixes_applied": fixes,
        "remaining_issues": diagnosis.get("issues", []),
        "ready_for_dispatch": diagnosis.get("ready_for_dispatch", False)
    }


@api_router.get("/bot/dispatch-queue-health")
async def get_dispatch_queue_health(
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get health summary of all orders in dispatch queue."""
    dispatch_items = await db.dispatches.find(
        {"status": {"$in": ["ready_for_dispatch", "ready_to_dispatch", "pending_dispatch"]}},
        {"_id": 0}
    ).to_list(1000)
    
    pf_items = await db.pending_fulfillment.find(
        {"status": {"$in": ["pending_dispatch", "in_dispatch_queue", "approved"]}},
        {"_id": 0}
    ).to_list(1000)
    
    all_items = dispatch_items + pf_items
    
    summary = {
        "total_in_queue": len(all_items),
        "ready_to_dispatch": 0,
        "with_issues": 0,
        "issues_breakdown": {
            "missing_phone": 0,
            "missing_address": 0,
            "missing_sku": 0,
            "missing_tracking": 0
        },
        "orders_needing_fix": []
    }
    
    for item in all_items:
        has_issue = False
        order_issues = []
        
        if not (item.get("customer_phone") or item.get("phone") or item.get("buyer_phone")):
            summary["issues_breakdown"]["missing_phone"] += 1
            has_issue = True
            order_issues.append("phone")
        
        if not item.get("address"):
            summary["issues_breakdown"]["missing_address"] += 1
            has_issue = True
            order_issues.append("address")
        
        if not item.get("master_sku_id"):
            summary["issues_breakdown"]["missing_sku"] += 1
            has_issue = True
            order_issues.append("sku")
        
        if not item.get("is_easy_ship") and not item.get("tracking_id"):
            summary["issues_breakdown"]["missing_tracking"] += 1
            has_issue = True
            order_issues.append("tracking")
        
        if has_issue:
            summary["with_issues"] += 1
            summary["orders_needing_fix"].append({
                "order_id": item.get("order_id") or item.get("amazon_order_id") or item.get("id"),
                "customer": item.get("customer_name") or item.get("buyer_name") or "Unknown",
                "issues": order_issues,
                "has_amazon_data": bool(item.get("amazon_order_id"))
            })
        else:
            summary["ready_to_dispatch"] += 1
    
    summary["orders_needing_fix"] = summary["orders_needing_fix"][:50]
    return summary


class MoveToPendingFulfillmentRequest(BaseModel):
    amazon_order_id: str
    customer_name: Optional[str] = None
    customer_phone: str
    address: str
    city: str
    state: str
    pincode: str


@api_router.post("/bot/move-to-pending-fulfillment")
async def bot_move_to_pending_fulfillment(
    data: MoveToPendingFulfillmentRequest,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Move an Amazon order to Pending Fulfillment queue after collecting all details.
    Uses shared SKU resolver for consistent multi-item mapping.
    If already imported (pending_fulfillment exists), update the customer details instead."""
    
    now = datetime.now(timezone.utc)
    
    # Load amazon_order early for fallback data
    amazon_order = await db.amazon_orders.find_one(
        {"$or": [{"amazon_order_id": data.amazon_order_id}, {"order_id": data.amazon_order_id}]},
        {"_id": 0}
    ) or {}
    amazon_shipping = amazon_order.get("shipping_address") or {}
    
    # First check if already in pending_fulfillment (already imported via import-amazon-to-crm)
    existing_pf = await db.pending_fulfillment.find_one({
        "$or": [
            {"amazon_order_id": data.amazon_order_id},
            {"order_id": data.amazon_order_id},
            {"id": data.amazon_order_id}  # Also check by pending_fulfillment id
        ]
    })
    
    if existing_pf:
        # Just update the customer details in existing pending_fulfillment
        update_data = {
            "customer_name": data.customer_name or existing_pf.get("customer_name") or amazon_order.get("buyer_name") or amazon_shipping.get("name"),
            "customer_phone": data.customer_phone or existing_pf.get("customer_phone") or amazon_order.get("buyer_phone") or amazon_shipping.get("phone"),
            "phone": data.customer_phone or existing_pf.get("phone") or amazon_order.get("buyer_phone") or amazon_shipping.get("phone"),
            "address": data.address or existing_pf.get("address") or amazon_shipping.get("address_line1") or f"{amazon_order.get('address_line1','')} {amazon_order.get('address_line2','')}".strip(),
            "city": data.city or existing_pf.get("city") or amazon_shipping.get("city") or amazon_order.get("city"),
            "state": data.state or existing_pf.get("state") or amazon_shipping.get("state") or amazon_order.get("state"),
            "pincode": data.pincode or existing_pf.get("pincode") or amazon_shipping.get("postal_code") or amazon_order.get("postal_code"),
            "updated_at": now.isoformat()
        }
        
        # Copy tracking_id and files from temp entry if they exist
        temp_order = await db.pending_fulfillment.find_one({"order_id": data.amazon_order_id})
        if temp_order and temp_order.get("id") != existing_pf.get("id"):
            if temp_order.get("invoice_url"):
                update_data["invoice_url"] = temp_order.get("invoice_url")
            if temp_order.get("label_url"):
                update_data["label_url"] = temp_order.get("label_url")
            if temp_order.get("tracking_id"):
                update_data["tracking_id"] = temp_order.get("tracking_id")
        
        await db.pending_fulfillment.update_one(
            {"id": existing_pf.get("id")},
            {"$set": update_data}
        )
        
        # Get stock info using shared function
        firm_id = existing_pf.get("firm_id")
        items = existing_pf.get("items", [])
        if items and firm_id:
            stock_result = await get_stock_for_resolved_items(items, firm_id, db)
        else:
            master_sku_id = existing_pf.get("master_sku_id")
            stock_info = await get_stock_info_for_pending_fulfillment(master_sku_id, existing_pf)
            stock_result = {"items": [stock_info], "all_in_stock": stock_info.get("in_stock", False)}
        
        return {
            "message": "Customer details updated",
            "pending_fulfillment_id": existing_pf.get("id"),
            "order_id": existing_pf.get("order_id") or data.amazon_order_id,
            "stock_info": stock_result
        }
    
    # Find the Amazon order (for new imports) - we already have it loaded
    if not amazon_order:
        raise HTTPException(status_code=404, detail="Amazon order not found")
    
    pf_id = str(uuid.uuid4())
    
    # Get customer name from multiple sources
    customer_name = (
        data.customer_name or 
        amazon_order.get("buyer_name") or 
        amazon_order.get("customer_name") or
        amazon_order.get("shipping_address", {}).get("name") or
        amazon_order.get("recipient_name") or
        "Unknown Customer"
    )
    
    # BUG FIX: Use firm from Amazon order, not just first active firm
    firm_id = amazon_order.get("firm_id")
    firm = None
    if firm_id:
        firm = await db.firms.find_one({"id": firm_id, "is_active": True}, {"_id": 0})
    
    # Fallback to default firm only if Amazon order has no firm
    if not firm:
        firm = await db.firms.find_one({"is_active": True}, {"_id": 0})
        firm_id = firm.get("id") if firm else None
    
    # ============ USE SHARED SKU RESOLVER ============
    resolution = await resolve_amazon_order_items_to_master_skus(amazon_order, firm_id, db, auto_persist_mapping=True)
    resolved_items = resolution["items"]
    total_quantity = resolution["total_quantity"]
    
    # Get primary SKU info from first resolved item
    primary_item = resolved_items[0] if resolved_items else {}
    master_sku_id = primary_item.get("master_sku_id")
    product_name = primary_item.get("master_sku_name") or primary_item.get("title")
    sku_code = primary_item.get("master_sku_code") or primary_item.get("amazon_sku")
    
    # Check stock for all items
    stock_result = await get_stock_for_resolved_items(resolved_items, firm_id, db) if resolved_items else {"all_in_stock": False, "items": []}
    in_stock = stock_result.get("all_in_stock", False)
    
    # Determine status based on stock
    status = "ready_to_dispatch" if in_stock else "awaiting_stock"
    
    # Check if any item is manufactured
    is_manufactured = False
    for item in resolved_items:
        if item.get("master_sku_id"):
            master_sku = await db.master_skus.find_one({"id": item["master_sku_id"]}, {"_id": 0})
            if master_sku and (master_sku.get("is_manufactured", False) or master_sku.get("product_type") == "manufactured"):
                is_manufactured = True
                break
    
    # Create or update pending_fulfillment entry
    pf_data = {
        "id": pf_id,
        "type": "amazon_order",
        "order_id": data.amazon_order_id,
        "amazon_order_id": data.amazon_order_id,
        "order_source": "amazon",
        "customer_name": customer_name,
        "customer_phone": data.customer_phone or amazon_order.get("buyer_phone") or amazon_shipping.get("phone"),
        "phone": data.customer_phone or amazon_order.get("buyer_phone") or amazon_shipping.get("phone"),
        "address": data.address or amazon_shipping.get("address_line1") or f"{amazon_order.get('address_line1','')} {amazon_order.get('address_line2','')}".strip(),
        "city": data.city or amazon_shipping.get("city") or amazon_order.get("city"),
        "state": data.state or amazon_shipping.get("state") or amazon_order.get("state"),
        "pincode": data.pincode or amazon_shipping.get("postal_code") or amazon_order.get("postal_code"),
        "master_sku_id": master_sku_id,  # Primary SKU for backward compat
        "master_sku_name": product_name,
        "sku_code": sku_code,
        "quantity": total_quantity,  # Sum of all item quantities
        "items": resolved_items,  # Full items array with master_sku_id on each
        "all_items_mapped": resolution["all_mapped"],
        "unmapped_skus": resolution["unmapped_skus"],
        "order_total": amazon_order.get("order_total"),
        "tracking_id": amazon_order.get("tracking_id") or amazon_order.get("tracking_number"),
        "firm_id": firm_id,
        "firm_name": firm.get("name") if firm else None,
        "is_manufactured_item": is_manufactured,
        "fulfillment_channel": amazon_order.get("fulfillment_channel"),
        "is_easy_ship": amazon_order.get("is_easy_ship", False),
        "status": status,
        "created_by": user["id"],
        "created_by_name": f"{user['first_name']} {user['last_name']}",
        "created_at": now.isoformat(),
        "updated_at": now.isoformat()
    }
    
    # Copy uploaded files and tracking if they exist in temporary location
    temp_order = await db.pending_fulfillment.find_one({"order_id": data.amazon_order_id})
    if temp_order:
        pf_data["invoice_url"] = temp_order.get("invoice_url")
        pf_data["label_url"] = temp_order.get("label_url")
        # CRITICAL: Also copy tracking_id that was entered earlier
        if temp_order.get("tracking_id"):
            pf_data["tracking_id"] = temp_order.get("tracking_id")
    
    if existing_pf:
        await db.pending_fulfillment.update_one(
            {"id": pf_id},
            {"$set": pf_data}
        )
    else:
        await db.pending_fulfillment.insert_one(pf_data)
    
    # Update amazon_orders with crm_status and resolved items
    await db.amazon_orders.update_one(
        {"amazon_order_id": data.amazon_order_id},
        {"$set": {
            "crm_status": "pending",
            "items": resolved_items,
            "all_skus_mapped": resolution["all_mapped"],
            "updated_at": now.isoformat()
        }}
    )
    
    return {
        "message": "Order moved to Pending Fulfillment",
        "order_id": data.amazon_order_id,
        "pending_fulfillment_id": pf_id,
        "status": status,
        "all_items_mapped": resolution["all_mapped"],
        "unmapped_skus": resolution["unmapped_skus"],
        "stock_info": stock_result
    }


@api_router.post("/bot/dispatch")
async def bot_dispatch_order(
    order_id: str = Form(...),
    serial_numbers: Optional[str] = Form(None),
    tracking_id: Optional[str] = Form(None),
    payment_status: Optional[str] = Form(None),
    invoice_number: Optional[str] = Form(None),
    invoice_value: Optional[float] = Form(None),
    eway_bill_number: Optional[str] = Form(None),
    courier: Optional[str] = Form(None),
    bigship_order_id: Optional[str] = Form(None),
    confirmed: bool = Form(False),
    notes: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Prepare an order for dispatch via bot - with compliance validation.
    NOTE: Accountant prepares the order, DISPATCHER marks it as dispatched.
    This creates a dispatch entry with status 'ready_for_dispatch'.
    """
    
    # Search by multiple fields: id, order_id, or amazon_order_id
    entry = await db.pending_fulfillment.find_one(
        {"$or": [
            {"id": order_id},
            {"order_id": order_id},
            {"amazon_order_id": order_id}
        ]}
    )
    if not entry:
        raise HTTPException(status_code=404, detail="Order not found")
    
    if entry.get("status") == "dispatched":
        raise HTTPException(status_code=400, detail="Order already dispatched")
    
    if entry.get("status") == "cancelled":
        raise HTTPException(status_code=400, detail="Cannot dispatch cancelled order")
    
    # CRITICAL: Check if dispatch entry already exists to prevent duplicates
    existing_dispatch = await db.dispatches.find_one({
        "$or": [
            {"pending_fulfillment_id": entry.get("id")},
            {"pending_fulfillment_id": order_id},
            {"order_id": entry.get("order_id")},
            {"marketplace_order_id": entry.get("amazon_order_id")}
        ],
        "status": {"$ne": "cancelled"}  # Allow re-dispatch if previous was cancelled
    }, {"_id": 0, "dispatch_number": 1, "status": 1})
    
    if existing_dispatch:
        raise HTTPException(
            status_code=409,  # Conflict
            detail=f"Dispatch already exists (#{existing_dispatch.get('dispatch_number')}). Status: {existing_dispatch.get('status')}"
        )
    
    # Determine if EasyShip/FBA (relaxed validation)
    order_source = entry.get("order_source") or entry.get("source") or ""
    is_easyship = order_source.lower() in ["easyship", "easy_ship", "amazon_easy_ship"]
    fulfillment_channel = (entry.get("fulfillment_channel") or "").upper()
    is_amazon_fba = fulfillment_channel == "AFN"
    is_offline_order = order_source.lower() == "offline" or entry.get("type") == "offline_order"
    
    # COMPLIANCE CHECKS
    errors = []
    
    # 1. Tracking ID - required for Amazon MFN, optional for offline/easyship/FBA
    final_tracking = tracking_id or entry.get("tracking_id")
    if not final_tracking and not is_offline_order and not is_easyship and not is_amazon_fba:
        errors.append("Tracking ID is required")
    elif final_tracking:
        # Check for duplicate tracking ID
        tracking_dup = await check_tracking_id_duplicate(final_tracking, entry.get("id"))
        if tracking_dup["exists"]:
            errors.append(tracking_dup["message"])
    
    # 2. Invoice - required for Amazon MFN, NOT required for offline orders (invoice is external)
    if not is_offline_order and not is_easyship and not is_amazon_fba:
        if not entry.get("invoice_url"):
            errors.append("Invoice must be uploaded")
    
    # 3. Shipping label - required for Amazon MFN, NOT required for offline/Bigship orders
    # If bigship_order_id is provided, label can be downloaded from Bigship
    has_bigship_label = bigship_order_id is not None
    if not is_offline_order and not is_easyship and not is_amazon_fba and not has_bigship_label:
        if not entry.get("label_url"):
            errors.append("Shipping label must be uploaded (or generate via Bigship)")
    
    # 4. Invoice number duplicate check (if provided)
    final_invoice_number = invoice_number or entry.get("external_invoice_number") or entry.get("invoice_number")
    if final_invoice_number:
        invoice_dup = await check_invoice_number_duplicate(final_invoice_number, entry.get("id"))
        if invoice_dup["exists"]:
            errors.append(invoice_dup["message"])
    
    # 5. E-Way Bill required if invoice > 50,000
    order_total = invoice_value or entry.get("order_total") or entry.get("grand_total") or entry.get("amount") or 0
    if order_total > 50000:
        final_eway = eway_bill_number or entry.get("eway_bill_number")
        if not final_eway:
            errors.append(f"E-Way Bill Number is required for invoice value ₹{order_total:,.2f} (exceeds ₹50,000)")
        # E-way bill copy only required for non-offline orders
        if not is_offline_order and not entry.get("eway_bill_url"):
            errors.append("E-Way Bill copy must be uploaded for invoice > ₹50,000")
    
    # 6. Must be confirmed
    if not confirmed:
        errors.append("Dispatch must be confirmed by accountant")
    
    # 7. Amazon orders must have SKU mapping (Fix #5: enforce mapping before dispatch)
    items = entry.get("items") or []
    if entry.get("type") == "amazon_order":
        unmapped_items = []
        
        # Check main entry SKU
        if not entry.get("master_sku_id"):
            unmapped_items.append(entry.get("product_name") or entry.get("asin") or entry.get("sku") or "Main item")
        
        # Check each item in items array
        for idx, item in enumerate(items):
            if not item.get("master_sku_id"):
                item_name = item.get("product_name") or item.get("asin") or item.get("seller_sku") or f"Item {idx + 1}"
                unmapped_items.append(item_name)
        
        if unmapped_items:
            errors.append(f"SKU mapping required before dispatch. Unmapped items: {', '.join(unmapped_items[:3])}{'...' if len(unmapped_items) > 3 else ''}")
    
    if errors:
        # Bug 5 Fix: Add helpful context to error messages
        order_type = "Amazon MFN" if not is_easyship and not is_amazon_fba and not is_offline_order else (
            "EasyShip" if is_easyship else ("Amazon FBA" if is_amazon_fba else "Offline Order")
        )
        error_context = {
            "errors": errors, 
            "message": f"Compliance checks failed for {order_type} order",
            "order_type": order_type,
            "order_id": entry.get("order_id"),
            "help": {
                "tracking_required": not is_offline_order and not is_easyship and not is_amazon_fba,
                "invoice_required": not is_offline_order and not is_easyship and not is_amazon_fba,
                "label_required": not is_offline_order and not is_easyship and not is_amazon_fba,
                "eway_bill_threshold": 50000
            }
        }
        raise HTTPException(status_code=400, detail=error_context)
    
    # Update tracking_id and other fields in pending_fulfillment
    update_data = {"updated_at": datetime.now(timezone.utc).isoformat()}
    if tracking_id:
        update_data["tracking_id"] = tracking_id
    if payment_status:
        update_data["payment_status"] = payment_status
    if invoice_number:
        update_data["invoice_number"] = invoice_number
    if invoice_value:
        update_data["order_total"] = invoice_value
        update_data["amount"] = invoice_value
    if eway_bill_number:
        update_data["eway_bill_number"] = eway_bill_number
    if serial_numbers:
        update_data["serial_number"] = serial_numbers
    if courier:
        update_data["courier"] = courier
        update_data["courier_name"] = courier
    if bigship_order_id:
        update_data["bigship_order_id"] = bigship_order_id
    
    # Mark as ready_to_dispatch in pending_fulfillment
    update_data["status"] = "ready_to_dispatch"
    update_data["prepared_by"] = user["id"]
    update_data["prepared_by_name"] = f"{user['first_name']} {user['last_name']}"
    update_data["prepared_at"] = datetime.now(timezone.utc).isoformat()
    
    # Use the entry's actual id field, not the search parameter
    entry_id = entry.get("id")
    await db.pending_fulfillment.update_one({"id": entry_id}, {"$set": update_data})
    
    # Create dispatch entry with status 'ready_for_dispatch' for dispatcher
    now = datetime.now(timezone.utc)
    dispatch_id = str(uuid.uuid4())
    
    # Generate dispatch number
    today_str = now.strftime("%Y%m%d")
    count = await db.dispatches.count_documents({"created_at": {"$regex": f"^{now.strftime('%Y-%m-%d')}"}})
    dispatch_number = f"DSP-{today_str}-{count + 1:04d}"
    
    # Get firm info
    firm = None
    if entry.get("firm_id"):
        firm = await db.firms.find_one({"id": entry["firm_id"]}, {"_id": 0})
    
    # Get master SKU info
    master_sku = None
    if entry.get("master_sku_id"):
        master_sku = await db.master_skus.find_one({"id": entry["master_sku_id"]}, {"_id": 0})
    
    # Determine dispatch type and order source based on entry type
    dispatch_type = "amazon_order" if entry.get("type") == "amazon_order" else "new_order"
    final_order_source = entry.get("order_source", "amazon" if entry.get("type") == "amazon_order" else "direct")
    
    # CRITICAL: Amazon orders have GST-inclusive pricing
    # We need to reverse-calculate taxable value for proper invoicing
    is_amazon_order = final_order_source.lower() in ["amazon", "flipkart", "marketplace"]
    gst_rate = master_sku.get("gst_rate", 18) if master_sku else 18
    
    # invoice_value is the total (GST inclusive for marketplace orders)
    final_invoice_value = order_total
    
    if is_amazon_order and final_invoice_value > 0:
        # Amazon price is GST-inclusive, calculate taxable value
        taxable_value = round(final_invoice_value / (1 + gst_rate / 100), 2)
        gst_amount = round(final_invoice_value - taxable_value, 2)
    else:
        # Direct orders - taxable value equals order total (GST added separately)
        taxable_value = final_invoice_value
        gst_amount = round(taxable_value * (gst_rate / 100), 2)
    
    # FIX: Extract serial numbers from items array for offline orders
    all_serial_numbers = []
    item_serials_list = []
    items = entry.get("items") or []
    
    for item in items:
        item_serials = item.get("serial_numbers") or []
        if item_serials:
            all_serial_numbers.extend(item_serials)
            item_serials_list.append({
                "master_sku_id": item.get("master_sku_id"),
                "product_name": item.get("product_name"),
                "serial_numbers": item_serials
            })
    
    # Use serials from items if no direct serial_numbers provided
    final_serial_numbers = serial_numbers or entry.get("serial_number") or (all_serial_numbers[0] if len(all_serial_numbers) == 1 else None)
    
    dispatch_doc = {
        "id": dispatch_id,
        "dispatch_number": dispatch_number,
        "dispatch_type": "offline_order" if is_offline_order else ("amazon_order" if entry.get("type") == "amazon_order" else "new_order"),
        "order_source": final_order_source,
        "is_easyship": is_easyship,
        "is_amazon_fba": is_amazon_fba,
        "is_offline_order": is_offline_order,
        "is_marketplace_order": is_amazon_order,
        "price_is_gst_inclusive": is_amazon_order,  # Flag for invoice generation
        "firm_id": entry.get("firm_id"),
        "firm_name": firm.get("name") if firm else None,
        "master_sku_id": entry.get("master_sku_id"),
        "master_sku_name": entry.get("master_sku_name") or (master_sku.get("name") if master_sku else None),
        "sku": entry.get("sku_code") or (master_sku.get("sku_code") if master_sku else None),
        "sku_code": entry.get("sku_code") or (master_sku.get("sku_code") if master_sku else None),
        "gst_rate": gst_rate,
        "quantity": entry.get("quantity", 1),
        "serial_number": final_serial_numbers,
        # Multi-item serial tracking for offline orders
        "item_serials": item_serials_list if item_serials_list else None,
        "all_serial_numbers": all_serial_numbers if all_serial_numbers else None,
        # Items array for multi-item offline orders
        "items": items if items else None,
        "order_id": entry.get("order_id"),
        "external_invoice_number": entry.get("external_invoice_number") or entry.get("invoice_number"),
        "marketplace_order_id": entry.get("amazon_order_id") or entry.get("order_id"),
        "customer_name": entry.get("customer_name"),
        "customer_id": entry.get("customer_id"),
        "customer_gst": entry.get("customer_gst"),
        "phone": entry.get("customer_phone") or entry.get("phone"),
        "address": entry.get("address"),
        "city": entry.get("city"),
        "state": entry.get("state"),
        "pincode": entry.get("pincode"),
        "delivery_method": entry.get("delivery_method"),
        "payment_status": entry.get("payment_status"),
        "amount_paid": entry.get("amount_paid"),
        "balance_due": entry.get("balance_due"),
        "tracking_id": final_tracking,
        "courier": courier or entry.get("carrier_name") or entry.get("carrier_code") or entry.get("courier"),
        "bigship_order_id": bigship_order_id or entry.get("bigship_order_id"),
        # Copy uploaded documents from pending_fulfillment
        "invoice_url": entry.get("invoice_url"),
        "invoice_number": final_invoice_number or entry.get("invoice_number"),
        "label_url": entry.get("label_url"),
        "label_file": entry.get("label_url"),  # For dispatcher compatibility
        "eway_bill_number": eway_bill_number or entry.get("eway_bill_number"),
        "eway_bill_url": entry.get("eway_bill_url"),
        # PRICING - properly separated for GST calculation
        "invoice_value": final_invoice_value,  # Total (GST inclusive for marketplace)
        "taxable_value": taxable_value,  # Amount before GST
        "gst_amount": gst_amount,  # GST portion
        "subtotal": entry.get("subtotal"),
        "total_gst": entry.get("total_gst"),
        "grand_total": entry.get("grand_total") or entry.get("order_total"),
        "pending_fulfillment_id": entry.get("id"),  # Link to pending fulfillment entry (use PF ID, not input order_id)
        "status": "ready_for_dispatch",  # Dispatcher will mark as 'dispatched'
        "notes": notes,
        "prepared_by": user["id"],
        "prepared_by_name": f"{user['first_name']} {user['last_name']}",
        "created_by": user["id"],
        "created_by_name": f"{user['first_name']} {user['last_name']}",
        "created_at": now.isoformat()
    }
    
    await db.dispatches.insert_one(dispatch_doc)
    
    # Update pending_fulfillment status to 'in_dispatch_queue'
    await db.pending_fulfillment.update_one(
        {"id": entry.get("id")},
        {"$set": {
            "status": "in_dispatch_queue",
            "dispatch_id": dispatch_id,
            "dispatch_number": dispatch_number,
            "updated_at": now.isoformat()
        }}
    )
    
    # Update amazon_orders status if this is an Amazon order
    if entry.get("type") == "amazon_order" and entry.get("amazon_order_id"):
        await db.amazon_orders.update_one(
            {"amazon_order_id": entry.get("amazon_order_id")},
            {"$set": {
                "crm_status": "ready_for_dispatch",
                "dispatch_id": dispatch_id,
                "dispatch_number": dispatch_number,
                "updated_at": now.isoformat()
            }}
        )
    
    # Create audit log
    await db.audit_logs.insert_one({
        "id": str(uuid.uuid4()),
        "action": "order_prepared_for_dispatch",
        "entity_type": "pending_fulfillment",
        "entity_id": order_id,
        "entity_name": entry.get("order_id"),
        "performed_by": user["id"],
        "performed_by_name": f"{user['first_name']} {user['last_name']}",
        "details": {
            "dispatch_id": dispatch_id, 
            "dispatch_number": dispatch_number,
            "tracking_id": final_tracking, 
            "serial_number": serial_numbers,
            "note": "Prepared by accountant via Operations Bot"
        },
        "timestamp": now.isoformat()
    })
    
    return {
        "message": "Order prepared for dispatch! Dispatcher will complete the physical dispatch.",
        "dispatch_id": dispatch_id, 
        "dispatch_number": dispatch_number,
        "status": "ready_for_dispatch",
        "next_step": "Order is now in Dispatcher Queue. Dispatcher will print labels and mark as dispatched."
    }


@api_router.get("/bot/prepare-dispatch/{order_id}")
async def bot_prepare_dispatch(
    order_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get all details needed for dispatch confirmation - comprehensive compliance check"""
    
    # Search by multiple fields: id, order_id, or amazon_order_id
    entry = await db.pending_fulfillment.find_one(
        {"$or": [
            {"id": order_id},
            {"order_id": order_id},
            {"amazon_order_id": order_id}
        ]},
        {"_id": 0}
    )
    
    # If not found in pending_fulfillment, check if it exists in amazon_orders and try to find linked pf
    if not entry:
        amazon_order = await db.amazon_orders.find_one(
            {"$or": [
                {"amazon_order_id": order_id},
                {"order_id": order_id}
            ]},
            {"_id": 0}
        )
        if amazon_order:
            # Try to find pending_fulfillment linked to this amazon order
            entry = await db.pending_fulfillment.find_one(
                {"$or": [
                    {"amazon_order_id": amazon_order.get("amazon_order_id")},
                    {"order_id": amazon_order.get("amazon_order_id")},
                    {"marketplace_order_id": amazon_order.get("amazon_order_id")}
                ]},
                {"_id": 0}
            )
            
            # If still no entry found but amazon order exists, return helpful error
            if not entry:
                raise HTTPException(
                    status_code=400, 
                    detail=f"Order {order_id} found in Amazon Orders but not yet imported to dispatch queue. Please 'Process in CRM' first."
                )
    
    if not entry:
        raise HTTPException(status_code=404, detail="Order not found")
    
    # Guard: don't allow re-dispatching completed orders
    _status = (entry.get("status") or "").lower()
    if _status in ("dispatched", "delivered", "cancelled", "in_dispatch_queue"):
        dispatch_info = await db.dispatches.find_one(
            {"pending_fulfillment_id": entry.get("id")},
            {"_id": 0, "dispatch_number": 1, "tracking_id": 1, "status": 1, "created_at": 1}
        )
        detail_msg = f"Order {order_id} is already {_status}."
        if dispatch_info and dispatch_info.get("dispatch_number"):
            detail_msg += f" Dispatch #{dispatch_info['dispatch_number']} (tracking {dispatch_info.get('tracking_id','-')})."
        raise HTTPException(status_code=400, detail=detail_msg)
    
    # Determine order type - EasyShip orders don't need phone/address
    order_source = entry.get("order_source") or entry.get("source") or ""
    is_easyship = order_source.lower() in ["easyship", "easy_ship", "amazon_easy_ship"]
    fulfillment_channel = (entry.get("fulfillment_channel") or "").upper()
    is_amazon_fba = fulfillment_channel == "AFN"
    
    # Get product/SKU details
    master_sku = None
    if entry.get("master_sku_id"):
        master_sku = await db.master_skus.find_one({"id": entry["master_sku_id"]}, {"_id": 0})
    
    # If no master_sku yet, try to find via SKU mapping from Amazon order
    if not master_sku and (entry.get("amazon_order_id") or entry.get("marketplace_order_id")):
        amazon_order_id = entry.get("amazon_order_id") or entry.get("marketplace_order_id")
        temp_amazon = await db.amazon_orders.find_one(
            {"$or": [{"amazon_order_id": amazon_order_id}, {"order_id": amazon_order_id}]},
            {"_id": 0, "sku": 1, "firm_id": 1}
        )
        if temp_amazon and temp_amazon.get("sku"):
            # Look up SKU mapping
            sku_mapping = await db.sku_mappings.find_one({
                "amazon_sku": temp_amazon["sku"],
                "$or": [{"firm_id": temp_amazon.get("firm_id")}, {"firm_id": {"$exists": False}}]
            })
            if sku_mapping and sku_mapping.get("master_sku_id"):
                master_sku = await db.master_skus.find_one({"id": sku_mapping["master_sku_id"]}, {"_id": 0})
                # Also try by ObjectId
                if not master_sku:
                    from bson import ObjectId
                    try:
                        master_sku = await db.master_skus.find_one({"_id": ObjectId(sku_mapping["master_sku_id"])}, {"_id": 0})
                    except:
                        pass
    
    # Get pricing from Amazon order if available
    amazon_price = None
    amazon_order = None
    if entry.get("amazon_order_id") or entry.get("marketplace_order_id"):
        amazon_order_id = entry.get("amazon_order_id") or entry.get("marketplace_order_id")
        amazon_order = await db.amazon_orders.find_one(
            {"$or": [{"amazon_order_id": amazon_order_id}, {"order_id": amazon_order_id}]},
            {"_id": 0}
        )
        if amazon_order:
            amazon_price = amazon_order.get("order_total") or amazon_order.get("item_price")
            # Also check EasyShip from Amazon order
            if amazon_order.get("is_easy_ship") or amazon_order.get("fulfillment_channel") == "EasyShip":
                is_easyship = True
    
    # Get available serial numbers for this SKU (include reserved for THIS order)
    available_serials = []
    if entry.get("master_sku_id") and entry.get("firm_id"):
        available_serials = await db.finished_good_serials.find(
            {
                "master_sku_id": entry["master_sku_id"],
                "firm_id": entry["firm_id"],
                "$or": [
                    {"status": "in_stock"},
                    {"status": "reserved", "reserved_by_order_id": entry.get("id")}
                ]
            },
            {"_id": 0, "id": 1, "serial_number": 1, "manufacturing_date": 1, "batch_number": 1, "status": 1}
        ).sort("manufacturing_date", 1).to_list(50)
    
    # Check if this is a manufactured item (has serials) or regular SKU
    # Check both product_type and is_manufactured flags for consistency
    is_manufactured = (
        master_sku.get("product_type") == "manufactured" or 
        master_sku.get("is_manufactured", False)
    ) if master_sku else False
    
    # Get regular SKU stock for non-manufactured items using shared helper
    sku_stock = None
    stock_items_result = None
    
    # First try the shared stock resolver for multi-item support
    if entry.get("firm_id"):
        items_for_stock = entry.get("items") or ([{
            "master_sku_id": entry.get("master_sku_id"),
            "quantity": entry.get("quantity", 1)
        }] if entry.get("master_sku_id") else [])
        if items_for_stock:
            stock_items_result = await get_stock_for_resolved_items(items_for_stock, entry["firm_id"], db)
    
    # Also get sku_stock for backward compatibility
    if master_sku and not is_manufactured and entry.get("firm_id"):
        # Try by master_sku_id first (more reliable)
        sku_stock = await db.skus.find_one(
            {"master_sku_id": entry.get("master_sku_id"), "firm_id": entry["firm_id"]},
            {"_id": 0, "stock_quantity": 1}
        )
        # Fallback to sku_code if no match
        if not sku_stock:
            sku_stock = await db.skus.find_one(
                {
                    "sku_code": master_sku.get("sku_code"),
                    "firm_id": entry["firm_id"],
                    "active": True
                },
                {"_id": 0, "stock_quantity": 1}
            )
    
    # Calculate GST (assuming 18% default, can be fetched from product)
    gst_rate = master_sku.get("gst_rate", 18) if master_sku else 18
    total_with_gst = amazon_price or entry.get("order_total") or entry.get("amount") or 0
    quantity = entry.get("quantity", 1)
    
    # Determine if price is GST-inclusive (marketplace orders)
    is_marketplace = order_source.lower() in ["amazon", "flipkart", "marketplace"]
    
    # Calculate prices
    if total_with_gst > 0:
        if is_marketplace:
            # Amazon/Flipkart: Price is GST-inclusive
            price_without_gst = round(total_with_gst / (1 + gst_rate/100), 2)
            gst_amount = round(total_with_gst - price_without_gst, 2)
            total_value = total_with_gst  # Already includes GST
        else:
            # Direct order: Price is taxable, GST added separately
            price_without_gst = total_with_gst
            gst_amount = round(total_with_gst * (gst_rate/100), 2)
            total_value = total_with_gst + gst_amount
    else:
        price_without_gst = 0
        gst_amount = 0
        total_value = 0
    
    # Check compliance requirements
    compliance = {
        "tracking_id_required": True,
        "tracking_id_provided": bool(entry.get("tracking_id")),
        "invoice_required": True,
        "invoice_uploaded": bool(entry.get("invoice_url")),
        "label_required": True,
        "label_uploaded": bool(entry.get("label_url")),
        "eway_bill_required": total_value > 50000,
        "eway_bill_provided": bool(entry.get("eway_bill_number")),
        "eway_bill_uploaded": bool(entry.get("eway_bill_url")),
        "serial_required": entry.get("is_manufactured", False) or bool(available_serials),
        "serial_provided": bool(entry.get("serial_number"))
    }
    
    # Determine what's missing
    missing = []
    if not compliance["tracking_id_provided"]:
        missing.append("tracking_id")
    if not compliance["invoice_uploaded"]:
        missing.append("invoice")
    if not compliance["label_uploaded"]:
        missing.append("shipping_label")
    if compliance["eway_bill_required"] and not compliance["eway_bill_provided"]:
        missing.append("eway_bill_number")
    if compliance["eway_bill_required"] and not compliance["eway_bill_uploaded"]:
        missing.append("eway_bill_copy")
    if compliance["serial_required"] and not compliance["serial_provided"]:
        missing.append("serial_number")
    
    # Customer details — required for all non-FBA/non-EasyShip orders
    if not is_amazon_fba and not is_easyship:
        if not entry.get("customer_first_name") and not entry.get("customer_name"):
            missing.append("customer_name")
        if not (entry.get("customer_phone") or entry.get("phone")):
            missing.append("customer_phone")
        addr = (entry.get("address") or entry.get("address_line1") or "").strip()
        if not addr:
            missing.append("address")
        elif len(addr) > 50:
            missing.append("address_too_long")
        if not entry.get("state"):
            missing.append("state")
        if not (entry.get("pincode") or entry.get("postal_code")):
            missing.append("pincode")
    
    return {
        "order": {
            "id": entry.get("id"),
            "order_id": entry.get("order_id"),
            "status": entry.get("status"),
            "payment_status": entry.get("payment_status", "unpaid"),
            "order_source": order_source,
            "is_easyship": is_easyship,
            "is_amazon_fba": is_amazon_fba
        },
        "customer": {
            "name": entry.get("customer_name"),
            "first_name": entry.get("customer_first_name"),
            "last_name": entry.get("customer_last_name"),
            "phone": entry.get("customer_phone") or entry.get("phone") or ("(Not required for EasyShip)" if is_easyship else None),
            "address": entry.get("address") or entry.get("address_line1") or ("(Handled by Amazon)" if is_easyship else None),
            "city": entry.get("city"),
            "state": entry.get("state"),
            "pincode": entry.get("pincode")
        },
        "product": {
            "name": entry.get("master_sku_name") or (master_sku.get("name") if master_sku else None),
            "sku_code": entry.get("sku_code") or (master_sku.get("sku_code") if master_sku else None),
            "hsn_code": master_sku.get("hsn_code") if master_sku else None,
            "quantity": quantity,
            "is_manufactured": is_manufactured  # Use calculated value from master_sku, not entry
        },
        "pricing": {
            "source": "amazon" if amazon_price else "order",
            "is_gst_inclusive": is_marketplace,  # Flag to indicate if price includes GST
            "taxable_value": price_without_gst,  # Amount before GST
            "gst_rate": gst_rate,
            "gst_amount": gst_amount,
            "quantity": quantity,
            "total_value": total_value  # Final amount (taxable + GST)
        },
        "logistics": {
            "tracking_id": entry.get("tracking_id"),
            "courier": entry.get("courier") or entry.get("shipping_method")
        },
        "documents": {
            "invoice_number": entry.get("invoice_number"),
            "invoice_uploaded": bool(entry.get("invoice_url")),
            "label_uploaded": bool(entry.get("label_url")),
            "eway_bill_number": entry.get("eway_bill_number"),
            "eway_bill_uploaded": bool(entry.get("eway_bill_url"))
        },
        "serial_numbers": {
            "selected": entry.get("serial_number"),
            "available": available_serials
        },
        "stock": {
            "available": (stock_items_result.get("items", [{}])[0].get("available", 0) if stock_items_result else (len(available_serials) if is_manufactured else (sku_stock.get("stock_quantity", 0) if sku_stock else 0))),
            "is_available": (stock_items_result.get("all_in_stock", False) if stock_items_result else (len(available_serials) > 0 if is_manufactured else (sku_stock.get("stock_quantity", 0) > 0 if sku_stock else False))),
            "per_item": (stock_items_result.get("items", []) if stock_items_result else [])
        },
        "item_count": len(entry.get("items", [])) or 1,  # Number of items in the order
        "is_multi_item": len(entry.get("items", [])) > 1,  # Flag for multi-item orders
        "master_sku": {
            "id": master_sku.get("id") if master_sku else None,
            "name": master_sku.get("name") if master_sku else None,
            "sku_code": master_sku.get("sku_code") if master_sku else None,
            "weight_kg": master_sku.get("weight_kg") if master_sku else None,  # Weight in kg
            "length_cm": master_sku.get("length_cm") if master_sku else None,  # Length in cm
            "breadth_cm": master_sku.get("breadth_cm") if master_sku else None,  # Breadth in cm
            "height_cm": master_sku.get("height_cm") if master_sku else None  # Height in cm
        } if master_sku else None,
        "compliance": compliance,
        "missing_fields": missing,
        "ready_to_dispatch": len(missing) == 0
    }


@api_router.get("/bot/available-serials/{order_id}")
async def bot_available_serials(
    order_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get available serial numbers for an order's product"""
    
    entry = await db.pending_fulfillment.find_one({"id": order_id}, {"_id": 0})
    if not entry:
        raise HTTPException(status_code=404, detail="Order not found")
    
    if not entry.get("master_sku_id"):
        return {"serials": [], "message": "No product SKU linked to this order"}
    
    firm_id = entry.get("firm_id") or "default"
    
    serials = await db.finished_good_serials.find(
        {
            "master_sku_id": entry["master_sku_id"],
            "firm_id": firm_id,
            "status": "in_stock"
        },
        {"_id": 0, "id": 1, "serial_number": 1, "manufacturing_date": 1, "batch_number": 1, "warranty_start": 1}
    ).sort("manufacturing_date", 1).to_list(100)
    
    return {
        "serials": serials,
        "count": len(serials),
        "product_name": entry.get("master_sku_name"),
        "quantity_needed": entry.get("quantity", 1)
    }


@api_router.post("/bot/select-serial")
async def bot_select_serial(
    order_id: str = Form(...),
    serial_number: str = Form(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Select and atomically reserve a serial number for dispatch."""
    entry = await db.pending_fulfillment.find_one({"id": order_id})
    if not entry:
        raise HTTPException(status_code=404, detail="Order not found")
    
    now_iso = datetime.now(timezone.utc).isoformat()
    
    # If the order already has a DIFFERENT serial reserved, release that one first
    prev_serial = entry.get("serial_number")
    if prev_serial and prev_serial != serial_number:
        await db.finished_good_serials.update_one(
            {"serial_number": prev_serial, "status": "reserved", "reserved_by_order_id": order_id},
            {"$set": {"status": "in_stock", "reserved_by_order_id": None, "reserved_at": None, "updated_at": now_iso}}
        )
    
    # Guard: serial must belong to the same master_sku + firm as the order
    # Accept "in_stock" OR "reserved" if already reserved by this same order (re-reserve scenario)
    serial_filter = {
        "serial_number": serial_number,
        "$or": [
            {"status": "in_stock"},
            {"status": "reserved", "reserved_by_order_id": order_id}
        ]
    }
    if entry.get("master_sku_id"):
        serial_filter["master_sku_id"] = entry["master_sku_id"]
    if entry.get("firm_id"):
        serial_filter["firm_id"] = entry["firm_id"]
    
    # Atomic reserve: find-and-update in one op so two callers can't both win
    reserved = await db.finished_good_serials.find_one_and_update(
        serial_filter,
        {"$set": {
            "status": "reserved",
            "reserved_by_order_id": order_id,
            "reserved_by_user": user["id"],
            "reserved_at": now_iso,
            "updated_at": now_iso,
        }},
        return_document=True
    )
    
    if not reserved:
        # Either doesn't exist, or already reserved/dispatched, or wrong sku/firm
        existing = await db.finished_good_serials.find_one({"serial_number": serial_number})
        if not existing:
            raise HTTPException(status_code=404, detail=f"Serial {serial_number} not found")
        if existing.get("status") != "in_stock":
            raise HTTPException(status_code=409, detail=f"Serial {serial_number} is {existing.get('status')} — pick another")
        raise HTTPException(status_code=400, detail=f"Serial {serial_number} does not belong to this order's SKU/firm")
    
    await db.pending_fulfillment.update_one(
        {"id": order_id},
        {"$set": {
            "serial_number": serial_number,
            "serial_id": reserved.get("id"),
            "updated_at": now_iso,
        }}
    )
    
    return {"message": f"Serial {serial_number} reserved for this order", "serial": serial_number}


@api_router.get("/bot/customer-history/{phone}")
async def bot_customer_history(phone: str, user: dict = Depends(require_roles(["admin", "accountant"]))):
    """Get customer's previous orders and suggest address"""
    history = await bot_get_customer_history(phone)
    return history


@api_router.get("/customer/refund-history")
async def customer_refund_history(
    phone: Optional[str] = None,
    amazon_order_id: Optional[str] = None,
    customer_name: Optional[str] = None,
    pincode: Optional[str] = None,
    user: dict = Depends(require_roles([
        "admin", "accountant", "supervisor", "dispatcher",
        "call_support", "service_agent", "customer",
    ])),
):
    """Has this customer had a refunded or cancelled order before? Surfaces
    a single payload the UI can use to show a 'previous refund/cancellation'
    warning on ticket creation, warranty registration, customer detail page,
    and global search results.

    Match keys (any one is enough):
      - phone               → exact match on amazon_orders.phone_manual
      - amazon_order_id     → direct order lookup
      - customer_name+pincode → fuzzy match on the manual customer fields

    'Refunded' threshold (defined 2026-05-25): sum(amazon_refunds.refund_amount)
    for the order must exceed 50% of its grand_total. Minor partial refunds
    don't trip the warning.

    'Cancelled' = amazon_orders.crm_status == 'cancelled'."""
    or_clauses = []
    if phone:
        # Normalise to the last 10 digits so '+91 98...', '+9198...', and
        # plain '98...' all hit. amazon_orders stores phones as 10-digit.
        digits = ''.join(c for c in phone if c.isdigit())[-10:]
        if len(digits) == 10:
            or_clauses.append({"phone_manual": digits})
    if amazon_order_id:
        or_clauses.append({"amazon_order_id": amazon_order_id.strip()})
    if customer_name and pincode:
        or_clauses.append({
            "customer_name_manual": {
                "$regex": f"^{re.escape(customer_name.strip())}",
                "$options": "i",
            },
            "pincode_manual": pincode.strip(),
        })

    empty = {"has_history": False, "refunded_count": 0,
             "cancelled_count": 0, "matched_orders": []}
    if not or_clauses:
        return empty

    matched = await db.amazon_orders.find(
        {"$or": or_clauses},
        {"_id": 0, "amazon_order_id": 1, "firm_id": 1, "firm_name": 1,
         "purchase_date": 1, "crm_status": 1, "order_total": 1,
         "customer_name_manual": 1, "phone_manual": 1, "pincode_manual": 1},
    ).to_list(200)
    if not matched:
        return empty

    def _money(v):
        if isinstance(v, dict):
            try: return float(v.get("Amount") or 0)
            except (TypeError, ValueError): return 0.0
        try: return float(v or 0)
        except (TypeError, ValueError): return 0.0

    flagged = []
    for o in matched:
        oid = o["amazon_order_id"]
        refund_total = 0.0
        async for r in db.amazon_refunds.find(
            {"amazon_order_id": oid}, {"_id": 0, "refund_amount": 1},
        ):
            refund_total += _money(r.get("refund_amount"))

        gt = _money(o.get("order_total"))
        if gt <= 0:
            inv = await db.sales_invoices.find_one(
                {"marketplace_order_id": oid}, {"_id": 0, "grand_total": 1},
            )
            if inv:
                gt = _money(inv.get("grand_total"))

        ratio = (refund_total / gt) if gt > 0 else 0.0
        is_refunded = refund_total > 0 and ratio > 0.5
        is_cancelled = (o.get("crm_status") == "cancelled")
        if not (is_refunded or is_cancelled):
            continue
        flagged.append({
            "amazon_order_id": oid,
            "firm_name": o.get("firm_name") or o.get("firm_id"),
            "purchase_date": (o.get("purchase_date") or "")[:10],
            "crm_status": o.get("crm_status"),
            "customer_name": o.get("customer_name_manual"),
            "phone": o.get("phone_manual"),
            "pincode": o.get("pincode_manual"),
            "grand_total": round(gt, 2),
            "refund_amount": round(refund_total, 2),
            "refund_ratio": round(ratio, 2),
            "is_refunded": is_refunded,
            "is_cancelled": is_cancelled,
        })

    refunded_n  = sum(1 for e in flagged if e["is_refunded"])
    cancelled_n = sum(1 for e in flagged if e["is_cancelled"])
    return {
        "has_history": bool(flagged),
        "refunded_count": refunded_n,
        "cancelled_count": cancelled_n,
        # Newest first so the UI shows recent activity at the top
        "matched_orders": sorted(
            flagged, key=lambda e: e["purchase_date"], reverse=True,
        ),
    }


@api_router.get("/bot/comprehensive-order/{order_id}")
async def bot_comprehensive_order_analysis(order_id: str, user: dict = Depends(require_roles(["admin", "accountant"]))):
    """
    Get comprehensive analysis of an order including all related data:
    - Customer details
    - Tracking ID
    - Serial numbers
    - SKU mapping
    - Pricing & GST
    - Sales invoice status
    - Dispatch entry
    - Payment reconciliation
    """
    analysis = {
        "order_id": order_id,
        "found": False,
        "source": None,
        "checks": {
            "customer_details": {"status": "missing", "data": {}},
            "tracking_id": {"status": "missing", "data": None},
            "serial_numbers": {"status": "not_applicable", "data": []},
            "sku_mapping": {"status": "missing", "data": {}},
            "pricing_gst": {"status": "missing", "data": {}},
            "sales_invoice": {"status": "missing", "data": None},
            "dispatch_entry": {"status": "missing", "data": None},
            "payment_reconciliation": {"status": "missing", "data": None}
        },
        "raw_order": None,
        "summary": {"complete": 0, "missing": 0, "issues": []}
    }
    
    # Search for order in all collections
    order = None
    source = None
    
    # Check pending_fulfillment
    pf_order = await db.pending_fulfillment.find_one({
        "$or": [
            {"order_id": {"$regex": f"^{order_id}$", "$options": "i"}},
            {"tracking_id": {"$regex": f"^{order_id}$", "$options": "i"}},
            {"id": order_id}
        ]
    }, {"_id": 0})
    if pf_order:
        order = pf_order
        source = "pending_fulfillment"
    
    # Check dispatches
    if not order:
        dispatch = await db.dispatches.find_one({
            "$or": [
                {"order_id": {"$regex": f"^{order_id}$", "$options": "i"}},
                {"tracking_id": {"$regex": f"^{order_id}$", "$options": "i"}},
                {"dispatch_number": {"$regex": f"^{order_id}$", "$options": "i"}},
                {"marketplace_order_id": {"$regex": f"^{order_id}$", "$options": "i"}}
            ]
        }, {"_id": 0})
        if dispatch:
            order = dispatch
            source = "dispatches"
    
    # Check amazon_orders
    if not order:
        amazon = await db.amazon_orders.find_one({
            "$or": [
                {"amazon_order_id": {"$regex": f"^{order_id}$", "$options": "i"}},
                {"order_id": {"$regex": f"^{order_id}$", "$options": "i"}}
            ]
        }, {"_id": 0})
        if amazon:
            order = amazon
            source = "amazon_orders"
    
    if not order:
        return analysis
    
    analysis["found"] = True
    analysis["source"] = source
    analysis["raw_order"] = order
    
    # 1. Customer Details Check
    customer_name = order.get("customer_name") or order.get("buyer_name")
    phone = (
        order.get("customer_phone") or order.get("phone") or 
        order.get("buyer_phone") or order.get("ship_phone") or
        order.get("shipping_phone") or order.get("recipient_phone")
    )
    address = order.get("address") or order.get("shipping_address")
    state = order.get("state") or order.get("shipping_state")
    pincode = order.get("pincode") or order.get("shipping_pincode") or order.get("postal_code")
    city = order.get("city") or order.get("shipping_city")
    
    customer_data = {
        "name": customer_name,
        "phone": phone,
        "address": address,
        "city": city,
        "state": state,
        "pincode": pincode
    }
    
    customer_complete = all([customer_name, phone, address, state, pincode])
    analysis["checks"]["customer_details"] = {
        "status": "complete" if customer_complete else "incomplete",
        "data": customer_data,
        "missing": [k for k, v in customer_data.items() if not v]
    }
    
    # 2. Tracking ID Check
    tracking_id = order.get("tracking_id") or order.get("tracking_number")
    analysis["checks"]["tracking_id"] = {
        "status": "complete" if tracking_id else "missing",
        "data": tracking_id
    }
    
    # 3. Serial Numbers Check
    items = order.get("items", [])
    has_manufactured = False
    serials_assigned = []
    
    for item in items:
        master_sku_id = item.get("master_sku_id")
        if master_sku_id:
            sku = await db.master_skus.find_one({"id": master_sku_id}, {"_id": 0})
            if sku and sku.get("product_type") == "manufactured":
                has_manufactured = True
    
    # Also check single-item orders
    if order.get("master_sku_id"):
        sku = await db.master_skus.find_one({"id": order.get("master_sku_id")}, {"_id": 0})
        if sku and sku.get("product_type") == "manufactured":
            has_manufactured = True
    
    # Check if serials are assigned
    if order.get("item_serials"):
        serials_assigned = order.get("item_serials", [])
    elif order.get("serial_number"):
        serials_assigned = [order.get("serial_number")]
    
    if has_manufactured:
        analysis["checks"]["serial_numbers"] = {
            "status": "complete" if serials_assigned else "missing",
            "data": serials_assigned,
            "required": True
        }
    else:
        analysis["checks"]["serial_numbers"] = {
            "status": "not_applicable",
            "data": [],
            "required": False
        }
    
    # 4. SKU Mapping Check
    sku_data = []
    if items:
        for item in items:
            master_sku_id = item.get("master_sku_id")
            if master_sku_id:
                sku = await db.master_skus.find_one({"id": master_sku_id}, {"_id": 0})
                if sku:
                    sku_data.append({
                        "name": sku.get("name"),
                        "sku_code": sku.get("sku_code"),
                        "hsn_code": sku.get("hsn_code"),
                        "gst_rate": sku.get("gst_rate"),
                        "mapped": True
                    })
                else:
                    sku_data.append({"master_sku_id": master_sku_id, "mapped": False})
            else:
                sku_data.append({"title": item.get("title"), "mapped": False})
    elif order.get("master_sku_id"):
        sku = await db.master_skus.find_one({"id": order.get("master_sku_id")}, {"_id": 0})
        if sku:
            sku_data.append({
                "name": sku.get("name"),
                "sku_code": sku.get("sku_code"),
                "hsn_code": sku.get("hsn_code"),
                "gst_rate": sku.get("gst_rate"),
                "mapped": True
            })
    
    all_mapped = all(s.get("mapped") for s in sku_data) if sku_data else False
    analysis["checks"]["sku_mapping"] = {
        "status": "complete" if all_mapped else "incomplete" if sku_data else "missing",
        "data": sku_data
    }
    
    # 5. Pricing & GST Check
    invoice_value = order.get("invoice_value") or order.get("order_total") or order.get("amount")
    taxable_value = order.get("taxable_value")
    gst_amount = order.get("gst_amount") or order.get("total_gst")
    
    pricing_data = {
        "invoice_value": invoice_value,
        "taxable_value": taxable_value,
        "gst_amount": gst_amount,
        "payment_status": order.get("payment_status", "unknown")
    }
    
    analysis["checks"]["pricing_gst"] = {
        "status": "complete" if invoice_value else "missing",
        "data": pricing_data
    }
    
    # 6. Sales Invoice Check
    lookup_id = order.get("order_id") or order.get("amazon_order_id") or order_id
    sales_invoice = await db.sales_invoices.find_one({
        "$or": [
            {"order_id": lookup_id},
            {"dispatch_id": order.get("id")},
            {"reference_number": {"$regex": lookup_id, "$options": "i"}}
        ]
    }, {"_id": 0})
    
    analysis["checks"]["sales_invoice"] = {
        "status": "complete" if sales_invoice else "missing",
        "data": {
            "invoice_number": sales_invoice.get("invoice_number") if sales_invoice else None,
            "date": sales_invoice.get("invoice_date") if sales_invoice else None,
            "grand_total": sales_invoice.get("grand_total") if sales_invoice else None
        } if sales_invoice else None
    }
    
    # 7. Dispatch Entry Check
    dispatch_entry = None
    if source == "dispatches":
        dispatch_entry = order
    else:
        dispatch_entry = await db.dispatches.find_one({
            "$or": [
                {"order_id": lookup_id},
                {"marketplace_order_id": lookup_id},
                {"pending_fulfillment_id": order.get("id")}
            ]
        }, {"_id": 0})
    
    analysis["checks"]["dispatch_entry"] = {
        "status": "complete" if dispatch_entry else "missing",
        "data": {
            "dispatch_number": dispatch_entry.get("dispatch_number") if dispatch_entry else None,
            "dispatch_date": dispatch_entry.get("dispatch_date") if dispatch_entry else None,
            "status": dispatch_entry.get("status") if dispatch_entry else None
        } if dispatch_entry else None
    }
    
    # 8. Payment Reconciliation Check
    # Check in ecommerce reconciliation if it's a marketplace order
    order_source = order.get("order_source") or order.get("source")
    recon_data = None
    
    if order_source in ["amazon", "flipkart", "Amazon", "Flipkart"]:
        recon_tx = await db.payout_transactions.find_one({
            "$or": [
                {"order_id": lookup_id},
                {"external_order_id": lookup_id}
            ]
        }, {"_id": 0})
        
        if recon_tx:
            recon_data = {
                "matched": recon_tx.get("matched", False),
                "transaction_type": recon_tx.get("type"),
                "amount": recon_tx.get("amount"),
                "statement_id": recon_tx.get("statement_id")
            }
    
    # Check if marked as paid
    payment_status = order.get("payment_status") or (dispatch_entry.get("payment_status") if dispatch_entry else None)
    
    analysis["checks"]["payment_reconciliation"] = {
        "status": "complete" if (recon_data and recon_data.get("matched")) or payment_status == "paid" else "pending" if recon_data else "not_reconciled",
        "data": recon_data or {"payment_status": payment_status},
        "marketplace_order": order_source in ["amazon", "flipkart", "Amazon", "Flipkart"]
    }
    
    # Generate Summary
    complete_count = sum(1 for c in analysis["checks"].values() if c["status"] == "complete" or c["status"] == "not_applicable")
    missing_count = sum(1 for c in analysis["checks"].values() if c["status"] in ["missing", "incomplete", "not_reconciled"])
    
    issues = []
    if analysis["checks"]["customer_details"]["status"] != "complete":
        issues.append(f"Missing customer details: {', '.join(analysis['checks']['customer_details'].get('missing', []))}")
    if analysis["checks"]["tracking_id"]["status"] == "missing":
        issues.append("Tracking ID not set")
    if analysis["checks"]["serial_numbers"]["status"] == "missing":
        issues.append("Serial number required but not assigned")
    if analysis["checks"]["sku_mapping"]["status"] != "complete":
        issues.append("SKU not fully mapped")
    if analysis["checks"]["pricing_gst"]["status"] == "missing":
        issues.append("Pricing/invoice value missing")
    if analysis["checks"]["sales_invoice"]["status"] == "missing":
        issues.append("Sales invoice not created")
    if analysis["checks"]["dispatch_entry"]["status"] == "missing":
        issues.append("Not dispatched yet")
    if analysis["checks"]["payment_reconciliation"]["status"] == "not_reconciled":
        issues.append("Payment not reconciled")
    
    analysis["summary"] = {
        "complete": complete_count,
        "total": len(analysis["checks"]),
        "issues": issues,
        "overall_status": "complete" if not issues else "has_issues"
    }
    
    return analysis


@api_router.get("/bot/orders-missing-invoices")
async def bot_get_orders_missing_invoices(
    limit: int = 20,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get orders that are missing invoice uploads - for 'fix invoices' command"""
    
    # Find pending fulfillment entries missing invoice_url
    missing_invoices = await db.pending_fulfillment.find({
        "status": {"$in": ["pending_dispatch", "ready_to_dispatch"]},
        "$or": [
            {"invoice_url": {"$exists": False}},
            {"invoice_url": None},
            {"invoice_url": ""}
        ]
    }, {"_id": 0}).sort("created_at", -1).limit(limit).to_list(limit)
    
    results = []
    for order in missing_invoices:
        results.append({
            "id": order.get("id"),
            "order_id": order.get("order_id"),
            "tracking_id": order.get("tracking_id"),
            "customer_name": order.get("customer_name"),
            "customer_phone": order.get("customer_phone") or order.get("phone"),
            "status": order.get("status"),
            "created_at": order.get("created_at"),
            "has_tracking": bool(order.get("tracking_id")),
            "has_label": bool(order.get("label_url"))
        })
    
    return {
        "count": len(results),
        "orders": results,
        "message": f"Found {len(results)} orders missing invoices"
    }


@api_router.post("/bot/chat")
async def bot_intelligent_chat(
    message: str = Form(...),
    session_id: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Intelligent chat endpoint that understands natural language queries.
    Parses intents like:
    - "find order 1234" / "show me order 1234" / "can you find order ID 1234"
    - "fix invoices" / "show missing invoices"
    - "status" / "how's everything"
    """
    message_lower = message.lower().strip()
    
    # Intent detection patterns
    import re
    
    # Skip command-like words early
    command_words = ["status", "stuck", "missing", "help", "production", "invoices", "me", "order", "orders", "the", "a", "an"]
    
    # Pattern: Fix invoices / missing invoices - CHECK FIRST before order search
    if any(p in message_lower for p in ["fix invoice", "missing invoice", "orders without invoice", "need invoice"]):
        return {
            "intent": "fix_invoices",
            "action": "list_missing_invoices",
            "message": "Fetching orders missing invoices..."
        }
    
    # Pattern: Stuck orders - CHECK EARLY
    if any(p in message_lower for p in ["stuck", "delayed", "pending too long", "old orders"]):
        return {
            "intent": "stuck_orders",
            "action": "list_stuck",
            "message": "Checking for stuck orders..."
        }
    
    # Pattern: Status / Summary / Briefing  
    if any(p in message_lower for p in ["status", "summary", "briefing", "how's everything", "what's going on", "overview"]):
        return {
            "intent": "status",
            "action": "daily_briefing",
            "message": "Fetching operations status..."
        }
    
    # Pattern: Find/show/get/check order [ID] - more specific patterns
    order_patterns = [
        # "show me order 123" or "find order 123"
        r"(?:show\s+me|find|get|check|pull|look\s*up|search)\s+(?:order\s+)?(?:id\s+)?[#]?([A-Za-z0-9][A-Za-z0-9\-_]+)",
        # "order 123" or "order id 123"
        r"^order\s+(?:id\s+)?[#]?([A-Za-z0-9][A-Za-z0-9\-_]+)$",
        # "can you find order 123"
        r"can\s+you\s+(?:find|show|get|check)\s+(?:order\s+)?(?:id\s+)?[#]?([A-Za-z0-9][A-Za-z0-9\-_]+)",
        # Just a long alphanumeric string that looks like an order ID (e.g., 171-3496729-7741914)
        r"^([0-9]{3}-[0-9]{7}-[0-9]{7})$",
        r"^([A-Z]{2,3}-[0-9]+)$"
    ]
    
    for pattern in order_patterns:
        match = re.search(pattern, message_lower)
        if match:
            order_id = match.group(1).strip()
            # Skip if it's just a command word
            if order_id.lower() in command_words:
                continue
            # Skip very short IDs (likely partial words)
            if len(order_id) < 3:
                continue
            return {
                "intent": "find_order",
                "order_id": order_id,
                "action": "comprehensive_analysis",
                "message": f"Looking up order {order_id}..."
            }
    
    # Pattern: Missing data
    if any(p in message_lower for p in ["missing data", "incomplete", "data gap"]):
        return {
            "intent": "missing_data",
            "action": "list_missing",
            "message": "Checking for data gaps..."
        }
    
    # Pattern: Production
    if any(p in message_lower for p in ["production", "stock", "inventory", "what to make"]):
        return {
            "intent": "production",
            "action": "production_suggestions",
            "message": "Analyzing stock levels..."
        }
    
    # Pattern: Help
    if any(p in message_lower for p in ["help", "what can you do", "commands", "how to use"]):
        return {
            "intent": "help",
            "action": "show_help",
            "message": "Here's what I can do..."
        }
    
    # Default: Try to search
    return {
        "intent": "search",
        "query": message,
        "action": "search_order",
        "message": f"Searching for '{message}'..."
    }


@api_router.get("/bot/universal-search/{query}")
async def bot_universal_search(
    query: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """
    Universal search across ALL CRM data:
    - Order IDs (amazon_orders, pending_fulfillment, dispatches)
    - Tracking IDs (dispatches, incoming_queue, returns)
    - Phone numbers (customers, orders)
    - Serial numbers (finished_good_serials)
    """
    results = {
        "query": query,
        "found_in": [],
        "primary_result": None,
        "all_results": {}
    }
    
    query_clean = query.strip()
    
    # 1. Search Amazon Orders
    amazon_order = await db.amazon_orders.find_one({
        "$or": [
            {"amazon_order_id": {"$regex": f"^{query_clean}$", "$options": "i"}},
            {"order_id": {"$regex": f"^{query_clean}$", "$options": "i"}}
        ]
    }, {"_id": 0})
    
    if amazon_order:
        results["found_in"].append("amazon_orders")
        
        # Check if actually exists in pending_fulfillment (not just crm_status flag)
        pf_exists = await db.pending_fulfillment.find_one({
            "$or": [
                {"amazon_order_id": amazon_order.get("amazon_order_id")},
                {"order_id": amazon_order.get("amazon_order_id")}
            ]
        })
        # Also check if already dispatched
        dispatch_exists = await db.dispatches.find_one({
            "$or": [
                {"marketplace_order_id": amazon_order.get("amazon_order_id")},
                {"order_id": amazon_order.get("amazon_order_id")}
            ]
        }, {"_id": 0, "dispatch_number": 1, "tracking_id": 1, "status": 1})
        
        in_crm = (pf_exists is not None) or (dispatch_exists is not None)
        
        results["all_results"]["amazon_order"] = {
            "type": "amazon_order",
            "data": amazon_order,
            "in_crm": in_crm,
            "status": amazon_order.get("crm_status") or amazon_order.get("order_status"),
            "actions": []
        }
        # Determine available actions based on order state
        if dispatch_exists:
            # Order already dispatched (either via normal flow or mark_already_dispatched)
            results["all_results"]["amazon_order"]["actions"] = ["view_dispatch"]
            results["all_results"]["amazon_order"]["dispatch_info"] = dispatch_exists
            results["all_results"]["amazon_order"]["status"] = "dispatched"
        elif not in_crm:
            results["all_results"]["amazon_order"]["actions"] = ["import_to_crm", "mark_already_dispatched"]
        elif pf_exists and pf_exists.get("status") not in ["dispatched", "cancelled"]:
            results["all_results"]["amazon_order"]["actions"] = ["prepare_dispatch", "view_details"]
        else:
            results["all_results"]["amazon_order"]["actions"] = ["view_details"]
    
    # 2. Search Pending Fulfillment (use contains match for order_id to handle partial searches)
    pf_order = await db.pending_fulfillment.find_one({
        "$or": [
            {"order_id": {"$regex": query_clean, "$options": "i"}},
            {"tracking_id": {"$regex": query_clean, "$options": "i"}},
            {"id": query_clean},
            {"amazon_order_id": {"$regex": query_clean, "$options": "i"}}
        ]
    }, {"_id": 0})
    
    if pf_order:
        results["found_in"].append("pending_fulfillment")
        results["all_results"]["pending_fulfillment"] = {
            "type": "pending_fulfillment",
            "data": pf_order,
            "status": pf_order.get("status"),
            "actions": ["prepare_dispatch", "update_details"] if pf_order.get("status") != "dispatched" else ["view_details"]
        }
    
    # 3. Search Dispatches (use contains match for order_id)
    dispatch = await db.dispatches.find_one({
        "$or": [
            {"order_id": {"$regex": query_clean, "$options": "i"}},
            {"tracking_id": {"$regex": query_clean, "$options": "i"}},
            {"dispatch_number": {"$regex": query_clean, "$options": "i"}},
            {"marketplace_order_id": {"$regex": query_clean, "$options": "i"}}
        ]
    }, {"_id": 0})
    
    if dispatch:
        results["found_in"].append("dispatches")
        results["all_results"]["dispatch"] = {
            "type": "dispatch",
            "data": dispatch,
            "status": dispatch.get("status"),
            "actions": ["view_details"]
        }
    
    # 4. Search Incoming Queue (Returns/RTO)
    incoming = await db.incoming_queue.find_one({
        "$or": [
            {"tracking_id": {"$regex": f"^{query_clean}$", "$options": "i"}},
            {"awb_number": {"$regex": f"^{query_clean}$", "$options": "i"}},
            {"order_id": {"$regex": f"^{query_clean}$", "$options": "i"}}
        ]
    }, {"_id": 0})
    
    if incoming:
        results["found_in"].append("incoming_queue")
        results["all_results"]["incoming"] = {
            "type": "incoming_return",
            "data": incoming,
            "status": incoming.get("status"),
            "actions": ["add_to_inventory", "send_to_repair", "send_to_repair_yard", "mark_dead_stock"]
        }
    
    # 5. Search Serial Numbers
    serial = await db.finished_good_serials.find_one({
        "serial_number": {"$regex": f"^{query_clean}$", "$options": "i"}
    }, {"_id": 0})
    
    if serial:
        results["found_in"].append("serial_numbers")
        # Get additional info about this serial
        serial_dispatch = await db.dispatches.find_one({"serial_number": serial.get("serial_number")}, {"_id": 0})
        serial_warranty = await db.warranties.find_one({"serial_number": serial.get("serial_number")}, {"_id": 0})
        
        results["all_results"]["serial"] = {
            "type": "serial_number",
            "data": serial,
            "dispatch_info": serial_dispatch,
            "warranty_info": serial_warranty,
            "status": serial.get("status"),
            "actions": ["update_serial_info", "view_history"]
        }
    
    # 6. Search by Phone Number
    if query_clean.isdigit() and len(query_clean) >= 10:
        # Search customers/orders by phone
        customer_orders = await db.pending_fulfillment.find({
            "$or": [
                {"customer_phone": {"$regex": query_clean}},
                {"phone": {"$regex": query_clean}}
            ]
        }, {"_id": 0}).limit(10).to_list(10)
        
        dispatched_orders = await db.dispatches.find({
            "phone": {"$regex": query_clean}
        }, {"_id": 0}).limit(10).to_list(10)
        
        if customer_orders or dispatched_orders:
            results["found_in"].append("customer_phone")
            results["all_results"]["customer"] = {
                "type": "customer_phone",
                "pending_orders": customer_orders,
                "dispatched_orders": dispatched_orders,
                "total_orders": len(customer_orders) + len(dispatched_orders),
                "actions": ["view_customer_history"]
            }
    
    # 7. Search Tickets (Repairs)
    ticket = await db.tickets.find_one({
        "$or": [
            {"ticket_number": {"$regex": f"^{query_clean}$", "$options": "i"}},
            {"tracking_id": {"$regex": f"^{query_clean}$", "$options": "i"}},
            {"return_tracking": {"$regex": f"^{query_clean}$", "$options": "i"}},
            {"board_serial_number": {"$regex": f"^{query_clean}$", "$options": "i"}}
        ]
    }, {"_id": 0})
    
    if ticket:
        results["found_in"].append("tickets")
        results["all_results"]["ticket"] = {
            "type": "repair_ticket",
            "data": ticket,
            "status": ticket.get("status"),
            "actions": ["view_ticket", "update_status"]
        }
    
    # Determine primary result
    if len(results["found_in"]) > 0:
        # Priority: serial > incoming > pending_fulfillment > amazon_order > dispatch > ticket > customer
        priority_order = ["serial_numbers", "incoming_queue", "pending_fulfillment", "amazon_orders", "dispatches", "tickets", "customer_phone"]
        for source in priority_order:
            if source in results["found_in"]:
                key_map = {
                    "serial_numbers": "serial",
                    "incoming_queue": "incoming",
                    "pending_fulfillment": "pending_fulfillment",
                    "amazon_orders": "amazon_order",
                    "dispatches": "dispatch",
                    "tickets": "ticket",
                    "customer_phone": "customer"
                }
                results["primary_result"] = results["all_results"].get(key_map[source])
                break
    
    return results


@api_router.post("/bot/import-amazon-to-crm")
async def bot_import_amazon_to_crm(
    amazon_order_id: str = Form(...),
    master_sku_id: Optional[str] = Form(None),
    customer_first_name: Optional[str] = Form(None),
    customer_last_name: Optional[str] = Form(None),
    customer_address: Optional[str] = Form(None),
    customer_phone: Optional[str] = Form(None),
    invoice_url: Optional[str] = Form(None),
    tracking_id: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Import Amazon order to CRM (creates pending_fulfillment entry).
    Uses shared SKU resolver for consistent multi-item mapping."""
    
    amazon_order = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id}, {"_id": 0})
    if not amazon_order:
        raise HTTPException(status_code=404, detail="Amazon order not found")
    
    # Check if this order was recently processed (within last 10 seconds) to prevent race conditions
    recent_cutoff = (datetime.now(timezone.utc) - timedelta(seconds=10)).isoformat()
    recent_import = await db.pending_fulfillment.find_one({
        "$or": [
            {"amazon_order_id": amazon_order_id},
            {"order_id": amazon_order_id}
        ],
        "created_at": {"$gte": recent_cutoff}
    })
    if recent_import:
        raise HTTPException(
            status_code=429,  # Too Many Requests
            detail="Order was just imported. Please wait and check the queue."
        )
    
    # COMPREHENSIVE duplicate check across ALL collections
    duplicate_check = await check_order_id_duplicate(amazon_order_id)
    if duplicate_check.get("exists"):
        raise HTTPException(
            status_code=400, 
            detail=duplicate_check.get("message", "Order already exists in CRM")
        )
    
    # Additional direct check for pending_fulfillment (belt and suspenders)
    existing = await db.pending_fulfillment.find_one({
        "$or": [
            {"amazon_order_id": amazon_order_id},
            {"order_id": amazon_order_id}
        ]
    })
    if existing:
        raise HTTPException(status_code=400, detail=f"Order already imported to CRM (ID: {existing.get('id')})")
    
    # Check dispatches as well
    existing_dispatch = await db.dispatches.find_one({
        "$or": [
            {"marketplace_order_id": amazon_order_id},
            {"order_id": amazon_order_id}
        ],
        "status": {"$ne": "cancelled"}
    })
    if existing_dispatch:
        raise HTTPException(
            status_code=400, 
            detail=f"Order already dispatched (Dispatch #: {existing_dispatch.get('dispatch_number')})"
        )
    
    now = datetime.now(timezone.utc)
    pf_id = str(uuid.uuid4())
    
    # Get firm ID
    firm_id = amazon_order.get("firm_id")
    firm = None
    if firm_id:
        firm = await db.firms.find_one({"id": firm_id}, {"_id": 0, "id": 1, "name": 1})
    if not firm:
        firm = await db.firms.find_one({}, {"_id": 0, "id": 1, "name": 1})
        firm_id = firm.get("id") if firm else None
    
    # ============ USE SHARED SKU RESOLVER ============
    resolution = await resolve_amazon_order_items_to_master_skus(amazon_order, firm_id, db, auto_persist_mapping=True)
    resolved_items = resolution["items"]
    total_quantity = resolution["total_quantity"]
    
    # Get primary SKU info from first resolved item OR use provided master_sku_id
    primary_item = resolved_items[0] if resolved_items else {}
    final_master_sku_id = master_sku_id or primary_item.get("master_sku_id")
    
    master_sku = None
    if final_master_sku_id:
        master_sku = await db.master_skus.find_one({"id": final_master_sku_id}, {"_id": 0})
    
    product_title = primary_item.get("master_sku_name") or primary_item.get("title") or "Unknown Product"
    amazon_sku = primary_item.get("amazon_sku") or primary_item.get("seller_sku") or primary_item.get("asin")
    
    # Build customer name - prefer provided name, fall back to Amazon data
    final_customer_name = None
    if customer_first_name and customer_last_name:
        final_customer_name = f"{customer_first_name} {customer_last_name}"
    elif customer_first_name:
        final_customer_name = customer_first_name
    else:
        final_customer_name = amazon_order.get("buyer_name") or amazon_order.get("customer_name")
    
    # Build address - prefer provided, fall back to Amazon data
    final_address = customer_address or amazon_order.get("shipping_address") or amazon_order.get("address") or amazon_order.get("address_line1")
    
    # Build phone - prefer provided, fall back to Amazon data (check multiple fields)
    final_phone = (
        customer_phone or 
        amazon_order.get("buyer_phone") or 
        amazon_order.get("phone") or
        amazon_order.get("ship_phone") or
        amazon_order.get("shipping_phone") or
        amazon_order.get("recipient_phone")
    )
    
    pf_entry = {
        "id": pf_id,
        "type": "amazon_order",
        "order_id": amazon_order.get("amazon_order_id"),
        "amazon_order_id": amazon_order.get("amazon_order_id"),
        "order_source": "amazon",
        "customer_name": final_customer_name,
        "customer_first_name": customer_first_name,
        "customer_last_name": customer_last_name,
        "customer_phone": final_phone,
        "phone": final_phone,
        "address": final_address,
        "address_line1": final_address,
        "city": amazon_order.get("shipping_city") or amazon_order.get("city"),
        "state": amazon_order.get("shipping_state") or amazon_order.get("state"),
        "pincode": amazon_order.get("shipping_pincode") or amazon_order.get("postal_code") or amazon_order.get("pincode"),
        "master_sku_id": final_master_sku_id,
        "master_sku_name": master_sku.get("name") if master_sku else product_title,
        "sku_code": master_sku.get("sku_code") if master_sku else amazon_sku,
        "amazon_sku": amazon_sku,
        "product_title": product_title,
        "quantity": total_quantity,  # Sum of all item quantities
        "order_total": amazon_order.get("order_total") or amazon_order.get("item_price"),
        "amount": amazon_order.get("order_total") or amazon_order.get("item_price"),
        "firm_id": firm_id,
        "firm_name": firm.get("name") if firm else None,
        "fulfillment_channel": amazon_order.get("fulfillment_channel"),
        "is_easyship": amazon_order.get("is_easy_ship", False),
        "tracking_id": tracking_id or amazon_order.get("tracking_id"),
        "carrier_name": amazon_order.get("carrier_name"),
        "invoice_url": invoice_url,
        "invoice_uploaded": bool(invoice_url),
        "items": resolved_items,  # Full items array with master_sku_id on each
        "all_items_mapped": resolution["all_mapped"],
        "unmapped_skus": resolution["unmapped_skus"],
        "status": "pending_dispatch",
        "payment_status": "paid" if amazon_order.get("payment_method") else "unpaid",
        "imported_by": user["id"],
        "imported_by_name": f"{user['first_name']} {user['last_name']}",
        "created_at": now.isoformat(),
        "updated_at": now.isoformat()
    }
    
    # Insert with duplicate key handling (belt and suspenders with the unique index)
    try:
        await db.pending_fulfillment.insert_one(pf_entry)
    except Exception as e:
        error_str = str(e).lower()
        if "duplicate key" in error_str or "e11000" in error_str:
            raise HTTPException(
                status_code=400, 
                detail=f"Order {amazon_order_id} already exists in the queue (duplicate detected)"
            )
        raise
    
    # Update amazon_orders with customer details and resolved items
    update_data = {
        "crm_status": "pending",
        "pending_fulfillment_id": pf_id,
        "items": resolved_items,
        "all_skus_mapped": resolution["all_mapped"],
        "imported_at": now.isoformat(),
        "updated_at": now.isoformat()
    }
    if customer_first_name:
        update_data["customer_first_name"] = customer_first_name
    if customer_last_name:
        update_data["customer_last_name"] = customer_last_name
    if final_customer_name:
        update_data["buyer_name"] = final_customer_name
    if customer_address:
        update_data["address_line1"] = customer_address
    if customer_phone:
        update_data["phone"] = customer_phone
    
    await db.amazon_orders.update_one(
        {"amazon_order_id": amazon_order_id},
        {"$set": update_data}
    )
    
    return {
        "message": "Amazon order imported to CRM successfully",
        "pending_fulfillment_id": pf_id,
        "order_id": amazon_order_id,
        "status": "pending_dispatch",
        "all_items_mapped": resolution["all_mapped"],
        "unmapped_skus": resolution["unmapped_skus"],
        "total_quantity": total_quantity,
        "next_actions": ["upload_invoice", "upload_label", "prepare_dispatch"]
    }


@api_router.post("/bot/mark-amazon-dispatched")
async def bot_mark_amazon_dispatched(
    amazon_order_id: str = Form(...),
    tracking_id: Optional[str] = Form(None),
    courier: Optional[str] = Form(None),
    dispatch_date: Optional[str] = Form(None),
    serial_number: Optional[str] = Form(None),
    master_sku_id: Optional[str] = Form(None),
    invoice_value: Optional[float] = Form(None),
    notes: Optional[str] = Form(None),
    customer_first_name: Optional[str] = Form(None),
    customer_last_name: Optional[str] = Form(None),
    customer_address: Optional[str] = Form(None),
    customer_state: Optional[str] = Form(None),
    customer_pincode: Optional[str] = Form(None),
    customer_phone: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Mark Amazon order as already dispatched (for historical reconciliation)"""
    
    amazon_order = await db.amazon_orders.find_one({"amazon_order_id": amazon_order_id}, {"_id": 0})
    if not amazon_order:
        raise HTTPException(status_code=404, detail="Amazon order not found")
    
    now = datetime.now(timezone.utc)
    dispatch_id = str(uuid.uuid4())
    
    # Generate dispatch number
    today_str = now.strftime("%Y%m%d")
    count = await db.dispatches.count_documents({"created_at": {"$regex": f"^{now.strftime('%Y-%m-%d')}"}})
    dispatch_number = f"MG-D-{today_str}{count + 1:05d}"
    
    # Get master SKU
    master_sku = None
    if master_sku_id:
        master_sku = await db.master_skus.find_one({"id": master_sku_id}, {"_id": 0})
    
    # Get firm
    firm = await db.firms.find_one({}, {"_id": 0, "id": 1, "name": 1})
    
    # CRITICAL: Amazon price is GST-inclusive - calculate taxable value
    final_invoice_value = invoice_value or amazon_order.get("order_total") or 0
    gst_rate = master_sku.get("gst_rate", 18) if master_sku else 18
    
    # Reverse-calculate taxable value from GST-inclusive price
    taxable_value = round(final_invoice_value / (1 + gst_rate / 100), 2) if final_invoice_value > 0 else 0
    gst_amount = round(final_invoice_value - taxable_value, 2) if final_invoice_value > 0 else 0
    
    # Create dispatch entry directly (already shipped)
    # Resolve customer fields - prefer user-entered values over Amazon order data
    full_name = None
    if customer_first_name and customer_last_name:
        full_name = f"{customer_first_name.strip()} {customer_last_name.strip()}"
    elif customer_first_name:
        full_name = customer_first_name.strip()
    
    resolved_name = full_name or amazon_order.get("buyer_name") or amazon_order.get("customer_name")
    resolved_phone = (customer_phone or "").strip() or amazon_order.get("buyer_phone") or amazon_order.get("phone")
    resolved_address = (customer_address or "").strip() or amazon_order.get("shipping_address") or amazon_order.get("address_line1") or amazon_order.get("address")
    resolved_state = (customer_state or "").strip() or amazon_order.get("shipping_state") or amazon_order.get("state")
    resolved_pincode = (customer_pincode or "").strip() or amazon_order.get("shipping_pincode") or amazon_order.get("postal_code")
    
    dispatch_doc = {
        "id": dispatch_id,
        "dispatch_number": dispatch_number,
        "dispatch_type": "amazon_order",
        "order_source": "amazon",
        "is_marketplace_order": True,
        "price_is_gst_inclusive": True,  # Flag for invoice generation
        "firm_id": firm.get("id") if firm else None,
        "firm_name": firm.get("name") if firm else None,
        "master_sku_id": master_sku_id,
        "master_sku_name": master_sku.get("name") if master_sku else None,
        "sku_code": master_sku.get("sku_code") if master_sku else None,
        "gst_rate": gst_rate,
        "quantity": amazon_order.get("quantity", 1),
        "serial_number": serial_number,
        "order_id": amazon_order.get("amazon_order_id"),
        "marketplace_order_id": amazon_order.get("amazon_order_id"),
        "customer_name": resolved_name,
        "customer_first_name": customer_first_name,
        "customer_last_name": customer_last_name,
        "phone": resolved_phone,
        "customer_phone": resolved_phone,
        "address": resolved_address,
        "city": amazon_order.get("shipping_city") or amazon_order.get("city"),
        "state": resolved_state,
        "pincode": resolved_pincode,
        "tracking_id": tracking_id or amazon_order.get("tracking_id"),
        "courier": courier or amazon_order.get("carrier_name"),
        # PRICING - properly separated for GST calculation
        "invoice_value": final_invoice_value,  # Total (GST inclusive)
        "taxable_value": taxable_value,  # Amount before GST
        "gst_amount": gst_amount,  # GST portion
        "status": "dispatched",
        "scanned_out_at": dispatch_date or now.isoformat(),
        "notes": notes or "Imported as already dispatched via Operations Bot",
        "is_historical_import": True,
        "created_by": user["id"],
        "created_by_name": f"{user['first_name']} {user['last_name']}",
        "created_at": now.isoformat()
    }
    
    await db.dispatches.insert_one(dispatch_doc)
    
    # Update amazon_orders status and customer details
    await db.amazon_orders.update_one(
        {"amazon_order_id": amazon_order_id},
        {"$set": {
            "crm_status": "dispatched",
            "dispatch_id": dispatch_id,
            "dispatch_number": dispatch_number,
            "dispatched_at": dispatch_date or now.isoformat(),
            "updated_at": now.isoformat(),
            # Write resolved customer fields back so search shows real customer
            "buyer_name": resolved_name,
            "buyer_phone": resolved_phone,
            "address_line1": resolved_address,
            "state": resolved_state,
            "postal_code": resolved_pincode
        }}
    )
    
    # Update serial number if provided
    if serial_number:
        await db.finished_good_serials.update_one(
            {"serial_number": serial_number},
            {"$set": {
                "status": "sold",
                "dispatch_id": dispatch_id,
                "dispatch_number": dispatch_number,
                "dispatched_at": now.isoformat(),
                "customer_name": resolved_name,
                "customer_phone": resolved_phone,
                "updated_at": now.isoformat()
            }}
        )
    
    # Also update pending_fulfillment if one exists for this order
    pf_update = {
        "status": "dispatched",
        "dispatch_id": dispatch_id,
        "dispatch_number": dispatch_number,
        "updated_at": now.isoformat()
    }
    if customer_first_name:
        pf_update["customer_first_name"] = customer_first_name
        pf_update["customer_last_name"] = customer_last_name
        pf_update["customer_name"] = resolved_name
    if customer_address:
        pf_update["address"] = resolved_address
    if customer_state:
        pf_update["state"] = resolved_state
    if customer_pincode:
        pf_update["pincode"] = resolved_pincode
    if customer_phone:
        pf_update["customer_phone"] = resolved_phone
        pf_update["phone"] = resolved_phone
    if tracking_id:
        pf_update["tracking_id"] = tracking_id
    if serial_number:
        pf_update["serial_number"] = serial_number
    
    await db.pending_fulfillment.update_one(
        {"$or": [
            {"amazon_order_id": amazon_order_id},
            {"marketplace_order_id": amazon_order_id}
        ]},
        {"$set": pf_update}
    )
    
    return {
        "message": "Amazon order marked as dispatched",
        "dispatch_id": dispatch_id,
        "dispatch_number": dispatch_number,
        "tracking_id": tracking_id,
        "status": "dispatched"
    }


@api_router.post("/bot/handle-rto")
async def bot_handle_rto(
    tracking_id: str = Form(...),
    action: str = Form(...),  # add_to_inventory, send_to_repair, send_to_repair_yard, mark_dead_stock
    master_sku_id: Optional[str] = Form(None),
    serial_number: Optional[str] = Form(None),
    condition: Optional[str] = Form("good"),  # good, damaged, defective
    notes: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Handle RTO/Return - Add to inventory, send to repair, or mark as dead stock"""
    
    # Find the incoming item or dispatch by tracking ID
    incoming = await db.incoming_queue.find_one({"tracking_id": tracking_id}, {"_id": 0})
    dispatch = await db.dispatches.find_one({"tracking_id": tracking_id}, {"_id": 0})
    
    source_item = incoming or dispatch
    if not source_item:
        raise HTTPException(status_code=404, detail=f"No record found for tracking ID: {tracking_id}")
    
    now = datetime.now(timezone.utc)
    
    # Get master SKU
    final_master_sku_id = master_sku_id or source_item.get("master_sku_id")
    master_sku = None
    if final_master_sku_id:
        master_sku = await db.master_skus.find_one({"id": final_master_sku_id}, {"_id": 0})
    
    if action == "add_to_inventory":
        # Add back to finished goods inventory
        if not final_master_sku_id:
            raise HTTPException(status_code=400, detail="Master SKU ID required to add to inventory")
        
        # Create inventory ledger entry
        firm = await db.firms.find_one({}, {"_id": 0, "id": 1})
        firm_id = source_item.get("firm_id") or (firm.get("id") if firm else None)
        
        ledger_entry = {
            "id": str(uuid.uuid4()),
            "item_type": "master_sku",
            "item_id": final_master_sku_id,
            "item_name": master_sku.get("name") if master_sku else None,
            "sku_code": master_sku.get("sku_code") if master_sku else None,
            "firm_id": firm_id,
            "transaction_type": "rto_return",
            "quantity_change": 1,
            "reference_type": "rto",
            "reference_id": tracking_id,
            "reference_number": tracking_id,
            "serial_number": serial_number or source_item.get("serial_number"),
            "condition": condition,
            "notes": notes or f"RTO return via tracking {tracking_id}",
            "created_by": user["id"],
            "created_by_name": f"{user['first_name']} {user['last_name']}",
            "created_at": now.isoformat()
        }
        
        # Get current balance
        last_entry = await db.inventory_ledger.find_one(
            {"item_id": final_master_sku_id, "item_type": "master_sku"},
            sort=[("created_at", -1)]
        )
        current_balance = last_entry.get("running_balance", 0) if last_entry else 0
        ledger_entry["running_balance"] = current_balance + 1
        
        await db.inventory_ledger.insert_one(ledger_entry)
        
        # Update serial number status if provided
        if serial_number:
            await db.finished_good_serials.update_one(
                {"serial_number": serial_number},
                {"$set": {
                    "status": "in_stock",
                    "condition": condition,
                    "rto_date": now.isoformat(),
                    "rto_tracking": tracking_id,
                    "updated_at": now.isoformat()
                }}
            )
        
        # Update incoming queue status
        if incoming:
            await db.incoming_queue.update_one(
                {"tracking_id": tracking_id},
                {"$set": {
                    "status": "processed",
                    "processed_action": "added_to_inventory",
                    "processed_at": now.isoformat(),
                    "processed_by": user["id"]
                }}
            )
        
        return {
            "message": "RTO added to inventory successfully",
            "action": "add_to_inventory",
            "master_sku": master_sku.get("name") if master_sku else final_master_sku_id,
            "new_balance": ledger_entry["running_balance"]
        }
    
    elif action == "send_to_repair":
        # Create repair ticket
        ticket_id = str(uuid.uuid4())
        ticket_number = f"TKT-{now.strftime('%Y%m%d')}-{str(uuid.uuid4())[:4].upper()}"
        
        ticket = {
            "id": ticket_id,
            "ticket_number": ticket_number,
            "type": "rto_repair",
            "source": "rto",
            "tracking_id": tracking_id,
            "master_sku_id": final_master_sku_id,
            "master_sku_name": master_sku.get("name") if master_sku else None,
            "serial_number": serial_number or source_item.get("serial_number"),
            "customer_name": source_item.get("customer_name"),
            "customer_phone": source_item.get("phone"),
            "condition": condition,
            "status": "pending_repair",
            "notes": notes,
            "created_by": user["id"],
            "created_by_name": f"{user['first_name']} {user['last_name']}",
            "created_at": now.isoformat()
        }
        
        await db.tickets.insert_one(ticket)
        
        # Update incoming queue
        if incoming:
            await db.incoming_queue.update_one(
                {"tracking_id": tracking_id},
                {"$set": {
                    "status": "sent_to_repair",
                    "ticket_id": ticket_id,
                    "ticket_number": ticket_number,
                    "processed_at": now.isoformat()
                }}
            )
        
        return {
            "message": "Sent to repair technician",
            "action": "send_to_repair",
            "ticket_number": ticket_number,
            "ticket_id": ticket_id
        }
    
    elif action == "send_to_repair_yard":
        # Update status to repair yard
        if incoming:
            await db.incoming_queue.update_one(
                {"tracking_id": tracking_id},
                {"$set": {
                    "status": "repair_yard",
                    "location": "repair_yard",
                    "condition": condition,
                    "processed_at": now.isoformat(),
                    "processed_by": user["id"],
                    "notes": notes
                }}
            )
        
        return {
            "message": "Sent to repair yard",
            "action": "send_to_repair_yard",
            "tracking_id": tracking_id
        }
    
    elif action == "mark_dead_stock":
        # Create dead stock entry
        dead_stock_entry = {
            "id": str(uuid.uuid4()),
            "tracking_id": tracking_id,
            "master_sku_id": final_master_sku_id,
            "master_sku_name": master_sku.get("name") if master_sku else None,
            "serial_number": serial_number or source_item.get("serial_number"),
            "condition": condition,
            "reason": notes or "Marked as dead stock via RTO processing",
            "source": "rto",
            "created_by": user["id"],
            "created_by_name": f"{user['first_name']} {user['last_name']}",
            "created_at": now.isoformat()
        }
        
        await db.dead_stock.insert_one(dead_stock_entry)
        
        # Update incoming queue
        if incoming:
            await db.incoming_queue.update_one(
                {"tracking_id": tracking_id},
                {"$set": {
                    "status": "dead_stock",
                    "processed_action": "marked_dead_stock",
                    "processed_at": now.isoformat()
                }}
            )
        
        # Update serial status
        if serial_number:
            await db.finished_good_serials.update_one(
                {"serial_number": serial_number},
                {"$set": {"status": "dead_stock", "updated_at": now.isoformat()}}
            )
        
        return {
            "message": "Marked as dead stock",
            "action": "mark_dead_stock",
            "tracking_id": tracking_id
        }
    
    else:
        raise HTTPException(status_code=400, detail=f"Invalid action: {action}")


@api_router.get("/bot/serial-info/{serial_number}")
async def bot_serial_info(
    serial_number: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get comprehensive information about a serial number"""
    
    serial = await db.finished_good_serials.find_one(
        {"serial_number": {"$regex": f"^{serial_number}$", "$options": "i"}},
        {"_id": 0}
    )
    
    if not serial:
        return {
            "found": False,
            "serial_number": serial_number,
            "message": "Serial number not found in system"
        }
    
    # Get related information
    master_sku = None
    if serial.get("master_sku_id"):
        master_sku = await db.master_skus.find_one({"id": serial["master_sku_id"]}, {"_id": 0})
    
    # Get dispatch info
    dispatch = await db.dispatches.find_one({"serial_number": serial_number}, {"_id": 0})
    
    # Get warranty info
    warranty = await db.warranties.find_one({"serial_number": serial_number}, {"_id": 0})
    
    # Get repair tickets
    tickets = await db.tickets.find(
        {"$or": [{"serial_number": serial_number}, {"board_serial_number": serial_number}]},
        {"_id": 0}
    ).sort("created_at", -1).to_list(10)
    
    # Determine missing fields
    missing_fields = []
    if not serial.get("manufacturing_date"):
        missing_fields.append("manufacturing_date")
    if not serial.get("batch_number"):
        missing_fields.append("batch_number")
    if not serial.get("master_sku_id"):
        missing_fields.append("master_sku_id")
    if serial.get("status") == "sold" and not dispatch:
        missing_fields.append("dispatch_info")
    if serial.get("status") == "sold" and not warranty:
        missing_fields.append("warranty_info")
    
    return {
        "found": True,
        "serial_number": serial_number,
        "serial_data": serial,
        "master_sku": master_sku,
        "dispatch_info": dispatch,
        "warranty_info": warranty,
        "repair_history": tickets,
        "status": serial.get("status"),
        "missing_fields": missing_fields,
        "has_missing_data": len(missing_fields) > 0,
        "actions": ["update_serial_info"] if missing_fields else []
    }


@api_router.post("/bot/update-serial")
async def bot_update_serial(
    serial_number: str = Form(...),
    field: str = Form(...),
    value: str = Form(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update a field on a serial number record"""
    
    serial = await db.finished_good_serials.find_one({"serial_number": serial_number})
    if not serial:
        raise HTTPException(status_code=404, detail="Serial number not found")
    
    allowed_fields = [
        "manufacturing_date", "batch_number", "master_sku_id", "firm_id",
        "condition", "notes", "customer_name", "customer_phone", "warranty_start", "warranty_end"
    ]
    
    if field not in allowed_fields:
        raise HTTPException(status_code=400, detail=f"Field '{field}' cannot be updated")
    
    update_data = {
        field: value,
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "updated_by": user["id"]
    }
    
    # If updating master_sku_id, also get the name
    if field == "master_sku_id":
        sku = await db.master_skus.find_one({"id": value}, {"_id": 0})
        if sku:
            update_data["master_sku_name"] = sku.get("name")
            update_data["sku_code"] = sku.get("sku_code")
    
    await db.finished_good_serials.update_one(
        {"serial_number": serial_number},
        {"$set": update_data}
    )
    
    return {
        "message": f"Serial {serial_number} updated: {field} = {value}",
        "serial_number": serial_number,
        "field": field,
        "value": value
    }


@api_router.post("/bot/update-order-field")
async def bot_update_order_field_v2(
    order_id: str = Form(...),
    source: str = Form(...),  # amazon_orders, pending_fulfillment, dispatches
    field: str = Form(...),
    value: str = Form(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update a field on any order type"""
    
    collection_map = {
        "amazon_orders": db.amazon_orders,
        "pending_fulfillment": db.pending_fulfillment,
        "dispatches": db.dispatches
    }
    
    if source not in collection_map:
        raise HTTPException(status_code=400, detail=f"Invalid source: {source}")
    
    collection = collection_map[source]
    
    # Find the order
    id_field = "amazon_order_id" if source == "amazon_orders" else "id"
    order = await collection.find_one({id_field: order_id})
    
    if not order:
        # Try alternate ID fields
        order = await collection.find_one({"order_id": order_id})
    
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    
    allowed_fields = [
        "customer_name", "customer_phone", "phone", "address", "city", "state", "pincode",
        "tracking_id", "courier", "master_sku_id", "serial_number", "invoice_value",
        "order_total", "amount", "payment_status", "notes"
    ]
    
    if field not in allowed_fields:
        raise HTTPException(status_code=400, detail=f"Field '{field}' cannot be updated")
    
    update_data = {
        field: value,
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    # If updating master_sku_id, also update related fields
    if field == "master_sku_id":
        sku = await db.master_skus.find_one({"id": value}, {"_id": 0})
        if sku:
            update_data["master_sku_name"] = sku.get("name")
            update_data["sku_code"] = sku.get("sku_code")
    
    await collection.update_one({id_field: order_id}, {"$set": update_data})
    
    return {
        "message": f"Order updated: {field} = {value}",
        "order_id": order_id,
        "source": source,
        "field": field,
        "value": value
    }


@api_router.get("/bot/master-skus")
async def bot_get_master_skus(
    search: Optional[str] = None,
    limit: int = 50,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get list of master SKUs for selection"""
    
    query = {}
    if search:
        query = {
            "$or": [
                {"name": {"$regex": search, "$options": "i"}},
                {"sku_code": {"$regex": search, "$options": "i"}}
            ]
        }
    
    skus = await db.master_skus.find(query, {"_id": 0, "id": 1, "name": 1, "sku_code": 1, "hsn_code": 1, "gst_rate": 1}).limit(limit).to_list(limit)
    
    return {"skus": skus, "count": len(skus)}


@api_router.get("/bot/search-items")
async def bot_search_items(
    item_type: str,
    search: Optional[str] = None,
    limit: int = 50,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Search items by type for purchase/adjustment flow.
    item_type: 'raw_material' (from raw_materials), 'traded_item' (from master_skus non-manufactured)
    """
    
    query = {}
    if search:
        query = {
            "$or": [
                {"name": {"$regex": search, "$options": "i"}},
                {"sku_code": {"$regex": search, "$options": "i"}},
                {"code": {"$regex": search, "$options": "i"}},  # raw_materials use 'code' field
                {"model_name": {"$regex": search, "$options": "i"}}
            ]
        }
    
    items = []
    
    if item_type == "traded_item":
        # Bug 2 Fix: Search master_skus for traded/finished goods (non-manufactured)
        # These are products you BUY from suppliers (not manufacture yourself)
        sku_query = dict(query) if query else {}
        sku_query["$and"] = sku_query.get("$and", [])
        if "$or" in sku_query:
            sku_query["$and"].append({"$or": sku_query.pop("$or")})
        sku_query["$and"].append({
            "$or": [
                {"is_manufactured": {"$ne": True}},
                {"is_manufactured": {"$exists": False}},
                {"product_type": "traded"},
                {"product_type": {"$exists": False}}
            ]
        })
        # Remove empty $and
        if not sku_query["$and"]:
            del sku_query["$and"]
        
        skus = await db.master_skus.find(sku_query, {"_id": 0}).limit(limit).to_list(limit)
        items = [{
            "id": s["id"], 
            "name": s.get("name"), 
            "sku_code": s.get("sku_code"),
            "hsn_code": s.get("hsn_code"),
            "gst_rate": s.get("gst_rate", 18),
            "type": "master_sku"  # Use master_sku as type for inventory ledger
        } for s in skus]
        
        # Also check traded_items collection as fallback
        if len(items) == 0:
            traded = await db.traded_items.find(query, {"_id": 0}).limit(limit).to_list(limit)
            items = [{
                "id": t["id"], 
                "name": t.get("name"), 
                "sku_code": t.get("sku_code"),
                "hsn_code": t.get("hsn_code"),
                "gst_rate": t.get("gst_rate", 18),
                "type": "traded_item"
            } for t in traded]
        
    elif item_type == "raw_material":
        # Search raw_materials collection
        raw = await db.raw_materials.find(query, {"_id": 0}).limit(limit).to_list(limit)
        items = [{
            "id": r["id"], 
            "name": r.get("name"), 
            "sku_code": r.get("code") or r.get("sku_code"),
            "hsn_code": r.get("hsn_code"),
            "gst_rate": r.get("gst_rate", 18),
            "type": "raw_material"
        } for r in raw]
        
    elif item_type == "master_sku":
        # Search all master_skus (for other flows)
        skus = await db.master_skus.find(query, {"_id": 0}).limit(limit).to_list(limit)
        items = [{
            "id": s["id"], 
            "name": s.get("name"), 
            "sku_code": s.get("sku_code"),
            "hsn_code": s.get("hsn_code"),
            "gst_rate": s.get("gst_rate", 18),
            "type": "master_sku"
        } for s in skus]
    
    return {"items": items, "count": len(items)}


# State name mapping for intelligent matching
STATE_MAPPINGS = {
    "up": "Uttar Pradesh", "uttar pradesh": "Uttar Pradesh", "uttarpradesh": "Uttar Pradesh",
    "mp": "Madhya Pradesh", "madhya pradesh": "Madhya Pradesh", "madhyapradesh": "Madhya Pradesh",
    "ap": "Andhra Pradesh", "andhra pradesh": "Andhra Pradesh", "andhrapradesh": "Andhra Pradesh",
    "ar": "Arunachal Pradesh", "arunachal pradesh": "Arunachal Pradesh",
    "as": "Assam", "assam": "Assam",
    "br": "Bihar", "bihar": "Bihar",
    "cg": "Chhattisgarh", "chattisgarh": "Chhattisgarh", "chhattisgarh": "Chhattisgarh",
    "ga": "Goa", "goa": "Goa",
    "gj": "Gujarat", "gujarat": "Gujarat",
    "hr": "Haryana", "haryana": "Haryana",
    "hp": "Himachal Pradesh", "himachal pradesh": "Himachal Pradesh", "himachal": "Himachal Pradesh",
    "jk": "Jammu and Kashmir", "jammu kashmir": "Jammu and Kashmir", "jammu and kashmir": "Jammu and Kashmir", "j&k": "Jammu and Kashmir",
    "jh": "Jharkhand", "jharkhand": "Jharkhand",
    "ka": "Karnataka", "karnataka": "Karnataka",
    "kl": "Kerala", "kerala": "Kerala",
    "la": "Ladakh", "ladakh": "Ladakh",
    "mh": "Maharashtra", "maharashtra": "Maharashtra",
    "mn": "Manipur", "manipur": "Manipur",
    "ml": "Meghalaya", "meghalaya": "Meghalaya",
    "mz": "Mizoram", "mizoram": "Mizoram",
    "nl": "Nagaland", "nagaland": "Nagaland",
    "or": "Odisha", "odisha": "Odisha", "orissa": "Odisha",
    "pb": "Punjab", "punjab": "Punjab",
    "rj": "Rajasthan", "rajasthan": "Rajasthan",
    "sk": "Sikkim", "sikkim": "Sikkim",
    "tn": "Tamil Nadu", "tamil nadu": "Tamil Nadu", "tamilnadu": "Tamil Nadu",
    "ts": "Telangana", "telangana": "Telangana",
    "tr": "Tripura", "tripura": "Tripura",
    "uk": "Uttarakhand", "uttarakhand": "Uttarakhand", "uttaranchal": "Uttarakhand",
    "wb": "West Bengal", "west bengal": "West Bengal", "westbengal": "West Bengal",
    "an": "Andaman and Nicobar Islands", "andaman": "Andaman and Nicobar Islands",
    "ch": "Chandigarh", "chandigarh": "Chandigarh",
    "dn": "Dadra and Nagar Haveli", "dadra": "Dadra and Nagar Haveli",
    "dd": "Daman and Diu", "daman": "Daman and Diu",
    "dl": "Delhi", "delhi": "Delhi", "new delhi": "Delhi",
    "ld": "Lakshadweep", "lakshadweep": "Lakshadweep",
    "py": "Puducherry", "puducherry": "Puducherry", "pondicherry": "Puducherry",
}

def normalize_state(state_input: str) -> dict:
    """Normalize state name - returns dict with normalized name and confidence"""
    if not state_input:
        return {"normalized": None, "confidence": "none", "suggestions": []}
    
    state_lower = state_input.lower().strip()
    
    # Exact match in mappings
    if state_lower in STATE_MAPPINGS:
        return {"normalized": STATE_MAPPINGS[state_lower], "confidence": "exact", "suggestions": []}
    
    # Partial match
    for key, value in STATE_MAPPINGS.items():
        if key in state_lower or state_lower in key:
            return {"normalized": value, "confidence": "partial", "suggestions": [value]}
    
    # Fuzzy suggestions
    suggestions = []
    for key, value in STATE_MAPPINGS.items():
        if state_lower[:2] == key[:2] or state_lower in value.lower():
            if value not in suggestions:
                suggestions.append(value)
    
    if suggestions:
        return {"normalized": None, "confidence": "suggest", "suggestions": suggestions[:3]}
    
    return {"normalized": None, "confidence": "unknown", "suggestions": []}


@api_router.post("/bot/normalize-state")
async def bot_normalize_state(
    state: str = Form(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Normalize state name from various inputs"""
    result = normalize_state(state)
    return result


@api_router.post("/bot/adjust-inventory")
async def bot_adjust_inventory(
    item_type: str = Form(...),  # traded_item, raw_material (manufactured items NOT allowed)
    item_id: str = Form(...),
    firm_id: str = Form(...),
    quantity_change: int = Form(...),  # positive or negative
    reason: str = Form(...),
    notes: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Adjust inventory quantity for traded items and raw materials only.
    Manufactured items cannot be adjusted - they require proper production/dispatch flow."""
    
    now = datetime.now(timezone.utc)
    
    # Get item details
    item_name = None
    sku_code = None
    
    if item_type == "master_sku":
        # Check if manufactured - manufactured items cannot be adjusted
        item = await db.master_skus.find_one({"id": item_id}, {"_id": 0})
        if item:
            is_manufactured = item.get("is_manufactured", False) or item.get("product_type") == "manufactured"
            if is_manufactured:
                raise HTTPException(
                    status_code=400, 
                    detail="Manufactured items cannot be adjusted. Use production/dispatch flow for manufactured goods with serial tracking."
                )
            item_name = item.get("name")
            sku_code = item.get("sku_code")
    elif item_type == "raw_material":
        item = await db.raw_materials.find_one({"id": item_id}, {"_id": 0})
        if item:
            item_name = item.get("name")
            sku_code = item.get("code")
    elif item_type == "traded_item":
        item = await db.traded_items.find_one({"id": item_id}, {"_id": 0})
        if item:
            item_name = item.get("name")
            sku_code = item.get("sku_code")
    else:
        raise HTTPException(status_code=400, detail="Invalid item type")
    
    if not item_name:
        raise HTTPException(status_code=404, detail="Item not found")
    
    # Get firm details
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    # Get current balance using the standard function
    current_balance = await get_current_stock(item_type, item_id, firm_id)
    
    # Determine entry type and quantity based on the change direction
    if quantity_change > 0:
        entry_type = "adjustment_in"
        quantity = quantity_change
        new_balance = current_balance + quantity_change
    else:
        entry_type = "adjustment_out"
        quantity = abs(quantity_change)
        new_balance = current_balance - quantity
        # Check for sufficient stock
        if new_balance < 0:
            raise HTTPException(
                status_code=400,
                detail=f"Insufficient stock. Current: {current_balance}, Requested reduction: {quantity}"
            )
    
    # Create ledger entry with proper format (matching LedgerEntryResponse model)
    ledger_entry = {
        "id": str(uuid.uuid4()),
        "entry_number": await generate_ledger_entry_number(),
        "entry_type": entry_type,
        "item_type": item_type,
        "item_id": item_id,
        "item_name": item_name,
        "item_sku": sku_code,
        "firm_id": firm_id,
        "firm_name": firm.get("name"),
        "quantity": quantity,
        "running_balance": new_balance,
        "reason": reason,
        "notes": notes or "Adjusted via Operations Bot",
        "created_by": user["id"],
        "created_by_name": f"{user['first_name']} {user['last_name']}",
        "created_at": now.isoformat()
    }
    
    await db.inventory_ledger.insert_one(ledger_entry)
    
    return {
        "message": f"Inventory adjusted: {item_name} {'+'if quantity_change > 0 else ''}{quantity_change}",
        "item_name": item_name,
        "previous_balance": current_balance,
        "new_balance": new_balance,
        "firm": firm.get("name")
    }


@api_router.get("/bot/check-stock")
async def bot_check_stock(
    item_type: str,
    item_id: str,
    firm_id: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Check current stock for an item at a specific firm, including available serials for manufactured items"""
    
    current_stock = 0
    serials = []
    is_manufactured = False
    
    if item_type == "master_sku":
        # Check if it's a manufactured item
        item = await db.master_skus.find_one({"id": item_id}, {"_id": 0})
        if item:
            is_manufactured = item.get("is_manufactured", False) or item.get("product_type") == "manufactured"
        
        if is_manufactured:
            # For manufactured items, check finished_good_serials
            serial_docs = await db.finished_good_serials.find({
                "master_sku_id": item_id,
                "firm_id": firm_id,
                "status": "in_stock"
            }, {"_id": 0, "serial_number": 1, "id": 1}).to_list(1000)
            
            serials = serial_docs
            current_stock = len(serial_docs)
        else:
            # For traded items, check inventory_ledger
            current_stock = await get_current_stock("master_sku", item_id, firm_id)
    
    elif item_type == "raw_material":
        current_stock = await get_current_stock("raw_material", item_id, firm_id)
    
    return {
        "current_stock": current_stock,
        "is_manufactured": is_manufactured,
        "serials": serials
    }


class TransferStockRequest(BaseModel):
    item_type: str  # master_sku, raw_material
    item_id: str
    from_firm_id: str
    to_firm_id: str
    quantity: int
    invoice_number: str
    is_manufactured: bool = False
    serial_numbers: List[str] = []
    notes: Optional[str] = None


@api_router.post("/bot/transfer-stock")
async def bot_transfer_stock(
    data: TransferStockRequest,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Transfer stock between firms with support for serial number tracking"""
    
    if data.quantity <= 0:
        raise HTTPException(status_code=400, detail="Quantity must be positive")
    
    if data.from_firm_id == data.to_firm_id:
        raise HTTPException(status_code=400, detail="From and To firm cannot be same")
    
    now = datetime.now(timezone.utc)
    
    # Get item details
    item_name = None
    sku_code = None
    is_manufactured = data.is_manufactured
    
    if data.item_type == "master_sku":
        item = await db.master_skus.find_one({"id": data.item_id}, {"_id": 0})
        if item:
            item_name = item.get("name")
            sku_code = item.get("sku_code")
            is_manufactured = is_manufactured or item.get("is_manufactured", False) or item.get("product_type") == "manufactured"
    elif data.item_type == "raw_material":
        item = await db.raw_materials.find_one({"id": data.item_id}, {"_id": 0})
        if item:
            item_name = item.get("name")
            sku_code = item.get("code")
    
    if not item_name:
        raise HTTPException(status_code=404, detail="Item not found")
    
    # Get firm details
    from_firm = await db.firms.find_one({"id": data.from_firm_id}, {"_id": 0})
    to_firm = await db.firms.find_one({"id": data.to_firm_id}, {"_id": 0})
    
    if not from_firm or not to_firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    # Validate stock availability
    if is_manufactured and data.serial_numbers:
        # Validate serials exist and are in stock at source firm
        for serial in data.serial_numbers:
            serial_doc = await db.finished_good_serials.find_one({
                "serial_number": serial,
                "master_sku_id": data.item_id,
                "firm_id": data.from_firm_id,
                "status": "in_stock"
            })
            if not serial_doc:
                raise HTTPException(
                    status_code=400, 
                    detail=f"Serial {serial} not found or not available at {from_firm.get('name')}"
                )
    else:
        # Validate quantity available
        current_stock = await get_current_stock(data.item_type, data.item_id, data.from_firm_id)
        if current_stock < data.quantity:
            raise HTTPException(
                status_code=400,
                detail=f"Insufficient stock. Available: {current_stock}, Requested: {data.quantity}"
            )
    
    # Create transfer record
    transfer_id = str(uuid.uuid4())
    transfer_number = f"TRF-{now.strftime('%Y%m%d')}-{str(uuid.uuid4())[:4].upper()}"
    
    transfer_doc = {
        "id": transfer_id,
        "transfer_number": transfer_number,
        "item_type": data.item_type,
        "item_id": data.item_id,
        "item_name": item_name,
        "sku_code": sku_code,
        "from_firm_id": data.from_firm_id,
        "from_firm_name": from_firm.get("name"),
        "to_firm_id": data.to_firm_id,
        "to_firm_name": to_firm.get("name"),
        "quantity": data.quantity,
        "is_manufactured": is_manufactured,
        "serial_numbers": data.serial_numbers if is_manufactured else [],
        "invoice_number": data.invoice_number,
        "notes": data.notes,
        "status": "completed",
        "created_by": user["id"],
        "created_by_name": f"{user['first_name']} {user['last_name']}",
        "created_at": now.isoformat()
    }
    
    await db.stock_transfers.insert_one(transfer_doc)
    
    # Handle serial number transfers for manufactured items
    if is_manufactured and data.serial_numbers:
        for serial in data.serial_numbers:
            # Update serial's firm_id
            await db.finished_good_serials.update_one(
                {"serial_number": serial, "master_sku_id": data.item_id},
                {"$set": {
                    "firm_id": data.to_firm_id,
                    "updated_at": now.isoformat(),
                    "transfer_history": {
                        "$push": {
                            "from_firm_id": data.from_firm_id,
                            "to_firm_id": data.to_firm_id,
                            "transfer_id": transfer_id,
                            "transfer_number": transfer_number,
                            "transferred_at": now.isoformat(),
                            "transferred_by": user["id"]
                        }
                    }
                }}
            )
        
        # Note: For manufactured items with serials, we don't update inventory_ledger
        # The serial tracking IS the inventory
    else:
        # Update inventory ledger for non-serial items
        # Deduct from source firm
        from_balance = await get_current_stock(data.item_type, data.item_id, data.from_firm_id)
        new_from_balance = from_balance - data.quantity
        
        await db.inventory_ledger.insert_one({
            "id": str(uuid.uuid4()),
            "entry_number": await generate_ledger_entry_number(),
            "entry_type": "transfer_out",
            "item_type": data.item_type,
            "item_id": data.item_id,
            "item_name": item_name,
            "item_sku": sku_code,
            "firm_id": data.from_firm_id,
            "firm_name": from_firm.get("name"),
            "quantity": data.quantity,
            "running_balance": new_from_balance,
            "reference_type": "transfer",
            "reference_id": transfer_id,
            "reference_number": transfer_number,
            "created_by": user["id"],
            "created_by_name": f"{user['first_name']} {user['last_name']}",
            "created_at": now.isoformat()
        })
        
        # Add to destination firm
        to_balance = await get_current_stock(data.item_type, data.item_id, data.to_firm_id)
        new_to_balance = to_balance + data.quantity
        
        await db.inventory_ledger.insert_one({
            "id": str(uuid.uuid4()),
            "entry_number": await generate_ledger_entry_number(),
            "entry_type": "transfer_in",
            "item_type": data.item_type,
            "item_id": data.item_id,
            "item_name": item_name,
            "item_sku": sku_code,
            "firm_id": data.to_firm_id,
            "firm_name": to_firm.get("name"),
            "quantity": data.quantity,
            "running_balance": new_to_balance,
            "reference_type": "transfer",
            "reference_id": transfer_id,
            "reference_number": transfer_number,
            "created_by": user["id"],
            "created_by_name": f"{user['first_name']} {user['last_name']}",
            "created_at": now.isoformat()
        })
    
    return {
        "message": "Stock transferred successfully",
        "transfer_number": transfer_number,
        "from_firm": from_firm.get("name"),
        "to_firm": to_firm.get("name"),
        "quantity": data.quantity,
        "invoice_number": data.invoice_number,
        "serials_transferred": len(data.serial_numbers) if is_manufactured else 0
    }


@api_router.post("/bot/record-expense")
async def bot_record_expense(
    firm_id: str = Form(...),
    expense_date: str = Form(...),
    category: str = Form(...),
    description: str = Form(...),
    amount: float = Form(...),
    payment_mode: str = Form(...),  # cash, bank, upi
    vendor_name: Optional[str] = Form(None),
    invoice_number: Optional[str] = Form(None),
    gst_applicable: bool = Form(False),
    gst_rate: Optional[float] = Form(None),  # 5, 12, 18, 28
    gst_amount: Optional[float] = Form(None),
    notes: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Record an expense with proper GST handling"""
    
    now = datetime.now(timezone.utc)
    
    # Get firm details
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0})
    if not firm:
        raise HTTPException(status_code=404, detail="Firm not found")
    
    expense_id = str(uuid.uuid4())
    expense_number = f"EXP-{now.strftime('%Y%m%d')}-{str(uuid.uuid4())[:4].upper()}"
    
    # Calculate GST if rate provided but amount not
    final_gst_amount = gst_amount
    if gst_applicable and gst_rate and not gst_amount:
        final_gst_amount = round(amount * gst_rate / 100, 2)
    
    total_amount = amount + (final_gst_amount or 0)
    
    expense_doc = {
        "id": expense_id,
        "expense_number": expense_number,
        "firm_id": firm_id,
        "firm_name": firm.get("name"),
        "expense_date": expense_date,
        "category": category,
        "description": description,
        "base_amount": amount,  # Base amount before GST
        "amount": total_amount,  # Total amount including GST (for display)
        "gst_applicable": gst_applicable,
        "gst_rate": gst_rate,
        "gst_amount": final_gst_amount or 0,
        "total_amount": total_amount,
        "payment_mode": payment_mode,
        "vendor_name": vendor_name,
        "invoice_number": invoice_number,
        "notes": notes,
        "status": "recorded",
        "created_by": user["id"],
        "created_by_name": f"{user['first_name']} {user['last_name']}",
        "created_at": now.isoformat()
    }
    
    await db.expenses.insert_one(expense_doc)
    
    return {
        "message": f"Expense recorded: ₹{total_amount:,.2f} for {category}",
        "expense_number": expense_number,
        "firm": firm.get("name"),
        "base_amount": amount,
        "gst_rate": gst_rate,
        "gst_amount": final_gst_amount or 0,
        "total_with_gst": total_amount
    }


@api_router.get("/bot/ticket-info/{query}")
async def bot_ticket_info(
    query: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get ticket info by ticket ID or customer phone"""
    
    # Search by ticket number or phone
    ticket = None
    tickets = []
    
    # Try ticket number first
    ticket = await db.tickets.find_one({
        "$or": [
            {"ticket_number": {"$regex": f"^{query}$", "$options": "i"}},
            {"id": query}
        ]
    }, {"_id": 0})
    
    if not ticket:
        # Try phone number
        if query.isdigit() and len(query) >= 10:
            tickets = await db.tickets.find(
                {"$or": [
                    {"customer_phone": {"$regex": query}},
                    {"phone": {"$regex": query}}
                ]},
                {"_id": 0}
            ).sort("created_at", -1).limit(10).to_list(10)
    
    if not ticket and not tickets:
        return {"found": False, "message": "No ticket found"}
    
    if ticket:
        tickets = [ticket]
    
    # Determine pending actions for each ticket
    results = []
    for t in tickets:
        pending_actions = []
        
        # Check for pending reverse pickup label
        if t.get("status") in ["pending_pickup", "approved"] and not t.get("reverse_label_url"):
            pending_actions.append("upload_reverse_label")
        
        # Check for pending spare dispatch
        if t.get("status") == "spare_required" and not t.get("spare_dispatched"):
            pending_actions.append("dispatch_spare")
        
        # Check for pending payment
        if t.get("payment_required") and not t.get("payment_received"):
            pending_actions.append("record_payment")
        
        results.append({
            "ticket_number": t.get("ticket_number"),
            "id": t.get("id"),
            "customer_name": t.get("customer_name"),
            "customer_phone": t.get("customer_phone") or t.get("phone"),
            "product": t.get("master_sku_name") or t.get("product_name"),
            "serial_number": t.get("serial_number") or t.get("board_serial_number"),
            "issue": t.get("issue_description") or t.get("complaint"),
            "status": t.get("status"),
            "created_at": t.get("created_at"),
            "pending_actions": pending_actions,
            "has_pending_actions": len(pending_actions) > 0
        })
    
    return {
        "found": True,
        "count": len(results),
        "tickets": results
    }


@api_router.post("/bot/ticket-action")
async def bot_ticket_action(
    ticket_id: str = Form(...),
    action: str = Form(...),  # upload_reverse_label, dispatch_spare, record_payment, update_status
    value: Optional[str] = Form(None),
    notes: Optional[str] = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Perform action on a ticket"""
    
    ticket = await db.tickets.find_one({"$or": [{"id": ticket_id}, {"ticket_number": ticket_id}]})
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    
    now = datetime.now(timezone.utc)
    update_data = {"updated_at": now.isoformat(), "updated_by": user["id"]}
    
    if action == "upload_reverse_label":
        if not value:
            raise HTTPException(status_code=400, detail="Reverse label URL required")
        update_data["reverse_label_url"] = value
        update_data["reverse_label_uploaded_at"] = now.isoformat()
        message = "Reverse pickup label uploaded"
    
    elif action == "dispatch_spare":
        update_data["spare_dispatched"] = True
        update_data["spare_dispatch_date"] = now.isoformat()
        update_data["spare_tracking_id"] = value
        message = f"Spare dispatched with tracking: {value}"
    
    elif action == "record_payment":
        update_data["payment_received"] = True
        update_data["payment_received_date"] = now.isoformat()
        update_data["payment_amount"] = float(value) if value else 0
        message = f"Payment recorded: ₹{value}"
    
    elif action == "update_status":
        if not value:
            raise HTTPException(status_code=400, detail="Status value required")
        update_data["status"] = value
        message = f"Status updated to: {value}"
    
    else:
        raise HTTPException(status_code=400, detail=f"Unknown action: {action}")
    
    if notes:
        update_data["action_notes"] = notes
    
    await db.tickets.update_one({"id": ticket.get("id")}, {"$set": update_data})
    
    return {
        "message": message,
        "ticket_number": ticket.get("ticket_number"),
        "action": action
    }


@api_router.get("/bot/dispatch-info/{query}")
async def bot_dispatch_info(
    query: str,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Get dispatch info by dispatch number or order ID"""
    
    dispatch = await db.dispatches.find_one({
        "$or": [
            {"dispatch_number": {"$regex": f"^{query}$", "$options": "i"}},
            {"order_id": {"$regex": f"^{query}$", "$options": "i"}},
            {"tracking_id": {"$regex": f"^{query}$", "$options": "i"}},
            {"id": query}
        ]
    }, {"_id": 0})
    
    if not dispatch:
        return {"found": False, "message": "Dispatch not found"}
    
    # Check for missing critical fields
    missing_fields = []
    if not dispatch.get("tracking_id"):
        missing_fields.append("tracking_id")
    if not dispatch.get("customer_name"):
        missing_fields.append("customer_name")
    if not dispatch.get("phone"):
        missing_fields.append("phone")
    if not dispatch.get("address"):
        missing_fields.append("address")
    if not dispatch.get("state"):
        missing_fields.append("state")
    if not dispatch.get("pincode"):
        missing_fields.append("pincode")
    if not dispatch.get("serial_number") and dispatch.get("master_sku_id"):
        # Check if SKU requires serial
        sku = await db.master_skus.find_one({"id": dispatch.get("master_sku_id")}, {"_id": 0})
        if sku and sku.get("product_type") == "manufactured":
            missing_fields.append("serial_number")
    if not dispatch.get("invoice_value"):
        missing_fields.append("invoice_value")
    
    return {
        "found": True,
        "dispatch": {
            "id": dispatch.get("id"),
            "dispatch_number": dispatch.get("dispatch_number"),
            "order_id": dispatch.get("order_id"),
            "status": dispatch.get("status"),
            "customer_name": dispatch.get("customer_name"),
            "phone": dispatch.get("phone"),
            "address": dispatch.get("address"),
            "city": dispatch.get("city"),
            "state": dispatch.get("state"),
            "pincode": dispatch.get("pincode"),
            "tracking_id": dispatch.get("tracking_id"),
            "courier": dispatch.get("courier"),
            "serial_number": dispatch.get("serial_number"),
            "master_sku_name": dispatch.get("master_sku_name"),
            "invoice_value": dispatch.get("invoice_value"),
            "created_at": dispatch.get("created_at")
        },
        "missing_fields": missing_fields,
        "has_missing_fields": len(missing_fields) > 0
    }


@api_router.post("/bot/update-dispatch")
async def bot_update_dispatch(
    dispatch_id: str = Form(...),
    field: str = Form(...),
    value: str = Form(...),
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update dispatch field"""
    
    dispatch = await db.dispatches.find_one({"$or": [{"id": dispatch_id}, {"dispatch_number": dispatch_id}]})
    if not dispatch:
        raise HTTPException(status_code=404, detail="Dispatch not found")
    
    allowed_fields = [
        "customer_name", "phone", "address", "city", "state", "pincode",
        "tracking_id", "courier", "serial_number", "invoice_value", "notes"
    ]
    
    if field not in allowed_fields:
        raise HTTPException(status_code=400, detail=f"Field '{field}' cannot be updated")
    
    # Normalize state if updating state field
    if field == "state":
        state_result = normalize_state(value)
        if state_result["normalized"]:
            value = state_result["normalized"]
    
    update_data = {
        field: value,
        "updated_at": datetime.now(timezone.utc).isoformat(),
        "updated_by": user["id"]
    }
    
    await db.dispatches.update_one({"id": dispatch.get("id")}, {"$set": update_data})
    
    return {
        "message": f"Dispatch updated: {field} = {value}",
        "dispatch_number": dispatch.get("dispatch_number"),
        "field": field,
        "value": value
    }


@api_router.post("/bot/update-tracking")
async def bot_update_tracking(
    order_id: str = Form(...),
    tracking_id: str = Form(...),
    courier_name: str = Form(None),
    label_url: str = Form(None),
    bigship_order_id: str = Form(None),
    user: dict = Depends(require_roles(["admin", "accountant", "dispatcher"]))
):
    """Update tracking ID, label URL, and Bigship order ID on pending_fulfillment or dispatch record"""
    
    update_data = {
        "tracking_id": tracking_id,
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    if courier_name:
        update_data["courier_name"] = courier_name
    if label_url:
        update_data["label_url"] = label_url
    if bigship_order_id:
        update_data["bigship_order_id"] = bigship_order_id
    
    # Try to find in pending_fulfillment first
    pending = await db.pending_fulfillment.find_one({"id": order_id})
    if pending:
        await db.pending_fulfillment.update_one(
            {"id": order_id},
            {"$set": update_data}
        )
        return {"success": True, "message": f"Tracking {tracking_id} and label saved to pending fulfillment"}
    
    # Try dispatches
    dispatch = await db.dispatches.find_one({"$or": [{"id": order_id}, {"pending_fulfillment_id": order_id}]})
    if dispatch:
        if not courier_name:
            update_data["courier"] = dispatch.get("courier")
        else:
            update_data["courier"] = courier_name
        await db.dispatches.update_one(
            {"id": dispatch["id"]},
            {"$set": update_data}
        )
        return {"success": True, "message": f"Tracking {tracking_id} and label saved to dispatch"}
    
    # Try amazon_orders
    amazon = await db.amazon_orders.find_one({"amazon_order_id": order_id})
    if amazon:
        await db.amazon_orders.update_one(
            {"amazon_order_id": order_id},
            {"$set": {
                "tracking_number": tracking_id,
                "courier_name": courier_name,
                "updated_at": datetime.now(timezone.utc).isoformat()
            }}
        )
        return {"success": True, "message": f"Tracking {tracking_id} saved to Amazon order"}
    
    raise HTTPException(status_code=404, detail="Order not found in pending_fulfillment, dispatches, or amazon_orders")


@api_router.post("/bot/update-customer-details")
async def bot_update_customer_details(
    request: Request,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update customer details on pending_fulfillment record"""
    data = await request.json()
    order_id = data.get("order_id")
    
    if not order_id:
        raise HTTPException(status_code=400, detail="order_id is required")
    
    update_data = {
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    if data.get("first_name"):
        update_data["customer_first_name"] = data["first_name"]
    if data.get("last_name"):
        update_data["customer_last_name"] = data["last_name"]
    if data.get("customer_name"):
        update_data["customer_name"] = data["customer_name"]
    if data.get("address"):
        update_data["address"] = data["address"]
        update_data["address_line1"] = data["address"]
    if data.get("phone"):
        update_data["phone"] = data["phone"]
        update_data["customer_phone"] = data["phone"]
    
    # Update pending_fulfillment
    result = await db.pending_fulfillment.update_one(
        {"id": order_id},
        {"$set": update_data}
    )
    
    if result.modified_count == 0:
        # Try by amazon_order_id
        result = await db.pending_fulfillment.update_one(
            {"amazon_order_id": order_id},
            {"$set": update_data}
        )
    
    if result.modified_count == 0:
        raise HTTPException(status_code=404, detail="Order not found")
    
    return {"success": True, "message": "Customer details updated"}


@api_router.post("/bot/update-pending-fulfillment")
async def bot_update_pending_fulfillment(
    request: Request,
    user: dict = Depends(require_roles(["admin", "accountant"]))
):
    """Update pending_fulfillment record with any field"""
    data = await request.json()
    order_id = data.get("order_id")
    
    if not order_id:
        raise HTTPException(status_code=400, detail="order_id is required")
    
    update_data = {
        "updated_at": datetime.now(timezone.utc).isoformat()
    }
    
    # Tracking and shipping fields
    if data.get("tracking_id"):
        update_data["tracking_id"] = data["tracking_id"]
        update_data["has_tracking"] = True
    if data.get("courier_name"):
        update_data["courier_name"] = data["courier_name"]
        update_data["carrier_name"] = data["courier_name"]
    if data.get("bigship_order_id"):
        update_data["bigship_order_id"] = data["bigship_order_id"]
    if data.get("shipping_label_url"):
        update_data["shipping_label_url"] = data["shipping_label_url"]
    
    # Customer information fields
    if data.get("customer_name"):
        update_data["customer_name"] = data["customer_name"]
    if data.get("customer_phone"):
        update_data["customer_phone"] = data["customer_phone"]
    if data.get("customer_address"):
        update_data["shipping_address"] = data["customer_address"]
    if data.get("city"):
        update_data["city"] = data["city"]
    if data.get("state"):
        update_data["state"] = data["state"]
    if data.get("pincode"):
        update_data["pincode"] = data["pincode"]
    
    # Invoice fields
    if data.get("invoice_value") is not None:
        update_data["invoice_value"] = float(data["invoice_value"])
    if data.get("invoice_number"):
        update_data["invoice_number"] = data["invoice_number"]
    
    # Master SKU linking
    if data.get("master_sku_id"):
        sku = await db.master_skus.find_one({"id": data["master_sku_id"]}, {"_id": 0})
        if sku:
            # Update items array with the new SKU
            update_data["items"] = [{
                "master_sku_id": sku["id"],
                "sku_code": sku.get("sku_code"),
                "master_sku_name": sku.get("name"),
                "quantity": data.get("quantity", 1)
            }]
            update_data["master_sku_id"] = sku["id"]
            update_data["sku_code"] = sku.get("sku_code")
            update_data["master_sku_name"] = sku.get("name")
    
    # Notes
    if data.get("notes"):
        update_data["notes"] = data["notes"]
    
    # E-way bill
    if data.get("eway_bill_number"):
        update_data["eway_bill_number"] = data["eway_bill_number"]
    
    # Update status if specified
    if data.get("status"):
        update_data["status"] = data["status"]
    
    # Update pending_fulfillment
    result = await db.pending_fulfillment.update_one(
        {"id": order_id},
        {"$set": update_data}
    )
    
    if result.modified_count == 0:
        # Try by amazon_order_id
        result = await db.pending_fulfillment.update_one(
            {"amazon_order_id": order_id},
            {"$set": update_data}
        )
    
    if result.modified_count == 0:
        raise HTTPException(status_code=404, detail="Order not found in pending fulfillment")
    
    # Get updated record
    updated = await db.pending_fulfillment.find_one(
        {"$or": [{"id": order_id}, {"amazon_order_id": order_id}]},
        {"_id": 0}
    )
    
    return {
        "success": True, 
        "message": "Pending fulfillment updated",
        "updated_fields": list(update_data.keys()),
        "order": updated
    }


