# Amazon Credentials per Firm
@api_router.post("/amazon/credentials")
async def save_amazon_credentials(
    data: AmazonCredentials,
    user: dict = Depends(require_roles(["admin"]))
):
    """Save Amazon API credentials for a firm - saves to BOTH collections for compatibility"""
    now = datetime.now(timezone.utc).isoformat()
    
    # Save to amazon_credentials collection
    existing = await db.amazon_credentials.find_one({"firm_id": data.firm_id})
    
    creds_doc = {
        "firm_id": data.firm_id,
        "seller_id": data.seller_id,
        "lwa_client_id": data.lwa_client_id,
        "lwa_client_secret": data.lwa_client_secret,
        "refresh_token": data.refresh_token,
        "aws_access_key": data.aws_access_key,
        "aws_secret_key": data.aws_secret_key,
        "marketplace_id": data.marketplace_id,
        "updated_at": now,
        "updated_by": user.get("id")
    }
    
    if existing:
        await db.amazon_credentials.update_one(
            {"firm_id": data.firm_id},
            {"$set": creds_doc}
        )
    else:
        creds_doc["id"] = str(uuid.uuid4())
        creds_doc["created_at"] = now
        await db.amazon_credentials.insert_one(creds_doc)
    
    # Also save to marketplace_credentials for backwards compatibility
    # Create a clean doc without _id to avoid upsert conflicts
    marketplace_doc = {
        "firm_id": data.firm_id,
        "seller_id": data.seller_id,
        "lwa_client_id": data.lwa_client_id,
        "lwa_client_secret": data.lwa_client_secret,
        "refresh_token": data.refresh_token,
        "aws_access_key": data.aws_access_key,
        "aws_secret_key": data.aws_secret_key,
        "marketplace_id": data.marketplace_id,
        "platform": "amazon",
        "is_active": True,
        "updated_at": now,
        "updated_by": user.get("id")
    }
    await db.marketplace_credentials.update_one(
        {"firm_id": data.firm_id, "platform": "amazon"},
        {"$set": marketplace_doc},
        upsert=True
    )
    
    return {"success": True, "message": "Amazon credentials saved"}

@api_router.get("/amazon/credentials/{firm_id}")
async def get_amazon_credentials(
    firm_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Get Amazon credentials for a firm (masked) - checks both collections"""
    # Check marketplace_credentials first (new collection)
    creds = await db.marketplace_credentials.find_one(
        {"firm_id": firm_id, "platform": "amazon"}, 
        {"_id": 0}
    )
    
    # Fallback to amazon_credentials (legacy)
    if not creds:
        creds = await db.amazon_credentials.find_one({"firm_id": firm_id}, {"_id": 0})
    
    if not creds:
        return {"has_credentials": False, "configured": False}
    
    return {
        "has_credentials": True,
        "configured": True,
        "seller_id": creds.get("seller_id"),
        "marketplace_id": creds.get("marketplace_id", "A21TJRUUN4KGV"),
        "lwa_client_id": (creds.get("lwa_client_id", "")[:20] + "...") if creds.get("lwa_client_id") else "",
        "is_active": creds.get("is_active", True),
        "created_at": creds.get("created_at"),
        "updated_at": creds.get("updated_at")
    }

@api_router.get("/amazon/firms-with-credentials")
async def list_firms_with_amazon_credentials(
    user: dict = Depends(require_roles(["admin"]))
):
    """List all firms that have Amazon credentials configured"""
    # Support both is_active and active fields for backwards compatibility
    firms = await db.firms.find(
        {"$or": [{"is_active": True}, {"active": True}, {"is_active": {"$exists": False}}]}, 
        {"_id": 0, "id": 1, "name": 1}
    ).to_list(100)
    
    result = []
    for firm in firms:
        # Check both collections
        creds = await db.marketplace_credentials.find_one({"firm_id": firm["id"], "platform": "amazon"})
        if not creds:
            creds = await db.amazon_credentials.find_one({"firm_id": firm["id"]})
        
        result.append({
            "id": firm["id"],
            "name": firm["name"],
            "has_amazon_credentials": bool(creds)
        })
    
    return {"firms": result}

# Helper function to sanitize brand names - replace ARB with MG
def sanitize_brand_text(text: str) -> str:
    """Replace ARB brand references with MG for white-labeling"""
    if not text:
        return text
    # Replace various case combinations
    result = text.replace("ARB", "MG").replace("arb", "mg").replace("Arb", "Mg")
    result = result.replace("ARB Accessories", "MG Accessories").replace("arb accessories", "mg accessories")
    result = result.replace("ARB ACCESSORIES", "MG ACCESSORIES")
    return result

# Website Scraping for Product Import
@api_router.post("/catalogue/scrape-product")
async def scrape_product_from_website(
    url: str = Form(...),
    user: dict = Depends(require_roles(["admin"]))
):
    """Scrape a single product from website"""
    import re
    from bs4 import BeautifulSoup
    
    try:
        response = requests.get(url, timeout=30, headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
        })
        response.raise_for_status()
        
        soup = BeautifulSoup(response.content, 'html.parser')
        
        # Extract product name
        name = ""
        name_elem = soup.select_one('h1.product_title, h1.entry-title, .product-title h1')
        if name_elem:
            name = name_elem.get_text(strip=True)
        
        # Extract price
        price = 0
        price_elem = soup.select_one('.price .woocommerce-Price-amount, .price ins .amount, .product-price')
        if price_elem:
            price_text = price_elem.get_text(strip=True)
            price_match = re.search(r'[\d,]+(?:\.\d+)?', price_text.replace(',', ''))
            if price_match:
                price = float(price_match.group())
        
        # Extract description
        description = ""
        desc_elem = soup.select_one('.woocommerce-product-details__short-description, .product-description, #tab-description')
        if desc_elem:
            description = desc_elem.get_text(strip=True)[:2000]
        
        # Extract images
        images = []
        # Try gallery images first
        gallery_imgs = soup.select('.woocommerce-product-gallery__image img, .product-gallery img, .product-images img')
        for img in gallery_imgs:
            src = img.get('data-large_image') or img.get('data-src') or img.get('src')
            if src and src.startswith('http') and src not in images:
                images.append(src)
        
        # Try main product image
        if not images:
            main_img = soup.select_one('.wp-post-image, .product-image img')
            if main_img:
                src = main_img.get('src')
                if src:
                    images.append(src)
        
        # Extract specifications
        specifications = {}
        spec_rows = soup.select('.woocommerce-product-attributes tr, .product-attributes tr, table.shop_attributes tr')
        for row in spec_rows:
            label = row.select_one('th, .label')
            value = row.select_one('td, .value')
            if label and value:
                key = label.get_text(strip=True).lower().replace(' ', '_')
                specifications[key] = value.get_text(strip=True)
        
        # Extract SKU
        sku = ""
        sku_elem = soup.select_one('.sku, .product_meta .sku')
        if sku_elem:
            sku = sku_elem.get_text(strip=True)
        
        # Extract category
        category = "accessories"
        cat_elem = soup.select_one('.posted_in a, .product-category a')
        if cat_elem:
            cat_text = cat_elem.get_text(strip=True).lower()
            if 'battery' in cat_text or 'batteries' in cat_text:
                category = 'battery'
            elif 'inverter' in cat_text:
                category = 'inverter'
            elif 'stabilizer' in cat_text:
                category = 'stabilizer'
        
        return {
            "success": True,
            "product": {
                "name": sanitize_brand_text(name),
                "price": price,
                "description": sanitize_brand_text(description),
                "images": images[:5],  # Max 5 images
                "specifications": {k: sanitize_brand_text(str(v)) for k, v in specifications.items()},
                "sku": sku,
                "category": category,
                "source_url": url
            }
        }
        
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to scrape product: {str(e)}")

