@api_router.post("/catalogue/reprocess-images/{datasheet_id}")
async def reprocess_datasheet_images(
    datasheet_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Re-process images for an existing datasheet - remove backgrounds using AI"""
    import base64
    import uuid
    
    # Get the datasheet
    datasheet = await db.product_datasheets.find_one({"id": datasheet_id})
    if not datasheet:
        raise HTTPException(status_code=404, detail="Datasheet not found")
    
    # Get original images (prefer original_images if available, else use images)
    original_images = datasheet.get("original_images") or datasheet.get("images") or []
    if not original_images:
        raise HTTPException(status_code=400, detail="No images found to process")
    
    # Get OpenAI API key from environment
    openai_api_key = os.environ.get('OPENAI_API_KEY')
    if not openai_api_key:
        raise HTTPException(status_code=500, detail="OpenAI API key not configured. Please add OPENAI_API_KEY to backend .env")
    
    enhanced_images = []
    enhanced_image_url = ""
    
    try:
        for idx, img_url in enumerate(original_images[:5]):  # Process max 5 images
            try:
                # Download original image
                img_response = requests.get(img_url, timeout=30)
                if img_response.status_code != 200:
                    continue
                
                img_data = img_response.content
                
                # Use raw OpenAI API for gpt-image-1 edit (background removal)
                edit_response = requests.post(
                    'https://api.openai.com/v1/images/edits',
                    headers={'Authorization': f'Bearer {openai_api_key}'},
                    files={
                        'image': ('image.png', img_data, 'image/png'),
                        'prompt': (None, 'Remove the background completely and replace with solid pure white background (#FFFFFF). Keep only the product, no shadows, no reflections. Professional product photo style.'),
                        'model': (None, 'gpt-image-1'),
                        'size': (None, '1024x1024'),
                    },
                    timeout=120
                )
                
                if edit_response.status_code == 200:
                    edit_data = edit_response.json()
                    if edit_data.get('data') and len(edit_data['data']) > 0:
                        # Get base64 image data
                        b64_image = edit_data['data'][0].get('b64_json')
                        if b64_image:
                            # Decode and save to file
                            img_bytes = base64.b64decode(b64_image)
                            filename = f"enhanced_{datasheet_id}_{idx}_{uuid.uuid4().hex[:8]}.png"
                            filepath = f"/app/frontend/public/uploads/{filename}"
                            
                            # Ensure uploads directory exists
                            os.makedirs("/app/frontend/public/uploads", exist_ok=True)
                            
                            with open(filepath, 'wb') as f:
                                f.write(img_bytes)
                            
                            # Create URL for the enhanced image
                            enhanced_url = f"/uploads/{filename}"
                            enhanced_images.append(enhanced_url)
                            
                            if not enhanced_image_url:
                                enhanced_image_url = enhanced_url
                else:
                    error_detail = edit_response.json() if edit_response.content else {}
                    print(f"OpenAI edit failed for image {idx}: {error_detail}")
                    
            except Exception as e:
                print(f"Failed to enhance image {idx + 1}: {str(e)}")
                continue
        
        if not enhanced_images:
            raise HTTPException(status_code=500, detail="Failed to process any images. Check OpenAI API key and try again.")
        
        # Update datasheet with enhanced images
        update_data = {
            "enhanced_images": enhanced_images,
            "enhanced_image": enhanced_image_url,
            "images": enhanced_images,  # Replace main images with enhanced ones
            "image_url": enhanced_image_url,  # Update primary image
            "updated_at": datetime.now(timezone.utc).isoformat()
        }
        
        # Keep original images for reference
        if not datasheet.get("original_images"):
            update_data["original_images"] = original_images
        
        await db.product_datasheets.update_one(
            {"id": datasheet_id},
            {"$set": update_data}
        )
        
        return {
            "success": True,
            "message": f"Successfully enhanced {len(enhanced_images)} images",
            "enhanced_count": len(enhanced_images),
            "enhanced_images": enhanced_images,
            "enhanced_image": enhanced_image_url
        }
        
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Image reprocessing failed: {str(e)}")

# Scrape Single Product URL (Generic)
@api_router.post("/catalogue/scrape-product-url")
async def scrape_single_product_url(
    product_url: str = Form(...),
    user: dict = Depends(require_roles(["admin"]))
):
    """Scrape a single product from any e-commerce website"""
    from bs4 import BeautifulSoup
    import re
    
    try:
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8"
        }
        
        response = requests.get(product_url, timeout=30, headers=headers)
        if response.status_code != 200:
            raise HTTPException(status_code=400, detail="Failed to fetch product page")
        
        soup = BeautifulSoup(response.content, 'html.parser')
        
        # Extract name
        name = None
        name_selectors = [
            'h1.product_title', 'h1.entry-title', '.product-title h1',
            'h1[data-product-title]', '.product-name h1', 'h1.product-single__title',
            'meta[property="og:title"]', 'title', 'h1'
        ]
        for sel in name_selectors:
            elem = soup.select_one(sel)
            if elem:
                if elem.name == 'meta':
                    name = elem.get('content', '')[:200]
                elif elem.name == 'title':
                    name = elem.get_text(strip=True).split('|')[0].split('-')[0].strip()[:200]
                else:
                    name = elem.get_text(strip=True)[:200]
                if name and len(name) > 3:
                    break
        
        if not name:
            name = "Product from " + product_url[:50]
        
        # Extract price
        price = 0
        price_selectors = [
            '.product-price-regular',  # StoreLink
            '.price .woocommerce-Price-amount bdi', '.price ins .amount',
            '.product-price', '[data-product-price]', '.price__current',
            '.product-single__price', '.price', 'span[data-price]',
            'meta[property="product:price:amount"]'
        ]
        for sel in price_selectors:
            elem = soup.select_one(sel)
            if elem:
                if elem.name == 'meta':
                    try:
                        price = float(elem.get('content', 0))
                    except:
                        pass
                else:
                    price_text = elem.get_text(strip=True)
                    # Look for price after ₹ symbol
                    price_match = re.search(r'₹\s*([\d,]+)', price_text)
                    if price_match:
                        try:
                            price = float(price_match.group(1).replace(',', ''))
                        except:
                            pass
                    else:
                        # Fallback: look for large numbers
                        price_match = re.search(r'([\d,]{4,})', price_text)
                        if price_match:
                            try:
                                price = float(price_match.group(1).replace(',', ''))
                            except:
                                pass
                if price > 0:
                    break
        
        # Extract images - get ALL gallery images from StoreLink
        images = []
        # Try gallery thumbnails first - these contain all product images
        for i in range(10):  # Check up to 10 thumbnails
            thumb = soup.select_one(f'#image-gallery-thumbnail-{i} img')
            if thumb:
                src = thumb.get('src', '')
                if src and src.startswith('http') and src not in images:
                    images.append(src)
            else:
                break  # No more thumbnails
        
        # Also try main gallery panel images
        for img in soup.select('#image-gallery-panels img'):
            src = img.get('src', '')
            if src and src.startswith('http') and src not in images:
                images.append(src)
        
        # Try og:image as fallback only if no gallery images found
        if not images:
            og_img = soup.select_one('meta[property="og:image"]')
            if og_img and og_img.get('content'):
                images.append(og_img.get('content'))
        
        img_selectors = [
            '.woocommerce-product-gallery__image img', '.product-gallery img',
            '.product-images img', '.product-single__photo img',
            '[data-product-featured-image]', '.product-main-image img'
        ]
        for sel in img_selectors:
            for img in soup.select(sel)[:5]:
                src = img.get('data-large_image') or img.get('data-src') or img.get('data-zoom') or img.get('src')
                if src and src.startswith('http') and src not in images:
                    if 'icon' not in src.lower() and 'logo' not in src.lower():
                        images.append(src)
        
        # Extract description - get FULL content from StoreLink product page
        description = ""
        full_html_description = ""
        
        # StoreLink specific: description is in #custom-page-content or #product-description
        desc_elem = soup.select_one('#custom-page-content, #product-description')
        if desc_elem:
            # Get the HTML for rich formatting
            full_html_description = str(desc_elem)
            # Get plain text version
            description = desc_elem.get_text(strip=True)[:2000]  # Allow longer description
        
        # Fallback to other selectors
        if not description:
            desc_selectors = [
                '.woocommerce-product-details__short-description', '#tab-description',
                '.product-description', '[data-product-description]',
                '.product-single__description', 'meta[name="description"]',
                'meta[property="og:description"]'
            ]
            for sel in desc_selectors:
                elem = soup.select_one(sel)
                if elem:
                    if elem.name == 'meta':
                        description = elem.get('content', '')[:2000]
                    else:
                        description = elem.get_text(strip=True)[:2000]
                    if description:
                        break
        
        # Extract specifications from description tables or lists
        specifications = {}
        spec_tables = soup.select('table')
        for table in spec_tables:
            rows = table.select('tr')
            for row in rows:
                cells = row.select('td, th')
                if len(cells) >= 2:
                    key = cells[0].get_text(strip=True)
                    value = cells[1].get_text(strip=True)
                    if key and value and len(key) < 50:
                        specifications[key] = value
        
        # Also try to extract specs from list items
        spec_lists = soup.select('ul li')
        for li in spec_lists[:20]:  # Limit to first 20
            text = li.get_text(strip=True)
            if ':' in text:
                parts = text.split(':', 1)
                if len(parts) == 2 and len(parts[0]) < 50:
                    specifications[parts[0].strip()] = parts[1].strip()
        
        return {
            "success": True,
            "product": {
                "name": sanitize_brand_text(name),
                "price": price,
                "images": images[:10],  # Allow up to 10 images
                "description": sanitize_brand_text(description),
                "html_description": sanitize_brand_text(full_html_description[:5000]) if full_html_description else "",
                "specifications": {k: sanitize_brand_text(str(v)) for k, v in specifications.items()} if specifications else {},
                "source_url": product_url
            }
        }
        
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to scrape product: {str(e)}")

# AI Bullet Point Generation
@api_router.post("/catalogue/generate-bullets")
async def generate_bullet_points(
    product_name: str = Form(...),
    description: str = Form(""),
    specifications: str = Form("{}"),
    user: dict = Depends(require_roles(["admin"]))
):
    """Generate Amazon-optimized bullet points using AI"""
    import json as json_module
    from emergentintegrations.llm.chat import LlmChat, UserMessage
    
    emergent_key = os.environ.get('EMERGENT_LLM_KEY', 'sk-emergent-2C8Cb2b5cA89e50D33')
    
    try:
        specs = json_module.loads(specifications) if specifications else {}
        
        chat = LlmChat(
            api_key=emergent_key,
            session_id=f"bullet-gen-{uuid.uuid4()}",
            system_message="You are an expert Amazon product copywriter. Generate compelling, SEO-optimized bullet points."
        ).with_model("openai", "gpt-5.2")
        
        prompt = f"""Create 5 Amazon bullet points for this product:

Product: {product_name}
Description: {description}
Specifications: {json_module.dumps(specs)}

Rules:
- Each bullet max 500 characters
- Start with CAPITALIZED benefit/feature keywords
- Include relevant search keywords naturally
- Focus on benefits, not just features
- Be specific with numbers/specs when available

Return ONLY a JSON array of 5 strings, no other text."""
        
        response = await chat.send_message(UserMessage(text=prompt))
        
        # Parse response
        import re
        json_match = re.search(r'\[[\s\S]*\]', response)
        if json_match:
            bullets = json_module.loads(json_match.group())
            return {"success": True, "bullet_points": bullets[:5]}
        
        raise HTTPException(status_code=500, detail="Failed to parse AI response")
        
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Bullet generation failed: {str(e)}")

# AI Amazon Content Generator - Title, Description, Bullet Points
@api_router.post("/catalogue/generate-amazon-content")
async def generate_amazon_content(
    product_name: str = Form(...),
    description: str = Form(""),
    specifications: str = Form("{}"),
    user: dict = Depends(require_roles(["admin"]))
):
    """Generate Amazon-optimized title, description, and bullet points using AI"""
    import json as json_module
    from emergentintegrations.llm.chat import LlmChat, UserMessage
    
    emergent_key = os.environ.get('EMERGENT_LLM_KEY', 'sk-emergent-2C8Cb2b5cA89e50D33')
    
    try:
        specs = json_module.loads(specifications) if specifications else {}
        
        chat = LlmChat(
            api_key=emergent_key,
            session_id=f"amazon-content-{uuid.uuid4()}",
            system_message="""You are an expert Amazon product listing copywriter. 
Generate compelling, SEO-optimized content that converts browsers into buyers.
Follow Amazon's style guidelines: professional, benefit-focused, keyword-rich."""
        ).with_model("openai", "gpt-5.2")
        
        prompt = f"""Create Amazon-optimized listing content for this product:

Product: {product_name}

Original Description: {description[:1500]}

Specifications: {json_module.dumps(specs, indent=2) if specs else 'Not provided'}

Generate the following in JSON format:
{{
    "amazon_title": "Optimized title under 200 chars, includes brand, key features, size/model",
    "amazon_description": "Compelling product description, 3-4 paragraphs, benefit-focused, SEO optimized",
    "bullet_points": ["5 bullet points highlighting key benefits and features"],
    "search_keywords": ["10 relevant search keywords"]
}}

Rules:
1. Title: Brand + Product Type + Key Feature + Model/Size (under 200 chars)
2. Description: Start with benefits, include use cases, mention quality
3. Bullets: Start with CAPITAL feature name, then benefit
4. Keywords: Mix of short and long-tail keywords

Return ONLY valid JSON, no markdown."""

        response = await chat.chat([UserMessage(text=prompt)])
        
        # Parse JSON response
        try:
            # Clean up response
            content = response.text.strip()
            if content.startswith('```'):
                content = content.split('```')[1]
                if content.startswith('json'):
                    content = content[4:]
            content = content.strip()
            
            result = json_module.loads(content)
            return {
                "success": True,
                "amazon_title": result.get("amazon_title", product_name),
                "amazon_description": result.get("amazon_description", description[:500]),
                "bullet_points": result.get("bullet_points", []),
                "search_keywords": result.get("search_keywords", [])
            }
        except json_module.JSONDecodeError:
            return {
                "success": True,
                "amazon_title": product_name,
                "amazon_description": description[:500],
                "bullet_points": [],
                "search_keywords": [],
                "raw_response": response.text
            }
        
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Amazon content generation failed: {str(e)}")

# Import Product to Catalogue
@api_router.post("/catalogue/import-product")
async def import_product_to_catalogue(
    name: str = Form(...),
    price: float = Form(...),
    description: str = Form(""),
    images: str = Form("[]"),  # JSON array
    specifications: str = Form("{}"),
    category: str = Form("accessories"),
    source_url: str = Form(""),
    bullet_points: str = Form("[]"),
    mrp_markup: float = Form(500.0),  # MRP = price + 500%
    margin_percent: float = Form(70.0),  # Selling = (price + 70%) + 18%
    gst_percent: float = Form(18.0),
    enhance_images: bool = Form(True),  # Auto-enhance images using AI
    user: dict = Depends(require_roles(["admin"]))
):
    """Import a scraped product to the catalogue with pricing calculations and AI image enhancement"""
    import json as json_module
    import base64
    
    now = datetime.now(timezone.utc).isoformat()
    
    # Parse JSON fields
    images_list = json_module.loads(images) if images else []
    specs_dict = json_module.loads(specifications) if specifications else {}
    bullets_list = json_module.loads(bullet_points) if bullet_points else []
    
    # AI Image Enhancement - Remove background and make it white
    # Uses OpenAI GPT-image-1 edit endpoint for actual image editing (not regeneration)
    enhanced_images = []
    enhanced_image_url = ""
    original_images = images_list.copy()
    
    if enhance_images and images_list:
        try:
            import base64
            
            # Get OpenAI API key - first try user's key, then fall back to env
            openai_key = os.environ.get('OPENAI_API_KEY', '')
            
            if not openai_key:
                print("No OpenAI API key found. Skipping image enhancement.")
            else:
                os.makedirs("/app/backend/uploads", exist_ok=True)
                backend_url = os.environ.get("REACT_APP_BACKEND_URL", "")
                
                # Process each image (up to 5) - background removal only
                for idx, original_url in enumerate(images_list[:5]):
                    try:
                        # Download original image
                        img_response = requests.get(original_url, timeout=30)
                        if img_response.status_code != 200:
                            continue
                        
                        # Use raw OpenAI API for gpt-image-1 edit
                        headers = {
                            "Authorization": f"Bearer {openai_key}"
                        }
                        
                        files = {
                            'model': (None, 'gpt-image-1'),
                            'image': ('image.png', img_response.content, 'image/png'),
                            'prompt': (None, 'Remove the background completely and replace with solid white (#FFFFFF). Keep the product exactly the same - do not modify the product itself.'),
                            'size': (None, '1024x1024')
                        }
                        
                        api_response = requests.post(
                            "https://api.openai.com/v1/images/edits",
                            headers=headers,
                            files=files,
                            timeout=120
                        )
                        
                        if api_response.status_code == 200:
                            data = api_response.json()
                            if 'data' in data and data['data']:
                                image_data = None
                                
                                if 'b64_json' in data['data'][0]:
                                    image_data = base64.b64decode(data['data'][0]['b64_json'])
                                elif 'url' in data['data'][0]:
                                    img_download = requests.get(data['data'][0]['url'], timeout=30)
                                    image_data = img_download.content
                                
                                if image_data:
                                    # Save to uploads folder
                                    filename = f"enhanced_{uuid.uuid4()}.png"
                                    upload_path = f"/app/backend/uploads/{filename}"
                                    
                                    with open(upload_path, 'wb') as f:
                                        f.write(image_data)
                                    
                                    # Create URL for the enhanced image
                                    if backend_url:
                                        enhanced_url = f"{backend_url}/api/uploads/{filename}"
                                    else:
                                        enhanced_url = f"/api/uploads/{filename}"
                                    
                                    enhanced_images.append(enhanced_url)
                                    
                                    if idx == 0:
                                        enhanced_image_url = enhanced_url
                        else:
                            print(f"API error for image {idx + 1}: {api_response.status_code} - {api_response.text[:200]}")
                            
                    except Exception as e:
                        print(f"Failed to enhance image {idx + 1}: {str(e)}")
                        continue
                
                # Replace images list with enhanced versions if any were successful
                if enhanced_images:
                    images_list = enhanced_images
                
        except Exception as e:
            print(f"Image enhancement failed: {str(e)}")
            import traceback
            traceback.print_exc()
            pass
    
    # Calculate prices
    # MRP = Website price + 500%
    mrp = price + (price * mrp_markup / 100)
    
    # Selling Price = (Website price + 70%) + 18% GST
    price_with_margin = price + (price * margin_percent / 100)
    selling_price = price_with_margin + (price_with_margin * gst_percent / 100)
    
    # Sanitize brand names - replace ARB with MG
    sanitized_name = sanitize_brand_text(name)
    sanitized_description = sanitize_brand_text(description) if description else ""
    sanitized_specs = {k: sanitize_brand_text(str(v)) for k, v in specs_dict.items()} if specs_dict else {}
    sanitized_bullets = [sanitize_brand_text(b) for b in bullets_list] if bullets_list else []
    
    # Create datasheet
    datasheet_doc = {
        "id": str(uuid.uuid4()),
        "category": category,
        "model_name": sanitized_name,
        "subtitle": sanitized_description[:500] if sanitized_description else "",  # Short description
        "full_description": sanitized_description,  # Full description from website
        "image_url": images_list[0] if images_list else "",
        "images": images_list,  # All enhanced images (or original if enhancement failed)
        "original_images": original_images,  # Keep original scraped images
        "enhanced_images": enhanced_images if enhanced_images else [],  # List of all AI-enhanced images
        "enhanced_image": enhanced_image_url if enhanced_image_url else "",  # First AI-enhanced image for Amazon
        "specifications": sanitized_specs,
        "features": sanitized_bullets,
        "warranty": "1 Year Warranty",
        "certifications": ["ISO 9001"],
        "source_url": source_url,
        "amazon_fields": {
            "website_price": price,
            "mrp": round(mrp),
            "selling_price": round(selling_price),
            "mrp_markup_percent": mrp_markup,
            "margin_percent": margin_percent,
            "gst_percent": gst_percent,
            "hsn_code": "85044090",  # Default for electronics
            "product_tax_code": "A_GEN_STANDARD",
            "weight_kg": 5,
            "length_cm": 10,
            "width_cm": 10,
            "height_cm": 10,
            "country_of_origin": "CN",
            "brand": "MuscleGrid",
            "bullet_points": bullets_list,
            "amazon_title": "",  # To be generated via AI
            "amazon_description": "",  # To be generated via AI
            "search_keywords": [],  # To be generated via AI
            "amazon_sku": "",
            "amazon_asin": "",
            "amazon_status": "not_listed"
        },
        "created_at": now,
        "updated_at": now,
        "created_by": user.get("id")
    }
    
    await db.product_datasheets.insert_one(datasheet_doc)
    datasheet_doc.pop("_id", None)
    
    return {
        "success": True,
        "datasheet": datasheet_doc,
        "pricing": {
            "website_price": price,
            "mrp": round(mrp),
            "selling_price": round(selling_price)
        },
        "image_enhanced": bool(enhanced_image_url),
        "enhanced_image_url": enhanced_image_url
    }

# AI Generate Amazon Content
@api_router.post("/catalogue/generate-amazon-content/{datasheet_id}")
async def generate_amazon_content_ai(
    datasheet_id: str,
    user: dict = Depends(require_roles(["admin"]))
):
    """Use AI to generate Amazon-optimized title, description, and bullet points"""
    from emergentintegrations.llm.chat import LlmChat, UserMessage
    
    # Get datasheet
    datasheet = await db.product_datasheets.find_one({"id": datasheet_id}, {"_id": 0})
    if not datasheet:
        raise HTTPException(status_code=404, detail="Datasheet not found")
    
    # Get LLM key
    llm_key = os.environ.get("EMERGENT_LLM_KEY") or os.environ.get("OPENAI_API_KEY")
    if not llm_key:
        raise HTTPException(status_code=400, detail="AI key not configured")
    
    # Build product context from datasheet
    product_name = datasheet.get("model_name", "")
    category = datasheet.get("category", "accessories")
    description = datasheet.get("description", "") or datasheet.get("subtitle", "")
    specs = datasheet.get("specs", {})
    features = datasheet.get("features", [])
    
    # Build specs string
    specs_text = ""
    if isinstance(specs, dict):
        specs_text = "\n".join([f"- {k}: {v}" for k, v in specs.items() if v])
    elif isinstance(specs, list):
        specs_text = "\n".join([f"- {s}" for s in specs if s])
    
    features_text = "\n".join([f"- {f}" for f in features[:10] if f])
    
    prompt = f"""You are an expert Amazon product listing specialist for MuscleGrid, a premium Indian brand specializing in batteries, solar equipment, and electrical accessories.

Generate Amazon-optimized content for this product:

**Product Name:** {product_name}
**Category:** {category}
**Description:** {description}
**Specifications:**
{specs_text}
**Features:**
{features_text}

Generate the following in JSON format:
{{
    "title": "Amazon SEO-optimized title (max 200 chars) - must include brand 'MuscleGrid' at the start, key specs, and search-friendly keywords",
    "description": "Compelling product description (500-1500 chars) highlighting benefits, use cases, and quality assurance. Use HTML <br> for line breaks.",
    "bullet_points": ["5 benefit-focused bullet points (each 100-250 chars) highlighting features, specs, applications, and warranty"],
    "search_terms": "Backend search keywords (comma-separated, max 250 chars total)"
}}

Rules:
1. Brand must be "MuscleGrid" at the start of title
2. Title should include: Brand + Key Feature + Product Type + Important Specs
3. Bullet points should start with CAPITAL letters and focus on BENEFITS not just features
4. Description should be engaging and highlight why this product is best
5. Include relevant keywords for Amazon search
6. Use technical specs where relevant (voltage, capacity, etc.)
7. Keep language professional but accessible
8. DO NOT include pricing or promotional language
9. Return ONLY valid JSON, no markdown

Return ONLY the JSON object, nothing else."""

    try:
        chat = LlmChat(
            api_key=llm_key,
            session_id=f"amazon-content-{datasheet_id}",
            system_message="You are an expert Amazon product listing specialist. Always return valid JSON only."
        ).with_model("openai", "gpt-4o-mini")
        
        user_message = UserMessage(text=prompt)
        response = await chat.send_message(user_message)
        
        # Parse JSON from response
        response_text = response.strip()
        # Remove markdown code blocks if present
        if response_text.startswith("```"):
            response_text = response_text.split("```")[1]
            if response_text.startswith("json"):
                response_text = response_text[4:]
        response_text = response_text.strip()
        
        ai_content = json.loads(response_text)
        
        # Validate and clean content
        amazon_title = ai_content.get("title", product_name)[:200]
        amazon_description = ai_content.get("description", description)[:2000]
        amazon_bullets = ai_content.get("bullet_points", features)[:5]
        amazon_bullets = [b[:500] for b in amazon_bullets if b]
        search_terms = ai_content.get("search_terms", "")[:250]
        
        # Ensure brand is MuscleGrid
        if not amazon_title.lower().startswith("musclegrid"):
            amazon_title = f"MuscleGrid {amazon_title}"[:200]
        
        # Update datasheet with AI-generated content
        update_data = {
            "amazon_fields.ai_generated": True,
            "amazon_fields.amazon_title": amazon_title,
            "amazon_fields.amazon_description": amazon_description,
            "amazon_fields.bullet_points": amazon_bullets,
            "amazon_fields.search_terms": search_terms,
            "amazon_fields.brand": "MuscleGrid",
            "amazon_fields.ai_generated_at": datetime.now(timezone.utc).isoformat(),
            "updated_at": datetime.now(timezone.utc).isoformat()
        }
        
        await db.product_datasheets.update_one(
            {"id": datasheet_id},
            {"$set": update_data}
        )
        
        return {
            "success": True,
            "title": amazon_title,
            "description": amazon_description,
            "bullet_points": amazon_bullets,
            "search_terms": search_terms,
            "brand": "MuscleGrid"
        }
        
    except json.JSONDecodeError as e:
        raise HTTPException(status_code=500, detail=f"Failed to parse AI response: {str(e)}")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"AI content generation failed: {str(e)}")


# Push Product to Amazon
@api_router.post("/catalogue/push-to-amazon/{datasheet_id}")
async def push_product_to_amazon(
    datasheet_id: str,
    firm_id: str = Form(...),
    user: dict = Depends(require_roles(["admin"]))
):
    """Push a catalogue product to Amazon"""
    import hashlib
    import hmac
    from urllib.parse import quote
    
    # Get datasheet
    datasheet = await db.product_datasheets.find_one({"id": datasheet_id}, {"_id": 0})
    if not datasheet:
        raise HTTPException(status_code=404, detail="Datasheet not found")
    
    # Get Amazon credentials for firm - check both collections
    creds = await db.amazon_credentials.find_one({"firm_id": firm_id}, {"_id": 0})
    if not creds:
        # Try marketplace_credentials (legacy)
        creds = await db.marketplace_credentials.find_one({"firm_id": firm_id, "platform": "amazon"}, {"_id": 0})
    if not creds:
        raise HTTPException(status_code=400, detail="Amazon credentials not configured for this firm")
    
    # Get firm info
    firm = await db.firms.find_one({"id": firm_id}, {"_id": 0})
    
    # Amazon SP-API setup
    def get_access_token():
        response = requests.post(
            "https://api.amazon.com/auth/o2/token",
            headers={"Content-Type": "application/x-www-form-urlencoded;charset=UTF-8"},
            data={
                "grant_type": "refresh_token",
                "client_id": creds["lwa_client_id"],
                "client_secret": creds["lwa_client_secret"],
                "refresh_token": creds["refresh_token"]
            }
        )
        return response.json().get("access_token")
    
    def sign(key, msg):
        return hmac.new(key, msg.encode('utf-8'), hashlib.sha256).digest()
    
    def get_signature_key(key, date_stamp, region, service):
        k_date = sign(('AWS4' + key).encode('utf-8'), date_stamp)
        k_region = sign(k_date, region)
        k_service = sign(k_region, service)
        return sign(k_service, 'aws4_request')
    
    def make_sp_api_request(method, path, params=None, body=None, access_token=None):
        t = datetime.now(timezone.utc)
        amz_date = t.strftime('%Y%m%dT%H%M%SZ')
        date_stamp = t.strftime('%Y%m%d')
        
        host = "sellingpartnerapi-eu.amazon.com"
        region = "eu-west-1"
        service = 'execute-api'
        
        canonical_querystring = '&'.join([f"{quote(k, safe='~')}={quote(str(v), safe='~')}" for k, v in sorted(params.items())]) if params else ''
        payload = json.dumps(body) if body else ''
        
        canonical_headers = f'host:{host}\nx-amz-access-token:{access_token}\nx-amz-date:{amz_date}\n'
        signed_headers = 'host;x-amz-access-token;x-amz-date'
        payload_hash = hashlib.sha256(payload.encode('utf-8')).hexdigest()
        canonical_request = f'{method}\n{path}\n{canonical_querystring}\n{canonical_headers}\n{signed_headers}\n{payload_hash}'
        
        algorithm = 'AWS4-HMAC-SHA256'
        credential_scope = f'{date_stamp}/{region}/{service}/aws4_request'
        string_to_sign = f'{algorithm}\n{amz_date}\n{credential_scope}\n{hashlib.sha256(canonical_request.encode("utf-8")).hexdigest()}'
        
        signing_key = get_signature_key(creds["aws_secret_key"], date_stamp, region, service)
        signature = hmac.new(signing_key, string_to_sign.encode('utf-8'), hashlib.sha256).hexdigest()
        
        authorization_header = f'{algorithm} Credential={creds["aws_access_key"]}/{credential_scope}, SignedHeaders={signed_headers}, Signature={signature}'
        
        headers = {
            'host': host,
            'x-amz-access-token': access_token,
            'x-amz-date': amz_date,
            'Authorization': authorization_header,
            'Content-Type': 'application/json'
        }
        
        url = f'https://{host}{path}{"?" + canonical_querystring if canonical_querystring else ""}'
        return requests.request(method, url, headers=headers, data=payload if payload else None)
    
    try:
        access_token = get_access_token()
        if not access_token:
            raise HTTPException(status_code=400, detail="Failed to get Amazon access token")
        
        amazon_fields = datasheet.get("amazon_fields", {})
        
        # Auto-generate AI content if not already generated
        if not amazon_fields.get("ai_generated"):
            try:
                from emergentintegrations.llm.chat import LlmChat, UserMessage
                
                llm_key = os.environ.get("EMERGENT_LLM_KEY") or os.environ.get("OPENAI_API_KEY")
                if llm_key:
                    # Build product context
                    product_name = datasheet.get("model_name", "")
                    category = datasheet.get("category", "accessories")
                    description = datasheet.get("description", "") or datasheet.get("subtitle", "")
                    specs = datasheet.get("specs", {})
                    features = datasheet.get("features", [])
                    
                    specs_text = ""
                    if isinstance(specs, dict):
                        specs_text = "\n".join([f"- {k}: {v}" for k, v in specs.items() if v])
                    elif isinstance(specs, list):
                        specs_text = "\n".join([f"- {s}" for s in specs if s])
                    
                    features_text = "\n".join([f"- {f}" for f in features[:10] if f])
                    
                    prompt = f"""Generate Amazon-optimized content for MuscleGrid product:
Product: {product_name}
Category: {category}
Description: {description[:500]}
Specs: {specs_text[:500]}
Features: {features_text[:500]}

Return JSON only:
{{"title": "MuscleGrid + optimized title (max 200 chars)", "description": "Compelling description (500-1500 chars)", "bullet_points": ["5 benefit-focused bullets (100-250 chars each)"], "search_terms": "keywords, comma-separated"}}

Rules: Brand must start with MuscleGrid. Title should have key specs. Bullets start with CAPITALS focusing on BENEFITS. Return ONLY JSON."""

                    chat = LlmChat(
                        api_key=llm_key,
                        session_id=f"amazon-push-{datasheet_id}",
                        system_message="You are an Amazon listing expert. Return only valid JSON."
                    ).with_model("openai", "gpt-4o-mini")
                    
                    response = await chat.send_message(UserMessage(text=prompt))
                    response_text = response.strip()
                    if response_text.startswith("```"):
                        response_text = response_text.split("```")[1]
                        if response_text.startswith("json"):
                            response_text = response_text[4:]
                    response_text = response_text.strip()
                    
                    ai_content = json.loads(response_text)
                    
                    # Update amazon_fields with AI content
                    amazon_fields["ai_generated"] = True
                    amazon_fields["amazon_title"] = ai_content.get("title", product_name)[:200]
                    amazon_fields["amazon_description"] = ai_content.get("description", description)[:2000]
                    amazon_fields["bullet_points"] = [b[:500] for b in ai_content.get("bullet_points", features)[:5] if b]
                    amazon_fields["search_terms"] = ai_content.get("search_terms", "")[:250]
                    amazon_fields["brand"] = "MuscleGrid"
                    
                    # Ensure brand at start of title
                    if not amazon_fields["amazon_title"].lower().startswith("musclegrid"):
                        amazon_fields["amazon_title"] = f"MuscleGrid {amazon_fields['amazon_title']}"[:200]
                    
                    # Save AI content to database
                    await db.product_datasheets.update_one(
                        {"id": datasheet_id},
                        {"$set": {
                            "amazon_fields": amazon_fields,
                            "updated_at": datetime.now(timezone.utc).isoformat()
                        }}
                    )
            except Exception as ai_err:
                print(f"AI content generation warning: {ai_err}")
                # Continue without AI - use existing data
        
        # Generate SKU if not already set
        sku = amazon_fields.get("amazon_sku") or f"MG-{datasheet['category'].upper()[:3]}-{str(uuid.uuid4())[:8].upper()}"
        
        # Determine product type based on category
        product_type_map = {
            "accessories": "SOLDERING_STATION",
            "battery": "BATTERY",
            "inverter": "POWER_INVERTER",
            "stabilizer": "VOLTAGE_CONVERTER"
        }
        product_type = product_type_map.get(datasheet.get("category", "accessories"), "SOLDERING_STATION")
        
        # Build listing payload with AI-generated content
        marketplace_id = creds.get("marketplace_id", "A21TJRUUN4KGV")
        brand = amazon_fields.get("brand", "MuscleGrid")
        
        # Use AI-generated title or fallback to model_name
        item_title = amazon_fields.get("amazon_title") or datasheet["model_name"]
        if not item_title.lower().startswith("musclegrid"):
            item_title = f"MuscleGrid {item_title}"
        item_title = item_title[:200]
        
        # Use AI-generated description or fallback
        item_description = amazon_fields.get("amazon_description") or datasheet.get("subtitle", "") or datasheet.get("description", "")
        item_description = item_description[:2000]
        
        # Use AI-generated bullet points or fallback to features
        bullet_points = amazon_fields.get("bullet_points") or datasheet.get("features", [])
        bullet_points = [bp[:500] for bp in bullet_points[:5] if bp]
        
        # Ensure we have at least 3 bullet points
        while len(bullet_points) < 3:
            bullet_points.append(f"{brand} quality product with premium build and reliable performance")
        
        listing_payload = {
            "productType": product_type,
            "requirements": "LISTING",
            "attributes": {
                "item_name": [{
                    "value": item_title,
                    "language_tag": "en_IN",
                    "marketplace_id": marketplace_id
                }],
                "brand": [{"value": brand, "language_tag": "en_IN"}],
                "bullet_point": [
                    {"value": bp, "language_tag": "en_IN"} 
                    for bp in bullet_points
                ],
                "product_description": [{
                    "value": item_description,
                    "language_tag": "en_IN"
                }],
                "country_of_origin": [{"value": amazon_fields.get("country_of_origin", "CN")}],
                "supplier_declared_dg_hz_regulation": [{"value": "not_applicable"}],
                "supplier_declared_has_product_identifier_exemption": [{"value": True}],
                "main_product_image_locator": [{"media_location": datasheet.get("image_url", "")}],
                "unit_count": [{"value": 1, "unit": "count"}],
                "number_of_items": [{"value": 1}],
                "manufacturer": [{"value": brand}],
                "importer_contact_information": [{"value": f"{firm.get('name', 'MuscleGrid')}, India. support@musclegrid.in"}],
                "packer_contact_information": [{"value": f"{firm.get('name', 'MuscleGrid')}, India. support@musclegrid.in"}],
                "rtip_manufacturer_contact_information": [{"value": f"{firm.get('name', 'MuscleGrid')}, India. support@musclegrid.in"}],
                "batteries_required": [{"value": False}],
                "warranty_description": [{"value": datasheet.get("warranty", "1 Year Warranty"), "language_tag": "en_IN"}],
                "item_type_name": [{"value": product_type.lower()}],
                "item_package_dimensions": [{
                    "length": {"value": amazon_fields.get("length_cm", 10), "unit": "centimeters"},
                    "width": {"value": amazon_fields.get("width_cm", 10), "unit": "centimeters"},
                    "height": {"value": amazon_fields.get("height_cm", 10), "unit": "centimeters"}
                }],
                "item_depth_width_height": [{
                    "depth": {"value": amazon_fields.get("length_cm", 10), "unit": "centimeters"},
                    "width": {"value": amazon_fields.get("width_cm", 10), "unit": "centimeters"},
                    "height": {"value": amazon_fields.get("height_cm", 10), "unit": "centimeters"}
                }],
                "item_weight": [{"value": amazon_fields.get("weight_kg", 5), "unit": "kilograms"}],
                "item_package_weight": [{"value": amazon_fields.get("weight_kg", 5), "unit": "kilograms"}],
                "external_product_information": [{"entity": "HSN Code", "value": amazon_fields.get("hsn_code", "85044090")}]
            }
        }
        
        # Add model_name if product type requires it
        if product_type in ["SOLDERING_STATION"]:
            listing_payload["attributes"]["model_name"] = [{"value": datasheet["model_name"][:50]}]
            listing_payload["attributes"]["power_source_type"] = [{"value": "ac"}]
            listing_payload["attributes"]["included_components"] = [{"value": "Main Unit, User Manual", "language_tag": "en_IN"}]
        
        # Add additional images
        images = datasheet.get("images", [])
        for i, img in enumerate(images[1:4], 1):  # Up to 3 additional images
            listing_payload["attributes"][f"other_product_image_locator_{i}"] = [{"media_location": img}]
        
        # Submit to Amazon
        response = make_sp_api_request(
            'PUT',
            f'/listings/2021-08-01/items/{creds["seller_id"]}/{sku}',
            params={'marketplaceIds': marketplace_id},
            body=listing_payload,
            access_token=access_token
        )
        
        result = response.json()
        
        # Update datasheet with Amazon info
        update_data = {
            "amazon_fields.amazon_sku": sku,
            "amazon_fields.amazon_submission_id": result.get("submissionId"),
            "amazon_fields.amazon_status": result.get("status", "unknown").lower(),
            "amazon_fields.amazon_last_push": datetime.now(timezone.utc).isoformat(),
            "updated_at": datetime.now(timezone.utc).isoformat()
        }
        
        if result.get("status") == "ACCEPTED":
            update_data["amazon_fields.amazon_status"] = "pending_review"
        elif result.get("status") == "INVALID":
            update_data["amazon_fields.amazon_errors"] = [
                {"field": i.get("attributeNames", ["?"])[0], "message": i.get("message", "")}
                for i in result.get("issues", [])
            ]
        
        await db.product_datasheets.update_one(
            {"id": datasheet_id},
            {"$set": update_data}
        )
        
        return {
            "success": result.get("status") == "ACCEPTED",
            "status": result.get("status"),
            "submission_id": result.get("submissionId"),
            "sku": sku,
            "issues": result.get("issues", []),
            "pricing": {
                "mrp": amazon_fields.get("mrp"),
                "selling_price": amazon_fields.get("selling_price")
            }
        }
        
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Amazon push failed: {str(e)}")

# Bulk Scrape from Website
@api_router.post("/catalogue/scrape-website")
async def scrape_all_products_from_website(
    base_url: str = Form(...),  # e.g., https://example.com
    category_url: str = Form(None),  # Optional specific category URL
    max_products: int = Form(50),
    user: dict = Depends(require_roles(["admin"]))
):
    """Scrape all products from an e-commerce website (supports multiple platforms including StoreLink)"""
    from bs4 import BeautifulSoup
    import re
    
    products = []
    
    try:
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.5"
        }
        
        # Detect platform and set appropriate URLs
        url = category_url or base_url
        
        # First, try to detect StoreLink websites (they use vite-plugin-ssr)
        response = requests.get(url, timeout=30, headers=headers)
        if response.status_code == 200:
            soup = BeautifulSoup(response.content, 'html.parser')
            

            # Check for StoreLink JSON data
            script_tag = soup.find('script', {'id': 'vite-plugin-ssr_pageContext'})
            if script_tag:
                # This is a StoreLink website - use concurrent scraper for speed
                import aiohttp
                import asyncio
                
                # First, find all product links on the page
                page_product_links = soup.select('a[href*="/product/"]')
                unique_links = set()
                for link in page_product_links:
                    href = link.get('href', '')
                    if href and '/product/' in href:
                        if href.startswith('/'):
                            href = f"{base_url.rstrip('/')}{href}"
                        unique_links.add(href)
                
                # Get ALL category links
                all_category_links = soup.select('a[href*="/category/"]')
                category_urls_set = set()
                for cat_link in all_category_links:
                    cat_href = cat_link.get('href', '')
                    if cat_href and '/category/' in cat_href:
                        if cat_href.startswith('/'):
                            cat_href = f"{base_url.rstrip('/')}{cat_href}"
                        category_urls_set.add(cat_href)
                
                # Async function to fetch product links from a category
                async def fetch_category_links(session, cat_url):
                    links = set()
                    try:
                        async with session.get(cat_url, timeout=aiohttp.ClientTimeout(total=15)) as resp:
                            if resp.status == 200:
                                html = await resp.text()
                                cat_soup = BeautifulSoup(html, 'html.parser')
                                for plink in cat_soup.select('a[href*="/product/"]'):
                                    href = plink.get('href', '')
                                    if href and '/product/' in href:
                                        if href.startswith('/'):
                                            href = f"{base_url.rstrip('/')}{href}"
                                        links.add(href)
                    except:
                        pass
                    return links
                
                # Async function to fetch product details
                async def fetch_product(session, link):
                    try:
                        async with session.get(link, timeout=aiohttp.ClientTimeout(total=15)) as resp:
                            if resp.status != 200:
                                return None
                            html = await resp.text()
                            prod_soup = BeautifulSoup(html, 'html.parser')
                            
                            # Extract name
                            name_elem = prod_soup.select_one('#product-name, h1.product-name, h1')
                            name = name_elem.get_text(strip=True) if name_elem else ""
                            if not name:
                                return None
                            
                            # Extract price
                            price = 0
                            price_elem = prod_soup.select_one('.product-price-regular, [id*="product-price"] p')
                            if price_elem:
                                price_text = price_elem.get_text(strip=True)
                                price_match = re.search(r'₹\s*([\d,]+)', price_text)
                                if price_match:
                                    try:
                                        price = float(price_match.group(1).replace(',', ''))
                                    except:
                                        pass
                            
                            # Extract images
                            images = []
                            for i in range(10):
                                thumb = prod_soup.select_one(f'#image-gallery-thumbnail-{i} img')
                                if thumb:
                                    src = thumb.get('src', '')
                                    if src and src.startswith('http'):
                                        images.append(src)
                                else:
                                    break
                            if not images:
                                og_img = prod_soup.select_one('meta[property="og:image"]')
                                if og_img and og_img.get('content'):
                                    images.append(og_img.get('content'))
                            
                            # Extract description
                            description = ""
                            desc_elem = prod_soup.select_one('#product-description, #custom-page-content')
                            if desc_elem:
                                description = desc_elem.get_text(strip=True)[:500]
                            
                            if name and (price > 0 or images):
                                return {
                                    "name": sanitize_brand_text(name),
                                    "price": price,
                                    "images": images[:5],
                                    "description": sanitize_brand_text(description),
                                    "source_url": link
                                }
                    except:
                        pass
                    return None
                
                # Main async scraping logic
                async def scrape_all():
                    nonlocal unique_links
                    connector = aiohttp.TCPConnector(limit=10)  # Limit concurrent connections
                    async with aiohttp.ClientSession(headers=headers, connector=connector) as session:
                        # First, fetch all categories concurrently
                        cat_tasks = [fetch_category_links(session, cat_url) for cat_url in list(category_urls_set)[:40]]
                        cat_results = await asyncio.gather(*cat_tasks)
                        for links in cat_results:
                            unique_links.update(links)
                        
                        # Now fetch product details concurrently in batches
                        product_links_list = list(unique_links)[:max_products]
                        batch_size = 15
                        all_products = []
                        
                        for i in range(0, len(product_links_list), batch_size):
                            batch = product_links_list[i:i+batch_size]
                            tasks = [fetch_product(session, link) for link in batch]
                            results = await asyncio.gather(*tasks)
                            for p in results:
                                if p:
                                    all_products.append(p)
                        
                        return all_products
                
                products = await scrape_all()
                
                if products:
                    return {
                        "success": True,
                        "products_found": len(products),
                        "products": products,
                        "platform": "storelink"
                    }
        
        
        # Fall back to generic scraper for WooCommerce/Shopify
        page = 1
        
        # Common selectors for different platforms
        product_selectors = [
            # WooCommerce
            'a.woocommerce-LoopProduct-link',
            '.product a.woocommerce-loop-product__link',
            '.products li.product a',
            # Shopify
            '.product-card a',
            '.product-item a',
            '[data-product-card] a',
            '.product-grid-item a',
            # Generic
            '.product a[href*="/product"]',
            '.product-item a[href*="/product"]',
            'article.product a',
            '.product-card-link',
            # StoreLink style
            '[data-product] a',
            '.item-card a'
        ]
        
        while len(products) < max_products and page <= 10:
            # Try different pagination patterns
            if page > 1:
                page_urls = [
                    f"{url}?page={page}",
                    f"{url}/page/{page}",
                    f"{url}?paged={page}"
                ]
            else:
                page_urls = [url]
                # Also try common shop pages
                if '/shop' not in url.lower() and '/products' not in url.lower():
                    page_urls.extend([
                        f"{base_url}/shop",
                        f"{base_url}/products",
                        f"{base_url}/collections/all"
                    ])
            
            found_links = set()
            
            for page_url in page_urls:
                try:
                    response = requests.get(page_url, timeout=30, headers=headers)
                    if response.status_code != 200:
                        continue
                    
                    soup = BeautifulSoup(response.content, 'html.parser')
                    
                    # Try all product selectors
                    for selector in product_selectors:
                        links = soup.select(selector)
                        for link in links:
                            href = link.get('href', '')
                            if not href:
                                continue
                            # Make absolute URL
                            if href.startswith('/'):
                                href = f"{base_url.rstrip('/')}{href}"
                            elif not href.startswith('http'):
                                continue
                            # Check if it looks like a product URL
                            if any(x in href.lower() for x in ['/product/', '/products/', '/item/', '/p/']):
                                found_links.add(href)
                    
                    if found_links:
                        break  # Found products, no need to try other page URLs
                        
                except Exception as e:
                    continue
            
            if not found_links:
                break
            
            # Scrape individual products
            for link in list(found_links)[:max_products - len(products)]:
                try:
                    prod_response = requests.get(link, timeout=30, headers=headers)
                    if prod_response.status_code != 200:
                        continue
                        
                    prod_soup = BeautifulSoup(prod_response.content, 'html.parser')
                    
                    # Extract name (try multiple selectors)
                    name = None
                    name_selectors = [
                        'h1.product_title', 'h1.entry-title', '.product-title h1',
                        'h1[data-product-title]', '.product-name h1', 'h1.product-single__title',
                        'h1', '.product-info h1'
                    ]
                    for sel in name_selectors:
                        elem = prod_soup.select_one(sel)
                        if elem:
                            name = elem.get_text(strip=True)[:200]
                            if name and len(name) > 3:
                                break
                    
                    if not name:
                        continue
                    
                    # Extract price
                    price = 0
                    price_selectors = [
                        '.price .woocommerce-Price-amount bdi',
                        '.price ins .amount',
                        '.product-price',
                        '[data-product-price]',
                        '.price__current',
                        '.product-single__price',
                        '.price',
                        'span[data-price]'
                    ]
                    for sel in price_selectors:
                        elem = prod_soup.select_one(sel)
                        if elem:
                            price_text = elem.get_text(strip=True)
                            # Extract number from price text
                            price_match = re.search(r'[\d,]+(?:\.\d+)?', price_text.replace(',', ''))
                            if price_match:
                                try:
                                    price = float(price_match.group().replace(',', ''))
                                    if price > 0:
                                        break
                                except:
                                    pass
                    
                    # Extract images
                    images = []
                    img_selectors = [
                        '.woocommerce-product-gallery__image img',
                        '.product-gallery img',
                        '.product-images img',
                        '.product-single__photo img',
                        '[data-product-featured-image]',
                        '.product-main-image img',
                        '.product img'
                    ]
                    for sel in img_selectors:
                        for img in prod_soup.select(sel)[:5]:
                            src = img.get('data-large_image') or img.get('data-src') or img.get('data-zoom') or img.get('src')
                            if src and src.startswith('http') and src not in images:
                                # Skip tiny/icon images
                                if 'icon' not in src.lower() and 'logo' not in src.lower():
                                    images.append(src)
                    
                    # Also try og:image meta tag
                    og_img = prod_soup.select_one('meta[property="og:image"]')
                    if og_img and og_img.get('content'):
                        img_url = og_img.get('content')
                        if img_url not in images:
                            images.insert(0, img_url)
                    
                    # Extract description
                    description = ""
                    desc_selectors = [
                        '.woocommerce-product-details__short-description',
                        '#tab-description',
                        '.product-description',
                        '[data-product-description]',
                        '.product-single__description',
                        'meta[name="description"]'
                    ]
                    for sel in desc_selectors:
                        elem = prod_soup.select_one(sel)
                        if elem:
                            if elem.name == 'meta':
                                description = elem.get('content', '')[:500]
                            else:
                                description = elem.get_text(strip=True)[:500]
                            if description:
                                break
                    
                    products.append({
                        "name": name,
                        "price": price,
                        "images": images[:5],
                        "description": description,
                        "source_url": link
                    })
                    
                except Exception as e:
                    continue
            
            page += 1
            
            # If we found products on this iteration, continue; otherwise break
            if len(products) == 0:
                break
        
        return {
            "success": True,
            "products_found": len(products),
            "products": products
        }
        
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Website scraping failed: {str(e)}")


