@api_router.post("/omnidim/leads")
async def omnidim_create_lead(
    lead_data: LeadCreate,
    _: bool = Depends(verify_omnidim_api_key)
):
    """
    Omnidim Voice Agent API: Create a sales lead from voice call.
    
    Headers Required:
    - X-API-Key: Your Omnidim API key
    
    JSON Body:
    - phone: Customer phone number (required)
    - name: Customer name (optional)
    - product_interest: Product they're interested in (optional)
    - notes: Call notes (optional)
    """
    phone = str(lead_data.phone)
    
    # Normalize phone
    clean_phone = phone.strip().replace(" ", "").replace("-", "")
    if clean_phone.startswith("+91"):
        clean_phone = clean_phone[3:]
    elif clean_phone.startswith("91") and len(clean_phone) > 10:
        clean_phone = clean_phone[2:]
    
    # Check for existing lead with same phone (avoid duplicates)
    phone_variants = [clean_phone, f"+91{clean_phone}", f"91{clean_phone}", phone]
    existing_lead = await db.leads.find_one(
        {"phone": {"$in": phone_variants}, "status": {"$nin": ["converted", "lost"]}},
        {"_id": 0}
    )
    
    if existing_lead:
        # Update existing lead with new interaction
        await db.leads.update_one(
            {"id": existing_lead["id"]},
            {
                "$set": {"updated_at": datetime.now(timezone.utc).isoformat()},
                "$push": {
                    "interactions": {
                        "type": "voice_call",
                        "notes": lead_data.notes,
                        "product_mentioned": lead_data.product_interest,
                        "timestamp": datetime.now(timezone.utc).isoformat()
                    }
                }
            }
        )
        return {
            "success": True,
            "lead_id": existing_lead["id"],
            "is_new": False,
            "message": f"Updated existing lead for {clean_phone}"
        }
    
    now = datetime.now(timezone.utc)
    lead_id = str(uuid.uuid4())
    
    lead_doc = {
        "id": lead_id,
        "phone": clean_phone,
        "name": lead_data.name or f"Lead-{clean_phone[-4:]}",
        "email": lead_data.email,
        "product_interest": lead_data.product_interest,
        "source": lead_data.source or "voice_agent",
        "status": "new",
        "notes": lead_data.notes,
        "assigned_to": None,
        "assigned_to_name": None,
        "follow_up_date": None,
        "interactions": [{
            "type": "voice_call",
            "notes": lead_data.notes,
            "product_mentioned": lead_data.product_interest,
            "timestamp": now.isoformat()
        }] if lead_data.notes or lead_data.product_interest else [],
        "created_by": "omnidim_agent",
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
        "converted_at": None
    }
    
    await db.leads.insert_one(lead_doc)
    
    # Create notification for sales team
    await create_notification(
        title="New Sales Lead",
        message=f"New lead from voice call: {lead_data.name or clean_phone}" + (f" - Interested in {lead_data.product_interest}" if lead_data.product_interest else ""),
        notification_type="lead_created",
        target_roles=["admin", "call_support"],
        link=f"/leads"
    )
    
    logger.info(f"Omnidim lead created: {lead_id} for phone {clean_phone}")

    return {
        "success": True,
        "lead_id": lead_id,
        "is_new": True,
        "message": f"New lead created for {lead_data.name or clean_phone}"
    }


def _omni_find(obj, keys):
    """Find the first non-empty value for any of `keys` anywhere in a nested dict/list (case-insensitive)."""
    want = {k.lower() for k in keys}
    stack = [obj]
    while stack:
        cur = stack.pop()
        if isinstance(cur, dict):
            for k, v in cur.items():
                if str(k).lower() in want and v not in (None, "", [], {}):
                    return v
            stack.extend(v for v in cur.values() if isinstance(v, (dict, list)))
        elif isinstance(cur, list):
            stack.extend(cur)
    return None


def _omni_transcript_text(t) -> str:
    """Normalize a transcript that may be a string (Omnidim 'full_conversation'), or a list of turns
    in {user_query, bot_response} (Omnidim 'interactions') or {role/speaker, text/content} form."""
    if isinstance(t, str):
        return t
    if isinstance(t, list):
        out = []
        for turn in t:
            if isinstance(turn, dict):
                if "user_query" in turn or "bot_response" in turn:  # Omnidim 'interactions'
                    uq, br = turn.get("user_query"), turn.get("bot_response")
                    if uq and uq is not False:
                        out.append(f"User: {uq}")
                    if br:
                        out.append(f"Bot: {br}")
                    continue
                who = turn.get("role") or turn.get("speaker") or turn.get("from") or ""
                msg = turn.get("text") or turn.get("content") or turn.get("message") or ""
                out.append(f"{who}: {msg}".strip(": ").strip())
            elif isinstance(turn, str):
                out.append(turn)
        return "\n".join(x for x in out if x)
    return ""


async def _omni_maybe_queue_outreach(digits, name, product, issue, urgency, sentiment, ticket_number):
    """From a post-call: if the customer raised a real issue, queue a REVIEW-GATED WhatsApp follow-up
    (deduped by phone). High-urgency / negative-sentiment calls also ping the founder. Returns id or None."""
    if not OMNIDIM_OUTREACH_ENABLED or len(digits or "") != 10 or not issue:
        return None
    if await db.whatsapp_optouts.find_one({"phone": digits}, {"_id": 1}):
        return None
    if await db.omnidim_outreach.find_one({"customer_phone": digits, "status": "pending_review"}, {"_id": 1}):
        return None  # already waiting for review
    cooldown = (datetime.now(timezone.utc) - timedelta(days=OMNIDIM_OUTREACH_COOLDOWN_DAYS)).isoformat()
    if await db.omnidim_outreach.find_one(
            {"customer_phone": digits, "status": "sent", "sent_at": {"$gte": cooldown}}, {"_id": 1}):
        return None  # contacted recently
    u, s = str(urgency or "").lower(), str(sentiment or "").lower()
    high = ("high" in u or "urgent" in u or "critical" in u or s in ("negative", "frustrated", "angry", "upset"))
    oid = str(uuid.uuid4())
    await db.omnidim_outreach.insert_one({
        "id": oid, "ticket_number": ticket_number, "customer_phone": digits, "customer_name": name or "",
        "product": product, "issue": (issue or "")[:300], "ticket_status": "from_call",
        "priority": "high" if high else "normal", "status": "pending_review", "source": "post_call",
        "created_at": datetime.now(timezone.utc).isoformat()})
    if high:
        await _wa_send_to_manager(
            f"\U0001f534 *Urgent call follow-up* — {name or digits} ({digits}) ne abhi call kiya: "
            f"{(issue or '')[:120]}{(' [' + str(urgency) + ']') if urgency else ''}. Reply *send omnidim* to text them.",
            fallback_desc=f"Urgent Omnidim call follow-up for {name or digits} ({digits}).")
    return oid


@api_router.post("/omnidim/post-call")
async def omnidim_post_call(request: Request):
    """Omnidim 'post-call delivery' webhook: receives the full call JSON after EVERY call.
    Auth via X-API-Key header OR ?token= / ?key= query (so it works even if Omnidim only lets you
    enter a URL). Stores the raw payload + best-effort extracted fields in db.omnidim_calls, and
    attaches the call summary/recording to the customer's most recent Omnidim ticket."""
    secret = (os.environ.get("OMNIDIM_WEBHOOK_SECRET", "") or os.environ.get("OMNIDIM_API_KEY", "")).strip()
    if secret:
        supplied = (request.headers.get("X-API-Key") or request.query_params.get("token")
                    or request.query_params.get("key") or request.query_params.get("secret") or "")
        if supplied != secret:
            raise HTTPException(status_code=401, detail="Invalid Omnidim webhook token")
    try:
        payload = await request.json()
    except Exception:
        payload = {"_raw_text": (await request.body()).decode("utf-8", "replace")[:20000]}

    # Customer number by call direction (outbound→to_number, inbound→from_number).
    direction = str(_omni_find(payload, ["call_direction", "direction"]) or "").lower()
    cust_num = (_omni_find(payload, ["to_number"]) if "out" in direction else _omni_find(payload, ["from_number"]))
    phone_raw = cust_num or _omni_find(payload, ["customer_phone", "phone_number", "phone", "caller",
                                                 "from_number", "to_number", "mobile", "callee"])
    digits = re.sub(r"\D", "", str(phone_raw or ""))[-10:]
    if len(digits) != 10:  # fallback: first India-style 10-digit number anywhere in the payload
        m = re.search(r"[6-9]\d{9}", json.dumps(payload, default=str))
        digits = m.group(0) if m else ""
    summary = _omni_find(payload, ["summary", "call_summary", "summary_text", "conversation_summary"])
    transcript = _omni_transcript_text(_omni_find(
        payload, ["full_conversation", "transcript", "conversation", "messages", "dialog", "interactions"]))
    outcome = _omni_find(payload, ["disposition", "outcome", "call_status", "result", "call_outcome"])
    sentiment = _omni_find(payload, ["sentiment", "customer_sentiment", "mood"])
    recording = _omni_find(payload, ["recording_url", "recording", "audio_url", "call_recording_url"])
    duration = _omni_find(payload, ["duration", "call_duration", "duration_seconds", "talk_time"])
    extracted = _omni_find(payload, ["extracted_variables", "variables", "extracted_data", "custom_data", "collected_data"])

    # Pull the structured fields Omnidim collected (ignore the demo "Test value for…" placeholders).
    ev = extracted if isinstance(extracted, dict) else {}

    def _ev(*names):
        for k, v in ev.items():
            if str(k).lower() in names and v and not str(v).lower().startswith("test value"):
                return v
        return None
    issue = _ev("technical_issue", "issue", "problem", "complaint")
    urgency = _ev("urgency_level", "urgency", "priority")
    product = _ev("product_interest", "product", "product_name", "model")
    cust_name = _ev("customer_name", "name", "caller_name")
    now = datetime.now(timezone.utc).isoformat()

    call_doc = {
        "id": str(uuid.uuid4()), "phone": digits, "summary": summary,
        "transcript": (transcript or "")[:20000], "outcome": outcome, "sentiment": sentiment,
        "recording_url": recording, "duration": duration, "extracted": extracted,
        "technical_issue": issue, "urgency": urgency, "product": product, "customer_name": cust_name,
        "direction": direction, "received_at": now, "source": "omnidim_post_call", "raw": payload,
    }
    await db.omnidim_calls.insert_one(call_doc)

    # Attach the call to the customer's most recent Omnidim ticket (context for staff + Kalpana).
    linked = None
    if digits:
        tk = await db.tickets.find_one(
            {"customer_phone": {"$regex": re.escape(digits) + "$"}}, sort=[("created_at", -1)])
        if tk:
            linked = tk.get("ticket_number")
            await db.tickets.update_one({"id": tk["id"]}, {"$set": {
                "last_call_summary": (summary or "")[:1000], "last_call_recording": recording,
                "last_call_at": now, "updated_at": now}})
            try:
                await add_ticket_history(tk["id"], f"Omnidim call: {(summary or outcome or 'call completed')[:160]}",
                                         REPAIR_LOOP_AGENT, {"action_type": "omnidim_call", "recording": recording})
            except Exception as e:
                logger.warning(f"omnidim call history attach failed: {e}")
    # If the caller raised a real issue, queue a review-gated WhatsApp follow-up (urgent ones ping the founder).
    queued = None
    try:
        queued = await _omni_maybe_queue_outreach(digits, cust_name, product, issue, urgency, sentiment, linked)
    except Exception as e:
        logger.warning(f"omnidim outreach queue from call failed: {e}")
    logger.info(f"Omnidim post-call stored: phone={digits or '?'} issue={bool(issue)} urgency={urgency} "
                f"linked_ticket={linked} queued_outreach={bool(queued)}")
    return {"success": True, "call_id": call_doc["id"], "phone": digits, "linked_ticket": linked,
            "issue": issue, "urgency": urgency, "queued_outreach": bool(queued)}


@api_router.get("/admin/omnidim-calls")
async def admin_omnidim_calls(limit: int = 100, skip: int = 0, phone: str = "", needs_help: bool = False,
                              current_user: dict = Depends(get_current_user)):
    """Admin call log of Omnidim voice-agent calls (newest first). List view omits raw payload + transcript."""
    require_roles(current_user, ["admin"])
    q = {}
    if phone:
        p = re.sub(r"\D", "", phone)[-10:]
        if p:
            q["phone"] = {"$regex": re.escape(p) + "$"}
    if needs_help:
        q["technical_issue"] = {"$nin": [None, ""]}
    total = await db.omnidim_calls.count_documents(q)
    lim = max(1, min(limit, 200))
    docs = await db.omnidim_calls.find(q, {"_id": 0, "raw": 0, "transcript": 0}).sort(
        "received_at", -1).skip(max(0, skip)).limit(lim).to_list(lim)
    by_sentiment = {d["_id"]: d["n"] async for d in db.omnidim_calls.aggregate(
        [{"$group": {"_id": "$sentiment", "n": {"$sum": 1}}}])}
    return {"total": total, "count": len(docs), "items": docs, "by_sentiment": by_sentiment}


@api_router.get("/admin/omnidim-calls/{call_id}")
async def admin_omnidim_call_detail(call_id: str, current_user: dict = Depends(get_current_user)):
    """Full detail for one call including the transcript (raw payload excluded)."""
    require_roles(current_user, ["admin"])
    d = await db.omnidim_calls.find_one({"id": call_id}, {"_id": 0, "raw": 0})
    if not d:
        raise HTTPException(status_code=404, detail="Call not found")
    return d


@api_router.get("/leads")
async def get_leads(
    status: Optional[str] = None,
    source: Optional[str] = None,
    assigned_to: Optional[str] = None,
    search: Optional[str] = None,
    skip: int = 0,
    limit: int = 50,
    user: dict = Depends(require_roles(["admin", "call_support"]))
):
    """Get all leads with filters - Admin and Call Support only"""
    query = {}
    
    if status:
        query["status"] = status
    if source:
        query["source"] = source
    if assigned_to:
        query["assigned_to"] = assigned_to
    if search:
        query["$or"] = [
            {"name": {"$regex": search, "$options": "i"}},
            {"phone": {"$regex": search, "$options": "i"}},
            {"email": {"$regex": search, "$options": "i"}},
            {"product_interest": {"$regex": search, "$options": "i"}}
        ]
    
    total = await db.leads.count_documents(query)
    leads = await db.leads.find(query, {"_id": 0}).sort("created_at", -1).skip(skip).limit(limit).to_list(limit)
    
    # Get stats
    stats = {
        "total": total,
        "new": await db.leads.count_documents({"status": "new"}),
        "contacted": await db.leads.count_documents({"status": "contacted"}),
        "qualified": await db.leads.count_documents({"status": "qualified"}),
        "converted": await db.leads.count_documents({"status": "converted"}),
        "lost": await db.leads.count_documents({"status": "lost"})
    }
    
    return {
        "leads": leads,
        "total": total,
        "stats": stats
    }


