class EmailAgentTest(BaseModel):
    sender: Optional[str] = "test@example.com"
    subject: Optional[str] = ""
    body: str


@api_router.post("/admin/email-agent/test-action")
async def email_agent_test_action(body: EmailAgentTest, execute: bool = False,
                                  user: dict = Depends(require_roles(["admin"]))):
    """Dry-run Pratibha's action routing on pasted text: what would she do, and
    which tier? With execute=true, a Tier-1 action is actually performed (admin)."""
    act = await email_agent.extract_action(body.subject or "", body.body or "")
    tier = _pratibha_tier(act["action"])
    labels = {0: "other → customer-reply flow", 1: "Tier 1 — Pratibha does it herself",
              2: "Tier 2 — founder approval, then she does it",
              3: "Tier 3 — founder approval, then a human does it"}
    out = {"action": act["action"], "params": act["params"], "tier": tier,
           "tier_label": labels[tier], "summary": _pratibha_action_summary(act["action"], act["params"])}
    if execute and tier == 1:
        ex = PRATIBHA_EXECUTORS.get(act["action"])
        ok, result = (await ex(act["params"], {"from_name": "Test", "subject": body.subject})) if ex else (False, "no executor")
        out.update({"executed": True, "ok": ok, "result": result})
    return {"success": True, "result": out}


@api_router.post("/admin/email-agent/test")
async def email_agent_test(body: EmailAgentTest, user: dict = Depends(require_roles(["admin"]))):
    """Dry-run Pratibha on pasted text — drafts the reply she would send, with NO
    mailbox and NO email actually going out. Lets you test/tune before going live."""
    ans = await email_agent.answer(body.sender or "customer@example.com",
                                   body.subject or "", body.body or "")
    return {
        "success": True,
        "category": email_agent.quick_category(body.subject or "", body.body or ""),
        "reply": ans["reply"], "model_ok": ans["model_ok"],
    }


class EmailAgentSend(BaseModel):
    body: str  # the (possibly edited) reply to send


@api_router.get("/admin/pratibha/pending-drafts")
async def pratibha_pending_drafts(user: dict = Depends(require_roles(["admin", "accountant"]))):
    """Customer-email replies Pratibha has drafted and is waiting for Shweta to approve on WhatsApp.
    A large backlog here is why ambiguous 'send' messages could fire random emails."""
    def _age_days(iso):
        try:
            return max(0, (datetime.now(timezone.utc) - datetime.fromisoformat((iso or "").replace("Z", "+00:00"))).days)
        except Exception:
            return None
    rows = []
    async for d in db.pratibha_wa_drafts.find(
            {"status": "awaiting_shweta"},
            {"_id": 0, "ref": 1, "customer_name": 1, "customer_email": 1, "subject": 1, "created_at": 1, "draft": 1}
            ).sort("created_at", -1):
        rows.append({"ref": d.get("ref"), "customer_name": d.get("customer_name"),
                     "customer_email": d.get("customer_email"), "subject": d.get("subject"),
                     "created_at": d.get("created_at"), "age_days": _age_days(d.get("created_at")),
                     "preview": (d.get("draft") or "")[:200]})
    return {"count": len(rows), "drafts": rows}


