@api_router.post("/admin/email-agent/messages/{msg_id}/send")
async def email_agent_send(msg_id: str, payload: EmailAgentSend,
                           user: dict = Depends(require_roles(["admin"]))):
    """Send the approved (edited) draft via the agent mailbox SMTP, mark replied."""
    m = await db.email_agent_inbox.find_one({"id": msg_id}, {"_id": 0})
    if not m:
        raise HTTPException(status_code=404, detail="Email not found")
    if not email_agent.is_configured():
        raise HTTPException(status_code=400, detail="Mailbox not configured — set EMAIL_AGENT_* in .env")
    if not (payload.body or "").strip():
        raise HTTPException(status_code=400, detail="Reply body is empty")
    subj = m.get("reply_subject") or m.get("subject") or ""
    if not subj.lower().startswith("re:"):
        subj = f"Re: {subj}"
    to_list = m.get("reply_to") or ([m.get("from_addr")] if m.get("from_addr") else [])
    cc_list = m.get("reply_cc") or []
    try:
        await email_agent.send_reply_all(to_list, cc_list, subj, payload.body.strip(),
                                         m.get("message_id") or "", m.get("references", ""))
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Send failed: {e}")
    now = datetime.now(timezone.utc).isoformat()
    await db.email_agent_inbox.update_one({"id": msg_id}, {"$set": {
        "status": "replied", "sent_reply": payload.body.strip(),
        "replied_by": user.get("id"),
        "replied_by_name": f"{user.get('first_name','')} {user.get('last_name','')}".strip() or user.get("email"),
        "replied_at": now, "updated_at": now}})
    # Learn from the human's edit: if they changed Pratibha's draft meaningfully, capture a lesson.
    asyncio.create_task(_pratibha_record_correction(m, m.get("draft_reply"), payload.body.strip(), user))
    return {"success": True, "status": "replied"}


@api_router.post("/admin/email-agent/messages/{msg_id}/dismiss")
async def email_agent_dismiss(msg_id: str, user: dict = Depends(require_roles(["admin"]))):
    r = await db.email_agent_inbox.update_one(
        {"id": msg_id}, {"$set": {"status": "dismissed", "updated_at": datetime.now(timezone.utc).isoformat()}})
    if not r.matched_count:
        raise HTTPException(status_code=404, detail="Email not found")
    return {"success": True, "status": "dismissed"}


@api_router.get("/amazon/processed-orders")
async def get_processed_amazon_orders(
    skip: int = 0,
    limit: int = 50,
    date_from: str = None,
    date_to: str = None,
    user: dict = Depends(require_roles(["admin"]))
):
    """Get list of processed Amazon orders with their files"""
    query = {}
    
    if date_from:
        query["processed_at"] = {"$gte": date_from}
    if date_to:
        if "processed_at" in query:
            query["processed_at"]["$lte"] = date_to
        else:
            query["processed_at"] = {"$lte": date_to}
    
    total = await db.amazon_order_processing.count_documents(query)
    orders = await db.amazon_order_processing.find(
        query, {"_id": 0}
    ).sort("processed_at", -1).skip(skip).limit(limit).to_list(limit)
    
    return {
        "orders": orders,
        "total": total
    }


# ==================== WHATSAPP AI AGENT ====================

# Global WhatsApp AI instance
_whatsapp_ai = None

# URL of the Node.js WhatsApp bridge (pm2 app crm-wa-bridge). Defaults to
# port 3011 because 3001 is occupied by the unrelated mg-shipper wa-bot.
WHATSAPP_BRIDGE_URL = os.environ.get("WHATSAPP_BRIDGE_URL", "http://127.0.0.1:3011")


async def get_whatsapp_ai():
    """Get the WhatsApp AI singleton"""
    global _whatsapp_ai
    if _whatsapp_ai is None:
        from whatsapp_agent import WhatsAppAIBrain
        _whatsapp_ai = WhatsAppAIBrain(db, send_whatsapp_message)
    return _whatsapp_ai


def _pratibha_wa_quiet_now() -> bool:
    """True when a PROACTIVE WhatsApp message should be HELD right now — i.e. it's outside India
    business hours (default Mon–Sat 10:00–20:00 IST). Times are evaluated in IST. Tunable via
    PRATIBHA_WA_QUIET_HOURS / PRATIBHA_WA_WORK_START_HOUR / _END_HOUR / PRATIBHA_WA_QUIET_SUNDAY."""
    if os.environ.get("PRATIBHA_WA_QUIET_HOURS", "true").lower() != "true":
        return False
    try:
        c = email_agent.cfg()
        now = email_agent._now_local(c)  # IST (Asia/Kolkata)
        start = int(os.environ.get("PRATIBHA_WA_WORK_START_HOUR", str(c.get("work_start_hour", 10))))
        end = int(os.environ.get("PRATIBHA_WA_WORK_END_HOUR", str(c.get("work_end_hour", 20))))
        sunday_quiet = os.environ.get("PRATIBHA_WA_QUIET_SUNDAY",
                                      "true" if c.get("quiet_sunday", True) else "false").lower() == "true"
        if sunday_quiet and now.weekday() == 6:  # Sunday
            return True
        return not (start <= now.hour < end)
    except Exception:
        return False


async def send_whatsapp_message(to: str, message: str, force: bool = False):
    """Send a WhatsApp message via the bridge.

    Pratibha's PROACTIVE messages are held outside India business hours (IST) and auto-flushed at
    the start of the next business day, so she doesn't ping the team at night / on Sunday. Pass
    force=True for transactional or interactive sends that must go regardless of the hour —
    customer-facing messages, admin manual sends, replies, and the morning flush itself."""
    if not force and _pratibha_wa_quiet_now():
        try:
            import hashlib
            now_iso = datetime.now(timezone.utc).isoformat()
            key = hashlib.sha1(f"{to}|{message}".encode("utf-8")).hexdigest()
            await db.pratibha_wa_outbox.update_one(
                {"dedup_key": key, "status": "queued"},
                {"$setOnInsert": {"queued_at": now_iso},
                 "$set": {"to": to, "message": message, "dedup_key": key,
                          "status": "queued", "updated_at": now_iso}},
                upsert=True)
            logger.info("WhatsApp proactive msg held (outside India business hours) — queued for next business day")
            return {"held": True, "queued": True}
        except Exception as e:
            logger.error(f"WA outbox queue failed, sending anyway: {e}")
    import httpx
    try:
        async with httpx.AsyncClient(timeout=30.0) as client:
            response = await client.post(
                f"{WHATSAPP_BRIDGE_URL}/send",
                json={"to": to, "message": message}
            )
            return response.json()
    except Exception as e:
        logger.error(f"WhatsApp send error: {e}")
        return {"error": str(e)}


async def scheduled_wa_outbox_flush():
    """Send any WhatsApp messages that were held overnight, once India business hours resume.
    No-op while still outside hours (e.g. Sunday) so the queue waits for the next business day."""
    try:
        if _pratibha_wa_quiet_now():
            return
        items = await db.pratibha_wa_outbox.find({"status": "queued"}, {"_id": 0}).sort("queued_at", 1).to_list(300)
        sent = 0
        for it in items:
            try:
                res = await send_whatsapp_message(it["to"], it["message"], force=True)
                if isinstance(res, dict) and res.get("error"):
                    continue  # bridge issue — leave queued, retry next run
                await db.pratibha_wa_outbox.update_one(
                    {"dedup_key": it["dedup_key"], "status": "queued"},
                    {"$set": {"status": "sent", "sent_at": datetime.now(timezone.utc).isoformat()}})
                sent += 1
                await asyncio.sleep(1.0)  # pace the morning catch-up
            except Exception as e:
                logger.error(f"WA outbox flush item failed: {e}")
        if sent:
            logger.info(f"WhatsApp outbox flush: delivered {sent} held message(s)")
    except Exception as e:
        logger.error(f"WA outbox flush failed: {e}")


async def send_whatsapp_media(to: str, caption: str, attachment: dict):
    """Send a WhatsApp message with a file (e.g. a label PDF) via the bridge. `attachment` is
    {filename, content(base64), media_type} as returned by _pratibha_fetch_label."""
    import httpx
    to = to if "@" in (to or "") else f"{re.sub(r'[^0-9]', '', to or '')}@c.us"
    try:
        async with httpx.AsyncClient(timeout=60.0) as client:
            response = await client.post(
                f"{WHATSAPP_BRIDGE_URL}/send",
                json={"to": to, "message": caption,
                      "media": {"mimetype": attachment.get("media_type", "application/pdf"),
                                "data": attachment.get("content"),
                                "filename": attachment.get("filename", "label.pdf")}})
            return response.json()
    except Exception as e:
        logger.error(f"WhatsApp media send error: {e}")
        return {"error": str(e)}


