    await _samrat_attach_authors(rows)
    for r in rows:
        r["like_count"] = len(r.get("liked_by") or [])
        r["liked"] = user["id"] in (r.get("liked_by") or [])
        r["comment_count"] = len(r.get("comments") or [])
    return {"posts": rows}


